def _fold_text(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", str(value or ""))
    ascii_only = "".join(char for char in normalized if not unicodedata.combining(char))
    sanitized = re.sub(r"[^\w\s]", " ", ascii_only.lower())
    return " ".join(sanitized.strip().split())


def _runtime_stage_timing_payload(**values: Any) -> dict[str, Any]:
    payload: dict[str, Any] = {"schema_version": "agvm.runtime_stage_timing.v1"}
    for key, value in values.items():
        if value is not None:
            payload[key] = value
    return payload


def _runtime_stage_phase_timings(stage_timing: dict[str, Any]) -> dict[str, Any]:
    return {
        key: round(float(value), 3)
        for key, value in dict(stage_timing or {}).items()
        if key.endswith("_ms") and isinstance(value, (int, float)) and not isinstance(value, bool)
    }


