def _looks_like_org_or_project_label(value: Any) -> bool:
    text = str(value or "").strip()
    folded = _fold_text(text)
    if not text or not folded:
        return False
    if any(marker in folded for marker in _GENERIC_ORG_LABEL_MARKERS):
        return True
    tokens = re.findall(r"\b[A-Za-z][A-Za-z0-9&.'-]{2,}\b", text)
    for token in tokens:
        letters = [char for char in token if char.isalpha()]
        if len(letters) >= 3 and all(char.isupper() for char in letters):
            return True
        if re.search(r"[a-z][A-Z]", token):
            return True
    return False


def _company_affiliation_signal_score(value: Any) -> float:
    text = _fold_text(value)
    if not text:
        return 0.0
    organization_markers = (
        "azienda",
        "aziende",
        "societa",
        "company",
        "companies",
        "organization",
        "organizations",
        "startup",
        "impresa",
        "business",
        "corporation",
        "group",
        "gruppo",
    )
    operating_relation_markers = (
        "fondat",
        "fondatore",
        "founder",
        "founded",
        "co founder",
        "cofondatore",
        "costituit",
        "established",
        "created",
        "ceo",
        "guidat",
        "led",
        "associate",
        "associated",
        "affiliated",
        "collegat",
        "linked",
        "related",
        "partner",
        "partnership",
        "alliance",
    )
    transaction_relation_markers = (
        "acquired",
        "acquiring",
        "acquisition",
        "acquisizione",
        "acquisit",
        "acquisisce",
        "transaction",
        "subsidiary",
        "controllat",
        "owned",
        "integrated",
        "integrata",
        "integrato",
        "portfolio",
    )
    project_shape = any(marker in text for marker in organization_markers)
    operating_relation = any(marker in text for marker in operating_relation_markers)
    transaction_relation = any(marker in text for marker in transaction_relation_markers)
    named_org_shape = bool(re.search(r"\b[A-Z][A-Za-z0-9&.'-]*(?:[A-Z][A-Za-z0-9&.'-]+|[A-Z]{2,})\b", str(value or "")))
    score = 0.0
    if project_shape:
        score += 0.28
    if operating_relation:
        score += 0.34
    if transaction_relation:
        score += 0.34
    if named_org_shape and (operating_relation or transaction_relation):
        score += 0.12
    if (operating_relation or transaction_relation) and any(marker in text for marker in ("person", "persona", "ceo", "founder", "fondatore")):
        score += 0.08
    return round(max(0.0, min(1.0, score)), 6)


def _memory_subject_label(query_text: str | None = None) -> str:
    try:
        nucleus = fetch_identity_nucleus()
    except Exception:
        nucleus = {}
    core_name = str((nucleus or {}).get("core_name") or "").strip()
    if core_name:
        return core_name
    for target in _query_named_targets(str(query_text or "")):
        if not _looks_like_org_or_project_label(target):
            return str(target).strip()
    return "la persona"


