def build_index(nodes: list[dict[str, Any]]) -> dict[str, Any]:
    spatial_index: dict[str, dict[str, Any]] = {}
    bucket_index: dict[str, list[str]] = defaultdict(list)
    highway_index: dict[str, set[str]] = defaultdict(set)
    document_index: set[str] = set()
    node_position_map: dict[str, dict[str, float]] = {}
    node_lookup = {str(node.get("id") or ""): node for node in nodes if str(node.get("id") or "")}
    for node in nodes:
        node_id = str(node["id"])
        spatial_index[node_id] = node_for_index(node)
        bucket_key = str((node.get("bucket") or {}).get("key") or position_to_bucket(node["final_position"])["key"])
        bucket_index[bucket_key].append(node_id)
        node_position_map[node_id] = dict(node["final_position"])
        if node.get("is_document_anchor") and is_document_eligible(node):
            document_index.add(node_id)
        for highway in node.get("highways") or []:
            target = str(highway["target_node_id"])
            target_node = node_lookup.get(target)
            if target_node is None or not is_answer_eligible(node) or not is_answer_eligible(target_node):
                continue
            highway_index[node_id].add(target)
            highway_index[target].add(node_id)
    return {
        "version": INDEX_VERSION,
        "bucket_size": BUCKET_SIZE,
        "spatial_index": spatial_index,
        "bucket_index": {key: sorted(value) for key, value in bucket_index.items()},
        "highway_index": {key: sorted(value) for key, value in highway_index.items()},
        "document_index": sorted(document_index),
        "node_position_map": node_position_map,
        "updated_at": utc_timestamp(),
    }


def ensure_index(graph: dict[str, Any]) -> dict[str, Any]:
    index_payload = load_index()
    node_ids = sorted(str(node["id"]) for node in graph.get("nodes", []))
    current_ids = sorted(str(key) for key in (index_payload.get("spatial_index") or {}).keys())
    required_node_keys = {
        "node_kind",
        "memory_type",
        "semantic_color",
        "bucket",
        "granularity",
        "novelty",
        "source_trust",
        "claim_status",
        "answer_eligible",
        "document_eligible",
    }
    has_complete_nodes = True
    for node in (index_payload.get("spatial_index") or {}).values():
        if not required_node_keys.issubset(set(dict(node).keys())):
            has_complete_nodes = False
            break
    if current_ids == node_ids and has_complete_nodes:
        return index_payload
    rebuilt = build_index(graph.get("nodes", []))
    return save_index(rebuilt)


def build_atlas(graph: dict[str, Any], index_payload: dict[str, Any]) -> dict[str, Any]:
    buckets: list[dict[str, Any]] = []
    spatial_index = dict(index_payload.get("spatial_index") or {})
    for bucket_key, node_ids in sorted(dict(index_payload.get("bucket_index") or {}).items()):
        nodes = [spatial_index.get(node_id) for node_id in node_ids]
        nodes = [node for node in nodes if node]
        if not nodes:
            continue
        centroid = {
            "x": sum(float(node["final_position"]["x"]) for node in nodes) / len(nodes),
            "y": sum(float(node["final_position"]["y"]) for node in nodes) / len(nodes),
            "z": sum(float(node["final_position"]["z"]) for node in nodes) / len(nodes),
        }
        guide_histogram: dict[str, int] = defaultdict(int)
        gateways: dict[str, float] = defaultdict(float)
        for node in nodes:
            guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or "")
            if guide_area:
                guide_histogram[guide_area] += 1
            for highway in node.get("highways") or []:
                gateways[str(highway["target_node_id"])] += float(highway.get("strength") or 0.0)
        buckets.append(
            {
                "bucket_key": bucket_key,
                "centroid": centroid,
                "node_count": len(nodes),
                "document_anchor_count": sum(1 for node in nodes if node.get("is_document_anchor")),
                "guide_area_histogram": dict(guide_histogram),
                "outgoing_highway_gateways": [
                    {"target_node_id": target, "strength": round(min(1.0, weight), 4), "reason": "atlas_gateway"}
                    for target, weight in sorted(gateways.items(), key=lambda item: (-item[1], item[0]))[:6]
                ],
            }
        )
    return {
        "version": ATLAS_VERSION,
        "bucket_size": BUCKET_SIZE,
        "generated_at": utc_timestamp(),
        "node_count": len(graph.get("nodes", [])),
        "bucket_count": len(buckets),
        "buckets": buckets,
    }


def atlas_is_compatible(atlas_payload: dict[str, Any], graph: dict[str, Any], index_payload: dict[str, Any]) -> bool:
    if int(atlas_payload.get("node_count") or 0) != len(graph.get("nodes", [])):
        return False
    if int(atlas_payload.get("bucket_count") or 0) != len(index_payload.get("bucket_index") or {}):
        return False
    for bucket in list(atlas_payload.get("buckets") or []):
        for gateway in list(bucket.get("outgoing_highway_gateways") or []):
            try:
                if float(gateway.get("strength") or 0.0) > 1.0:
                    return False
            except (TypeError, ValueError):
                return False
    return True


def ensure_atlas(graph: dict[str, Any], index_payload: dict[str, Any]) -> dict[str, Any]:
    atlas_payload = load_atlas()
    if atlas_is_compatible(atlas_payload, graph, index_payload):
        return atlas_payload
    rebuilt = build_atlas(graph, index_payload)
    return save_atlas(rebuilt)


def shortlist_atlas_buckets(atlas_payload: dict[str, Any], position: dict[str, float]) -> list[dict[str, Any]]:
    ranked: list[tuple[float, str, dict[str, Any]]] = []
    for bucket in list(atlas_payload.get("buckets") or []):
        centroid = dict(bucket["centroid"])
        fit = 0.7 * max(0.0, 1.0 - min(1.0, distance(position, centroid) / 1.6)) + 0.3 * (
            float(bucket.get("node_count") or 0) / max(1.0, float(atlas_payload.get("node_count") or 1.0))
        )
        ranked.append((round(fit, 6), str(bucket["bucket_key"]), bucket))
    ranked.sort(key=lambda item: (-item[0], item[1]))
    return [{**bucket, "fit_score": fit} for fit, _, bucket in ranked[:6]]


def find_local_candidates(
    query_position: dict[str, float],
    query_brainhex: dict[str, int | str],
    index_payload: dict[str, Any],
    *,
    max_candidates: int = 32,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    spatial_index = dict(index_payload.get("spatial_index") or {})
    bucket_index = dict(index_payload.get("bucket_index") or {})
    highway_index = dict(index_payload.get("highway_index") or {})
    document_index = list(index_payload.get("document_index") or [])
    current_bucket = position_to_bucket(query_position)["key"]
    bx, by, bz = [int(value) for value in current_bucket.split(":")]
    candidate_sources: dict[str, list[str]] = defaultdict(list)
    ordered_ids: list[str] = []

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            for dz in (-1, 0, 1):
                neighbor = f"{bx + dx}:{by + dy}:{bz + dz}"
                for node_id in bucket_index.get(neighbor, []):
                    ordered_ids.append(node_id)
                    candidate_sources[node_id].append("bucket")

    document_anchor_candidate_ids: list[str] = []
    if len(ordered_ids) < 8:
        for node_id in document_index[:8]:
            ordered_ids.append(node_id)
            candidate_sources[node_id].append("document_anchor")
            document_anchor_candidate_ids.append(node_id)

    highway_expansion_ids: list[str] = []
    for node_id in list(dict.fromkeys(ordered_ids)):
        for neighbor in highway_index.get(node_id, []):
            ordered_ids.append(neighbor)
            candidate_sources[neighbor].append("highway_neighbor")
            highway_expansion_ids.append(neighbor)

    def brainhex_gap(node: dict[str, Any]) -> int:
        other = dict(node.get("routing_brainhex") or {})
        return (
            abs(int(query_brainhex["theta_bin"]) - int(other.get("theta_bin", 0)))
            + abs(int(query_brainhex["phi_bin"]) - int(other.get("phi_bin", 0)))
            + abs(int(query_brainhex["radius_bin"]) - int(other.get("radius_bin", 0)))
        )

    ranked: list[tuple[int, float, int, str, dict[str, Any]]] = []
    for node_id in dict.fromkeys(ordered_ids):
        node = spatial_index.get(node_id)
        if not node or not is_answer_eligible(node):
            continue
        source_rank = 0 if "bucket" in candidate_sources[node_id] else 1 if "document_anchor" in candidate_sources[node_id] else 2
        ranked.append((source_rank, distance(query_position, node["final_position"]), brainhex_gap(node), node_id, node))
    ranked.sort(key=lambda item: (item[0], item[1], item[2], item[3]))
    candidates = [item[4] for item in ranked[:max_candidates]]
    return candidates, {
        "candidate_ids": [candidate["id"] for candidate in candidates],
        "candidate_sources": {node_id: list(dict.fromkeys(candidate_sources[node_id])) for node_id in candidate_sources},
        "bucket_key": current_bucket,
        "document_anchor_candidate_ids": list(dict.fromkeys(document_anchor_candidate_ids)),
        "highway_expansion_ids": list(dict.fromkeys(highway_expansion_ids)),
    }


def estimate_links_and_highways(
    summary: str,
    scores: dict[str, float],
    memory_type: str,
    candidate_nodes: list[dict[str, Any]],
) -> dict[str, Any]:
    ranked: list[tuple[float, dict[str, Any], float, float]] = []
    for candidate in candidate_nodes:
        if not is_answer_eligible(candidate):
            continue
        semantic = semantic_similarity(scores, dict(candidate.get("routing_semantic_scores") or {}), ROUTING_FIELDS)
        lexical = lexical_overlap(summary, str(candidate.get("summary") or candidate.get("raw_text") or ""))
        combined = 0.72 * semantic + 0.28 * lexical
        ranked.append((combined, candidate, semantic, lexical))
    ranked.sort(key=lambda item: (-item[0], item[1]["id"]))

    links: list[dict[str, Any]] = []
    highways: list[dict[str, Any]] = []
    for combined, candidate, semantic, lexical in ranked:
        target = str(candidate["id"])
        reason = f"semantic={semantic:.2f}; lexical={lexical:.2f}"
        if combined >= 0.88:
            highways.append(
                {
                    "target_node_id": target,
                    "strength": round(combined, 4),
                    "reason": reason,
                    "kind": f"{memory_type}_bridge",
                    "stability": round(semantic, 4),
                }
            )
        elif combined >= 0.62:
            links.append({"target_node_id": target, "strength": round(combined, 4), "reason": reason})
    return {
        "links": links[:8],
        "highways": highways[:6],
        "origin_node_id": links[0]["target_node_id"] if links else None,
    }


def compute_final_position(
    base_position: dict[str, float],
    candidate_nodes: list[dict[str, Any]],
    links: list[dict[str, Any]],
    local_correction_plan: dict[str, Any] | None = None,
) -> dict[str, float]:
    if not candidate_nodes:
        return dict(base_position)
    correction = dict(local_correction_plan or {})
    candidate_by_id = {str(candidate["id"]): candidate for candidate in candidate_nodes}
    linked_targets = {str(link["target_node_id"]) for link in links}
    linked_positions = [dict(candidate["final_position"]) for candidate in candidate_nodes if str(candidate["id"]) in linked_targets]
    anchors = set(str(node_id) for node_id in correction.get("anchor_node_ids") or [])
    repels = set(str(node_id) for node_id in correction.get("repel_node_ids") or [])
    anchor_positions = [dict(candidate["final_position"]) for candidate in candidate_nodes if str(candidate["id"]) in anchors]
    repel_positions = [dict(candidate["final_position"]) for candidate in candidate_nodes if str(candidate["id"]) in repels]
    attraction_targets = [
        {
            "position": dict(candidate_by_id[str(item.get("node_id"))]["final_position"]),
            "weight": max(0.0, min(1.0, float(item.get("weight") or 0.0))),
        }
        for item in list(correction.get("attraction_targets") or [])
        if str(item.get("node_id") or "") in candidate_by_id
    ]
    repulsion_targets = [
        {
            "position": dict(candidate_by_id[str(item.get("node_id"))]["final_position"]),
            "weight": max(0.0, min(1.0, float(item.get("weight") or 0.0))),
        }
        for item in list(correction.get("repulsion_targets") or [])
        if str(item.get("node_id") or "") in candidate_by_id
    ]

    centroid = None
    if linked_positions:
        centroid = {
            "x": sum(position["x"] for position in linked_positions) / len(linked_positions),
            "y": sum(position["y"] for position in linked_positions) / len(linked_positions),
            "z": sum(position["z"] for position in linked_positions) / len(linked_positions),
        }
    elif anchor_positions:
        centroid = {
            "x": sum(position["x"] for position in anchor_positions) / len(anchor_positions),
            "y": sum(position["y"] for position in anchor_positions) / len(anchor_positions),
            "z": sum(position["z"] for position in anchor_positions) / len(anchor_positions),
        }
    if centroid is None:
        centroid = dict(base_position)

    cluster_pull = max(0.0, min(1.0, float(correction.get("cluster_pull_strength") or 0.18)))
    fx = (1.0 - cluster_pull) * float(base_position["x"]) + cluster_pull * centroid["x"]
    fy = (1.0 - cluster_pull) * float(base_position["y"]) + cluster_pull * centroid["y"]
    fz = (1.0 - cluster_pull) * float(base_position["z"]) + cluster_pull * centroid["z"]

    for target in attraction_targets:
        fx += 0.12 * target["weight"] * (target["position"]["x"] - fx)
        fy += 0.12 * target["weight"] * (target["position"]["y"] - fy)
        fz += 0.12 * target["weight"] * (target["position"]["z"] - fz)

    if repel_positions:
        repel_centroid = {
            "x": sum(position["x"] for position in repel_positions) / len(repel_positions),
            "y": sum(position["y"] for position in repel_positions) / len(repel_positions),
            "z": sum(position["z"] for position in repel_positions) / len(repel_positions),
        }
        fx += 0.10 * (fx - repel_centroid["x"])
        fy += 0.10 * (fy - repel_centroid["y"])
        fz += 0.10 * (fz - repel_centroid["z"])

    for target in repulsion_targets:
        fx += 0.12 * target["weight"] * (fx - target["position"]["x"])
        fy += 0.12 * target["weight"] * (fy - target["position"]["y"])
        fz += 0.12 * target["weight"] * (fz - target["position"]["z"])

    facet_bias = dict(correction.get("facet_bias") or {})
    fx += 0.06 * float(facet_bias.get("x") or 0.0)
    fy += 0.06 * float(facet_bias.get("y") or 0.0)
    fz += 0.06 * float(facet_bias.get("z") or 0.0)

    radial_policy = dict(correction.get("radial_policy") or {})
    target_band = str(radial_policy.get("target_band") or "")
    if target_band:
        target_norm = {"core": 0.16, "inner": 0.34, "mid": 0.56, "outer": 0.82}.get(target_band)
        if target_norm is not None:
            current_norm = distance({"x": fx, "y": fy, "z": fz}, {"x": 0.0, "y": 0.0, "z": 0.0})
            if current_norm > 1e-9:
                desired_norm = target_norm + 0.08 * max(0.0, min(1.0, float(radial_policy.get("band_bias") or 0.5)))
                scale = desired_norm / current_norm
                radial_adjustment = max(0.0, min(1.0, float(correction.get("mobility") or 0.25)))
                fx = (1.0 - 0.35 * radial_adjustment) * fx + 0.35 * radial_adjustment * fx * scale
                fy = (1.0 - 0.35 * radial_adjustment) * fy + 0.35 * radial_adjustment * fy * scale
                fz = (1.0 - 0.35 * radial_adjustment) * fz + 0.35 * radial_adjustment * fz * scale

    dx = fx - float(base_position["x"])
    dy = fy - float(base_position["y"])
    dz = fz - float(base_position["z"])
    raw_shift = distance({"x": fx, "y": fy, "z": fz}, base_position)
    max_shift = float(correction.get("max_shift") or 0.12)
    mobility = float(correction.get("mobility") or 0.25)
    allowed_shift = max_shift * max(0.05, min(1.0, mobility))
    if raw_shift > allowed_shift and raw_shift > 1e-12:
        scale = allowed_shift / raw_shift
        fx = float(base_position["x"]) + dx * scale
        fy = float(base_position["y"]) + dy * scale
        fz = float(base_position["z"]) + dz * scale
    return {"x": fx, "y": fy, "z": fz}


def apply_local_separation(
    seed: dict[str, Any],
    final_position: dict[str, float],
    candidate_nodes: list[dict[str, Any]],
) -> dict[str, float]:
    minimum_gap = float((seed.get("local_correction_plan") or {}).get("minimum_separation") or 0.028)
    close_nodes = []
    for candidate in candidate_nodes:
        fit = distance(final_position, dict(candidate["final_position"]))
        if fit < minimum_gap:
            close_nodes.append((fit, dict(candidate["final_position"])))
    if not close_nodes:
        return final_position

    key = f"{seed.get('raw_text') or seed.get('summary') or ''}|{seed.get('derivation_role') or ''}|{seed.get('memory_type') or ''}"
    digest = hashlib.sha256(key.encode("utf-8")).digest()
    sx = (digest[0] / 255.0) * 2.0 - 1.0
    sy = (digest[1] / 255.0) * 2.0 - 1.0
    sz = (digest[2] / 255.0) * 2.0 - 1.0

    rx = 0.0
    ry = 0.0
    rz = 0.0
    for fit, position in close_nodes:
        weight = max(0.0, minimum_gap - fit) / max(minimum_gap, 1e-6)
        rx += (final_position["x"] - position["x"]) * (0.55 + weight)
        ry += (final_position["y"] - position["y"]) * (0.55 + weight)
        rz += (final_position["z"] - position["z"]) * (0.55 + weight)

    rx += 0.35 * sx
    ry += 0.35 * sy
    rz += 0.35 * sz
    norm = max((rx * rx + ry * ry + rz * rz) ** 0.5, 1e-9)
    offset = min(minimum_gap * 0.9, 0.045)
    return {
        "x": float(final_position["x"]) + offset * (rx / norm),
        "y": float(final_position["y"]) + offset * (ry / norm),
        "z": float(final_position["z"]) + offset * (rz / norm),
    }


def finalize_node(seed: dict[str, Any], graph: dict[str, Any], index_payload: dict[str, Any], *, fixed_id: str | None = None) -> dict[str, Any]:
    candidates, debug = find_local_candidates(seed["base_position"], seed["routing_brainhex"], index_payload, max_candidates=24)
    seed_can_route = is_answer_eligible(seed)
    link_estimate = (
        estimate_links_and_highways(seed["summary"], seed["routing_semantic_scores"], seed["memory_type"], candidates)
        if seed_can_route
        else {"links": [], "highways": [], "origin_node_id": None}
    )
    suggested_links = list(seed.get("suggested_links") or [])
    suggested_highways = list(seed.get("suggested_highways") or [])
    merged_links = {str(link["target_node_id"]): dict(link) for link in link_estimate["links"]}
    if seed_can_route:
        for link in suggested_links:
            target = str(link.get("target_node_id") or "")
            if not target:
                continue
            merged_links[target] = {
                "target_node_id": target,
                "strength": round(min(1.0, float(link.get("strength") or 0.6)), 4),
                "reason": str(link.get("reason") or "llm_link"),
                "kind": link.get("kind"),
                "stability": link.get("stability"),
            }
    merged_highways = {str(link["target_node_id"]): dict(link) for link in link_estimate["highways"]}
    if seed_can_route:
        for link in suggested_highways:
            target = str(link.get("target_node_id") or "")
            if not target:
                continue
            merged_highways[target] = {
                "target_node_id": target,
                "strength": round(min(1.0, float(link.get("strength") or 0.75)), 4),
                "reason": str(link.get("reason") or "llm_highway"),
                "kind": link.get("kind"),
                "stability": link.get("stability"),
            }
    final_links = list(merged_links.values())[:8]
    final_highways = list(merged_highways.values())[:6]
    final_position = compute_final_position(seed["base_position"], candidates, final_links, dict(seed.get("local_correction_plan") or {}))
    final_position = apply_local_separation(seed, final_position, candidates)
    topology_brainhex = position_to_topology_brainhex(final_position)
    topology_color = color_from_brainhex(topology_brainhex)
    bucket = position_to_bucket(final_position)
    return {
        **seed,
        "id": fixed_id or f"vec_node_{uuid.uuid4().hex[:12]}",
        "final_position": final_position,
        "topology_brainhex": topology_brainhex,
        "topology_color": topology_color,
        "bucket": bucket,
        "links": final_links,
        "highways": final_highways,
        "debug": {**debug, "suggested_origin_node_id": link_estimate["origin_node_id"]},
    }


def _planner_seed_timeout_seconds(retrieval_mode: str | None, query_text: str | None = None) -> float:
    normalized = str(retrieval_mode or "balanced").strip().lower()
    query_class = _query_class(query_text or "")
    if query_class == "broad_summary":
        return {
            "flash": 3.2,
            "balanced": 7.5,
            "heavy": 9.5,
            "forensic": 10.5,
        }.get(normalized, 7.5)
    if query_class in {"style_values", "broad_summary"} and normalized in {"balanced", "heavy"}:
        normalized = "forensic"
    elif query_class == "style_values" and normalized == "balanced":
        normalized = "heavy"
    return {
        "flash": 2.4,
        "balanced": 3.8,
        "heavy": 5.2,
        "forensic": 6.2,
    }.get(normalized, 3.8)


def _planner_seed_retry_timeout_seconds(retrieval_mode: str | None, query_text: str | None = None) -> float:
    normalized = str(retrieval_mode or "balanced").strip().lower()
    query_class = _query_class(query_text or "")
    if query_class == "broad_summary":
        return {
            "balanced": 4.0,
            "heavy": 8.5,
            "forensic": 10.5,
        }.get(normalized, 0.0)
    if query_class in {"style_values", "broad_summary"} and normalized in {"balanced", "heavy"}:
        normalized = "forensic"
    elif query_class == "style_values" and normalized == "balanced":
        normalized = "heavy"
    return {
        "balanced": 4.4,
        "heavy": 5.4,
        "forensic": 6.4,
    }.get(normalized, 0.0)


def _planner_seed_transport_guard_seconds() -> float:
    return 0.8


def _planner_seed_max_items(query_text: str, max_probe_count: int, max_total_branches: int | None = None) -> int:
    query_class = _query_class(query_text)
    query_contract = build_query_contract(query_text)
    required_slot_count = len(
        {
            _canonical_required_slot(str(slot))
            for slot in [
                *list(query_contract.get("required_slots") or []),
                *list(query_contract.get("required_semantic_slots") or []),
            ]
            if str(slot or "").strip()
        }
    )
    requested_aspect_count = len(
        {
            str(aspect or "").strip().lower()
            for aspect in list(query_contract.get("requested_aspects") or [])
            if str(aspect or "").strip()
        }
    )
    multi_slot_min = min(4, max(required_slot_count, requested_aspect_count))
    class_cap = 3
    if _query_is_entity_connection_path_request(query_text):
        class_cap = max(3, int(query_contract.get("min_landing_count") or 3))
    elif query_class == "direct_fact":
        class_cap = 3 if _is_temporal_reference_query(query_text) else 1
    elif query_class == "document_lookup":
        class_cap = 3 if _is_temporal_reference_query(query_text) else 2
    elif query_class in {"relation_fact", "style_values"}:
        class_cap = 2
    elif query_class == "broad_summary":
        class_cap = 6
    if str(query_contract.get("query_kind") or "") == "exact_relation_fact":
        class_cap = 1
    elif bool(query_contract.get("requires_expansion")):
        class_cap = max(class_cap, int(query_contract.get("min_landing_count") or 1))
    if multi_slot_min > 1 and str(query_contract.get("query_kind") or "") != "exact_relation_fact":
        class_cap = max(class_cap, multi_slot_min)
    hard_limit = max(1, int(max_probe_count))
    if multi_slot_min > 1:
        hard_limit = max(hard_limit, multi_slot_min)
    if max_total_branches is not None:
        hard_limit = min(hard_limit, max(1, int(max_total_branches)))
    return max(1, min(hard_limit, class_cap))


def _planner_seed_source_from_error(error: str | None) -> str:
    normalized = str(error or "").strip().lower()
    if not normalized:
        return "provider_error"
    if "disabled" in normalized or "missing_api_key" in normalized:
        return "disabled"
    if "timeout" in normalized or "timed out" in normalized:
        return "timeout"
    if "parse" in normalized or "schema" in normalized or "json" in normalized:
        return "parse_error"
    return "provider_error"


def _compact_retrieval_seed_metamemory() -> str:
    compact = _truncate_prompt_text(build_metamemory_package("retrieval"), 420)
    return (
        "AGVM retrieval policy: emit compact answer strands only. "
        "No path geometry, no prose answer, no long rationale. "
        "Backend executes routes.\n"
        f"{compact}"
    )


def _minimal_retrieval_seed_taxonomy() -> str:
    return (
        "Minimal AGVM field taxonomy for the fast seed retry.\n"
        "Allowed goals: name, birthplace, residence, role, projects, family, father, partner, mentor, sibling, style, values, history, documents.\n"
        "Allowed answer fields: identity, identity_and_place, role_and_projects, relationships, communication_style, values, history, document_sources.\n"
        "Each strand must include a landing_hint. Destination queues are omitted in this retry; the backend compiles them. "
        "Do not emit path geometry or broad narrative."
    )


def _planner_seed_slot_guidance(query_text: str, *, max_items: int) -> str:
    query_class = _query_class(query_text)
    required_slots = [slot for slot in _required_slots_for_query(query_text) if slot]
    guidance_lines = [
        f"Query class: {query_class}.",
        f"Max strands allowed: {max_items}.",
        f"Required slots in priority order: {', '.join(required_slots) if required_slots else 'identity'}.",
    ]
    if query_class == "broad_summary":
        guidance_lines.extend(
            [
                "For broad summary, maximize slot coverage before duplicating the same slot.",
                "Prefer one strand per slot before emitting both role and projects.",
                "If capacity is tight, preserve identity, place, work, history, style, values, and relationships as far as max strands allows.",
            ]
        )
    elif _query_is_entity_connection_path_request(query_text):
        guidance_lines.extend(
            [
                "For entity connection/path requests, emit multiple work/company strands that cover the named organizations and the requested corridor/path evidence.",
                "Do not collapse the request into a single identity strand.",
                "Prefer one strand for the organization cluster, one for temporal/acquisition links if present, and one for document/source anchors if capacity allows.",
            ]
        )
    elif query_class == "document_lookup":
        guidance_lines.extend(
            [
                "For document lookup, keep the seed focused on document sources first.",
                "Do not waste strands on generic biography unless the query explicitly asks for it.",
            ]
        )
    elif query_class == "direct_fact":
        guidance_lines.append("For direct fact, prefer exactly one strand unless the query explicitly asks for multiple facts.")
    return "\n".join(guidance_lines)


def _planner_seed_identity_context(identity_source: dict[str, Any]) -> dict[str, Any]:
    identity_context = build_identity_context(identity_source)
    return {
        "core_name": identity_context.get("core_name"),
        "self_name_candidates": list(identity_context.get("self_name_candidates") or [])[:2],
        "partner_candidates": list(identity_context.get("partner_candidates") or [])[:2],
        "mentor_candidates": list(identity_context.get("mentor_candidates") or [])[:2],
        "sibling_candidates": list(identity_context.get("sibling_candidates") or [])[:2],
        "role_candidates": list(identity_context.get("role_candidates") or [])[:3],
        "project_candidates": list(identity_context.get("project_candidates") or [])[:3],
        "employer_candidates": list(identity_context.get("employer_candidates") or [])[:3],
        "core_nodes": [
            {
                "node_id": str(node.get("node_id") or ""),
                "summary": _truncate_prompt_text(node.get("summary") or "", 80),
                "memory_type": str(node.get("memory_type") or ""),
            }
            for node in list(identity_context.get("core_nodes") or [])[:2]
        ],
    }


def _strand_default_region(goal: str) -> tuple[str | None, str | None, str]:
    defaults = list(_semantic_destination_templates_for_goal(goal) or [])
    primary = dict(defaults[0] if defaults else {})
    return (
        str(primary.get("guide_area") or _guide_area_for_goal(goal) or "").strip() or None,
        str(primary.get("memory_type") or "").strip() or None,
        str(primary.get("radial_expectation") or "mid").strip() or "mid",
    )


def _heuristic_answer_strand(
    *,
    strand_id: str,
    query_text: str,
    goal: str,
    landing_hint: str,
    priority: float,
    planner_family: str = "heuristic",
    answer_hypothesis: str | None = None,
    expected_guide_area: str | None = None,
    expected_memory_type: str | None = None,
    radial_expectation: str | None = None,
    inverse_rationale: str | None = None,
    destination_queue: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    guide_area_default, memory_type_default, radial_default = _strand_default_region(goal)
    normalized_goal = _canonical_goal_from_context(
        goal,
        root_query_text=query_text,
        probe_query_text=landing_hint,
        expected_guide_area=expected_guide_area or guide_area_default,
    )
    expected_guide_area_value = _guide_area_for_query_text(
        landing_hint,
        expected_guide_area or _guide_area_for_goal(normalized_goal) or guide_area_default,
    )
    radial_value = str(radial_expectation or radial_default or "mid").strip() or "mid"
    hypothesis = _truncate_prompt_text(
        answer_hypothesis
        or inverse_query_hint(landing_hint or query_text, intent_type=detect_query_intent(landing_hint or query_text)),
        220,
    )
    inverse_reason = _truncate_prompt_text(
        inverse_rationale
        or inverse_query_hint(landing_hint or query_text, intent_type=detect_query_intent(landing_hint or query_text)),
        220,
    )
    memory_type_value = _stabilize_expected_memory_type(
        landing_hint or query_text,
        hypothesis,
        expected_memory_type or memory_type_default,
        expected_guide_area_value,
        {},
    )
    normalized_destinations = _normalize_destination_queue(
        spec_destinations=list(destination_queue or []),
        goal=normalized_goal,
        probe_label=strand_id,
        fallback_guide_area=expected_guide_area_value,
        fallback_memory_type=memory_type_value,
        fallback_radial_expectation=radial_value,
        fallback_color_hex=None,
    )
    return {
        "strand_id": strand_id,
        "answer_field": str(_expected_answer_field_for_goal(normalized_goal) or _goal_to_slot(normalized_goal)).strip(),
        "answer_hypothesis": hypothesis,
        "goal": normalized_goal,
        "landing_hint": _truncate_prompt_text(landing_hint or query_text, 180),
        "destination_queue": normalized_destinations,
        "priority": round(max(0.0, min(1.0, float(priority))), 4),
        "planner_family": "ai" if str(planner_family or "").strip().lower() == "ai" else "heuristic",
        "seed_confidence": round(max(0.0, min(1.0, float(priority))), 4),
        "inverse_rationale": inverse_reason,
        "expected_guide_area": expected_guide_area_value,
        "expected_memory_type": memory_type_value,
        "radial_expectation": radial_value,
    }


def heuristic_answer_strands(query_text: str, max_probe_count: int) -> list[dict[str, Any]]:
    limit = max(1, int(max_probe_count))
    query_class = _query_class(query_text)
    contract = build_query_contract(query_text)
    query_kind = str(contract.get("query_kind") or "")
    aspect_templates = _aspect_landing_templates(query_text)
    strand_specs: list[tuple[str, str, float, str | None]] = []
    if query_class == "document_lookup":
        strand_specs = [
            ("documents", query_text.strip(), 0.72, "Media Signals"),
            ("projects", query_text.strip(), 0.58, "Projects"),
            ("history", query_text.strip(), 0.48, "History"),
        ]
    elif query_class == "broad_summary":
        subject_templates = _aspect_landing_templates(query_text)
        strand_specs = [
            ("name", subject_templates["name"][0], 0.96, "Identity"),
            ("history", subject_templates["history"][0], 0.92, "History"),
            ("residence", subject_templates["residence"][0], 0.88, "Identity"),
            ("role", subject_templates["role"][0], 0.84, "Projects"),
            ("projects", subject_templates["projects"][0], 0.8, "Projects"),
            ("style", subject_templates["style"][0], 0.76, "Expression"),
            ("father", subject_templates["father"][0], 0.74, "Relationships"),
            ("partner", subject_templates["partner"][0], 0.72, "Relationships"),
            ("values", subject_templates["values"][0], 0.68, "Values"),
        ]
    elif query_kind in {"company_founding_relation", "company_founding_timeline"}:
        strand_specs = [
            (
                "company_founding",
                "Quali societa, aziende o organizzazioni risultano fondate, guidate, associate, acquisite, controllate, integrate o collegate?",
                0.96,
                "Projects",
            ),
            ("history", "Quali anni o date sono collegati a fondazioni, acquisizioni, integrazioni o passaggi societari?", 0.82, "History"),
            (
                "documents",
                "Documenti e fonti su aziende, societa, organizzazioni, fondazioni, acquisizioni, controllate, integrazioni, partnership e affiliazioni.",
                0.7,
                "Media Signals",
            ),
        ]
        existing_goals = {goal for goal, _hint, _priority, _area in strand_specs}
        for aspect in detect_query_aspects(query_text):
            if len(strand_specs) >= limit:
                break
            if aspect in existing_goals or aspect not in CANONICAL_QUERY_GOALS:
                continue
            landing_hint, expected_area = aspect_templates.get(aspect, (query_text.strip(), _guide_area_for_goal(aspect)))
            strand_specs.append((aspect, landing_hint, max(0.52, 0.78 - (0.08 * len(strand_specs))), expected_area))
            existing_goals.add(aspect)
    elif query_kind == "work_narrative":
        strand_specs = [
            ("role", "Che lavoro fa la persona e quale ruolo emerge?", 0.96, "Projects"),
            ("projects", "Quali progetti, societa o attivita descrivono il lavoro?", 0.88, "Projects"),
            ("documents", query_text.strip(), 0.58, "Media Signals"),
        ]
    elif query_kind == "exact_relation_fact":
        relation_goals = [
            str(relation or "").strip()
            for relation in list(contract.get("requested_relations") or [])
            if str(relation or "").strip() in CANONICAL_QUERY_GOALS
        ]
        for index, goal in enumerate(relation_goals[:limit]):
            landing_hint, expected_area = aspect_templates.get(goal, (query_text.strip(), _guide_area_for_goal(goal)))
            strand_specs.append((goal, landing_hint, max(0.4, 0.96 - (index * 0.12)), expected_area))
    else:
        aspects = [aspect for aspect in detect_query_aspects(query_text) if aspect in CANONICAL_QUERY_GOALS]
        if _is_temporal_reference_query(query_text):
            for goal, landing_hint, priority, expected_area in [
                ("history", "Quali anni e date esplicite compaiono nella storia?", 0.96, "History"),
                ("history", "Quali milestone temporali emergono dai progetti?", 0.86, "Projects"),
                ("history", "Quali note o documenti citano periodi, timeline o date?", 0.76, "Media Signals"),
            ][:limit]:
                strand_specs.append((goal, landing_hint, priority, expected_area))
        elif aspects:
            base_priority = 0.96
            for index, aspect in enumerate(aspects[:limit]):
                landing_hint, expected_area = aspect_templates.get(aspect, (query_text.strip(), _guide_area_for_goal(aspect)))
                strand_specs.append((aspect, landing_hint, max(0.4, base_priority - (index * 0.12)), expected_area))
            contract = build_query_contract(query_text)
            if str(contract.get("query_kind") or "") == "narrative_relation":
                desired_count = min(limit, int(contract.get("min_landing_count") or len(strand_specs)))
                supplemental = [
                    ("history", aspect_templates["history"][0], 0.72, "History"),
                    ("documents", query_text.strip(), 0.56, "Media Signals"),
                ]
                existing = {(goal, hint) for goal, hint, _priority, _area in strand_specs}
                for item in supplemental:
                    if len(strand_specs) >= desired_count:
                        break
                    if (item[0], item[1]) in existing:
                        continue
                    strand_specs.append(item)
                    existing.add((item[0], item[1]))
        else:
            pieces = [part.strip(" ,;") for part in re.split(r"\s+(?:and|e)\s+|,|;|\+", query_text) if part.strip(" ,;")]
            if not pieces:
                pieces = [query_text.strip()]
            for index, piece in enumerate(pieces[:limit]):
                goal = _goal_for_query_text(piece or query_text, heuristic_projection(piece or query_text).get("expected_guide_area"))
                strand_specs.append((goal, piece or query_text.strip(), max(0.42, 0.92 - (index * 0.14)), _guide_area_for_goal(goal)))
    return [
        _heuristic_answer_strand(
            strand_id=f"strand_heuristic_{index}",
            query_text=query_text,
            goal=goal,
            landing_hint=landing_hint,
            priority=priority,
            planner_family="heuristic",
            expected_guide_area=expected_area,
        )
        for index, (goal, landing_hint, priority, expected_area) in enumerate(strand_specs[:limit], start=1)
    ][:limit]


def _normalize_answer_strands(
    strands: list[dict[str, Any]] | None,
    *,
    query_text: str,
    max_probe_count: int,
    planner_family: str,
) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for index, raw in enumerate(list(strands or [])[: max(1, int(max_probe_count))], start=1):
        if not isinstance(raw, dict):
            continue
        landing_hint = _truncate_prompt_text(
            raw.get("landing_hint") or raw.get("query_text") or raw.get("answer_field") or raw.get("goal") or query_text,
            180,
        )
        goal = _canonical_goal_from_context(
            str(raw.get("goal") or ""),
            root_query_text=query_text,
            probe_query_text=landing_hint,
            expected_guide_area=str(raw.get("expected_guide_area") or ""),
        )
        if not goal:
            goal = _goal_for_query_text(landing_hint or query_text, str(raw.get("expected_guide_area") or ""))
        if not goal:
            continue
        signature = (
            str(raw.get("answer_field") or _expected_answer_field_for_goal(goal) or "").strip().lower(),
            str(goal).strip().lower(),
            _fold_text(landing_hint),
        )
        if signature in seen:
            continue
        seen.add(signature)
        priority = round(max(0.0, min(1.0, float(raw.get("priority") or max(0.35, 1.0 - ((index - 1) * 0.14))))), 4)
        raw_family = _normalized_planner_family(str(raw.get("planner_family") or ""), fallback=planner_family)
        strand = _heuristic_answer_strand(
            strand_id=str(raw.get("strand_id") or f"strand_{planner_family}_{index}").strip() or f"strand_{planner_family}_{index}",
            query_text=query_text,
            goal=goal,
            landing_hint=landing_hint,
            priority=priority,
            planner_family=raw_family,
            answer_hypothesis=str(raw.get("answer_hypothesis") or "").strip() or None,
            expected_guide_area=str(raw.get("expected_guide_area") or "").strip() or None,
            expected_memory_type=str(raw.get("expected_memory_type") or "").strip() or None,
            radial_expectation=str(raw.get("radial_expectation") or "").strip() or None,
            inverse_rationale=str(raw.get("inverse_rationale") or "").strip() or None,
            destination_queue=_sanitize_seed_destination_queue(
                [dict(item) for item in list(raw.get("destination_queue") or []) if isinstance(item, dict)],
                goal=goal,
                query_text=query_text,
                planner_family=raw_family,
            ),
        )
        strand["answer_field"] = _canonical_answer_field(
            str(raw.get("answer_field") or strand.get("answer_field") or "").strip() or None,
            goal=goal,
        )
        strand["planner_family"] = raw_family
        strand["family_plan_id"] = str(raw.get("family_plan_id") or _family_plan_id_for_family(raw_family)).strip() or _family_plan_id_for_family(raw_family)
        strand["family_plan_confidence"] = round(
            max(
                0.0,
                min(1.0, float(raw.get("family_plan_confidence") or raw.get("seed_confidence") or raw.get("confidence") or priority)),
            ),
            4,
        )
        strand["seed_confidence"] = round(
            max(
                0.0,
                min(
                    1.0,
                    float(raw.get("seed_confidence") or raw.get("confidence") or raw.get("priority") or priority),
                ),
            ),
            4,
        )
        normalized.append(strand)
    return normalized[: max(1, int(max_probe_count))]


def _semantic_contract_memory_type_for_goal(goal: str) -> str | None:
    normalized = str(goal or "").strip().lower()
    if normalized in {"name", "birthplace", "residence"}:
        return "identity"
    if normalized in {"family", "father", "partner", "mentor", "sibling"}:
        return "relational"
    if normalized == "role":
        return "knowledge"
    if normalized in {"projects", "company_founding"}:
        return "project"
    if normalized == "style":
        return "identity_style"
    if normalized == "values":
        return "value"
    if normalized == "history":
        return "episodic"
    if normalized == "documents":
        return "document_anchor"
    return None


def _semantic_contract_subject_label(contract: dict[str, Any], query_text: str) -> str:
    identity_hints = dict(contract.get("identity_hints") or {})
    for key in ("core_name", "display_name", "name", "subject_name"):
        value = str(identity_hints.get(key) or "").strip()
        if value:
            return value
    return _memory_subject_label(query_text)


def _semantic_contract_goal_for_required_slot(slot: str, query_text: str) -> str | None:
    normalized = _canonical_required_slot(str(slot or "").strip().lower())
    aspects = [aspect for aspect in detect_query_aspects(query_text) if aspect in CANONICAL_QUERY_GOALS]
    if normalized == "identity":
        return "name"
    if normalized == "place":
        for candidate in ("residence", "birthplace"):
            if candidate in aspects:
                return candidate
        return "residence"
    if normalized == "work":
        for candidate in ("company_founding", "role", "projects"):
            if candidate in aspects:
                return candidate
        return "role"
    if normalized == "relationships":
        for candidate in ("family", "father", "partner", "mentor", "sibling"):
            if candidate in aspects:
                return candidate
        return "family"
    if normalized in {"style", "values", "history", "documents"}:
        return normalized
    return normalized if normalized in CANONICAL_QUERY_GOALS else None


def _semantic_contract_landing_hint_for_goal(goal: str, *, subject: str, query_text: str) -> tuple[str, str]:
    normalized = str(goal or "").strip().lower()
    templates = {
        "name": (f"Chi e {subject} e qual e la sua identita pubblica?", "Identity"),
        "birthplace": (f"Dove e nato {subject}?", "History"),
        "residence": (f"Dove vive o opera {subject}?", "Identity"),
        "family": (f"Quali fatti familiari pubblici sono supportati per {subject}?", "Relationships"),
        "father": (f"Quale relazione familiare o paterna riguarda {subject}?", "Relationships"),
        "partner": (f"Quale partner o relazione stabile riguarda {subject}?", "Relationships"),
        "mentor": (f"Quale mentore o relazione guida riguarda {subject}?", "Relationships"),
        "sibling": (f"Quali fratelli o sorelle riguardano {subject}?", "Relationships"),
        "role": (f"Che ruolo, lavoro o posizione pubblica ha {subject}?", "Projects"),
        "projects": (f"Quali progetti, attivita o iniziative descrivono il lavoro di {subject}?", "Projects"),
        "company_founding": (
            f"Quali aziende, societa o organizzazioni sono fondate, guidate, associate, acquisite, controllate, integrate o collegate a {subject}?",
            "Projects",
        ),
        "style": (f"Come comunica o si esprime {subject}?", "Expression"),
        "values": (f"Quali valori o principi guidano {subject}?", "Values"),
        "history": (f"Quali passaggi temporali o biografici sono rilevanti per {subject}?", "History"),
        "documents": (str(query_text or "").strip(), "Media Signals"),
    }
    return templates.get(normalized, (str(query_text or "").strip(), _guide_area_for_goal(normalized)))


def _append_required_semantic_slot_strands(
    raw_strands: list[dict[str, Any]],
    *,
    contract: dict[str, Any],
    query_text: str,
    max_count: int,
) -> None:
    if len(raw_strands) >= max_count:
        return
    required_slots = [
        _canonical_required_slot(str(slot).strip())
        for slot in list(_required_slots_for_query(query_text))
        if str(slot).strip()
    ]
    if not required_slots:
        return
    covered_slots = {
        _goal_to_slot(str(item.get("goal") or ""))
        for item in raw_strands
        if str(item.get("goal") or "").strip()
    }
    subject = _semantic_contract_subject_label(contract, query_text)
    for slot in required_slots:
        if len(raw_strands) >= max_count:
            break
        if slot in covered_slots:
            continue
        goal = _semantic_contract_goal_for_required_slot(slot, query_text)
        if not goal:
            continue
        landing_hint, guide_area = _semantic_contract_landing_hint_for_goal(
            goal,
            subject=subject,
            query_text=query_text,
        )
        raw_strands.append(
            {
                "strand_id": f"strand_semantic_contract_slot_{slot}_{len(raw_strands) + 1}",
                "goal": goal,
                "answer_field": _expected_answer_field_for_goal(goal),
                "landing_hint": landing_hint,
                "answer_hypothesis": landing_hint,
                "priority": round(max(0.52, 0.9 - (len(raw_strands) * 0.08)), 4),
                "planner_family": "ai",
                "family_plan_id": "semantic_contract_ai_slot_recovery",
                "family_plan_confidence": 0.88,
                "seed_confidence": 0.88,
                "expected_guide_area": guide_area,
                "expected_memory_type": _semantic_contract_memory_type_for_goal(goal),
                "radial_expectation": "inner" if slot in {"identity", "work", "relationships"} else "mid",
                "inverse_rationale": (
                    "Required answerability slot recovered from the AI semantic contract "
                    "before spatial planning."
                ),
            }
        )
        covered_slots.add(slot)


def _answer_strands_from_semantic_contract(
    semantic_contract: dict[str, Any] | None,
    *,
    query_text: str,
    max_probe_count: int,
) -> list[dict[str, Any]]:
    contract = dict(semantic_contract or {})
    if not contract:
        return []
    expected_evidence = [
        dict(item)
        for item in list(contract.get("expected_evidence") or [])
        if isinstance(item, dict)
    ]
    landing_hypotheses = [
        dict(item)
        for item in list((dict(contract.get("landing_plan") or {})).get("landing_hypotheses") or [])
        if isinstance(item, dict)
    ]
    landing_by_target: dict[str, dict[str, Any]] = {}
    for landing in landing_hypotheses:
        for target_id in list(landing.get("target_evidence_ids") or []):
            target_key = str(target_id or "").strip()
            if target_key and target_key not in landing_by_target:
                landing_by_target[target_key] = landing

    max_count = max(1, int(max_probe_count))
    raw_strands: list[dict[str, Any]] = []
    contract_intent = str((dict(contract.get("intent") or {})).get("primary") or "").strip().lower()
    total = max(1, min(max_count, len(expected_evidence) or len(landing_hypotheses) or 1))
    for index, target in enumerate(expected_evidence[:max_count], start=1):
        target_id = str(target.get("target_id") or "").strip()
        landing = landing_by_target.get(target_id, {})
        claim_shape = str(target.get("claim_shape") or landing.get("textual_probe") or "").strip()
        success_question = str(target.get("success_question") or "").strip()
        folded_target = _fold_text(target_id)
        folded_claim = _fold_text(claim_shape)
        target_looks_like_node_id = bool(re.match(r"^(?:vec_)?node[_a-f0-9-]+$", folded_target))
        generic_claim = folded_claim in {"identity", "summary", "profile", "person identity", "person identity summary"}
        landing_hint = (success_question if generic_claim else claim_shape) or success_question or query_text
        guide_area = _guide_area_for_goal(target_id) or _guide_area_for_goal(landing_hint)
        goal_seed = "" if target_looks_like_node_id or generic_claim else (target_id or claim_shape)
        goal = _canonical_goal_from_context(
            goal_seed,
            root_query_text=query_text,
            probe_query_text=" ".join(part for part in (claim_shape, success_question, landing_hint) if part),
            expected_guide_area=str(guide_area or ""),
        )
        if goal == "history" and generic_claim and contract_intent in {"identity", "broad_dossier"}:
            goal = "name"
        if not goal:
            continue
        priority = max(0.48, 1.0 - ((index - 1) * 0.09))
        raw_strands.append(
            {
                "strand_id": f"strand_semantic_contract_{index}",
                "goal": goal,
                "answer_field": _expected_answer_field_for_goal(goal),
                "landing_hint": landing_hint,
                "answer_hypothesis": landing_hint or inverse_query_hint(query_text),
                "priority": round(priority, 4),
                "planner_family": "ai",
                "family_plan_id": "semantic_contract_ai",
                "family_plan_confidence": 0.92,
                "seed_confidence": 0.92,
                "expected_guide_area": guide_area,
                "expected_memory_type": _semantic_contract_memory_type_for_goal(goal),
                "radial_expectation": "inner" if goal in {"name", "role", "father", "partner"} else "mid",
                "inverse_rationale": str(target.get("success_question") or "").strip() or None,
            }
        )

    if not raw_strands:
        for index, landing in enumerate(landing_hypotheses[:max_count], start=1):
            landing_hint = str(landing.get("textual_probe") or query_text).strip()
            guide_area = _guide_area_for_goal(landing_hint)
            goal = _canonical_goal_from_context(
                str(landing.get("landing_id") or ""),
                root_query_text=query_text,
                probe_query_text=landing_hint,
                expected_guide_area=str(guide_area or ""),
            )
            if not goal:
                continue
            raw_strands.append(
                {
                    "strand_id": f"strand_semantic_contract_landing_{index}",
                    "goal": goal,
                    "answer_field": _expected_answer_field_for_goal(goal),
                    "landing_hint": landing_hint,
                    "answer_hypothesis": landing_hint,
                    "priority": round(max(0.48, 1.0 - ((index - 1) * 0.1)), 4),
                    "planner_family": "ai",
                    "family_plan_id": "semantic_contract_ai",
                    "family_plan_confidence": 0.86,
                    "seed_confidence": 0.86,
                    "expected_guide_area": guide_area,
                    "expected_memory_type": _semantic_contract_memory_type_for_goal(goal),
                    "radial_expectation": "mid",
                    "inverse_rationale": str(landing.get("why_traverse") or "").strip() or None,
                }
            )

    _append_required_semantic_slot_strands(
        raw_strands,
        contract=contract,
        query_text=query_text,
        max_count=max_count,
    )

    normalized = _normalize_answer_strands(
        raw_strands,
        query_text=query_text,
        max_probe_count=max_count,
        planner_family="ai",
    )
    return _select_answer_strands_for_query(
        normalized,
        query_text=query_text,
        max_probe_count=max_count,
    )


def _supplement_answer_strands_for_query(
    answer_strands: list[dict[str, Any]] | None,
    *,
    query_text: str,
    max_probe_count: int,
) -> list[dict[str, Any]]:
    normalized_existing = [dict(item) for item in list(answer_strands or []) if isinstance(item, dict)]
    if not normalized_existing:
        return []
    hard_limit = max(1, int(max_probe_count))
    required_slots = [str(item).strip() for item in list(_required_slots_for_query(query_text)) if str(item).strip()]
    heuristic_backfill = _normalize_answer_strands(
        heuristic_answer_strands(query_text, hard_limit),
        query_text=query_text,
        max_probe_count=hard_limit,
        planner_family="heuristic",
    )
    merged: list[dict[str, Any]] = [dict(item) for item in normalized_existing[:hard_limit]]
    seen_signatures = {
        (
            str(item.get("answer_field") or "").strip().lower(),
            str(item.get("goal") or "").strip().lower(),
            _fold_text(str(item.get("landing_hint") or "")),
        )
        for item in merged
    }
    covered_slots = {
        _goal_to_slot(str(item.get("goal") or ""))
        for item in merged
        if str(item.get("goal") or "").strip()
    }
    covered_goals = {
        str(item.get("goal") or "").strip().lower()
        for item in merged
        if str(item.get("goal") or "").strip()
    }
    allow_duplicate_goals = _is_temporal_reference_query(query_text)

    def _try_add(candidate: dict[str, Any], *, require_missing_slot: bool) -> bool:
        nonlocal merged
        if len(merged) >= hard_limit:
            return False
        goal = str(candidate.get("goal") or "").strip().lower()
        if not goal:
            return False
        slot = _goal_to_slot(goal)
        if require_missing_slot and slot in covered_slots:
            return False
        signature = (
            str(candidate.get("answer_field") or "").strip().lower(),
            goal,
            _fold_text(str(candidate.get("landing_hint") or "")),
        )
        if signature in seen_signatures or (goal in covered_goals and not allow_duplicate_goals):
            return False
        merged.append(dict(candidate))
        seen_signatures.add(signature)
        covered_goals.add(goal)
        if slot:
            covered_slots.add(slot)
        return True

    for candidate in heuristic_backfill:
        slot = _goal_to_slot(str(candidate.get("goal") or ""))
        if required_slots and slot not in required_slots:
            continue
        added = _try_add(candidate, require_missing_slot=True)
        if added and len(merged) >= hard_limit:
            return merged[:hard_limit]

    for candidate in heuristic_backfill:
        slot = _goal_to_slot(str(candidate.get("goal") or ""))
        if required_slots and slot not in required_slots and not _is_broad_summary_query(query_text) and not _is_temporal_reference_query(query_text):
            continue
        if _is_company_goal_query(query_text) and slot not in {"work", "documents"}:
            continue
        _try_add(candidate, require_missing_slot=False)
        if len(merged) >= hard_limit:
            break

    if required_slots:
        heuristic_candidates_by_slot: dict[str, dict[str, Any]] = {}
        for candidate in heuristic_backfill:
            goal = str(candidate.get("goal") or "").strip().lower()
            slot = _goal_to_slot(goal)
            if slot and slot not in heuristic_candidates_by_slot:
                heuristic_candidates_by_slot[slot] = dict(candidate)

        def _refresh_slot_state() -> tuple[dict[str, int], list[str]]:
            slot_counts: dict[str, int] = defaultdict(int)
            for item in merged:
                slot_counts[_goal_to_slot(str(item.get("goal") or ""))] += 1
            missing = [slot for slot in required_slots if slot and slot_counts.get(slot, 0) <= 0]
            return slot_counts, missing

        slot_counts, missing_slots = _refresh_slot_state()
        while missing_slots:
            missing_slot = sorted(
                missing_slots,
                key=lambda slot: (_slot_priority_index(slot, query_text=query_text), slot),
            )[0]
            candidate = heuristic_candidates_by_slot.get(missing_slot)
            if not candidate:
                break
            if len(merged) < hard_limit and _try_add(candidate, require_missing_slot=True):
                slot_counts, missing_slots = _refresh_slot_state()
                continue
            replaceable_index: int | None = None
            replaceable_rank: tuple[int, int, float] | None = None
            for index, existing in enumerate(merged):
                existing_goal = str(existing.get("goal") or "").strip().lower()
                existing_slot = _goal_to_slot(existing_goal)
                if existing_slot == missing_slot:
                    continue
                duplicate_penalty = 0 if int(slot_counts.get(existing_slot, 0)) > 1 else 1
                priority_rank = _slot_priority_index(existing_slot, query_text=query_text)
                existing_priority = float(existing.get("priority") or 0.0)
                candidate_rank = (duplicate_penalty, -priority_rank, existing_priority)
                if replaceable_rank is None or candidate_rank < replaceable_rank:
                    replaceable_rank = candidate_rank
                    replaceable_index = index
            if replaceable_index is None:
                break
            merged[replaceable_index] = dict(candidate)
            seen_signatures = {
                (
                    str(item.get("answer_field") or "").strip().lower(),
                    str(item.get("goal") or "").strip().lower(),
                    _fold_text(str(item.get("landing_hint") or "")),
                )
                for item in merged
            }
            covered_goals = {
                str(item.get("goal") or "").strip().lower()
                for item in merged
                if str(item.get("goal") or "").strip()
            }
            covered_slots = {
                _goal_to_slot(str(item.get("goal") or ""))
                for item in merged
                if str(item.get("goal") or "").strip()
            }
            slot_counts, missing_slots = _refresh_slot_state()

    merged = _select_answer_strands_for_query(merged, query_text=query_text, max_probe_count=hard_limit)
    return merged[:hard_limit]


def _answer_strands_to_probe_specs(answer_strands: list[dict[str, Any]], *, root_query_text: str) -> list[dict[str, Any]]:
    strands = [dict(item) for item in list(answer_strands or []) if isinstance(item, dict)]
    total_priority = sum(max(0.0, float(item.get("priority") or 0.0)) for item in strands) or float(max(1, len(strands)))
    specs: list[dict[str, Any]] = []
    for strand in strands:
        goal = _canonical_goal_from_context(
            str(strand.get("goal") or ""),
            root_query_text=root_query_text,
            probe_query_text=str(strand.get("landing_hint") or root_query_text),
            expected_guide_area=str(strand.get("expected_guide_area") or ""),
        )
        if not goal:
            continue
        priority = round(max(0.0, min(1.0, float(strand.get("priority") or 0.0))), 4)
        specs.append(
            {
                "strand_id": str(strand.get("strand_id") or "").strip() or None,
                "query_text": str(strand.get("landing_hint") or root_query_text).strip() or root_query_text.strip(),
                "goal": goal,
                "answer_hypothesis": str(strand.get("answer_hypothesis") or "").strip() or inverse_query_hint(root_query_text),
                "weight": round(priority / total_priority, 6),
                "landing_basis": "answer_strand_bootstrap",
                "expected_guide_area": str(strand.get("expected_guide_area") or "").strip() or None,
                "expected_memory_type": str(strand.get("expected_memory_type") or "").strip() or None,
                "radial_expectation": str(strand.get("radial_expectation") or "mid").strip() or "mid",
                "inverse_rationale": str(strand.get("inverse_rationale") or "").strip() or None,
                "priority": priority,
                "expected_answer_field": str(strand.get("answer_field") or "").strip() or _expected_answer_field_for_goal(goal),
                "destination_queue": [dict(item) for item in list(strand.get("destination_queue") or []) if isinstance(item, dict)],
                "search_radius": _default_search_radius(
                    str(strand.get("radial_expectation") or "mid"),
                    str(strand.get("expected_memory_type") or "").strip() or None,
                ),
                "planner_family": _normalized_planner_family(str(strand.get("planner_family") or ""), fallback="heuristic"),
                "family_plan_id": str(
                    strand.get("family_plan_id")
                    or _family_plan_id_for_family(str(strand.get("planner_family") or "heuristic"))
                ).strip()
                or _family_plan_id_for_family(str(strand.get("planner_family") or "heuristic")),
                "family_plan_confidence": round(
                    max(0.0, min(1.0, float(strand.get("family_plan_confidence") or strand.get("seed_confidence") or priority))),
                    4,
                ),
            }
        )
    return specs


def _planner_seed_summaries(answer_strands: list[dict[str, Any]], *, query_text: str) -> tuple[dict[str, Any], dict[str, Any]]:
    strand_rows = [dict(item) for item in list(answer_strands or []) if isinstance(item, dict)]
    required_slots = _required_slots_for_query(query_text)
    strand_slots = sorted(
        {
            _goal_to_slot(str(item.get("goal") or ""))
            for item in strand_rows
            if str(item.get("goal") or "").strip()
        }
    )
    covered_slots = sorted(set(required_slots) & set(strand_slots))
    seed_goal_coverage = {
        "required_slots": required_slots,
        "strand_slots": strand_slots,
        "covered_slots": covered_slots,
        "coverage_ratio": round(len(covered_slots) / max(1, len(required_slots)), 6),
    }
    strands_with_destinations = sum(1 for item in strand_rows if list(item.get("destination_queue") or []))
    seed_destination_presence = {
        "strand_count": len(strand_rows),
        "strands_with_destinations": strands_with_destinations,
        "ratio": round(strands_with_destinations / max(1, len(strand_rows)), 6),
    }
    return seed_goal_coverage, seed_destination_presence


def _planner_seed_plan_from_payload(
    payload: dict[str, Any] | None,
    *,
    query: RetrieveRequest,
    planner_source: str,
    recovered_from_timeout: bool = False,
) -> dict[str, Any] | None:
    if not payload:
        return None
    seed_max_probe_count = _planner_seed_max_items(query.query_text, query.max_probe_count, query.max_total_branches)
    ai_answer_strands = _normalize_answer_strands(
        list(payload.get("answer_strands") or []),
        query_text=query.query_text,
        max_probe_count=seed_max_probe_count,
        planner_family="ai",
    )
    ai_answer_strands = _select_answer_strands_for_query(
        ai_answer_strands,
        query_text=query.query_text,
        max_probe_count=seed_max_probe_count,
    )
    if not ai_answer_strands:
        return None
    probes = _answer_strands_to_probe_specs(ai_answer_strands, root_query_text=query.query_text)
    if not probes:
        return None
    return {
        "probes": probes[: int(query.max_total_branches)],
        "stop_policy": {"stop_when_confidence_ge": 0.78},
        "planner_source": planner_source,
        "seed_summary": str(payload.get("seed_summary") or "").strip() or None,
        "seed_query_class": str(payload.get("seed_query_class") or "").strip() or _query_class(query.query_text),
        "seed_recovered_from_timeout": bool(recovered_from_timeout),
    }


def _run_fast_planner_seed_request(
    query: RetrieveRequest,
    *,
    identity_source: dict[str, Any],
    retrieval_mode: str,
    minimal: bool = False,
    timeout_override: float | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    if not llm_enabled():
        return None, "llm_disabled"
    seed_query_class = _query_class(query.query_text)
    max_items = _planner_seed_max_items(query.query_text, query.max_probe_count, query.max_total_branches)
    identity_hints = _planner_seed_identity_context(identity_source)
    slot_guidance = _planner_seed_slot_guidance(query.query_text, max_items=max_items)
    identity_hints_json = _truncate_prompt_text(json.dumps(identity_hints, ensure_ascii=False), 420)
    metamemory_block = _minimal_retrieval_seed_taxonomy() if minimal else _compact_retrieval_seed_metamemory()
    allowed_goals = ["name", "birthplace", "residence", "role", "projects", "family", "father", "partner", "mentor", "sibling", "style", "values", "history", "documents"]
    allowed_answer_fields = [
        "identity",
        "identity_and_place",
        "role_and_projects",
        "relationships",
        "communication_style",
        "values",
        "history",
        "document_sources",
    ]
    strand_properties = {
        "answer_field": {"type": "string", "enum": allowed_answer_fields},
        "answer_hypothesis": {"type": "string"},
        "goal": {"type": "string", "enum": allowed_goals},
        "landing_hint": {"type": "string"},
        "priority": {"type": "number", "minimum": 0.0, "maximum": 1.0},
    }
    strand_required = ["answer_field", "answer_hypothesis", "goal", "landing_hint", "priority"]
    if not minimal:
        strand_properties["destination_queue"] = {
            "type": "array",
            "maxItems": 3,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "required": ["label", "guide_area", "memory_type", "radial_expectation", "priority", "rationale"],
                "properties": {
                    "label": {"type": "string"},
                    "guide_area": {"type": ["string", "null"]},
                    "memory_type": {"type": ["string", "null"]},
                    "radial_expectation": {"type": "string", "enum": ["core", "inner", "mid", "outer"]},
                    "priority": {"type": "number", "minimum": 0.0, "maximum": 1.0},
                    "rationale": {"type": "string"},
                },
            },
        }
        strand_required.append("destination_queue")
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": ["answer_strands"],
        "properties": {
            "answer_strands": {
                "type": "array",
                "maxItems": max_items,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": strand_required,
                    "properties": strand_properties,
                },
            },
            "seed_summary": {"type": ["string", "null"]},
            "seed_query_class": {"type": ["string", "null"]},
        },
    }
    system_prompt = (
        "AGVM fast planner seed.\n"
        f"{metamemory_block}\n\n"
        f"{slot_guidance}\n\n"
        "Return bounded JSON only. One strand = one answer field. "
        "Short strings. No answer prose, geometry, hops, or broad narrative."
    )
    user_prompt = (
        f"Query: {query.query_text}\n"
        f"Class: {seed_query_class}; max strands: {max_items}; required: {', '.join(_required_slots_for_query(query.query_text))}.\n"
        f"Identity hints: {identity_hints_json}\n"
        "Goals: name,birthplace,residence,role,projects,family,father,partner,mentor,sibling,style,values,history,documents.\n"
        "Fields: identity,identity_and_place,role_and_projects,relationships,communication_style,values,history,document_sources."
    )
    requested_timeout = timeout_override if timeout_override is not None else _planner_seed_timeout_seconds(retrieval_mode, query.query_text)
    payload, error = structured_json(
        model=retrieval_model(),
        system_prompt=system_prompt,
        user_prompt=user_prompt,
        schema_name="agvm_fast_planner_seed",
        schema=schema,
        timeout=requested_timeout + _planner_seed_transport_guard_seconds(),
        role="retrieval",
        max_output_tokens=900 if minimal else 1400,
    )
    return payload, error


def llm_fast_planner_seed(
    query: RetrieveRequest,
    *,
    identity_source: dict[str, Any],
    retrieval_mode: str,
) -> tuple[dict[str, Any] | None, str | None]:
    return _run_fast_planner_seed_request(
        query,
        identity_source=identity_source,
        retrieval_mode=retrieval_mode,
        minimal=False,
    )


def llm_query_decomposition(query_text: str, max_probe_count: int) -> tuple[list[dict[str, Any]] | None, str | None]:
    seed_payload, error = llm_fast_planner_seed(
        RetrieveRequest(
            query_text=query_text,
            max_probe_count=max_probe_count,
            max_total_branches=max_probe_count,
        ),
        identity_source={"core_nodes": []},
        retrieval_mode="balanced",
    )
    if error or not seed_payload:
        return None, error or "llm_empty"
    answer_strands = _normalize_answer_strands(
        list(seed_payload.get("answer_strands") or []),
        query_text=query_text,
        max_probe_count=max_probe_count,
        planner_family="ai",
    )
    answer_strands = _select_answer_strands_for_query(answer_strands, query_text=query_text, max_probe_count=max_probe_count)
    if not answer_strands:
        return None, "llm_empty"
    return _answer_strands_to_probe_specs(answer_strands, root_query_text=query_text), None


def heuristic_query_decomposition(query_text: str, max_probe_count: int) -> list[dict[str, Any]]:
    strand_limit = max_probe_count if not _is_broad_summary_query(query_text) else max(max_probe_count, len(_broad_summary_probe_goal_order()))
    answer_strands = heuristic_answer_strands(query_text, strand_limit)
    probe_specs = _answer_strands_to_probe_specs(answer_strands, root_query_text=query_text)
    return _select_probe_specs_for_query(probe_specs, query_text=query_text, max_probe_count=max_probe_count)


def _legacy_heuristic_query_decomposition_unused(query_text: str, max_probe_count: int) -> list[dict[str, Any]]:
    if _is_document_lookup_query(query_text):
        return [
            {
                "query_text": query_text.strip(),
                "weight": 0.62,
                "goal": "documents",
                "landing_basis": "document_anchor_lookup",
                "expected_guide_area": "Media Signals",
                "expected_memory_type": "document_anchor",
            },
            {
                "query_text": query_text.strip(),
                "weight": 0.38,
                "goal": "history",
                "landing_basis": "document_semantic_fallback",
                "expected_guide_area": "History",
            },
        ][:max_probe_count]
    aspects = [aspect for aspect in detect_query_aspects(query_text) if aspect in CANONICAL_QUERY_GOALS]
    if aspects:
        aspect_templates = _aspect_landing_templates(query_text)
        selected_aspects = aspects[:max_probe_count]
        weight = round(1.0 / max(1, len(selected_aspects)), 6)
        probes: list[dict[str, Any]] = []
        for aspect in selected_aspects:
            probe_query, expected_guide_area = aspect_templates.get(aspect, (query_text.strip(), heuristic_projection(query_text).get("expected_guide_area")))
            probes.append(
                {
                    "query_text": probe_query,
                    "weight": weight,
                    "goal": aspect,
                    "landing_basis": "aspect_template",
                    "expected_guide_area": expected_guide_area,
                }
            )
        return probes
    pieces = [part.strip(" ,;") for part in re.split(r"\s+(?:and|e)\s+|,|;|\+", query_text) if part.strip(" ,;")]
    if not pieces:
        pieces = [query_text.strip()]
    total_chars = max(1, sum(len(piece) for piece in pieces[:max_probe_count]))
    probes = []
    for index, piece in enumerate(pieces[:max_probe_count]):
        probes.append(
            {
                "query_text": piece,
                "weight": round(len(piece) / total_chars, 6),
                "expected_guide_area": heuristic_projection(piece).get("expected_guide_area"),
            }
        )
    return probes


def inverse_query_hint(query_text: str, *, intent_type: str | None = None) -> str:
    lowered = query_text.lower().strip()
    intent = intent_type or detect_query_intent(query_text)
    if intent == "identity_name":
        return "identity memory stating the person's name and core self-identity"
    if intent == "workplace":
        return "work or project memory describing where the person works"
    if intent == "birthplace":
        return "episodic or identity memory stating birthplace"
    if intent == "partner_name":
        return "relationship memory stating the partner's name"
    if any(token in lowered for token in ("come parlo", "how do i speak", "style di comunicazione", "stile di comunicazione")):
        return "identity-style memory describing communication style, tone, and expression"
    if any(token in lowered for token in ("qual è la mia storia", "my story", "storia")):
        return "episodic and identity memories describing the person's history and major life events"
    if any(token in lowered for token in ("su cosa lavoro", "what am i working", "progetto", "project")):
        return "project memory describing ongoing work, projects, and goals"
    return f"memory that would directly answer: {query_text.strip()}"


def _is_broad_summary_query(query_text: str) -> bool:
    lowered = _fold_text(query_text)
    return any(
        token in lowered
        for token in (
            "raccontami tutto di te",
            "raccontami in sintesi",
            "raccontami la tua vita",
            "raccontami della tua vita",
            "raccontami tutto",
            "parlami della tua vita",
            "parlami di te",
            "parlami del tuo lavoro",
            "parlami dei tuoi progetti",
            "lavoro e dei progetti",
            "lavoro e progetti",
            "riassumimi tutto",
            "dimmi tutto",
            "raccontami tutto quello che sai",
            "tutto quello che sai",
            "voglio un dossier completo",
            "dossier completo",
            "quadro completo",
            "profilo completo",
            "profilo esteso",
            "profilo non riassuntivo",
            "curriculum",
            "biografia completa",
            "storia completa",
            "tutta la tua vita",
            "riassunto completo",
            "tell me about yourself",
            "tell me about your life",
            "tell me your life story",
            "tell me everything",
            "full profile",
            "complete biography",
        )
    )


def _is_document_lookup_query(query_text: str) -> bool:
    lowered = _fold_text(query_text)
    padded = f" {lowered} "
    return any(
        token in lowered
        for token in (
            "documento",
            "documenti",
            "document",
            "pdf",
            "file",
            "spec",
            "report",
            "note",
            "appunto",
            "doc ",
        )
    ) or " memo " in padded


def _is_temporal_reference_query(query_text: str) -> bool:
    lowered = _fold_text(query_text)
    if any(
        phrase in lowered
        for phrase in (
            "quando ragioni",
            "quando comunica",
            "quando comunichi",
            "quando parla",
            "quando parli",
            "quando spiega",
            "quando spieghi",
            "quando lavora",
            "quando lavori",
            "when working",
            "when you work",
        )
    ):
        return False
    padded = f" {lowered} "
    phrases = ("riferimenti agli anni", "riferimenti alle date")
    words = ("anno", "anni", "data", "date", "quando", "timeline", "cronologia", "temporale", "temporal", "periodo", "year", "years", "when", "dates")
    return any(phrase in lowered for phrase in phrases) or any(f" {word} " in padded for word in words) or bool(re.search(r"\b(?:19|20)\d{2}\b", lowered))


def _explicit_temporal_terms(query_text: str) -> list[str]:
    years = re.findall(r"\b(?:19|20)\d{2}\b", str(query_text or ""))
    numeric_dates = re.findall(r"\b\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?\b", str(query_text or ""))
    return list(dict.fromkeys([*years, *numeric_dates]))


def _temporal_query_terms(query_text: str, *, max_range_years: int = 25) -> list[str]:
    explicit_terms = _explicit_temporal_terms(query_text)
    year_terms = [term for term in explicit_terms if re.fullmatch(r"(?:19|20)\d{2}", term)]
    if len(year_terms) < 2:
        return explicit_terms
    folded = _fold_text(query_text)
    padded = f" {folded} "
    range_markers = (
        " dal ",
        " al ",
        " alla ",
        " fino ",
        " fino a ",
        " tra ",
        " fra ",
        " between ",
        " from ",
        " to ",
        " through ",
        " until ",
        " range ",
        " periodo ",
        " period ",
        "-",
        "/",
        "–",
        "—",
    )
    if not any(marker in padded or marker in folded for marker in range_markers):
        return explicit_terms
    start = int(year_terms[0])
    end = int(year_terms[-1])
    lower, upper = sorted((start, end))
    if upper - lower > max_range_years:
        return explicit_terms
    expanded_years = [str(year) for year in range(lower, upper + 1)]
    non_year_terms = [term for term in explicit_terms if term not in year_terms]
    return list(dict.fromkeys([*expanded_years, *non_year_terms]))


def _temporal_sweep_terms(query_text: str) -> list[str]:
    query_terms = _temporal_query_terms(query_text)
    if query_terms:
        return query_terms
    return [str(year) for year in range(1990, 2036)]


_TEMPORAL_EVENT_MARKERS: tuple[str, ...] = (
    "acquired",
    "acquisition",
    "announced",
    "press release",
    "transaction",
    "established",
    "founded",
    "launched",
    "inaugurated",
    "strategic alliance",
    "recognized by",
    "sample vendor",
    "published",
    "acquis",
    "annunc",
    "fondat",
    "inaugur",
    "alleanza",
)

_TEMPORAL_LOW_SIGNAL_MARKERS: tuple[str, ...] = (
    "copyright",
    "all rights reserved",
    "cookie",
    "privacy policy",
    "newsletter",
    "subscribe",
    "site navigation",
    "website navigation",
)


def _temporal_source_event_rank(text: str, node: dict[str, Any] | None = None) -> float:
    folded = _fold_text(text)
    if not folded:
        return 0.0
    node_payload = dict(node or {})
    memory_type = str(node_payload.get("memory_type") or "").strip().lower()
    guide_area = str(
        node_payload.get("guide_area")
        or dict(node_payload.get("provenance") or {}).get("guide_conceptual_area")
        or ""
    ).strip().lower()
    score = 0.0
    if re.search(r"\b\d{1,2}\s+[a-z]+\s+(?:19|20)\d{2}\b", folded) or re.search(r"\b(?:19|20)\d{2}-\d{2}-\d{2}\b", folded):
        score += 0.18
    if re.search(r"/(?:19|20)\d{2}/(?:19|20)\d{2}-\d{2}-\d{2}", folded):
        score += 0.12
    event_hits = sum(1 for marker in _TEMPORAL_EVENT_MARKERS if marker in folded)
    score += min(event_hits, 4) * 0.09
    if "press-releases" in folded or "press release" in folded:
        score += 0.12
    if any(marker in folded for marker in ("company", "corporation", "srl", "ltd", "spa", "energy", "systems", "solution")):
        score += 0.04
    if guide_area in {"history", "media signals", "projects", "documents"}:
        score += 0.08
    if memory_type in {"episodic", "history", "project", "document_fact", "document_chunk"}:
        score += 0.07
    if any(marker in folded for marker in _TEMPORAL_LOW_SIGNAL_MARKERS):
        score -= 0.08
    year_count = len(set(re.findall(r"\b(?:19|20)\d{2}\b", folded)))
    if year_count >= 5 and event_hits == 0:
        score -= 0.26
    if folded.count(" 0 ") + folded.count(" 50 ") + folded.count(" 100 ") >= 2 and event_hits == 0:
        score -= 0.18
    return round(max(0.0, min(1.0, score)), 6)


def _temporal_sweep_match_for_node(query_text: str, node: dict[str, Any]) -> dict[str, Any] | None:
    node_id = str(node.get("id") or "").strip()
    if not node_id:
        return None
    summary = str(node.get("summary") or node.get("raw_text") or "").strip()
    raw_text = str(node.get("raw_text") or summary).strip()
    synthetic_match = {
        "node_id": node_id,
        "summary": summary,
        "score": float(node.get("memory_confidence") or node.get("evidence_confidence") or 0.62),
        "raw_score": float(node.get("memory_confidence") or node.get("evidence_confidence") or 0.62),
        "probe_id": "temporal_sweep",
        "reason": "temporal_sweep",
        "sources": ["temporal_sweep"],
        "evidence_snippet": raw_text or summary,
        "node": node,
    }
    inventory = build_temporal_inventory([synthetic_match], max_entries=6)
    entries = [dict(entry) for entry in list(inventory.get("entries") or []) if isinstance(entry, dict)]
    if not entries:
        return None
    requested_terms = set(_temporal_query_terms(query_text))
    if requested_terms:
        entries = [
            entry
            for entry in entries
            if requested_terms & set(str(token) for token in list(entry.get("tokens") or []))
        ]
        if not entries:
            return None
    best_entry = max(
        entries,
        key=lambda entry: (
            float(entry.get("confidence") or 0.0) + _temporal_source_event_rank(str(entry.get("text") or ""), node),
            _temporal_source_event_rank(str(entry.get("text") or ""), node),
            len(str(entry.get("text") or "")),
        ),
    )
    years = sorted({str(year) for entry in entries for year in list(entry.get("years") or []) if str(year)}, key=lambda value: int(value))
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or node.get("guide_area") or "")
    memory_type = str(node.get("memory_type") or "")
    base_score = 0.86
    if requested_terms:
        base_score += 0.08
    if guide_area.lower() == "history" or memory_type in {"episodic", "history"}:
        base_score += 0.05
    if guide_area.lower() in {"projects", "media signals", "documents"} or memory_type in {"project", "document_anchor", "document_chunk"}:
        base_score += 0.03
    temporal_event_rank = _temporal_source_event_rank(str(best_entry.get("text") or raw_text or summary), node)
    score = min(0.995, max(base_score, float(best_entry.get("confidence") or 0.0)) + min(0.08, temporal_event_rank * 0.12))
    return {
        **synthetic_match,
        "summary": summary or str(best_entry.get("text") or ""),
        "score": round(score, 6),
        "raw_score": round(score, 6),
        "reason": "temporal_sweep_explicit_date_evidence",
        "sources": ["temporal_sweep", "text_term_index"],
        "evidence_snippet": str(best_entry.get("text") or raw_text or summary),
        "temporal_event_rank": temporal_event_rank,
        "temporal_inventory": {
            **inventory,
            "entries": entries,
            "years": years or list(inventory.get("years") or []),
        },
    }


def _fetch_temporal_sweep_nodes(query_text: str, *, limit: int) -> list[dict[str, Any]]:
    query_terms = _temporal_query_terms(query_text)
    if query_terms:
        node_by_id: dict[str, dict[str, Any]] = {}

        def collect(terms: list[str], *, node_limit: int) -> None:
            for node in fetch_nodes_by_text_terms(terms, limit=node_limit, include_raw_text=True):
                node_id = str(dict(node or {}).get("id") or "").strip()
                if node_id and node_id not in node_by_id:
                    node_by_id[node_id] = dict(node or {})

        collect(query_terms, node_limit=max(int(limit) * 4, 48))
        year_terms = [term for term in query_terms if re.fullmatch(r"(?:19|20)\d{2}", str(term or ""))]
        if len(year_terms) > 1:
            explicit_years = [
                term
                for term in _explicit_temporal_terms(query_text)
                if re.fullmatch(r"(?:19|20)\d{2}", str(term or ""))
            ]
            per_year_terms = list(dict.fromkeys([*explicit_years, *year_terms[:2], *year_terms[-8:]]))
            per_year_limit = max(4, min(8, int(limit)))
            for year in per_year_terms:
                collect([year], node_limit=per_year_limit)
        return list(node_by_id.values())[: max(int(limit) * 8, 96)]
    node_by_id: dict[str, dict[str, Any]] = {}
    for year in range(1990, 2036):
        for node in fetch_nodes_by_text_terms([str(year)], limit=2, include_raw_text=True):
            node_id = str(node.get("id") or "").strip()
            if node_id and node_id not in node_by_id:
                node_by_id[node_id] = dict(node)
    return list(node_by_id.values())[: max(int(limit) * 6, 48)]


def _temporal_named_target_terms(query_text: str) -> list[str]:
    return [
        entity
        for entity in _warm_entities_from_text(query_text)
        if entity and not re.fullmatch(r"(?:19|20)\d{2}", entity)
    ][:4]


def _temporal_target_match_for_node(query_text: str, node: dict[str, Any], target: str) -> dict[str, Any] | None:
    node_id = str(node.get("id") or "").strip()
    if not node_id:
        return None
    summary = str(node.get("summary") or node.get("raw_text") or "").strip()
    raw_text = str(node.get("raw_text") or summary).strip()
    haystack = _fold_text(f"{summary} {raw_text}")
    if _fold_text(target) not in haystack:
        return None
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or node.get("guide_area") or "")
    memory_type = str(node.get("memory_type") or "")
    score = max(0.93, min(0.975, float(node.get("memory_confidence") or node.get("evidence_confidence") or 0.82) + 0.08))
    slot = "projects" if guide_area.lower() == "projects" or memory_type == "project" else _goal_to_slot(_goal_for_query_text(target, guide_area))
    return {
        "node_id": node_id,
        "summary": summary,
        "score": round(score, 6),
        "raw_score": round(score, 6),
        "probe_id": "temporal_target_sweep",
        "reason": "temporal_named_target_evidence",
        "sources": ["temporal_target_sweep", "text_term_index"],
        "evidence_snippet": raw_text or summary,
        "node": node,
        "support_slots": [slot],
        "branch_goals": ["projects" if slot == "projects" else slot],
    }


def _named_target_goal_for_node(
    query_text: str,
    node: dict[str, Any],
    target: str,
    identity_context: dict[str, Any] | None,
) -> str:
    target_folded = _fold_text(target)
    node_text = _fold_text(f"{node.get('summary') or ''} {node.get('raw_text') or ''}")
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or node.get("guide_area") or "")
    memory_type = str(node.get("memory_type") or "").strip().lower()
    context = dict(identity_context or {})

    def folded_values(key: str) -> set[str]:
        return {_fold_text(item) for item in list(context.get(key) or []) if str(item or "").strip()}

    if target_folded in folded_values("partner_candidates"):
        return "partner"
    if target_folded in folded_values("mentor_candidates"):
        return "mentor"
    if target_folded in folded_values("sibling_candidates"):
        return "sibling"
    if target_folded in folded_values("project_candidates") or target_folded in folded_values("employer_candidates"):
        return "projects"
    if (
        memory_type == "project"
        or guide_area.lower() == "projects"
        or any(token in node_text for token in ("project", "progetto", "sto costruendo", "sta costruendo", "guido", "guida", "works on", "building"))
    ):
        return "projects"
    core_name = _fold_text(str(context.get("core_name") or ""))
    if target_folded and core_name and target_folded in core_name:
        return "name"
    return _goal_for_query_text(query_text, guide_area)


def _named_target_match_for_node(
    query_text: str,
    node: dict[str, Any],
    target: str,
    identity_context: dict[str, Any] | None,
    *,
    source: str,
) -> dict[str, Any] | None:
    node_id = str(node.get("id") or "").strip()
    if not node_id:
        return None
    summary = str(node.get("summary") or node.get("raw_text") or "").strip()
    raw_text = str(node.get("raw_text") or summary).strip()
    haystack = _fold_text(f"{summary} {raw_text}")
    target_folded = _fold_text(target)
    if not target_folded or target_folded not in haystack:
        return None
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or node.get("guide_area") or "")
    memory_type = str(node.get("memory_type") or "")
    goal = _named_target_goal_for_node(query_text, node, target, identity_context)
    slot = _goal_to_slot(goal)
    confidence = max(
        float(node.get("memory_confidence") or 0.0),
        float(node.get("evidence_confidence") or 0.0),
        float(node.get("identity_resolution_confidence") or 0.0),
        0.72,
    )
    if goal == "projects" and (memory_type == "project" or guide_area.lower() == "projects"):
        confidence = max(confidence, 0.9)
    score = max(0.86, min(0.98, confidence + 0.08))
    return {
        "node_id": node_id,
        "summary": summary,
        "score": round(score, 6),
        "raw_score": round(score, 6),
        "probe_id": source,
        "label": "named target",
        "reason": f"{source}:{target}",
        "sources": [source, "text_term_index"],
        "evidence_snippet": raw_text or summary,
        "node": node,
        "support_slots": [slot],
        "branch_goals": [goal],
        "first_answer_preflight": True,
        "named_target_preflight": True,
    }


def _augment_matches_with_temporal_sweep(
    query_text: str,
    matches: list[dict[str, Any]],
    *,
    limit: int,
) -> list[dict[str, Any]]:
    if not _is_temporal_reference_query(query_text):
        return matches
    terms = _temporal_sweep_terms(query_text)
    if not terms:
        return matches
    existing_by_id = {str(match.get("node_id") or ""): dict(match) for match in list(matches or []) if str(match.get("node_id") or "").strip()}
    try:
        nodes = _fetch_temporal_sweep_nodes(query_text, limit=limit)
    except Exception:
        return matches
    sweep_matches: list[dict[str, Any]] = []
    for node in nodes:
        sweep_match = _temporal_sweep_match_for_node(query_text, dict(node))
        if not sweep_match:
            continue
        sweep_matches.append(sweep_match)
    year_best: dict[str, dict[str, Any]] = {}
    remainder: list[dict[str, Any]] = []
    for sweep_match in sweep_matches:
        inventory = dict(sweep_match.get("temporal_inventory") or {})
        years = [str(year) for year in list(inventory.get("years") or []) if str(year)]
        if not years:
            remainder.append(sweep_match)
            continue
        for year in years:
            current = year_best.get(year)
            candidate_key = (
                float(sweep_match.get("score") or 0.0),
                float(sweep_match.get("temporal_event_rank") or 0.0),
                len(str(sweep_match.get("evidence_snippet") or "")),
            )
            current_key = (
                float((current or {}).get("score") or 0.0),
                float((current or {}).get("temporal_event_rank") or 0.0),
                len(str((current or {}).get("evidence_snippet") or "")),
            )
            if current is None or candidate_key > current_key:
                year_best[year] = sweep_match
    requested_years = [
        str(year)
        for year in _temporal_query_terms(query_text)
        if re.fullmatch(r"(?:19|20)\d{2}", str(year or ""))
    ]
    explicit_years = [
        str(year)
        for year in _explicit_temporal_terms(query_text)
        if re.fullmatch(r"(?:19|20)\d{2}", str(year or ""))
    ]
    capacity = max(int(limit), 12)
    if len(requested_years) > capacity:
        selected_years: list[str] = []
        for year in explicit_years:
            if year in year_best and year not in selected_years:
                selected_years.append(year)
        ranked_years = sorted(
            [year for year in year_best if year not in selected_years],
            key=lambda year: (
                -float(year_best[year].get("temporal_event_rank") or 0.0),
                -float(year_best[year].get("score") or 0.0),
                abs(int(year) - int(requested_years[-1])) if requested_years else 0,
                int(year),
            ),
        )
        for year in ranked_years:
            if len(selected_years) >= capacity:
                break
            selected_years.append(year)
        diversified = sorted(selected_years, key=lambda value: int(value))
    else:
        diversified = list(dict.fromkeys(str(year) for year in sorted(year_best, key=lambda value: int(value))))
    ordered_sweep = [year_best[year] for year in diversified]
    seen_sweep_ids = {str(match.get("node_id") or "") for match in ordered_sweep}
    ordered_sweep.extend(match for match in remainder if str(match.get("node_id") or "") not in seen_sweep_ids)
    for sweep_match in ordered_sweep[: max(int(limit), 12)]:
        node_id = str(sweep_match.get("node_id") or "")
        existing = existing_by_id.get(node_id)
        if existing is None or float(sweep_match.get("score") or 0.0) > float(existing.get("score") or 0.0):
            existing_by_id[node_id] = sweep_match
        else:
            existing_sources = list(existing.get("sources") or [])
            existing["sources"] = list(dict.fromkeys([*existing_sources, "temporal_sweep_seen"]))
            existing_by_id[node_id] = existing
    for target in _temporal_named_target_terms(query_text):
        try:
            target_nodes = fetch_nodes_by_text_terms([target], limit=max(6, min(int(limit), 12)), include_raw_text=True)
        except Exception:
            target_nodes = []
        target_matches = [
            match
            for node in target_nodes
            for match in [_temporal_target_match_for_node(query_text, dict(node), target)]
            if match
        ]
        for target_match in target_matches[:4]:
            node_id = str(target_match.get("node_id") or "")
            existing = existing_by_id.get(node_id)
            if existing is None or float(target_match.get("score") or 0.0) > float(existing.get("score") or 0.0):
                existing_by_id[node_id] = target_match
            else:
                existing_sources = list(existing.get("sources") or [])
                existing["sources"] = list(dict.fromkeys([*existing_sources, "temporal_target_sweep_seen"]))
                existing_by_id[node_id] = existing
    return list(existing_by_id.values())


def _temporal_exact_match_score(query_text: str, text: str) -> float:
    terms = _explicit_temporal_terms(query_text)
    if not terms:
        return 0.0
    haystack = _fold_text(text)
    hits = sum(1 for term in terms if term in haystack)
    return hits / max(1, len(terms))


def _query_class(query_text: str) -> str:
    aspects = detect_query_aspects(query_text)
    contract = build_query_contract(query_text)
    query_kind = str(contract.get("query_kind") or "")
    if _is_broad_summary_query(query_text):
        return "broad_summary"
    if _is_document_lookup_query(query_text):
        return "document_lookup"
    if _query_is_entity_connection_path_request(query_text):
        return "relation_fact"
    if query_kind in {"company_founding_relation", "company_founding_timeline"}:
        return "relation_fact"
    if any(aspect in aspects for aspect in ("family", "father", "partner", "mentor", "sibling")):
        return "relation_fact"
    if any(aspect in aspects for aspect in ("style", "values")):
        return "style_values"
    return "direct_fact"


def _should_use_llm_planner(query_text: str) -> bool:
    query_class = _query_class(query_text)
    lowered = _fold_text(query_text)
    aspects = detect_query_aspects(query_text)
    explicit_multi = sum(1 for token in (" e ", " and ", ",", ";", " insieme ", " both ", " oltre ") if token in f" {lowered} ")
    if _query_is_entity_connection_path_request(query_text):
        return True
    if query_contract_requires_expansion(query_text, retrieval_mode="balanced"):
        return True
    if _is_temporal_reference_query(query_text):
        return True
    if query_class in {"broad_summary", "document_lookup"}:
        return True
    if query_class in {"direct_fact", "relation_fact", "style_values"} and len(aspects) <= 2 and explicit_multi <= 1:
        return False
    if query_class == "direct_fact" and len(aspects) <= 1:
        return False
    return True


def _initial_probe_limit(query: RetrieveRequest) -> int:
    hard_limit = min(query.max_probe_count, query.max_total_branches)
    if not llm_enabled():
        return hard_limit
    if _is_broad_summary_query(query.query_text):
        return hard_limit
    if hard_limit >= 5:
        return hard_limit - 2
    if hard_limit >= 3:
        return hard_limit - 1
    if hard_limit >= 2:
        return hard_limit - 1
    return hard_limit


def _retrieval_mode_config(retrieval_mode: str, query_class: str) -> dict[str, Any]:
    mode = str(retrieval_mode or "balanced")
    config: dict[str, Any] = {
        "threshold_adjust": 0.0,
        "broad_summary_goal_floor": 3,
        "direct_fact_floor": 0.64,
        "allow_partial_stop": True,
    }
    if mode == "flash":
        config.update({
            "threshold_adjust": -0.06,
            "broad_summary_goal_floor": 2,
            "direct_fact_floor": 0.58,
        })
    elif mode == "heavy":
        config.update({
            "threshold_adjust": 0.04,
            "broad_summary_goal_floor": 5,
            "direct_fact_floor": 0.7,
            "allow_partial_stop": False,
        })
    elif mode == "forensic":
        config.update({
            "threshold_adjust": 0.08,
            "broad_summary_goal_floor": 6,
            "direct_fact_floor": 0.78,
            "allow_partial_stop": False,
        })
    if query_class == "broad_summary":
        config["allow_partial_stop"] = mode != "forensic"
    return config


def _select_retrieval_mode(query: RetrieveRequest) -> tuple[str, str]:
    if query.retrieval_mode:
        return str(query.retrieval_mode), "client"
    query_class = _query_class(query.query_text)
    aspects = detect_query_aspects(query.query_text)
    if query_class == "document_lookup":
        return "forensic", "master"
    if query_class == "broad_summary":
        return "heavy", "master"
    if _is_temporal_reference_query(query.query_text):
        return "balanced", "master"
    if query_contract_requires_expansion(query.query_text, retrieval_mode="balanced"):
        return "balanced", "query_contract"
    if query_class == "style_values" and "values" in aspects:
        return "heavy", "master"
    if query_class in {"direct_fact", "relation_fact"} and len(aspects) <= 1:
        return "flash", "master"
    return "balanced", "master"


def _should_use_ai_navigation_worker(*, retrieval_mode: str, query_class: str, round_index: int, goal: str) -> bool:
    if not llm_enabled():
        return False
    if retrieval_mode in {"heavy", "forensic"}:
        return True
    if query_class in {"broad_summary", "document_lookup"}:
        return True
    if round_index > 1 and goal in {"family", "father", "partner", "mentor", "sibling", "history", "documents", "style", "values"}:
        return True
    return False


def _goal_to_slot(goal: str) -> str:
    normalized = str(goal or "").strip().lower()
    mapping = {
        "name": "identity",
        "birthplace": "place",
        "residence": "place",
        "role": "work",
        "projects": "work",
        "company_founding": "work",
        "family": "relationships",
        "father": "relationships",
        "partner": "relationships",
        "mentor": "relationships",
        "sibling": "relationships",
        "style": "style",
        "values": "values",
        "history": "history",
        "documents": "documents",
    }
    return mapping.get(normalized, normalized or "identity")


def _canonical_required_slot(slot: str) -> str:
    normalized = str(slot or "").strip().lower()
    mapping = {
        "relation_detail": "relationships",
        "relationship": "relationships",
        "family": "relationships",
        "family_relation": "relationships",
        "work_company": "work",
        "role_and_projects": "work",
        "company": "work",
        "company_founding": "work",
        "project": "work",
        "document": "documents",
        "document_sources": "documents",
    }
    return mapping.get(normalized, normalized)


def _required_slots_for_query(query_text: str) -> list[str]:
    contract = build_query_contract(query_text)
    required: list[str] = []
    for slot in list(contract.get("required_slots") or []):
        canonical = _canonical_required_slot(str(slot))
        if canonical and canonical not in required:
            required.append(canonical)
    return required or ["identity"]


def _contract_match_priority(query_text: str, match: dict[str, Any]) -> float:
    required_slots = {str(slot).strip().lower() for slot in _required_slots_for_query(query_text)}
    requested_goals = {
        str(goal).strip().lower()
        for goal in detect_query_aspects(query_text)
        if str(goal).strip().lower() in CANONICAL_QUERY_GOALS
    }
    goals = {
        str(goal).strip().lower()
        for goal in [match.get("goal"), *list(match.get("branch_goals") or [])]
        if str(goal or "").strip()
    }
    slots = {
        _goal_to_slot(goal)
        for goal in goals
        if str(goal or "").strip()
    }
    slots.update(
        _canonical_required_slot(str(slot).strip().lower())
        for slot in list(match.get("support_slots") or [])
        if str(slot or "").strip()
    )
    goals.discard("")
    slots.discard("")
    sources = {str(source).strip().lower() for source in list(match.get("sources") or []) if str(source).strip()}
    priority = 0.0
    if goals & requested_goals:
        priority += 2.0
    if slots & required_slots:
        priority += 1.25
    if "goal_text" in sources and slots & required_slots:
        priority += 1.0
    if "goal_subject_text" in sources and slots & required_slots:
        priority += 1.1
    if "goal_support" in sources and slots & required_slots:
        priority += 0.35
    node = dict(match.get("node") or {})
    memory_type = str(match.get("memory_type") or node.get("memory_type") or "").strip().lower()
    if "relationships" in slots and memory_type == "relational":
        priority += 0.75
    if "values" in slots and memory_type in {"value", "identity_style", "identity"}:
        priority += 0.55
    return round(priority, 4)


def _contract_match_sort_key(query_text: str, match: dict[str, Any]) -> tuple[float, float, str]:
    priority = _contract_match_priority(query_text, match)
    score = float(match.get("score") or 0.0)
    return (-priority, -score, str(match.get("node_id") or ""))


def _expected_answer_field_for_goal(goal: str) -> str:
    normalized = str(goal or "").strip().lower()
    mapping = {
        "name": "identity",
        "birthplace": "identity_and_place",
        "residence": "identity_and_place",
        "role": "role_and_projects",
        "projects": "role_and_projects",
        "father": "relationships",
        "partner": "relationships",
        "mentor": "relationships",
        "sibling": "relationships",
        "style": "communication_style",
        "values": "values",
        "history": "history",
        "documents": "document_sources",
    }
    return mapping.get(normalized, _goal_to_slot(normalized) or "identity")


def _broad_summary_slot_priority() -> list[str]:
    return ["identity", "history", "place", "work", "style", "values", "relationships", "documents"]


def _slot_priority_index(slot: str, *, query_text: str) -> int:
    normalized = str(slot or "").strip().lower()
    if _is_broad_summary_query(query_text):
        order = _broad_summary_slot_priority()
        if normalized in order:
            return order.index(normalized)
    required_slots = [str(item).strip().lower() for item in _required_slots_for_query(query_text) if str(item).strip()]
    if normalized in required_slots:
        return required_slots.index(normalized)
    return len(required_slots) + 8


def _canonical_answer_field(raw_answer_field: str | None, *, goal: str) -> str:
    normalized = _fold_text(str(raw_answer_field or ""))
    expected = _expected_answer_field_for_goal(goal)
    mapped: str | None = None
    if normalized in {"identity", "name", "self", "persona"}:
        mapped = "identity"
    elif normalized in {"identity and place", "identity_place", "place", "residence", "birthplace"}:
        mapped = "identity_and_place"
    elif normalized in {"work", "role", "projects", "role and projects", "role_projects", "career"}:
        mapped = "role_and_projects"
    elif normalized in {"relationships", "relationship", "family", "father", "partner", "mentor", "sibling"}:
        mapped = "relationships"
    elif normalized in {"style", "communication style", "communication_style", "expression"}:
        mapped = "communication_style"
    elif normalized in {"values", "value"}:
        mapped = "values"
    elif normalized in {"history", "life", "biography"}:
        mapped = "history"
    elif normalized in {"documents", "document", "document sources", "document_sources"}:
        mapped = "document_sources"
    if not mapped:
        return expected
    compatibility = {
        "identity": {"name"},
        "identity_and_place": {"birthplace", "residence"},
        "role_and_projects": {"role", "projects"},
        "relationships": {"family", "father", "partner", "mentor", "sibling"},
        "communication_style": {"style"},
        "values": {"values"},
        "history": {"history"},
        "document_sources": {"documents"},
    }
    if goal and goal not in compatibility.get(mapped, set()):
        return expected
    return mapped


def _normalized_planner_family(raw_planner_family: str | None, *, fallback: str) -> str:
    normalized = str(raw_planner_family or "").strip().lower()
    if normalized == "ai":
        return "ai"
    fallback_normalized = str(fallback or "").strip().lower()
    return "ai" if fallback_normalized == "ai" else "heuristic"


def _sanitize_seed_destination_queue(
    destination_queue: list[dict[str, Any]] | None,
    *,
    goal: str,
    query_text: str,
    planner_family: str,
) -> list[dict[str, Any]]:
    destination_rows = [dict(item) for item in list(destination_queue or []) if isinstance(item, dict)]
    if not destination_rows:
        return []
    if planner_family == "ai" and _is_broad_summary_query(query_text):
        return []
    return destination_rows


def _corroboration_needs_for_goal(goal: str, *, query_class: str) -> list[str]:
    slot = _goal_to_slot(goal)
    needs: list[str] = [slot]
    if goal in {"role", "projects"}:
        needs.extend(["project", "identity"])
    elif goal in {"family", "father", "partner", "mentor", "sibling"}:
        needs.extend(["identity", "relationship"])
    elif goal == "style":
        needs.extend(["identity_style", "expression"])
    elif goal == "values":
        needs.extend(["value", "identity"])
    elif goal == "history":
        needs.extend(["episodic", "identity"])
    elif goal == "documents":
        needs.extend(["document_anchor", "document_chunk", "document_fact"])
    if query_class == "document_lookup":
        needs.extend(["document_anchor", "document_chunk"])
    return list(dict.fromkeys(item for item in needs if item))


def _expected_stop_condition_for_goal(goal: str, *, query_class: str) -> str:
    if query_class == "document_lookup":
        return "enough_grounded_document_anchor_evidence"
    mapping = {
        "role": "enough_grounded_role_and_project_evidence",
        "projects": "enough_grounded_role_and_project_evidence",
        "style": "enough_grounded_style_evidence",
        "values": "enough_grounded_values_evidence",
        "history": "enough_grounded_history_evidence",
        "documents": "enough_grounded_document_evidence",
    }
    return mapping.get(str(goal or "").strip().lower(), f"enough_grounded_{_goal_to_slot(goal)}_evidence")


def _semantic_destination_templates_for_goal(goal: str) -> list[dict[str, Any]]:
    normalized = str(goal or "").strip().lower()
    if normalized in {"role", "projects"}:
        return [
            {"label": "work", "guide_area": "Projects", "memory_type": "project", "radial_expectation": "mid", "priority": 0.94},
            {"label": "projects", "guide_area": "Operational", "memory_type": "knowledge", "radial_expectation": "mid", "priority": 0.82},
            {"label": "documents", "guide_area": "Media Signals", "memory_type": "document_anchor", "radial_expectation": "outer", "priority": 0.68},
        ]
    if normalized == "company_founding":
        return [
            {"label": "company_relations", "guide_area": "Projects", "memory_type": "project", "radial_expectation": "mid", "priority": 0.96},
            {"label": "company_events", "guide_area": "History", "memory_type": "episodic", "radial_expectation": "mid", "priority": 0.76},
            {"label": "company_documents", "guide_area": "Media Signals", "memory_type": "document_anchor", "radial_expectation": "outer", "priority": 0.72},
        ]
    if normalized in {"family", "father", "partner", "mentor", "sibling"}:
        return [
            {"label": "relationships", "guide_area": "Relationships", "memory_type": "relational", "radial_expectation": "inner", "priority": 0.92},
            {"label": "identity", "guide_area": "Identity", "memory_type": "identity", "radial_expectation": "core", "priority": 0.7},
        ]
    if normalized == "style":
        return [
            {"label": "style", "guide_area": "Expression", "memory_type": "identity_style", "radial_expectation": "inner", "priority": 0.94},
            {"label": "values", "guide_area": "Values", "memory_type": "value", "radial_expectation": "mid", "priority": 0.66},
        ]
    if normalized == "values":
        return [
            {"label": "values", "guide_area": "Values", "memory_type": "value", "radial_expectation": "inner", "priority": 0.94},
            {"label": "style", "guide_area": "Expression", "memory_type": "identity_style", "radial_expectation": "mid", "priority": 0.62},
        ]
    if normalized == "history":
        return [
            {"label": "history", "guide_area": "History", "memory_type": "episodic", "radial_expectation": "mid", "priority": 0.9},
            {"label": "documents", "guide_area": "Media Signals", "memory_type": "document_anchor", "radial_expectation": "outer", "priority": 0.64},
        ]
    if normalized == "documents":
        return [
            {"label": "document_anchor", "guide_area": "Media Signals", "memory_type": "document_anchor", "radial_expectation": "outer", "priority": 0.96},
            {"label": "document_chunks", "guide_area": "Media Signals", "memory_type": "document_chunk", "radial_expectation": "outer", "priority": 0.84},
            {"label": "document_facts", "guide_area": "Media Signals", "memory_type": "document_fact", "radial_expectation": "outer", "priority": 0.72},
        ]
    if normalized in {"birthplace", "residence"}:
        return [
            {"label": "place", "guide_area": "Identity", "memory_type": "identity", "radial_expectation": "core", "priority": 0.88},
            {"label": "history", "guide_area": "History", "memory_type": "episodic", "radial_expectation": "mid", "priority": 0.6},
        ]
    return [
        {"label": "identity", "guide_area": "Identity", "memory_type": "identity", "radial_expectation": "core", "priority": 0.9},
    ]


def _normalize_destination_queue(
    *,
    spec_destinations: list[dict[str, Any]] | None,
    goal: str,
    probe_label: str,
    fallback_guide_area: str | None,
    fallback_memory_type: str | None,
    fallback_radial_expectation: str,
    fallback_color_hex: str | None,
    fallback_bucket_keys: list[str] | None = None,
) -> list[dict[str, Any]]:
    destination_specs = [dict(item) for item in list(spec_destinations or []) if isinstance(item, dict)]
    if not destination_specs:
        destination_specs = _semantic_destination_templates_for_goal(goal)
    normalized: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for index, destination in enumerate(destination_specs, start=1):
        label = str(destination.get("label") or destination.get("destination_label") or destination.get("goal") or goal or probe_label).strip() or probe_label
        guide_area = str(destination.get("guide_area") or fallback_guide_area or "").strip() or None
        memory_type = str(destination.get("memory_type") or fallback_memory_type or "").strip() or None
        radial_expectation = str(destination.get("radial_expectation") or fallback_radial_expectation or "mid").strip() or "mid"
        signature = (label.lower(), str(guide_area or "").lower(), str(memory_type or "").lower())
        if signature in seen:
            continue
        seen.add(signature)
        destination_id = str(destination.get("destination_id") or f"dest_{probe_label.lower().replace(' ', '_')}_{index}").strip()
        normalized.append(
            {
                "destination_id": destination_id,
                "destination_key": "::".join(
                    [
                        str(label or "").strip().lower(),
                        str(guide_area or "").strip().lower(),
                        str(memory_type or "").strip().lower(),
                    ]
                ),
                "label": label,
                "guide_area": guide_area,
                "memory_type": memory_type,
                "radial_expectation": radial_expectation,
                "semantic_color_hint": str(destination.get("semantic_color_hint") or fallback_color_hex or "").strip() or None,
                "target_bucket_keys": [str(item) for item in list(destination.get("target_bucket_keys") or fallback_bucket_keys or []) if str(item).strip()][:4],
                "target_node_ids": [str(item) for item in list(destination.get("target_node_ids") or []) if str(item).strip()][:4],
                "rationale": _truncate_prompt_text(str(destination.get("rationale") or destination.get("reason") or f"{probe_label} should cover {label}").strip(), 180),
                "priority": round(max(0.0, min(1.0, float(destination.get("priority") or max(0.3, 1.0 - ((index - 1) * 0.14))))), 4),
            }
        )
    return normalized[:4]


def _destination_lease_key(destination: dict[str, Any] | None) -> str | None:
    destination = dict(destination or {})
    explicit = str(destination.get("destination_key") or "").strip().lower()
    if explicit:
        return explicit
    label = str(destination.get("label") or "").strip().lower()
    guide_area = str(destination.get("guide_area") or "").strip().lower()
    memory_type = str(destination.get("memory_type") or "").strip().lower()
    if not any((label, guide_area, memory_type)):
        return None
    return "::".join([label, guide_area, memory_type])


def _hex_to_rgb(hex_value: str | None) -> tuple[int, int, int] | None:
    normalized = str(hex_value or "").strip().lstrip("#")
    if len(normalized) != 6 or any(ch not in "0123456789abcdefABCDEF" for ch in normalized):
        return None
    return tuple(int(normalized[index : index + 2], 16) for index in (0, 2, 4))


def _color_similarity_from_hex(left_hex: str | None, right_hex: str | None) -> float:
    left_rgb = _hex_to_rgb(left_hex)
    right_rgb = _hex_to_rgb(right_hex)
    if left_rgb is None or right_rgb is None:
        return 0.0
    distance_sum = (
        abs(left_rgb[0] - right_rgb[0])
        + abs(left_rgb[1] - right_rgb[1])
        + abs(left_rgb[2] - right_rgb[2])
    )
    return max(0.0, 1.0 - (distance_sum / (255.0 * 3.0)))


def _route_region_id_for_candidate(candidate: dict[str, Any]) -> str:
    node = dict(candidate or {})
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or node.get("guide_area") or "").strip().lower() or "unknown"
    memory_type = str(node.get("memory_type") or "").strip().lower() or "unknown"
    radial_value = compute_radius_value(
        dict(node.get("routing_semantic_scores") or {}),
        dict(node.get("routing_facets") or {}),
        is_summary=bool(node.get("is_summary")),
        is_document_anchor=bool(node.get("is_document_anchor")),
        granularity=float(node.get("granularity") or 0.5),
        novelty=float(node.get("novelty") or 0.5),
    )
    if radial_value <= 0.24:
        radial_expectation = "core"
    elif radial_value <= 0.42:
        radial_expectation = "inner"
    elif radial_value <= 0.68:
        radial_expectation = "mid"
    else:
        radial_expectation = "outer"
    return f"{guide_area}::{memory_type}::{radial_expectation}"


def _region_descriptor_from_candidate(
    candidate: dict[str, Any] | None,
    *,
    fallback_probe: dict[str, Any],
    destination: dict[str, Any] | None = None,
) -> dict[str, Any]:
    node = dict(candidate or {})
    destination = dict(destination or {})
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or node.get("guide_area") or destination.get("guide_area") or fallback_probe.get("expected_guide_area") or "").strip() or None
    memory_type = str(node.get("memory_type") or destination.get("memory_type") or fallback_probe.get("expected_memory_type") or "").strip() or None
    region_id = _route_region_id_for_candidate(node) if node else _region_descriptor_from_probe(fallback_probe, destination=destination).get("region_id")
    label = str(node.get("summary") or destination.get("label") or fallback_probe.get("label") or fallback_probe.get("goal") or "region").strip()
    semantic_color_hint = (
        str((node.get("semantic_color") or {}).get("hex") or "").strip()
        or str((node.get("topology_color") or {}).get("hex") or "").strip()
        or str(destination.get("semantic_color_hint") or ((fallback_probe.get("semantic_color") or {}).get("hex")) or "").strip()
        or None
    )
    bucket_key = str((node.get("bucket") or {}).get("key") or "").strip()
    target_bucket_keys = [bucket_key] if bucket_key else [str(item) for item in list(destination.get("target_bucket_keys") or fallback_probe.get("target_bucket_keys") or []) if str(item).strip()][:4]
    return {
        "region_id": str(region_id or "unknown"),
        "label": label,
        "guide_area": guide_area,
        "memory_type": memory_type,
        "radial_expectation": str(destination.get("radial_expectation") or fallback_probe.get("radial_expectation") or "mid"),
        "semantic_color_hint": semantic_color_hint,
        "target_bucket_keys": target_bucket_keys,
    }


def _route_candidate_source_label(sources: list[str]) -> str:
    normalized_sources = {str(source or "") for source in list(sources or [])}
    if "route_highway" in normalized_sources or "action_highway" in normalized_sources:
        return "highway"
    if "highway_neighbor" in normalized_sources:
        return "highway_neighbor"
    if "route_link" in normalized_sources or "action_link" in normalized_sources:
        return "link"
    if "adjacent_bucket" in normalized_sources:
        return "adjacent_bucket"
    if "exact_temporal" in normalized_sources:
        return "exact_temporal"
    if "nearby_radius" in normalized_sources:
        return "nearby_radius"
    if "goal_support" in normalized_sources:
        return "goal_support"
    if "identity_core" in normalized_sources:
        return "identity_core"
    if "document_anchor" in normalized_sources:
        return "document_anchor"
    return "candidate_pool"


def _route_candidate_move_type(sources: list[str], *, current_node_id: str | None, candidate_id: str) -> tuple[str, str, bool]:
    normalized_sources = {str(source or "") for source in list(sources or [])}
    if current_node_id and candidate_id == current_node_id:
        return "hydrate_current_node", "none", False
    if "route_highway" in normalized_sources or "action_highway" in normalized_sources or "highway_neighbor" in normalized_sources:
        return "follow_highway", "highway", True
    if "route_link" in normalized_sources or "action_link" in normalized_sources:
        return "follow_local_link", "link", True
    return "inspect_local_neighbors", "local", True


def _route_family_attribution(branch: dict[str, Any]) -> str:
    families = _families_for_record(branch)
    if len(families) > 1:
        return "dual-origin"
    return families[0] if families else "heuristic"


def _active_region_pressure(blackboard: dict[str, Any], *, branch_id: str) -> dict[str, int]:
    pressure_map: dict[str, int] = defaultdict(int)
    for summary in list(blackboard.get("branch_summaries") or []):
        if str(summary.get("branch_id") or "") == branch_id:
            continue
        if str(summary.get("status") or "") != "active":
            continue
        region_id = str((summary.get("current_region") or {}).get("region_id") or "")
        if region_id:
            pressure_map[region_id] += 1
    return dict(pressure_map)


def _destination_queue_for_execution(branch: dict[str, Any]) -> tuple[list[dict[str, Any]], int]:
    execution_queue = [dict(item) for item in list(branch.get("execution_destination_queue") or []) if isinstance(item, dict)]
    if not execution_queue:
        execution_queue = [
            dict(item)
            for item in list(branch.get("semantic_destination_queue") or branch.get("destination_queue") or [])
            if isinstance(item, dict)
        ]
    execution_index = int(branch.get("destination_execution_index") or 0)
    if execution_index < 0:
        execution_index = 0
    if execution_index >= len(execution_queue):
        execution_index = max(0, len(execution_queue) - 1)
    return execution_queue, execution_index


def _destination_identity(destination: dict[str, Any] | None) -> tuple[str, str, str, str]:
    destination = dict(destination or {})
    return (
        str(destination.get("destination_id") or "").strip().lower(),
        str(destination.get("label") or "").strip().lower(),
        str(destination.get("guide_area") or "").strip().lower(),
        str(destination.get("memory_type") or "").strip().lower(),
    )


def _destination_semantic_index(queue: list[dict[str, Any]], destination: dict[str, Any] | None) -> int | None:
    target_identity = _destination_identity(destination)
    if not any(target_identity):
        return None
    for index, item in enumerate(list(queue or [])):
        if _destination_identity(item) == target_identity:
            return index
    return None


_TERMINAL_DESTINATION_STATES = {
    "reached",
    "route_exhausted",
    "merged",
    "suppressed_by_master",
    "superseded_by_stronger_branch",
}


def _destination_resolution_key(destination: dict[str, Any] | None, *, fallback_prefix: str = "destination") -> str | None:
    destination = dict(destination or {})
    destination_id = str(destination.get("destination_id") or "").strip()
    if destination_id:
        return destination_id
    destination_key = _destination_lease_key(destination)
    if destination_key:
        return destination_key
    label = str(destination.get("label") or "").strip()
    if label:
        return f"{fallback_prefix}::{label.lower()}"
    return None


def _clone_destination_resolution(payload: dict[str, Any] | None) -> dict[str, dict[str, Any]]:
    cloned: dict[str, dict[str, Any]] = {}
    for key, value in dict(payload or {}).items():
        normalized_key = str(key or "").strip()
        if not normalized_key:
            continue
        cloned[normalized_key] = dict(value or {})
    return cloned


def _ensure_branch_destination_resolution(branch: dict[str, Any], *, round_index: int = 0) -> dict[str, dict[str, Any]]:
    resolution = _clone_destination_resolution(branch.get("destination_resolution"))
    semantic_queue = [dict(item) for item in list(branch.get("semantic_destination_queue") or branch.get("destination_queue") or []) if isinstance(item, dict)]
    origin_families = _families_for_record(branch)
    for semantic_index, destination in enumerate(semantic_queue):
        destination_key = _destination_resolution_key(destination)
        if not destination_key:
            continue
        existing = dict(resolution.get(destination_key) or {})
        execution_index = _destination_semantic_index(list(branch.get("execution_destination_queue") or semantic_queue), destination)
        execution_history = [int(item) for item in list(existing.get("execution_order_history") or []) if isinstance(item, int)]
        if execution_index is not None and execution_index not in execution_history:
            execution_history.append(int(execution_index))
        resolution[destination_key] = {
            "destination_id": str(destination.get("destination_id") or destination_key),
            "label": str(destination.get("label") or destination_key),
            "origin_families": list(existing.get("origin_families") or origin_families),
            "semantic_order_index": semantic_index,
            "execution_order_history": execution_history[:12],
            "state": str(existing.get("state") or "pending"),
            "state_reason": str(existing.get("state_reason") or "queued_for_resolution"),
            "first_seen_round": int(existing.get("first_seen_round") or round_index),
            "terminal_round": int(existing.get("terminal_round")) if existing.get("terminal_round") is not None else None,
        }
    branch["destination_resolution"] = resolution
    return resolution


def _set_destination_resolution_state(
    branch: dict[str, Any],
    destination: dict[str, Any] | None,
    *,
    state: str,
    state_reason: str,
    round_index: int,
    execution_index: int | None = None,
) -> dict[str, dict[str, Any]]:
    resolution = _ensure_branch_destination_resolution(branch, round_index=round_index)
    destination_payload = dict(destination or {})
    destination_key = _destination_resolution_key(destination_payload)
    if not destination_key:
        return resolution
    entry = dict(resolution.get(destination_key) or {})
    if not entry:
        semantic_index = _destination_semantic_index(list(branch.get("semantic_destination_queue") or branch.get("destination_queue") or []), destination_payload)
        entry = {
            "destination_id": str(destination_payload.get("destination_id") or destination_key),
            "label": str(destination_payload.get("label") or destination_key),
            "origin_families": _families_for_record(branch),
            "semantic_order_index": semantic_index if semantic_index is not None else -1,
            "execution_order_history": [],
            "state": "pending",
            "state_reason": "queued_for_resolution",
            "first_seen_round": int(round_index),
            "terminal_round": None,
        }
    current_state = str(entry.get("state") or "pending")
    if current_state in _TERMINAL_DESTINATION_STATES and state not in _TERMINAL_DESTINATION_STATES:
        branch["destination_resolution"] = resolution
        return resolution
    execution_history = [int(item) for item in list(entry.get("execution_order_history") or []) if isinstance(item, int)]
    if execution_index is not None and int(execution_index) not in execution_history:
        execution_history.append(int(execution_index))
    entry["execution_order_history"] = execution_history[:12]
    entry["state"] = str(state)
    entry["state_reason"] = str(state_reason or state)
    if state in _TERMINAL_DESTINATION_STATES:
        entry["terminal_round"] = int(round_index)
    elif entry.get("terminal_round") is None:
        entry["terminal_round"] = None
    resolution[destination_key] = entry
    branch["destination_resolution"] = resolution
    return resolution


def _bulk_mark_open_destinations(
    branch: dict[str, Any],
    *,
    state: str,
    state_reason: str,
    round_index: int,
) -> dict[str, dict[str, Any]]:
    resolution = _ensure_branch_destination_resolution(branch, round_index=round_index)
    for key, entry in list(resolution.items()):
        current_state = str((entry or {}).get("state") or "pending")
        if current_state in _TERMINAL_DESTINATION_STATES:
            continue
        updated = dict(entry or {})
        updated["state"] = str(state)
        updated["state_reason"] = str(state_reason or state)
        if state in _TERMINAL_DESTINATION_STATES:
            updated["terminal_round"] = int(round_index)
        resolution[key] = updated
    branch["destination_resolution"] = resolution
    return resolution


def _finalize_terminal_branch_destinations(branch: dict[str, Any], *, round_index: int) -> dict[str, Any]:
    updated = dict(branch or {})
    status = str(updated.get("status") or "").strip()
    route_state = str(updated.get("route_state") or "").strip()
    stop_reason = str(updated.get("stop_reason") or route_state or status or "terminal_branch").strip()
    terminal_state: str | None = None
    terminal_reason = stop_reason or "terminal_branch"
    if status == "satisfied" or route_state in {"goal_satisfied", "superseded"}:
        terminal_state = "superseded_by_stronger_branch"
        terminal_reason = stop_reason or route_state or "goal_satisfied"
    elif status == "merged" or route_state == "merged":
        terminal_state = "merged"
        terminal_reason = stop_reason or "merged"
    elif status == "stopped" or route_state in {"route_exhausted", "stopped"}:
        terminal_state = "suppressed_by_master" if terminal_reason.startswith("master_") else "route_exhausted"
    if terminal_state is None:
        return updated
    _bulk_mark_open_destinations(
        updated,
        state=terminal_state,
        state_reason=terminal_reason,
        round_index=int(round_index or 0),
    )
    updated["active_destination"] = None
    progress = dict(updated.get("destination_progress") or {})
    progress["active_destination_id"] = None
    progress["remaining_destination_ids"] = []
    updated["destination_progress"] = progress
    return updated


def _final_closure_summary(branches: list[dict[str, Any]]) -> dict[str, Any]:
    blockers: list[dict[str, Any]] = []
    blocker_reason_histogram: dict[str, int] = defaultdict(int)
    for branch in list(branches or []):
        resolution = _ensure_branch_destination_resolution(branch, round_index=0)
        branch_id = str(branch.get("branch_id") or "")
        planner_family = str(branch.get("planner_family") or "heuristic")
        origin_families = _families_for_record(branch)
        for key, entry in resolution.items():
            state = str((entry or {}).get("state") or "pending")
            if state in _TERMINAL_DESTINATION_STATES:
                continue
            blocker = {
                "branch_id": branch_id,
                "planner_family": planner_family,
                "origin_families": origin_families,
                "destination_key": key,
                "destination_id": str((entry or {}).get("destination_id") or key),
                "label": str((entry or {}).get("label") or key),
                "state": state,
                "state_reason": str((entry or {}).get("state_reason") or state),
                "semantic_order_index": (entry or {}).get("semantic_order_index"),
            }
            blockers.append(blocker)
            blocker_reason_histogram[str(blocker["state_reason"] or blocker["state"])] += 1
    return {
        "final_closure_ready": not blockers,
        "unresolved_destination_count": len(blockers),
        "final_closure_blockers": blockers[:16],
        "closure_blocker_reason_histogram": dict(blocker_reason_histogram),
    }


def _context_level_1_ready(
    *,
    context: dict[str, Any] | None = None,
    evidence_reservoir: dict[str, Any] | None = None,
    shared_evidence: dict[str, Any] | None = None,
) -> bool:
    context = dict(context or {})
    evidence_reservoir = dict(evidence_reservoir or {})
    shared_evidence = dict(shared_evidence or {})
    sections = list(context.get("structured_sections") or [])
    if sections:
        return True
    if str(context.get("context_summary") or "").strip():
        return True
    promoted_count = int((evidence_reservoir.get("reservoir_summary") or {}).get("promoted_count") or 0)
    if promoted_count > 0:
        return True
    if float(shared_evidence.get("confidence") or 0.0) >= 0.45:
        return True
    return False


def _answer_surface_state(
    *,
    can_answer_now: bool,
    context_level_1_ready: bool,
    final_closure_ready: bool,
    final_sealed: bool,
) -> str:
    if final_sealed:
        return "final_sealed"
    if can_answer_now and not final_closure_ready:
        return "answer_now_and_continue"
    if can_answer_now:
        return "answer_now"
    if context_level_1_ready:
        return "context_level_1_ready"
    return "not_ready"


def _surface_runtime_fields(
    *,
    branches: list[dict[str, Any]],
    context: dict[str, Any] | None = None,
    evidence_reservoir: dict[str, Any] | None = None,
    shared_evidence: dict[str, Any] | None = None,
    can_answer_now: bool = False,
    final_sealed: bool = False,
) -> dict[str, Any]:
    closure_summary = _final_closure_summary(branches)
    level_1_ready = _context_level_1_ready(
        context=context,
        evidence_reservoir=evidence_reservoir,
        shared_evidence=shared_evidence,
    )
    answer_surface = _answer_surface_state(
        can_answer_now=can_answer_now,
        context_level_1_ready=level_1_ready,
        final_closure_ready=bool(closure_summary.get("final_closure_ready")),
        final_sealed=final_sealed,
    )
    closure_state = "final_sealed" if final_sealed else ("exploration_complete" if bool(closure_summary.get("final_closure_ready")) else "open")
    return {
        "answer_surface_state": answer_surface,
        "closure_state": closure_state,
        "final_closure_ready": bool(closure_summary.get("final_closure_ready")),
        "final_closure_blockers": [dict(item) for item in list(closure_summary.get("final_closure_blockers") or [])[:16]],
        "unresolved_destination_count": int(closure_summary.get("unresolved_destination_count") or 0),
        "closure_blocker_reason_histogram": dict(closure_summary.get("closure_blocker_reason_histogram") or {}),
        "context_level_1_ready": bool(level_1_ready),
        "answer_now_before_exploration_complete": bool(can_answer_now and not bool(closure_summary.get("final_closure_ready"))),
        "final_closure_after_destination_resolution": bool(final_sealed and bool(closure_summary.get("final_closure_ready"))),
    }


def _route_destination_match_for_node(node_payload: dict[str, Any] | None, destination: dict[str, Any] | None) -> bool:
    node_payload = dict(node_payload or {})
    destination = dict(destination or {})
    if not destination or not node_payload:
        return False
    target_node_ids = {str(item).strip() for item in list(destination.get("target_node_ids") or []) if str(item).strip()}
    if str(node_payload.get("id") or "").strip() in target_node_ids:
        return True
    target_bucket_keys = {str(item).strip() for item in list(destination.get("target_bucket_keys") or []) if str(item).strip()}
    node_bucket_key = str((node_payload.get("bucket") or {}).get("key") or "").strip()
    if node_bucket_key and node_bucket_key in target_bucket_keys:
        return True
    active_guide_area = str(destination.get("guide_area") or "").strip().lower()
    active_memory_type = str(destination.get("memory_type") or "").strip().lower()
    node_guide_area = str((node_payload.get("provenance") or {}).get("guide_conceptual_area") or node_payload.get("guide_area") or "").strip().lower()
    node_memory_type = str(node_payload.get("memory_type") or "").strip().lower()
    return bool((active_guide_area and node_guide_area == active_guide_area) or (active_memory_type and node_memory_type == active_memory_type))


def _select_route_candidate_for_destination(
    *,
    probe: dict[str, Any],
    branch: dict[str, Any],
    candidate_map: dict[str, dict[str, Any]],
    candidate_sources: dict[str, list[str]],
    destination: dict[str, Any],
    blackboard: dict[str, Any] | None = None,
    current_position: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
    if not candidate_map:
        return None, []
    current_node_id = str(branch.get("current_node_id") or "").strip() or None
    ranked_route_candidates: list[dict[str, Any]] = []
    for candidate_id, candidate in candidate_map.items():
        score, debug = _route_score_candidate(
            probe=probe,
            branch=branch,
            candidate=candidate,
            sources=list(candidate_sources.get(candidate_id) or []),
            destination=destination,
            blackboard=blackboard,
            current_position=current_position,
        )
        navigation_action, edge_type, travel_performed = _route_candidate_move_type(
            list(candidate_sources.get(candidate_id) or []),
            current_node_id=current_node_id,
            candidate_id=candidate_id,
        )
        ranked_route_candidates.append(
            {
                "score": score,
                "candidate_id": candidate_id,
                "candidate": dict(candidate),
                "debug": debug,
                "edge_type": edge_type,
                "travel_performed": bool(travel_performed and candidate_id != current_node_id),
                "navigation_action": navigation_action,
            }
        )
    ranked_route_candidates.sort(
        key=lambda item: (
            -float(item["score"]),
            -float((item.get("debug") or {}).get("destination_progress_gain") or 0.0),
            str(item["candidate_id"]),
        )
    )

    def _edge_priority(edge_type: str) -> int:
        return {"highway": 3, "link": 2, "local": 1, "none": 0}.get(str(edge_type or ""), 0)

    selected = ranked_route_candidates[0]
    for candidate in ranked_route_candidates[1:]:
        score_gap = abs(float(candidate["score"]) - float(selected["score"]))
        candidate_progress = float((candidate.get("debug") or {}).get("destination_progress_gain") or 0.0)
        selected_progress = float((selected.get("debug") or {}).get("destination_progress_gain") or 0.0)
        if (
            score_gap <= 0.05
            and candidate_progress + 1e-6 >= selected_progress
            and _edge_priority(str(candidate.get("edge_type") or "")) > _edge_priority(str(selected.get("edge_type") or ""))
        ):
            selected = candidate
    return selected, ranked_route_candidates


def _maybe_reorder_execution_destinations(
    *,
    probe: dict[str, Any],
    branch: dict[str, Any],
    semantic_destination_queue: list[dict[str, Any]],
    execution_destination_queue: list[dict[str, Any]],
    execution_index: int,
    candidate_map: dict[str, dict[str, Any]],
    candidate_sources: dict[str, list[str]],
    blackboard: dict[str, Any] | None = None,
    current_position: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], int, dict[str, Any] | None]:
    if not execution_destination_queue or execution_index >= len(execution_destination_queue):
        return execution_destination_queue, execution_index, None
    active_destination = dict(execution_destination_queue[execution_index] or {})
    active_selected, _ = _select_route_candidate_for_destination(
        probe=probe,
        branch=branch,
        candidate_map=candidate_map,
        candidate_sources=candidate_sources,
        destination=active_destination,
        blackboard=blackboard,
        current_position=current_position,
    )
    active_score = float((active_selected or {}).get("score") or 0.0)
    active_debug = dict((active_selected or {}).get("debug") or {})
    active_edge = str((active_selected or {}).get("edge_type") or "none")
    best_reorder: dict[str, Any] | None = None
    for alt_index in range(execution_index + 1, len(execution_destination_queue)):
        alternative_destination = dict(execution_destination_queue[alt_index] or {})
        alt_selected, _ = _select_route_candidate_for_destination(
            probe=probe,
            branch=branch,
            candidate_map=candidate_map,
            candidate_sources=candidate_sources,
            destination=alternative_destination,
            blackboard=blackboard,
            current_position=current_position,
        )
        if not alt_selected:
            continue
        alt_score = float(alt_selected.get("score") or 0.0)
        if alt_score < active_score + 0.12:
            continue
        alt_debug = dict(alt_selected.get("debug") or {})
        reasons: list[str] = []
        if str(alt_selected.get("edge_type") or "") == "highway" and active_edge != "highway":
            reasons.append("stronger_highway_access")
        if float(alt_debug.get("corroboration_yield") or 0.0) >= float(active_debug.get("corroboration_yield") or 0.0) + 0.10:
            reasons.append("corroboration_gain")
        if float(alt_debug.get("topology_efficiency") or 0.0) >= float(active_debug.get("topology_efficiency") or 0.0) + 0.15:
            reasons.append("topology_efficiency_gain")
        if not reasons:
            continue
        candidate_reorder = {
            "alt_index": alt_index,
            "alt_score": alt_score,
            "reasons": reasons,
            "destination": alternative_destination,
        }
        if best_reorder is None or float(candidate_reorder["alt_score"]) > float(best_reorder["alt_score"]):
            best_reorder = candidate_reorder
    if best_reorder is None:
        return execution_destination_queue, execution_index, None
    reordered_queue = [dict(item) for item in list(execution_destination_queue or [])]
    destination = reordered_queue.pop(int(best_reorder["alt_index"]))
    reordered_queue.insert(execution_index, destination)
    reorder_reason = "+".join(best_reorder["reasons"])
    reordered_destination = dict(reordered_queue[execution_index] or {})
    reorder_event = {
        "source_node_id": str(branch.get("current_node_id") or "").strip() or None,
        "target_node_id": None,
        "destination_id": str(reordered_destination.get("destination_id") or "") or None,
        "destination_key": _destination_lease_key(reordered_destination),
        "destination_label": str(reordered_destination.get("label") or "") or None,
        "edge_type": "none",
        "move_type": "reorder",
        "navigation_action": "reorder_execution_queue",
        "candidate_source": None,
        "travel_performed": False,
        "route_score": round(float(best_reorder["alt_score"]), 4),
        "route_reason": f"execution reorder toward {str(reordered_destination.get('label') or reordered_destination.get('destination_id') or 'destination')}",
        "route_yield": round(float(branch.get("route_yield") or 0.0), 4),
        "destination_reached": False,
        "lease_conflict": False,
        "region_pressure": 0.0,
        "yielded_match_count": 0,
        "family_attribution": _route_family_attribution(branch),
        "considered_highway": False,
        "destination_relevance": 0.0,
        "destination_progress_gain": 0.0,
        "corroboration_yield": 0.0,
        "topology_efficiency": 0.0,
        "highway_usefulness_memory": 0.5,
        "reorder_reason": reorder_reason,
        "reorder_from_label": str(active_destination.get("label") or active_destination.get("destination_id") or "destination"),
        "reorder_to_label": str(reordered_destination.get("label") or reordered_destination.get("destination_id") or "destination"),
        "destination_before": dict(active_destination),
        "destination_after": dict(reordered_destination),
        "semantic_order_index": _destination_semantic_index(semantic_destination_queue, reordered_destination),
        "execution_order_index": execution_index,
        "yielded_match_ids": [],
        "studied_node_ids": [],
        "hydrated_node_ids": [],
    }
    return reordered_queue, execution_index, reorder_event


def _candidate_destination_progress_gain(candidate_node: dict[str, Any], destination: dict[str, Any]) -> float:
    destination = dict(destination or {})
    candidate_node = dict(candidate_node or {})
    candidate_id = str(candidate_node.get("id") or "").strip()
    target_node_ids = {str(item).strip() for item in list(destination.get("target_node_ids") or []) if str(item).strip()}
    if candidate_id and candidate_id in target_node_ids:
        return 1.0
    bucket_key = str((candidate_node.get("bucket") or {}).get("key") or "").strip()
    target_bucket_keys = {str(item).strip() for item in list(destination.get("target_bucket_keys") or []) if str(item).strip()}
    if bucket_key and bucket_key in target_bucket_keys:
        return 0.9
    guide_area = str(destination.get("guide_area") or "").strip().lower()
    memory_type = str(destination.get("memory_type") or "").strip().lower()
    candidate_guide_area = str((candidate_node.get("provenance") or {}).get("guide_conceptual_area") or candidate_node.get("guide_area") or "").strip().lower()
    candidate_memory_type = str(candidate_node.get("memory_type") or "").strip().lower()
    if guide_area and memory_type and candidate_guide_area == guide_area and candidate_memory_type == memory_type:
        return 0.7
    if (guide_area and candidate_guide_area == guide_area) or (memory_type and candidate_memory_type == memory_type):
        return 0.5
    return 0.0


def _route_corroboration_yield(candidate_node: dict[str, Any], branch: dict[str, Any], destination: dict[str, Any]) -> float:
    candidate_node = dict(candidate_node or {})
    branch = dict(branch or {})
    destination = dict(destination or {})
    candidate_id = str(candidate_node.get("id") or "").strip()
    bucket_key = str((candidate_node.get("bucket") or {}).get("key") or "").strip()
    studied_node_ids = {str(item).strip() for item in list(branch.get("studied_node_ids") or []) if str(item).strip()}
    hydrated_node_ids = {str(item).strip() for item in list(branch.get("hydrated_node_ids") or []) if str(item).strip()}
    evidence_node_ids = {str(item).strip() for item in list(branch.get("evidence_node_ids") or []) if str(item).strip()}
    visited_bucket_keys = {str(item).strip() for item in list(branch.get("visited_bucket_keys") or []) if str(item).strip()}
    covered_slots = {str(item).strip().lower() for item in list(branch.get("covered_slots") or []) if str(item).strip()}
    goal_slot = _goal_to_slot(str(branch.get("goal") or ""))
    yield_score = 0.0
    if candidate_id and candidate_id not in studied_node_ids:
        yield_score += 0.22
    if candidate_id and candidate_id not in hydrated_node_ids:
        yield_score += 0.14
    if candidate_id and candidate_id not in evidence_node_ids:
        yield_score += 0.16
    if bucket_key and bucket_key not in visited_bucket_keys:
        yield_score += 0.1
    if goal_slot and goal_slot not in covered_slots:
        yield_score += 0.1
    if bool(candidate_node.get("is_document_anchor")) and str(destination.get("memory_type") or "").strip().lower() == "document_anchor":
        yield_score += 0.18
    if bool(candidate_node.get("is_summary")):
        yield_score += 0.06
    yield_score += min(0.12, max(0.0, float(candidate_node.get("memory_confidence") or 0.0) * 0.12))
    yield_score += min(0.12, max(0.0, float(candidate_node.get("evidence_confidence") or 0.0) * 0.12))
    return max(0.0, min(1.0, yield_score))


def _route_topology_efficiency(
    candidate_node: dict[str, Any],
    *,
    current_position: dict[str, Any] | None,
    source_label: str,
    destination_progress_gain: float,
) -> float:
    candidate_position = dict(candidate_node.get("final_position") or candidate_node.get("base_position") or {})
    distance_score = 0.5
    if current_position and candidate_position:
        position_distance = _position_distance(dict(current_position or {}), candidate_position)
        if position_distance is not None:
            distance_score = max(0.0, 1.0 - min(1.0, position_distance / 0.72))
    source_efficiency = {
        "highway": 0.92 if destination_progress_gain >= 0.5 else 0.68,
        "highway_neighbor": 0.78 if destination_progress_gain >= 0.5 else 0.62,
        "link": 0.74,
        "adjacent_bucket": 0.62,
        "nearby_radius": 0.56,
        "goal_support": 0.66,
        "identity_core": 0.64,
        "exact_temporal": 0.82,
        "document_anchor": 0.7,
        "candidate_pool": 0.5,
    }.get(source_label, 0.5)
    return max(0.0, min(1.0, 0.58 * distance_score + 0.42 * source_efficiency))


def _route_prior_float(value: Any, *, default: float | None = None, _depth: int = 0) -> float | None:
    if _depth > 3:
        return default
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    if isinstance(value, (int, float)):
        numeric = float(value)
        if numeric == numeric:
            return numeric
        return default
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return default
        try:
            numeric = float(stripped)
        except (TypeError, ValueError):
            return default
        return numeric if numeric == numeric else default
    if isinstance(value, dict):
        for key in ("weight", "score", "value", "confidence", "preference", "calibration_weight", "mean"):
            if key in value:
                numeric = _route_prior_float(value.get(key), default=None, _depth=_depth + 1)
                if numeric is not None:
                    return numeric
        child_values = [
            numeric
            for numeric in (
                _route_prior_float(child, default=None, _depth=_depth + 1)
                for child in value.values()
            )
            if numeric is not None
        ]
        if child_values:
            return max(child_values)
        return default
    if isinstance(value, (list, tuple, set)):
        child_values = [
            numeric
            for numeric in (
                _route_prior_float(child, default=None, _depth=_depth + 1)
                for child in value
            )
            if numeric is not None
        ]
        if child_values:
            return max(child_values)
        return default
    return default


def _route_preference_key_from_edge(edge: Any) -> str | None:
    normalized = str(edge or "").strip().lower().replace("-", "_")
    if not normalized:
        return None
    if "highway" in normalized:
        return "highway"
    if normalized in {"link", "semantic_link", "source_anchor", "document_anchor", "document_reference"}:
        return "link"
    if "link" in normalized or "anchor" in normalized or "reference" in normalized:
        return "link"
    if normalized in {"local", "nearby", "nearby_radius", "adjacent", "adjacent_bucket", "radius"}:
        return "local"
    if "local" in normalized or "nearby" in normalized or "adjacent" in normalized or "radius" in normalized:
        return "local"
    return None


def _route_preference_prior_map(branch: dict[str, Any]) -> dict[str, float]:
    raw_prior = dict(branch.get("route_preference_prior") or {})
    route_preference_prior: dict[str, float] = {}
    for key, value in raw_prior.items():
        normalized_key = str(key).strip().lower()
        if not normalized_key:
            continue
        numeric = _route_prior_float(value, default=None)
        if numeric is not None:
            route_preference_prior[normalized_key] = numeric

    preferred_edges = list(raw_prior.get("preferred_edges") or branch.get("ai_spatial_preferred_edges") or [])
    for index, edge in enumerate(preferred_edges[:8]):
        preference_key = _route_preference_key_from_edge(edge)
        if not preference_key:
            continue
        edge_weight = max(0.56, 0.86 - (float(index) * 0.06))
        route_preference_prior[preference_key] = max(
            float(route_preference_prior.get(preference_key) or 0.0),
            edge_weight,
        )
    return route_preference_prior


def _route_highway_usefulness_memory(branch: dict[str, Any], *, source_label: str) -> float:
    route_preference_prior = _route_preference_prior_map(branch)
    preference_key = "local"
    if source_label in {"highway", "highway_neighbor"}:
        preference_key = "highway"
    elif source_label == "link":
        preference_key = "link"
    value = route_preference_prior.get(preference_key)
    if value is None:
        return 0.5
    normalized = max(0.0, min(1.0, float(value)))
    if source_label == "highway":
        return max(0.5, normalized)
    if source_label == "highway_neighbor":
        return max(0.45, normalized)
    return normalized


def _route_score_candidate(
    *,
    probe: dict[str, Any],
    branch: dict[str, Any],
    candidate: dict[str, Any],
    sources: list[str],
    destination: dict[str, Any],
    blackboard: dict[str, Any] | None = None,
    current_position: dict[str, Any] | None = None,
) -> tuple[float, dict[str, Any]]:
    candidate_node = dict(candidate or {})
    destination = dict(destination or {})
    blackboard = dict(blackboard or {})
    routing_similarity = semantic_similarity(
        dict(probe.get("routing_semantic_scores") or {}),
        dict(candidate_node.get("routing_semantic_scores") or {}),
        ROUTING_FIELDS,
    )
    guide_area = str(destination.get("guide_area") or "").strip().lower()
    memory_type = str(destination.get("memory_type") or "").strip().lower()
    candidate_guide_area = str((candidate_node.get("provenance") or {}).get("guide_conceptual_area") or candidate_node.get("guide_area") or "").strip().lower()
    candidate_memory_type = str(candidate_node.get("memory_type") or "").strip().lower()
    bucket_key = str((candidate_node.get("bucket") or {}).get("key") or "").strip()
    target_bucket_keys = {str(item).strip() for item in list(destination.get("target_bucket_keys") or []) if str(item).strip()}
    target_node_ids = {str(item).strip() for item in list(destination.get("target_node_ids") or []) if str(item).strip()}
    direct_destination_hit = bool((bucket_key and bucket_key in target_bucket_keys) or (str(candidate_node.get("id") or "").strip() in target_node_ids))
    destination_relevance = (
        0.34 * max(0.0, min(1.0, routing_similarity))
        + (0.22 if guide_area and candidate_guide_area == guide_area else 0.0)
        + (0.18 if memory_type and candidate_memory_type == memory_type else 0.0)
        + (0.14 if bucket_key and bucket_key in target_bucket_keys else 0.0)
        + (0.12 if str(candidate_node.get("id") or "").strip() in target_node_ids else 0.0)
        + (0.08 if bool(candidate_node.get("is_document_anchor")) and memory_type == "document_anchor" else 0.0)
    )
    destination_relevance = max(0.0, min(1.0, destination_relevance))
    destination_progress_gain = _candidate_destination_progress_gain(candidate_node, destination)

    probe_color = str(destination.get("semantic_color_hint") or ((probe.get("semantic_color") or {}).get("hex")) or "").strip() or None
    candidate_color = (
        str((candidate_node.get("semantic_color") or {}).get("hex") or "").strip()
        or str((candidate_node.get("topology_color") or {}).get("hex") or "").strip()
        or None
    )
    source_label = _route_candidate_source_label(sources)
    corroboration_yield = _route_corroboration_yield(candidate_node, branch, destination)
    topology_efficiency = _route_topology_efficiency(
        candidate_node,
        current_position=current_position,
        source_label=source_label,
        destination_progress_gain=destination_progress_gain,
    )
    highway_usefulness_memory = _route_highway_usefulness_memory(branch, source_label=source_label)

    region_id = _route_region_id_for_candidate(candidate_node)
    pressure_map = _active_region_pressure(blackboard, branch_id=str(branch.get("branch_id") or ""))
    region_pressure = float(pressure_map.get(region_id) or 0.0)
    region_pressure_penalty = max(0.0, min(1.0, region_pressure / 3.0))

    destination_key = _destination_lease_key(destination)
    destination_leases = dict(blackboard.get("destination_leases") or {})
    leased_branch_id = str(destination_leases.get(str(destination_key or "")) or "")
    lease_conflict = bool(destination_key and leased_branch_id and leased_branch_id != str(branch.get("branch_id") or ""))
    lease_penalty = 1.0 if lease_conflict else 0.0

    total = (
        0.28 * destination_relevance
        + 0.16 * destination_progress_gain
        + 0.16 * corroboration_yield
        + 0.12 * topology_efficiency
        + 0.12 * highway_usefulness_memory
        - 0.08 * region_pressure_penalty
        - 0.08 * lease_penalty
    )
    total = max(0.0, min(1.0, total))
    return round(total, 4), {
        "routing_similarity": round(max(0.0, min(1.0, routing_similarity)), 4),
        "destination_relevance": round(destination_relevance, 4),
        "destination_progress_gain": round(destination_progress_gain, 4),
        "corroboration_yield": round(corroboration_yield, 4),
        "topology_efficiency": round(topology_efficiency, 4),
        "highway_usefulness_memory": round(highway_usefulness_memory, 4),
        "source_label": source_label,
        "direct_destination_hit": direct_destination_hit,
        "lease_conflict": lease_conflict,
        "region_pressure": round(region_pressure, 4),
        "region_id": region_id,
        "edge_bias": "highway" if source_label in {"highway", "highway_neighbor"} else ("link" if source_label == "link" else "local"),
    }


def _choose_backend_route_move(
    *,
    probe: dict[str, Any],
    branch: dict[str, Any],
    candidate_map: dict[str, dict[str, Any]],
    candidate_sources: dict[str, list[str]],
    blackboard: dict[str, Any] | None = None,
    current_position: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    active_destination = dict(branch.get("active_destination") or {})
    current_node_id = str(branch.get("current_node_id") or "").strip() or None
    if not candidate_map:
        route_decision = {
            "source_node_id": current_node_id,
            "target_node_id": None,
            "destination_id": str(active_destination.get("destination_id") or "") or None,
            "destination_key": _destination_lease_key(active_destination),
            "destination_label": str(active_destination.get("label") or "") or None,
            "edge_type": "none",
            "move_type": "study",
            "navigation_action": "expand_radius",
            "candidate_source": None,
            "travel_performed": False,
            "route_score": 0.0,
            "route_reason": "no_viable_route_candidates",
            "route_yield": round(float(branch.get("route_yield") or 0.0), 4),
            "destination_reached": False,
            "lease_conflict": False,
            "region_pressure": 0.0,
            "yielded_match_count": 0,
            "family_attribution": _route_family_attribution(branch),
            "considered_highway": False,
            "destination_relevance": 0.0,
            "destination_progress_gain": 0.0,
            "corroboration_yield": 0.0,
            "topology_efficiency": 0.0,
            "highway_usefulness_memory": 0.5,
        }
        return route_decision, None

    selected, ranked_route_candidates = _select_route_candidate_for_destination(
        probe=probe,
        branch=branch,
        candidate_map=candidate_map,
        candidate_sources=candidate_sources,
        destination=active_destination,
        blackboard=blackboard,
        current_position=current_position,
    )
    if not selected:
        selected = {
            "score": 0.0,
            "candidate_id": current_node_id,
            "candidate": {},
            "debug": {},
            "edge_type": "none",
            "travel_performed": False,
            "navigation_action": "expand_radius",
        }
    top_score = float(selected["score"])
    top_candidate_id = str(selected["candidate_id"])
    top_candidate = dict(selected["candidate"])
    debug = dict(selected["debug"] or {})
    source_label = str(debug.get("source_label") or "candidate_pool")
    navigation_action = str(selected["navigation_action"] or "")
    edge_type = str(selected["edge_type"] or "none")
    travel_performed = bool(selected["travel_performed"])
    highway_candidates = [
        dict(item)
        for item in ranked_route_candidates
        if str((item.get("debug") or {}).get("source_label") or "") in {"highway", "highway_neighbor"}
        or str((item.get("debug") or {}).get("edge_bias") or "") == "highway"
    ]
    considered_highway = bool(highway_candidates)
    selected_is_highway = bool(edge_type == "highway" and travel_performed)
    highway_not_used_reason: str | None = None
    best_highway = highway_candidates[0] if highway_candidates else None
    if considered_highway and not selected_is_highway:
        best_highway_debug = dict((best_highway or {}).get("debug") or {})
        best_highway_score = float((best_highway or {}).get("score") or 0.0)
        selected_progress = float(debug.get("destination_progress_gain") or 0.0)
        highway_progress = float(best_highway_debug.get("destination_progress_gain") or 0.0)
        if bool(best_highway_debug.get("lease_conflict")):
            highway_not_used_reason = "highway_lease_conflict"
        elif top_score >= best_highway_score + 0.05:
            highway_not_used_reason = f"better_{edge_type or 'local'}_route_score"
        elif selected_progress >= highway_progress + 0.02:
            highway_not_used_reason = "better_destination_progress_without_highway"
        elif best_highway_score <= 0.18:
            highway_not_used_reason = "highway_route_score_too_low"
        else:
            highway_not_used_reason = "highway_considered_not_selected"
    move_type = "travel" if travel_performed else ("hydrate" if navigation_action == "hydrate_current_node" else "study")
    route_reason = f"{source_label} route toward {str(active_destination.get('label') or branch.get('goal') or 'goal')}"
    if not travel_performed and top_score <= 0.18:
        move_type = "study"
        navigation_action = "expand_radius"
        edge_type = "none"
        route_reason = "route_score_too_low_for_travel"
    route_decision = {
        "source_node_id": current_node_id,
        "target_node_id": top_candidate_id if travel_performed or navigation_action == "hydrate_current_node" else None,
        "destination_id": str(active_destination.get("destination_id") or "") or None,
        "destination_key": _destination_lease_key(active_destination),
        "destination_label": str(active_destination.get("label") or "") or None,
        "edge_type": edge_type,
        "move_type": move_type,
        "navigation_action": navigation_action,
        "candidate_source": source_label,
        "travel_performed": bool(travel_performed and top_candidate_id != current_node_id),
        "route_score": round(top_score, 4),
        "route_reason": route_reason,
        "route_yield": round(float(branch.get("route_yield") or 0.0), 4),
        "destination_reached": False,
        "lease_conflict": bool(debug.get("lease_conflict")),
        "region_pressure": round(float(debug.get("region_pressure") or 0.0), 4),
        "yielded_match_count": 0,
        "family_attribution": _route_family_attribution(branch),
        "considered_highway": considered_highway,
        "highway_candidate_count": len(highway_candidates),
        "highway_not_used_reason": highway_not_used_reason,
        "best_highway_target_node_id": str((best_highway or {}).get("candidate_id") or "") or None,
        "best_highway_route_score": round(float((best_highway or {}).get("score") or 0.0), 4) if best_highway else None,
        "destination_relevance": round(float(debug.get("destination_relevance") or 0.0), 4),
        "destination_progress_gain": round(float(debug.get("destination_progress_gain") or 0.0), 4),
        "corroboration_yield": round(float(debug.get("corroboration_yield") or 0.0), 4),
        "topology_efficiency": round(float(debug.get("topology_efficiency") or 0.0), 4),
        "highway_usefulness_memory": round(float(debug.get("highway_usefulness_memory") or 0.5), 4),
    }
    selected_candidate = None if navigation_action == "expand_radius" and not travel_performed else dict(top_candidate)
    return route_decision, selected_candidate


def _region_descriptor_from_probe(
    probe: dict[str, Any],
    *,
    bucket_keys: list[str] | None = None,
    destination: dict[str, Any] | None = None,
) -> dict[str, Any]:
    destination = dict(destination or {})
    guide_area = str(destination.get("guide_area") or probe.get("expected_guide_area") or "").strip() or None
    memory_type = str(destination.get("memory_type") or probe.get("expected_memory_type") or "").strip() or None
    radial_expectation = str(destination.get("radial_expectation") or probe.get("radial_expectation") or "mid").strip() or "mid"
    label = str(destination.get("label") or guide_area or memory_type or probe.get("goal") or probe.get("label") or "region").strip()
    target_bucket_keys = [str(item) for item in list(destination.get("target_bucket_keys") or bucket_keys or probe.get("target_bucket_keys") or []) if str(item).strip()][:4]
    return {
        "region_id": f"{str(guide_area or 'unknown').lower()}::{str(memory_type or 'unknown').lower()}::{radial_expectation}",
        "label": label,
        "guide_area": guide_area,
        "memory_type": memory_type,
        "radial_expectation": radial_expectation,
        "semantic_color_hint": str(destination.get("semantic_color_hint") or ((probe.get('semantic_color') or {}).get('hex')) or "").strip() or None,
        "target_bucket_keys": target_bucket_keys,
    }


def _decision_source_from_error(error: str | None, *, fallback_prefix: str = "fallback") -> str:
    normalized = str(error or "").strip().lower()
    if not normalized:
        return f"{fallback_prefix}_provider_error"
    if "disabled" in normalized:
        return f"{fallback_prefix}_disabled"
    if "timeout" in normalized or "timed out" in normalized:
        return f"{fallback_prefix}_timeout"
    if "parse" in normalized or "schema" in normalized or "json" in normalized:
        return f"{fallback_prefix}_parse_error"
    return f"{fallback_prefix}_provider_error"


def _fallback_reason_from_error(error: str | None) -> str:
    normalized = str(error or "").strip().lower()
    if not normalized:
        return "empty"
    if "disabled" in normalized:
        return "disabled"
    if "timeout" in normalized or "timed out" in normalized:
        return "timeout"
    if "parse" in normalized or "schema" in normalized or "json" in normalized:
        return "parse_error"
    if "empty" in normalized:
        return "empty"
    return "provider_error"


def _controller_evidence_basis(branch: dict[str, Any], *, limit: int = 6) -> list[str]:
    basis: list[str] = []
    goal = str(branch.get("goal") or "").strip()
    if goal:
        basis.append(f"goal:{goal}")
    expected_field = str(branch.get("expected_answer_field") or "").strip()
    if expected_field:
        basis.append(f"field:{expected_field}")
    active_destination = dict(branch.get("active_destination") or {})
    destination_label = str(active_destination.get("label") or "").strip()
    if destination_label:
        basis.append(f"destination:{destination_label}")
    for slot in list(branch.get("covered_slots") or [])[:3]:
        slot_value = str(slot or "").strip()
        if slot_value:
            basis.append(f"slot:{slot_value}")
    for node_id in list(branch.get("evidence_node_ids") or [])[:3]:
        normalized = str(node_id or "").strip()
        if normalized:
            basis.append(f"evidence:{normalized}")
    return basis[:limit]


def _controller_escalation_defaults(
    *,
    action: str,
    branch: dict[str, Any],
    target_destination_id: str | None,
    reason: str | None,
) -> dict[str, Any]:
    requested_master_action = {
        "continue_current_route": "continue",
        "switch_destination": "reroute",
        "hold_branch": "hold",
        "stop_branch": "stop",
        "request_doc_hydration": "request_doc_hydration",
        "request_radius_widen": "request_radius_widen",
        "escalate_to_master": "reroute",
    }.get(action, "continue")
    active_destination = dict(branch.get("active_destination") or {})
    blocking_destination_id = str(target_destination_id or active_destination.get("destination_id") or "").strip() or None
    blocking_state = str(branch.get("route_state") or branch.get("status") or "").strip() or None
    escalation_needed = action in {
        "switch_destination",
        "hold_branch",
        "request_doc_hydration",
        "request_radius_widen",
        "escalate_to_master",
    }
    return {
        "escalation_needed": escalation_needed,
        "escalation_reason": _truncate_prompt_text(str(reason or action), 180) if escalation_needed else None,
        "requested_master_action": requested_master_action,
        "blocking_destination_id": blocking_destination_id,
        "blocking_state": blocking_state,
    }


_ALLOWED_CONTROLLER_ACTIONS = {
    "continue_current_route",
    "switch_destination",
    "hold_branch",
    "stop_branch",
    "request_radius_widen",
    "request_doc_hydration",
    "escalate_to_master",
}


def _normalize_controller_recommendation(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if not payload:
        return None
    raw_action = str(payload.get("action") or "").strip()
    legacy_map = {
        "reroute_next_destination": "switch_destination",
        "stop_route_exhausted": "stop_branch",
        "stop_goal_satisfied": "stop_branch",
        "request_more_context": "request_doc_hydration",
        "hold_position": "hold_branch",
    }
    action = legacy_map.get(raw_action, raw_action)
    if action not in _ALLOWED_CONTROLLER_ACTIONS:
        return None
    evidence_basis = [str(item).strip() for item in list(payload.get("evidence_basis") or []) if str(item).strip()]
    requested_actions = [str(item).strip() for item in list(payload.get("requested_actions") or []) if str(item).strip()]
    normalized = {
        "action": action,
        "reason": _truncate_prompt_text(str(payload.get("reason") or "").strip(), 180) or None,
        "confidence": max(0.0, min(1.0, float(payload.get("confidence") or 0.0))),
        "target_destination_id": str(payload.get("target_destination_id") or "").strip() or None,
        "requested_actions": requested_actions[:3],
        "decision_source": str(payload.get("decision_source") or "").strip() or None,
        "controller_kind": str(payload.get("controller_kind") or "").strip() or None,
        "turn_ms": round(float(payload.get("turn_ms") or 0.0), 2) if payload.get("turn_ms") is not None else None,
        "evidence_basis": evidence_basis[:6],
        "hold_reason": _truncate_prompt_text(str(payload.get("hold_reason") or "").strip(), 160) or None,
        "override_applied": bool(payload.get("override_applied")),
        "fallback_preview_action": str(payload.get("fallback_preview_action") or "").strip() or None,
        "fallback_reason": str(payload.get("fallback_reason") or "").strip() or None,
        "escalation_needed": bool(payload.get("escalation_needed")),
        "escalation_reason": _truncate_prompt_text(str(payload.get("escalation_reason") or "").strip(), 180) or None,
        "requested_master_action": str(payload.get("requested_master_action") or "").strip() or None,
        "blocking_destination_id": str(payload.get("blocking_destination_id") or "").strip() or None,
        "blocking_state": str(payload.get("blocking_state") or "").strip() or None,
    }
    if action != "hold_branch":
        normalized["hold_reason"] = None
    return normalized


def _branch_local_stop_recommendation(branch: dict[str, Any], *, query_class: str) -> str | None:
    status = str(branch.get("status") or "")
    if status == "satisfied":
        return "stop_branch"
    if status in {"stopped", "merged"}:
        return "stop_branch"
    route_yield = float(branch.get("route_yield") or 0.0)
    if route_yield <= 0.08 and len(list(branch.get("visited_bucket_keys") or [])) >= 2:
        return "stop_branch"
    if query_class == "document_lookup" and route_yield >= 0.56:
        return "request_doc_hydration"
    return None


def _controller_recommendation_fallback(
    branch: dict[str, Any],
    *,
    query_class: str,
) -> dict[str, Any]:
    status = str(branch.get("status") or "")
    active_destination = dict(branch.get("active_destination") or {})
    remaining_destinations = [dict(item) for item in list(branch.get("destination_queue") or [])]
    local_stop = _branch_local_stop_recommendation(branch, query_class=query_class)
    if status == "satisfied":
        action = "stop_branch"
        reason = str(branch.get("stop_reason") or "branch_goal_satisfied")
        confidence = 0.92
    elif local_stop == "stop_branch" and len(remaining_destinations) > 1:
        action = "switch_destination"
        reason = str(branch.get("stop_reason") or "current_destination_low_yield")
        confidence = 0.68
    elif local_stop == "stop_branch":
        action = "stop_branch"
        reason = str(branch.get("stop_reason") or "route_exhausted")
        confidence = 0.71
    elif status in {"stopped", "merged"}:
        action = "hold_branch"
        reason = str(branch.get("stop_reason") or status)
        confidence = 0.76
    elif query_class == "broad_summary" and not list(branch.get("covered_slots") or []):
        action = "request_radius_widen"
        reason = "broad_summary_needs_more_slot_coverage"
        confidence = 0.58
    else:
        action = "continue_current_route"
        reason = f"continue toward {str(active_destination.get('label') or branch.get('goal') or 'goal')}"
        confidence = 0.62
    requested_actions: list[str] = []
    if action == "request_doc_hydration" and str(branch.get("worker_kind") or "").startswith("document"):
        requested_actions.append("read_document_chunk")
    elif action == "request_doc_hydration":
        requested_actions.append("hydrate_nodes")
    elif action == "request_radius_widen":
        requested_actions.append("expand_radius")
    elif action == "switch_destination":
        requested_actions.append("inspect_adjacent_buckets")
    elif action == "continue_current_route" and list(branch.get("visited_bucket_keys") or []):
        requested_actions.append("inspect_bucket")
    escalation_defaults = _controller_escalation_defaults(
        action=action,
        branch=branch,
        target_destination_id=str(active_destination.get("destination_id") or "").strip() or None,
        reason=reason,
    )
    return _normalize_controller_recommendation({
        "action": action,
        "reason": _truncate_prompt_text(reason, 180),
        "confidence": confidence,
        "target_destination_id": str(active_destination.get("destination_id") or "") or None,
        "requested_actions": requested_actions[:3],
        "decision_source": "fallback_disabled",
        "fallback_reason": "disabled",
        "controller_kind": "fallback_branch_controller",
        "evidence_basis": _controller_evidence_basis(branch),
        "hold_reason": reason if action == "hold_branch" else None,
        **escalation_defaults,
    }) or {}


def _controller_timeout_seconds(*, retrieval_mode: str, query_class: str) -> float:
    if retrieval_mode == "flash":
        return 1.4
    if retrieval_mode == "balanced":
        return 2.4 if query_class in {"direct_fact", "relation_fact", "style_values"} else 3.0
    if retrieval_mode == "heavy":
        return 4.2
    return 5.0


def _should_use_ai_branch_controller(
    *,
    retrieval_mode: str,
    query_class: str,
    branch: dict[str, Any],
) -> bool:
    if not llm_enabled():
        return False
    mode = str(retrieval_mode or "balanced").strip().lower()
    planner_family = str(branch.get("planner_family") or "").strip().lower()
    if query_class == "broad_summary":
        return planner_family == "ai"
    if mode in {"heavy", "forensic"}:
        return True
    if query_class == "document_lookup":
        return True
    if planner_family == "ai":
        return True
    if mode in {"flash", "balanced"}:
        return False
    if len(list(branch.get("destination_queue") or [])) > 1:
        return True
    if float(branch.get("route_yield") or 0.0) <= 0.18 and len(list(branch.get("visited_bucket_keys") or [])) >= 1:
        return True
    if bool(branch.get("corroboration_needs")) and len(list(branch.get("covered_slots") or [])) < len(list(branch.get("corroboration_needs") or [])):
        return True
    return False


def llm_branch_controller(
    *,
    query_text: str,
    query_class: str,
    retrieval_mode: str,
    branch: dict[str, Any],
    blackboard: dict[str, Any],
) -> tuple[dict[str, Any] | None, str | None]:
    if not llm_enabled():
        return None, "llm_disabled"
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": ["action", "reason", "confidence"],
        "properties": {
            "action": {"type": "string", "enum": sorted(_ALLOWED_CONTROLLER_ACTIONS)},
            "reason": {"type": "string"},
            "confidence": {"type": "number", "minimum": 0.0, "maximum": 1.0},
            "target_destination_id": {"type": ["string", "null"]},
            "requested_actions": {"type": "array", "items": {"type": "string"}, "maxItems": 3},
            "evidence_basis": {"type": "array", "items": {"type": "string"}, "maxItems": 6},
            "hold_reason": {"type": ["string", "null"]},
            "escalation_needed": {"type": "boolean"},
            "escalation_reason": {"type": ["string", "null"]},
            "requested_master_action": {
                "type": ["string", "null"],
                "enum": [None, "continue", "reroute", "hold", "stop", "request_doc_hydration", "request_radius_widen"],
            },
            "blocking_destination_id": {"type": ["string", "null"]},
            "blocking_state": {"type": ["string", "null"]},
        },
    }
    branch_summary = {
        "branch_id": str(branch.get("branch_id") or ""),
        "planner_family": str(branch.get("planner_family") or "heuristic"),
        "goal": str(branch.get("goal") or ""),
        "expected_answer_field": str(branch.get("expected_answer_field") or "") or None,
        "route_state": str(branch.get("route_state") or ""),
        "route_yield": round(float(branch.get("route_yield") or 0.0), 4),
        "active_destination": dict(branch.get("active_destination") or {}),
        "destination_queue": [dict(item) for item in list(branch.get("destination_queue") or [])[:3]],
        "covered_slots": list(branch.get("covered_slots") or [])[:6],
        "corroboration_needs": list(branch.get("corroboration_needs") or [])[:6],
        "local_stop_recommendation": str(branch.get("local_stop_recommendation") or "") or None,
        "status": str(branch.get("status") or ""),
        "evidence_node_ids": list(branch.get("evidence_node_ids") or [])[:6],
        "visited_bucket_keys": list(branch.get("visited_bucket_keys") or [])[:6],
    }
    blackboard_summary = _summarize_blackboard_for_master(blackboard, max_items_per_slot=2)
    payload, error = structured_json(
        model=retrieval_model(),
        system_prompt=(
            "You are an AGVM branch controller. Judge only the local branch state. "
            "You do not answer the query and you do not compute path geometry. "
            "Choose one bounded local recommendation: continue, switch destination, hold, stop, request radius widen, request document hydration, or escalate to master. "
            "Base your decision on route yield, destination progress, corroboration coverage, contradiction risk, region pressure, and evidence density."
        ),
        user_prompt=(
            f"Query: {query_text}\n"
            f"Query class: {query_class}\n"
            f"Retrieval mode: {retrieval_mode}\n"
            f"Branch: {branch_summary}\n"
            f"Blackboard summary: {blackboard_summary}\n"
            "Return only the best bounded local recommendation for this branch."
        ),
        schema_name="agvm_branch_controller",
        schema=schema,
        timeout=_controller_timeout_seconds(retrieval_mode=retrieval_mode, query_class=query_class),
        role="retrieval",
    )
    if error or not payload:
        return None, error or "llm_empty"
    return _normalize_controller_recommendation(payload), None


def _branch_controller_recommendation(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str,
    branch: dict[str, Any],
    blackboard: dict[str, Any],
) -> dict[str, Any]:
    fallback = _controller_recommendation_fallback(branch, query_class=query_class)
    fallback_action = str(fallback.get("action") or "")
    if not _should_use_ai_branch_controller(retrieval_mode=retrieval_mode, query_class=query_class, branch=branch):
        return {
            **fallback,
            "decision_source": "fallback_disabled",
            "controller_kind": "fallback_branch_controller",
            "fallback_preview_action": fallback_action or None,
            "override_applied": False,
        }
    started_at = time.perf_counter()
    llm_recommendation, llm_error = llm_branch_controller(
        query_text=query_text,
        query_class=query_class,
        retrieval_mode=retrieval_mode,
        branch=branch,
        blackboard=blackboard,
    )
    turn_ms = round((time.perf_counter() - started_at) * 1000.0, 2)
    if llm_recommendation:
        action = str(llm_recommendation.get("action") or "")
        escalation_defaults = _controller_escalation_defaults(
            action=action,
            branch=branch,
            target_destination_id=str(llm_recommendation.get("target_destination_id") or "").strip() or None,
            reason=str(llm_recommendation.get("reason") or ""),
        )
        return {
            **llm_recommendation,
            "decision_source": "llm",
            "fallback_reason": None,
            "controller_kind": "llm_branch_controller",
            "turn_ms": turn_ms,
            "evidence_basis": list(llm_recommendation.get("evidence_basis") or _controller_evidence_basis(branch)),
            "fallback_preview_action": fallback_action or None,
            "override_applied": bool(action and fallback_action and action != fallback_action),
            "escalation_needed": bool(llm_recommendation.get("escalation_needed", escalation_defaults["escalation_needed"])),
            "escalation_reason": llm_recommendation.get("escalation_reason") or escalation_defaults["escalation_reason"],
            "requested_master_action": llm_recommendation.get("requested_master_action") or escalation_defaults["requested_master_action"],
            "blocking_destination_id": llm_recommendation.get("blocking_destination_id") or escalation_defaults["blocking_destination_id"],
            "blocking_state": llm_recommendation.get("blocking_state") or escalation_defaults["blocking_state"],
        }
    return {
        **fallback,
        "decision_source": _decision_source_from_error(llm_error, fallback_prefix="fallback"),
        "fallback_reason": _fallback_reason_from_error(llm_error),
        "controller_kind": "fallback_branch_controller",
        "turn_ms": turn_ms,
        "evidence_basis": list(fallback.get("evidence_basis") or _controller_evidence_basis(branch)),
        "fallback_preview_action": fallback_action or None,
        "override_applied": False,
    }


def _apply_controller_recommendation(branch: dict[str, Any], recommendation: dict[str, Any] | None) -> dict[str, Any]:
    updated = dict(branch)
    normalized_recommendation = _normalize_controller_recommendation(dict(recommendation or {}))
    if not normalized_recommendation:
        updated["controller_recommendation"] = None
        return updated
    _ensure_branch_destination_resolution(updated, round_index=int(updated.get("last_round_index") or 0))
    action = str(normalized_recommendation.get("action") or "")
    updated["controller_recommendation"] = normalized_recommendation
    updated["controller_kind"] = str(normalized_recommendation.get("controller_kind") or "") or None
    updated["controller_confidence"] = float(normalized_recommendation.get("confidence") or 0.0)
    updated["controller_reason"] = str(normalized_recommendation.get("reason") or "") or None
    updated["controller_turn_ms"] = normalized_recommendation.get("turn_ms")
    updated["controller_evidence_basis"] = list(normalized_recommendation.get("evidence_basis") or [])
    updated["controller_decision_source"] = str(normalized_recommendation.get("decision_source") or "") or None
    updated["controller_fallback_reason"] = str(normalized_recommendation.get("fallback_reason") or "") or None
    updated["controller_escalation_needed"] = bool(normalized_recommendation.get("escalation_needed"))
    updated["controller_escalation_reason"] = str(normalized_recommendation.get("escalation_reason") or "") or None
    updated["controller_requested_master_action"] = str(normalized_recommendation.get("requested_master_action") or "") or None
    updated["controller_blocking_destination_id"] = str(normalized_recommendation.get("blocking_destination_id") or "") or None
    updated["controller_blocking_state"] = str(normalized_recommendation.get("blocking_state") or "") or None
    round_index = int(updated.get("last_round_index") or 0)
    current_destination = dict(updated.get("active_destination") or {})
    if action == "switch_destination":
        remaining = [dict(item) for item in list(updated.get("destination_queue") or [])]
        if len(remaining) > 1:
            current = remaining.pop(0)
            remaining.append(current)
            updated["destination_queue"] = remaining
            updated["active_destination"] = remaining[0]
            updated["route_state"] = "reroute_pending"
            updated["lifecycle_stage"] = "reroute_pending"
            _set_destination_resolution_state(
                updated,
                current_destination,
                state="superseded_by_stronger_branch",
                state_reason="controller_switch_destination",
                round_index=round_index,
            )
            _set_destination_resolution_state(
                updated,
                updated.get("active_destination"),
                state="active",
                state_reason="controller_switch_destination",
                round_index=round_index,
            )
    elif action == "stop_branch":
        route_state = "goal_satisfied" if str(updated.get("status") or "") == "satisfied" else "route_exhausted"
        lifecycle_stage = "satisfied" if route_state == "goal_satisfied" else "stopped"
        updated["route_state"] = route_state
        updated["lifecycle_stage"] = lifecycle_stage
        updated["local_stop_recommendation"] = "stop_branch"
        if str(updated.get("status") or "") == "active":
            updated["status"] = "satisfied" if route_state == "goal_satisfied" else "stopped"
            if route_state == "route_exhausted" and not str(updated.get("stop_reason") or "").strip():
                updated["stop_reason"] = "controller_stop_branch"
        if route_state == "goal_satisfied":
            _set_destination_resolution_state(
                updated,
                current_destination,
                state="reached",
                state_reason="controller_goal_satisfied",
                round_index=round_index,
            )
            _bulk_mark_open_destinations(
                updated,
                state="superseded_by_stronger_branch",
                state_reason="controller_goal_satisfied",
                round_index=round_index,
            )
        else:
            _bulk_mark_open_destinations(
                updated,
                state="route_exhausted",
                state_reason=str(updated.get("stop_reason") or "controller_stop_branch"),
                round_index=round_index,
            )
    elif action == "hold_branch":
        updated["route_state"] = "evidence_holding"
        updated["lifecycle_stage"] = "evidence_holding"
        _set_destination_resolution_state(
            updated,
            current_destination,
            state="active",
            state_reason="controller_hold_branch",
            round_index=round_index,
        )
    elif action == "request_radius_widen":
        updated["search_radius"] = round(min(0.42, float(updated.get("search_radius") or 0.24) + 0.02), 4)
        updated["route_state"] = "routing"
        updated["lifecycle_stage"] = "routing"
        _set_destination_resolution_state(
            updated,
            current_destination,
            state="active",
            state_reason="controller_request_radius_widen",
            round_index=round_index,
        )
    elif action == "request_doc_hydration":
        updated["route_state"] = "routing"
        updated["lifecycle_stage"] = "routing"
        _set_destination_resolution_state(
            updated,
            current_destination,
            state="active",
            state_reason="controller_request_doc_hydration",
            round_index=round_index,
        )
    elif action == "continue_current_route":
        updated["route_state"] = "routing"
        updated["lifecycle_stage"] = "routing"
        _set_destination_resolution_state(
            updated,
            current_destination,
            state="active",
            state_reason="controller_continue_current_route",
            round_index=round_index,
        )
    return updated


