_ALLOWED_NAVIGATION_ACTIONS = {
    "inspect_bucket",
    "inspect_adjacent_buckets",
    "expand_radius",
    "follow_highway",
    "follow_local_link",
    "hydrate_node",
    "hydrate_nodes",
    "read_document_anchor",
    "read_document_chunk",
    "terminate_branch",
}


def _normalize_navigation_actions(actions: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
    normalized: list[dict[str, Any]] = []
    for action in list(actions or []):
        action_type = str(action.get("action") or "").strip()
        if action_type not in _ALLOWED_NAVIGATION_ACTIONS:
            continue
        payload = dict(action.get("payload") or {})
        normalized.append(
            {
                "action": action_type,
                "payload": payload,
                "confidence": max(0.0, min(1.0, float(action.get("confidence") or 0.0))),
                "rationale": str(action.get("rationale") or "").strip(),
            }
        )
    return normalized[:4]


def _master_state_snapshot(
    *,
    retrieval_mode: str,
    query_class: str,
    branches: list[dict[str, Any]],
    decision_history: list[dict[str, Any]],
    llm_scout_state: dict[str, Any] | None = None,
    answer_surface_state: str = "not_ready",
    closure_state: str = "open",
    final_closure_ready: bool = False,
    final_closure_blockers: list[dict[str, Any]] | None = None,
    unresolved_destination_count: int = 0,
    last_decision_source: str | None = None,
    last_fallback_reason: str | None = None,
) -> dict[str, Any]:
    active_worker_ids = [str(branch.get("worker_id") or branch.get("branch_id") or "") for branch in branches if str(branch.get("status") or "") == "active"]
    active_branch_ids = [str(branch.get("branch_id") or "") for branch in branches if str(branch.get("status") or "") == "active"]
    family_counts = {
        "heuristic": sum(1 for branch in branches if _record_has_family(branch, "heuristic")),
        "ai": sum(1 for branch in branches if _record_has_family(branch, "ai")),
    }
    active_destinations = [
        {
            "branch_id": str(branch.get("branch_id") or ""),
            "planner_family": str(branch.get("planner_family") or "heuristic"),
            "origin_families": _families_for_record(branch),
            "dual_origin": bool(branch.get("dual_origin")),
            "destination_id": str((branch.get("active_destination") or {}).get("destination_id") or ""),
            "label": str((branch.get("active_destination") or {}).get("label") or ""),
            "route_state": str(branch.get("route_state") or ""),
            "lifecycle_stage": str(branch.get("lifecycle_stage") or ""),
        }
        for branch in branches
        if str(branch.get("status") or "") == "active"
    ]
    return {
        "status": "running" if active_worker_ids else "settled",
        "retrieval_mode": retrieval_mode,
        "query_class": query_class,
        "answer_surface_state": answer_surface_state,
        "closure_state": closure_state,
        "final_closure_ready": bool(final_closure_ready),
        "final_closure_blockers": [dict(item) for item in list(final_closure_blockers or [])[:12]],
        "unresolved_destination_count": int(unresolved_destination_count or 0),
        "active_worker_ids": active_worker_ids,
        "active_branch_ids": active_branch_ids,
        "active_worker_count": len(active_worker_ids),
        "active_destination_count": len([item for item in active_destinations if item.get("destination_id")]),
        "active_destinations": active_destinations[:8],
        "planner_family_counts": family_counts,
        "decision_history": list(decision_history[-12:]),
        "last_decision_source": last_decision_source,
        "last_fallback_reason": last_fallback_reason,
        "llm_scout_status": str((llm_scout_state or {}).get("status") or ""),
    }


def _worker_registry(branches: list[dict[str, Any]], llm_scout_state: dict[str, Any] | None = None) -> dict[str, Any]:
    registry: dict[str, Any] = {}
    for branch in branches:
        worker_id = str(branch.get("worker_id") or branch.get("branch_id") or "")
        if not worker_id:
            continue
        registry[worker_id] = {
            "worker_id": worker_id,
            "worker_kind": str(branch.get("worker_kind") or "heuristic_navigation"),
            "planner_family": str(branch.get("planner_family") or "heuristic"),
            "merge_outcome": str(branch.get("merge_outcome") or "") or None,
            "dual_origin": bool(branch.get("dual_origin")),
            "origin_families": _families_for_record(branch),
            "merge_score": round(float(branch.get("merge_score") or 0.0), 4) if branch.get("merge_score") is not None else None,
            "family_branch_id": str(branch.get("family_branch_id") or ""),
            "family_plan_id": str(branch.get("family_plan_id") or ""),
            "controller_kind": str(branch.get("controller_kind") or "") or None,
            "controller_decision_source": str(branch.get("controller_decision_source") or "") or None,
            "status": str(branch.get("status") or ""),
            "goal": str(branch.get("goal") or ""),
            "probe_ids": list(branch.get("probe_ids") or []),
            "expected_answer_field": str(branch.get("expected_answer_field") or "") or None,
            "active_destination_id": str((branch.get("active_destination") or {}).get("destination_id") or "") or None,
            "route_state": str(branch.get("route_state") or ""),
            "lifecycle_stage": str(branch.get("lifecycle_stage") or ""),
        }
    if llm_scout_state:
        registry["llm_planner_scout"] = {
            "worker_id": "llm_planner_scout",
            "worker_kind": "llm_planner_scout",
            "status": str(llm_scout_state.get("status") or "disabled"),
            "goal": "planner_probe_injection",
            "probe_ids": [],
        }
    return registry


