def _truncate_prompt_text(value: Any, limit: int = 220) -> str:
    text = " ".join(str(value or "").split())
    if len(text) <= limit:
        return text
    return f"{text[: max(0, limit - 3)].rstrip()}..."


def _keywords_for_text(value: str, *, limit: int = 12) -> list[str]:
    folded = _fold_text(value)
    tokens: list[str] = []
    for token in folded.split():
        if len(token) < 3:
            continue
        if token in {"come", "sono", "della", "delle", "dello", "that", "with", "from", "this", "quale"}:
            continue
        if token not in tokens:
            tokens.append(token)
        if len(tokens) >= limit:
            break
    return tokens


def _extract_claims_from_sections(section_snapshots: list[dict[str, Any]], *, limit: int = 8) -> list[str]:
    claims: list[str] = []
    for section in section_snapshots:
        title = str(section.get("title") or section.get("key") or "section").strip()
        for item in list(section.get("items") or []):
            text = str(item or "").strip()
            if not text:
                continue
            claims.append(f"{title}: {text}")
            if len(claims) >= limit:
                return claims
    return claims


