def _warm_terms_from_text(value: Any, *, limit: int = 80) -> list[str]:
    folded = _fold_text(str(value or ""))
    if not folded:
        return []
    terms: list[str] = []
    tokens = [token for token in folded.split() if len(token) >= 3 and token not in _WARM_CONTEXT_STOPWORDS]
    for token in tokens:
        if token not in terms:
            terms.append(token)
        if len(terms) >= limit:
            return terms
    for span in (2, 3):
        for index in range(0, max(0, len(tokens) - span + 1)):
            phrase = " ".join(tokens[index : index + span])
            if phrase and phrase not in terms:
                terms.append(phrase)
            if len(terms) >= limit:
                return terms
    return terms


def _warm_entities_from_text(value: Any, *, limit: int = 24) -> list[str]:
    text = str(value or "")
    entities: list[str] = []
    question_leads = {"Che", "Cosa", "Come", "Dove", "Quando", "Quale", "Quali", "E", "Nel", "Nella", "The", "What", "Where", "When", "How"}
    for candidate in re.findall(r"\b[A-Z][A-Za-z0-9]*(?:\s+[A-Z][A-Za-z0-9]*)+\b", text):
        parts = candidate.split()
        while parts and parts[0] in question_leads:
            parts = parts[1:]
        normalized = " ".join(parts).strip()
        if len(normalized.split()) < 2:
            continue
        folded = _fold_text(normalized)
        if folded and folded not in entities:
            entities.append(folded)
        if len(entities) >= limit:
            break
    if len(entities) < limit:
        for match in re.finditer(r"\b[A-Z][A-Za-z0-9]{2,}\b", text):
            token = str(match.group(0) or "").strip()
            if len(token) < 4 or token in question_leads:
                continue
            folded = _fold_text(token)
            if not folded or folded in _WARM_CONTEXT_STOPWORDS:
                continue
            if folded not in entities:
                entities.append(folded)
            if len(entities) >= limit:
                break
    return entities


def _warm_packet_text_values(packet: dict[str, Any]) -> list[str]:
    values: list[str] = []
    signature = dict(packet.get("topic_signature") or {})
    for key in ("query_text", "keywords", "slots", "aspects", "covered_goals", "branch_goals", "follow_up_queries", "claims", "topic_terms", "entities"):
        value = signature.get(key)
        if isinstance(value, list):
            values.extend(str(item) for item in value)
        elif value:
            values.append(str(value))
    values.extend(str(item) for item in list(packet.get("claims") or []))
    for item in list(packet.get("supporting_snippets") or []):
        if isinstance(item, dict):
            values.extend(str(item.get(key) or "") for key in ("text", "kind", "node_id"))
    for item in list(packet.get("follow_up_candidates") or []):
        if isinstance(item, dict):
            values.extend(str(item.get(key) or "") for key in ("query", "reason", "kind"))
    for branch in list(packet.get("branch_memory") or []):
        if not isinstance(branch, dict):
            continue
        values.extend(str(branch.get(key) or "") for key in ("goal", "expected_answer_field", "route_state", "planner_family"))
        destination = _canonical_active_destination(branch.get("active_destination"))
        if destination:
            values.extend(str(destination.get(key) or "") for key in ("destination_id", "destination_key", "label", "guide_area", "memory_type"))
    return [value for value in values if value.strip()]


def _dedupe_limited(values: list[str], *, limit: int) -> list[str]:
    deduped: list[str] = []
    for value in values:
        normalized = str(value or "").strip()
        if normalized and normalized not in deduped:
            deduped.append(normalized)
        if len(deduped) >= limit:
            break
    return deduped


def _query_has_followup_shape(query_text: str) -> bool:
    folded = _fold_text(query_text)
    padded = f" {folded} "
    tokens = folded.split()
    if not tokens:
        return False
    markers = (
        " e ",
        " poi ",
        " invece ",
        " anche ",
        " colleg",
        " si collega ",
        " che ruolo ",
        " quale ruolo ",
        " nel ",
        " nel 19",
        " nel 20",
        " e nel ",
        " and ",
        " also ",
        " what about ",
        " how does ",
        "questa cosa",
        "questa risposta",
        "questo punto",
        "cosa supporta",
        "cosa supportano",
        "documenti supportano",
        "fonti supportano",
        "supporting documents",
    )
    pronouns = (" tu ", " tuo ", " tua ", " tuoi ", " tue ", " ti ", " hai ", " sei ", " she ", " he ", " her ", " his ", " they ")
    return any(marker in padded for marker in markers) or (len(tokens) <= 9 and any(pronoun in padded for pronoun in pronouns))


def _query_is_source_trace_followup(query_text: str) -> bool:
    folded = _fold_text(query_text)
    padded = f" {folded} "
    deictic_markers = (
        " questa cosa ",
        " questa risposta ",
        " questa informazione ",
        " questo punto ",
        " questo fatto ",
        " cio ",
        " quanto detto ",
        " la risposta ",
        " this answer ",
        " this claim ",
        " that claim ",
        " this thing ",
    )
    source_markers = (
        "documenti",
        "documento",
        "fonti",
        "fonte",
        "supporta",
        "supportano",
        "supportano questa",
        "evidence",
        "source",
        "sources",
        "supporting documents",
        "source trace",
    )
    return any(marker in padded for marker in deictic_markers) and any(marker in folded for marker in source_markers)


def _query_has_implicit_memory_subject(query_text: str) -> bool:
    folded = _fold_text(query_text)
    padded = f" {folded} "
    patterns = (
        " tu ",
        " te ",
        " ti ",
        " tuo ",
        " tua ",
        " tuoi ",
        " tue ",
        " sei ",
        " fai ",
        " vivi ",
        " lavori ",
        " comunichi ",
        " ragioni ",
        " hai fatto",
        " hai lavorato",
        " hai costruito",
        " cosa hai",
        " cosa fai",
        " cosa lavori",
    )
    return any(pattern in padded for pattern in patterns)


def _continuity_score_details(query_text: str, packet: dict[str, Any]) -> dict[str, Any]:
    query_signature = _build_topic_signature(query_text)
    warm_signature = dict(packet.get("topic_signature") or {})
    query_keywords = set(query_signature.get("keywords") or [])
    warm_keywords = set(warm_signature.get("keywords") or [])
    query_slots = set(query_signature.get("slots") or [])
    warm_slots = set(warm_signature.get("slots") or []) | set(packet.get("covered_slots") or [])
    query_aspects = set(query_signature.get("aspects") or [])
    warm_aspects = set(warm_signature.get("aspects") or [])
    query_terms = set(_warm_terms_from_text(query_text, limit=48))
    warm_terms = set(warm_signature.get("topic_terms") or packet.get("topic_terms") or [])
    if not warm_terms:
        for value in _warm_packet_text_values(packet):
            warm_terms.update(_warm_terms_from_text(value, limit=40))
    query_entities = set(_warm_entities_from_text(query_text))
    warm_entities = set(warm_signature.get("entities") or packet.get("topic_entities") or [])
    if not warm_entities:
        for value in _warm_packet_text_values(packet):
            warm_entities.update(_warm_entities_from_text(value))
    follow_up_terms: set[str] = set()
    for item in list(packet.get("follow_up_candidates") or []):
        if isinstance(item, dict):
            follow_up_terms.update(_warm_terms_from_text(item.get("query") or item.get("reason") or "", limit=24))
    branch_goals = {str(item.get("goal") or "").strip() for item in list(packet.get("branch_memory") or []) if isinstance(item, dict) and str(item.get("goal") or "").strip()}
    branch_slots = {_goal_to_slot(goal) for goal in branch_goals}
    matched_keywords = sorted(query_keywords & warm_keywords)
    matched_terms = sorted(query_terms & warm_terms)
    matched_entities = sorted(
        entity
        for entity in query_entities
        if entity in warm_entities or any(entity in warm_entity or warm_entity in entity for warm_entity in warm_entities)
    )
    matched_slots = sorted(query_slots & (warm_slots | branch_slots))
    matched_aspects = sorted(query_aspects & (warm_aspects | branch_goals))
    followup_overlap = sorted(query_terms & follow_up_terms)
    keyword_overlap = len(matched_keywords) / max(1, len(query_keywords | warm_keywords))
    term_overlap = len(matched_terms) / max(1, len(query_terms))
    entity_overlap = len(matched_entities) / max(1, len(query_entities)) if query_entities else 0.0
    slot_overlap = len(matched_slots) / max(1, len(query_slots)) if query_slots else 0.0
    aspect_overlap = len(matched_aspects) / max(1, len(query_aspects)) if query_aspects else 0.0
    followup_overlap_ratio = len(followup_overlap) / max(1, len(query_terms)) if follow_up_terms else 0.0
    query_class = str(query_signature.get("query_class") or "")
    warm_class = str(warm_signature.get("query_class") or "")
    compatible_class = bool(query_class and (query_class == warm_class or warm_class == "broad_summary" or query_class in {"direct_fact", "relation_fact", "style_values"}))
    class_bonus = 0.08 if compatible_class else 0.0
    followup_bonus = 0.2 if _query_has_followup_shape(query_text) else 0.0
    source_trace_followup = _query_is_source_trace_followup(query_text)
    source_trace_followup_bonus = 0.18 if source_trace_followup and (packet.get("read_set") or packet.get("evidence_refs") or packet.get("supporting_snippets")) else 0.0
    personal_slots = {"identity", "place", "work", "relationships", "style", "values", "history"}
    implicit_memory_subject = (
        not query_entities
        and bool(query_slots & personal_slots)
        and bool((warm_slots | branch_slots) & personal_slots)
        and _query_has_implicit_memory_subject(query_text)
        and query_class in {"direct_fact", "relation_fact", "style_values"}
    )
    implicit_subject_bonus = 0.14 if implicit_memory_subject else 0.0
    confidence_bonus = min(0.08, max(0.0, float(packet.get("confidence") or 0.0)) * 0.08)
    contradiction_penalty = 0.16 if list(packet.get("contradictions") or []) else 0.0
    divergence_flags: list[str] = []
    support_slots = warm_slots | branch_slots
    core_query_slots = set(query_slots) - {"history", "documents", "document_source", "temporal"}
    work_support_terms = {"lavoro", "work", "ruolo", "role", "progetto", "project", "projects"}
    founding_support_terms = {
        "fondato",
        "fondata",
        "fondatore",
        "founder",
        "founded",
        "company",
        "companies",
        "societa",
        "azienda",
    }

    def warm_has_org_or_project_signal() -> bool:
        if any(_looks_like_org_or_project_label(entity) for entity in warm_entities):
            return True
        if any(term in warm_terms for term in _GENERIC_ORG_LABEL_MARKERS):
            return True
        if "work" in support_slots or "projects" in support_slots:
            return bool(warm_entities)
        return False

    def warm_supports_core_slot(slot: str) -> bool:
        normalized_slot = str(slot or "").strip()
        if not normalized_slot:
            return True
        if normalized_slot in support_slots:
            return True
        if normalized_slot == "relation_detail":
            return "relationships" in support_slots or bool({"padre", "father", "papa", "dad", "monumento", "monument", "family", "famiglia"} & warm_terms)
        if normalized_slot == "relationships":
            return bool({"relationships", "partner", "relation_detail"} & support_slots) or bool({"padre", "father", "papa", "dad", "partner", "relazione", "famiglia", "monumento", "monument"} & warm_terms)
        if normalized_slot == "work":
            return bool({"work", "projects"} & support_slots) or bool(work_support_terms & warm_terms) or warm_has_org_or_project_signal()
        if normalized_slot in {"style", "values"}:
            return (
                normalized_slot in support_slots
                or (
                    bool(implicit_memory_subject or followup_bonus)
                    and bool((support_slots | branch_slots) & personal_slots)
                )
            )
        if normalized_slot == "work_detail":
            return "work" in support_slots or bool(work_support_terms & warm_terms) or warm_has_org_or_project_signal()
        if normalized_slot == "company_founding":
            return bool({"projects", "work"} & support_slots) and bool(founding_support_terms & warm_terms or warm_has_org_or_project_signal())
        return False

    unsupported_core_slots = sorted(slot for slot in core_query_slots if not warm_supports_core_slot(slot))
    if unsupported_core_slots:
        divergence_flags.append("required_slot_shift_without_warm_support")
    document_topic_signal_present = bool(matched_terms or matched_entities or followup_overlap or source_trace_followup)
    if query_class == "document_lookup" and warm_class != "document_lookup":
        if source_trace_followup:
            pass
        elif document_topic_signal_present:
            divergence_flags.append("document_lookup_intent_shift_requires_cold_validation")
        else:
            divergence_flags.append("document_lookup_without_topic_overlap")
    if query_entities and warm_entities and not matched_entities and not matched_terms:
        divergence_flags.append("new_named_entity_without_warm_overlap")
    document_lookup_divergence = any(flag.startswith("document_lookup_") for flag in divergence_flags)
    hard_slot_divergence = "required_slot_shift_without_warm_support" in divergence_flags
    divergence_penalty = 0.42 if document_lookup_divergence or hard_slot_divergence else (0.12 if divergence_flags else 0.0)
    score = (
        keyword_overlap * 0.12
        + term_overlap * 0.2
        + entity_overlap * 0.18
        + slot_overlap * 0.15
        + aspect_overlap * 0.12
        + followup_overlap_ratio * 0.12
        + class_bonus
        + followup_bonus
        + source_trace_followup_bonus
        + implicit_subject_bonus
        + confidence_bonus
        - contradiction_penalty
        - divergence_penalty
    )
    score = round(max(0.0, min(1.0, score)), 4)
    if document_lookup_divergence or hard_slot_divergence:
        deterministic_state = "low_continuity"
        warm_layer = "cold"
    elif score >= 0.62:
        deterministic_state = "high_continuity"
        warm_layer = "hot"
    elif score >= 0.24 or (followup_bonus and not divergence_flags and float(packet.get("confidence") or 0.0) >= 0.5):
        deterministic_state = "medium_continuity"
        warm_layer = "warm"
    else:
        deterministic_state = "low_continuity"
        warm_layer = "cold"
    reason_parts = []
    if matched_entities:
        reason_parts.append(f"entities={','.join(matched_entities[:3])}")
    if matched_slots:
        reason_parts.append(f"slots={','.join(matched_slots[:4])}")
    if matched_terms:
        reason_parts.append(f"terms={','.join(matched_terms[:4])}")
    if followup_bonus:
        reason_parts.append("followup_shape")
    if source_trace_followup:
        reason_parts.append("source_trace_followup")
    if implicit_memory_subject:
        reason_parts.append("implicit_memory_subject")
    if divergence_flags:
        reason_parts.append(f"divergence={','.join(divergence_flags)}")
    return {
        "continuity_score": score,
        "deterministic_state": deterministic_state,
        "warm_layer": warm_layer,
        "gate_reason": "; ".join(reason_parts) or "no_material_overlap",
        "matched_keywords": matched_keywords[:8],
        "matched_topic_terms": matched_terms[:10],
        "matched_entities": matched_entities[:8],
        "matched_slots": matched_slots[:8],
        "matched_aspects": matched_aspects[:8],
        "matched_follow_up_terms": followup_overlap[:8],
        "implicit_memory_subject": bool(implicit_memory_subject),
        "source_trace_followup": bool(source_trace_followup),
        "query_terms": sorted(query_terms)[:16],
        "warm_topic_terms": sorted(warm_terms)[:20],
        "query_entities": sorted(query_entities)[:8],
        "warm_entities": sorted(warm_entities)[:12],
        "followup_shape": bool(followup_bonus),
        "divergence_flags": divergence_flags,
    }


def _build_topic_signature(
    query_text: str,
    *,
    shared_evidence: dict[str, Any] | None = None,
    section_snapshots: list[dict[str, Any]] | None = None,
    branches: list[dict[str, Any]] | None = None,
    follow_up_candidates: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    claims = _extract_claims_from_sections(list(section_snapshots or []), limit=6)
    branch_goals = [str(branch.get("goal") or "") for branch in list(branches or []) if str(branch.get("goal") or "").strip()][:8]
    follow_up_queries = [str(item.get("query") or "").strip() for item in list(follow_up_candidates or []) if str(item.get("query") or "").strip()][:5]
    signature_text = "\n".join([str(query_text or ""), *claims, *branch_goals, *follow_up_queries])
    return {
        "query_text": str(query_text or "").strip(),
        "keywords": _keywords_for_text(query_text),
        "query_class": _query_class(query_text),
        "slots": _required_slots_for_query(query_text),
        "aspects": detect_query_aspects(query_text),
        "covered_goals": list((shared_evidence or {}).get("covered_goals") or []),
        "branch_goals": branch_goals,
        "follow_up_queries": follow_up_queries,
        "claims": claims,
        "topic_terms": _warm_terms_from_text(signature_text, limit=48),
        "entities": _warm_entities_from_text(signature_text, limit=16),
    }


def _build_hot_context_summary(
    partial_matches: list[dict[str, Any]],
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
    evidence_reservoir_summary: dict[str, Any] | None = None,
) -> dict[str, Any]:
    family_contribution_summary = dict(shared_evidence_snapshot.get("family_contribution_summary") or {})
    return {
        "node_count": len([str(match.get("node_id") or "") for match in partial_matches[:8] if str(match.get("node_id") or "")]),
        "snippet_count": len(_build_stream_evidence_snippets(partial_matches[:6])),
        "section_count": len(section_snapshots),
        "covered_goals": list(shared_evidence_snapshot.get("covered_goals") or [])[:6],
        "unresolved_slots": list(shared_evidence_snapshot.get("unresolved_slots") or [])[:6],
        "confidence": round(float(shared_evidence_snapshot.get("confidence") or 0.0), 4),
        "reservoir_entry_count": int((evidence_reservoir_summary or {}).get("entry_count") or 0),
        "reservoir_document_count": int((evidence_reservoir_summary or {}).get("document_count") or 0),
        "raw_text_coverage_ratio": round(float((evidence_reservoir_summary or {}).get("raw_text_coverage_ratio") or 0.0), 4),
        "family_contribution_summary": family_contribution_summary,
    }


def _surface_value_present(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, dict):
        return any(_surface_value_present(item) for item in value.values())
    if isinstance(value, list):
        return any(_surface_value_present(item) for item in value)
    return True


def _surface_value_score(value: Any) -> float:
    if value is None:
        return 0.0
    if isinstance(value, str):
        return float(len(value.strip()))
    if isinstance(value, dict):
        score = 0.0
        for key, item in value.items():
            if not _surface_value_present(item):
                continue
            score += 4.0
            score += _surface_value_score(item)
            if str(key).strip():
                score += 1.0
        return score
    if isinstance(value, list):
        return float(len(value) * 6) + sum(_surface_value_score(item) for item in value)
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    try:
        return abs(float(value))
    except Exception:
        return 1.0


def _clone_surface_value(value: Any) -> Any:
    if isinstance(value, dict):
        return {key: _clone_surface_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_clone_surface_value(item) for item in value]
    return value


def _merge_surface_accumulator(
    accumulator: dict[str, Any],
    *,
    hot_context_summary: dict[str, Any] | None = None,
    context_dossier_partial: str | None = None,
    evidence_snippets: list[dict[str, Any]] | None = None,
    master_state: dict[str, Any] | None = None,
    planner_runtime: dict[str, Any] | None = None,
) -> None:
    updates = {
        "hot_context_summary": hot_context_summary,
        "context_dossier_partial": context_dossier_partial,
        "evidence_snippets": evidence_snippets,
        "master_state": master_state,
        "planner_runtime": planner_runtime,
    }
    for key, candidate in updates.items():
        if not _surface_value_present(candidate):
            continue
        current = accumulator.get(key)
        if not _surface_value_present(current) or _surface_value_score(candidate) >= _surface_value_score(current):
            accumulator[key] = _clone_surface_value(candidate)


def _canonical_active_destination(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    payload = dict(value)
    meaningful_text = any(
        str(payload.get(key) or "").strip()
        for key in ("destination_id", "destination_key", "label", "guide_area", "memory_type")
    )
    meaningful_targets = any(list(payload.get(key) or []) for key in ("target_bucket_keys", "target_node_ids"))
    return payload if (meaningful_text or meaningful_targets) else None


def build_landing_metadata(probes: list[dict[str, Any]], branches: list[dict[str, Any]]) -> list[dict[str, Any]]:
    branch_by_probe_id: dict[str, dict[str, Any]] = {}
    branch_by_id: dict[str, dict[str, Any]] = {}
    for raw_branch in list(branches or []):
        if not isinstance(raw_branch, dict):
            continue
        branch = dict(raw_branch)
        branch_id = str(branch.get("branch_id") or "").strip()
        if branch_id:
            branch_by_id[branch_id] = branch
        for raw_probe_id in list(branch.get("probe_ids") or []):
            probe_id = str(raw_probe_id or "").strip()
            if probe_id and probe_id not in branch_by_probe_id:
                branch_by_probe_id[probe_id] = branch

    records: list[dict[str, Any]] = []
    for index, raw_probe in enumerate(list(probes or [])):
        if not isinstance(raw_probe, dict):
            continue
        probe = dict(raw_probe)
        probe_id = str(probe.get("probe_id") or f"probe_{index + 1}").strip()
        branch = branch_by_probe_id.get(probe_id)
        if branch is None and probe_id:
            branch = branch_by_id.get(f"branch_{probe_id}")
        branch = dict(branch or {})
        branch_id = str(branch.get("branch_id") or "").strip()
        active_destination = _canonical_active_destination(branch.get("active_destination"))
        raw_destination_queue = list(branch.get("destination_queue") or probe.get("destination_queue") or [])
        destination_queue = [
            destination
            for destination in (_canonical_active_destination(item) for item in raw_destination_queue)
            if destination
        ][:6]
        if active_destination is None and destination_queue:
            active_destination = dict(destination_queue[0])
        origin_families = [
            str(item).strip().lower()
            for item in list(branch.get("origin_families") or probe.get("origin_families") or [])
            if str(item).strip()
        ]
        planner_family = str(branch.get("planner_family") or probe.get("planner_family") or "").strip().lower()
        if planner_family and planner_family not in origin_families:
            origin_families.append(planner_family)
        target_bucket_keys = [
            str(item).strip()
            for item in list(probe.get("target_bucket_keys") or (active_destination or {}).get("target_bucket_keys") or [])
            if str(item).strip()
        ]
        landing_position = probe.get("landing_position")
        if not isinstance(landing_position, dict):
            landing_position = probe.get("base_position") if isinstance(probe.get("base_position"), dict) else {}
        records.append(
            {
                "landing_id": branch_id or probe_id,
                "probe_id": probe_id,
                "branch_id": branch_id,
                "family_branch_id": str(branch.get("family_branch_id") or probe.get("family_branch_id") or "").strip(),
                "worker_id": str(branch.get("worker_id") or branch_id or "").strip(),
                "planner_family": planner_family or None,
                "origin_families": origin_families,
                "dual_origin": bool(branch.get("dual_origin") or probe.get("dual_origin")),
                "label": str(probe.get("label") or "").strip(),
                "query_text": str(probe.get("query_text") or "").strip(),
                "goal": str(probe.get("goal") or branch.get("goal") or "").strip(),
                "query_class": str(probe.get("query_class") or "").strip(),
                "answer_hypothesis": str(probe.get("answer_hypothesis") or branch.get("answer_hypothesis") or "").strip(),
                "expected_answer_field": str(probe.get("expected_answer_field") or branch.get("expected_answer_field") or "").strip(),
                "expected_guide_area": probe.get("expected_guide_area"),
                "expected_memory_type": probe.get("expected_memory_type"),
                "expected_radial_band": probe.get("radial_expectation"),
                "search_radius": probe.get("search_radius") or branch.get("search_radius"),
                "target_bucket_keys": target_bucket_keys,
                "crowding_penalty": probe.get("crowding_penalty"),
                "landing_position": dict(landing_position or {}),
                "spatial_snap": dict(branch.get("spatial_snap") or probe.get("spatial_snap") or {}),
                "ai_spatial_path_id": str(branch.get("ai_spatial_path_id") or probe.get("ai_spatial_path_id") or "").strip() or None,
                "ai_spatial_landing_region_ref": str(branch.get("ai_spatial_landing_region_ref") or probe.get("ai_spatial_landing_region_ref") or "").strip() or None,
                "ai_spatial_landing_coordinate": dict(branch.get("ai_spatial_landing_coordinate") or probe.get("ai_spatial_landing_coordinate") or {}) or None,
                "ai_spatial_bridge_targets": [
                    str(item).strip()
                    for item in list(branch.get("ai_spatial_bridge_targets") or probe.get("ai_spatial_bridge_targets") or [])
                    if str(item).strip()
                ][:6],
                "ai_spatial_preferred_edges": [
                    str(item).strip()
                    for item in list(branch.get("ai_spatial_preferred_edges") or probe.get("ai_spatial_preferred_edges") or [])
                    if str(item).strip()
                ][:8],
                "heuristic_provisional": bool(branch.get("heuristic_provisional") or probe.get("heuristic_provisional")),
                "provisional_until_ai_spatial": bool(branch.get("provisional_until_ai_spatial") or probe.get("provisional_until_ai_spatial")),
                "active_destination": active_destination,
                "destination_queue": destination_queue,
                "status": branch.get("status"),
                "stop_reason": branch.get("stop_reason"),
                "route_state": branch.get("route_state") or branch.get("lifecycle_stage"),
                "lifecycle_stage": branch.get("lifecycle_stage"),
                "destination_reached": bool(branch.get("destination_reached")),
                "studied_node_count": len(list(branch.get("studied_node_ids") or branch.get("visited_node_ids") or [])),
                "hydrated_node_count": len(list(branch.get("hydrated_node_ids") or [])),
                "evidence_node_count": len(list(branch.get("evidence_node_ids") or [])),
                "route_trace_count": len(list(branch.get("route_trace") or [])),
            }
        )
    return records


SEARCH_MAP_2D_TRUTH_SCHEMA_VERSION = "agvm.search_map_2d_truth.v1"


def _search_map_string_list(value: Any) -> list[str]:
    return [str(item).strip() for item in list(value or []) if str(item).strip()]


def _search_map_dict(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, dict) else {}


def _search_map_branch_id_for_landing(record: dict[str, Any]) -> str:
    branch = _search_map_dict(record.get("branch"))
    return str(
        record.get("branch_id")
        or branch.get("branch_id")
        or record.get("family_branch_id")
        or record.get("worker_id")
        or ""
    ).strip()


def _search_map_landing_id(record: dict[str, Any], fallback: str) -> str:
    branch_id = _search_map_branch_id_for_landing(record)
    return str(
        record.get("landing_id")
        or branch_id
        or record.get("probe_id")
        or fallback
    ).strip()


def _search_map_spatial_fields(record: dict[str, Any]) -> dict[str, Any]:
    snap = _search_map_dict(record.get("spatial_snap"))
    return {
        "spatial_snap": snap,
        "has_spatial_snap": bool(snap),
        "ai_spatial_path_id": str(record.get("ai_spatial_path_id") or snap.get("path_id") or "").strip() or None,
        "ai_spatial_landing_region_ref": str(record.get("ai_spatial_landing_region_ref") or snap.get("ai_landing_region_ref") or "").strip() or None,
        "ai_spatial_landing_coordinate": _search_map_dict(record.get("ai_spatial_landing_coordinate") or snap.get("ai_landing_coordinate")) or None,
        "ai_spatial_bridge_targets": _search_map_string_list(record.get("ai_spatial_bridge_targets")),
        "ai_spatial_preferred_edges": _search_map_string_list(record.get("ai_spatial_preferred_edges")),
        "heuristic_provisional": bool(record.get("heuristic_provisional")),
        "provisional_until_ai_spatial": bool(record.get("provisional_until_ai_spatial")),
    }


def _search_map_landing_rows(
    *,
    probes: list[dict[str, Any]],
    branches: list[dict[str, Any]],
    landing_metadata: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, str]]:
    branch_ids = {
        str(branch.get("branch_id") or "").strip()
        for branch in branches
        if isinstance(branch, dict) and str(branch.get("branch_id") or "").strip()
    }
    branch_id_by_probe: dict[str, str] = {}
    for branch in branches:
        if not isinstance(branch, dict):
            continue
        branch_id = str(branch.get("branch_id") or "").strip()
        if not branch_id:
            continue
        for probe_id in _search_map_string_list(branch.get("probe_ids")):
            branch_id_by_probe.setdefault(probe_id, branch_id)

    rows: list[dict[str, Any]] = []
    landing_id_by_branch: dict[str, str] = {}
    for index, raw_record in enumerate(list(landing_metadata or [])):
        if not isinstance(raw_record, dict):
            continue
        record = dict(raw_record)
        branch_id = _search_map_branch_id_for_landing(record)
        if not branch_id:
            branch_id = branch_id_by_probe.get(str(record.get("probe_id") or "").strip(), "")
        landing_id = _search_map_landing_id(record, branch_id or f"probe:{index + 1}")
        if branch_id:
            landing_id_by_branch[branch_id] = landing_id
        rows.append(
            {
                "landing_id": landing_id,
                "branch_id": branch_id or None,
                "probe_id": str(record.get("probe_id") or "").strip() or None,
                "route_id": f"route::{branch_id or landing_id}",
                "origin_role": "branch_local_scout_origin",
                "independent_scout_origin": True,
                "planner_family": str(record.get("planner_family") or "").strip() or None,
                "origin_families": _search_map_string_list(record.get("origin_families")),
                "dual_origin": bool(record.get("dual_origin")),
                "goal": str(record.get("goal") or record.get("query_text") or "").strip(),
                "expected_answer_field": str(record.get("expected_answer_field") or "").strip() or None,
                "expected_guide_area": record.get("expected_guide_area"),
                "target_bucket_keys": _search_map_string_list(record.get("target_bucket_keys")),
                "landing_position": _search_map_dict(record.get("landing_position")),
                "search_radius": record.get("search_radius"),
                "status": record.get("status"),
                "route_state": record.get("route_state") or record.get("lifecycle_stage"),
                **_search_map_spatial_fields(record),
            }
        )

    for index, branch in enumerate(branches):
        if not isinstance(branch, dict):
            continue
        branch_id = str(branch.get("branch_id") or "").strip()
        if not branch_id or branch_id in landing_id_by_branch:
            continue
        landing_id = branch_id
        landing_id_by_branch[branch_id] = landing_id
        rows.append(
            {
                "landing_id": landing_id,
                "branch_id": branch_id,
                "probe_id": (_search_map_string_list(branch.get("probe_ids")) or [None])[0],
                "route_id": f"route::{branch_id}",
                "origin_role": "branch_local_scout_origin",
                "independent_scout_origin": True,
                "planner_family": str(branch.get("planner_family") or "").strip() or None,
                "origin_families": _search_map_string_list(branch.get("origin_families")),
                "dual_origin": bool(branch.get("dual_origin")),
                "goal": str(branch.get("goal") or "").strip(),
                "expected_answer_field": str(branch.get("expected_answer_field") or "").strip() or None,
                "expected_guide_area": None,
                "target_bucket_keys": [],
                "landing_position": _search_map_dict(branch.get("start_region")),
                "search_radius": branch.get("search_radius"),
                "status": branch.get("status"),
                "route_state": branch.get("route_state") or branch.get("lifecycle_stage"),
                **_search_map_spatial_fields(branch),
            }
        )

    for probe_index, probe in enumerate(probes):
        if not isinstance(probe, dict):
            continue
        probe_id = str(probe.get("probe_id") or "").strip()
        branch_id = branch_id_by_probe.get(probe_id, "")
        if branch_id and branch_id in landing_id_by_branch:
            continue
        if not branch_id and probe_id in {str(row.get("probe_id") or "") for row in rows}:
            continue
        landing_id = branch_id or probe_id or f"probe:{probe_index + 1}"
        if branch_id:
            landing_id_by_branch[branch_id] = landing_id
        rows.append(
            {
                "landing_id": landing_id,
                "branch_id": branch_id or None,
                "probe_id": probe_id or None,
                "route_id": f"route::{branch_id or landing_id}",
                "origin_role": "branch_local_scout_origin",
                "independent_scout_origin": True,
                "planner_family": str(probe.get("planner_family") or "").strip() or None,
                "origin_families": _search_map_string_list(probe.get("origin_families")),
                "dual_origin": bool(probe.get("dual_origin")),
                "goal": str(probe.get("goal") or probe.get("query_text") or "").strip(),
                "expected_answer_field": str(probe.get("expected_answer_field") or "").strip() or None,
                "expected_guide_area": probe.get("expected_guide_area"),
                "target_bucket_keys": _search_map_string_list(probe.get("target_bucket_keys")),
                "landing_position": _search_map_dict(probe.get("landing_position") or probe.get("base_position")),
                "search_radius": probe.get("search_radius"),
                "status": "planned",
                "route_state": "planned",
                **_search_map_spatial_fields(probe),
            }
        )

    return rows, landing_id_by_branch


def _search_map_destination_rows(branch: dict[str, Any]) -> list[dict[str, Any]]:
    destinations: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw_destination in (
        [branch.get("active_destination")]
        + list(branch.get("execution_destination_queue") or [])
        + list(branch.get("semantic_destination_queue") or [])
        + list(branch.get("destination_queue") or [])
    ):
        destination = _search_map_dict(raw_destination)
        if not destination:
            continue
        destination_id = str(
            destination.get("destination_id")
            or destination.get("destination_key")
            or destination.get("label")
            or destination.get("guide_area")
            or destination.get("memory_type")
            or ""
        ).strip()
        bucket_keys = _search_map_string_list(destination.get("target_bucket_keys"))
        key = f"{destination_id}|{','.join(bucket_keys)}"
        if not destination_id and not bucket_keys:
            continue
        if key in seen:
            continue
        seen.add(key)
        destinations.append(
            {
                "destination_id": destination_id or None,
                "label": str(destination.get("label") or destination_id or "").strip() or None,
                "guide_area": str(destination.get("guide_area") or "").strip() or None,
                "memory_type": str(destination.get("memory_type") or "").strip() or None,
                "target_bucket_keys": bucket_keys,
                "target_node_ids": _search_map_string_list(destination.get("target_node_ids")),
            }
        )
    return destinations[:8]


def build_search_map_2d_truth(
    *,
    search_id: str | None = None,
    thread_id: str | None = None,
    probes: list[dict[str, Any]] | None = None,
    branches: list[dict[str, Any]] | None = None,
    landing_metadata: list[dict[str, Any]] | None = None,
    route_truth_summary: dict[str, Any] | None = None,
    path_corridors: dict[str, Any] | None = None,
    phase: str = "result",
) -> dict[str, Any]:
    """Build a UI/MCP-safe 2D map contract from backend route truth only."""

    probe_rows = [dict(item) for item in list(probes or []) if isinstance(item, dict)]
    branch_rows = [dict(item) for item in list(branches or []) if isinstance(item, dict)]
    landing_rows, landing_id_by_branch = _search_map_landing_rows(
        probes=probe_rows,
        branches=branch_rows,
        landing_metadata=[dict(item) for item in list(landing_metadata or []) if isinstance(item, dict)],
    )
    route_plans: list[dict[str, Any]] = []
    route_steps: list[dict[str, Any]] = []
    route_segments: list[dict[str, Any]] = []
    intermediate_nodes: list[dict[str, Any]] = []
    terminal_states: list[dict[str, Any]] = []
    cross_landing_bridges: list[dict[str, Any]] = []
    path_lifecycle_rows = [
        {
            "path_id": str(path.get("path_id") or ""),
            "route_kind": str(path.get("route_kind") or "landing_origin_corridor"),
            "origin_landing_id": str(path.get("origin_landing_id") or path.get("from_landing_id") or ""),
            "target_landing_id": str(path.get("target_landing_id") or path.get("to_landing_id") or "") or None,
            "lifecycle_state": str(path.get("lifecycle_state") or ((path.get("lifecycle") or {}).get("state") if isinstance(path.get("lifecycle"), dict) else "") or "pending"),
            "lifecycle_state_reason": str(path.get("lifecycle_state_reason") or ((path.get("lifecycle") or {}).get("state_reason") if isinstance(path.get("lifecycle"), dict) else "") or ""),
            "changed_context_package": bool(path.get("changed_context_package") or ((path.get("package_impact") or {}).get("changed_context_package") if isinstance(path.get("package_impact"), dict) else False)),
            "runtime_branch_ids": [
                str(item).strip()
                for item in list(path.get("runtime_branch_ids") or [])
                if str(item).strip()
            ],
        }
        for path in list((path_corridors or {}).get("paths") or [])
        if isinstance(path, dict)
    ]
    path_lifecycle_by_branch: dict[str, list[dict[str, Any]]] = {}
    for row in path_lifecycle_rows:
        for branch_id in list(row.get("runtime_branch_ids") or []):
            path_lifecycle_by_branch.setdefault(str(branch_id), []).append(row)
    bridge_fields = {"cross_landing_bridge", "target_landing_id", "bridge_goal", "bridge_target_landing_id"}

    for branch in branch_rows:
        branch_id = str(branch.get("branch_id") or "").strip()
        if not branch_id:
            continue
        landing_id = landing_id_by_branch.get(branch_id, branch_id)
        route_id = f"route::{branch_id}"
        destinations = _search_map_destination_rows(branch)
        route_trace = [dict(item) for item in list(branch.get("route_trace") or []) if isinstance(item, dict)]
        bound_path_lifecycle = [dict(item) for item in path_lifecycle_by_branch.get(branch_id, [])]
        route_plans.append(
            {
                "route_id": route_id,
                "branch_id": branch_id,
                "landing_id": landing_id,
                "route_label": f"{branch_id} / {landing_id}",
                "goal": str(branch.get("goal") or "").strip(),
                "planner_family": str(branch.get("planner_family") or "").strip() or None,
                "origin_families": _search_map_string_list(branch.get("origin_families")),
                "destination_count": len(destinations),
                "intended_destinations": destinations,
                "route_trace_count": len(route_trace),
                "travel_hop_count": sum(1 for item in route_trace if bool(item.get("travel_performed"))),
                "route_state": branch.get("route_state") or branch.get("lifecycle_stage"),
                "status": branch.get("status"),
                "path_lifecycle": bound_path_lifecycle,
                "path_lifecycle_state": str(bound_path_lifecycle[0].get("lifecycle_state") or "") if bound_path_lifecycle else None,
                "path_changed_context_package": any(bool(item.get("changed_context_package")) for item in bound_path_lifecycle),
                **_search_map_spatial_fields(branch),
            }
        )
        for step_index, entry in enumerate(route_trace):
            route_step_id = f"{branch_id}:route_step:{step_index + 1}"
            edge_type = str(entry.get("edge_type") or "local").strip().lower()
            if edge_type not in {"highway", "link", "local"}:
                edge_type = "local"
            travel_performed = bool(entry.get("travel_performed") or str(entry.get("move_type") or "") == "travel")
            target_landing_id = str(entry.get("target_landing_id") or entry.get("bridge_target_landing_id") or "").strip()
            explicit_bridge = bool(entry.get("cross_landing_bridge")) or bool(target_landing_id and any(field in entry for field in bridge_fields))
            step_payload = {
                "route_step_id": route_step_id,
                "route_id": route_id,
                "branch_id": branch_id,
                "landing_id": landing_id,
                "sequence_index": step_index + 1,
                "trace_driven": True,
                "movement_kind": "travel" if travel_performed else "trace_marker",
                "travel_performed": travel_performed,
                "move_type": entry.get("move_type"),
                "edge_type": edge_type,
                "family_attribution": entry.get("family_attribution") or branch.get("planner_family"),
                "from_node_id": entry.get("from_node_id") or entry.get("source_node_id"),
                "to_node_id": entry.get("to_node_id") or entry.get("target_node_id"),
                "from_bucket_key": entry.get("from_bucket_key"),
                "to_bucket_key": entry.get("to_bucket_key"),
                "considered_highway": bool(entry.get("considered_highway") or edge_type == "highway"),
                "destination_reached": bool(entry.get("destination_reached")),
                "route_score": entry.get("route_score"),
                "route_reason": entry.get("route_reason"),
                "target_landing_id": target_landing_id or None,
                "cross_landing_bridge": explicit_bridge,
                **_search_map_spatial_fields(branch),
            }
            route_steps.append(step_payload)
            if travel_performed:
                route_segments.append(
                    {
                        "segment_id": f"{branch_id}:segment:{step_index + 1}",
                        "route_step_id": route_step_id,
                        "route_id": route_id,
                        "branch_id": branch_id,
                        "landing_id": landing_id,
                        "segment_kind": "travel",
                        "edge_type": edge_type,
                        "from_node_id": step_payload["from_node_id"],
                        "to_node_id": step_payload["to_node_id"],
                        "from_bucket_key": step_payload["from_bucket_key"],
                        "to_bucket_key": step_payload["to_bucket_key"],
                        "branch_local": not explicit_bridge,
                        "cross_landing_bridge": explicit_bridge,
                        "target_landing_id": target_landing_id or None,
                        "spatial_snap": dict(step_payload.get("spatial_snap") or {}),
                        "ai_spatial_path_id": step_payload.get("ai_spatial_path_id"),
                    }
                )
            if explicit_bridge:
                cross_landing_bridges.append(
                    {
                        "bridge_id": f"{branch_id}:bridge:{step_index + 1}",
                        "route_step_id": route_step_id,
                        "route_id": route_id,
                        "source_branch_id": branch_id,
                        "source_landing_id": landing_id,
                        "target_landing_id": target_landing_id or None,
                        "bridge_goal": str(entry.get("bridge_goal") or entry.get("route_reason") or "").strip() or None,
                    }
                )
        node_sources = [
            ("candidate", branch.get("candidate_node_ids")),
            ("studied", branch.get("studied_node_ids")),
            ("hydrated", branch.get("hydrated_node_ids")),
            ("promoted", branch.get("evidence_node_ids")),
            ("reservoir", branch.get("reservoir_only_node_ids")),
        ]
        for role, node_ids in node_sources:
            for node_id in _search_map_string_list(node_ids):
                intermediate_nodes.append(
                    {
                        "node_id": node_id,
                        "node_role": role,
                        "branch_id": branch_id,
                        "landing_id": landing_id,
                        "route_id": route_id,
                        "source": "backend_branch_state",
                    }
                )
        terminal_states.append(
            {
                "branch_id": branch_id,
                "landing_id": landing_id,
                "route_id": route_id,
                "status": branch.get("status"),
                "route_state": branch.get("route_state") or branch.get("lifecycle_stage"),
                "stop_reason": branch.get("stop_reason"),
                "destination_reached": bool(branch.get("destination_reached")),
                "path_lifecycle_state": str(bound_path_lifecycle[0].get("lifecycle_state") or "") if bound_path_lifecycle else None,
                "path_changed_context_package": any(bool(item.get("changed_context_package")) for item in bound_path_lifecycle),
                **_search_map_spatial_fields(branch),
            }
        )

    route_summary = dict(route_truth_summary or {})
    travel_event_count = sum(1 for item in route_steps if bool(item.get("travel_performed")))
    metrics = {
        "landing_count": len(landing_rows),
        "branch_count": len(route_plans),
        "route_plan_count": len(route_plans),
        "route_step_count": len(route_steps),
        "travel_event_count": travel_event_count,
        "route_segment_count": len(route_segments),
        "movement_event_count": travel_event_count,
        "intermediate_node_count": len(intermediate_nodes),
        "cross_landing_bridge_count": len(cross_landing_bridges),
        "path_lifecycle_count": len(path_lifecycle_rows),
        "path_completed_count": sum(1 for item in path_lifecycle_rows if str(item.get("lifecycle_state") or "") == "completed"),
        "path_stopped_count": sum(1 for item in path_lifecycle_rows if str(item.get("lifecycle_state") or "") == "stopped"),
        "path_started_count": sum(1 for item in path_lifecycle_rows if str(item.get("lifecycle_state") or "") == "started"),
        "path_pending_count": sum(1 for item in path_lifecycle_rows if str(item.get("lifecycle_state") or "") == "pending"),
        "path_changed_context_package_count": sum(1 for item in path_lifecycle_rows if bool(item.get("changed_context_package"))),
        "highway_considered_count": int(route_summary.get("highway_considered_count") or 0),
        "highway_traversed_count": int(route_summary.get("highway_traversed_count") or 0),
        "ai_spatial_snap_landing_count": sum(1 for item in landing_rows if bool(item.get("has_spatial_snap"))),
        "ai_spatial_route_plan_count": sum(1 for item in route_plans if bool(item.get("has_spatial_snap"))),
        "ai_spatial_route_step_count": sum(1 for item in route_steps if bool(item.get("has_spatial_snap"))),
        "ai_spatial_travel_event_count": sum(1 for item in route_steps if bool(item.get("has_spatial_snap")) and bool(item.get("travel_performed"))),
        "heuristic_provisional_landing_count": sum(1 for item in landing_rows if bool(item.get("heuristic_provisional"))),
        "serial_landing_route_detected": False,
    }
    return {
        "schema_version": SEARCH_MAP_2D_TRUTH_SCHEMA_VERSION,
        "package_kind": "search_map_2d_truth",
        "search_id": search_id,
        "thread_id": thread_id,
        "phase": phase,
        "motion_policy": {
            "mode": "trace_driven",
            "live_motion_source": "route_trace",
            "allow_synthetic_motion": False,
            "allow_css_perpetual_motion": False,
            "replay_required_for_animation": True,
            "replay_label_required": True,
        },
        "invariants": {
            "each_landing_is_independent_scout_origin": True,
            "path_model": "landing_to_ai_chosen_route_or_corridor",
            "parallel_landings_are_not_serial_route": True,
            "serial_landing_route_detected": False,
            "route_labels_use_branch_landing_route_ids": True,
            "array_order_route_labeling_allowed": False,
            "cross_landing_bridge_requires_explicit_backend_bridge": True,
        },
        "landings": landing_rows,
        "route_plans": route_plans,
        "route_steps": route_steps,
        "route_segments": route_segments,
        "intermediate_nodes": intermediate_nodes,
        "terminal_states": terminal_states,
        "cross_landing_bridges": cross_landing_bridges,
        "path_lifecycle": path_lifecycle_rows,
        "metrics": metrics,
    }


def _family_attribution_summary_for_answer(
    *,
    branches: list[dict[str, Any]],
    fallback_summary: dict[str, Any] | None,
    evidence_node_ids: list[str] | None,
) -> dict[str, Any]:
    summary = {"heuristic": 0, "ai": 0, "dual_origin": 0}
    evidence_ids = {str(item).strip() for item in list(evidence_node_ids or []) if str(item).strip()}
    relevant = []
    for branch in branches:
        branch_nodes = {str(item).strip() for item in list(branch.get("evidence_node_ids") or []) if str(item).strip()}
        if evidence_ids and branch_nodes.isdisjoint(evidence_ids):
            continue
        relevant.append(branch)
    for branch in relevant:
        families = {
            str(item).strip().lower()
            for item in list(branch.get("origin_families") or [])
            if str(item).strip().lower() in {"heuristic", "ai"}
        }
        if not families:
            planner_family = str(branch.get("planner_family") or "").strip().lower()
            families = {planner_family if planner_family in {"heuristic", "ai"} else "heuristic"}
        if len(families) > 1 or bool(branch.get("dual_origin")):
            summary["dual_origin"] += 1
        if "heuristic" in families:
            summary["heuristic"] += 1
        if "ai" in families:
            summary["ai"] += 1
    if any(summary.values()):
        return summary
    fallback = dict(fallback_summary or {})
    return {
        "heuristic": int(fallback.get("heuristic") or 0),
        "ai": int(fallback.get("ai") or 0),
        "dual_origin": int(fallback.get("dual_origin") or 0),
    }


def _augment_answer_support_surface(
    answer: dict[str, Any] | None,
    *,
    matches: list[dict[str, Any]],
    shared_evidence: dict[str, Any],
    branches: list[dict[str, Any]],
) -> dict[str, Any] | None:
    if not answer:
        return answer
    metadata = build_answer_support_metadata(
        matches=matches,
        shared_evidence=shared_evidence,
        evidence_node_ids=list(answer.get("evidence_node_ids") or []),
    )
    answer_evidence_ids = {
        str(node_id).strip()
        for node_id in list(answer.get("evidence_node_ids") or [])
        if str(node_id).strip()
    }
    answer_evidence_ids.update(
        str(snippet.get("node_id") or "").strip()
        for snippet in list(answer.get("evidence_snippets") or [])
        if isinstance(snippet, dict) and str(snippet.get("node_id") or "").strip()
    )
    snippet_slots = {
        _goal_to_slot(str(snippet.get("kind") or ""))
        for snippet in list(answer.get("evidence_snippets") or [])
        if isinstance(snippet, dict) and str(snippet.get("kind") or "").strip()
    }
    coverage_slots = {
        str(slot).strip()
        for slot, value in dict(shared_evidence.get("coverage_by_slot") or {}).items()
        if str(slot).strip() and float(value or 0.0) > 0.0
    }
    answer["support_node_count"] = max(
        int(metadata.get("support_node_count") or 0),
        int(answer.get("support_node_count") or 0),
        len(answer_evidence_ids),
    )
    answer["support_slot_count"] = max(
        int(metadata.get("support_slot_count") or 0),
        int(answer.get("support_slot_count") or 0),
        len({slot for slot in snippet_slots if slot}),
        len(coverage_slots),
    )
    answer["family_attribution_summary"] = _family_attribution_summary_for_answer(
        branches=branches,
        fallback_summary=dict(metadata.get("family_attribution_summary") or answer.get("family_attribution_summary") or {}),
        evidence_node_ids=list(answer.get("evidence_node_ids") or []),
    )
    answer["contradiction_present"] = bool(
        metadata.get("contradiction_present")
        or answer.get("contradiction_present")
        or list(shared_evidence.get("contradiction_flags") or [])
    )
    return answer


def _compute_ai_material_contribution(
    *,
    planner_seed_runtime: dict[str, Any],
    llm_scout_state: dict[str, Any],
    branches: list[dict[str, Any]],
    semantic_contract_runtime: dict[str, Any] | None = None,
    path_corridors: dict[str, Any] | None = None,
) -> tuple[bool, str | None]:
    semantic_runtime = dict(semantic_contract_runtime or {})
    path_package = dict(path_corridors or {})
    path_metrics = dict(path_package.get("metrics") or {})
    path_row_count = len(list(path_package.get("paths") or [])) or int(path_metrics.get("path_count") or 0)
    route_event_count = int(path_metrics.get("route_event_count") or 0)
    terminal_path_count = int(path_metrics.get("terminal_path_count") or 0)
    if _semantic_contract_is_ai_material(semantic_runtime) and path_row_count > 0 and (route_event_count > 0 or terminal_path_count > 0):
        return True, "semantic_contract_path_corridor_material"
    if (
        _semantic_contract_is_ai_material(semantic_runtime)
        and bool(planner_seed_runtime.get("semantic_contract_ai_seed_used"))
    ):
        return True, None
    planner_seed_source = str(planner_seed_runtime.get("planner_seed_source") or "").strip()
    if planner_seed_source == "llm":
        return True, None
    if int(llm_scout_state.get("added_probe_count") or 0) > 0:
        return True, None
    for branch in branches:
        origin_families = {
            str(item).strip().lower()
            for item in list(branch.get("origin_families") or [])
            if str(item).strip().lower() in {"heuristic", "ai"}
        }
        if "ai" in origin_families or bool(branch.get("dual_origin")):
            return True, None
        if str(branch.get("planner_family") or "").strip().lower() == "ai" and list(branch.get("route_trace") or []):
            return True, None
    if planner_seed_source == "timeout":
        return False, "planner_seed_timeout_no_refinement_gain"
    if planner_seed_source == "provider_error":
        return False, "planner_seed_provider_error_no_refinement_gain"
    if planner_seed_source == "disabled":
        return False, "planner_disabled"
    if _semantic_contract_is_ai_material(semantic_runtime):
        return False, "semantic_contract_without_route_material"
    return False, "ai_refinement_no_material_change"


def _build_ai_materiality_summary(
    *,
    query_text: str,
    retrieval_mode: str,
    planner_seed_runtime: dict[str, Any],
    llm_scout_state: dict[str, Any],
    branches: list[dict[str, Any]],
    final_scout_wait_seconds: float,
    first_answer_sla_split: bool,
    semantic_contract_runtime: dict[str, Any] | None = None,
    path_corridors: dict[str, Any] | None = None,
) -> dict[str, Any]:
    material, reason = _compute_ai_material_contribution(
        planner_seed_runtime=planner_seed_runtime,
        llm_scout_state=llm_scout_state,
        branches=branches,
        semantic_contract_runtime=semantic_contract_runtime,
        path_corridors=path_corridors,
    )
    mode = str(retrieval_mode or "balanced").strip().lower()
    planner_seed_budget_seconds = (
        _planner_seed_timeout_seconds(mode, query_text)
        + _planner_seed_transport_guard_seconds()
    )
    branch_ai_count = sum(1 for branch in branches if _record_has_family(branch, "ai"))
    path_package = dict(path_corridors or {})
    path_metrics = dict(path_package.get("metrics") or {})
    return {
        "enabled": bool(llm_scout_state.get("enabled")),
        "status": str(llm_scout_state.get("status") or "") or None,
        "suppressed_reason": str(llm_scout_state.get("suppressed_reason") or "") or None,
        "error": str(llm_scout_state.get("error") or "") or None,
        "completed": bool(llm_scout_state.get("completed")),
        "completed_ms": llm_scout_state.get("completed_ms"),
        "first_answer_sla_split": bool(first_answer_sla_split),
        "llm_scout_fast_only": bool(llm_scout_state.get("fast_only")),
        "llm_scout_fast_only_reason": str(llm_scout_state.get("fast_only_reason") or "") or None,
        "final_wait_budget_seconds": round(max(0.0, float(final_scout_wait_seconds or 0.0)), 3),
        "final_join_wait_seconds": round(max(0.0, float(llm_scout_state.get("final_join_wait_seconds") or final_scout_wait_seconds or 0.0)), 3),
        "final_wait_capped_by_sla": bool(llm_scout_state.get("final_wait_capped_by_sla")),
        "non_blocking_finalization": bool(llm_scout_state.get("non_blocking_finalization")),
        "first_answer_ready_before_final_join": bool(llm_scout_state.get("first_answer_ready_before_final_join")),
        "final_surface_sla_seconds": round(max(0.0, float(llm_scout_state.get("final_surface_sla_seconds") or 0.0)), 3),
        "planner_seed_budget_seconds": round(planner_seed_budget_seconds, 3),
        "planner_seed_source": str(planner_seed_runtime.get("planner_seed_source") or "") or None,
        "planner_seed_status": str(planner_seed_runtime.get("planner_seed_status") or "") or None,
        "planner_seed_ms": planner_seed_runtime.get("planner_seed_ms"),
        "semantic_contract_status": str((semantic_contract_runtime or {}).get("status") or "") or None,
        "semantic_contract_source": str((semantic_contract_runtime or {}).get("source") or "") or None,
        "semantic_contract_material": bool((semantic_contract_runtime or {}).get("material")),
        "semantic_contract_ai_required": bool((semantic_contract_runtime or {}).get("ai_required")),
        "semantic_contract_compiler_ms": (semantic_contract_runtime or {}).get("compiler_ms"),
        "llm_probe_count": int(llm_scout_state.get("llm_probe_count") or 0),
        "llm_added_probe_count": int(llm_scout_state.get("added_probe_count") or 0),
        "branch_ai_count": int(branch_ai_count),
        "branch_reuse_count": int(llm_scout_state.get("branch_reuse_count") or 0),
        "branch_enrich_count": int(llm_scout_state.get("branch_enrich_count") or 0),
        "branch_fork_count": int(llm_scout_state.get("branch_fork_count") or 0),
        "ai_compiled_path_count": len(list(path_package.get("paths") or [])) or int(path_metrics.get("path_count") or 0),
        "ai_compiled_path_route_event_count": int(path_metrics.get("route_event_count") or 0),
        "ai_compiled_path_terminal_count": int(path_metrics.get("terminal_path_count") or 0),
        "material": material,
        "reason": reason,
    }


def build_ai_landing_materialization_contract(
    *,
    query_text: str,
    response_mode: str | None = None,
    semantic_contract: dict[str, Any] | None,
    semantic_contract_runtime: dict[str, Any] | None,
    planner_seed_runtime: dict[str, Any] | None,
    llm_scout_state: dict[str, Any] | None,
    probes: list[dict[str, Any]] | None,
    branches: list[dict[str, Any]] | None,
    path_corridors: dict[str, Any] | None,
    ai_materiality_summary: dict[str, Any] | None,
    ai_validation_gate: dict[str, Any] | None,
    final_ai_approval: dict[str, Any] | None,
    final_surface_fields: dict[str, Any] | None,
    ai_spatial_landing_contract: dict[str, Any] | None = None,
) -> dict[str, Any]:
    contract = dict(semantic_contract or {})
    runtime = dict(semantic_contract_runtime or {})
    spatial_contract = dict(ai_spatial_landing_contract or {})
    seed_runtime = dict(planner_seed_runtime or {})
    if not spatial_contract:
        spatial_contract = dict(seed_runtime.get("ai_spatial_landing_contract") or {})
    spatial_metrics = dict(spatial_contract.get("metrics") or {})
    scout = dict(llm_scout_state or {})
    materiality = dict(ai_materiality_summary or {})
    validation_gate = dict(ai_validation_gate or {})
    approval = dict(final_ai_approval or {})
    surface = dict(final_surface_fields or {})
    landing_plan = dict(contract.get("landing_plan") or {})
    path_package = dict(path_corridors or {})
    path_metrics = dict(path_package.get("metrics") or {})

    expected_evidence = [
        dict(item)
        for item in list(contract.get("expected_evidence") or contract.get("expected_evidence_targets") or [])
        if isinstance(item, dict)
    ]
    landing_hypotheses = [
        dict(item)
        for item in list(landing_plan.get("landing_hypotheses") or landing_plan.get("landings") or [])
        if isinstance(item, dict)
    ]
    semantic_paths = [
        dict(item)
        for item in list(landing_plan.get("paths") or contract.get("paths") or [])
        if isinstance(item, dict)
    ]
    spatial_paths = [
        dict(item)
        for item in list(spatial_contract.get("inverse_answer_paths") or [])
        if isinstance(item, dict)
    ]
    path_rows = [
        dict(item)
        for item in list(path_package.get("paths") or path_package.get("path_rows") or path_package.get("corridors") or [])
        if isinstance(item, dict)
    ]
    probe_rows = [dict(probe) for probe in list(probes or []) if isinstance(probe, dict)]
    branch_rows = [dict(branch) for branch in list(branches or []) if isinstance(branch, dict)]
    ai_probes = [probe for probe in probe_rows if _record_has_family(probe, "ai")]
    ai_branches = [branch for branch in branch_rows if _record_has_family(branch, "ai")]
    ai_route_trace_count = sum(len(list(branch.get("route_trace") or [])) for branch in ai_branches)
    ai_travel_count = sum(
        1
        for branch in ai_branches
        for entry in list(branch.get("route_trace") or [])
        if isinstance(entry, dict) and bool(entry.get("travel_performed"))
    )
    llm_enabled_value = bool(scout.get("enabled") or runtime.get("enabled") or seed_runtime.get("planner_seed_enabled"))
    required = bool(runtime.get("ai_required") or contract.get("ai_required") or validation_gate.get("required"))
    semantic_source = str(runtime.get("source") or contract.get("contract_authority") or "").strip() or None
    contract_materialized = _semantic_contract_is_ai_material(runtime)
    spatial_contract_observed = bool(spatial_contract)
    spatial_contract_materialized = bool(spatial_contract.get("materialized") or spatial_contract.get("certifiable"))
    spatial_landing_count = int(spatial_metrics.get("ai_landing_count") or len(spatial_paths) or 0)
    spatial_path_count = int(spatial_metrics.get("ai_path_count") or len(spatial_paths) or 0)
    spatial_contract_required_for_certification = bool(required and spatial_contract_observed)
    spatial_contract_certifies_route = bool(
        not spatial_contract_required_for_certification
        or (spatial_contract_materialized and spatial_landing_count > 0 and spatial_path_count > 0)
    )
    landing_created = bool((contract_materialized and landing_hypotheses) or (spatial_contract_materialized and spatial_landing_count > 0))
    path_intent_created = bool((contract_materialized and semantic_paths) or (spatial_contract_materialized and spatial_path_count > 0))
    semantic_seed_used = bool(seed_runtime.get("semantic_contract_ai_seed_used"))
    seed_landing_materialized = bool(
        semantic_seed_used
        or str(seed_runtime.get("planner_seed_source") or "") == "llm"
    )
    scout_added_probe_count = int(scout.get("added_probe_count") or 0)
    scout_probe_count = int(scout.get("llm_probe_count") or 0)
    landing_materialized = bool(ai_probes or ai_branches or scout_added_probe_count > 0 or seed_landing_materialized)
    branch_materialized = bool(ai_branches)
    path_corridor_materialized = bool(path_rows or int(path_metrics.get("path_count") or 0) > 0)
    ai_compiled_path_materialized = bool(path_intent_created and path_corridor_materialized)
    semantic_route_candidate_materialized = bool(
        landing_materialized
        or branch_materialized
        or ai_route_trace_count > 0
        or ai_compiled_path_materialized
    )
    route_level_materialized = bool(semantic_route_candidate_materialized and spatial_contract_certifies_route)
    judge_attempted = bool(
        approval.get("attempted")
        or validation_gate.get("final_llm_approval")
        or any(
            str(decision.get("decision_source") or "").strip() == "llm"
            and str(decision.get("decision") or "").strip() in {"emit_answer_final", "stop_all"}
            and not bool(decision.get("should_continue_expanding"))
            for decision in list((validation_gate.get("decision_history") or []))
            if isinstance(decision, dict)
        )
    )
    judge_materialized = bool(approval.get("approved") or validation_gate.get("final_llm_approval"))
    answer_requested = str(response_mode or "").strip() in {"answer", "both"}
    legacy_final_requested = bool(response_mode is None)
    surface_final_requested = bool(
        validation_gate.get("final_requested")
        or surface.get("final_closure_ready")
        or str(surface.get("closure_state") or "") == "final_sealed"
        or str(surface.get("answer_surface_state") or "") == "final_sealed"
    )
    final_requested = bool(surface_final_requested and (answer_requested or legacy_final_requested))

    blockers: list[str] = []
    if required and not llm_enabled_value:
        blockers.append("ai_disabled_or_unavailable")
    if required and not contract_materialized:
        blockers.append("ai_semantic_contract_missing")
    if required and spatial_contract_observed and not spatial_contract_materialized:
        blockers.append("ai_spatial_landing_contract_missing")
    if required and spatial_contract_materialized and spatial_landing_count <= 0:
        blockers.append("ai_spatial_landing_count_zero")
    if required and spatial_contract_materialized and spatial_path_count <= 0:
        blockers.append("ai_spatial_path_count_zero")
    if required and not landing_created:
        blockers.append("ai_landing_hypotheses_missing")
    if required and not (landing_materialized or ai_compiled_path_materialized):
        blockers.append("ai_landing_runtime_missing")
    if required and not (branch_materialized or ai_compiled_path_materialized):
        blockers.append("ai_branch_missing")
    if required and path_intent_created and not path_corridor_materialized and not ai_route_trace_count:
        blockers.append("ai_path_corridor_not_executed")
    if required and final_requested and not judge_materialized:
        blockers.append("ai_judge_missing")
    for item in list(validation_gate.get("blockers") or []):
        blocker = str(item).strip()
        if not blocker or blocker in blockers:
            continue
        if not final_requested and blocker in {"ai_judge_missing", "ai_final_judge_missing", "blocked_ai_final_judge_missing"}:
            continue
        blockers.append(blocker)

    scout_status = str(scout.get("status") or "").strip()
    if not required:
        validation_state = "not_required"
    elif not llm_enabled_value:
        validation_state = "ai_unavailable_fallback"
    elif route_level_materialized and (not final_requested or judge_materialized):
        validation_state = "materialized"
    elif route_level_materialized and final_requested and not judge_materialized:
        validation_state = "materialized_judge_pending"
    elif scout_status in {"pending", "running"}:
        validation_state = "pending_ai_route_material"
    elif contract_materialized:
        validation_state = "provisional_no_ai_route_material"
    else:
        validation_state = "ai_materialization_failed"

    return {
        "schema_version": "agvm.ai_landing_materialization.v1",
        "query_text": str(query_text or ""),
        "required": required,
        "llm_enabled": llm_enabled_value,
        "validation_state": validation_state,
        "materialized": bool(route_level_materialized and (not final_requested or judge_materialized)),
        "route_level_materialized": route_level_materialized,
        "semantic_route_candidate_materialized": semantic_route_candidate_materialized,
        "spatial_contract_required_for_certification": spatial_contract_required_for_certification,
        "spatial_contract_certifies_route": spatial_contract_certifies_route,
        "honest_failure": bool(required and validation_state in {"ai_unavailable_fallback", "provisional_no_ai_route_material", "ai_materialization_failed"}),
        "silent_success_prevented": bool(required and blockers and not bool(surface.get("final_closure_ready"))),
        "blockers": _dedupe_limited(blockers, limit=16),
        "ai_landing_count": spatial_landing_count,
        "ai_path_count": spatial_path_count,
        "spatial_contract": {
            "observed": spatial_contract_observed,
            "materialized": spatial_contract_materialized,
            "certifiable": bool(spatial_contract.get("certifiable")),
            "status": str(spatial_contract.get("status") or "") or None,
            "source": str(spatial_contract.get("source") or "") or None,
            "planner_latency_ms": spatial_contract.get("planner_latency_ms"),
            "metamemory_spatial_revision": spatial_contract.get("metamemory_spatial_revision"),
            "missing_reasons": list(spatial_contract.get("missing_reasons") or [])[:12],
            "metrics": spatial_metrics,
        },
        "semantic_contract": {
            "materialized": contract_materialized,
            "source": semantic_source,
            "status": str(runtime.get("status") or "") or None,
            "compiler_ms": runtime.get("compiler_ms"),
            "attempt_count": runtime.get("attempt_count"),
            "retry_used": bool(runtime.get("retry_used")),
            "retry_status": str(runtime.get("retry_status") or "") or None,
            "error": str(runtime.get("error") or "") or None,
            "expected_evidence_count": len(expected_evidence),
        },
        "landing": {
            "created_by_ai": landing_created,
            "materialized": bool(landing_materialized or ai_compiled_path_materialized),
            "hypothesis_count": len(landing_hypotheses),
            "spatial_contract_landing_count": spatial_landing_count,
            "probe_count": len(ai_probes),
            "llm_probe_count": scout_probe_count,
            "llm_added_probe_count": scout_added_probe_count,
            "semantic_seed_used": semantic_seed_used,
            "planner_seed_source": str(seed_runtime.get("planner_seed_source") or "") or None,
            "materialized_by_ai_compiled_path": ai_compiled_path_materialized,
        },
        "branch": {
            "materialized": branch_materialized,
            "ai_branch_count": len(ai_branches),
            "ai_route_trace_count": ai_route_trace_count,
            "ai_travel_count": ai_travel_count,
            "dual_origin_branch_count": int(scout.get("dual_origin_branch_count") or 0),
            "reuse_count": int(scout.get("branch_reuse_count") or 0),
            "enrich_count": int(scout.get("branch_enrich_count") or 0),
            "fork_count": int(scout.get("branch_fork_count") or 0),
        },
        "path": {
            "intent_created_by_ai": path_intent_created,
            "intent_count": max(len(semantic_paths), spatial_path_count),
            "spatial_contract_path_count": spatial_path_count,
            "corridor_materialized": path_corridor_materialized,
            "ai_compiled_path_materialized": ai_compiled_path_materialized,
            "corridor_count": int(path_metrics.get("path_count") or len(path_rows)),
            "path_row_count": len(path_rows),
        },
        "judge": {
            "required_for_final": bool(required and final_requested),
            "attempted": judge_attempted,
            "materialized": judge_materialized,
            "approved": bool(approval.get("approved") or validation_gate.get("final_llm_approval")),
            "error": approval.get("error"),
        },
        "scout": {
            "enabled": bool(scout.get("enabled")),
            "status": scout_status or None,
            "completed": bool(scout.get("completed")),
            "completed_ms": scout.get("completed_ms"),
            "fast_only": bool(scout.get("fast_only")),
            "fast_only_reason": str(scout.get("fast_only_reason") or "") or None,
            "error": str(scout.get("error") or "") or None,
        },
        "legacy_materiality": {
            "material": bool(materiality.get("material")),
            "reason": materiality.get("reason"),
        },
    }


def _llm_scout_fast_only_mode(
    *,
    first_answer_sla_split: bool,
    semantic_contract: dict[str, Any] | None,
    semantic_contract_runtime: dict[str, Any] | None,
) -> bool:
    contract = dict(semantic_contract or {})
    runtime = dict(semantic_contract_runtime or {})
    ai_required = bool(runtime.get("ai_required") or contract.get("ai_required"))
    return bool(first_answer_sla_split and not ai_required)


def _build_final_ai_validation_gate(
    *,
    semantic_contract: dict[str, Any] | None,
    semantic_contract_runtime: dict[str, Any] | None,
    ai_materiality_summary: dict[str, Any] | None,
    master_decision_history: list[dict[str, Any]] | None,
    final_surface_fields: dict[str, Any] | None,
    response_mode: str | None = None,
) -> dict[str, Any]:
    semantic_contract_payload = dict(semantic_contract or {})
    semantic_runtime = dict(semantic_contract_runtime or {})
    materiality = dict(ai_materiality_summary or {})
    final_surface = dict(final_surface_fields or {})
    ai_required = bool(semantic_runtime.get("ai_required") or semantic_contract_payload.get("ai_required"))
    answer_requested = str(response_mode or "").strip() in {"answer", "both"}
    legacy_final_requested = response_mode is None
    surface_final_requested = bool(
        final_surface.get("final_closure_ready")
        or str(final_surface.get("closure_state") or "") == "final_sealed"
        or str(final_surface.get("answer_surface_state") or "") == "final_sealed"
    )
    final_requested = bool(surface_final_requested and (answer_requested or legacy_final_requested))
    history = [dict(item or {}) for item in list(master_decision_history or []) if isinstance(item, dict)]
    final_llm_approval: dict[str, Any] | None = None
    final_llm_decision: dict[str, Any] | None = None
    for decision in reversed(history):
        decision_source = str(decision.get("decision_source") or "").strip()
        decision_name = str(decision.get("decision") or "").strip()
        should_continue = bool(decision.get("should_continue_expanding"))
        approval_payload = dict(decision.get("final_ai_approval") or {}) if isinstance(decision.get("final_ai_approval"), dict) else {}
        if decision_source == "llm" and approval_payload and final_llm_decision is None:
            final_llm_decision = decision
        if decision_source == "llm" and decision_name in {"emit_answer_final", "stop_all"} and not should_continue:
            final_llm_approval = decision
            break
    ai_material = bool(materiality.get("material"))
    blockers: list[str] = []
    if ai_required and not ai_material:
        blockers.append("ai_material_missing")
    if ai_required and final_requested and final_llm_approval is None and final_llm_decision is None:
        blockers.append("ai_final_judge_missing")
    if ai_required and final_requested and final_llm_approval is None and final_llm_decision is not None:
        blockers.append("ai_final_judge_rejected")
    scout_status = str(materiality.get("status") or "").strip()
    if ai_required and scout_status in {"pending", "running"} and not ai_material:
        blockers.append("ai_scout_still_running")
    satisfied = (not ai_required) or (ai_material and (not final_requested or final_llm_approval is not None))
    return {
        "schema_version": "agvm.ai_validation_gate.v1",
        "required": ai_required,
        "answer_final_judge_required": bool(final_requested),
        "satisfied": bool(satisfied),
        "blocked": bool(final_requested and not satisfied),
        "final_requested": final_requested,
        "ai_material": ai_material,
        "ai_material_reason": materiality.get("reason"),
        "semantic_contract_status": str(semantic_runtime.get("status") or "") or None,
        "semantic_contract_source": str(semantic_runtime.get("source") or "") or None,
        "semantic_contract_material": bool(semantic_runtime.get("material")),
        "llm_scout_status": scout_status or None,
        "final_llm_approval": bool(final_llm_approval),
        "final_llm_judge_attempted": bool(final_llm_decision),
        "final_llm_judge_rejected": bool(final_llm_decision is not None and final_llm_approval is None),
        "final_llm_approval_round": (final_llm_approval or {}).get("round") if final_llm_approval else None,
        "final_llm_rejection_reason": str(((final_llm_decision or {}).get("final_ai_approval") or {}).get("reason") or (final_llm_decision or {}).get("reason") or "") or None,
        "last_decision_source": str((history[-1] if history else {}).get("decision_source") or "") or None,
        "last_decision": str((history[-1] if history else {}).get("decision") or "") or None,
        "blockers": blockers,
    }


def _apply_final_ai_validation_gate(
    *,
    final_surface_fields: dict[str, Any],
    ai_validation_gate: dict[str, Any],
    can_answer_now: bool,
) -> dict[str, Any]:
    if not bool(ai_validation_gate.get("blocked")):
        return dict(final_surface_fields or {})
    updated = dict(final_surface_fields or {})
    blocker_reason = ",".join(str(item) for item in list(ai_validation_gate.get("blockers") or [])) or "ai_validation_not_satisfied"
    ai_blocker = {
        "branch_id": "ai_validation",
        "planner_family": "ai",
        "origin_families": ["ai"],
        "destination_key": "ai_validation",
        "destination_id": "ai_validation",
        "label": "AI validation",
        "state": "pending",
        "state_reason": blocker_reason,
        "semantic_order_index": None,
    }
    blockers = [ai_blocker]
    blockers.extend(dict(item or {}) for item in list(updated.get("final_closure_blockers") or []) if isinstance(item, dict))
    histogram = dict(updated.get("closure_blocker_reason_histogram") or {})
    histogram[blocker_reason] = int(histogram.get(blocker_reason) or 0) + 1
    updated["final_closure_ready"] = False
    updated["closure_state"] = "open"
    updated["final_closure_blockers"] = blockers[:16]
    updated["closure_blocker_reason_histogram"] = histogram
    updated["unresolved_destination_count"] = max(1, int(updated.get("unresolved_destination_count") or 0), len(blockers))
    updated["answer_surface_state"] = (
        "answer_now_and_continue"
        if can_answer_now
        else ("context_level_1_ready" if bool(updated.get("context_level_1_ready")) else "not_ready")
    )
    updated["answer_now_before_exploration_complete"] = bool(can_answer_now)
    updated["final_closure_after_destination_resolution"] = False
    return updated


def _final_surface_requests_final_closure(final_surface_fields: dict[str, Any] | None) -> bool:
    final_surface = dict(final_surface_fields or {})
    return bool(
        final_surface.get("final_closure_ready")
        or str(final_surface.get("closure_state") or "") == "final_sealed"
        or str(final_surface.get("answer_surface_state") or "") == "final_sealed"
    )


def _document_lookup_exact_ai_exception(
    *,
    query_class: str | None,
    document_mode: str | None,
    document_lookup_kind: str | None,
    document_lookup: dict[str, Any] | None,
    document_packets: list[dict[str, Any]] | None,
    context_package_materialization: dict[str, Any] | None,
) -> dict[str, Any]:
    lookup = dict(document_lookup or {})
    packets = [dict(item or {}) for item in list(document_packets or []) if isinstance(item, dict)]
    package = dict(context_package_materialization or {})
    kind = str(document_lookup_kind or lookup.get("kind") or "").strip()
    mode = str(document_mode or lookup.get("document_mode") or "").strip()
    state = str(lookup.get("state") or "").strip()
    supporting_count = int(lookup.get("supporting_document_count") or len(list(lookup.get("supporting_documents") or [])) or 0)
    packet_count = len(packets)
    exact_score = float(lookup.get("max_exact_match_score") or lookup.get("max_packet_query_fit") or 0.0)
    contract_passed = bool(package.get("contract_passed"))
    exact_lookup = (
        str(query_class or "").strip() == "document_lookup"
        and mode in {"lookup", "document_lookup", "exact_lookup"}
        and kind == "exact_document_lookup"
        and state
        and state
        not in {
            "no_matching_document_packet",
            "no_matching_document_packet_yet",
            "no_document_found",
            "unmatched",
            "empty",
            "none",
        }
        and (supporting_count > 0 or packet_count > 0 or exact_score > 0.0)
        and contract_passed
    )
    return {
        "applied": bool(exact_lookup),
        "reason": "exact_deterministic_document_lookup" if exact_lookup else None,
        "query_class": str(query_class or "") or None,
        "document_mode": mode or None,
        "document_lookup_kind": kind or None,
        "document_lookup_state": state or None,
        "supporting_document_count": supporting_count,
        "document_packet_count": packet_count,
        "max_exact_match_score": exact_score,
        "context_package_contract_passed": contract_passed,
    }


def _ai_materialization_block_state(ai_landing_materialization: dict[str, Any] | None) -> str:
    materialization = dict(ai_landing_materialization or {})
    blockers = {
        str(item).strip()
        for item in list(materialization.get("blockers") or [])
        if str(item).strip()
    }
    scout = dict(materialization.get("scout") or {})
    scout_status = str(scout.get("status") or "").strip()
    scout_error = str(scout.get("error") or "").strip()
    if scout_error or scout_status in {"error", "failed", "provider_error"}:
        return "provider_error"
    if scout_status in {"pending", "running"}:
        return "context_partial_needs_more_search"
    if any("budget" in blocker for blocker in blockers):
        return "budget_exhausted_before_ai_material"
    return "blocked_ai_material_missing"


def _build_ai_materialization_hard_gate(
    *,
    query_class: str | None,
    response_mode: str | None,
    semantic_contract: dict[str, Any] | None,
    semantic_contract_runtime: dict[str, Any] | None,
    ai_landing_materialization: dict[str, Any] | None,
    ai_validation_gate: dict[str, Any] | None,
    final_surface_fields: dict[str, Any] | None,
    context_package_materialization: dict[str, Any] | None,
    answer_demo_materialization: dict[str, Any] | None,
    document_mode: str | None = None,
    document_lookup_kind: str | None = None,
    document_lookup: dict[str, Any] | None = None,
    document_packets: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    contract = dict(semantic_contract or {})
    runtime = dict(semantic_contract_runtime or {})
    materialization = dict(ai_landing_materialization or {})
    validation_gate = dict(ai_validation_gate or {})
    context_materialization = dict(context_package_materialization or {})
    answer_materialization = dict(answer_demo_materialization or {})
    ai_required = bool(runtime.get("ai_required") or contract.get("ai_required") or validation_gate.get("required"))
    exact_document_exception = _document_lookup_exact_ai_exception(
        query_class=query_class,
        document_mode=document_mode,
        document_lookup_kind=document_lookup_kind,
        document_lookup=document_lookup,
        document_packets=document_packets,
        context_package_materialization=context_materialization,
    )
    required = bool(ai_required and not exact_document_exception.get("applied"))
    answer_requested = str(response_mode or "") in {"answer", "both"}
    final_requested = bool(_final_surface_requests_final_closure(final_surface_fields) and answer_requested)
    query_class_text = str(query_class or "").strip()
    route_level_materialized = bool(materialization.get("route_level_materialized"))
    validation_state = str(materialization.get("validation_state") or "").strip()
    materialized_state = validation_state in {"materialized", "materialized_judge_pending"}
    route_material_ok = bool(route_level_materialized and materialized_state)
    judge = dict(materialization.get("judge") or {})
    judge_materialized = bool(
        judge.get("materialized")
        or judge.get("approved")
        or validation_gate.get("final_llm_approval")
    )
    context_contract_passed = bool(context_materialization.get("contract_passed"))
    answer_demo_state = str(answer_materialization.get("state") or "").strip()
    answer_demo_requested = bool(answer_materialization.get("requested") or answer_demo_state not in {"", "not_requested"})
    answer_demo_ready = (not answer_requested) or answer_demo_state in {"ready", "not_requested"}
    secondary_answer_demo_only = bool(query_class_text == "document_lookup" and not final_requested)
    answer_demo_requires_final_validation = bool(answer_requested and answer_demo_requested and not secondary_answer_demo_only)
    blockers: list[str] = []
    materialization_blockers = [
        str(item).strip()
        for item in list(materialization.get("blockers") or [])
        if str(item).strip()
    ]
    if required and not route_material_ok:
        blockers.append(_ai_materialization_block_state(materialization))
        blockers.extend(materialization_blockers[:8])
    if (
        required
        and route_material_ok
        and not judge_materialized
        and (final_requested or answer_demo_requires_final_validation)
    ):
        validation_blockers = {
            str(item).strip()
            for item in list(validation_gate.get("blockers") or [])
            if str(item).strip()
        }
        blockers.append(
            "blocked_ai_final_judge_rejected"
            if "ai_final_judge_rejected" in validation_blockers
            else "blocked_ai_final_judge_missing"
        )
    if required and answer_requested and not context_contract_passed:
        blockers.append("blocked_context_package_unapproved")
    answer_demo_blockers: list[str] = []
    if required and answer_requested and context_contract_passed and not answer_demo_ready:
        answer_demo_blockers.append("answer_demo_not_approved_secondary")
        if answer_demo_requires_final_validation:
            blockers.append("blocked_answer_demo_not_approved")
    blockers = _dedupe_limited(blockers, limit=16)
    if exact_document_exception.get("applied"):
        state = "exact_document_lookup_exception"
    elif blockers:
        state = blockers[0]
    elif required:
        state = "ai_materialization_validated"
    else:
        state = "ai_not_required"
    return {
        "schema_version": "agvm.ai_materialization_hard_gate.v1",
        "required": required,
        "ai_required": ai_required,
        "satisfied": bool((not required) or not blockers),
        "blocked": bool(required and blockers),
        "validation_state": state,
        "blockers": blockers,
        "final_requested": final_requested,
        "route_level_materialized": route_level_materialized,
        "route_material_ok": route_material_ok,
        "ai_landing_validation_state": validation_state or None,
        "judge_materialized": judge_materialized,
        "context_package_contract_passed": context_contract_passed,
        "answer_demo_state": answer_demo_state or None,
        "answer_demo_ready": answer_demo_ready,
        "answer_demo_blockers": answer_demo_blockers,
        "mcp_context_package_ready": bool(
            context_contract_passed
            and route_material_ok
            and "blocked_context_package_unapproved" not in blockers
        ),
        "document_lookup_exception": exact_document_exception,
    }


def _apply_ai_materialization_hard_gate(
    *,
    final_surface_fields: dict[str, Any],
    hard_gate: dict[str, Any],
    can_answer_now: bool,
) -> dict[str, Any]:
    if not bool(hard_gate.get("blocked")):
        return dict(final_surface_fields or {})
    updated = dict(final_surface_fields or {})
    blocker_reason = str(hard_gate.get("validation_state") or "blocked_ai_material_missing").strip()
    blocker = {
        "branch_id": "ai_materialization",
        "planner_family": "ai",
        "origin_families": ["ai"],
        "destination_key": "ai_materialization",
        "destination_id": "ai_materialization",
        "label": "AI materialization",
        "state": "blocked",
        "state_reason": blocker_reason,
        "semantic_order_index": None,
        "blockers": list(hard_gate.get("blockers") or []),
    }
    existing = [
        dict(item or {})
        for item in list(updated.get("final_closure_blockers") or [])
        if isinstance(item, dict) and str((item or {}).get("destination_id") or "") != "ai_materialization"
    ]
    blockers = [blocker] + existing
    histogram = dict(updated.get("closure_blocker_reason_histogram") or {})
    histogram[blocker_reason] = int(histogram.get(blocker_reason) or 0) + 1
    updated["final_closure_ready"] = False
    updated["closure_state"] = "open"
    updated["final_closure_blockers"] = blockers[:16]
    updated["closure_blocker_reason_histogram"] = histogram
    updated["unresolved_destination_count"] = max(1, int(updated.get("unresolved_destination_count") or 0), len(blockers))
    updated["answer_surface_state"] = (
        "answer_now_and_continue"
        if can_answer_now
        else ("context_level_1_ready" if bool(updated.get("context_level_1_ready")) else "not_ready")
    )
    updated["answer_now_before_exploration_complete"] = bool(can_answer_now)
    updated["final_closure_after_destination_resolution"] = False
    return updated


def _sync_answer_demo_materialization_with_final_contract(
    answer_demo_materialization: dict[str, Any] | None,
    *,
    answer_demo_requested: bool,
    answer: dict[str, Any] | None,
    answer_short: str | None,
    answer_full: str | None,
    context_package: dict[str, Any] | None,
    context_package_materialization: dict[str, Any] | None,
    ai_materialization_hard_gate: dict[str, Any] | None,
    final_surface_fields: dict[str, Any] | None,
    answer_demo_from_context_package: bool,
    answer_demo_replaced_misaligned_surface: bool,
) -> dict[str, Any]:
    materialization = dict(answer_demo_materialization or {})
    package = dict(context_package or {})
    package_contract = dict(package.get("contract") or {})
    package_materialization = dict(context_package_materialization or {})
    hard_gate = dict(ai_materialization_hard_gate or {})
    answer_payload = dict(answer or {})
    contract_passed = bool(package_contract.get("passed") or package_materialization.get("contract_passed"))
    from_package = bool(
        answer_demo_from_context_package
        or answer_payload.get("context_package_answer_demo")
        or materialization.get("from_context_package")
    )
    short_text = clean_answer_surface_text(answer_short)
    full_text = clean_answer_surface_text(answer_full)
    content_ready = bool(short_text or full_text or clean_answer_surface_text(answer_payload.get("answer_text")))

    materialization.update(
        {
            "schema_version": "agvm.answer_demo_materialization.v1",
            "requested": bool(answer_demo_requested),
            "from_context_package": bool(from_package),
            "replaced_misaligned_surface": bool(
                answer_demo_replaced_misaligned_surface or materialization.get("replaced_misaligned_surface")
            ),
            "context_package_contract_passed": bool(contract_passed),
            "context_package_is_source_of_truth": True,
            "answer_demo_is_secondary": True,
        }
    )
    if not answer_demo_requested:
        materialization.update(
            {
                "state": "not_requested",
                "reason": "mcp_context_package_only",
                "blocked_by_ai_materialization_hard_gate": False,
            }
        )
        return materialization
    if bool(hard_gate.get("blocked")):
        state = str(hard_gate.get("validation_state") or materialization.get("state") or "blocked_ai_material_missing")
        materialization.update(
            {
                "state": state,
                "reason": "ai_materialization_hard_gate_blocked_final_answer_demo",
                "blocked_by_ai_materialization_hard_gate": True,
                "hard_gate_state": state,
                "hard_gate_blockers": list(hard_gate.get("blockers") or []),
            }
        )
        return materialization

    materialization["blocked_by_ai_materialization_hard_gate"] = False
    if contract_passed and from_package and content_ready:
        final_ready = bool(dict(final_surface_fields or {}).get("final_closure_ready"))
        materialization.update(
            {
                "state": "ready" if final_ready else "materialized_unsealed",
                "reason": "answer_demo_materialized" if final_ready else "answer_demo_materialized_but_final_closure_open",
                "source": "approved_mcp_context_package",
                "answer_context_aligned": True,
            }
        )
    elif contract_passed and not content_ready:
        materialization.update(
            {
                "state": "context_ready_answer_pending",
                "reason": "approved_context_package_ready_but_answer_demo_not_materialized",
            }
        )
    elif not contract_passed:
        materialization.update(
            {
                "state": "blocked_context_contract",
                "reason": "context_package_contract_not_satisfied",
            }
        )
    return materialization


_UNKNOWN_SECTION_LABELS = {
    "identity": "identita",
    "work": "lavoro e aziende",
    "relationships": "relazioni",
    "style": "stile di comunicazione",
    "values": "valori",
    "history": "storia e timeline",
    "temporal_inventory": "riferimenti temporali",
    "documents": "documenti/fonti",
}


def _has_active_or_pending_branch(branches: list[dict[str, Any]] | None) -> bool:
    active_states = {"active", "running", "pending", "planned", "open"}
    for branch in list(branches or []):
        status = str((branch or {}).get("status") or "").strip().lower()
        if status in active_states:
            return True
    return False


def _build_unknown_not_in_memory_answer(
    *,
    query_text: str,
    unresolved_sections: list[str],
    context_package: dict[str, Any] | None,
    retrieval_mode: str = "balanced",
) -> dict[str, Any]:
    partial_known_answer = build_partial_known_answer_demo_from_mcp_context_package(
        query_text=query_text,
        context_package=context_package,
        unresolved_sections=unresolved_sections,
        retrieval_mode=retrieval_mode,
    )
    if partial_known_answer:
        return partial_known_answer

    labels = [_UNKNOWN_SECTION_LABELS.get(section, section.replace("_", " ")) for section in unresolved_sections]
    missing_label = ", ".join(labels) if labels else "informazione richiesta"
    first_person_query = bool(
        any(
            marker in _fold_text(query_text)
            for marker in (
                "tu",
                "ti",
                "te",
                "tuo",
                "tua",
                "tuoi",
                "tue",
                "mi chiamo",
                "sei",
                "fai",
                "your",
                "you",
            )
        )
    )
    prefix = "Non trovo nella memoria" if first_person_query else "La memoria non contiene"
    answer_text = (
        f"{prefix} evidenza affidabile per: {missing_label}. "
        "Per questo non chiudo quella parte come fatto certo."
    )
    sections = [
        str((section or {}).get("title") or section.get("key") or "").strip()
        for section in list((context_package or {}).get("sections") or [])
        if isinstance(section, dict) and str((section or {}).get("title") or section.get("key") or "").strip()
    ]
    if sections:
        answer_text += f" Il context package approvato copre invece: {', '.join(sections[:4])}."
    return {
        "answer_text": answer_text,
        "mode": "insufficient",
        "confidence": 0.0,
        "evidence_node_ids": [],
        "reasoning_summary": "Terminal insufficient answer: required context sections remained unresolved after route exploration and no supported answer was available.",
        "insufficient": True,
        "answerability_state": "insufficient",
        "evidence_snippets": [],
        "support_node_count": 0,
        "support_slot_count": 0,
        "family_attribution_summary": {},
        "contradiction_present": False,
        "answer_adequacy": {
            "passed": True,
            "unknown_not_in_memory": True,
            "missing_required_sections": list(unresolved_sections),
            "context_ledger_leak": False,
            "off_contract_topics": [],
        },
    }


def normalize_retrieve_response_payload(result: dict[str, Any]) -> dict[str, Any]:
    normalized = dict(result or {})
    if not isinstance(normalized.get("probes"), list):
        normalized["probes"] = []
    if not isinstance(normalized.get("matches"), list):
        normalized["matches"] = []
    if not isinstance(normalized.get("visited_node_ids"), list):
        normalized["visited_node_ids"] = []
    if not isinstance(normalized.get("visited_bucket_keys"), list):
        normalized["visited_bucket_keys"] = []
    if not str(normalized.get("stop_reason") or "").strip():
        normalized["stop_reason"] = "snapshot_result"
    normalized_branches: list[dict[str, Any]] = []
    for branch in list(normalized.get("branches") or []):
        branch_payload = dict(branch or {})
        branch_payload["active_destination"] = _canonical_active_destination(branch_payload.get("active_destination"))
        normalized_branches.append(branch_payload)
    normalized["branches"] = normalized_branches
    normalized_steps: list[dict[str, Any]] = []
    for step in list(normalized.get("steps") or []):
        step_payload = dict(step or {})
        step_payload["active_destination"] = _canonical_active_destination(step_payload.get("active_destination"))
        normalized_steps.append(step_payload)
    normalized["steps"] = normalized_steps
    landing_metadata = [
        dict(record)
        for record in list(normalized.get("landing_metadata") or [])
        if isinstance(record, dict)
    ]
    if not landing_metadata:
        landing_metadata = build_landing_metadata(
            [dict(probe) for probe in list(normalized.get("probes") or []) if isinstance(probe, dict)],
            normalized_branches,
        )
    normalized["landing_metadata"] = landing_metadata
    planner_runtime = dict(normalized.get("planner_runtime") or {})
    planner_runtime["landing_metadata_count"] = len(landing_metadata)
    planner_runtime.setdefault("branch_count", len(normalized_branches))
    normalized["planner_runtime"] = planner_runtime
    normalized.setdefault("semantic_contract", dict(planner_runtime.get("semantic_contract") or {}))
    normalized.setdefault("semantic_contract_runtime", dict(planner_runtime.get("semantic_contract_runtime") or {}))
    valid_document_lookup_kinds = {
        "none",
        "exact_document_lookup",
        "related_document_lookup",
        "document_synthesis",
        "source_trace_for_answer",
        "no_document_found",
    }
    document_lookup_kind_value = str(normalized.get("document_lookup_kind") or "").strip()
    if document_lookup_kind_value == "related_documents":
        document_lookup_kind_value = "related_document_lookup"
    if document_lookup_kind_value not in valid_document_lookup_kinds:
        document_lookup_kind_value = "none"
    normalized["document_lookup_kind"] = document_lookup_kind_value
    normalized.setdefault("document_lookup", {})
    normalized.setdefault("supporting_documents", [])
    normalized.setdefault("source_trace", [])
    normalized.setdefault("document_workspace", {})
    context_package_for_documents = dict(normalized.get("context_package") or {})
    document_workspace_for_documents = dict(normalized.get("document_workspace") or {})
    normalized.setdefault("document_text_policy", str(context_package_for_documents.get("document_text_policy") or "refs_only"))
    normalized.setdefault(
        "document_refs",
        list(context_package_for_documents.get("document_refs") or document_workspace_for_documents.get("document_refs") or []),
    )
    normalized.setdefault(
        "document_ref_contract",
        dict(context_package_for_documents.get("document_ref_contract") or document_workspace_for_documents.get("document_ref_contract") or {}),
    )
    normalized.setdefault(
        "document_delivery_contract",
        dict(context_package_for_documents.get("document_delivery_contract") or document_workspace_for_documents.get("document_delivery_contract") or {}),
    )
    normalized.setdefault("document_bundle", dict(context_package_for_documents.get("document_bundle") or {}))
    normalized.setdefault("warm_followup_economy", {})
    normalized.setdefault(
        "warm_context_carryover",
        dict(planner_runtime.get("warm_context_carryover") or dict((normalized.get("warm_followup_economy") or {}).get("warm_context_carryover") or {})),
    )
    answer = dict(normalized.get("answer") or {}) if isinstance(normalized.get("answer"), dict) else normalized.get("answer")
    if isinstance(answer, dict):
        answer.setdefault("mode", "grounded_facts")
        answer.setdefault("confidence", 0.0)
        answer.setdefault("reasoning_summary", "Answer surface was generated from the current grounded evidence snapshot.")
        answer.setdefault("evidence_node_ids", [])
        answer.setdefault("insufficient", False)
        answer.setdefault("answerability_state", "grounded")
        answer.setdefault("evidence_snippets", list(normalized.get("evidence_snippets") or answer.get("evidence_snippets") or []))
        answer.setdefault("document_lookup_kind", normalized.get("document_lookup_kind") or "none")
        answer.setdefault("document_lookup", dict(normalized.get("document_lookup") or {}))
        answer.setdefault("supporting_documents", list(normalized.get("supporting_documents") or []))
        answer.setdefault("source_trace", list(normalized.get("source_trace") or []))
        normalized["answer"] = answer
    context = normalized.get("context")
    if isinstance(context, dict):
        context_payload = dict(context)
        if not str(context_payload.get("context_summary") or "").strip():
            section_items: list[str] = []
            for section in list(context_payload.get("structured_sections") or []):
                if not isinstance(section, dict):
                    continue
                for item in list(section.get("items") or []):
                    if isinstance(item, dict):
                        text = str(item.get("text") or item.get("summary") or "").strip()
                    else:
                        text = str(item or "").strip()
                    if text:
                        section_items.append(text)
                    if len(section_items) >= 3:
                        break
                if len(section_items) >= 3:
                    break
            context_payload["context_summary"] = " ".join(section_items)[:1200].strip()
        context_payload.setdefault("context_fragments", [])
