def _document_lookup_terms(query_text: str) -> list[str]:
    folded = _fold_text(query_text)
    folded = re.sub(
        r"\b(?:trova(?:mi)?|cerca|recupera(?:mi)?|mostra(?:mi)?|apri(?:mi)?|scarica|ritrova|secondo|riassumi|sintetizza)\b",
        " ",
        folded,
    )
    tokens: list[str] = []
    source_tokens = re.findall(r"[a-z0-9]+", folded)
    for token in source_tokens:
        if len(token) < 3 or token in _DOCUMENT_LOOKUP_STOPWORDS:
            continue
        if token not in tokens:
            tokens.append(token)
    token_set = set(source_tokens)
    bridge_terms: list[str] = []
    if "weight" in token_set:
        if "low" in token_set or "under" in token_set:
            bridge_terms.append("underweight")
        if "high" in token_set or "over" in token_set:
            bridge_terms.append("overweight")
    if "blood" in token_set and ("level" in token_set or "levels" in token_set):
        bridge_terms.extend(["serum", "plasma"])
    for term in bridge_terms:
        if term not in tokens and term not in _DOCUMENT_LOOKUP_STOPWORDS:
            tokens.append(term)
    return tokens[:20]


