_DOCUMENT_PACKET_INLINE_RAW_TEXT_LIMIT = 12000
_DOCUMENT_PACKET_INLINE_CHUNK_TEXT_LIMIT = 2400


def _cap_document_inline_text(value: Any, *, limit: int) -> tuple[str, int, bool]:
    text = str(value or "").strip()
    full_chars = len(text)
    if full_chars <= max(0, int(limit)):
        return text, full_chars, False
    capped = text[: max(0, int(limit))].rstrip()
    return capped, full_chars, True


def _cap_document_packet_inline_payload(packet: dict[str, Any]) -> dict[str, Any]:
    """Keep MCP/context packets bounded while preserving raw-document availability metadata."""
    capped_packet = dict(packet or {})
    anchor_text, anchor_full_chars, anchor_truncated = _cap_document_inline_text(
        capped_packet.get("anchor_raw_text"),
        limit=_DOCUMENT_PACKET_INLINE_RAW_TEXT_LIMIT,
    )
    if anchor_text or capped_packet.get("anchor_raw_text"):
        capped_packet["anchor_raw_text"] = anchor_text
        capped_packet["anchor_raw_text_full_char_count"] = anchor_full_chars
        capped_packet["anchor_raw_text_included_char_count"] = len(anchor_text)
        capped_packet["anchor_raw_text_truncated"] = bool(anchor_truncated)
        capped_packet["raw_inline_limit"] = _DOCUMENT_PACKET_INLINE_RAW_TEXT_LIMIT
    capped_chunks: list[dict[str, Any]] = []
    for chunk in list(capped_packet.get("ordered_chunk_sequence") or []):
        if not isinstance(chunk, dict):
            continue
        row = dict(chunk)
        for field in ("raw_text", "evidence_snippet", "text"):
            if field not in row:
                continue
            capped, full_chars, truncated = _cap_document_inline_text(
                row.get(field),
                limit=_DOCUMENT_PACKET_INLINE_CHUNK_TEXT_LIMIT,
            )
            row[field] = capped
            if truncated:
                row[f"{field}_full_char_count"] = full_chars
                row[f"{field}_included_char_count"] = len(capped)
                row[f"{field}_truncated"] = True
        capped_chunks.append(row)
    capped_packet["ordered_chunk_sequence"] = capped_chunks
    capped_facts: list[dict[str, Any]] = []
    for fact in list(capped_packet.get("supported_fact_text") or []):
        if not isinstance(fact, dict):
            continue
        row = dict(fact)
        for field in ("raw_text", "summary", "text"):
            if field not in row:
                continue
            capped, full_chars, truncated = _cap_document_inline_text(
                row.get(field),
                limit=_DOCUMENT_PACKET_INLINE_CHUNK_TEXT_LIMIT,
            )
            row[field] = capped
            if truncated:
                row[f"{field}_full_char_count"] = full_chars
                row[f"{field}_included_char_count"] = len(capped)
                row[f"{field}_truncated"] = True
        capped_facts.append(row)
    capped_packet["supported_fact_text"] = capped_facts
    return capped_packet


def _document_catalog_unique(values: list[Any] | tuple[Any, ...], *, limit: int = 12) -> list[str]:
    output: list[str] = []
    seen: set[str] = set()
    for value in values:
        text = " ".join(str(value or "").split()).strip(" -|:;,")
        if not text:
            continue
        key = _fold_text(text)
        if not key or key in seen:
            continue
        seen.add(key)
        output.append(text)
        if len(output) >= limit:
            break
    return output


def _clean_document_catalog_title(value: Any) -> str:
    text = " ".join(str(value or "").split()).strip(" -|")
    if not text:
        return ""
    text = re.sub(r"(?i)^\s*(?:document\s+title|documento|source\s+title|title)\s*[:=-]\s*", "", text).strip()
    text = re.sub(r"(?i)^\s*(?:public\s+source|source|fonte)\s*[:=-]\s*", "", text).strip()
    text = re.split(
        r"(?i)\s+(?:public\s+source|source\s+url|source|fonte|expected\s+retrieval\s+behavior)\s*[:=-]\s*",
        text,
        maxsplit=1,
    )[0].strip(" -|")
    return _truncate_prompt_text(text, 180)


def _document_title_from_packet(packet: dict[str, Any]) -> str:
    candidates = [
        str(packet.get("title") or ""),
        str(packet.get("source_label") or ""),
        str(packet.get("anchor_raw_text") or ""),
    ]
    for value in candidates:
        text = str(value or "").strip()
        if not text:
            continue
        metadata_match = re.search(
            r"(?im)^\s*(?:document\s+title|source\s+title|title|titolo)\s*[:=-]\s*(.+?)\s*$",
            text,
        )
        if metadata_match:
            cleaned = _clean_document_catalog_title(metadata_match.group(1))
            if cleaned:
                return cleaned
    for value in candidates[:2]:
        cleaned = _clean_document_catalog_title(value)
        if cleaned:
            return cleaned
    return "Document"


def _document_catalog_text(packet: dict[str, Any]) -> str:
    parts = [
        str(packet.get("title") or ""),
        str(packet.get("source_label") or ""),
        str(packet.get("source_type") or ""),
        str(packet.get("provenance_summary") or ""),
        str(packet.get("anchor_raw_text") or ""),
    ]
    for chunk in list(packet.get("ordered_chunk_sequence") or [])[:12]:
        if isinstance(chunk, dict):
            parts.append(str(chunk.get("raw_text") or chunk.get("evidence_snippet") or ""))
    for fact in list(packet.get("supported_fact_text") or [])[:12]:
        if isinstance(fact, dict):
            parts.append(str(fact.get("raw_text") or fact.get("summary") or ""))
    for match in list(packet.get("top_chunk_matches") or [])[:6]:
        node = dict(match.get("node") or {})
        parts.append(str(match.get("evidence_snippet") or node.get("raw_text") or node.get("summary") or ""))
    for match in list(packet.get("top_fact_matches") or [])[:6]:
        node = dict(match.get("node") or {})
        parts.append(str(match.get("evidence_snippet") or node.get("raw_text") or node.get("summary") or ""))
    return " ".join(part for part in parts if part).strip()


def _document_catalog_candidate_phrases(text: str) -> list[str]:
    candidates: list[str] = []
    original = str(text or "")
    phrase_pattern = r"\b(?:[A-Z][A-Za-z0-9&.'-]+|[A-Z]{2,})(?:\s+(?:[A-Z][A-Za-z0-9&.'-]+|[A-Z]{2,}|of|di|del|della|and|for|the|&)){0,5}\b"
    for match in re.finditer(phrase_pattern, original):
        value = " ".join(match.group(0).split()).strip(" -|:;,.'")
        value = re.sub(r"(?i)^(?:dr|mr|mrs|ms)\.\s+", "", value).strip()
        value = re.sub(r"\s+(?:of|di|del|della|and|for|the|&)$", "", value, flags=re.IGNORECASE).strip()
        if re.search(r"[a-z]\.\s+[A-Z]", match.group(0)):
            continue
        if "." in value:
            continue
        if value:
            candidates.append(value)
    mixed_case_pattern = r"\b[A-Za-z][A-Za-z0-9]*(?:[A-Z][A-Za-z0-9]+|[0-9]+)[A-Za-z0-9]*\b"
    for match in re.finditer(mixed_case_pattern, original):
        value = match.group(0).strip(" -|:;,.'")
        if value:
            candidates.append(value)
    return _document_catalog_unique(candidates, limit=36)


def _document_catalog_entity_tags(text: str) -> list[str]:
    entities: list[str] = []
    for phrase in _document_catalog_candidate_phrases(text):
        folded = _fold_text(phrase)
        if not folded:
            continue
        tokens = folded.split()
        if not tokens or tokens[0] in _DOCUMENT_CATALOG_ENTITY_STOPWORDS:
            continue
        if tokens[-1] in _DOCUMENT_CATALOG_ENTITY_STOPWORDS:
            continue
        if any(token in _DOCUMENT_CATALOG_ENTITY_STOPWORDS for token in tokens) and len(tokens) <= 2:
            continue
        if folded.startswith(("document title", "public source", "source pack", "expected retrieval")):
            continue
        if len(tokens) == 1:
            original = phrase.strip()
            internal_upper = any(char.isupper() for char in original[1:])
            if not (original.isupper() or internal_upper or len(original) >= 4):
                continue
        if len(tokens) > 6:
            continue
        entities.append(phrase)
    return _document_catalog_unique(entities, limit=16)


def _document_catalog_timeline_tags(text: str) -> list[str]:
    tags: list[str] = []
    for year in re.findall(r"\b(?:19|20)\d{2}\b", str(text or "")):
        tags.append(year)
    for date_value in re.findall(r"\b\d{1,2}\s+[A-Z][a-z]+\s+(?:19|20)\d{2}\b", str(text or "")):
        tags.append(date_value)
    for date_value in re.findall(r"\b\d{4}-\d{2}-\d{2}\b", str(text or "")):
        tags.append(date_value)
    return _document_catalog_unique(tags, limit=16)


def _document_catalog_topic_tags(text: str, query_text: str = "") -> list[str]:
    folded = _fold_text(text)
    tags: list[str] = []
    padded = f" {folded} "
    for topic, markers in _DOCUMENT_CATALOG_TOPIC_PATTERNS.items():
        if any(marker in padded for marker in markers):
            tags.append(topic)
    return _document_catalog_unique(tags, limit=16)


def _document_catalog_project_tags(entity_tags: list[str], topic_tags: list[str], text: str) -> list[str]:
    folded_text = _fold_text(text)
    tags: list[str] = []
    for entity in entity_tags:
        folded = _fold_text(entity)
        if not folded:
            continue
        has_project_hint = any(hint in folded_text[max(0, folded_text.find(folded) - 90) : folded_text.find(folded) + len(folded) + 90] for hint in _DOCUMENT_CATALOG_PROJECT_HINTS) if folded in folded_text else False
        has_product_shape = any(char.isupper() for char in str(entity)[1:]) or str(entity).isupper() or len(str(entity).split()) >= 3
        if has_project_hint or has_product_shape:
            tags.append(entity)
    for topic in topic_tags:
        if topic in {"power plant controller", "energy management", "industrial software", "renewable energy"}:
            tags.append(topic)
    return _document_catalog_unique(tags, limit=12)


def _decorate_document_packet_catalog(packet: dict[str, Any], *, query_text: str) -> dict[str, Any]:
    decorated = dict(packet or {})
    title = _document_title_from_packet(decorated)
    decorated["title"] = title
    catalog_text = _document_catalog_text({**decorated, "title": title})
    entity_tags = _document_catalog_entity_tags(catalog_text)
    timeline_tags = _document_catalog_timeline_tags(catalog_text)
    topic_tags = _document_catalog_topic_tags(catalog_text, query_text=query_text)
    project_tags = _document_catalog_project_tags(entity_tags, topic_tags, catalog_text)
    related_node_ids = _document_catalog_unique(
        [
            decorated.get("anchor_node_id"),
            *list(decorated.get("summary_node_ids") or []),
            *list(decorated.get("chunk_node_ids") or []),
            *list(decorated.get("fact_node_ids") or []),
            *[
                _document_chunk_evidence_node_id(dict(chunk))
                for chunk in list(decorated.get("ordered_chunk_sequence") or [])
                if isinstance(chunk, dict)
            ],
            *[
                str(fact.get("node_id") or "")
                for fact in list(decorated.get("supported_fact_text") or [])
                if isinstance(fact, dict)
            ],
        ],
        limit=24,
    )
    chunk_count = len(list(decorated.get("ordered_chunk_sequence") or [])) or int((decorated.get("coverage") or {}).get("chunk_count") or 0)
    fact_count = len(list(decorated.get("supported_fact_text") or [])) or int((decorated.get("coverage") or {}).get("fact_count") or 0)
    decorated["entity_tags"] = entity_tags
    decorated["project_tags"] = project_tags
    decorated["timeline_tags"] = timeline_tags
    decorated["topic_tags"] = topic_tags
    decorated["related_node_ids"] = related_node_ids
    decorated["chunks_count"] = int(chunk_count)
    decorated["facts_count"] = int(fact_count)
    decorated["summary_count"] = len(list(decorated.get("summary_node_ids") or [])) or int((decorated.get("coverage") or {}).get("summary_count") or 0)
    decorated["raw_text_available"] = bool(decorated.get("complete_text_available")) or int(decorated.get("raw_text_char_count") or 0) > 0
    decorated["catalog_index"] = {
        "title": title,
        "source_label": decorated.get("source_label"),
        "source_type": decorated.get("source_type"),
        "source_trust": decorated.get("source_trust"),
        "project_tags": project_tags,
        "entity_tags": entity_tags,
        "timeline_tags": timeline_tags,
        "topic_tags": topic_tags,
        "related_node_ids": related_node_ids,
        "chunks_count": int(chunk_count),
        "facts_count": int(fact_count),
        "raw_text_available": bool(decorated["raw_text_available"]),
        "raw_text_char_count": int(decorated.get("raw_text_char_count") or 0),
    }
    return decorated


def _document_packet_query_fit(query_text: str, packet: dict[str, Any]) -> float:
    terms = _document_lookup_terms(query_text)
    if not terms:
        return 0.0
    text_parts = [
        str(packet.get("title") or ""),
        str(packet.get("source_label") or ""),
        str(packet.get("source_type") or ""),
        str(packet.get("anchor_raw_text") or ""),
        " ".join(str(item) for item in list(packet.get("project_tags") or [])),
        " ".join(str(item) for item in list(packet.get("entity_tags") or [])),
        " ".join(str(item) for item in list(packet.get("timeline_tags") or [])),
        " ".join(str(item) for item in list(packet.get("topic_tags") or [])),
    ]
    for chunk in list(packet.get("ordered_chunk_sequence") or [])[:6]:
        if isinstance(chunk, dict):
            text_parts.append(str(chunk.get("raw_text") or chunk.get("evidence_snippet") or ""))
    for fact in list(packet.get("supported_fact_text") or [])[:6]:
        if isinstance(fact, dict):
            text_parts.append(str(fact.get("raw_text") or fact.get("summary") or ""))
    folded_text = _fold_text(" ".join(text_parts))
    matched_terms = [term for term in terms if term in folded_text]
    overlap = len(matched_terms) / max(1, len(terms))
    phrase = " ".join(terms[: min(8, len(terms))])
    phrase_bonus = 0.22 if phrase and phrase in folded_text else 0.0
    lead_pair_bonus = 0.14 if len(terms) >= 2 and all(term in folded_text for term in terms[:2]) else 0.0
    anchor_bonus = 0.08 if str(packet.get("anchor_raw_text") or "").strip() and overlap >= 0.5 else 0.0
    requested_years = [term for term in terms if re.fullmatch(r"(?:19|20)\d{2}", term)]
    timeline_bonus = 0.1 if requested_years and all(term in folded_text for term in requested_years) else 0.0
    tag_bonus = 0.08 if matched_terms and any(
        term in _fold_text(" ".join(str(item) for item in list(packet.get(key) or [])))
        for term in matched_terms
        for key in ("project_tags", "entity_tags", "topic_tags")
    ) else 0.0
    company_affiliation_bonus = 0.0
    if _is_company_goal_query(query_text):
        company_affiliation_bonus = 0.28 * _company_affiliation_signal_score(" ".join(text_parts))
    return round(min(1.0, overlap + phrase_bonus + lead_pair_bonus + anchor_bonus + timeline_bonus + tag_bonus + company_affiliation_bonus), 6)


_DOCUMENT_LOOKUP_TOPIC_SYNONYMS = {
    "acquisition": (
        "acquired",
        "acquiring",
        "acquisition",
        "acquisizione",
        "acquisito",
        "acquisita",
        "acquisisce",
        "transaction",
        "takeover",
    ),
    "founding": (
        "founded",
        "founder",
        "fonda",
        "fondato",
        "fondata",
        "founded by",
        "established",
        "created",
    ),
    "partnership": (
        "partnership",
        "collaboration",
        "collaborazione",
        "agreement",
        "accordo",
        "alliance",
    ),
    "investment": (
        "investment",
        "investimento",
        "funding",
        "round",
        "capital",
        "venture",
    ),
    "release": (
        "release",
        "press release",
        "announced",
        "annuncia",
        "announced that",
        "news",
    ),
}


def _document_lookup_requested_topics(query_text: str) -> list[str]:
    folded = _fold_text(query_text)
    topics: list[str] = []
    for topic, markers in _DOCUMENT_LOOKUP_TOPIC_SYNONYMS.items():
        if any(marker in folded for marker in markers):
            topics.append(topic)
    if _is_company_goal_query(query_text):
        for topic in ("founding", "acquisition", "partnership"):
            if topic not in topics:
                topics.append(topic)
    return topics


def _document_packet_ranking_features(query_text: str, packet: dict[str, Any]) -> dict[str, Any]:
    terms = _document_lookup_terms(query_text)
    if not terms:
        return {
            "schema_version": "agvm.document_packet_rank.v1",
            "score": 0.0,
            "matched_terms": [],
            "missing_terms": [],
            "requested_years": [],
            "requested_topics": [],
            "reasons": ["no_query_terms"],
        }
    title = _fold_text(packet.get("title") or "")
    source = _fold_text(" ".join([str(packet.get("source_label") or ""), str(packet.get("source_type") or ""), str(packet.get("source_trust") or "")]))
    tags = _fold_text(
        " ".join(
            str(item)
            for key in ("project_tags", "entity_tags", "timeline_tags", "topic_tags")
            for item in list(packet.get(key) or [])
        )
    )
    body = _fold_text(_document_packet_full_text(packet))
    all_text = " ".join([title, source, tags, body]).strip()
    requested_years = [term for term in terms if re.fullmatch(r"(?:19|20)\d{2}", term)]
    requested_topics = _document_lookup_requested_topics(query_text)
    topic_marker_text = " ".join(
        marker
        for topic in requested_topics
        for marker in _DOCUMENT_LOOKUP_TOPIC_SYNONYMS.get(topic, ())
    )
    topic_terms = {
        token
        for token in re.findall(r"[a-z0-9]+", _fold_text(topic_marker_text))
        if len(token) >= 3
    }
    entity_terms = [
        term
        for term in terms
        if term not in requested_years and term not in topic_terms
    ]

    def fit(scope_text: str, scoped_terms: list[str] | set[str] | tuple[str, ...]) -> float:
        scoped = [term for term in scoped_terms if str(term or "").strip()]
        if not scoped:
            return 0.0
        return len([term for term in scoped if term in scope_text]) / max(1, len(scoped))

    matched_terms = [term for term in terms if term in all_text]
    missing_terms = [term for term in terms if term not in all_text]
    title_fit = fit(title, terms)
    source_fit = fit(source, terms)
    body_fit = fit(all_text, terms)
    entity_fit = fit(" ".join([title, source, tags, body]), entity_terms)
    year_fit = fit(all_text, requested_years)
    topic_fit = 0.0
    if requested_topics:
        topic_hits = 0
        for topic in requested_topics:
            markers = _DOCUMENT_LOOKUP_TOPIC_SYNONYMS.get(topic, ())
            if topic in tags or any(_fold_text(marker) in all_text for marker in markers):
                topic_hits += 1
        topic_fit = topic_hits / max(1, len(requested_topics))
    company_affiliation_fit = _company_affiliation_signal_score(all_text) if _is_company_goal_query(query_text) else 0.0
    official_source_bonus = 0.0
    if any(marker in source for marker in ("press", "release", "official", "primary", "company", "website", "pdf")):
        official_source_bonus = 0.04
    raw_bonus = 0.03 if bool(packet.get("complete_text_available") or packet.get("full_text") or packet.get("anchor_raw_text")) else 0.0
    existing_fit = max(
        float(packet.get("query_fit_score") or 0.0),
        float(packet.get("exact_match_score") or 0.0),
        float(dict(packet.get("document_claim_rank") or {}).get("score") or 0.0),
    )
    year_penalty = 0.0
    if requested_years and year_fit < 1.0:
        year_penalty += 0.18
        packet_years = set(re.findall(r"\b(?:19|20)\d{2}\b", " ".join([tags, body, title, source])))
        if packet_years and not set(requested_years).issubset(packet_years):
            year_penalty += 0.08
    topic_penalty = 0.08 if requested_topics and topic_fit <= 0.0 else 0.0
    score = (
        0.22 * body_fit
        + 0.16 * title_fit
        + 0.10 * source_fit
        + 0.20 * entity_fit
        + (0.14 * year_fit if requested_years else 0.06)
        + (0.10 * topic_fit if requested_topics else 0.04)
        + 0.12 * company_affiliation_fit
        + 0.08 * existing_fit
        + official_source_bonus
        + raw_bonus
        - year_penalty
        - topic_penalty
    )
    score = round(max(0.0, min(1.0, score)), 6)
    reasons: list[str] = []
    if title_fit >= 0.5:
        reasons.append("title_matches_query_terms")
    if source_fit >= 0.5:
        reasons.append("source_matches_query_terms")
    if entity_fit >= 0.75:
        reasons.append("entities_match")
    if requested_years and year_fit >= 1.0:
        reasons.append("requested_years_match")
    if requested_topics and topic_fit >= 1.0:
        reasons.append("requested_topic_matches")
    if company_affiliation_fit >= 0.55:
        reasons.append("company_affiliation_relation_shape")
    if official_source_bonus:
        reasons.append("official_source_shape")
    if year_penalty:
        reasons.append("requested_year_missing_or_conflicting")
    if topic_penalty:
        reasons.append("requested_topic_missing")
    return {
        "schema_version": "agvm.document_packet_rank.v1",
        "score": score,
        "matched_terms": matched_terms[:16],
        "missing_terms": missing_terms[:16],
        "requested_years": requested_years,
        "requested_topics": requested_topics,
        "title_fit": round(title_fit, 6),
        "source_fit": round(source_fit, 6),
        "body_fit": round(body_fit, 6),
        "entity_fit": round(entity_fit, 6),
        "year_fit": round(year_fit, 6),
        "topic_fit": round(topic_fit, 6),
        "company_affiliation_fit": round(company_affiliation_fit, 6),
        "existing_fit": round(existing_fit, 6),
        "official_source_bonus": round(official_source_bonus, 6),
        "raw_bonus": round(raw_bonus, 6),
        "penalty": round(year_penalty + topic_penalty, 6),
        "reasons": reasons,
    }


def _document_lookup_requested_label(query_text: str) -> str:
    return "documento/PDF esplicito" if " pdf " in f" {_fold_text(query_text)} " else "documento esplicito"


def _document_lookup_max_packet_fit(document_packets: list[dict[str, Any]] | None) -> float:
    return max(
        [
            max(
                float(dict(packet or {}).get("query_fit_score") or dict(packet or {}).get("query_fit") or 0.0),
                float(dict(packet or {}).get("exact_match_score") or 0.0),
                float(dict(packet or {}).get("document_rank_score") or 0.0),
            )
            for packet in list(document_packets or [])
        ]
        or [0.0]
    )


def _document_query_wants_source_trace(query_text: str) -> bool:
    lowered = _fold_text(query_text)
    padded = f" {lowered} "
    has_document_or_source = any(
        token in lowered
        for token in (
            "documento",
            "documenti",
            "document",
            "documents",
            "fonte",
            "fonti",
            "source",
            "sources",
            "evidence",
        )
    )
    has_support_verbs = any(
        token in lowered
        for token in (
            "supporta",
            "supportano",
            "dimostra",
            "dimostrano",
            "provano",
            "prova",
            "conferma",
            "confermano",
            "giustifica",
            "giustificano",
            "lo dimostrano",
            "lo provano",
            "lo confermano",
            "prove this",
            "prove that",
            "support this",
            "support that",
            "confirm this",
            "confirm that",
            "back this",
            "back that",
        )
    )
    return any(
        token in lowered
        for token in (
            "source trace",
            "traccia sorgente",
            "traccia fonte",
            "traccia fonti",
            "traccia delle fonti",
            "fonti della risposta",
            "fonti usate",
            "documenti supportano",
            "documenti che supportano",
            "quali fonti",
            "quali documenti supportano",
            "support documents",
            "supporting documents",
            "sources for the answer",
        )
    ) or " fonti " in padded and " risposta " in padded or bool(has_document_or_source and has_support_verbs)


def _document_query_wants_related_catalog(query_text: str) -> bool:
    lowered = _fold_text(query_text)
    padded = f" {lowered} "
    has_plural_document = any(token in padded for token in (" documenti ", " documents ", " files "))
    has_related_action = any(
        token in lowered
        for token in (
            "relativi",
            "relative",
            "correlati",
            "collegati",
            "su ",
            "parlano",
            "riguardano",
            "related",
            "about",
            "supportano",
            "mostrami",
            "quali documenti",
        )
    )
    return bool(has_plural_document and has_related_action)


def _document_lookup_target_text(query_text: str) -> str:
    raw = str(query_text or "").strip()
    if ":" in raw:
        tail = raw.split(":", 1)[1].strip()
        tail = re.split(r"(?i)\b(?:richiesta\s+mcp|mcp\s+request|richiesta|request)\s*:", tail, maxsplit=1)[0].strip()
        tail = tail.strip(" .;:-")
        if tail:
            return tail
    terms = _document_lookup_terms(query_text)
    return " ".join(terms).strip()


def _document_packet_full_text(packet: dict[str, Any]) -> str:
    parts: list[str] = []
    seen: set[str] = set()

    def add(value: Any) -> None:
        text = str(value or "").strip()
        if not text:
            return
        folded = _fold_text(text)
        if folded in seen:
            return
        seen.add(folded)
        parts.append(text)

    anchor_raw_text = str(packet.get("anchor_raw_text") or "").strip()
    chunks = sorted(
        [dict(chunk) for chunk in list(packet.get("ordered_chunk_sequence") or []) if isinstance(chunk, dict)],
        key=lambda chunk: int(chunk.get("chunk_index") or 0),
    )
    anchor_is_inline_preview = bool(packet.get("anchor_raw_text_truncated")) and bool(chunks)
    if anchor_raw_text and not anchor_is_inline_preview:
        add(anchor_raw_text)
    else:
        for chunk in chunks:
            add(chunk.get("raw_text") or chunk.get("evidence_snippet"))
        if not parts:
            for fact in list(packet.get("supported_fact_text") or []):
                if isinstance(fact, dict):
                    add(fact.get("raw_text") or fact.get("summary"))
        if not parts and anchor_raw_text:
            add(anchor_raw_text)
    return "\n\n".join(parts).strip()


def _document_packet_source_trace(packet: dict[str, Any], *, limit: int = 24) -> list[dict[str, Any]]:
    title = str(packet.get("title") or packet.get("source_label") or "Document").strip()
    anchor_node_id = str(packet.get("anchor_node_id") or "").strip()
    source_label = str(packet.get("source_label") or "").strip() or None
    source_type = str(packet.get("source_type") or "").strip() or None
    rows: list[dict[str, Any]] = []
    anchor_raw_text = str(packet.get("anchor_raw_text") or "").strip()
    if anchor_node_id:
        rows.append(
            {
                "anchor_node_id": anchor_node_id,
                "node_id": anchor_node_id,
                "role": "anchor",
                "title": title,
                "source_label": source_label,
                "source_type": source_type,
                "chunk_index": None,
                "source_span_start": None,
                "source_span_end": None,
                "score": None,
                "text_preview": _truncate_prompt_text(anchor_raw_text or title, 700),
            }
        )
    for chunk in sorted(
        [dict(item) for item in list(packet.get("ordered_chunk_sequence") or []) if isinstance(item, dict)],
        key=lambda item: int(item.get("chunk_index") or 0),
    ):
        chunk_text = str(chunk.get("raw_text") or chunk.get("evidence_snippet") or "").strip()
        if not chunk_text:
            continue
        rows.append(
            {
                "anchor_node_id": anchor_node_id,
                "node_id": str(chunk.get("node_id") or chunk.get("source_node_id") or "").strip(),
                "source_node_id": str(chunk.get("source_node_id") or "").strip() or None,
                "role": "chunk",
                "title": title,
                "source_label": source_label,
                "source_type": source_type,
                "chunk_index": chunk.get("chunk_index"),
                "source_span_start": chunk.get("source_span_start"),
                "source_span_end": chunk.get("source_span_end"),
                "score": chunk.get("score"),
                "source_kind": chunk.get("source_kind"),
                "derived": bool(chunk.get("derived")),
                "text_preview": _truncate_prompt_text(chunk_text, 900),
            }
        )
    for fact in list(packet.get("supported_fact_text") or []):
        if not isinstance(fact, dict):
            continue
        fact_text = str(fact.get("raw_text") or fact.get("summary") or "").strip()
        if not fact_text:
            continue
        rows.append(
            {
                "anchor_node_id": anchor_node_id,
                "node_id": str(fact.get("node_id") or "").strip(),
                "role": "fact",
                "title": title,
                "source_label": source_label,
                "source_type": source_type,
                "chunk_index": None,
                "source_span_start": None,
                "source_span_end": None,
                "score": fact.get("score"),
                "text_preview": _truncate_prompt_text(fact_text, 700),
            }
        )
    return rows[:limit]


def _document_packet_exact_match_score(query_text: str, packet: dict[str, Any]) -> float:
    terms = _document_lookup_terms(query_text)
    if not terms:
        return round(float(packet.get("query_fit_score") or 0.0), 6)
    title = _fold_text(packet.get("title") or "")
    source = _fold_text(" ".join([str(packet.get("source_label") or ""), str(packet.get("source_type") or "")]))
    tags = _fold_text(
        " ".join(
            str(item)
            for key in ("project_tags", "entity_tags", "timeline_tags", "topic_tags")
            for item in list(packet.get(key) or [])
        )
    )
    full_text = _fold_text(_document_packet_full_text(packet))
    all_text = " ".join([title, source, tags, full_text]).strip()
    target = _fold_text(_document_lookup_target_text(query_text))
    title_overlap = sum(1 for term in terms if term in title) / max(1, len(terms))
    body_overlap = sum(1 for term in terms if term in all_text) / max(1, len(terms))
    score = float(packet.get("query_fit_score") or 0.0)
    if target and target in title:
        score = max(score, 0.98)
    elif target and target in source:
        score = max(score, 0.92)
    elif target and target in all_text:
        score = max(score, 0.78)
    if title_overlap >= 1.0:
        score = max(score, 0.9)
    elif title_overlap >= 0.66:
        score = max(score, 0.74)
    if body_overlap >= 1.0:
        score = max(score, 0.72)
    elif body_overlap >= 0.66:
        score = max(score, 0.55)
    if any(re.fullmatch(r"(?:19|20)\d{2}", term) for term in terms) and all(term in all_text for term in terms if re.fullmatch(r"(?:19|20)\d{2}", term)):
        score = max(score, min(1.0, score + 0.08))
    return round(min(1.0, score), 6)


def _document_supporting_documents(document_packets: list[dict[str, Any]], *, limit: int = 6) -> list[dict[str, Any]]:
    supporting: list[dict[str, Any]] = []
    for packet in list(document_packets or [])[:limit]:
        packet = dict(packet or {})
        full_text = str(packet.get("full_text") or _document_packet_full_text(packet)).strip()
        query_fit = float(packet.get("query_fit_score") or 0.0)
        exact_match = float(packet.get("exact_match_score") or 0.0)
        supporting.append(
            {
                "anchor_node_id": str(packet.get("anchor_node_id") or ""),
                "title": str(packet.get("title") or packet.get("source_label") or "Document"),
                "source_label": packet.get("source_label"),
                "source_type": packet.get("source_type"),
                "query_fit_score": round(query_fit, 6),
                "exact_match_score": round(exact_match, 6),
                "document_rank_score": round(float(packet.get("document_rank_score") or 0.0), 6),
                "document_rank_reasons": list(packet.get("document_rank_reasons") or [])[:8],
                "chunks_count": int(packet.get("chunks_count") or len(list(packet.get("ordered_chunk_sequence") or [])) or 0),
                "facts_count": int(packet.get("facts_count") or len(list(packet.get("supported_fact_text") or [])) or 0),
                "summary_count": int(packet.get("summary_count") or 0),
                "full_text_available": bool(full_text),
                "complete_text_available": bool(packet.get("complete_text_available")),
                "full_text_mode": str(packet.get("full_text_mode") or "none"),
                "full_text_char_count": len(full_text),
                "source_trace_count": len(list(packet.get("source_trace") or [])),
                "project_tags": list(packet.get("project_tags") or []),
                "entity_tags": list(packet.get("entity_tags") or []),
                "timeline_tags": list(packet.get("timeline_tags") or []),
                "topic_tags": list(packet.get("topic_tags") or []),
                "support_reason": (
                    "query-specific document rank"
                    if float(packet.get("document_rank_score") or 0.0) >= 0.65
                    else "exact title/source match"
                    if exact_match >= 0.75
                    else "related document evidence"
                    if query_fit >= 0.35
                    else "candidate document packet"
                ),
            }
        )
    return supporting


def _build_document_lookup_contract(
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]],
    answer: dict[str, Any] | None,
) -> dict[str, Any]:
    packets = [packet for packet in list(document_packets or []) if isinstance(packet, dict) and packet]
    explicit_document_query = bool(_is_document_lookup_query(query_text) or document_mode != "none")
    wants_source_trace = bool(_document_query_wants_source_trace(query_text) or _query_is_source_trace_followup(query_text))
    max_query_fit = _document_lookup_max_packet_fit(packets)
    max_exact = max([float(packet.get("exact_match_score") or 0.0) for packet in packets] or [0.0])
    no_match = False
    if explicit_document_query and document_mode == "lookup" and not wants_source_trace:
        no_match = not packets or max(max_query_fit, max_exact) < 0.2
    elif explicit_document_query and not packets:
        no_match = True
    if no_match:
        kind = "no_document_found"
    elif not explicit_document_query:
        kind = "none"
    elif wants_source_trace:
        kind = "source_trace_for_answer"
    elif document_mode == "synthesis":
        kind = "document_synthesis"
    elif _document_query_wants_related_catalog(query_text):
        kind = "related_document_lookup"
    elif document_mode == "lookup":
        kind = "exact_document_lookup"
    else:
        kind = "none"
    for packet in packets:
        packet["lookup_role"] = kind if kind != "no_document_found" else "none"
    supporting_documents = _document_supporting_documents(packets)
    source_trace = [
        dict(row)
        for packet in packets[:4]
        for row in list(packet.get("source_trace") or _document_packet_source_trace(packet))
        if isinstance(row, dict)
    ][:48]
    answer_state = str((answer or {}).get("document_lookup_state") or "")
    if kind == "no_document_found":
        state = "no_matching_document_packet"
    elif packets:
        state = "matched"
    elif explicit_document_query:
        state = "no_document_packets_retrieved"
    else:
        state = answer_state or "not_document_query"
    lead_packet = packets[0] if packets else {}
    return {
        "kind": kind,
        "state": state,
        "target_text": _document_lookup_target_text(query_text),
        "document_mode": document_mode,
        "packet_count": len(packets),
        "supporting_document_count": len(supporting_documents),
        "source_trace_count": len(source_trace),
        "max_query_fit_score": round(max_query_fit, 6),
        "max_exact_match_score": round(max_exact, 6),
        "top_anchor_node_id": lead_packet.get("anchor_node_id"),
        "top_title": lead_packet.get("title"),
        "top_source_label": lead_packet.get("source_label"),
        "top_full_text_available": bool(str(lead_packet.get("full_text") or "").strip()),
        "top_complete_text_available": bool(lead_packet.get("complete_text_available")),
        "top_full_text_char_count": len(str(lead_packet.get("full_text") or "")),
        "no_match": bool(kind == "no_document_found"),
        "supporting_documents": supporting_documents,
        "source_trace": source_trace,
    }


def _apply_document_lookup_contract_to_answer(
    answer: dict[str, Any] | None,
    *,
    query_text: str,
    contract: dict[str, Any],
) -> dict[str, Any] | None:
    if not contract or str(contract.get("kind") or "none") == "none":
        return answer
    decorated = dict(answer or {})
    if not decorated:
        decorated = {
            "answer_text": "",
            "mode": "document_lookup_guard",
            "confidence": 0.0,
            "evidence_node_ids": [],
            "reasoning_summary": "Document lookup contract created without an answer payload.",
            "insufficient": False,
            "answerability_state": "partial",
            "evidence_snippets": [],
            "support_node_count": 0,
            "support_slot_count": 0,
            "family_attribution_summary": {},
            "contradiction_present": False,
            "answer_adequacy": {},
        }
    kind = str(contract.get("kind") or "")
    if kind == "no_document_found":
        requested = _document_lookup_requested_label(query_text)
        target = str(contract.get("target_text") or "").strip()
        suffix = f" per '{target}'" if target else ""
        decorated["answer_text"] = f"Non trovo un {requested}{suffix} nella memoria documentale recuperata."
        decorated["mode"] = "document_lookup_guard"
        decorated["confidence"] = min(float(decorated.get("confidence") or 0.0), 0.35)
        decorated["answerability_state"] = "partial"
        decorated["insufficient"] = False
        decorated["document_lookup_state"] = "no_matching_document_packet"
    elif kind == "source_trace_for_answer":
        supporting_documents = [dict(item) for item in list(contract.get("supporting_documents") or []) if isinstance(item, dict)]
        folded_answer = _fold_text(decorated.get("answer_text") or "")
        if supporting_documents and (not folded_answer or folded_answer.startswith("non trovo un documento")):
            titles = _dedupe_limited(
                [str(item.get("title") or item.get("source_label") or "documento").strip() for item in supporting_documents],
                limit=4,
            )
            decorated["answer_text"] = "I documenti principali che supportano questa risposta sono: " + "; ".join(titles) + "."
            decorated["mode"] = "document_lookup_guard"
            decorated["answerability_state"] = "grounded"
            decorated["insufficient"] = False
            decorated["confidence"] = max(float(decorated.get("confidence") or 0.0), min(0.82, 0.48 + 0.08 * len(titles)))
        decorated["document_lookup_state"] = str(contract.get("state") or decorated.get("document_lookup_state") or "matched")
    else:
        decorated["document_lookup_state"] = str(contract.get("state") or decorated.get("document_lookup_state") or "matched")
    decorated["document_lookup_kind"] = str(contract.get("kind") or "none")
    decorated["document_lookup"] = dict(contract)
    decorated["supporting_documents"] = list(contract.get("supporting_documents") or [])
    decorated["source_trace"] = list(contract.get("source_trace") or [])
    if decorated.get("answer_text"):
        decorated["answer_text"] = clean_answer_surface_text(decorated.get("answer_text"))
    return decorated


def _document_lookup_has_no_matching_packet(
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]] | None,
) -> bool:
    return (
        document_mode == "lookup"
        and not bool(_document_query_wants_source_trace(query_text) or _query_is_source_trace_followup(query_text))
        and bool(_document_lookup_terms(query_text))
        and bool(list(document_packets or []))
        and _document_lookup_max_packet_fit(document_packets) < 0.2
    )


def _document_lookup_no_match_closure_ready(
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]] | None,
    shared_evidence: dict[str, Any] | None = None,
) -> bool:
    packets = [dict(packet or {}) for packet in list(document_packets or []) if dict(packet or {})]
    if not _document_lookup_has_no_matching_packet(
        query_text=query_text,
        document_mode=document_mode,
        document_packets=packets,
    ):
        return False
    coverage_by_slot = dict((shared_evidence or {}).get("coverage_by_slot") or {})
    document_coverage = float(coverage_by_slot.get("documents") or 0.0)
    anchor_count = sum(1 for packet in packets if str(packet.get("anchor_node_id") or "").strip())
    chunk_count = sum(len(list(packet.get("ordered_chunk_sequence") or [])) for packet in packets)
    return len(packets) >= 3 or anchor_count >= 2 or chunk_count >= 3 or document_coverage >= 0.6


def _document_lookup_packet_closure_ready(
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]] | None,
    min_fit: float = 0.55,
) -> bool:
    packets = [dict(packet or {}) for packet in list(document_packets or []) if dict(packet or {})]
    if document_mode != "lookup" or not _document_lookup_terms(query_text) or not packets:
        return False
    lead_fit = _document_lookup_max_packet_fit(packets)
    if lead_fit < float(min_fit):
        return False
    for packet in packets:
        packet_fit = max(
            float(packet.get("query_fit_score") or packet.get("query_fit") or 0.0),
            float(packet.get("exact_match_score") or 0.0),
            float(packet.get("document_rank_score") or 0.0),
        )
        if packet_fit < float(min_fit):
            continue
        if (
            bool(packet.get("complete_text_available"))
            or int(packet.get("raw_text_char_count") or 0) > 0
            or str(packet.get("anchor_node_id") or "").strip()
            or list(packet.get("ordered_chunk_sequence") or [])
            or list(packet.get("supported_fact_text") or [])
        ):
            return True
    return False


def _document_synthesis_packet_closure_ready(
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]] | None,
    min_fit: float = 0.35,
) -> bool:
    packets = [dict(packet or {}) for packet in list(document_packets or []) if dict(packet or {})]
    if document_mode != "synthesis" or not packets:
        return False
    for packet in packets:
        coverage = dict(packet.get("coverage") or {})
        match_count = int(coverage.get("match_count") or 0)
        query_fit = float(packet.get("query_fit_score") or packet.get("query_fit") or 0.0)
        has_material = (
            bool(packet.get("complete_text_available"))
            or int(packet.get("raw_text_char_count") or 0) > 0
            or bool(str(packet.get("anchor_node_id") or "").strip())
            or bool(list(packet.get("ordered_chunk_sequence") or []))
            or bool(list(packet.get("supported_fact_text") or []))
        )
        if has_material and (query_fit >= float(min_fit) or match_count >= 2 or bool(packet.get("complete_text_available"))):
            return True
    return False


def _build_document_packets(
    matches: list[dict[str, Any]],
    shared_evidence: dict[str, Any] | None = None,
    query_text: str = "",
    packet_limit: int = 6,
) -> list[dict[str, Any]]:
    bounded_packet_limit = max(1, min(12, int(packet_limit or 6)))
    grouped: dict[str, dict[str, Any]] = {}
    fallback_index = 0
    anchor_ids = [
        str(dict(match.get("node") or {}).get("id") or "")
        for match in matches
        if str((dict(match.get("document_hit") or {}).get("document_role") or dict(match.get("node") or {}).get("document_role") or "")).strip() == "anchor"
        and str(dict(match.get("node") or {}).get("id") or "").strip()
    ]
    lone_anchor_id = anchor_ids[0] if len(anchor_ids) == 1 else None
    for match in matches:
        node = dict(match.get("node") or {})
        if not is_document_eligible(node):
            continue
        document_hit = dict(match.get("document_hit") or {})
        role = str(document_hit.get("document_role") or node.get("document_role") or "").strip()
        source_key = _document_source_key(node)
        if role not in {"anchor", "summary", "chunk", "fact"} and not source_key:
            continue
        group_key = str(document_hit.get("document_anchor_id") or node.get("document_anchor_id") or source_key or "")
        if not group_key and lone_anchor_id and role in {"summary", "chunk", "fact"}:
            group_key = lone_anchor_id
        elif lone_anchor_id and role in {"summary", "chunk", "fact"} and group_key == source_key and source_key and source_key.endswith("::"):
            group_key = lone_anchor_id
        if not group_key:
            fallback_index += 1
            group_key = f"document_group_{fallback_index}"
        provenance = dict(node.get("provenance") or {})
        packet = grouped.setdefault(
            group_key,
            {
                "anchor_node_id": str(document_hit.get("document_anchor_id") or node.get("document_anchor_id") or node.get("id") or group_key),
                "source_label": provenance.get("source_label"),
                "source_type": provenance.get("source_type"),
                "source_trust": node.get("source_trust") or "user_asserted",
                "claim_status": node.get("claim_status") or "fact",
                "answer_eligible": bool(node.get("answer_eligible", True)),
                "profile_eligible": bool(node.get("profile_eligible", True)),
                "document_eligible": bool(node.get("document_eligible", True)),
                "title": str(node.get("summary") or provenance.get("source_label") or node.get("id") or "Document"),
                "summary_node_ids": [],
                "chunk_node_ids": [],
                "fact_node_ids": [],
                "top_chunk_matches": [],
                "top_fact_matches": [],
                "provenance_summary": None,
                "relevance_summary": "",
                "coverage": {"match_count": 0, "chunk_count": 0, "fact_count": 0, "summary_count": 0},
                "open_questions": list((shared_evidence or {}).get("unresolved_slots") or [])[:4],
                "full_text_mode": "none",
                "complete_text_available": False,
                "raw_text_char_count": 0,
                "anchor_raw_text": None,
                "ordered_chunk_sequence": [],
                "supported_fact_text": [],
                "_anchor_match": None,
            },
        )
        packet["coverage"]["match_count"] = int(packet["coverage"].get("match_count") or 0) + 1
        if role == "anchor":
            packet["_anchor_match"] = dict(match)
            packet["anchor_node_id"] = str(node.get("id") or packet["anchor_node_id"])
            packet["title"] = str(node.get("summary") or packet["title"] or "")
        elif role == "summary":
            if str(node.get("id") or "") not in packet["summary_node_ids"]:
                packet["summary_node_ids"].append(str(node.get("id") or ""))
            packet["coverage"]["summary_count"] = int(packet["coverage"].get("summary_count") or 0) + 1
        elif role == "chunk":
            if str(node.get("id") or "") not in packet["chunk_node_ids"]:
                packet["chunk_node_ids"].append(str(node.get("id") or ""))
            packet["coverage"]["chunk_count"] = int(packet["coverage"].get("chunk_count") or 0) + 1
            packet["top_chunk_matches"].append(dict(match))
        elif role == "fact":
            if str(node.get("id") or "") not in packet["fact_node_ids"]:
                packet["fact_node_ids"].append(str(node.get("id") or ""))
            packet["coverage"]["fact_count"] = int(packet["coverage"].get("fact_count") or 0) + 1
            packet["top_fact_matches"].append(dict(match))

    packets: list[dict[str, Any]] = []
    packet_anchor_cache: dict[str, str] = {}
    for packet in grouped.values():
        anchor_match = dict(packet.pop("_anchor_match") or {})
        if anchor_match:
            anchor_node = dict(anchor_match.get("node") or {})
            anchor_document_hit = dict(anchor_match.get("document_hit") or {})
            document_claim_rank = (
                dict(anchor_match.get("document_claim_rank") or {})
                or dict(anchor_document_hit.get("document_claim_rank") or {})
                or dict(anchor_node.get("document_claim_rank") or {})
            )
            packet["title"] = str(anchor_node.get("summary") or packet.get("title") or "Document")
            packet["source_label"] = packet.get("source_label") or dict(anchor_node.get("provenance") or {}).get("source_label")
            packet["source_type"] = packet.get("source_type") or dict(anchor_node.get("provenance") or {}).get("source_type")
            packet["source_trust"] = anchor_node.get("source_trust") or packet.get("source_trust") or "user_asserted"
            packet["claim_status"] = anchor_node.get("claim_status") or packet.get("claim_status") or "fact"
            packet["answer_eligible"] = bool(anchor_node.get("answer_eligible", packet.get("answer_eligible", True)))
            packet["profile_eligible"] = bool(anchor_node.get("profile_eligible", packet.get("profile_eligible", True)))
            packet["document_eligible"] = bool(anchor_node.get("document_eligible", packet.get("document_eligible", True)))
            anchor_raw_text = str(anchor_node.get("raw_text") or "").strip()
            if anchor_raw_text:
                packet["anchor_raw_text"] = anchor_raw_text
            if document_claim_rank:
                packet["document_claim_rank"] = document_claim_rank
        elif str(packet.get("source_label") or "").strip():
            source_label = str(packet.get("source_label") or "").strip()
            source_type = str(packet.get("source_type") or "").strip()
            source_key = f"{source_type.lower()}::{source_label.lower()}"
            if source_key not in packet_anchor_cache:
                try:
                    packet_anchor_cache.update(
                        fetch_document_anchor_ids_by_source_refs(
                            [{"source_label": source_label, "source_type": source_type}]
                        )
                    )
                except Exception:
                    packet_anchor_cache[source_key] = ""
            resolved_anchor_id = str(packet_anchor_cache.get(source_key) or "").strip()
            if resolved_anchor_id:
                packet["anchor_node_id"] = resolved_anchor_id
        chunk_matches = sorted(
            list(packet.get("top_chunk_matches") or []),
            key=lambda item: (
                (dict(item.get("document_hit") or {}).get("source_span_start") is None),
                int(dict(item.get("document_hit") or {}).get("source_span_start") or 0),
                -float(item.get("raw_score") or item.get("score") or 0.0),
            ),
        )
        normalized_chunk_matches: list[dict[str, Any]] = []
        for index, match in enumerate(chunk_matches, start=1):
            node = dict(match.get("node") or {})
            document_hit = dict(match.get("document_hit") or {})
            node["document_chunk_index"] = index
            document_hit["chunk_index"] = index
            normalized_chunk_matches.append({**match, "node": node, "document_hit": document_hit})
        packet["top_chunk_matches"] = normalized_chunk_matches[:4]
        packet["top_fact_matches"] = sorted(
            list(packet.get("top_fact_matches") or []),
            key=lambda item: -float(item.get("raw_score") or item.get("score") or 0.0),
        )[:4]
        ordered_chunk_sequence = []
        for match in normalized_chunk_matches:
            node = dict(match.get("node") or {})
            chunk_raw_text = str(node.get("raw_text") or match.get("evidence_snippet") or node.get("summary") or "").strip()
            if not chunk_raw_text:
                continue
            document_hit = dict(match.get("document_hit") or {})
            ordered_chunk_sequence.append(
                {
                    "node_id": str(match.get("node_id") or ""),
                    "chunk_index": int(document_hit.get("chunk_index") or node.get("document_chunk_index") or 0),
                    "source_span_start": document_hit.get("source_span_start"),
                    "source_span_end": document_hit.get("source_span_end"),
                    "raw_text": chunk_raw_text,
                    "evidence_snippet": str(match.get("evidence_snippet") or chunk_raw_text).strip(),
                    "score": round(float(match.get("raw_score") or match.get("score") or 0.0), 4),
                }
            )
        packet["ordered_chunk_sequence"] = ordered_chunk_sequence
        supported_fact_text = []
        for match in list(packet.get("top_fact_matches") or []):
            if not is_answer_eligible(match):
                continue
            node = dict(match.get("node") or {})
            fact_text = str(node.get("raw_text") or match.get("evidence_snippet") or node.get("summary") or "").strip()
            if not fact_text:
                continue
            supported_fact_text.append(
                {
                    "node_id": str(match.get("node_id") or ""),
                    "summary": str(match.get("summary") or node.get("summary") or "").strip(),
                    "raw_text": fact_text,
                    "score": round(float(match.get("raw_score") or match.get("score") or 0.0), 4),
                }
            )
        packet["supported_fact_text"] = supported_fact_text
        packet["persisted_chunk_count"] = len(ordered_chunk_sequence)
        if not ordered_chunk_sequence:
            anchor_source_node_id = str(packet.get("anchor_node_id") or "").strip()
            anchor_raw_text = str(packet.get("anchor_raw_text") or "").strip()
            if anchor_source_node_id and anchor_raw_text:
                ordered_chunk_sequence = _split_document_text_into_chunks(
                    anchor_raw_text,
                    source_node_id=anchor_source_node_id,
                    max_chars=520,
                    max_chunks=10,
                )
            elif supported_fact_text:
                longest_fact = max(
                    supported_fact_text,
                    key=lambda item: len(str(item.get("raw_text") or item.get("summary") or "")),
                )
                fact_node_id = str(longest_fact.get("node_id") or packet.get("anchor_node_id") or "").strip()
                fact_text = str(longest_fact.get("raw_text") or longest_fact.get("summary") or "").strip()
                if fact_node_id and fact_text:
                    ordered_chunk_sequence = _split_document_text_into_chunks(
                        fact_text,
                        source_node_id=fact_node_id,
                        max_chars=520,
                        max_chunks=6,
                    )
                    for chunk in ordered_chunk_sequence:
                        chunk["source_kind"] = "derived_fact_chunk"
        packet["ordered_chunk_sequence"] = ordered_chunk_sequence
        packet["derived_chunk_count"] = sum(1 for item in ordered_chunk_sequence if bool(item.get("derived")))
        packet["provenance_summary"] = " / ".join(
            [value for value in [str(packet.get("source_label") or "").strip(), str(packet.get("source_type") or "").strip()] if value]
        ) or None
        lead_chunk = packet["top_chunk_matches"][0] if packet["top_chunk_matches"] else None
        lead_fact = packet["top_fact_matches"][0] if packet["top_fact_matches"] else None
        packet["relevance_summary"] = (
            str((lead_chunk or lead_fact or anchor_match).get("reason") or "")
            or f"Document packet with {int(packet['coverage'].get('match_count') or 0)} grounded matches."
        )
        anchor_chars = len(str(packet.get("anchor_raw_text") or ""))
        chunk_chars = sum(len(str(item.get("raw_text") or "")) for item in ordered_chunk_sequence if not bool(item.get("derived")))
        fact_chars = sum(len(str(item.get("raw_text") or "")) for item in supported_fact_text)
        packet["raw_text_char_count"] = anchor_chars + chunk_chars + fact_chars
        if anchor_chars >= max(160, chunk_chars):
            packet["full_text_mode"] = "anchor_raw"
            packet["complete_text_available"] = True
        elif ordered_chunk_sequence:
            packet["full_text_mode"] = "ordered_chunk_sequence"
            packet["complete_text_available"] = True
        elif anchor_chars > 0 or supported_fact_text:
            packet["full_text_mode"] = "mixed_evidence"
            packet["complete_text_available"] = bool(anchor_chars > 0)
        packet = _cap_document_packet_inline_payload(packet)
        packet = _decorate_document_packet_catalog(packet, query_text=query_text)
        claim_rank_score = 0.0
        try:
            claim_rank_score = float(dict(packet.get("document_claim_rank") or {}).get("score") or 0.0)
        except (TypeError, ValueError):
            claim_rank_score = 0.0
        packet["query_fit_score"] = max(_document_packet_query_fit(query_text, packet), claim_rank_score)
        packet["full_text"] = _document_packet_full_text(packet) or None
        packet["exact_match_score"] = _document_packet_exact_match_score(query_text, packet)
        rank_features = _document_packet_ranking_features(query_text, packet)
        packet["document_rank"] = rank_features
        packet["document_rank_score"] = float(rank_features.get("score") or 0.0)
        packet["document_rank_reasons"] = list(rank_features.get("reasons") or [])
        packet["lookup_role"] = "none"
        packet["source_trace"] = _document_packet_source_trace(packet)
        packet["catalog_index"] = {
            **dict(packet.get("catalog_index") or {}),
            "query_fit_score": packet["query_fit_score"],
            "exact_match_score": packet["exact_match_score"],
            "document_rank_score": packet["document_rank_score"],
            "document_rank_reasons": packet["document_rank_reasons"],
            "full_text_available": bool(packet.get("full_text")),
            "source_trace_count": len(list(packet.get("source_trace") or [])),
        }
        packets.append(packet)
    packets.sort(
        key=lambda item: (
            -float(item.get("document_rank_score") or 0.0),
            -float(item.get("exact_match_score") or 0.0),
            -float(item.get("query_fit_score") or 0.0),
            -int((item.get("coverage") or {}).get("match_count") or 0),
            -len(list(item.get("top_chunk_matches") or [])),
            str(item.get("title") or ""),
        )
    )
    if packets:
        document_evidence_lane = rank_document_evidence_candidates(
            query_text=query_text,
            candidates=packets,
            limit=bounded_packet_limit,
            candidate_window=max(48, bounded_packet_limit * 4),
        )
        ranked_packets = [
            dict(packet)
            for packet in list(document_evidence_lane.get("documents") or [])
            if isinstance(packet, dict)
        ]
        if ranked_packets:
            return ranked_packets[:bounded_packet_limit]
    return packets[:bounded_packet_limit]


def _build_document_context(
    *,
    document_mode: str,
    document_packets: list[dict[str, Any]],
    fallback_context: dict[str, Any] | None,
) -> dict[str, Any]:
    if document_mode == "none":
        return dict(fallback_context or {})
    document_items: list[str] = []
    chunk_items: list[str] = []
    fact_items: list[str] = []
    evidence_node_ids: list[str] = []
    context_fragments: list[dict[str, Any]] = []
    for packet in document_packets:
        title = str(packet.get("title") or packet.get("source_label") or "Document").strip()
        anchor_node_id = str(packet.get("anchor_node_id") or "").strip()
        if anchor_node_id and anchor_node_id not in evidence_node_ids:
            evidence_node_ids.append(anchor_node_id)
        summary_line = title
        provenance_summary = str(packet.get("provenance_summary") or "").strip()
        if provenance_summary:
            summary_line = f"{title} | {provenance_summary}"
        if summary_line and summary_line not in document_items:
            document_items.append(summary_line)
        ordered_chunks = [dict(item) for item in list(packet.get("ordered_chunk_sequence") or []) if isinstance(item, dict)]
        if ordered_chunks:
            for chunk in ordered_chunks[:3]:
                snippet = str(chunk.get("raw_text") or chunk.get("evidence_snippet") or "").strip()
                if not snippet:
                    continue
                chunk_label = f"{title}: {_truncate_prompt_text(snippet, 220)}"
                if chunk_label not in chunk_items:
                    chunk_items.append(chunk_label)
                node_id = _document_chunk_evidence_node_id(chunk)
                if node_id and node_id not in evidence_node_ids:
                    evidence_node_ids.append(node_id)
                context_fragments.append(
                    {
                        "topic": title,
                        "text": _truncate_prompt_text(snippet, 280),
                        "confidence": float(chunk.get("score") or 0.0),
                        "evidence_node_ids": [node_id] if node_id else [],
                        "fragment_type": "document_chunk",
                    }
                )
        else:
            for match in list(packet.get("top_chunk_matches") or [])[:3]:
                node = dict(match.get("node") or {})
                snippet = str(match.get("evidence_snippet") or node.get("raw_text") or node.get("summary") or "").strip()
                if not snippet:
                    continue
                chunk_label = f"{title}: {_truncate_prompt_text(snippet, 220)}"
                if chunk_label not in chunk_items:
                    chunk_items.append(chunk_label)
                node_id = str(match.get("node_id") or "")
                if node_id and node_id not in evidence_node_ids:
                    evidence_node_ids.append(node_id)
                context_fragments.append(
                    {
                        "topic": title,
                        "text": _truncate_prompt_text(snippet, 280),
                        "confidence": float(match.get("raw_score") or match.get("score") or 0.0),
                        "evidence_node_ids": [node_id] if node_id else [],
                        "fragment_type": "document_chunk",
                    }
                )
        for match in list(packet.get("top_fact_matches") or [])[:3]:
            fact_text = str(match.get("summary") or dict(match.get("node") or {}).get("summary") or "").strip()
            if not fact_text:
                continue
            fact_label = f"{title}: {fact_text}"
            if fact_label not in fact_items:
                fact_items.append(fact_label)
            node_id = str(match.get("node_id") or "")
            if node_id and node_id not in evidence_node_ids:
                evidence_node_ids.append(node_id)
    sections = [
        {
            "key": "documents",
            "title": "Documents",
            "items": document_items[:6],
            "evidence_node_ids": [str(packet.get("anchor_node_id") or "") for packet in document_packets if str(packet.get("anchor_node_id") or "").strip()],
            "confidence": round(max((float((packet.get("coverage") or {}).get("match_count") or 0) for packet in document_packets), default=0.0), 4),
        },
        {
            "key": "chunks",
            "title": "Chunks",
            "items": chunk_items[:8],
            "evidence_node_ids": evidence_node_ids[:12],
            "confidence": round(min(1.0, max(0.4, len(chunk_items) * 0.12)), 4) if chunk_items else 0.0,
        },
        {
            "key": "facts",
            "title": "Facts",
            "items": fact_items[:8],
            "evidence_node_ids": evidence_node_ids[:12],
            "confidence": round(min(1.0, max(0.4, len(fact_items) * 0.12)), 4) if fact_items else 0.0,
        },
    ]
    sections = [section for section in sections if list(section.get("items") or [])]
    context_summary = " ".join(document_items[:2] + chunk_items[:2])[:1200].strip()
    return {
        "context_summary": context_summary,
        "context_fragments": context_fragments[:12],
        "structured_sections": sections,
        "traits": [],
        "style_cues": [],
        "communication_cues": [],
        "values_cues": [],
        "biographical_cues": [],
        "movement_cues": [],
        "story_points": document_items[:4],
        "open_uncertainties": sorted({item for packet in document_packets for item in list(packet.get("open_questions") or [])})[:6],
        "evidence_node_ids": evidence_node_ids[:16],
    }


def _build_evidence_reservoir(
    *,
    matches: list[dict[str, Any]],
    shared_evidence: dict[str, Any] | None,
    branches: list[dict[str, Any]],
    document_packets: list[dict[str, Any]],
    continuity_state: str = "low_continuity",
    warm_state_used: bool = False,
) -> dict[str, Any]:
    shared_evidence_snapshot = dict(shared_evidence or {})
    contradictions = [str(item).strip() for item in list(shared_evidence_snapshot.get("contradiction_flags") or []) if str(item).strip()]
    fallback_support_slots = [
        str(slot).strip()
        for slot, value in dict(shared_evidence_snapshot.get("coverage_by_slot") or {}).items()
        if str(slot).strip() and float(value or 0.0) > 0.0
    ]
    fallback_branch_goals = [
        str(goal).strip()
        for goal in list(shared_evidence_snapshot.get("covered_goals") or [])
        if str(goal).strip()
    ] or list(fallback_support_slots)
    branch_ids_by_node: dict[str, set[str]] = defaultdict(set)
    branch_goals_by_node: dict[str, set[str]] = defaultdict(set)
    support_slots_by_node: dict[str, set[str]] = defaultdict(set)
    planner_families_by_node: dict[str, set[str]] = defaultdict(set)
    for branch in list(branches or []):
        branch_id = str(branch.get("branch_id") or "").strip()
        goal = str(branch.get("goal") or "").strip()
        planner_families = _families_for_record(branch)
        evidence_node_ids = [str(node_id) for node_id in list(branch.get("evidence_node_ids") or []) if str(node_id).strip()]
        for node_id in evidence_node_ids:
            if branch_id:
                branch_ids_by_node[node_id].add(branch_id)
            if goal:
                branch_goals_by_node[node_id].add(goal)
                support_slots_by_node[node_id].add(goal)
            for planner_family in planner_families:
                planner_families_by_node[node_id].add(planner_family)
    entries: list[dict[str, Any]] = []
    entries_by_node_id: dict[str, dict[str, Any]] = {}
    for match in list(matches or []):
        node = dict(match.get("node") or {})
        node_id = str(match.get("node_id") or node.get("id") or "").strip()
        if not node_id:
            continue
        raw_text = str(node.get("raw_text") or "").strip()
        summary = str(match.get("summary") or node.get("summary") or raw_text).strip()
        evidence_snippet = str(match.get("evidence_snippet") or raw_text or summary).strip()
        provenance = dict(node.get("provenance") or {})
        document_hit = dict(match.get("document_hit") or {})
        document_role = str(document_hit.get("document_role") or node.get("document_role") or "").strip() or None
        document_anchor_id = str(document_hit.get("document_anchor_id") or node.get("document_anchor_id") or "").strip() or None
        match_branch_goals = [
            str(goal).strip()
            for goal in list(match.get("branch_goals") or [])
            if str(goal).strip()
        ]
        match_support_slots = [
            str(slot).strip()
            for slot in list(match.get("support_slots") or [])
            if str(slot).strip()
        ]
        branch_goals = sorted(branch_goals_by_node.get(node_id) or match_branch_goals)
        support_slots = sorted(support_slots_by_node.get(node_id) or match_support_slots)
        document_supported = bool(
            document_hit
            or document_role
            or document_anchor_id
            or bool(node.get("is_document_anchor"))
            or str(node.get("memory_type") or "").strip().lower().startswith("document_")
        )
        if document_supported:
            if "documents" not in branch_goals:
                branch_goals = sorted([*branch_goals, "documents"])
            if "documents" not in support_slots:
                support_slots = sorted([*support_slots, "documents"])
        if warm_state_used:
            if not branch_goals and fallback_branch_goals:
                branch_goals = fallback_branch_goals[:6]
            if not support_slots and fallback_support_slots:
                support_slots = fallback_support_slots[:6]
        entry = {
            "entry_id": f"entry::{node_id}",
            "node_id": node_id,
            "summary": summary,
            "raw_text": raw_text,
            "evidence_snippet": evidence_snippet,
            "memory_type": str(node.get("memory_type") or ""),
            "topic": str(provenance.get("guide_conceptual_area") or node.get("memory_type") or "").strip() or None,
            "provenance": provenance,
            "branch_ids": sorted(branch_ids_by_node.get(node_id) or []),
            "branch_goals": branch_goals,
            "planner_families": sorted(planner_families_by_node.get(node_id) or []),
            "support_slots": support_slots,
            "contradiction_flags": contradictions[:6],
            "score": round(float(match.get("raw_score") or match.get("score") or 0.0), 4),
            "score_source": str(match.get("reason") or "").strip() or None,
            "document_role": document_role,
            "document_anchor_id": document_anchor_id,
            "document_chunk_index": node.get("document_chunk_index"),
            "source_label": provenance.get("source_label"),
            "source_type": provenance.get("source_type"),
            "source_span_start": document_hit.get("source_span_start") if document_hit else node.get("source_span_start"),
            "source_span_end": document_hit.get("source_span_end") if document_hit else node.get("source_span_end"),
            "raw_text_preserved": bool(raw_text),
            "source_trust": node.get("source_trust") or "user_asserted",
            "claim_status": node.get("claim_status") or "fact",
            "answer_eligible": bool(node.get("answer_eligible", True)),
            "profile_eligible": bool(node.get("profile_eligible", True)),
            "document_eligible": bool(node.get("document_eligible", True)),
        }
        entries.append(entry)
        entries_by_node_id[node_id] = entry

    documents: list[dict[str, Any]] = []
    for packet in list(document_packets or []):
        anchor_node_id = str(packet.get("anchor_node_id") or "").strip()
        packet_source_label = str(packet.get("source_label") or "").strip() or None
        packet_source_type = str(packet.get("source_type") or "").strip() or None
        anchor_entry = entries_by_node_id.get(anchor_node_id, {})
        ordered_chunk_sequence = []
        for chunk in list(packet.get("ordered_chunk_sequence") or []):
            node_id = str(chunk.get("node_id") or "").strip()
            source_node_id = _document_chunk_evidence_node_id(dict(chunk))
            entry = entries_by_node_id.get(node_id, {})
            raw_text = str(entry.get("raw_text") or chunk.get("raw_text") or "").strip()
            ordered_chunk_sequence.append(
                {
                    "node_id": node_id,
                    "source_node_id": source_node_id or None,
                    "chunk_index": chunk.get("chunk_index"),
                    "source_span_start": chunk.get("source_span_start"),
                    "source_span_end": chunk.get("source_span_end"),
                    "raw_text": raw_text,
                    "evidence_snippet": str(entry.get("evidence_snippet") or chunk.get("evidence_snippet") or raw_text).strip(),
                    "score": round(float(entry.get("score") or chunk.get("score") or 0.0), 4),
                    "source_kind": str(chunk.get("source_kind") or ("derived_raw_chunk" if bool(chunk.get("derived")) else "persisted_chunk")),
                    "derived": bool(chunk.get("derived")),
                }
            )
        supported_fact_text = []
        for fact in list(packet.get("supported_fact_text") or []):
            node_id = str(fact.get("node_id") or "").strip()
            entry = entries_by_node_id.get(node_id, {})
            supported_fact_text.append(
                {
                    "node_id": node_id,
                    "summary": str(fact.get("summary") or entry.get("summary") or "").strip(),
                    "raw_text": str(entry.get("raw_text") or fact.get("raw_text") or "").strip(),
                    "score": round(float(entry.get("score") or fact.get("score") or 0.0), 4),
                }
            )
        documents.append(
            {
                "anchor_node_id": anchor_node_id or str(anchor_entry.get("node_id") or ""),
                "source_label": packet_source_label,
                "source_type": packet_source_type,
                "source_trust": str(packet.get("source_trust") or anchor_entry.get("source_trust") or "user_asserted"),
                "claim_status": str(packet.get("claim_status") or anchor_entry.get("claim_status") or "fact"),
                "answer_eligible": bool(packet.get("answer_eligible", anchor_entry.get("answer_eligible", True))),
                "profile_eligible": bool(packet.get("profile_eligible", anchor_entry.get("profile_eligible", True))),
                "document_eligible": bool(packet.get("document_eligible", anchor_entry.get("document_eligible", True))),
                "title": str(packet.get("title") or packet_source_label or "Document"),
                "full_text_mode": str(packet.get("full_text_mode") or "none"),
                "complete_text_available": bool(packet.get("complete_text_available")),
                "raw_text_char_count": int(packet.get("raw_text_char_count") or 0),
                "anchor_raw_text": str(packet.get("anchor_raw_text") or anchor_entry.get("raw_text") or "").strip() or None,
                "ordered_chunk_sequence": ordered_chunk_sequence,
                "supported_fact_text": supported_fact_text,
                "provenance_summary": str(packet.get("provenance_summary") or "").strip(),
                "relevance_summary": str(packet.get("relevance_summary") or "").strip(),
                "open_questions": [str(item).strip() for item in list(packet.get("open_questions") or []) if str(item).strip()][:6],
                "query_fit_score": float(packet.get("query_fit_score") or 0.0),
                "project_tags": [str(item).strip() for item in list(packet.get("project_tags") or []) if str(item).strip()][:12],
                "entity_tags": [str(item).strip() for item in list(packet.get("entity_tags") or []) if str(item).strip()][:16],
                "timeline_tags": [str(item).strip() for item in list(packet.get("timeline_tags") or []) if str(item).strip()][:16],
                "topic_tags": [str(item).strip() for item in list(packet.get("topic_tags") or []) if str(item).strip()][:16],
                "related_node_ids": [str(item).strip() for item in list(packet.get("related_node_ids") or []) if str(item).strip()][:24],
                "chunks_count": int(packet.get("chunks_count") or len(ordered_chunk_sequence)),
                "facts_count": int(packet.get("facts_count") or len(supported_fact_text)),
                "summary_count": int(packet.get("summary_count") or len(list(packet.get("summary_node_ids") or []))),
                "raw_text_available": bool(packet.get("raw_text_available")) or bool(packet.get("complete_text_available")),
                "catalog_index": dict(packet.get("catalog_index") or {}),
            }
        )

    branch_count = len(list(branches or []))
    branch_pair_count = (branch_count * max(0, branch_count - 1)) / 2
    branch_overlaps = list(shared_evidence_snapshot.get("branch_overlaps") or [])
    merged_branch_count = sum(
        1
        for branch in list(branches or [])
        if str(branch.get("status") or "") == "merged"
        or str(branch.get("stop_reason") or "") in {"merged_duplicate_route", "merged_duplicate_destination", "merged_into_other_branch"}
    )
    highway_yields = [
        float(entry.get("route_yield") or 0.0)
        for branch in list(branches or [])
        for entry in list(branch.get("route_trace") or [])
        if bool(entry.get("travel_performed")) and str(entry.get("edge_type") or "") == "highway"
    ]
    destination_reached_count = sum(
        1
        for branch in list(branches or [])
        if bool((branch.get("destination_progress") or {}).get("destination_reached"))
        or any(bool(entry.get("destination_reached")) for entry in list(branch.get("route_trace") or []))
    )
    entry_count = len(entries)
    raw_entry_count = sum(1 for entry in entries if bool(entry.get("raw_text_preserved")))
    document_count = len(documents)
    document_complete_count = sum(1 for document in documents if bool(document.get("complete_text_available")))
    supporting_entry_count = sum(1 for entry in entries if list(entry.get("support_slots") or []) or list(entry.get("branch_goals") or []))
    quality_metrics = {
        "raw_text_coverage_ratio": round(raw_entry_count / max(1, entry_count), 6),
        "document_chunk_coverage_ratio": round(document_complete_count / max(1, document_count), 6) if document_count else 0.0,
        "support_density": round(supporting_entry_count / max(1, entry_count), 6),
        "contradiction_exposure_ratio": 1.0 if not contradictions else 1.0,
        "highway_route_yield": round(sum(highway_yields) / max(1, len(highway_yields)), 6) if highway_yields else 0.0,
        "branch_duplication_ratio": round(len(branch_overlaps) / max(1.0, branch_pair_count), 6) if branch_pair_count else 0.0,
        "branch_merge_ratio": round(merged_branch_count / max(1, branch_count), 6) if branch_count else 0.0,
        "destination_reached_ratio": round(destination_reached_count / max(1, branch_count), 6) if branch_count else 0.0,
        "warm_context_reuse_quality": 1.0 if warm_state_used and continuity_state == "high_continuity" else (0.66 if warm_state_used and continuity_state == "medium_continuity" else 0.0),
    }
    reservoir_summary = {
        "entry_count": entry_count,
        "document_count": document_count,
        "raw_text_char_count": sum(len(str(entry.get("raw_text") or "")) for entry in entries),
        "document_raw_complete_count": document_complete_count,
        "supporting_entry_count": supporting_entry_count,
        "contradiction_count": len(contradictions),
        "raw_text_coverage_ratio": quality_metrics["raw_text_coverage_ratio"],
        "document_chunk_coverage_ratio": quality_metrics["document_chunk_coverage_ratio"],
        "family_contribution_summary": dict(shared_evidence_snapshot.get("family_contribution_summary") or {}),
    }
    return {
        "entries": entries,
        "documents": documents,
        "reservoir_summary": reservoir_summary,
        "quality_metrics": quality_metrics,
        "prompt_pack_summary": {},
    }


def _build_document_follow_up_candidates(
    *,
    document_mode: str,
    document_packets: list[dict[str, Any]],
    existing_followups: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    if document_mode == "none":
        return list(existing_followups or [])
    suggestions = [dict(item) for item in list(existing_followups or [])]
    seen = {str(item.get("query") or "") for item in suggestions}

    def add(query: str, reason: str, priority: float) -> None:
        if not query or query in seen:
            return
        seen.add(query)
        suggestions.append({"query": query, "reason": reason, "priority": round(priority, 3)})

    for packet in document_packets[:2]:
        title = str(packet.get("title") or packet.get("source_label") or "questo documento").strip()
        add(f"Apri i chunk principali di {title}", "document_chunk_drilldown", 0.92)
        add(f"Quali fatti supportati emergono da {title}?", "document_fact_drilldown", 0.88)
    if len(document_packets) >= 2:
        add("Confronta i documenti principali emersi nella ricerca.", "document_compare", 0.84)
    add("Verifica se le fonti documentali sono coerenti tra loro.", "document_contradiction_check", 0.8)
    suggestions.sort(key=lambda item: (-float(item.get("priority") or 0.0), str(item.get("query") or "")))
    return suggestions[:4]


def _decorate_document_answer(
    answer: dict[str, Any] | None,
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]],
) -> dict[str, Any] | None:
    if not answer or document_mode == "none" or not document_packets:
        return answer
    if _is_temporal_reference_query(query_text):
        return answer
    decorated = dict(answer)
    lead_packet = dict(document_packets[0] or {})
    lead_title = str(lead_packet.get("title") or lead_packet.get("source_label") or "documento").strip()
    lead_source = str(lead_packet.get("provenance_summary") or "").strip()
    lookup_terms = _document_lookup_terms(query_text) if document_mode == "lookup" else []
    lead_query_fit = _document_lookup_max_packet_fit(document_packets)
    if document_mode == "lookup" and str(decorated.get("mode") or "") != "document_packet":
        if lookup_terms and lead_query_fit < 0.2:
            existing = clean_answer_surface_text(decorated.get("answer_text"))
            requested = _document_lookup_requested_label(query_text)
            message = f"Non trovo un {requested} che corrisponda alla richiesta nella memoria recuperata."
            if existing and not _fold_text(existing).startswith("non trovo"):
                message = f"{message} Nella memoria recuperata trovo pero: {existing}"
            decorated["answer_text"] = message
            decorated["answerability_state"] = "partial"
            decorated["insufficient"] = False
            decorated["document_lookup_state"] = "no_matching_document_packet"
        else:
            answer_text = f"Documento trovato: {lead_title}"
            if lead_source:
                answer_text = f"{answer_text} ({lead_source})"
            decorated["answer_text"] = answer_text
            decorated["mode"] = "grounded_facts"
            decorated["answerability_state"] = "grounded"
    reasoning_summary = str(decorated.get("reasoning_summary") or "").strip()
    if lead_source:
        suffix = f"Source-backed on {lead_source}."
        if suffix not in reasoning_summary:
            decorated["reasoning_summary"] = f"{reasoning_summary} {suffix}".strip()
    evidence_node_ids = list(decorated.get("evidence_node_ids") or [])
    anchor_id = str(lead_packet.get("anchor_node_id") or "").strip()
    if anchor_id and anchor_id not in evidence_node_ids:
        evidence_node_ids.insert(0, anchor_id)
    decorated["evidence_node_ids"] = evidence_node_ids[:10]
    if decorated.get("answer_text"):
        decorated["answer_text"] = clean_answer_surface_text(decorated.get("answer_text"))
    return decorated


def _document_full_text_requested(query_text: str) -> bool:
    lowered = _fold_text(query_text)
    return any(
        token in lowered
        for token in (
            "per intero",
            "testo completo",
            "testo integrale",
            "documento completo",
            "documento integrale",
            "evidenze grezze",
            "evidenza grezza",
            "raw evidence",
            "raw text",
            "senza riassumere",
            "non riassumere",
            "chunk",
            "source trace",
            "traccia sorgente",
        )
    )


def _document_packet_raw_lines(packet: dict[str, Any], *, long_form: bool) -> list[str]:
    lines: list[str] = []
    anchor_raw_text = str(packet.get("anchor_raw_text") or "").strip()
    anchor_limit = 1400 if long_form else 420
    chunk_limit = 10 if long_form else 3
    chunk_text_limit = 1200 if long_form else 320
    fact_limit = 8 if long_form else 3
    fact_text_limit = 700 if long_form else 260
    if anchor_raw_text:
        lines.append(f"- Anchor raw: {_truncate_prompt_text(anchor_raw_text, anchor_limit)}")
    ordered_chunks = list(packet.get("ordered_chunk_sequence") or [])
    if ordered_chunks:
        for chunk in ordered_chunks[:chunk_limit]:
            if not isinstance(chunk, dict):
                continue
            chunk_text = str(chunk.get("raw_text") or chunk.get("text") or chunk.get("evidence_snippet") or "").strip()
            if not chunk_text:
                continue
            chunk_index = int(chunk.get("chunk_index") or len(lines) + 1)
            node_id = str(chunk.get("node_id") or "").strip()
            node_suffix = f" [{node_id}]" if node_id else ""
            lines.append(f"- Chunk {chunk_index}{node_suffix}: {_truncate_prompt_text(chunk_text, chunk_text_limit)}")
    else:
        for match in list(packet.get("top_chunk_matches") or [])[:chunk_limit]:
            node = dict(match.get("node") or {})
            snippet = str(match.get("evidence_snippet") or node.get("raw_text") or node.get("summary") or "").strip()
            if snippet:
                chunk_index = int(node.get("document_chunk_index") or len(lines) + 1)
                lines.append(f"- Chunk {chunk_index}: {_truncate_prompt_text(snippet, chunk_text_limit)}")
    for fact in list(packet.get("supported_fact_text") or [])[:fact_limit]:
        if not isinstance(fact, dict):
            continue
        fact_text = str(fact.get("raw_text") or fact.get("summary") or "").strip()
        if fact_text:
            node_id = str(fact.get("node_id") or "").strip()
            node_suffix = f" [{node_id}]" if node_id else ""
            lines.append(f"- Fact{node_suffix}: {_truncate_prompt_text(fact_text, fact_text_limit)}")
    if not lines:
        for match in list(packet.get("top_fact_matches") or [])[:fact_limit]:
            node = dict(match.get("node") or {})
            fact_text = str(match.get("summary") or node.get("raw_text") or node.get("summary") or "").strip()
            if fact_text:
                lines.append(f"- Fact: {_truncate_prompt_text(fact_text, fact_text_limit)}")
    return lines


def _looks_like_context_ledger_answer(value: str | None) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    lowered = _fold_text(text)
    ledger_markers = (
        " raw context:",
        "- raw context:",
        "- fact [",
        "- chunk ",
        "mixed evidence",
        "mixed_evidence",
        "manual text",
        "manual_text",
        "navigation store",
        "document packet",
        "visualizza profilo",
    )
    if any(marker in lowered for marker in ledger_markers):
        return True
    if re.search(r"\b\d{2,}\s+follower\b", lowered):
        return True
    return bool(re.search(r"(?im)^\s*-\s+(fact|chunk|anchor raw|open questions)\b", text))


def _answer_surface_contract_blocked(query_text: str, answer_text: str | None) -> bool:
    text = clean_answer_surface_text(answer_text)
    if not text:
        return False
    if _looks_like_context_ledger_answer(text):
        return True
    checked = _apply_answer_contract(
        query_text,
        {
            "answer_text": text,
            "mode": "surface_guard",
            "confidence": 0.0,
            "evidence_node_ids": [],
            "reasoning_summary": "Answer surface contract guard.",
            "insufficient": False,
            "answerability_state": "grounded",
            "evidence_snippets": [],
        },
        [],
    )
    adequacy = dict(checked.get("answer_adequacy") or {})
    return bool(
        list(adequacy.get("off_contract_topics") or [])
        or bool(adequacy.get("context_ledger_leak"))
    )


def _human_answer_full(
    *,
    query_text: str = "",
    answer_short: str | None,
    answer_full: str | None,
    context_dossier: str | None,
    document_mode: str,
    document_packets: list[dict[str, Any]],
) -> str | None:
    short = str(answer_short or "").strip()
    full = str(answer_full or "").strip()
    if not short:
        return polish_final_answer_surface(query_text, full) or full or None
    short_clean = polish_final_answer_surface(query_text, short) or short
    short_blocked = _answer_surface_contract_blocked(query_text, short_clean)
    if detect_query_intent(query_text) == "temporal_inventory":
        return None if short_blocked else short_clean
    if not full or _looks_like_context_ledger_answer(full):
        return None if short_blocked else short_clean
    if (
        document_mode == "none"
        and _query_class(query_text) in {"direct_fact", "relation_fact", "style_values"}
        and not _is_temporal_reference_query(query_text)
        and query_contract_allows_fast_final(query_text, retrieval_mode="balanced", answer={"answer_text": short_clean})
    ):
        return None if short_blocked else short_clean
    full_clean = polish_final_answer_surface(query_text, full) or full
    if _is_temporal_reference_query(query_text) and len(full) > max(len(short) + 260, 700):
        return None if short_blocked else short_clean
    query_contract = build_query_contract(query_text)
    if document_mode != "none" or document_packets:
        if str(query_contract.get("query_kind") or "") != "document_lookup":
            bounded_check = _apply_answer_contract(
                query_text,
                {
                    "answer_text": full_clean,
                    "mode": "grounded_facts",
                    "confidence": 0.8,
                    "evidence_node_ids": [],
                    "reasoning_summary": "Non-document answer surface check with document evidence present.",
                    "insufficient": False,
                    "answerability_state": "grounded",
                    "evidence_snippets": [],
                },
                [],
            )
            bounded_adequacy = dict(bounded_check.get("answer_adequacy") or {})
            if (
                bool(bounded_adequacy.get("context_ledger_leak"))
                or list(bounded_adequacy.get("off_contract_topics") or [])
                or list(bounded_adequacy.get("third_person_markers") or [])
            ):
                return None if short_blocked else short_clean
        return full_clean or short_clean or None
    if _looks_like_context_ledger_answer(context_dossier) and len(full) <= len(short) + 40:
        return None if short_blocked else short_clean
    if str(query_contract.get("answer_width") or "") == "bounded":
        bounded_check = _apply_answer_contract(
            query_text,
            {
                "answer_text": full_clean,
                "mode": "grounded_facts",
                "confidence": 0.8,
                "evidence_node_ids": [],
                "reasoning_summary": "Bounded answer width check.",
                "insufficient": False,
                "answerability_state": "grounded",
                "evidence_snippets": [],
            },
            [],
        )
        bounded_adequacy = dict(bounded_check.get("answer_adequacy") or {})
        if bool(bounded_check.get("insufficient")) or list(bounded_adequacy.get("off_contract_topics") or []):
            return None if short_blocked else short_clean
    if _query_class(query_text) == "broad_summary":
        merged = _merge_broad_first_answer_facts(query_text=query_text, answer_short=short_clean, answer_full=full_clean)
        if merged:
            return merged
    return full_clean


def _answer_surface_update_summary(
    *,
    query_text: str,
    answer_short: str | None,
    candidate_answer_full: str | None,
    final_answer_full: str | None,
    preserved_short_final: bool,
) -> dict[str, Any]:
    short_clean = polish_final_answer_surface(query_text, answer_short) or clean_answer_surface_text(answer_short)
    candidate_clean = polish_final_answer_surface(query_text, candidate_answer_full) or clean_answer_surface_text(candidate_answer_full)
    final_clean = polish_final_answer_surface(query_text, final_answer_full) or clean_answer_surface_text(final_answer_full)
    if not final_clean:
        policy = "no_final_answer"
        reason = "empty_final_surface"
    elif preserved_short_final:
        policy = "kept_first_answer"
        reason = "exact_contract_fast_final"
    elif short_clean and final_clean == short_clean:
        policy = "kept_first_answer"
        if candidate_clean and candidate_clean != short_clean and _looks_like_context_ledger_answer(candidate_clean):
            reason = "candidate_rejected_context_ledger"
        elif candidate_clean and candidate_clean != short_clean:
            reason = "candidate_rejected_by_contract"
        else:
            reason = "no_material_final_gain"
    elif short_clean and len(final_clean) > len(short_clean) + 40:
        policy = "updated_final_answer"
        reason = "contract_passing_material_gain"
    elif short_clean:
        policy = "updated_final_answer"
        reason = "contract_passing_minor_gain"
    else:
        policy = "updated_final_answer"
        reason = "final_surface_only"
    return {
        "policy": policy,
        "reason": reason,
        "first_answer_chars": len(short_clean),
        "candidate_final_chars": len(candidate_clean),
        "final_answer_chars": len(final_clean),
        "delta_chars": len(final_clean) - len(short_clean),
        "candidate_rejected": bool(candidate_clean and candidate_clean != final_clean and final_clean == short_clean),
    }


def _early_final_candidate_answer_full(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_payload: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
) -> str | None:
    answer_short = polish_final_answer_surface(query_text, partial_payload.get("answer_short")) or clean_answer_surface_text(partial_payload.get("answer_short"))
    full_partial = polish_final_answer_surface(query_text, partial_payload.get("answer_full_partial")) or clean_answer_surface_text(partial_payload.get("answer_full_partial"))
    contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    query_kind = str(contract.get("query_kind") or "")
    if query_kind in {"exact_fact", "exact_relation_fact"} and answer_short:
        return answer_short
    disallowed_topics = {
        str(item).strip()
        for item in list(contract.get("disallowed_topics") or [])
        if str(item).strip()
    }
    skip_family_topics = bool(disallowed_topics & {"family_relation", "family_monument"})
    candidates: list[str] = []

    def add_candidate(value: str | None) -> None:
        text = clean_answer_surface_text(value)
        if not text or _looks_like_context_ledger_answer(text):
            return
        folded = _fold_text(text)
        if skip_family_topics and any(token in folded for token in ("padre", "father", "monumento", "aeronautica", "air force")):
            return
        if any(topic == "generic_profile" and token in folded for topic in disallowed_topics for token in ("biografia completa", "profilo generico")):
            return
        candidates.append(text)

    add_candidate(answer_short)
    if full_partial and full_partial != answer_short:
        add_candidate(full_partial)
    for snapshot in list(section_snapshots or [])[:8]:
        title = str(snapshot.get("title") or snapshot.get("key") or "").strip()
        folded_title = _fold_text(title)
        if any(token in folded_title for token in ("document", "chunk", "ledger", "raw context", "trace")):
            continue
        if skip_family_topics and any(token in folded_title for token in ("relationship", "relationships", "relazioni", "family", "famiglia")):
            continue
        for item in list(snapshot.get("items") or [])[:4]:
            add_candidate(str(item or ""))
    if not candidates:
        return answer_short or None
    selected: list[str] = []
    seen: set[str] = set()
    for candidate in candidates:
        for sentence in re.split(r"(?<=[.!?])\s+|;\s+", candidate):
            cleaned = clean_answer_surface_text(sentence)
            if not cleaned:
                continue
            folded = _fold_text(cleaned)
            if not folded or folded in seen:
                continue
            if any((len(folded) >= 34 and folded in existing) or (len(existing) >= 34 and existing in folded) for existing in seen):
                continue
            seen.add(folded)
            selected.append(cleaned)
            if len(" ".join(selected)) >= 1800:
                break
        if len(" ".join(selected)) >= 1800:
            break
    merged = " ".join(selected).strip()
    polished = polish_final_answer_surface(query_text, merged) or clean_answer_surface_text(merged)
    return polished or answer_short or None


def _early_final_surface_decision(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_payload: dict[str, Any],
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
    evidence_reservoir: dict[str, Any] | None = None,
    document_mode: str = "none",
    document_packets: list[dict[str, Any]] | None = None,
    usable: bool = False,
    candidate_answer_full: str | None = None,
) -> dict[str, Any]:
    answer = dict(partial_payload.get("answer") or {})
    candidate_answer = polish_final_answer_surface(query_text, candidate_answer_full) or clean_answer_surface_text(candidate_answer_full)
    if not usable:
        return {"ready": False, "reason": "partial_not_usable", "candidate_answer_full": candidate_answer}
    if not candidate_answer:
        return {"ready": False, "reason": "empty_candidate_answer", "candidate_answer_full": None}
    if bool(answer.get("insufficient")) or str(answer.get("answerability_state") or "") == "insufficient":
        return {"ready": False, "reason": "answer_insufficient", "candidate_answer_full": candidate_answer}
    if str(answer.get("document_lookup_state") or "") in {"no_matching_document_packet_yet"}:
        return {"ready": False, "reason": "document_lookup_still_open", "candidate_answer_full": candidate_answer}
    adequacy = dict(answer.get("answer_adequacy") or {})
    if adequacy and not bool(adequacy.get("passed", True)):
        return {"ready": False, "reason": "answer_adequacy_failed", "candidate_answer_full": candidate_answer}
    if _looks_like_context_ledger_answer(candidate_answer):
        return {"ready": False, "reason": "candidate_context_ledger", "candidate_answer_full": candidate_answer}
    matrix = build_evidence_satisfaction_matrix(
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        answer=answer,
        shared_evidence=shared_evidence_snapshot,
        evidence_reservoir=evidence_reservoir,
    )
    contract = dict(matrix.get("query_contract") or {})
    if not bool(matrix.get("final_ready")):
        return {
            "ready": False,
            "reason": "missing_required_slots",
            "missing_slots": list(matrix.get("missing_slots") or []),
            "candidate_answer_full": candidate_answer,
            "query_kind": str(contract.get("query_kind") or ""),
        }
    query_kind = str(contract.get("query_kind") or "")
    support_node_count = int(answer.get("support_node_count") or len(list(answer.get("evidence_node_ids") or [])))
    support_slot_count = int(answer.get("support_slot_count") or 0)
    distinct_packet_count = int(answer.get("distinct_evidence_packet_count") or 0)
    section_count = len([snapshot for snapshot in list(section_snapshots or []) if list(snapshot.get("items") or [])])
    candidate_chars = len(candidate_answer)
    document_packet_count = len(list(document_packets or []))
    if query_kind == "document_lookup":
        if str(document_mode or "none") == "none" and document_packet_count <= 0:
            return {"ready": False, "reason": "document_surface_not_ready", "candidate_answer_full": candidate_answer, "query_kind": query_kind}
        min_chars = 70
        min_support = 1
    elif query_kind == "broad_profile":
        min_chars = 240
        min_support = 3
        if section_count < 4:
            return {"ready": False, "reason": "broad_profile_needs_more_sections", "candidate_answer_full": candidate_answer, "query_kind": query_kind}
    elif query_kind in {"work_narrative", "narrative", "narrative_relation"}:
        min_chars = 140
        min_support = 2
        if section_count < 2 and support_slot_count < 2:
            return {"ready": False, "reason": "narrative_needs_more_sections", "candidate_answer_full": candidate_answer, "query_kind": query_kind}
    elif query_kind in {"company_founding_relation", "company_founding_timeline"}:
        min_chars = 80
        min_support = 1
    elif str(contract.get("answer_style") or "") in {"timeline", "list"}:
        min_chars = 70
        min_support = 1
    else:
        min_chars = 12
        min_support = 1
    support_strength = max(support_node_count, support_slot_count, distinct_packet_count)
    if support_strength < min_support:
        return {
            "ready": False,
            "reason": "support_floor_not_met",
            "support_strength": support_strength,
            "min_support": min_support,
            "candidate_answer_full": candidate_answer,
            "query_kind": query_kind,
        }
    if candidate_chars < min_chars:
        return {
            "ready": False,
            "reason": "candidate_too_short",
            "candidate_chars": candidate_chars,
            "min_chars": min_chars,
            "candidate_answer_full": candidate_answer,
            "query_kind": query_kind,
        }
    return {
        "ready": True,
        "reason": "contract_passing_early_final_surface",
        "query_kind": query_kind,
        "answer_style": str(contract.get("answer_style") or ""),
        "candidate_answer_full": candidate_answer,
        "candidate_chars": candidate_chars,
        "support_node_count": support_node_count,
        "support_slot_count": support_slot_count,
        "distinct_evidence_packet_count": distinct_packet_count,
        "section_count": section_count,
        "satisfied_required_slot_count": int(matrix.get("satisfied_required_slot_count") or 0),
        "required_slot_count": int(matrix.get("required_slot_count") or 0),
        "missing_slots": list(matrix.get("missing_slots") or []),
    }


def _background_enrichment_budget(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str | None = None,
) -> dict[str, Any]:
    contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    query_kind = str(contract.get("query_kind") or "")
    mode = str(retrieval_mode or "balanced").strip().lower()
    if mode == "flash":
        max_rounds = 0
        max_seconds = 0.75
        max_context_updates = 1
        max_answer_candidates = 0
    elif mode == "balanced":
        max_rounds = 1
        max_seconds = 2.5
        max_context_updates = 3
        max_answer_candidates = 1
    elif mode == "heavy":
        max_rounds = 2
        max_seconds = 6.0
        max_context_updates = 6
        max_answer_candidates = 2
    else:
        max_rounds = 3
        max_seconds = 9.0
        max_context_updates = 9
        max_answer_candidates = 3
    if query_kind == "document_lookup" or str(query_class or "") == "document_lookup":
        max_rounds = min(max_rounds, 1)
        max_seconds = min(max_seconds, 3.0)
        max_context_updates = min(max_context_updates, 4)
        max_answer_candidates = min(max_answer_candidates, 1)
    elif query_kind in {"exact_fact", "exact_relation_fact", "company_founding_relation", "company_founding_timeline"}:
        max_rounds = min(max_rounds, 1)
        max_seconds = min(max_seconds, 2.5)
        max_context_updates = min(max_context_updates, 3)
        max_answer_candidates = min(max_answer_candidates, 1)
    elif query_kind in {"broad_profile", "work_narrative", "narrative", "narrative_relation"}:
        max_rounds = max(max_rounds, 1 if mode in {"flash", "balanced"} else max_rounds)
    return {
        "schema_version": "agvm.background_enrichment_budget.v1",
        "enabled": True,
        "query_kind": query_kind,
        "retrieval_mode": mode,
        "max_rounds_after_early_final": int(max_rounds),
        "max_seconds_after_early_final": float(max_seconds),
        "max_context_updates_after_early_final": int(max_context_updates),
        "max_answer_candidates_after_early_final": int(max_answer_candidates),
        "detach_result_snapshot": True,
        "yield_policy": _background_enrichment_yield_policy(
            query_text=query_text,
            retrieval_mode=retrieval_mode,
            query_class=query_class,
        ),
        "policy": "seal_answer_then_budget_background",
    }


def _client_visible_partial_terminal_budget_seconds(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str | None = None,
    route_truth_required: bool = False,
) -> float:
    """Bound work after the MCP client has already seen a partial context package."""
    if route_truth_required:
        return 0.0
    contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    query_kind = str(contract.get("query_kind") or "")
    mode = str(retrieval_mode or "balanced").strip().lower()
    if mode == "flash":
        budget = 1.25
    elif mode == "balanced":
        budget = 3.5
    elif mode == "heavy":
        budget = 7.5
    else:
        budget = 10.0
    if query_kind == "document_lookup" or str(query_class or "") == "document_lookup":
        budget = min(budget, 3.0)
    elif query_kind in {"exact_fact", "exact_relation_fact", "company_founding_relation", "company_founding_timeline"}:
        budget = min(budget, 2.75)
    elif query_kind in {"broad_profile", "work_narrative", "narrative", "narrative_relation"} and mode in {"heavy", "forensic"}:
        budget = max(budget, 7.5)
    raw_override = os.getenv("AGVM_CLIENT_VISIBLE_PARTIAL_TERMINAL_BUDGET_SECONDS")
    if raw_override is not None:
        try:
            budget = float(raw_override)
        except (TypeError, ValueError):
            pass
    return max(0.0, float(budget))


def _background_enrichment_yield_policy(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str | None = None,
) -> dict[str, Any]:
    contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    query_kind = str(contract.get("query_kind") or "")
    mode = str(retrieval_mode or "balanced").strip().lower()
    broad_kinds = {"broad_profile", "work_narrative", "narrative", "narrative_relation"}
    focused_kinds = {
        "document_lookup",
        "exact_fact",
        "exact_relation_fact",
        "company_founding_relation",
        "company_founding_timeline",
        "temporal",
    }
    if mode == "flash":
        min_score = 0.12
        patience = 0
    elif mode == "balanced":
        min_score = 0.16
        patience = 0
    elif mode == "heavy":
        min_score = 0.18
        patience = 1 if query_kind in broad_kinds else 0
    else:
        min_score = 0.16
        patience = 1 if query_kind in broad_kinds else 0
    if query_kind in focused_kinds or str(query_class or "") == "document_lookup":
        min_score = max(min_score, 0.18)
        patience = 0
    return {
        "schema_version": "agvm.background_enrichment_yield_policy.v1",
        "enabled": True,
        "query_kind": query_kind,
        "retrieval_mode": mode,
        "query_class": str(query_class or ""),
        "min_marginal_yield_score": round(float(min_score), 4),
        "low_yield_patience_rounds": int(patience),
        "min_new_evidence_items": 1,
        "route_progress_gain_floor": 0.08,
        "policy": "stop_background_when_marginal_yield_collapses",
    }


def _stable_str_set(values: Any) -> set[str]:
    return {str(item).strip() for item in list(values or []) if str(item).strip()}


def _background_enrichment_yield_snapshot(
    *,
    visited_node_ids: Any = None,
    aggregated_matches: Any = None,
    shared_topics: Any = None,
    context_wave_count: int = 0,
    context_update_count: int = 0,
    answer_candidate_count: int = 0,
    document_packets: Any = None,
    branches: Any = None,
    evidence_reservoir: Any = None,
) -> dict[str, Any]:
    match_ids = {
        str(key).strip()
        for key in dict(aggregated_matches or {}).keys()
        if str(key).strip()
    }
    node_ids = _stable_str_set(visited_node_ids) | match_ids
    topic_map = dict(shared_topics or {})
    covered_goals = {str(key).strip() for key in topic_map.keys() if str(key).strip()}
    fulfilled_goals = {
        str(key).strip()
        for key, value in topic_map.items()
        if str(key).strip() and str(dict(value or {}).get("status") or "") == "fulfilled"
    }
    document_ids: set[str] = set()
    for packet in list(document_packets or []):
        if not isinstance(packet, dict):
            continue
        for key in ("anchor_node_id", "chunk_node_id", "source_node_id", "node_id"):
            value = str(packet.get(key) or "").strip()
            if value:
                document_ids.add(value)
    branch_rows = [dict(item) for item in list(branches or []) if isinstance(item, dict)]
    active_branches = [branch for branch in branch_rows if str(branch.get("status") or "") == "active"]
    route_yields = [_bounded_unit_float(branch.get("route_yield")) for branch in branch_rows]
    reservoir_summary = dict((evidence_reservoir or {}).get("reservoir_summary") or {})
    return {
        "schema_version": "agvm.background_enrichment_yield_snapshot.v1",
        "node_ids": sorted(node_ids),
        "match_ids": sorted(match_ids),
        "covered_goals": sorted(covered_goals),
        "fulfilled_goals": sorted(fulfilled_goals),
        "document_ids": sorted(document_ids),
        "context_wave_count": int(context_wave_count or 0),
        "context_update_count": int(context_update_count or 0),
        "answer_candidate_count": int(answer_candidate_count or 0),
        "active_branch_count": len(active_branches),
        "branch_count": len(branch_rows),
        "avg_route_yield": round(sum(route_yields) / max(1, len(route_yields)), 4),
        "max_route_yield": round(max(route_yields, default=0.0), 4),
        "reservoir_entry_count": int(reservoir_summary.get("entry_count") or 0),
        "reservoir_document_count": int(reservoir_summary.get("document_count") or 0),
    }


def _background_enrichment_yield_report(
    *,
    before_snapshot: dict[str, Any],
    after_snapshot: dict[str, Any],
    policy: dict[str, Any],
    round_index: int,
    elapsed_ms_after_early_final: float | None = None,
) -> dict[str, Any]:
    before = dict(before_snapshot or {})
    after = dict(after_snapshot or {})
    new_node_ids = sorted(_stable_str_set(after.get("node_ids")) - _stable_str_set(before.get("node_ids")))
    new_match_ids = sorted(_stable_str_set(after.get("match_ids")) - _stable_str_set(before.get("match_ids")))
    new_goals = sorted(_stable_str_set(after.get("covered_goals")) - _stable_str_set(before.get("covered_goals")))
    new_fulfilled_goals = sorted(_stable_str_set(after.get("fulfilled_goals")) - _stable_str_set(before.get("fulfilled_goals")))
    new_document_ids = sorted(_stable_str_set(after.get("document_ids")) - _stable_str_set(before.get("document_ids")))
    context_wave_delta = max(0, int(after.get("context_wave_count") or 0) - int(before.get("context_wave_count") or 0))
    context_update_delta = max(0, int(after.get("context_update_count") or 0) - int(before.get("context_update_count") or 0))
    answer_candidate_delta = max(0, int(after.get("answer_candidate_count") or 0) - int(before.get("answer_candidate_count") or 0))
    reservoir_entry_delta = max(0, int(after.get("reservoir_entry_count") or 0) - int(before.get("reservoir_entry_count") or 0))
    route_progress_gain = max(0.0, float(after.get("max_route_yield") or 0.0) - float(before.get("max_route_yield") or 0.0))
    material_new_item_count = (
        len(new_node_ids)
        + len(new_match_ids)
        + len(new_goals)
        + len(new_fulfilled_goals)
        + len(new_document_ids)
        + reservoir_entry_delta
    )
    marginal_yield_score = min(
        1.0,
        min(0.32, 0.08 * len(new_node_ids) + 0.05 * len(new_match_ids))
        + min(0.24, 0.12 * len(new_goals) + 0.14 * len(new_fulfilled_goals))
        + min(0.20, 0.10 * len(new_document_ids) + 0.04 * reservoir_entry_delta)
        + min(0.08, 0.03 * context_update_delta + 0.02 * context_wave_delta)
        + min(0.08, 0.06 * answer_candidate_delta)
        + min(0.12, 0.70 * route_progress_gain),
    )
    threshold = float((policy or {}).get("min_marginal_yield_score") or 0.0)
    min_new_items = int((policy or {}).get("min_new_evidence_items") or 1)
    route_gain_floor = float((policy or {}).get("route_progress_gain_floor") or 0.0)
    low_yield = bool(
        marginal_yield_score < threshold
        and material_new_item_count < min_new_items
        and route_progress_gain < route_gain_floor
    )
    return {
        "schema_version": "agvm.background_enrichment_yield_report.v1",
        "round_index": int(round_index or 0),
        "elapsed_ms_after_early_final": round(float(elapsed_ms_after_early_final or 0.0), 2),
        "marginal_yield_score": round(float(marginal_yield_score), 4),
        "min_marginal_yield_score": round(float(threshold), 4),
        "low_yield": low_yield,
        "material_new_item_count": int(material_new_item_count),
        "new_node_ids": new_node_ids[:24],
        "new_match_ids": new_match_ids[:24],
        "new_goal_ids": new_goals[:16],
        "new_fulfilled_goal_ids": new_fulfilled_goals[:16],
        "new_document_ids": new_document_ids[:16],
        "context_wave_delta": int(context_wave_delta),
        "context_update_delta": int(context_update_delta),
        "answer_candidate_delta": int(answer_candidate_delta),
        "reservoir_entry_delta": int(reservoir_entry_delta),
        "route_progress_gain": round(float(route_progress_gain), 4),
        "active_branch_count_after": int(after.get("active_branch_count") or 0),
        "branch_count_after": int(after.get("branch_count") or 0),
        "avg_route_yield_after": round(float(after.get("avg_route_yield") or 0.0), 4),
        "max_route_yield_after": round(float(after.get("max_route_yield") or 0.0), 4),
    }


def _background_enrichment_yield_stop_status(
    *,
    policy: dict[str, Any],
    yield_report: dict[str, Any],
    consecutive_low_yield_rounds: int,
) -> dict[str, Any]:
    if not bool((policy or {}).get("enabled", True)):
        return {"should_stop": False, "reason": "yield_policy_disabled"}
    if not bool((yield_report or {}).get("low_yield")):
        return {
            "should_stop": False,
            "reason": "marginal_yield_still_useful",
            "consecutive_low_yield_rounds": int(consecutive_low_yield_rounds or 0),
        }
    patience = int((policy or {}).get("low_yield_patience_rounds") or 0)
    should_stop = int(consecutive_low_yield_rounds or 0) > patience
    return {
        "should_stop": bool(should_stop),
        "reason": "background_low_yield_converged" if should_stop else "low_yield_patience_remaining",
        "consecutive_low_yield_rounds": int(consecutive_low_yield_rounds or 0),
        "low_yield_patience_rounds": patience,
        "marginal_yield_score": yield_report.get("marginal_yield_score"),
        "min_marginal_yield_score": yield_report.get("min_marginal_yield_score"),
    }


def _background_enrichment_yield_summary(reports: list[dict[str, Any]], policy: dict[str, Any]) -> dict[str, Any]:
    valid_reports = [dict(report) for report in list(reports or []) if isinstance(report, dict)]
    scores = [float(report.get("marginal_yield_score") or 0.0) for report in valid_reports]
    low_count = sum(1 for report in valid_reports if bool(report.get("low_yield")))
    return {
        "schema_version": "agvm.background_enrichment_yield_summary.v1",
        "policy": dict(policy or {}),
        "round_count": len(valid_reports),
        "low_yield_round_count": int(low_count),
        "last_marginal_yield_score": round(float(scores[-1]), 4) if scores else None,
        "best_marginal_yield_score": round(max(scores), 4) if scores else None,
        "total_new_item_count": int(sum(int(report.get("material_new_item_count") or 0) for report in valid_reports)),
        "total_context_updates": int(sum(int(report.get("context_update_delta") or 0) for report in valid_reports)),
        "total_answer_candidates": int(sum(int(report.get("answer_candidate_delta") or 0) for report in valid_reports)),
        "stopped_for_low_yield": bool(valid_reports and bool(valid_reports[-1].get("low_yield")) and low_count > int((policy or {}).get("low_yield_patience_rounds") or 0)),
    }


def _background_enrichment_budget_status(
    *,
    budget: dict[str, Any],
    early_final_elapsed_seconds: float,
    rounds_after_early_final: int,
    context_updates_after_early_final: int,
    answer_candidates_after_early_final: int,
) -> dict[str, Any]:
    if not bool((budget or {}).get("enabled", True)):
        return {"should_stop": False, "reason": "disabled"}
    max_rounds = int((budget or {}).get("max_rounds_after_early_final") or 0)
    max_seconds = float((budget or {}).get("max_seconds_after_early_final") or 0.0)
    max_context_updates = int((budget or {}).get("max_context_updates_after_early_final") or 0)
    max_answer_candidates = int((budget or {}).get("max_answer_candidates_after_early_final") or 0)
    if rounds_after_early_final >= max_rounds:
        return {
            "should_stop": True,
            "reason": "background_round_budget_exhausted",
            "rounds_after_early_final": int(rounds_after_early_final),
            "max_rounds_after_early_final": max_rounds,
        }
    if max_seconds > 0.0 and early_final_elapsed_seconds >= max_seconds:
        return {
            "should_stop": True,
            "reason": "background_time_budget_exhausted",
            "elapsed_seconds_after_early_final": round(float(early_final_elapsed_seconds), 3),
            "max_seconds_after_early_final": max_seconds,
        }
    if context_updates_after_early_final >= max_context_updates:
        return {
            "should_stop": True,
            "reason": "background_context_update_budget_exhausted",
            "context_updates_after_early_final": int(context_updates_after_early_final),
            "max_context_updates_after_early_final": max_context_updates,
        }
    if answer_candidates_after_early_final >= max_answer_candidates:
        return {
            "should_stop": True,
            "reason": "background_answer_candidate_budget_exhausted",
            "answer_candidates_after_early_final": int(answer_candidates_after_early_final),
            "max_answer_candidates_after_early_final": max_answer_candidates,
        }
    return {
        "should_stop": False,
        "reason": "within_background_budget",
        "rounds_after_early_final": int(rounds_after_early_final),
        "elapsed_seconds_after_early_final": round(float(early_final_elapsed_seconds), 3),
        "context_updates_after_early_final": int(context_updates_after_early_final),
        "answer_candidates_after_early_final": int(answer_candidates_after_early_final),
    }


def _bounded_unit_float(value: Any, default: float = 0.0) -> float:
    try:
        numeric = float(value)
    except (TypeError, ValueError):
        numeric = float(default)
    return max(0.0, min(1.0, numeric))


def _branch_requires_route_validation(
    branch: dict[str, Any],
    *,
    warm_state_used: bool,
    retrieval_mode: str,
    route_truth_required: bool = False,
) -> bool:
    if list(branch.get("route_trace") or []):
        return False
    if bool(route_truth_required):
        return True
    return bool(warm_state_used) and str(retrieval_mode or "").strip().lower() != "flash"


def _post_final_worker_throttle_policy(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str | None = None,
    route_truth_required: bool = False,
    route_truth_branch_cap: int | None = None,
    route_truth_round_budget: int | None = None,
) -> dict[str, Any]:
    contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    query_kind = str(contract.get("query_kind") or "")
    mode = str(retrieval_mode or "balanced").strip().lower()
    broad_kinds = {"broad_profile", "work_narrative", "narrative", "narrative_relation"}
    focused_kinds = {
        "document_lookup",
        "exact_fact",
        "exact_relation_fact",
        "company_founding_relation",
        "company_founding_timeline",
        "temporal",
    }
    if mode == "flash":
        branch_worker_cap = 0
        ai_worker_cap = 0
        threshold = 0.42
        min_keep_count = 0
    elif mode == "balanced":
        branch_worker_cap = 1
        ai_worker_cap = 0
        threshold = 0.34
        min_keep_count = 1 if query_kind in broad_kinds else 0
    elif mode == "heavy":
        branch_worker_cap = 1
        ai_worker_cap = 0
        threshold = 0.28 if query_kind in broad_kinds else 0.32
        min_keep_count = 1 if query_kind in broad_kinds else 0
    else:
        branch_worker_cap = 2 if query_kind in broad_kinds else 1
        ai_worker_cap = 0
        threshold = 0.24 if query_kind in broad_kinds else 0.28
        min_keep_count = 1 if query_kind in broad_kinds else 0
    if query_kind in focused_kinds or str(query_class or "") == "document_lookup":
        branch_worker_cap = min(branch_worker_cap, 1)
        ai_worker_cap = 0
        threshold = max(threshold, 0.34 if query_kind == "document_lookup" else 0.32)
        min_keep_count = 0
    branch_round_budget = 1
    policy_label = "score_branch_value_before_launch"
    if route_truth_required:
        requested_branch_cap = max(1, min(6, int(route_truth_branch_cap or branch_worker_cap or 1)))
        requested_round_budget = max(1, min(4, int(route_truth_round_budget or 1)))
        branch_worker_cap = max(branch_worker_cap, requested_branch_cap)
        branch_round_budget = max(branch_round_budget, requested_round_budget)
        ai_worker_cap = max(ai_worker_cap, 1)
        threshold = min(threshold, 0.22)
        min_keep_count = max(min_keep_count, branch_worker_cap)
        policy_label = "route_truth_completion_before_prune"
    return {
        "schema_version": "agvm.post_final_worker_throttle.v1",
        "enabled": True,
        "query_kind": query_kind,
        "retrieval_mode": mode,
        "query_class": str(query_class or ""),
        "route_truth_required": bool(route_truth_required),
        "branch_worker_cap_after_early_final": int(branch_worker_cap),
        "ai_worker_cap_after_early_final": int(ai_worker_cap),
        "branch_round_budget_after_early_final": int(branch_round_budget),
        "branch_value_threshold": round(float(threshold), 4),
        "min_keep_count": int(min_keep_count),
        "policy": policy_label,
    }


def _post_final_branch_value_report(
    branch: dict[str, Any],
    *,
    threshold: float,
    shared_topics: dict[str, dict[str, Any]],
    query_text: str,
    retrieval_mode: str,
    query_class: str | None = None,
    round_index: int = 0,
) -> dict[str, Any]:
    contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    query_kind = str(contract.get("query_kind") or "")
    goal = str(branch.get("goal") or "").strip()
    goal_folded = _fold_text(goal)
    goal_slot = _goal_to_slot(goal)
    required_slots = {
        str(slot).strip().lower()
        for slot in list(contract.get("required_slots") or [])
        if str(slot).strip()
    }
    optional_slots = {
        str(slot).strip().lower()
        for slot in list(contract.get("optional_slots") or [])
        if str(slot).strip()
    }
    covered_slots = {
        str(slot).strip().lower()
        for slot in list(branch.get("covered_slots") or [])
        if str(slot).strip()
    }
    shared_topic = dict(shared_topics.get(goal) or shared_topics.get(goal_slot) or {})
    shared_confidence = _bounded_unit_float(shared_topic.get("confidence"))
    covered_by_shared_evidence = bool(shared_topic and shared_confidence >= max(0.5, float(threshold)))
    evidence_count = len({str(item).strip() for item in list(branch.get("evidence_node_ids") or []) if str(item).strip()})
    visited_count = len({str(item).strip() for item in list(branch.get("visited_bucket_keys") or []) if str(item).strip()})
    route_trace_count = len([item for item in list(branch.get("route_trace") or []) if isinstance(item, dict)])
    destination_queue = [
        dict(item)
        for item in list(
            branch.get("execution_destination_queue")
            or branch.get("semantic_destination_queue")
            or branch.get("destination_queue")
            or []
        )
        if isinstance(item, dict)
    ]
    pending_destination_count = max(
        0,
        len(
            [
                item
                for item in destination_queue
                if str(item.get("state") or item.get("status") or "").strip().lower()
                not in {"satisfied", "reached", "resolved", "merged", "suppressed_by_master"}
            ]
        ),
    )
    destination_text = _fold_text(
        " ".join(
            " ".join(
                [
                    str(destination.get("destination_id") or ""),
                    str(destination.get("destination_key") or ""),
                    str(destination.get("label") or ""),
                    str(destination.get("guide_area") or ""),
                    str(destination.get("memory_type") or ""),
                ]
            )
            for destination in destination_queue[:4]
        )
    )
    document_signal = 1.0 if (
        query_kind == "document_lookup"
        or str(query_class or "") == "document_lookup"
        or any(token in goal_folded for token in ("document", "source", "font", "dossier"))
        or any(token in destination_text for token in ("document", "source", "font", "dossier"))
    ) else 0.0
    required_slot_signal = 1.0 if goal_slot in required_slots or goal_folded in required_slots else 0.0
    optional_slot_signal = 1.0 if goal_slot in optional_slots or goal_folded in optional_slots else 0.0
    dual_origin_signal = 1.0 if bool(branch.get("dual_origin")) or len(list(branch.get("origin_families") or [])) > 1 else 0.0
    route_state = str(branch.get("route_state") or branch.get("lifecycle_stage") or "").strip().lower()
    local_stop = str(branch.get("local_stop_recommendation") or "").strip().lower()
    priority_score = _bounded_unit_float(branch.get("branch_priority", branch.get("priority", 0.0)))
    evidence_score = min(1.0, evidence_count / 3.0)
    visited_score = min(1.0, visited_count / 4.0)
    route_score = _bounded_unit_float(branch.get("route_yield"))
    trace_score = min(1.0, route_trace_count / 3.0)
    pending_score = min(1.0, pending_destination_count / 3.0)
    slot_score = min(1.0, len(covered_slots & (required_slots | optional_slots)) / max(1.0, float(len(required_slots | optional_slots))))
    value_score = (
        0.24 * priority_score
        + 0.18 * evidence_score
        + 0.14 * route_score
        + 0.10 * trace_score
        + 0.10 * pending_score
        + 0.10 * required_slot_signal
        + 0.05 * optional_slot_signal
        + 0.05 * document_signal
        + 0.04 * dual_origin_signal
        + 0.04 * visited_score
        + 0.04 * slot_score
    )
    if covered_by_shared_evidence:
        value_score -= 0.30
    if local_stop in {"stop_branch", "stop_route_exhausted"}:
        value_score -= 0.18
    if route_state in {"route_exhausted", "stopped", "merged"}:
        value_score -= 0.12
    if evidence_count == 0 and int(round_index or 0) > 1:
        value_score -= 0.06
    value_score = max(0.0, min(1.0, value_score))
    reasons: list[str] = []
    if required_slot_signal:
        reasons.append("required_slot")
    if optional_slot_signal:
        reasons.append("optional_slot")
    if evidence_count:
        reasons.append("has_evidence")
    if route_score > 0.0:
        reasons.append("route_yield")
    if pending_destination_count:
        reasons.append("pending_destinations")
    if document_signal:
        reasons.append("document_signal")
    if covered_by_shared_evidence:
        reasons.append("covered_by_shared_evidence")
    if local_stop:
        reasons.append(f"local_stop:{local_stop}")
    if not reasons:
        reasons.append("low_observed_value")
    return {
        "schema_version": "agvm.post_final_branch_value.v1",
        "branch_id": str(branch.get("branch_id") or ""),
        "worker_id": str(branch.get("worker_id") or branch.get("branch_id") or ""),
        "goal": goal,
        "planner_family": str(branch.get("planner_family") or ""),
        "origin_families": list(branch.get("origin_families") or []),
        "query_kind": query_kind,
        "round_index": int(round_index or 0),
        "value_score": round(float(value_score), 4),
        "threshold": round(float(threshold), 4),
        "covered_by_shared_evidence": bool(covered_by_shared_evidence),
        "shared_confidence": round(float(shared_confidence), 4),
        "evidence_count": int(evidence_count),
        "visited_bucket_count": int(visited_count),
        "route_trace_count": int(route_trace_count),
        "route_yield": round(float(route_score), 4),
        "pending_destination_count": int(pending_destination_count),
        "branch_priority": round(float(priority_score), 4),
        "required_slot_signal": bool(required_slot_signal),
        "optional_slot_signal": bool(optional_slot_signal),
        "document_signal": bool(document_signal),
        "local_stop_recommendation": local_stop or None,
        "route_state": route_state or None,
        "reasons": reasons[:8],
    }


def _merge_broad_first_answer_facts(*, query_text: str, answer_short: str | None, answer_full: str | None) -> str | None:
    if _query_class(query_text) != "broad_summary":
        return clean_answer_surface_text(answer_full)
    short_clean = polish_final_answer_surface(query_text, answer_short) or clean_answer_surface_text(answer_short)
    full_clean = polish_final_answer_surface(query_text, answer_full) or clean_answer_surface_text(answer_full)
    if not short_clean:
        return full_clean or None
    if not full_clean:
        return short_clean
    full_folded = _fold_text(full_clean)
    missing_short_sentences: list[str] = []
    for sentence in re.split(r"(?<=[.!?])\s+", short_clean):
        cleaned = sentence.strip()
        folded = _fold_text(cleaned)
        if len(folded) < 18:
            continue
        sentence_terms = {term for term in re.findall(r"\b\w{4,}\b", folded) if term}
        if not sentence_terms:
            continue
        covered_terms = {term for term in sentence_terms if term in full_folded}
        coverage_floor = max(2, int(len(sentence_terms) * 0.7 + 0.999))
        if folded not in full_folded and len(covered_terms) < coverage_floor:
            missing_short_sentences.append(cleaned)
    if not missing_short_sentences:
        return full_clean
    merged = " ".join([*missing_short_sentences, full_clean]).strip()
    return polish_final_answer_surface(query_text, merged) or clean_answer_surface_text(merged) or full_clean


def _build_document_dossier(
    *,
    query_text: str,
    document_mode: str,
    document_packets: list[dict[str, Any]],
    answer_short: str | None,
    retrieval_mode: str,
) -> tuple[str | None, str | None]:
    if document_mode == "none" or not document_packets:
        return None, None
    if _is_temporal_reference_query(query_text):
        return None, None
    lead_packet = dict(document_packets[0] or {})
    sections: list[str] = []
    long_form = retrieval_mode in {"heavy", "forensic"} or _document_full_text_requested(query_text)
    packet_limit = 6 if long_form else 4
    for packet in document_packets[:packet_limit]:
        title = str(packet.get("title") or packet.get("source_label") or "Document").strip()
        provenance_summary = str(packet.get("provenance_summary") or "").strip()
        lines = [title if not provenance_summary else f"{title} ({provenance_summary})"]
        full_text_mode = str(packet.get("full_text_mode") or "none").strip()
        raw_text_char_count = int(packet.get("raw_text_char_count") or 0)
        if full_text_mode != "none" or raw_text_char_count > 0:
            lines.append(f"- Raw context: {full_text_mode or 'mixed'}; {raw_text_char_count} chars available")
        lines.extend(_document_packet_raw_lines(dict(packet), long_form=long_form))
        open_questions = [str(item).strip() for item in list(packet.get("open_questions") or []) if str(item).strip()]
        if open_questions and retrieval_mode in {"heavy", "forensic"}:
            lines.append(f"- Open questions: {', '.join(open_questions[:4])}")
        sections.append("\n".join(lines))
    context_dossier = "\n\n".join(sections).strip() or None
    lead_title = str(lead_packet.get("title") or lead_packet.get("source_label") or "documento").strip()
    if long_form and context_dossier:
        intro = answer_short or f"Documento individuato: {lead_title}."
        answer_full = f"{intro}\n\n{context_dossier}".strip()
        cap = 7600 if retrieval_mode == "forensic" else 6200
        answer_full = answer_full[:cap].strip()
    elif document_mode == "lookup":
        answer_full = answer_short or f"Documento individuato: {lead_title}."
    else:
        answer_full = answer_short or f"Risposta costruita dai documenti principali: {lead_title}."
    return answer_full, context_dossier

def _warm_packet_seed_matches(packet: dict[str, Any]) -> list[dict[str, Any]]:
    node_ids = [str(node_id) for node_id in list(packet.get("node_ids") or []) if str(node_id).strip()]
    if not node_ids:
        return []
    supporting_snippets = {
        str(item.get("node_id") or ""): str(item.get("text") or "").strip()
        for item in list(packet.get("supporting_snippets") or [])
        if str(item.get("node_id") or "").strip()
    }
    score_lookup = {
        str(item.get("node_id") or ""): round(float(item.get("score") or packet.get("confidence") or 0.0), 4)
        for item in list(packet.get("evidence_refs") or [])
        if str(item.get("node_id") or "").strip()
    }
    nodes = fetch_nodes_by_ids(node_ids)
    matches: list[dict[str, Any]] = []
    for node in nodes:
        node_id = str(node.get("id") or "")
        if not node_id:
            continue
        matches.append(
            {
                "node_id": node_id,
                "summary": str(node.get("summary") or ""),
                "score": float(score_lookup.get(node_id, packet.get("confidence") or 0.62)),
                "raw_score": float(score_lookup.get(node_id, packet.get("confidence") or 0.62)),
                "probe_id": "warm_thread_state",
                "label": "warm_thread_state",
                "reason": "warm_thread_carryover",
                "sources": ["warm_thread_state"],
                "evidence_snippet": supporting_snippets.get(node_id) or str(node.get("raw_text") or node.get("summary") or ""),
                "node": dict(node),
            }
        )
    return matches


def _continuity_score(query_text: str, packet: dict[str, Any]) -> float:
    return float(_continuity_score_details(query_text, packet).get("continuity_score") or 0.0)


def _semantic_followup_gate(query_text: str, packet: dict[str, Any], deterministic_state: str) -> str | None:
    if not llm_enabled() or deterministic_state != "medium_continuity":
        return None
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": ["continuity_state", "reason"],
        "properties": {
            "continuity_state": {"type": "string", "enum": ["high_continuity", "medium_continuity", "low_continuity"]},
            "reason": {"type": "string"},
        },
    }
    payload, error = structured_json(
        model=retrieval_model(),
        system_prompt=(
            "You are the AGVM follow-up gate. Decide only whether the new query should strongly reuse, partially reuse, "
            "or mostly reset the warm thread state. Prefer low continuity when the carryover would be risky."
        ),
        user_prompt=f"New query: {query_text}\nWarm packet summary: {_summarize_warm_state(packet)}\nTopic signature: {packet.get('topic_signature')}",
        schema_name="agvm_followup_gate",
        schema=schema,
        timeout=1.2,
        role="retrieval",
    )
    if error or not payload:
        return None
    state = str(payload.get("continuity_state") or "").strip()
    return state if state in {"high_continuity", "medium_continuity", "low_continuity"} else None


def _evaluate_continuity_details(
    query_text: str,
    warm_state: dict[str, Any] | None,
    *,
    allow_semantic_gate: bool = True,
) -> dict[str, Any]:
    packet = dict((warm_state or {}).get("warm_packet") or {})
    if not packet:
        return {
            "continuity_state": "low_continuity",
            "deterministic_state": "low_continuity",
            "semantic_state": None,
            "continuity_score": 0.0,
            "warm_layer": "cold",
            "gate_reason": "no_warm_packet",
            "matched_entities": [],
            "matched_slots": [],
            "matched_topic_terms": [],
            "divergence_flags": ["no_warm_packet"],
            "semantic_gate_deferred": False,
            "semantic_gate_required": False,
            "semantic_gate_mode": "not_applicable",
        }
    details = _continuity_score_details(query_text, packet)
    deterministic = str(details.get("deterministic_state") or "low_continuity")
    deterministic_warm_signal = bool(
        deterministic in {"medium_continuity", "high_continuity"}
        and not list(details.get("divergence_flags") or [])
        and (
            bool(details.get("followup_shape"))
            or bool(details.get("implicit_memory_subject"))
            or bool(details.get("matched_entities"))
            or bool(details.get("matched_slots"))
            or bool(details.get("matched_topic_terms"))
            or bool(details.get("matched_follow_up_terms"))
        )
    )
    semantic_gate_required = bool(deterministic == "medium_continuity" and not deterministic_warm_signal)
    semantic_gate_deferred = bool(not allow_semantic_gate and deterministic == "medium_continuity" and llm_enabled())
    semantic_state_raw = _semantic_followup_gate(query_text, packet, deterministic) if allow_semantic_gate else None
    semantic_state = semantic_state_raw
    if semantic_state == "low_continuity" and deterministic_warm_signal:
        semantic_state = None
    if semantic_gate_deferred and semantic_gate_required:
        continuity_state = "low_continuity"
    else:
        continuity_state = semantic_state or deterministic
    warm_layer = "hot" if continuity_state == "high_continuity" else ("warm" if continuity_state == "medium_continuity" else "cold")
    divergence_flags = list(details.get("divergence_flags") or [])
    if semantic_gate_deferred and semantic_gate_required and "semantic_gate_deferred_without_deterministic_signal" not in divergence_flags:
        divergence_flags.append("semantic_gate_deferred_without_deterministic_signal")
    return {
        **details,
        "divergence_flags": divergence_flags,
        "continuity_state": continuity_state,
        "semantic_state": semantic_state,
        "semantic_state_raw": semantic_state_raw,
        "warm_layer": warm_layer,
        "deterministic_warm_signal": deterministic_warm_signal,
        "semantic_gate_deferred": semantic_gate_deferred,
        "semantic_gate_required": semantic_gate_required,
        "semantic_gate_mode": "blocking" if allow_semantic_gate else "deferred_critical_path",
    }


def _evaluate_continuity_state(query_text: str, warm_state: dict[str, Any] | None) -> str:
    return str(_evaluate_continuity_details(query_text, warm_state).get("continuity_state") or "low_continuity")


def _rank_warm_node_ids_for_query(query_text: str, packet: dict[str, Any], *, limit: int) -> list[str]:
    query_terms = set(_warm_terms_from_text(query_text, limit=48))
    if not query_terms:
        return [str(node_id) for node_id in list(packet.get("node_ids") or []) if str(node_id).strip()][:limit]
    snippet_text_by_id = {
        str(item.get("node_id") or ""): str(item.get("text") or "")
        for item in list(packet.get("supporting_snippets") or [])
        if isinstance(item, dict) and str(item.get("node_id") or "").strip()
    }
    ref_score_by_id = {
        str(item.get("node_id") or ""): float(item.get("score") or 0.0)
        for item in list(packet.get("evidence_refs") or [])
        if isinstance(item, dict) and str(item.get("node_id") or "").strip()
    }
    ordered_ids = _dedupe_limited(
        [
            *[str(node_id) for node_id in list(packet.get("node_ids") or []) if str(node_id).strip()],
            *[str(node_id) for node_id in list(dict(packet.get("read_set") or {}).get("node_ids") or []) if str(node_id).strip()],
        ],
        limit=64,
    )
    node_text_by_id: dict[str, str] = {}
    if ordered_ids:
        try:
            for node in fetch_nodes_by_ids(ordered_ids[:64], include_raw_text=True):
                node_id = str(node.get("id") or "").strip()
                if not node_id:
                    continue
                provenance = dict(node.get("provenance") or {})
                node_text_by_id[node_id] = " ".join(
                    str(part or "")
                    for part in (
                        node.get("summary"),
                        node.get("raw_text"),
                        node.get("memory_type"),
                        provenance.get("guide_conceptual_area"),
                    )
                    if str(part or "").strip()
                )
        except Exception:
            node_text_by_id = {}
    packet_terms = set(_warm_terms_from_text(" ".join(_warm_packet_text_values(packet)), limit=200))
    backfill_terms = [
        term
        for term in query_terms
        if term in packet_terms and len(term) >= 4
    ][:6]
    if backfill_terms:
        try:
            for node in fetch_nodes_by_text_terms(backfill_terms, limit=12, include_raw_text=True):
                node_id = str(node.get("id") or "").strip()
                if not node_id or node_id in ordered_ids:
                    continue
                provenance = dict(node.get("provenance") or {})
                ordered_ids.append(node_id)
                node_text_by_id[node_id] = " ".join(
                    str(part or "")
                    for part in (
                        node.get("summary"),
                        node.get("raw_text"),
                        node.get("memory_type"),
                        provenance.get("guide_conceptual_area"),
                    )
                    if str(part or "").strip()
                )
        except Exception:
            pass
    scored: list[tuple[float, int, str]] = []
    for index, node_id in enumerate(ordered_ids):
        support_text = " ".join(
            part
            for part in (
                snippet_text_by_id.get(node_id, ""),
                node_text_by_id.get(node_id, ""),
            )
            if part
        )
        snippet_terms = set(_warm_terms_from_text(support_text, limit=96))
        overlap = len(query_terms & snippet_terms) / max(1, len(query_terms))
        phrase_bonus = 0.0
        folded_support = _fold_text(support_text)
        folded_query = _fold_text(query_text)
        if folded_query and folded_query in folded_support:
            phrase_bonus = 0.22
        elif any(term in folded_support for term in query_terms):
            phrase_bonus = 0.08
        score = overlap + phrase_bonus + min(0.2, ref_score_by_id.get(node_id, 0.0) * 0.2)
        scored.append((score, -index, node_id))
    ranked = [node_id for score, _order, node_id in sorted(scored, reverse=True) if node_id]
    return ranked[:limit]


def _filter_warm_records_by_node_ids(records: list[Any], node_ids: list[str], *, limit: int) -> list[Any]:
    wanted = set(node_ids)
    filtered = [
        item
        for item in records
        if isinstance(item, dict) and str(item.get("node_id") or "").strip() in wanted
    ]
    if not filtered:
        filtered = list(records)
    return filtered[:limit]


def _attach_warm_recall_trace_to_branches(
    branches: list[dict[str, Any]],
    warm_matches: list[dict[str, Any]],
    *,
    continuity_state: str,
) -> None:
    support_ids = [str(match.get("node_id") or "").strip() for match in warm_matches if str(match.get("node_id") or "").strip()]
    support_ids = list(dict.fromkeys(support_ids))[:8]
    if not support_ids:
        return
    lead_match = next((match for match in warm_matches if str(match.get("node_id") or "").strip()), {})
    lead_node_id = str(lead_match.get("node_id") or support_ids[0]).strip()
    route_score = round(float(lead_match.get("score") or lead_match.get("raw_score") or 0.0), 4)
    for branch in branches:
        if list(branch.get("route_trace") or []):
            continue
        destination = _canonical_active_destination(branch.get("active_destination")) or {}
        trace_entry = {
            "source_node_id": None,
            "target_node_id": lead_node_id,
            "to_node_id": lead_node_id,
            "destination_id": destination.get("destination_id"),
            "destination_key": destination.get("destination_key"),
            "destination_label": destination.get("label") or str(branch.get("goal") or "") or None,
            "edge_type": "none",
            "move_type": "hydrate",
            "navigation_action": "warm_thread_recall",
            "candidate_source": "warm_thread_state",
            "travel_performed": False,
            "route_score": route_score,
            "yielded_match_count": len(warm_matches),
            "destination_reached": True,
            "continuity_state": str(continuity_state),
        }
        branch["route_trace"] = [trace_entry]
        branch["move_types"] = list(dict.fromkeys(list(branch.get("move_types") or []) + ["hydrate"]))[:24]
        branch["evidence_node_ids"] = list(dict.fromkeys(list(branch.get("evidence_node_ids") or []) + support_ids))[:24]
        branch["visited_node_ids"] = list(dict.fromkeys(list(branch.get("visited_node_ids") or []) + support_ids))[:24]
        branch["studied_node_ids"] = list(dict.fromkeys(list(branch.get("studied_node_ids") or []) + support_ids))[:24]
        branch["hydrated_node_ids"] = list(dict.fromkeys(list(branch.get("hydrated_node_ids") or []) + support_ids))[:24]
        branch["covered_slots"] = list(dict.fromkeys(list(branch.get("covered_slots") or []) + [_goal_to_slot(str(branch.get("goal") or ""))]))[:12]
        branch["route_yield"] = max(float(branch.get("route_yield") or 0.0), 1.0)
        branch["route_state"] = "goal_satisfied"
        branch["lifecycle_stage"] = "satisfied"
        branch["status"] = "satisfied"
        branch["stop_reason"] = "warm_context_sufficient"


def _apply_warm_state_gate(warm_state: dict[str, Any] | None, continuity_state: str, query_text: str | None = None) -> dict[str, Any] | None:
    packet = dict((warm_state or {}).get("warm_packet") or {})
    if not packet or continuity_state == "low_continuity":
        return None
    if continuity_state == "high_continuity":
        ranked_node_ids = _rank_warm_node_ids_for_query(str(query_text or ""), packet, limit=8)
        packet_node_ids = [str(node_id) for node_id in list(packet.get("node_ids") or []) if str(node_id).strip()]
        return {
            **packet,
            "warm_layer": "hot",
            "node_ids": _dedupe_limited([*ranked_node_ids, *packet_node_ids], limit=max(8, len(packet_node_ids))),
        }
    ranked_node_ids = _rank_warm_node_ids_for_query(str(query_text or ""), packet, limit=5)
    return {
        **packet,
        "warm_layer": "warm",
        "claims": list(packet.get("claims") or [])[:4],
        "node_ids": ranked_node_ids or list(packet.get("node_ids") or [])[:5],
        "evidence_refs": _filter_warm_records_by_node_ids(list(packet.get("evidence_refs") or []), ranked_node_ids, limit=5),
        "supporting_snippets": _filter_warm_records_by_node_ids(list(packet.get("supporting_snippets") or []), ranked_node_ids, limit=5),
        "branch_memory": list(packet.get("branch_memory") or [])[:2],
        "follow_up_candidates": list(packet.get("follow_up_candidates") or [])[:3],
    }


def _query_has_source_pressure(query_text: str) -> bool:
    document_lookup, document_synthesis = _document_mode_keywords(query_text)
    lowered = _fold_text(query_text)
    explicit_source_terms = (
        "cita",
        "citami",
        "riferimento",
        "riferimenti",
        "fonte",
        "fonti",
        "source",
        "sources",
        "provenienza",
        "evidence",
        "ledger",
        "raw context",
        "raw_text",
        "chunk",
        "documento",
        "documenti",
        "file",
        "pdf",
    )
    return bool(document_lookup or document_synthesis or any(term in lowered for term in explicit_source_terms))


def _warm_reuse_budget_decision(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str,
    continuity_state: str,
    warm_state_used: bool,
    warm_usable: bool,
    warm_answerability: str,
) -> dict[str, Any]:
    source_pressure = _query_has_source_pressure(query_text)
    query_contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    contract_validation_required = bool(query_contract.get("requires_expansion")) and not bool(query_contract.get("fast_final_allowed"))
    route_validation_required = bool(
        source_pressure
        or query_class == "document_lookup"
        or str(retrieval_mode or "").strip().lower() == "forensic"
        or contract_validation_required
    )
    base = {
        "max_rounds": None,
        "final_scout_wait_seconds": None,
        "reason": None,
        "source_pressure": source_pressure,
        "route_validation_required": route_validation_required,
        "answer_sufficient": False,
    }
    if not warm_state_used:
        return {**base, "reason": "warm_state_not_used"}
    if continuity_state not in {"high_continuity", "medium_continuity"}:
        return {**base, "reason": "warm_continuity_not_sufficient"}
    answerability = str(warm_answerability or "").strip()
    partial_direct_warm_ok = bool(
        answerability == "partial"
        and not route_validation_required
        and query_class in {"direct_fact", "relation_fact"}
    )
    if not warm_usable or (answerability != "grounded" and not partial_direct_warm_ok):
        return {**base, "reason": "warm_answer_not_grounded"}
    base = {**base, "answer_sufficient": True}
    mode = str(retrieval_mode or "balanced").strip().lower()
    if query_class == "document_lookup" or mode == "forensic":
        return {**base, "reason": "document_or_forensic_requires_full_validation"}
    if source_pressure:
        return {
            **base,
            "max_rounds": 1 if mode in {"flash", "balanced"} else 2,
            "final_scout_wait_seconds": 0.75 if mode == "flash" else 1.25,
            "reason": "warm_context_with_source_validation",
        }
    if contract_validation_required:
        return {
            **base,
            "max_rounds": 1 if mode in {"flash", "balanced"} else 2,
            "final_scout_wait_seconds": 0.75 if mode == "flash" else 1.25,
            "reason": "warm_context_requires_contract_validation",
        }
    if mode == "flash":
        return {
            **base,
            "max_rounds": 0,
            "final_scout_wait_seconds": 0.35,
            "reason": "warm_context_sufficient_flash",
        }
    if mode == "balanced":
        return {
            **base,
            "max_rounds": 0,
            "final_scout_wait_seconds": 0.75,
            "reason": "warm_context_sufficient_balanced",
        }
    if mode == "heavy" and continuity_state == "high_continuity":
        return {
            **base,
            "max_rounds": 1,
            "final_scout_wait_seconds": 1.25,
            "reason": "warm_high_continuity_validation",
        }
    return {**base, "reason": "warm_reuse_keeps_default_budget"}


def _direct_preflight_support_ready(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_payload: dict[str, Any],
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
) -> bool:
    query_class = _query_class(query_text)
    if query_class not in {"direct_fact", "relation_fact", "style_values"}:
        return False
    query_contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    named_targets = _query_named_targets(query_text)
    expansion_requires_contract_proof = bool(query_contract.get("requires_expansion")) and not bool(query_contract.get("fast_final_allowed")) and not named_targets
    relation_requires_contract_proof = query_class == "relation_fact" and not query_contract_allows_fast_final(
        query_text,
        retrieval_mode=retrieval_mode,
        answer=dict(partial_payload.get("answer") or {}),
        shared_evidence=shared_evidence_snapshot,
    )
    expansion_requires_contract_proof = bool(expansion_requires_contract_proof or relation_requires_contract_proof)
    if _is_temporal_reference_query(query_text) or _query_has_source_pressure(query_text):
        return False
    answer = dict(partial_payload.get("answer") or {})
    if relation_requires_contract_proof:
        answer = _apply_answer_contract(query_text, answer, [])
    if bool(answer.get("insufficient")) or str(answer.get("answerability_state") or "").strip() == "insufficient":
        return False
    if query_class == "style_values" and str(answer.get("answerability_state") or "").strip() != "grounded":
        return False
    answer_adequacy = dict(answer.get("answer_adequacy") or {})
    if answer_adequacy and not bool(answer_adequacy.get("passed")):
        return False
    confidence = float(answer.get("confidence") or 0.0)
    support_node_count = int(answer.get("support_node_count") or 0)
    support_slot_count = int(answer.get("support_slot_count") or 0)
    if expansion_requires_contract_proof:
        contract_matrix = build_evidence_satisfaction_matrix(
            query_text=query_text,
            retrieval_mode=retrieval_mode,
            answer=answer,
            shared_evidence=shared_evidence_snapshot,
        )
        required_support = 1
        if not (
            bool(contract_matrix.get("final_ready"))
            and str(answer.get("answerability_state") or "") == "grounded"
            and (
                support_node_count >= required_support
                or support_slot_count >= required_support
                or len(section_snapshots) >= required_support
            )
        ):
            return False
    coverage_by_slot = dict(shared_evidence_snapshot.get("coverage_by_slot") or {})
    max_coverage = max([float(value or 0.0) for value in coverage_by_slot.values()] or [0.0])
    requested_targets = named_targets
    answer_text = _fold_text(
        " ".join(
            str(part or "")
            for part in (
                answer.get("answer_text"),
                partial_payload.get("answer_short"),
                partial_payload.get("answer_full_partial"),
            )
        )
    )
    support_text = _fold_text(
        " ".join(
            [
                json.dumps(partial_payload.get("evidence_snippets") or [], ensure_ascii=False),
                json.dumps(partial_payload.get("context") or {}, ensure_ascii=False),
                str(partial_payload.get("context_dossier_partial") or ""),
            ]
        )
    )
    if requested_targets:
        if support_node_count < 1:
            return False
        for target in requested_targets:
            folded_target = _fold_text(target)
            if folded_target not in answer_text or folded_target not in support_text:
                return False
        return confidence >= 0.56 or max_coverage >= 0.5
    if support_node_count < 1 and support_slot_count < 1 and not section_snapshots:
        return False
    threshold = 0.58 if retrieval_mode == "flash" else 0.62
    return confidence >= threshold or max_coverage >= threshold


def _broad_preflight_support_ready(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_payload: dict[str, Any],
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
) -> bool:
    if _query_class(query_text) != "broad_summary" or retrieval_mode not in {"heavy", "forensic"}:
        return False
    answer = dict(partial_payload.get("answer") or {})
    if bool(answer.get("insufficient")) or str(answer.get("answerability_state") or "").strip() == "insufficient":
        return False
    answer_adequacy = dict(answer.get("answer_adequacy") or {})
    if answer_adequacy and not bool(answer_adequacy.get("passed", True)):
        return False
    coverage_by_slot = {
        str(slot).strip(): float(value or 0.0)
        for slot, value in dict(shared_evidence_snapshot.get("coverage_by_slot") or {}).items()
        if str(slot).strip()
    }
    required_slots = [slot for slot in _required_slots_for_query(query_text) if slot]
    covered_slots = [slot for slot in required_slots if float(coverage_by_slot.get(slot) or 0.0) >= 0.55]
    slot_floor = 5 if retrieval_mode == "heavy" else 6
    evidence_snippets = list(partial_payload.get("evidence_snippets") or [])
    context_dossier_partial = str(partial_payload.get("context_dossier_partial") or "")
    answer_text = clean_answer_surface_text(answer.get("answer_text") or partial_payload.get("answer_short"))
    return (
        len(covered_slots) >= min(slot_floor, len(required_slots))
        and len(section_snapshots) >= 4
        and len(evidence_snippets) >= 5
        and len(answer_text) >= 180
        and len(context_dossier_partial) >= 700
    )


def _direct_preflight_closure_ready(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_payload: dict[str, Any],
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
    preflight_usable: bool,
) -> bool:
    if not preflight_usable:
        return False
    if _broad_preflight_support_ready(
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        partial_payload=partial_payload,
        shared_evidence_snapshot=shared_evidence_snapshot,
        section_snapshots=section_snapshots,
    ):
        return True
    return _direct_preflight_support_ready(
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        partial_payload=partial_payload,
        shared_evidence_snapshot=shared_evidence_snapshot,
        section_snapshots=section_snapshots,
    )


def _answer_partial_usable(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_payload: dict[str, Any],
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
    warm_state_used: bool = False,
    continuity_state: str = "",
) -> bool:
    answer = dict(partial_payload.get("answer") or {})
    if bool(answer.get("insufficient")) or str(answer.get("answerability_state") or "").strip() == "insufficient":
        return False
    answer_adequacy = dict(answer.get("answer_adequacy") or {})
    if answer_adequacy and not bool(answer_adequacy.get("passed")):
        return False
    if str(answer.get("document_lookup_state") or "") in {"no_matching_document_packet", "no_matching_document_packet_yet"}:
        return False
    confidence = float(answer.get("confidence") or 0.0)
    support_node_count = int(answer.get("support_node_count") or 0)
    support_slot_count = int(answer.get("support_slot_count") or 0)
    distinct_evidence_packet_count = int(answer.get("distinct_evidence_packet_count") or 0)
    ordered_document_sequence_supported = bool(answer.get("ordered_document_sequence_supported"))
    support_sufficient = (
        support_node_count >= 2
        or support_slot_count >= 2
        or distinct_evidence_packet_count >= 2
        or ordered_document_sequence_supported
    )
    coverage_by_slot = dict(shared_evidence_snapshot.get("coverage_by_slot") or {})
    max_coverage = max([float(value or 0.0) for value in coverage_by_slot.values()] or [0.0])
    query_class = _query_class(query_text)
    requested_years = re.findall(r"\b(?:19|20)\d{2}\b", str(query_text or ""))
    if requested_years:
        evidence_text = " ".join(
            [
                str(partial_payload.get("answer_short") or ""),
                str(partial_payload.get("answer_full_partial") or ""),
                str(partial_payload.get("context_dossier_partial") or ""),
                json.dumps(partial_payload.get("evidence_snippets") or [], ensure_ascii=False),
                json.dumps(partial_payload.get("context") or {}, ensure_ascii=False),
            ]
        )
        if any(year not in evidence_text for year in requested_years):
            return False
    if _direct_preflight_support_ready(
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        partial_payload=partial_payload,
        shared_evidence_snapshot=shared_evidence_snapshot,
        section_snapshots=section_snapshots,
    ):
        return True
    if (
        query_contract_requires_expansion(query_text, retrieval_mode=retrieval_mode)
        and query_class in {"relation_fact", "style_values", "direct_fact"}
        and (confidence >= 0.5 or max_coverage >= 0.5 or support_node_count >= 1 or bool(section_snapshots))
    ):
        return True
    if (
        warm_state_used
        and continuity_state in {"high_continuity", "medium_continuity"}
        and query_class in {"direct_fact", "relation_fact", "style_values"}
        and not _query_has_source_pressure(query_text)
        and (
            confidence >= 0.58
            or max_coverage >= 0.58
            or support_node_count >= 1
            or bool(section_snapshots)
        )
    ):
        return True
    if query_class in {"direct_fact", "relation_fact", "style_values"} and retrieval_mode == "flash":
        return confidence >= (0.58 if retrieval_mode == "flash" else 0.62) or max_coverage >= (0.58 if retrieval_mode == "flash" else 0.62)
    context_dossier_partial = str(partial_payload.get("context_dossier_partial") or "")
    evidence_snippets = list(partial_payload.get("evidence_snippets") or [])
    if (
        query_class == "broad_summary"
        and retrieval_mode in {"heavy", "forensic"}
        and answer_adequacy.get("passed", True)
        and confidence >= 0.58
        and len(clean_answer_surface_text(answer.get("answer_text") or partial_payload.get("answer_short"))) >= 140
        and len(context_dossier_partial) >= 600
        and len(evidence_snippets) >= 4
        and (len(section_snapshots) >= 2 or len(context_dossier_partial) >= 900)
    ):
        return True
    if not support_sufficient:
        return False
    if retrieval_mode in {"heavy", "forensic"}:
        return len(section_snapshots) >= 2 and max_coverage >= 0.48
    return bool(section_snapshots) and max_coverage >= 0.5


def _decorate_partial_answer_payload(
    payload: dict[str, Any],
    *,
    usable: bool,
    answer_revision: int,
    runtime_phase: str,
    continuity_state: str,
    warm_state_used: bool,
    hot_context_summary: dict[str, Any],
    warm_state_summary: dict[str, Any] | None,
) -> dict[str, Any]:
    return {
        **payload,
        "usable": bool(usable),
        "answer_revision": int(answer_revision),
        "runtime_phase": str(runtime_phase),
        "continuity_state": str(continuity_state),
        "warm_state_used": bool(warm_state_used),
        "hot_context_summary": dict(hot_context_summary or {}),
        "warm_state_summary": dict(warm_state_summary or {}),
    }


def _summarize_blackboard_for_master(blackboard: dict[str, Any], *, max_items_per_slot: int = 3) -> dict[str, Any]:
    facts_by_slot = {}
    for slot, values in dict(blackboard.get("facts_by_slot") or {}).items():
        normalized_values = [_truncate_prompt_text(item, 180) for item in list(values or []) if str(item or "").strip()]
        if normalized_values:
            facts_by_slot[str(slot)] = normalized_values[:max_items_per_slot]
    worker_reports = []
    for report in list(blackboard.get("worker_reports") or [])[:8]:
        worker_reports.append(
            {
                "worker_id": str(report.get("worker_id") or ""),
                "worker_kind": str(report.get("worker_kind") or ""),
                "planner_family": str(report.get("planner_family") or "heuristic"),
                "goal": str(report.get("goal") or ""),
                "status": str(report.get("status") or ""),
                "stop_reason": str(report.get("stop_reason") or ""),
                "evidence_count": int(report.get("evidence_count") or 0),
                "visited_bucket_count": int(report.get("visited_bucket_count") or 0),
                "recommended_next_actions": list(report.get("recommended_next_actions") or [])[:2],
                "expected_answer_field": str(report.get("expected_answer_field") or "") or None,
                "active_destination": _canonical_active_destination(report.get("active_destination")),
                "route_state": str(report.get("route_state") or ""),
                "route_yield": round(float(report.get("route_yield") or 0.0), 4),
                "covered_slots": list(report.get("covered_slots") or [])[:5],
                "controller_recommendation": dict(report.get("controller_recommendation") or {}),
                "controller_kind": str(report.get("controller_kind") or "") or None,
                "controller_decision_source": str(report.get("controller_decision_source") or "") or None,
                "lifecycle_stage": str(report.get("lifecycle_stage") or ""),
            }
        )
    branch_summaries = [
        {
            "branch_id": str(snapshot.get("branch_id") or ""),
            "family_branch_id": str(snapshot.get("family_branch_id") or ""),
            "planner_family": str(snapshot.get("planner_family") or "heuristic"),
            "goal": str(snapshot.get("goal") or ""),
            "expected_answer_field": str(snapshot.get("expected_answer_field") or "") or None,
            "active_destination": _canonical_active_destination(snapshot.get("active_destination")),
            "route_state": str(snapshot.get("route_state") or ""),
            "route_yield": round(float(snapshot.get("route_yield") or 0.0), 4),
            "covered_slots": list(snapshot.get("covered_slots") or [])[:5],
            "controller_recommendation": dict(snapshot.get("controller_recommendation") or {}),
            "controller_kind": str(snapshot.get("controller_kind") or "") or None,
            "controller_decision_source": str(snapshot.get("controller_decision_source") or "") or None,
            "local_stop_recommendation": str(snapshot.get("local_stop_recommendation") or "") or None,
            "lifecycle_stage": str(snapshot.get("lifecycle_stage") or ""),
        }
        for snapshot in list(blackboard.get("branch_summaries") or [])[:8]
    ]
    return {
        "retrieval_mode": str(blackboard.get("retrieval_mode") or ""),
        "required_slots": list(blackboard.get("required_slots") or []),
        "coverage_by_slot": dict(blackboard.get("coverage_by_slot") or {}),
        "unresolved_slots": list(blackboard.get("unresolved_slots") or []),
        "facts_by_slot": facts_by_slot,
        "shared_node_count": len(list(blackboard.get("shared_node_ids") or [])),
        "shared_bucket_count": len(list(blackboard.get("shared_bucket_keys") or [])),
        "contradiction_flags": list(blackboard.get("contradiction_flags") or []),
        "follow_up_candidates": list(blackboard.get("follow_up_candidates") or [])[:4],
        "worker_reports": worker_reports,
        "branch_summaries": branch_summaries,
        "family_overlap": dict(blackboard.get("family_overlap") or {}),
        "family_divergence": dict(blackboard.get("family_divergence") or {}),
        "family_yield": dict(blackboard.get("family_yield") or {}),
        "family_conflicts": list(blackboard.get("family_conflicts") or [])[:6],
        "family_contribution_summary": dict(blackboard.get("family_contribution_summary") or {}),
        "master_state": dict(blackboard.get("master_state") or {}),
    }


def _normalize_master_decision(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if not payload:
        return None
    decision = str(payload.get("decision") or "").strip()
    if decision not in _ALLOWED_MASTER_DECISIONS:
        return None
    normalized = {
        "decision": decision,
        "reason": _truncate_prompt_text(str(payload.get("reason") or "").strip(), 220),
        "target_worker_id": str(payload.get("target_worker_id") or "").strip() or None,
        "target_branch_id": str(payload.get("target_branch_id") or "").strip() or None,
        "delta": float(payload.get("delta") or 0.0),
        "confidence": max(0.0, min(1.0, float(payload.get("confidence") or 0.0))),
        "goal": str(payload.get("goal") or "").strip() or None,
        "worker_kind": str(payload.get("worker_kind") or "").strip() or None,
        "evidence_topic": str(payload.get("evidence_topic") or "").strip() or None,
        "directive": str(payload.get("directive") or "").strip() or None,
        "directive_destination": str(payload.get("directive_destination") or "").strip() or None,
        "target_family": str(payload.get("target_family") or "").strip() or None,
        "hold_reason": _truncate_prompt_text(str(payload.get("hold_reason") or "").strip(), 160) or None,
        "can_answer_now": bool(payload.get("can_answer_now")),
        "should_continue_expanding": bool(payload.get("should_continue_expanding", decision not in {"stop_all", "emit_answer_final"})),
    }
    if decision != "widen_radius":
        normalized["delta"] = 0.0
    return normalized


def master_judge_llm(
    *,
    query_text: str,
    query_class: str,
    retrieval_mode: str,
    blackboard: dict[str, Any],
    round_index: int,
    timing: dict[str, Any],
) -> tuple[dict[str, Any] | None, str | None]:
    if not llm_enabled():
        return None, "llm_disabled"
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": ["decision", "reason", "confidence", "can_answer_now", "should_continue_expanding"],
        "properties": {
            "decision": {"type": "string", "enum": sorted(_ALLOWED_MASTER_DECISIONS)},
            "reason": {"type": "string"},
            "confidence": {"type": "number", "minimum": 0.0, "maximum": 1.0},
            "can_answer_now": {"type": "boolean"},
            "should_continue_expanding": {"type": "boolean"},
            "target_worker_id": {"type": ["string", "null"]},
            "target_branch_id": {"type": ["string", "null"]},
            "delta": {"type": "number"},
            "goal": {"type": ["string", "null"]},
            "worker_kind": {"type": ["string", "null"]},
            "evidence_topic": {"type": ["string", "null"]},
            "directive": {"type": ["string", "null"]},
            "directive_destination": {"type": ["string", "null"]},
            "target_family": {"type": ["string", "null"]},
            "hold_reason": {"type": ["string", "null"]},
        },
    }
    blackboard_summary = _summarize_blackboard_for_master(blackboard)
    system_prompt = (
        "You are the AGVM master retrieval orchestrator.\n\n"
        "Judge whether the current shared blackboard is already sufficient, or which bounded next decision is most useful. "
        "You do not navigate directly and you do not invent facts. "
        "Prefer semantic sufficiency over budget exhaustion. "
        "You must separately decide whether the system can answer now and whether it should continue expanding after that answer. "
        "Use the retrieval mode policy strictly:\n"
        "- flash: stop quickly when one grounded direct fact is strong.\n"
        "- balanced: allow more evidence when slots remain unresolved.\n"
        "- heavy: prefer richer dossier coverage before stopping.\n"
        "- forensic: require source-backed or document-backed resolution when relevant.\n"
        "Choose only one bounded decision from the allowed list. "
        "Compare heuristic and ai branch families explicitly when both are active. "
        "When useful, direct a specific branch toward a destination, hold it, stop it, keep a planner family alive, or suppress a redundant family. "
        "You must act as the semantic director, not as a node-by-node navigator."
    )
    user_prompt = (
        f"Query: {query_text}\n"
        f"Query class: {query_class}\n"
        f"Retrieval mode: {retrieval_mode}\n"
        f"Round: {round_index}\n"
        f"Timing: {timing}\n"
        f"Blackboard: {blackboard_summary}\n"
        "Decide whether the context is already enough to answer now, which branch should continue, stop, reroute, or hold, "
        "whether radius should widen slightly, whether document evidence should be requested, and whether heuristic or ai family should be kept or suppressed."
    )
    if retrieval_mode == "flash":
        timeout = 3.2
    elif retrieval_mode == "balanced":
        timeout = 9.0 if query_class in {"direct_fact", "relation_fact", "style_values"} else 10.5
    elif retrieval_mode == "heavy":
        timeout = 11.5
    else:
        timeout = 13.0
    payload, error = structured_json(
        model=retrieval_model(),
        system_prompt=system_prompt,
        user_prompt=user_prompt,
        schema_name="agvm_master_judge",
        schema=schema,
        timeout=timeout,
        role="retrieval",
    )
    if error:
        return None, error
    return _normalize_master_decision(payload), None


def final_answer_approval_llm(
    *,
    query_text: str,
    retrieval_mode: str,
    answer_short: str | None,
    answer_full: str | None,
    context_dossier: str | None,
    semantic_contract: dict[str, Any],
    ai_materiality_summary: dict[str, Any],
    timing: dict[str, Any],
) -> tuple[dict[str, Any] | None, str | None]:
    if not llm_enabled():
        return None, "llm_disabled"
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": [
            "approve_final",
            "confidence",
            "reason",
            "missing_evidence",
            "answer_directly_addresses_query",
            "context_supports_answer",
            "contains_forbidden_or_off_contract_material",
            "should_continue_expanding",
        ],
        "properties": {
            "approve_final": {"type": "boolean"},
            "confidence": {"type": "number", "minimum": 0.0, "maximum": 1.0},
            "reason": {"type": "string"},
            "missing_evidence": {"type": "array", "maxItems": 8, "items": {"type": "string"}},
            "answer_directly_addresses_query": {"type": "boolean"},
            "context_supports_answer": {"type": "boolean"},
            "contains_forbidden_or_off_contract_material": {"type": "boolean"},
            "should_continue_expanding": {"type": "boolean"},
            "target_family": {"type": ["string", "null"]},
            "next_search_need": {"type": ["string", "null"]},
        },
    }
    contract_summary = {
        "intent": dict((semantic_contract or {}).get("intent") or {}),
        "required_sections": list(((semantic_contract or {}).get("context_contract") or {}).get("required_sections") or []),
        "forbidden_evidence": list((semantic_contract or {}).get("forbidden_evidence") or [])[:12],
        "ai_required": bool((semantic_contract or {}).get("ai_required")),
    }
    prompt_payload = {
        "query": query_text,
        "retrieval_mode": retrieval_mode,
        "answer_short": clean_answer_surface_text(answer_short),
        "answer_full": _truncate_prompt_text(clean_answer_surface_text(answer_full), limit=1800),
        "context_dossier_excerpt": _truncate_prompt_text(context_dossier or "", limit=3600),
        "semantic_contract": contract_summary,
        "ai_materiality": dict(ai_materiality_summary or {}),
        "timing": dict(timing or {}),
    }
    payload, error = structured_json(
        model=retrieval_model(),
        system_prompt=(
            "You are the AGVM final answer approval judge. Do not answer the user. "
            "Approve final sealing only when the answer directly addresses every requested point, "
            "the context supports it, AI material was used, and no forbidden/off-contract material is required by the answer. "
            "If evidence is missing, the answer is empty, or the context includes relevant off-contract contamination, reject and request bounded continuation."
        ),
        user_prompt=json.dumps(prompt_payload, ensure_ascii=False),
        schema_name="agvm_final_answer_approval",
        schema=schema,
        timeout=8.5 if str(retrieval_mode or "balanced") == "balanced" else 10.5,
        role="retrieval",
        max_output_tokens=700,
    )
    if error or not payload:
        return None, error or "llm_empty"
    payload = dict(payload)
    payload["approve_final"] = bool(payload.get("approve_final"))
    payload["confidence"] = max(0.0, min(1.0, float(payload.get("confidence") or 0.0)))
    payload["should_continue_expanding"] = bool(payload.get("should_continue_expanding", not payload["approve_final"]))
    return payload, None


def _fallback_master_decide(
    *,
    query_text: str = "",
    retrieval_mode: str,
    query_class: str,
    branches: list[dict[str, Any]],
    blackboard: dict[str, Any],
    stop_threshold: float,
    round_progress: bool,
) -> dict[str, Any]:
    coverage_by_slot = dict(blackboard.get("coverage_by_slot") or {})
    unresolved_slots = list(blackboard.get("unresolved_slots") or [])
    evidence_satisfaction = dict(blackboard.get("evidence_satisfaction") or {})
    active_branches = [branch for branch in branches if str(branch.get("status") or "") == "active"]
    shared_confidence = max([float(value or 0.0) for value in coverage_by_slot.values()] or [0.0])
    family_divergence = dict(blackboard.get("family_divergence") or {})
    family_yield = dict(blackboard.get("family_yield") or {})
    document_anchor_evidence = any(
        any(bool(match.get("node", {}).get("is_document_anchor")) for match in list(branch.get("top_matches") or [])[:3])
        for branch in branches
    )
    active_branch = next((branch for branch in active_branches if str(branch.get("status") or "") == "active"), None)
    active_family = str((active_branch or {}).get("planner_family") or "")
    if float(family_divergence.get("divergence_ratio") or 0.0) >= 0.55 and len(active_branches) >= 2:
        heuristic_yield = float(family_yield.get("heuristic") or 0.0)
        ai_yield = float(family_yield.get("ai") or 0.0)
        if heuristic_yield > ai_yield + 0.08:
            return {
                "decision": "continue_worker",
                "reason": "heuristic_family_currently_higher_yield",
                "directive": "keep_family",
                "target_family": "heuristic",
                "can_answer_now": shared_confidence >= 0.5,
                "should_continue_expanding": True,
            }
        if ai_yield > heuristic_yield + 0.08:
            return {
                "decision": "continue_worker",
                "reason": "ai_family_currently_higher_yield",
                "directive": "keep_family",
                "target_family": "ai",
                "can_answer_now": shared_confidence >= 0.5,
                "should_continue_expanding": True,
            }
    contract_requires_expansion = bool(
        query_text
        and query_class == "relation_fact"
        and query_contract_requires_expansion(query_text, retrieval_mode=retrieval_mode)
    )
    contract_final_ready = bool(
        blackboard.get("final_closure_ready")
        or evidence_satisfaction.get("final_ready")
    )
    if contract_requires_expansion and contract_final_ready:
        return {
            "decision": "stop_all",
            "reason": "evidence_contract_satisfied",
            "can_answer_now": True,
            "should_continue_expanding": False,
            "directive": "finalize_now",
        }
    if query_class in {"direct_fact", "relation_fact", "style_values"} and shared_confidence >= max(0.62, stop_threshold - 0.08):
        if contract_requires_expansion and active_branches and round_progress:
            return {
                "decision": "continue_worker",
                "reason": "evidence_contract_requires_expansion",
                "directive": "answer_now_and_continue",
                "target_worker_id": str((active_branch or {}).get("worker_id") or (active_branch or {}).get("branch_id") or "") or None,
                "target_branch_id": str((active_branch or {}).get("branch_id") or "") or None,
                "target_family": active_family or None,
                "can_answer_now": True,
                "should_continue_expanding": True,
            }
        return {
            "decision": "stop_all",
            "reason": "evidence_contract_exhausted" if contract_requires_expansion else "high_confidence_direct_fact",
            "can_answer_now": True,
            "should_continue_expanding": False,
            "directive": "finalize_now",
        }
    if query_class == "document_lookup" and document_anchor_evidence and float(coverage_by_slot.get("documents") or 0.0) >= max(0.58, stop_threshold - 0.1):
        return {
            "decision": "stop_all",
            "reason": "document_evidence_sufficient",
            "can_answer_now": True,
            "should_continue_expanding": False,
            "directive": "finalize_now",
        }
    if query_class == "broad_summary" and not unresolved_slots:
        return {
            "decision": "stop_all",
            "reason": "broad_summary_coverage_sufficient",
            "can_answer_now": True,
            "should_continue_expanding": False,
            "directive": "finalize_now",
        }
    if not active_branches and shared_confidence >= 0.55:
        return {
            "decision": "stop_all",
            "reason": "shared_context_sufficient",
            "can_answer_now": True,
            "should_continue_expanding": False,
            "directive": "finalize_now",
        }
    if not round_progress:
        return {
            "decision": "stop_all",
            "reason": "diminishing_returns" if retrieval_mode != "forensic" else "budget_exhausted",
            "can_answer_now": shared_confidence >= 0.45,
            "should_continue_expanding": False,
            "directive": "answer_now" if shared_confidence >= 0.45 else "finalize_now",
        }
    if active_branch and str(active_branch.get("local_stop_recommendation") or "") in {"stop_route_exhausted", "stop_branch"}:
        return {
            "decision": "stop_worker",
            "reason": "route_exhausted",
            "target_worker_id": str(active_branch.get("worker_id") or active_branch.get("branch_id") or "") or None,
            "target_branch_id": str(active_branch.get("branch_id") or "") or None,
            "directive": "stop_branch",
            "directive_destination": str((active_branch.get("active_destination") or {}).get("destination_id") or "") or None,
            "target_family": active_family or None,
            "can_answer_now": shared_confidence >= 0.48,
            "should_continue_expanding": len(active_branches) > 1,
        }
    return {
        "decision": "continue_worker",
        "reason": "continue_worker",
        "target_worker_id": str((active_branch or {}).get("worker_id") or (active_branch or {}).get("branch_id") or "") or None,
        "target_branch_id": str((active_branch or {}).get("branch_id") or "") or None,
        "directive": "answer_now_and_continue" if shared_confidence >= (0.58 if retrieval_mode == "flash" else 0.5) else "continue_branch",
        "directive_destination": str(((active_branch or {}).get("active_destination") or {}).get("destination_id") or "") or None,
        "target_family": active_family or None,
        "can_answer_now": shared_confidence >= (0.58 if retrieval_mode == "flash" else 0.5),
        "should_continue_expanding": True,
    }


def _master_decide(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str,
    branches: list[dict[str, Any]],
    blackboard: dict[str, Any],
    stop_threshold: float,
    round_progress: bool,
    round_index: int,
    timing: dict[str, Any],
) -> dict[str, Any]:
    coverage_by_slot = dict(blackboard.get("coverage_by_slot") or {})
    shared_confidence = max([float(value or 0.0) for value in coverage_by_slot.values()] or [0.0])
    contract_requires_expansion = bool(
        query_text
        and query_class == "relation_fact"
        and query_contract_requires_expansion(query_text, retrieval_mode=retrieval_mode)
    )
    if contract_requires_expansion and timing.get("answer_first_ms") is not None and shared_confidence >= 0.5:
        fallback = _fallback_master_decide(
            query_text=query_text,
            retrieval_mode=retrieval_mode,
            query_class=query_class,
            branches=branches,
            blackboard=blackboard,
            stop_threshold=stop_threshold,
            round_progress=round_progress,
        )
        return {
            **fallback,
            "decision_source": "fallback_contract_after_first_answer",
            "fallback_reason": "contract_sla_guard_after_first_answer",
        }
    if query_class == "broad_summary":
        required_slots = [slot for slot in _required_slots_for_query(query_text) if slot]
        covered_slots = [slot for slot in required_slots if float(coverage_by_slot.get(slot) or 0.0) >= 0.55]
        slot_floor = 5 if retrieval_mode == "heavy" else 6 if retrieval_mode == "forensic" else 4
        if len(covered_slots) >= min(slot_floor, len(required_slots)) and shared_confidence >= 0.55:
            fallback = _fallback_master_decide(
                query_text=query_text,
                retrieval_mode=retrieval_mode,
                query_class=query_class,
                branches=branches,
                blackboard={**blackboard, "unresolved_slots": []},
                stop_threshold=stop_threshold,
                round_progress=round_progress,
            )
            return {
                **fallback,
                "decision_source": "fallback_broad_coverage",
                "fallback_reason": "broad_summary_slot_coverage_sufficient",
            }
    if (
        retrieval_mode == "flash"
        and query_class == "direct_fact"
        and not _explicit_temporal_terms(query_text)
        and shared_confidence >= max(0.6, float(stop_threshold or 0.0) - 0.08)
    ):
        fallback = _fallback_master_decide(
            query_text=query_text,
            retrieval_mode=retrieval_mode,
            query_class=query_class,
            branches=branches,
            blackboard=blackboard,
            stop_threshold=stop_threshold,
            round_progress=round_progress,
        )
        return {
            **fallback,
            "decision_source": "fallback_fast_direct_fact",
            "fallback_reason": "fast_direct_fact_sla_guard",
        }
    if query_class == "direct_fact" and _explicit_temporal_terms(query_text):
        fallback = _fallback_master_decide(
            query_text=query_text,
            retrieval_mode=retrieval_mode,
            query_class=query_class,
            branches=branches,
            blackboard=blackboard,
            stop_threshold=stop_threshold,
            round_progress=round_progress,
        )
        return {
            **fallback,
            "decision_source": "fallback_temporal_guard",
            "fallback_reason": "explicit_temporal_evidence_guard",
        }
    llm_decision, llm_error = master_judge_llm(
        query_text=query_text,
        query_class=query_class,
        retrieval_mode=retrieval_mode,
        blackboard=blackboard,
        round_index=round_index,
        timing=timing,
    )
    if llm_decision:
        return {**llm_decision, "decision_source": "llm", "fallback_reason": None}
    fallback = _fallback_master_decide(
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
        branches=branches,
        blackboard=blackboard,
        stop_threshold=stop_threshold,
        round_progress=round_progress,
    )
    return {
        **fallback,
        "decision_source": _decision_source_from_error(llm_error, fallback_prefix="fallback"),
        "fallback_reason": _fallback_reason_from_error(llm_error),
        "decision_error": llm_error,
    }


def reverse_like_projection(text: str, *, query_text: str | None = None) -> dict[str, Any]:
    basis = str(text or query_text or "").strip()
    query_basis = str(query_text or basis).strip()
    query_class = _query_class(query_basis)
    aspects = detect_query_aspects(query_basis)
    answer_atom = basis or inverse_query_hint(query_basis, intent_type=detect_query_intent(query_basis))
    if query_class == "relation_fact":
        if "father" in aspects:
            answer_atom = f"{answer_atom}. Family memory stating the father's name and grounded family details."
        elif "partner" in aspects:
            answer_atom = f"{answer_atom}. Relationship memory stating the partner's name and bond."
        elif "mentor" in aspects:
            answer_atom = f"{answer_atom}. Relationship memory stating the mentor's name and role."
        else:
            answer_atom = f"{answer_atom}. Relationship memory with a named person."
    elif query_class == "style_values":
        answer_atom = f"{answer_atom}. Communication style, tone, expression, and recurring wording cues."
    elif query_class == "broad_summary":
        answer_atom = (
            f"{answer_atom}. Identity, role, projects, relationships, place, style, values, and history "
            "as separate but cooperating answer memories."
        )
    elif query_class == "document_lookup":
        answer_atom = f"{answer_atom}. Document anchor, document metadata, and source-backed file memory."
    projection = heuristic_projection(answer_atom)
    expected_guide_area = _guide_area_for_query_text(query_basis, projection.get("expected_guide_area"))
    if expected_guide_area:
        projection["expected_guide_area"] = expected_guide_area
    if query_class == "relation_fact":
        projection["memory_type"] = "relational"
    elif query_class == "style_values":
        projection["memory_type"] = "identity_style" if "style" in aspects else "value"
    elif query_class == "document_lookup":
        projection["memory_type"] = "document_anchor"
    elif query_class == "direct_fact" and "role" in aspects:
        projection["memory_type"] = "knowledge"
    return projection


def _vector_stats(values: list[float]) -> tuple[float, float, float]:
    if not values:
        return 0.0, 0.0, 0.0
    mean = sum(values) / len(values)
    variance = sum((value - mean) ** 2 for value in values) / len(values)
    return mean, variance**0.5, max(values) - min(values)


def _distribution_is_degenerate(score_map: dict[str, Any], fields: tuple[str, ...] | list[str]) -> bool:
    normalized = normalize_scores(dict(score_map or {}), fields)
    values = [float(normalized.get(field) or 0.0) for field in fields]
    _mean, stdev, spread = _vector_stats(values)
    top = max(values, default=0.0)
    return stdev <= 0.025 or spread <= 0.09 or top <= (1.0 / max(1, len(values))) + 0.06


def _blend_score_maps(
    primary: dict[str, Any],
    fallback: dict[str, Any],
    fields: tuple[str, ...] | list[str],
    *,
    fallback_weight: float,
) -> dict[str, float]:
    weight = max(0.0, min(1.0, float(fallback_weight)))
    return normalize_scores(
        {
            field: (1.0 - weight) * float(dict(primary or {}).get(field) or 0.0) + weight * float(dict(fallback or {}).get(field) or 0.0)
            for field in fields
        },
        fields,
    )


def _default_search_radius(radial_expectation: str, expected_memory_type: str | None) -> float:
    base = {
        "core": 0.18,
        "inner": 0.24,
        "mid": 0.30,
        "outer": 0.36,
    }.get(str(radial_expectation or "mid"), 0.28)
    normalized_type = str(expected_memory_type or "").strip().lower()
    if normalized_type in {"identity", "relational", "value", "identity_style"}:
        base = min(base, 0.24)
    elif normalized_type in {"episodic", "document_anchor"}:
        base = min(0.42, base + 0.04)
    return base


def _clamp_search_radius(requested: Any, radial_expectation: str, expected_memory_type: str | None) -> float:
    default = _default_search_radius(radial_expectation, expected_memory_type)
    lower = max(0.12, default - 0.06)
    upper = min(0.42, default + 0.08)
    requested_value = float(requested or default)
    return round(max(lower, min(upper, requested_value)), 4)


def _goal_type_compatibility(probe: dict[str, Any], candidate: dict[str, Any]) -> float:
    goal = str(probe.get("goal") or "").strip().lower()
    candidate_type = str(candidate.get("memory_type") or "").strip().lower()
    expected_memory_type = str(probe.get("expected_memory_type") or "").strip().lower()
    is_document_anchor = bool(candidate.get("is_document_anchor"))

    if goal == "name":
        if candidate_type == "identity":
            return 1.0
        if is_document_anchor:
            return 0.86
        if candidate_type in {"knowledge", "relational"}:
            return 0.7
    if goal in {"birthplace", "residence"}:
        if candidate_type in {"knowledge", "episodic"}:
            return 1.0
        if is_document_anchor:
            return 0.88
        if candidate_type == "identity":
            return 0.72
    if goal in {"family", "father", "partner", "mentor", "sibling"}:
        if is_document_anchor:
            return 1.0
        if candidate_type == "relational":
            return 0.82
        if goal == "father" and candidate_type == "identity":
            return 0.78
        if candidate_type in {"identity", "knowledge"}:
            return 0.58
    if goal == "role":
        if candidate_type == "knowledge":
            return 1.0
        if is_document_anchor:
            return 0.92
        if candidate_type == "technical":
            return 0.82
        if candidate_type == "identity":
            return 0.56
        if candidate_type == "project":
            return 0.28
    if goal == "projects":
        if candidate_type == "project":
            return 1.0
        if is_document_anchor:
            return 0.82
        if candidate_type in {"knowledge", "technical"}:
            return 0.7
    if goal == "company_founding":
        if candidate_type == "project":
            return 1.0
        if is_document_anchor or candidate_type in {"document_anchor", "document_chunk", "document_fact"}:
            return 0.94
        if candidate_type in {"knowledge", "technical"}:
            return 0.74
    if goal == "style":
        if candidate_type == "identity_style":
            return 1.0
        if candidate_type == "technical" or is_document_anchor:
            return 0.78
        if candidate_type in {"identity", "value"}:
            return 0.62
    if goal == "values":
        if candidate_type == "value":
            return 1.0
        if candidate_type == "identity":
            return 0.76
        if is_document_anchor:
            return 0.62
    if goal == "history":
        if candidate_type in {"episodic", "document_anchor"} or is_document_anchor:
            return 1.0
        if candidate_type in {"identity", "project"}:
            return 0.64
    if goal == "documents":
        if is_document_anchor or candidate_type == "document_anchor":
            return 1.0
        if candidate_type in {"knowledge", "relational", "project"}:
            return 0.52
        return 0.18

    if expected_memory_type:
        return 1.0 if expected_memory_type == candidate_type else (0.55 if not expected_memory_type else 0.18)
    return 0.55


def _relation_signal_for_probe(probe: dict[str, Any], node: dict[str, Any], identity_context: dict[str, Any] | None) -> float:
    text = f"{node.get('summary') or ''} {node.get('raw_text') or ''}".lower()
    query_text = str(probe.get("query_text") or "").lower()
    answer_hypothesis = str(probe.get("answer_hypothesis") or "").lower()
    intent_type = str(probe.get("intent_type") or "").strip()
    goal = str(probe.get("goal") or "").strip().lower()
    memory_type = str(node.get("memory_type") or "")
    guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or "")
    nucleus = identity_context or {}

    def contains_any(values: list[str], haystack: str) -> bool:
        return any(value and value.lower() in haystack for value in values)

    if goal == "name" or intent_type == "identity_name":
        name_candidates = [str(item).lower() for item in list(nucleus.get("self_name_candidates") or []) if item]
        if contains_any(name_candidates, text):
            return 1.0
        return 0.78 if memory_type == "identity" else 0.0

    if goal == "birthplace" or intent_type == "birthplace" or any(token in query_text for token in ("nato", "nata", "born", "birth")):
        return 1.0 if any(token in text for token in ("nato", "nata", "born", "birth")) else 0.0

    if goal == "residence":
        return 1.0 if any(token in text for token in ("vive a", "lives in")) else 0.0

    if goal == "role":
        role_candidates = [str(item).lower() for item in list(nucleus.get("role_candidates") or []) if item]
        if contains_any(role_candidates, text):
            return 1.0
        if any(token in text for token in ("lavora come", "lavoro come", "works as", "i work as")):
            return 0.94
        return 0.0

    if goal == "projects" or (intent_type == "workplace" and not _is_role_query(query_text)):
        project_candidates = [str(item).lower() for item in list(nucleus.get("project_candidates") or []) if item]
        employer_candidates = [str(item).lower() for item in list(nucleus.get("employer_candidates") or []) if item]
        if contains_any(project_candidates, text):
            return 1.0
        if contains_any(employer_candidates, text) and any(token in text for token in ("inside", "dentro", "works on", "lavora su", "build", "guida")):
            return 0.92
        if memory_type == "project" and any(token in text for token in ("build", "construct", "progetto", "project", "guida", "works on", "lavora su")):
            return 0.82

    if goal == "company_founding":
        company_signal = _company_affiliation_signal_score(f"{text} {answer_hypothesis}")
        if company_signal >= 0.68:
            return max(0.9, company_signal)
        if company_signal >= 0.42:
            return max(0.72, company_signal)

    if goal == "father" or intent_type == "father_name" or any(token in query_text for token in ("padre", "papa", "father", "dad")):
        if any(token in text for token in ("padre", "papa", "father", "dad")):
            return 0.84

    if goal == "partner" or intent_type == "partner_name" or any(token in query_text for token in ("partner", "fidanz", "girlfriend", "wife", "husband")):
        partner_candidates = [str(item).lower() for item in list(nucleus.get("partner_candidates") or []) if item]
        if contains_any(partner_candidates, text) and any(token in text for token in ("partner", "fidanz", "girlfriend", "wife", "husband")):
            return 1.0
        if contains_any(partner_candidates, answer_hypothesis) and contains_any(partner_candidates, text):
            return 0.9
        if any(token in text for token in ("partner", "fidanz", "girlfriend", "wife", "husband")):
            return 0.72

    if goal == "mentor" or any(token in query_text for token in ("mentor", "mentore")):
        mentor_candidates = [str(item).lower() for item in list(nucleus.get("mentor_candidates") or []) if item]
        if contains_any(mentor_candidates, text) and any(token in text for token in ("mentor", "mentore")):
            return 1.0
        if contains_any(mentor_candidates, answer_hypothesis) and contains_any(mentor_candidates, text):
            return 0.9
        if any(token in text for token in ("mentor", "mentore")):
            return 0.72

    if goal == "sibling":
        sibling_candidates = [str(item).lower() for item in list(nucleus.get("sibling_candidates") or []) if item]
        if contains_any(sibling_candidates, text) and any(token in text for token in ("fratello", "sorella", "brother", "sibling")):
            return 1.0
        if any(token in text for token in ("fratello", "sorella", "brother", "sibling")):
            return 0.72

    if goal == "style":
        style_descriptor_tokens = ("dirett", "tecnic", "strutturat", "lucid", "chiar", "concis", "essenzial", "analitic", "precis", "ridond")
        communication_tokens = ("comunica", "parla", "scrive", "si esprime", "stile", "communication style", "tone", "voice", "spiega")
        technical_structure_tokens = ("codice", "code", "architett", "struttura", "dettagli", "sistema", "system", "research", "ricerca", "document")
        if any(token in text for token in ("parla in modo", "stile di comunicazione", "communication style")):
            return 1.0
        if (guide_area == "Expression" or memory_type == "identity_style") and any(token in text for token in style_descriptor_tokens):
            return 0.96
        if any(token in text for token in ("diretto", "direct")) and any(token in text for token in ("tecnico", "technical", "architett", "codice", "struttura")):
            return 0.92
        if any(token in text for token in communication_tokens) and any(token in text for token in style_descriptor_tokens):
            return 0.88
        if any(token in text for token in technical_structure_tokens) and any(token in text for token in ("spiega", "spiegando", "struttura", "dettagli", "conversazioni", "documenti", "documents")):
            return 0.8
        return 0.0

    if goal == "values":
        if (guide_area == "Values" or memory_type == "value") and any(token in text for token in _VALUE_SIGNAL_TERMS):
            return 0.94
        if any(token in text for token in _VALUE_SIGNAL_TERMS):
            return 0.88

    if goal == "history":
        if any(token in text for token in ("ho lavorato", "in passato", "prima di", "history", "passato")):
            return 0.9

    if goal == "documents":
        if bool(node.get("is_document_anchor")):
            return 1.0
        if any(token in text for token in ("documento", "document", "pdf", "memo", "report", "note", "spec")):
            return 0.78

    return float(node.get("identity_resolution_confidence") or 0.0)


