def _identity_subject_terms(identity_context: dict[str, Any] | None) -> list[str]:
    context = dict(identity_context or {})
    values: list[str] = [
        str(context.get("core_name") or ""),
        *[str(item or "") for item in list(context.get("self_name_candidates") or [])],
        *[str(item or "") for item in list(context.get("aliases") or [])],
    ]
    terms: list[str] = []
    for value in values:
        folded = _fold_text(value)
        if len(folded) < 4:
            continue
        if folded not in terms:
            terms.append(folded)
    return terms[:8]


def _node_text_is_subject_anchored(node: dict[str, Any], identity_context: dict[str, Any] | None) -> bool:
    text = _fold_text(
        " ".join(
            str(value or "")
            for value in (
                node.get("summary"),
                node.get("raw_text"),
                (node.get("provenance") or {}).get("source_label"),
            )
        )
    )
    if not text:
        return False
    if any(term and term in text for term in _identity_subject_terms(identity_context)):
        return True
    return any(marker in text for marker in _FIRST_PERSON_SUBJECT_ANCHOR_TERMS)


def _subject_anchored_goal_text_nodes(
    goal: str,
    terms: tuple[str, ...],
    identity_context: dict[str, Any] | None,
    *,
    limit: int,
) -> list[dict[str, Any]]:
    if goal not in {"style", "values"} or not terms:
        return []
    try:
        nodes = fetch_nodes_by_text_terms(list(terms), limit=max(int(limit) * 4, 48), include_raw_text=True)
    except Exception:
        return []
    filtered: list[dict[str, Any]] = []
    for node in nodes:
        if not is_answer_eligible(node):
            continue
        if not _node_text_is_subject_anchored(dict(node), identity_context):
            continue
        folded = _fold_text(f"{node.get('summary') or ''} {node.get('raw_text') or ''}")
        if not any(_fold_text(term) in folded for term in terms):
            continue
        filtered.append(dict(node))
        if len(filtered) >= max(1, int(limit)):
            break
    return filtered


def _is_role_query(query_text: str) -> bool:
    lowered = query_text.lower()
    return any(token in lowered for token in ("che lavoro", "what does", "job", "ruolo", "works as", "lavora come", "occupation", "professione"))


