def _derived_retrieval_aliases_for_text(text: str, *, limit: int = 36) -> list[str]:
    folded = f" {_fold_text(text)} "
    aliases: list[str] = []
    alias_seen: set[str] = set()

    def add(alias: str) -> None:
        cleaned = " ".join(str(alias or "").split()).strip()
        if not cleaned:
            return
        folded_alias = _fold_text(cleaned)
        if not folded_alias or folded_alias in folded:
            return
        if folded_alias in alias_seen:
            return
        alias_seen.add(folded_alias)
        aliases.append(cleaned)

    for triggers, derived_aliases in _DERIVED_RETRIEVAL_ALIAS_RULES:
        trigger_hit = False
        for trigger in triggers:
            folded_trigger = _fold_text(trigger)
            if not folded_trigger:
                continue
            if f" {folded_trigger} " in folded or (len(folded_trigger) >= 6 and folded_trigger in folded):
                trigger_hit = True
                break
        if trigger_hit:
            for alias in derived_aliases:
                add(alias)
                if len(aliases) >= limit:
                    return aliases
    return aliases


def _node_retrieval_surface(node: dict[str, Any]) -> str:
    aliases = [
        str(item).strip()
        for item in list(node.get("retrieval_aliases") or [])
        if str(item).strip()
    ]
    affordance = dict(node.get("retrieval_affordance") or {})
    affordance_parts = [
        str(affordance.get("question") or "").strip(),
        str(affordance.get("answer_claim") or "").strip(),
    ]
    stored_surface_parts = [
        str(node.get("summary") or "").strip(),
        str(node.get("raw_text") or "").strip(),
        *aliases,
        *affordance_parts,
    ]
    derived_aliases = _derived_retrieval_aliases_for_text(" ".join(part for part in stored_surface_parts if part))
    return " ".join(
        part
        for part in [
            *stored_surface_parts,
            *derived_aliases,
        ]
        if part
    )


def rank_candidate(
    probe: dict[str, Any],
    candidate: dict[str, Any],
    sources: list[str],
    *,
    identity_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    routing_similarity = semantic_similarity(probe["routing_semantic_scores"], candidate["routing_semantic_scores"], ROUTING_FIELDS)
    facet_similarity = semantic_similarity(probe["routing_facets"], candidate["routing_facets"], FACET_FIELDS)
    retrieval_surface = _node_retrieval_surface(candidate)
    summary_grounding = lexical_overlap(
        str(probe.get("answer_hypothesis") or probe["query_text"]),
        retrieval_surface,
    )
    spatial_fit = max(
        0.0,
        1.0 - min(
            1.0,
            distance(probe.get("landing_position") or probe["base_position"], candidate["final_position"])
            / max(0.18, float(probe.get("search_radius") or 0.28) * 2.0),
        ),
    )
    source_reliability_fit = float(candidate["routing_facets"].get("source_reliability", 0.0))
    goal = str(probe.get("goal") or "").strip().lower()
    candidate_text = retrieval_surface.lower()
    temporal_exact_fit = _temporal_exact_match_score(str(probe.get("query_text") or ""), candidate_text)
    candidate_area = str(candidate["provenance"].get("guide_conceptual_area") or "")
    guide_area_alignment = (
        1.0
        if probe.get("expected_guide_area")
        and probe.get("expected_guide_area") == candidate["provenance"].get("guide_conceptual_area")
        else 0.45
    )
    type_compatibility = _goal_type_compatibility(probe, candidate)
    identity_fit = _relation_signal_for_probe(probe, candidate, identity_context)
    confidence_fit = max(
        float(candidate.get("memory_confidence") or 0.0),
        float(candidate.get("evidence_confidence") or 0.0),
        float(candidate.get("identity_resolution_confidence") or 0.0),
    )
    source_prior = _source_prior_for_probe(probe, candidate, sources)
    support_bonus = 0.0
    if "goal_support" in sources:
        support_bonus = 0.18
    elif "goal_subject_text" in sources:
        support_bonus = 0.18
    elif "goal_text" in sources:
        support_bonus = 0.16
    elif "exact_temporal" in sources:
        support_bonus = 0.22
    elif "identity_core" in sources and str(probe.get("goal") or "") in {"name", "birthplace", "residence", "role", "family", "father", "partner", "mentor", "sibling"}:
        support_bonus = 0.08
    raw_score = (
        0.27 * routing_similarity
        + 0.14 * facet_similarity
        + 0.20 * spatial_fit
        + 0.18 * summary_grounding
        + 0.08 * identity_fit
        + 0.06 * guide_area_alignment
        + 0.05 * type_compatibility
        + 0.03 * source_reliability_fit
        + 0.02 * confidence_fit
        + 0.02 * source_prior
        + support_bonus
    )
    if goal == "style":
        if candidate_area == "Expression":
            raw_score += 0.18
        if str(candidate.get("memory_type") or "") == "identity_style":
            raw_score += 0.12
        if any(token in candidate_text for token in ("dirett", "tecnic", "strutturat", "lucid", "chiar", "concis", "essenzial", "analitic", "ridond")):
            raw_score += 0.16
        if any(token in candidate_text for token in ("codice", "code", "architett", "struttura", "dettagli")):
            raw_score += 0.08
        if str(candidate.get("memory_type") or "") == "identity" and candidate_area not in {"Expression", "Media Signals"}:
            raw_score -= 0.1
    elif goal == "values":
        if candidate_area == "Values":
            raw_score += 0.14
        if str(candidate.get("memory_type") or "") == "value":
            raw_score += 0.12
        if any(token in candidate_text for token in (*_VALUE_SIGNAL_TERMS, "coerenza architetturale")):
            raw_score += 0.12
    elif goal == "documents":
        if candidate.get("is_document_anchor"):
            raw_score += 0.34
        if candidate_area == "Media Signals":
            raw_score += 0.1
        if any(token in candidate_text for token in ("documento", "document", "pdf", "memo", "report", "note", "spec")):
            raw_score += 0.12
        elif not candidate.get("is_document_anchor"):
            raw_score -= 0.16
    elif goal == "company_founding":
        company_signal = _company_affiliation_signal_score(retrieval_surface)
        if company_signal >= 0.42:
            raw_score += 0.22 * company_signal
        if candidate_area in {"Projects", "Media Signals"}:
            raw_score += 0.08
        if candidate.get("is_document_anchor") and company_signal >= 0.42:
            raw_score += 0.08
    if goal == "history" and _explicit_temporal_terms(str(probe.get("query_text") or "")):
        if temporal_exact_fit > 0:
            raw_score += 0.42 + 0.08 * temporal_exact_fit
        else:
            raw_score -= 0.12
    raw_score += 0.35 * intent_bonus(probe.get("intent_type"), candidate)
    raw_score = max(0.0, min(1.0, raw_score))
    return {
        "node_id": candidate["id"],
        "summary": candidate["summary"],
        "score": round(raw_score * float(probe["weight"]), 6),
        "raw_score": round(raw_score, 6),
        "probe_id": probe["probe_id"],
        "label": probe["label"],
        "reason": (
            f"summary={summary_grounding:.2f}; routing={routing_similarity:.2f}; "
            f"spatial={spatial_fit:.2f}; type={type_compatibility:.2f}; identity={identity_fit:.2f}; "
            f"temporal={temporal_exact_fit:.2f}; confidence={confidence_fit:.2f}"
        ),
        "sources": sources,
        "evidence_snippet": None,
        "node": candidate,
    }


def _evidence_snippet(query_text: str, answer_hypothesis: str, raw_text: str, *, limit: int = 220) -> str:
    source = " ".join(str(raw_text or "").split())
    if len(source) <= limit:
        return source
    tokens = [token for token in re.findall(r"\w+", f"{query_text} {answer_hypothesis}".lower()) if len(token) > 2]
    lowered = source.lower()
    start = 0
    for token in tokens:
        index = lowered.find(token)
        if index >= 0:
            start = max(0, index - 48)
            break
    snippet = source[start : start + limit]
    if start > 0:
        snippet = f"...{snippet}"
    if start + limit < len(source):
        snippet = f"{snippet.rstrip()}..."
    return snippet


def rerank_hydrated_matches(
    probe: dict[str, Any],
    matches: list[dict[str, Any]],
    *,
    hydrate_limit: int,
    max_nodes_fulltext: int,
    identity_context: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    hydrate_cap = max(hydrate_limit, max_nodes_fulltext + 6)
    hydrate_ids = [match["node_id"] for match in matches[:hydrate_limit]]
    for match in matches:
        sources = list(match.get("sources") or [])
        if (
            "goal_support" in sources
            or "goal_subject_text" in sources
            or "goal_text" in sources
            or "exact_temporal" in sources
            or ("identity_core" in sources and str(probe.get("goal") or "") in {"name", "birthplace", "residence", "family", "father", "partner", "mentor", "sibling", "role"})
            or (match.get("node") or {}).get("is_document_anchor")
        ) and match["node_id"] not in hydrate_ids:
            hydrate_ids.append(match["node_id"])
        if len(hydrate_ids) >= hydrate_cap:
            break
    hydrated = {node["id"]: node for node in fetch_nodes_by_ids(hydrate_ids, include_raw_text=True)}
    reranked: list[dict[str, Any]] = []
    for match in matches:
        node = hydrated.get(match["node_id"], match["node"])
        retrieval_surface = _node_retrieval_surface(node)
        lexical = lexical_overlap(probe["query_text"], retrieval_surface)
        hypothesis_lexical = lexical_overlap(
            str(probe.get("answer_hypothesis") or probe["query_text"]),
            retrieval_surface,
        )
        type_compatibility = _goal_type_compatibility(probe, node)
        identity_fit = _relation_signal_for_probe(probe, node, identity_context)
        spatial_fit = max(
            0.0,
            1.0 - min(
                1.0,
                distance(probe.get("landing_position") or probe["base_position"], node["final_position"])
                / max(0.18, float(probe.get("search_radius") or 0.28) * 2.0),
            ),
        )
        raw_score = (
            0.18 * float(match["raw_score"])
            + 0.30 * hypothesis_lexical
            + 0.20 * lexical
            + 0.12 * type_compatibility
            + 0.16 * identity_fit
            + 0.06 * spatial_fit
            + 0.04 * max(float(node.get("memory_confidence") or 0.0), float(node.get("evidence_confidence") or 0.0))
            + 0.02 * intent_bonus(probe.get("intent_type"), node)
        )
        sources = list(match.get("sources") or [])
        goal = str(probe.get("goal") or "")
        node_text = retrieval_surface.lower()
        temporal_exact_fit = _temporal_exact_match_score(str(probe.get("query_text") or ""), node_text)
        if "goal_support" in sources:
            raw_score += 0.22
        elif "goal_subject_text" in sources:
            raw_score += 0.24
        elif "goal_text" in sources:
            raw_score += 0.2
        elif "exact_temporal" in sources:
            raw_score += 0.24
        elif "identity_core" in sources and goal in {"name", "birthplace", "residence", "role", "family", "father", "partner", "mentor", "sibling"}:
            raw_score += 0.08
        if goal in {"family", "father", "partner", "mentor", "sibling"} and node.get("is_document_anchor") and identity_fit >= 0.85:
            raw_score += 0.16
        if goal == "role" and any(token in node_text for token in ("lavora come", "works as", "lavoro come", "role")):
            raw_score += 0.18
        if goal == "style":
            guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or "")
            if guide_area == "Expression":
                raw_score += 0.24
            if str(node.get("memory_type") or "") == "identity_style":
                raw_score += 0.12
            if any(token in node_text for token in ("dirett", "tecnic", "strutturat", "lucid", "chiar", "concis", "essenzial", "analitic", "ridond")):
                raw_score += 0.22
            if any(token in node_text for token in ("codice", "code", "architett", "struttura", "dettagli", "research", "ricerca", "document")):
                raw_score += 0.08
            if guide_area not in {"Expression", "Media Signals"} and not any(token in node_text for token in ("dirett", "tecnic", "strutturat", "lucid", "chiar")):
                raw_score -= 0.14
        if goal == "values":
            guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or "")
            if guide_area == "Values":
                raw_score += 0.18
            if str(node.get("memory_type") or "") == "value":
                raw_score += 0.12
            if any(token in node_text for token in (*_VALUE_SIGNAL_TERMS, "coerenza architetturale")):
                raw_score += 0.16
        if goal == "documents":
            guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or "")
            if bool(node.get("is_document_anchor")):
                raw_score += 0.34
            if guide_area == "Media Signals":
                raw_score += 0.1
            if any(token in node_text for token in ("documento", "document", "pdf", "memo", "report", "note", "spec")):
                raw_score += 0.16
            elif not bool(node.get("is_document_anchor")):
                raw_score -= 0.18
        if goal == "company_founding":
            guide_area = str((node.get("provenance") or {}).get("guide_conceptual_area") or "")
            company_signal = _company_affiliation_signal_score(retrieval_surface)
            if company_signal >= 0.42:
                raw_score += 0.28 * company_signal
            if guide_area in {"Projects", "Media Signals"}:
                raw_score += 0.1
            if bool(node.get("is_document_anchor")) and company_signal >= 0.42:
                raw_score += 0.1
        if goal == "history" and _explicit_temporal_terms(str(probe.get("query_text") or "")):
            if temporal_exact_fit > 0:
                raw_score += 0.46 + 0.1 * temporal_exact_fit
            else:
                raw_score -= 0.14
        if goal in {"family", "father", "partner", "mentor", "sibling", "role"} and identity_fit < 0.35 and hypothesis_lexical < 0.12:
            raw_score -= 0.16
        raw_score = max(0.0, min(1.0, raw_score))
        reranked.append(
            {
                **match,
                "summary": str(node.get("summary") or match["summary"]),
                "score": round(raw_score * float(probe["weight"]), 6),
                "raw_score": round(raw_score, 6),
                "reason": (
                    f"grounding={hypothesis_lexical:.2f}; lexical={lexical:.2f}; "
                    f"type={type_compatibility:.2f}; identity={identity_fit:.2f}; temporal={temporal_exact_fit:.2f}; spatial={spatial_fit:.2f}"
                ),
                "evidence_snippet": _evidence_snippet(
                    probe["query_text"],
                    str(probe.get("answer_hypothesis") or probe["query_text"]),
                    str(node.get("raw_text") or node.get("summary") or ""),
                ),
                "node": node,
            }
        )
    reranked.sort(key=lambda item: (-item["raw_score"], item["node_id"]))
    return reranked


def compute_satisfaction(matches: list[dict[str, Any]]) -> float:
    if not matches:
        return 0.0
    top1 = float(matches[0]["raw_score"])
    top3 = matches[:3]
    mean_top3 = sum(float(item["raw_score"]) for item in top3) / len(top3)
    evidence_bonus = sum(float(item["node"].get("evidence_confidence") or 0.0) for item in top3) / len(top3)
    return round(0.55 * top1 + 0.25 * mean_top3 + 0.20 * evidence_bonus, 6)


def retrieve(query: RetrieveRequest, graph: dict[str, Any], index_payload: dict[str, Any], atlas_payload: dict[str, Any]) -> dict[str, Any]:
    identity_context = build_identity_context(graph)
    planner_payload, planner_error = llm_retrieval_plan(query, identity_context, atlas_payload)
    if planner_payload:
        raw_specs = list(planner_payload.get("probes") or [])[: query.max_total_branches]
        probes = [
            build_probe_from_spec(
                spec,
                index + 1,
                root_query_text=query.query_text,
                atlas_payload=atlas_payload,
                identity_context=identity_context,
            )
            for index, spec in enumerate(raw_specs)
        ]
        planner_mode = "llm"
        stop_threshold = max(0.5, min(0.99, float((planner_payload.get("stop_policy") or {}).get("stop_when_confidence_ge") or 0.82)))
        decomposition_mode = "llm"
    else:
        probes, stop_threshold, decomposition_mode = fallback_retrieval_plan(
            query,
            atlas_payload=atlas_payload,
            identity_context=identity_context,
        )
        planner_mode = "heuristic"

    visited_node_ids: set[str] = set()
    visited_bucket_keys: set[str] = set()
    all_steps: list[dict[str, Any]] = []
    aggregated: dict[str, dict[str, Any]] = {}
    atlas_shortlists = {probe["probe_id"]: shortlist_atlas_buckets(atlas_payload, probe.get("landing_position") or probe["base_position"]) for probe in probes}
    branches: list[dict[str, Any]] = []
    shared_topics: dict[str, dict[str, Any]] = {}

    for probe in probes:
        probe["target_bucket_keys"] = [bucket["bucket_key"] for bucket in atlas_shortlists[probe["probe_id"]]]
        branches.append(
            {
                "branch_id": f"branch_{probe['probe_id']}",
                "probe_ids": [probe["probe_id"]],
                "goal": probe["goal"],
                "status": "active",
                "success_criteria": {
                    "min_confidence": probe["success_min_confidence"],
                },
                "budget": {
                    "max_steps": min(query.max_steps, query.max_total_steps),
                    "max_candidate_reads": query.max_candidates_per_step,
                    "max_nearby_bundles": 2,
                    "max_fulltexts": query.max_nodes_fulltext,
                    "max_text_chars": max(
                        200,
                        min(query.max_total_text_chars, int(probe.get("max_text_chars") or query.max_total_text_chars)),
                    ),
                    "max_highway_hops": 1 if query.allow_highway_expansion else 0,
                    "max_pattern_hops": 1 if query.allow_pattern_expansion else 0,
                },
                "search_radius": probe["search_radius"],
                "visited_node_ids": [],
                "visited_bucket_keys": [],
                "evidence_node_ids": [],
                "stop_reason": None,
            }
        )

    branch_map = {branch["branch_id"]: branch for branch in branches}
    stop_reason = "budget_exhausted"
    max_rounds = min(query.max_total_steps, max(branch["budget"]["max_steps"] for branch in branches) if branches else query.max_total_steps)

    for round_index in range(1, max_rounds + 1):
        round_progress = False
        for branch in branches:
            if branch["status"] != "active":
                continue
            goal = branch["goal"]
            if goal in shared_topics and float(shared_topics[goal]["confidence"]) >= float(branch["success_criteria"]["min_confidence"]):
                branch["status"] = "satisfied"
                branch["stop_reason"] = "goal_satisfied_by_shared_context"
                continue
            probe = next((item for item in probes if item["probe_id"] == branch["probe_ids"][0]), None)
            if not probe:
                branch["status"] = "stopped"
                branch["stop_reason"] = "missing_probe"
                continue

            current_position = dict(probe["base_position"])
            if branch["visited_node_ids"]:
                last_node_id = branch["visited_node_ids"][-1]
                current_position = dict((index_payload.get("node_position_map") or {}).get(last_node_id) or current_position)

            candidates, nearby_bundle = gather_nearby_bundle(
                current_position,
                index_payload,
                radius=float(branch["search_radius"]),
                max_candidate_reads=int(branch["budget"]["max_candidate_reads"]),
                max_nodes_fulltext=int(branch["budget"]["max_fulltexts"]),
                max_text_chars=int(branch["budget"]["max_text_chars"]),
            )
            debug = {
                "candidate_ids": [candidate["id"] for candidate in candidates],
                "candidate_sources": {candidate["id"]: ["nearby_radius"] for candidate in candidates},
                "bucket_key": nearby_bundle["center_bucket_key"],
                "document_anchor_candidate_ids": [node["node_id"] for node in nearby_bundle["nearby_nodes"] if node["document_anchor"]],
                "highway_expansion_ids": [],
            }
            candidate_map = {candidate["id"]: candidate for candidate in candidates}
            if query.allow_adjacent_bucket_expansion:
                for bucket in atlas_shortlists[probe["probe_id"]][:2]:
                    for node_id in (index_payload.get("bucket_index") or {}).get(bucket["bucket_key"], []):
                        candidate_map.setdefault(node_id, (index_payload.get("spatial_index") or {}).get(node_id))
            ranked = []
            for candidate in [candidate for candidate in candidate_map.values() if candidate]:
                sources = list((debug.get("candidate_sources") or {}).get(candidate["id"], []))
                ranked.append(rank_candidate(probe, candidate, sources, identity_context=identity_context))
            ranked.sort(key=lambda item: (-item["raw_score"], item["node_id"]))
            top_matches = ranked[: query.max_matches]
            satisfaction = compute_satisfaction(top_matches)
            branch["visited_bucket_keys"].append(nearby_bundle["center_bucket_key"])
            visited_bucket_keys.add(nearby_bundle["center_bucket_key"])
            for match in top_matches:
                match = {**dict(match), "goal": goal, "answer_slot": _goal_to_slot(goal)}
                round_progress = True
                visited_node_ids.add(match["node_id"])
                branch["visited_node_ids"].append(match["node_id"])
                branch["evidence_node_ids"].append(match["node_id"])
                existing = aggregated.get(match["node_id"])
                if existing is None or float(match["score"]) > float(existing["score"]):
                    aggregated[match["node_id"]] = match
            branch["visited_node_ids"] = list(dict.fromkeys(branch["visited_node_ids"]))
            branch["evidence_node_ids"] = list(dict.fromkeys(branch["evidence_node_ids"]))
            branch["visited_bucket_keys"] = list(dict.fromkeys(branch["visited_bucket_keys"]))
            if top_matches:
                shared_topics[goal] = {
                    "topic": goal,
                    "node_ids": [match["node_id"] for match in top_matches[:3]],
                    "confidence": max(float(top_matches[0]["raw_score"]), float(shared_topics.get(goal, {}).get("confidence") or 0.0)),
                }
            step_stop_reason = None
            if top_matches and float(top_matches[0]["raw_score"]) >= float(branch["success_criteria"]["min_confidence"]):
                branch["status"] = "satisfied"
                step_stop_reason = "branch_goal_satisfied"
                branch["stop_reason"] = step_stop_reason
            elif satisfaction >= stop_threshold:
                branch["status"] = "satisfied"
                step_stop_reason = "shared_stop_threshold_met"
                branch["stop_reason"] = step_stop_reason
            all_steps.append(
                {
                    "probe_id": probe["probe_id"],
                    "label": probe["label"],
                    "step_number": round_index,
                    "bucket_key": nearby_bundle["center_bucket_key"],
                    "target_bucket_keys": probe["target_bucket_keys"],
                    "candidate_ids": debug["candidate_ids"],
                    "visited_node_ids": sorted(visited_node_ids),
                    "visited_bucket_keys": sorted(visited_bucket_keys),
                    "followed_highway_targets": debug["highway_expansion_ids"],
                    "matches": top_matches[:6],
                    "satisfaction_score": satisfaction,
                    "stop_reason": step_stop_reason,
                }
            )

        if shared_topics and all(branch["status"] != "active" for branch in branches):
            stop_reason = "all_branch_goals_satisfied"
            break
        if not round_progress:
            stop_reason = "no_progress"
            break

        # merge branches that now cover the same goal or share most evidence
        for left in branches:
            if left["status"] != "active":
                continue
            for right in branches:
                if right["branch_id"] == left["branch_id"] or right["status"] != "active":
                    continue
                overlap = len(set(left["evidence_node_ids"]) & set(right["evidence_node_ids"]))
                if left["goal"] == right["goal"] or overlap >= 2:
                    right["status"] = "merged"
                    right["stop_reason"] = f"merged_into_{left['branch_id']}"

    matches = list(aggregated.values())
    matches.sort(key=lambda item: _contract_match_sort_key(query.query_text, item))
    query_class = _query_class(query.query_text)
    if query_class == "broad_summary":
        matches = _diversify_broad_summary_matches(matches, limit=query.max_matches)
    shared_evidence = {
        "covered_goals": sorted(shared_topics.keys()),
        "branch_status": {branch["branch_id"]: branch["status"] for branch in branches},
        "evidence_topics": list(shared_topics.values()),
        "shared_node_ids": sorted(visited_node_ids),
        "shared_bucket_keys": sorted(visited_bucket_keys),
        "confidence": max((float(topic["confidence"]) for topic in shared_topics.values()), default=0.0),
    }
    answer, context = generate_grounded_answer(query.query_text, matches[: query.max_matches], shared_evidence, query.response_mode)
    if stop_reason == "budget_exhausted" and all_steps:
        stop_reason = all_steps[-1].get("stop_reason") or stop_reason
    return {
        "query_text": query.query_text,
        "response_mode": query.response_mode,
        "decomposition_mode": decomposition_mode,
        "planner_mode": planner_mode,
        "probes": probes,
        "branches": branches,
        "shared_evidence": shared_evidence,
        "steps": all_steps,
        "matches": matches[: query.max_matches],
        "visited_node_ids": sorted(visited_node_ids),
        "visited_bucket_keys": sorted(visited_bucket_keys),
        "stop_reason": stop_reason if matches else "no_candidates",
        "answer": answer if query.response_mode in {"answer", "both"} else None,
        "context": context if query.response_mode in {"context", "both"} else None,
        "planner_runtime": {
            "planner_mode": planner_mode,
            "decomposition_mode": decomposition_mode,
            "branch_count": len(branches),
            "shared_confidence": float(shared_evidence.get("confidence") or 0.0),
        },
        "answerability_state": (answer or {}).get("answerability_state"),
    }


def _hydrate_top_matches(matches: list[dict[str, Any]], *, max_nodes_fulltext: int) -> list[dict[str, Any]]:
    hydrate_ids = [match["node_id"] for match in matches[:max_nodes_fulltext]]
    hydrated = {node["id"]: node for node in fetch_nodes_by_ids(hydrate_ids, include_raw_text=True)}
    enriched: list[dict[str, Any]] = []
    for match in matches:
        node = hydrated.get(match["node_id"], match["node"])
        enriched.append({**match, "node": node})
    return enriched


def _prepare_rerank_pool(matches: list[dict[str, Any]], *, hydrate_limit: int) -> list[dict[str, Any]]:
    pool_limit = min(len(matches), max(hydrate_limit * 4, 24))
    pool: list[dict[str, Any]] = list(matches[:pool_limit])
    seen_ids = {match["node_id"] for match in pool}
    for match in matches:
        sources = set(match.get("sources") or [])
        node = dict(match.get("node") or {})
        if (
            "goal_support" in sources
            or "identity_core" in sources
            or "exact_temporal" in sources
            or bool(node.get("is_document_anchor"))
        ) and match["node_id"] not in seen_ids:
            pool.append(match)
            seen_ids.add(match["node_id"])
        if len(pool) >= pool_limit + 12:
            break
    return pool


def _summary_section_key(match: dict[str, Any]) -> str:
    node = dict(match.get("node") or {})
    provenance = dict(node.get("provenance") or {})
    guide_area = str(
        node.get("guide_area")
        or node.get("guide_conceptual_area")
        or provenance.get("guide_area")
        or provenance.get("guide_conceptual_area")
        or ""
    )
    memory_type = str(node.get("memory_type") or "")
    if guide_area in {"Relationships"} or memory_type in {"relational", "relation", "relationship"}:
        return "relationships"
    if guide_area in {"Projects", "Operational"} or memory_type in {"project", "knowledge"}:
        return "work"
    if guide_area in {"Expression"} or memory_type == "identity_style":
        return "style"
    if guide_area in {"Values"} or memory_type == "value":
        return "values"
    if guide_area in {"History", "Media Signals"} or memory_type in {"episodic", "document_anchor"}:
        return "history"
    return "identity"


def _diversify_broad_summary_matches(matches: list[dict[str, Any]], *, limit: int) -> list[dict[str, Any]]:
    preferred_sections = ("identity", "work", "relationships", "style", "values", "history")
    by_section: dict[str, list[dict[str, Any]]] = {section: [] for section in preferred_sections}
    for match in matches:
        by_section.setdefault(_summary_section_key(match), []).append(match)
    diversified: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    for section in preferred_sections:
        for match in by_section.get(section, []):
            node_id = str(match.get("node_id") or "")
            if not node_id or node_id in seen_ids:
                continue
            diversified.append(match)
            seen_ids.add(node_id)
            break
    for match in matches:
        node_id = str(match.get("node_id") or "")
        if not node_id or node_id in seen_ids:
            continue
        diversified.append(match)
        seen_ids.add(node_id)
        if len(diversified) >= max(limit, len(preferred_sections)):
            break
    return diversified[: max(limit, len(preferred_sections))]


def _apply_probe_shortlists(
    probes: list[dict[str, Any]],
    query: RetrieveRequest,
    atlas_payload: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    atlas_shortlists = {
        probe["probe_id"]: shortlist_atlas_buckets(atlas_payload, probe.get("landing_position") or probe["base_position"])
        for probe in probes
    }
    for probe in probes:
        shortlist = list(atlas_shortlists[probe["probe_id"]])
        probe["target_bucket_keys"] = [bucket["bucket_key"] for bucket in shortlist]
        probe["destination_queue"] = _normalize_destination_queue(
            spec_destinations=list(probe.get("destination_queue") or []),
            goal=str(probe.get("goal") or ""),
            probe_label=str(probe.get("label") or probe.get("probe_id") or "landing"),
            fallback_guide_area=str(probe.get("expected_guide_area") or ""),
            fallback_memory_type=str(probe.get("expected_memory_type") or ""),
            fallback_radial_expectation=str(probe.get("radial_expectation") or "mid"),
            fallback_color_hex=str(((probe.get("semantic_color") or {}).get("hex")) or ""),
            fallback_bucket_keys=list(probe.get("target_bucket_keys") or []),
        )
        probe["destination_queue"] = reorder_destination_queue(
            list(probe.get("destination_queue") or []),
            dict(probe.get("calibration_destination_weights") or {}),
        )
        primary_bucket = shortlist[0] if shortlist else None
        crowding_penalty = 0.0
        if primary_bucket:
            region_summary = fetch_region_summary(str(primary_bucket.get("bucket_key") or ""))
            region_density = int(((region_summary or {}).get("density") or {}).get("node_count") or primary_bucket.get("node_count") or 0)
            crowding_penalty_factor = max(0.7, min(1.35, float(probe.get("crowding_penalty_factor") or 1.0)))
            crowding_penalty = min(0.35, (region_density / 80.0) * crowding_penalty_factor)
            if crowding_penalty > 0.0:
                probe["search_radius"] = max(0.14, float(probe.get("search_radius") or 0.24) - crowding_penalty * 0.06)
        probe["crowding_penalty"] = round(crowding_penalty, 4)
    return atlas_shortlists


def _planner_family_for_probe(probe: dict[str, Any]) -> str:
    family = str(probe.get("planner_family") or "").strip().lower()
    if family in {"heuristic", "ai"}:
        return family
    landing_basis = str(probe.get("landing_basis") or "").strip().lower()
    if landing_basis.startswith("llm"):
        return "ai"
    return "heuristic"


def _family_plan_id_for_family(planner_family: str) -> str:
    return "ai_family_plan" if str(planner_family or "").strip().lower() == "ai" else "heuristic_family_plan"


def _planner_merge_window_seconds(*, retrieval_mode: str) -> float:
    mode = str(retrieval_mode or "balanced")
    if mode == "flash":
        return 1.0
    if mode == "heavy":
        return 4.5
    if mode == "forensic":
        return 6.0
    return 2.5


def _semantic_contract_timeout_seconds(retrieval_mode: str) -> float:
    mode = str(retrieval_mode or "balanced").strip().lower()
    if mode == "flash":
        return 9.0
    if mode == "heavy":
        return 18.0
    if mode == "forensic":
        return 24.0
    return 14.0


def _semantic_contract_final_wait_seconds(retrieval_mode: str, query_text: str | None = None) -> float:
    mode = str(retrieval_mode or "balanced").strip().lower()
    query_class = _query_class(query_text or "")
    if mode == "flash":
        return 2.5
    if mode == "forensic":
        return 12.0
    if mode == "heavy":
        return 9.0
    if query_class == "broad_summary":
        return 7.0
    return 5.0


def _semantic_contract_final_join_wait_seconds(
    retrieval_mode: str,
    query_text: str | None = None,
    *,
    compiler_started_at: float | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    semantic_timeout_seconds = _semantic_contract_timeout_seconds(retrieval_mode)
    policy_wait_seconds = _semantic_contract_final_wait_seconds(retrieval_mode, query_text)
    elapsed_before_final_wait = (
        max(0.0, float(now if now is not None else time.perf_counter()) - compiler_started_at)
        if compiler_started_at is not None
        else 0.0
    )
    remaining_budget_seconds = max(
        0.25,
        semantic_timeout_seconds - elapsed_before_final_wait + 0.75,
    )
    wait_seconds = max(policy_wait_seconds, remaining_budget_seconds)
    return {
        "wait_seconds": wait_seconds,
        "policy_wait_seconds": policy_wait_seconds,
        "semantic_timeout_seconds": semantic_timeout_seconds,
        "semantic_elapsed_before_final_wait_seconds": round(elapsed_before_final_wait, 3),
        "wait_basis": "semantic_compiler_timeout_budget",
    }


def _semantic_contract_is_ai_material(runtime: dict[str, Any] | None) -> bool:
    payload = dict(runtime or {})
    source = str(payload.get("source") or "").strip()
    return bool(payload.get("material")) and source in {"llm", "semantic_contract_cache"}


def _semantic_contract_runtime_rank(runtime: dict[str, Any] | None) -> int:
    payload = dict(runtime or {})
    if _semantic_contract_is_ai_material(payload):
        source = str(payload.get("source") or "").strip()
        if source == "llm":
            return 50
        if source == "semantic_contract_cache":
            return 45
        return 40
    status = str(payload.get("status") or "").strip()
    if status in {"completed", "cache_hit"} and bool(payload.get("material")):
        return 30
    if status in {"deferred", "pending"}:
        return 10
    if payload:
        return 5
    return 0


def _ai_spatial_contract_is_materialized(contract: dict[str, Any] | None) -> bool:
    payload = dict(contract or {})
    return bool(
        payload.get("materialized")
        and payload.get("certifiable")
        and [item for item in list(payload.get("inverse_answer_paths") or []) if isinstance(item, dict)]
    )


def _ai_spatial_contract_runtime(contract: dict[str, Any] | None) -> dict[str, Any]:
    payload = dict(contract or {})
    return {
        "schema_version": "agvm.ai_spatial_landing_contract_runtime.v1",
        "status": str(payload.get("status") or ""),
        "source": str(payload.get("source") or ""),
        "materialized": bool(payload.get("materialized")),
        "certifiable": bool(payload.get("certifiable")),
        "planner_latency_ms": payload.get("planner_latency_ms"),
        "missing_reasons": list(payload.get("missing_reasons") or []),
        "metrics": dict(payload.get("metrics") or {}),
        "cache": dict(payload.get("cache") or {}),
        "metamemory_spatial_revision": payload.get("metamemory_spatial_revision"),
        "brain_revision": payload.get("brain_revision"),
    }


def _ai_spatial_contract_rank(contract: dict[str, Any] | None) -> int:
    payload = dict(contract or {})
    if _ai_spatial_contract_is_materialized(payload):
        source = str(payload.get("source") or "").strip()
        if source in {"fresh_llm", "cached_llm", "ai_spatial_contract_cache"}:
            return 50
        return 45
    status = str(payload.get("status") or "").strip()
    if status in {"materialized", "ready"}:
        return 35
    if status in {"deferred", "pending", "blocked", "error"}:
        return 10
    if payload:
        return 5
    return 0


def _event_payload_surfaces(event: dict[str, Any]) -> list[dict[str, Any]]:
    payload = dict(dict(event or {}).get("payload") or {})
    surfaces: list[dict[str, Any]] = []
    if payload:
        surfaces.append(payload)
    result = dict(payload.get("result") or {})
    if result:
        surfaces.append(result)
    planner_runtime = dict(payload.get("planner_runtime") or result.get("planner_runtime") or {})
    if planner_runtime:
        surfaces.append(planner_runtime)
    return surfaces


def _latest_materialized_semantic_surface_from_events(search_id: str | None) -> tuple[dict[str, Any], dict[str, Any]]:
    resolved_search_id = str(search_id or "").strip()
    if not resolved_search_id:
        return {}, {}
    try:
        events = fetch_search_events(resolved_search_id, limit=220, busy_timeout_ms=80)
    except Exception:  # noqa: BLE001
        return {}, {}
    best_contract: dict[str, Any] = {}
    best_runtime: dict[str, Any] = {}
    best_rank = 0
    for event in reversed(list(events or [])):
        for surface in _event_payload_surfaces(dict(event or {})):
            runtime = dict(surface.get("semantic_contract_runtime") or {})
            rank = _semantic_contract_runtime_rank(runtime)
            if rank <= best_rank:
                continue
            contract = dict(surface.get("semantic_contract") or {})
            best_contract = contract
            best_runtime = runtime
            best_rank = rank
            if rank >= 50:
                return best_contract, best_runtime
    if best_rank >= 30:
        return best_contract, best_runtime
    return {}, {}


def _latest_materialized_ai_spatial_surface_from_events(search_id: str | None) -> tuple[dict[str, Any], dict[str, Any]]:
    resolved_search_id = str(search_id or "").strip()
    if not resolved_search_id:
        return {}, {}
    try:
        events = fetch_search_events(resolved_search_id, limit=260, busy_timeout_ms=80)
    except Exception:  # noqa: BLE001
        return {}, {}
    best_contract: dict[str, Any] = {}
    best_runtime: dict[str, Any] = {}
    best_rank = 0
    for event in reversed(list(events or [])):
        for surface in _event_payload_surfaces(dict(event or {})):
            planner_runtime = dict(surface.get("planner_runtime") or {})
            contract = dict(surface.get("ai_spatial_landing_contract") or planner_runtime.get("ai_spatial_landing_contract") or {})
            rank = _ai_spatial_contract_rank(contract)
            if rank <= best_rank:
                continue
            runtime = dict(
                surface.get("ai_spatial_landing_contract_runtime")
                or planner_runtime.get("ai_spatial_landing_contract_runtime")
                or _ai_spatial_contract_runtime(contract)
            )
            best_contract = contract
            best_runtime = runtime
            best_rank = rank
            if rank >= 50:
                return best_contract, best_runtime
    if best_rank >= 35:
        return best_contract, best_runtime
    return {}, {}


def _semantic_contract_brain_revision(query: RetrieveRequest, atlas_payload: dict[str, Any] | None) -> str:
    brain_id = str(getattr(query, "brain_id", None) or current_brain_id() or "legacy_global").strip() or "legacy_global"
    atlas = dict(atlas_payload or {})
    buckets = list(atlas.get("buckets") or [])
    nodes = list(atlas.get("nodes") or atlas.get("items") or [])
    declared_bucket_count = int(atlas.get("bucket_count") or len(buckets) or 0)
    declared_node_count = int(atlas.get("node_count") or len(nodes) or 0)
    payload = {
        "schema_version": "agvm.semantic_brain_revision.v2",
        "brain_id": brain_id,
        "atlas_version": atlas.get("schema_version") or atlas.get("version") or atlas.get("atlas_version"),
        "memory_revision": atlas.get("memory_revision")
        or atlas.get("graph_revision")
        or atlas.get("revision")
        or atlas.get("updated_revision"),
        "bucket_count": declared_bucket_count,
        "node_count": declared_node_count,
    }
    digest = hashlib.sha1(json.dumps(payload, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:16]
    return f"{brain_id}:{digest}"


def _fast_model_profile(
    *,
    retrieval_mode: str,
    query_text: str,
    response_mode: str,
    semantic_contract_runtime: dict[str, Any] | None,
    planner_seed_runtime: dict[str, Any] | None,
    first_answer_sla_split: bool | None = None,
) -> dict[str, Any]:
    semantic_runtime = dict(semantic_contract_runtime or {})
    planner_seed = dict(planner_seed_runtime or {})
    mode = str(retrieval_mode or "balanced").strip().lower()
    query_class = _query_class(query_text or "")
    return {
        "schema_version": "agvm.fast_model_profile.v1",
        "retrieval_mode": mode,
        "query_class": query_class,
        "compiler": {
            "model": compiler_model(),
            "timeout_seconds": _semantic_contract_timeout_seconds(mode),
            "final_wait_seconds": _semantic_contract_final_wait_seconds(mode, query_text),
            "cache_status": semantic_runtime.get("cache_status"),
            "cache_hit": bool(semantic_runtime.get("cache_hit")),
            "source": semantic_runtime.get("source"),
            "material": bool(semantic_runtime.get("material")),
        },
        "retrieval": {
            "model": retrieval_model(),
            "planner_seed_status": planner_seed.get("planner_seed_status"),
            "planner_seed_deferred": bool(planner_seed.get("planner_seed_deferred")),
            "first_answer_sla_split": bool(first_answer_sla_split if first_answer_sla_split is not None else planner_seed.get("first_answer_sla_split")),
        },
        "judge": {
            "model": retrieval_model(),
            "role": "retrieval",
        },
        "answer": {
            "model": answer_model(),
            "requested": str(response_mode or "both") in {"answer", "both"},
        },
    }


def _first_answer_sla_split_enabled(runtime_plan: dict[str, Any]) -> bool:
    planner_seed_runtime = dict(runtime_plan.get("planner_seed_runtime") or {})
    planner_runtime = dict(runtime_plan.get("planner_runtime") or {})
    return bool(
        planner_seed_runtime.get("first_answer_sla_split")
        or planner_seed_runtime.get("critical_path_planner_seed_deferred")
        or planner_runtime.get("first_answer_sla_split")
        or planner_runtime.get("critical_path_planner_seed_deferred")
    )


def _initial_llm_scout_wait_seconds(*, planner_merge_window_seconds: float, runtime_plan: dict[str, Any]) -> float:
    if _first_answer_sla_split_enabled(runtime_plan):
        return 0.0
    return max(0.0, float(planner_merge_window_seconds or 0.0))


def _final_llm_scout_wait_seconds(*, retrieval_mode: str, first_answer_sla_split: bool) -> float:
    if not first_answer_sla_split:
        return 0.0
    mode = str(retrieval_mode or "balanced")
    if mode == "flash":
        return 0.75
    if mode == "heavy":
        return 10.0
    if mode == "forensic":
        return 14.0
    return 6.0


def _first_answer_sla_ms(*, retrieval_mode: str) -> int:
    mode = str(retrieval_mode or "balanced").strip().lower()
    if mode == "flash":
        return 1200
    if mode == "heavy":
        return 4500
    if mode == "forensic":
        return 7000
    return 2500


def _final_surface_sla_seconds(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str,
    first_answer_sla_split: bool,
) -> float:
    if not first_answer_sla_split:
        return 0.0
    mode = str(retrieval_mode or "balanced").strip().lower()
    if mode == "flash":
        return 0.35
    if mode == "balanced":
        return 1.25 if query_class in {"direct_fact", "relation_fact", "style_values"} else 2.0
    if mode == "heavy":
        return 3.0 if query_contract_requires_expansion(query_text, retrieval_mode=mode) else 2.25
    if mode == "forensic":
        return 4.5
    return 2.0


def _final_scout_join_wait_seconds(
    *,
    final_scout_wait_seconds: float,
    final_surface_sla_seconds: float,
    first_answer_sla_split: bool,
    first_answer_ready: bool,
) -> float:
    wait_budget = max(0.0, float(final_scout_wait_seconds or 0.0))
    if not first_answer_sla_split or not first_answer_ready:
        return wait_budget
    surface_cap = max(0.0, float(final_surface_sla_seconds or 0.0))
    return min(wait_budget, surface_cap)


def _should_preserve_short_final_answer(
    *,
    query_text: str,
    answer_short: str | None,
    answerability_state: str,
    query_class: str,
    retrieval_mode: str,
    document_mode: str,
    document_packets: list[dict[str, Any]] | None,
) -> bool:
    if not str(answer_short or "").strip() or answerability_state != "grounded":
        return False
    if document_mode != "none" or list(document_packets or []):
        return False
    if query_class not in {"direct_fact", "relation_fact"}:
        return False
    if retrieval_mode not in {"flash", "balanced"}:
        return False
    if _is_temporal_reference_query(query_text):
        return False
    query_contract = build_query_contract(query_text, retrieval_mode=retrieval_mode)
    if str(query_contract.get("answer_style") or "") != "exact":
        return False
    if bool(query_contract.get("requires_expansion")):
        return False
    return bool(query_contract.get("fast_final_allowed"))


def _material_scout_wait_seconds(
    *,
    query_text: str,
    retrieval_mode: str,
    first_answer_sla_split: bool,
    base_wait_seconds: float,
) -> float:
    if not first_answer_sla_split:
        return 0.0
    base_wait = max(0.0, float(base_wait_seconds or 0.0))
    mode = str(retrieval_mode or "balanced").strip().lower()
    if not query_contract_requires_expansion(query_text, retrieval_mode=mode):
        return base_wait
    planner_budget = (
        _planner_seed_timeout_seconds(mode, query_text)
        + _planner_seed_transport_guard_seconds()
        + 0.25
    )
    if mode == "flash":
        return max(base_wait, min(planner_budget, 3.5))
    if mode == "balanced":
        return max(base_wait, min(planner_budget, 8.75))
    return max(base_wait, planner_budget)


def _allow_ai_navigation_worker_on_round(
    *,
    query_text: str,
    retrieval_mode: str,
    query_class: str,
    round_index: int,
    goal: str,
    first_answer_sla_split: bool,
    answer_first_ms: float | None,
) -> bool:
    if first_answer_sla_split and answer_first_ms is None:
        return False
    if (
        first_answer_sla_split
        and answer_first_ms is not None
        and retrieval_mode in {"flash", "balanced"}
        and query_class in {"direct_fact", "relation_fact", "style_values"}
        and not query_contract_requires_expansion(query_text, retrieval_mode=retrieval_mode)
    ):
        return False
    return _should_use_ai_navigation_worker(
        retrieval_mode=retrieval_mode,
        query_class=query_class,
        round_index=round_index,
        goal=goal,
    )


def _annotate_probe_family(
    probe: dict[str, Any],
    *,
    planner_family: str,
    family_plan_id: str | None = None,
    family_plan_confidence: float | None = None,
) -> dict[str, Any]:
    normalized_family = "ai" if str(planner_family or "").strip().lower() == "ai" else "heuristic"
    updated = dict(probe)
    updated["planner_family"] = normalized_family
    updated["family_plan_id"] = str(family_plan_id or _family_plan_id_for_family(normalized_family))
    confidence = family_plan_confidence
    if confidence is None:
        confidence = updated.get("branch_priority")
    if confidence is None:
        confidence = updated.get("weight")
    updated["family_plan_confidence"] = round(max(0.0, min(1.0, float(confidence or 0.0))), 4)
    updated["family_destination_queue"] = [dict(item) for item in list(updated.get("destination_queue") or [])]
    updated["family_branch_id"] = str(updated.get("family_branch_id") or f"{normalized_family}::{updated.get('probe_id') or 'probe'}")
    landing_basis = str(updated.get("landing_basis") or "").strip()
    if normalized_family == "ai" and not landing_basis.startswith("llm"):
        updated["landing_basis"] = f"llm::{landing_basis or 'canonical_planner'}"
    if normalized_family == "heuristic" and not landing_basis:
        updated["landing_basis"] = "inverse_like_estimation"
    destination_queue = [dict(item) for item in list(updated.get("destination_queue") or [])]
    updated["family_destination_queue"] = [dict(item) for item in destination_queue]
    updated["origin_families"] = sorted(
        {
            str(item).strip().lower()
            for item in list(updated.get("origin_families") or [normalized_family])
            if str(item).strip().lower() in {"heuristic", "ai"}
        }
        or {normalized_family}
    )
    updated["dual_origin"] = len(updated["origin_families"]) > 1
    source_probe_ids_by_family = {
        str(key).strip().lower(): str(value).strip()
        for key, value in dict(updated.get("source_probe_ids_by_family") or {}).items()
        if str(key).strip().lower() in {"heuristic", "ai"} and str(value).strip()
    }
    if str(updated.get("probe_id") or "").strip():
        source_probe_ids_by_family.setdefault(normalized_family, str(updated.get("probe_id") or "").strip())
    updated["source_probe_ids_by_family"] = source_probe_ids_by_family
    semantic_destination_queue = [dict(item) for item in list(updated.get("semantic_destination_queue") or destination_queue)]
    updated["semantic_destination_queue"] = semantic_destination_queue
    origin_destination_queues = {
        str(key).strip().lower(): [dict(item) for item in list(value or [])]
        for key, value in dict(updated.get("origin_destination_queues") or {}).items()
        if str(key).strip().lower() in {"heuristic", "ai"}
    }
    origin_destination_queues.setdefault(normalized_family, [dict(item) for item in semantic_destination_queue])
    updated["origin_destination_queues"] = origin_destination_queues
    updated["merge_outcome"] = updated.get("merge_outcome")
    updated["merge_score"] = updated.get("merge_score")
    updated["merge_reasons"] = [str(item).strip() for item in list(updated.get("merge_reasons") or []) if str(item).strip()][:10]
    updated["ai_refinement_delta"] = dict(updated.get("ai_refinement_delta") or {})
    return updated


def _families_for_record(record: dict[str, Any]) -> list[str]:
    normalized = sorted(
        {
            str(item).strip().lower()
            for item in list(record.get("origin_families") or [])
            if str(item).strip().lower() in {"heuristic", "ai"}
        }
    )
    if normalized:
        return normalized
    return [_planner_family_for_probe(record) if "probe_id" in record else (str(record.get("planner_family") or "").strip().lower() or "heuristic")]


def _record_has_family(record: dict[str, Any], family: str) -> bool:
    normalized_family = str(family or "").strip().lower()
    return normalized_family in _families_for_record(record)


def _destination_label_prefix(queue: list[dict[str, Any]], *, limit: int = 2) -> list[str]:
    labels: list[str] = []
    for item in list(queue or [])[:limit]:
        label = str(item.get("label") or "").strip().lower()
        if label:
            labels.append(label)
    return labels


def _destination_queue_prefix_similarity(left_queue: list[dict[str, Any]], right_queue: list[dict[str, Any]]) -> float:
    left_labels = _destination_label_prefix(left_queue)
    right_labels = _destination_label_prefix(right_queue)
    if left_labels and right_labels and left_labels == right_labels:
        return 1.0
    if set(left_labels) & set(right_labels):
        return 0.5
    return 0.0


def _radial_expectation_similarity(left: str | None, right: str | None) -> float:
    left_value = str(left or "").strip().lower()
    right_value = str(right or "").strip().lower()
    if left_value and right_value and left_value == right_value:
        return 1.0
    adjacency = {("core", "inner"), ("inner", "mid"), ("mid", "outer")}
    if (left_value, right_value) in adjacency or (right_value, left_value) in adjacency:
        return 0.5
    return 0.0


def _position_distance(left: dict[str, Any], right: dict[str, Any]) -> float | None:
    try:
        return float(
            distance(
                {
                    "x": float(left.get("x") or 0.0),
                    "y": float(left.get("y") or 0.0),
                    "z": float(left.get("z") or 0.0),
                },
                {
                    "x": float(right.get("x") or 0.0),
                    "y": float(right.get("y") or 0.0),
                    "z": float(right.get("z") or 0.0),
                },
            )
        )
    except Exception:
        return None


def _landing_neighborhood_similarity(left_probe: dict[str, Any], right_probe: dict[str, Any]) -> float:
    left_bucket_keys = {str(item).strip() for item in list(left_probe.get("target_bucket_keys") or []) if str(item).strip()}
    right_bucket_keys = {str(item).strip() for item in list(right_probe.get("target_bucket_keys") or []) if str(item).strip()}
    if left_bucket_keys and right_bucket_keys and left_bucket_keys & right_bucket_keys:
        return 1.0
    left_position = dict(left_probe.get("landing_position") or {})
    right_position = dict(right_probe.get("landing_position") or {})
    position_distance = _position_distance(left_position, right_position)
    if position_distance is None:
        return 0.0
    if position_distance <= 0.18:
        return 1.0
    if position_distance <= 0.32:
        return 0.5
    return 0.0


def _probe_merge_basis(ai_probe: dict[str, Any], heuristic_probe: dict[str, Any]) -> str | None:
    ai_strand_id = str(ai_probe.get("strand_id") or "").strip()
    heuristic_strand_id = str(heuristic_probe.get("strand_id") or "").strip()
    if ai_strand_id and heuristic_strand_id:
        return "strand_id" if ai_strand_id == heuristic_strand_id else None
    ai_field = str(ai_probe.get("expected_answer_field") or "").strip().lower()
    heuristic_field = str(heuristic_probe.get("expected_answer_field") or "").strip().lower()
    if ai_field and heuristic_field:
        return "answer_field" if ai_field == heuristic_field else None
    ai_goal = str(ai_probe.get("goal") or "").strip().lower()
    heuristic_goal = str(heuristic_probe.get("goal") or "").strip().lower()
    if ai_goal and heuristic_goal:
        return "goal" if ai_goal == heuristic_goal else None
    return None


def _probe_path_mission_id(probe: dict[str, Any]) -> str:
    direct = str(probe.get("path_mission_id") or probe.get("mission_id") or "").strip()
    if direct:
        return direct
    route_prior = dict(probe.get("route_preference_prior") or {})
    return str(route_prior.get("path_mission_id") or route_prior.get("mission_id") or "").strip()


def _probe_mission_goal_key(probe: dict[str, Any]) -> str:
    for key in ("expected_answer_field", "answer_field", "goal", "strand_id"):
        value = _fold_text(str(probe.get(key) or "")).strip()
        if value:
            return value
    return ""


def _mission_merge_score_bonus(
    ai_probe: dict[str, Any],
    heuristic_probe: dict[str, Any],
    *,
    basis: str | None,
    components: dict[str, float],
) -> tuple[float, list[str]]:
    """Small generic boost when a provisional heuristic branch overlaps an AI mission.

    This must stay category-free: the boost uses mission identity, answer-field/goal
    compatibility and local route overlap, not hand-written company/style/etc. rules.
    """
    reasons: list[str] = []
    bonus = 0.0
    if _probe_path_mission_id(ai_probe):
        reasons.append("ai_path_mission_present")
    if basis in {"strand_id", "answer_field"}:
        bonus += 0.08
        reasons.append(f"mission_basis_overlap:{basis}")
    elif basis == "goal":
        bonus += 0.05
        reasons.append("mission_basis_overlap:goal")
    if _probe_mission_goal_key(ai_probe) and _probe_mission_goal_key(ai_probe) == _probe_mission_goal_key(heuristic_probe):
        bonus += 0.03
        reasons.append("mission_goal_key_overlap")
    if float(components.get("landing_neighborhood_similarity") or 0.0) > 0.0:
        bonus += 0.02
        reasons.append("mission_landing_overlap")
    if float(components.get("destination_queue_prefix_similarity") or 0.0) > 0.0:
        bonus += 0.02
        reasons.append("mission_destination_overlap")
    return round(min(0.14, bonus), 6), list(dict.fromkeys(reasons))


def _mission_merge_learning_signal(
    *,
    ai_probe: dict[str, Any],
    outcome: str,
    reason: str,
    best_score: float,
    heuristic_probe: dict[str, Any] | None = None,
) -> dict[str, Any]:
    return {
        "schema_version": "agvm.mission_merge_learning_signal.v1",
        "signal_type": "ai_heuristic_merge_divergence",
        "outcome": str(outcome or "unknown"),
        "reason": str(reason or "unspecified"),
        "path_mission_id": _probe_path_mission_id(ai_probe) or None,
        "ai_probe_id": str(ai_probe.get("probe_id") or "").strip() or None,
        "heuristic_probe_id": str((heuristic_probe or {}).get("probe_id") or "").strip() or None,
        "ai_goal": str(ai_probe.get("goal") or "").strip() or None,
        "heuristic_goal": str((heuristic_probe or {}).get("goal") or "").strip() or None,
        "ai_goal_key": _probe_mission_goal_key(ai_probe) or None,
        "heuristic_goal_key": _probe_mission_goal_key(heuristic_probe or {}) or None,
        "best_merge_score": round(float(best_score or 0.0), 6),
        "learning_use": "feed_heuristic_calibration_sleep_evolve_after_review",
    }


def _probe_merge_similarity(ai_probe: dict[str, Any], heuristic_probe: dict[str, Any]) -> tuple[float, list[str], dict[str, float]]:
    components: dict[str, float] = {}
    reasons: list[str] = []
    goal_match = 1.0 if str(ai_probe.get("goal") or "").strip().lower() == str(heuristic_probe.get("goal") or "").strip().lower() and str(ai_probe.get("goal") or "").strip() else 0.0
    components["goal_match"] = goal_match
    if goal_match >= 1.0:
        reasons.append("goal_match")
    ai_area = str(ai_probe.get("expected_guide_area") or "").strip().lower()
    heuristic_area = str(heuristic_probe.get("expected_guide_area") or "").strip().lower()
    if ai_area and heuristic_area:
        components["expected_guide_area_match"] = 1.0 if ai_area == heuristic_area else 0.0
    else:
        components["expected_guide_area_match"] = 0.5
    if components["expected_guide_area_match"] > 0.0:
        reasons.append("guide_area_compatible")
    ai_memory_type = str(ai_probe.get("expected_memory_type") or "").strip().lower()
    heuristic_memory_type = str(heuristic_probe.get("expected_memory_type") or "").strip().lower()
    if ai_memory_type and heuristic_memory_type:
        components["expected_memory_type_match"] = 1.0 if ai_memory_type == heuristic_memory_type else 0.0
    else:
        components["expected_memory_type_match"] = 0.5
    if components["expected_memory_type_match"] > 0.0:
        reasons.append("memory_type_compatible")
    components["radial_expectation_match"] = _radial_expectation_similarity(
        str(ai_probe.get("radial_expectation") or ""),
        str(heuristic_probe.get("radial_expectation") or ""),
    )
    if components["radial_expectation_match"] > 0.0:
        reasons.append("radial_compatible")
    components["destination_queue_prefix_similarity"] = _destination_queue_prefix_similarity(
        list(ai_probe.get("destination_queue") or []),
        list(heuristic_probe.get("destination_queue") or []),
    )
    if components["destination_queue_prefix_similarity"] > 0.0:
        reasons.append("destination_prefix_overlap")
    components["landing_neighborhood_similarity"] = _landing_neighborhood_similarity(ai_probe, heuristic_probe)
    if components["landing_neighborhood_similarity"] > 0.0:
        reasons.append("landing_neighborhood_overlap")
    weighted_score = (
        components["goal_match"] * 0.25
        + components["expected_guide_area_match"] * 0.15
        + components["expected_memory_type_match"] * 0.15
        + components["radial_expectation_match"] * 0.10
        + components["destination_queue_prefix_similarity"] * 0.20
        + components["landing_neighborhood_similarity"] * 0.15
    )
    return round(max(0.0, min(1.0, weighted_score)), 6), reasons, components


def _merge_semantic_destination_queue(
    heuristic_queue: list[dict[str, Any]],
    ai_queue: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    merged = [dict(item) for item in list(heuristic_queue or [])]
    existing_keys = {
        (
            str(item.get("label") or "").strip().lower(),
            str(item.get("guide_area") or "").strip().lower(),
            str(item.get("memory_type") or "").strip().lower(),
            str(item.get("radial_expectation") or "").strip().lower(),
        )
        for item in merged
    }
    appended: list[dict[str, Any]] = []
    for item in list(ai_queue or []):
        normalized = dict(item)
        key = (
            str(normalized.get("label") or "").strip().lower(),
            str(normalized.get("guide_area") or "").strip().lower(),
            str(normalized.get("memory_type") or "").strip().lower(),
            str(normalized.get("radial_expectation") or "").strip().lower(),
        )
        if key in existing_keys:
            continue
        merged.append(normalized)
        appended.append(normalized)
        existing_keys.add(key)
    return merged, appended


def _ai_refinement_delta(
    heuristic_probe: dict[str, Any],
    ai_probe: dict[str, Any],
    *,
    components: dict[str, float],
) -> tuple[bool, dict[str, Any], list[str]]:
    delta: dict[str, Any] = {}
    reasons: list[str] = []
    heuristic_priority = float(heuristic_probe.get("branch_priority") or heuristic_probe.get("weight") or 0.0)
    ai_priority = float(ai_probe.get("branch_priority") or ai_probe.get("weight") or 0.0)
    if abs(ai_priority - heuristic_priority) > 0.12:
        delta["branch_priority"] = {
            "heuristic": round(heuristic_priority, 4),
            "ai": round(ai_priority, 4),
        }
        reasons.append("priority_shift")
    merged_semantic_queue, appended_destinations = _merge_semantic_destination_queue(
        list(heuristic_probe.get("destination_queue") or []),
        list(ai_probe.get("destination_queue") or []),
    )
    if appended_destinations:
        first_three_labels = {
            str(item.get("label") or "").strip().lower()
            for item in merged_semantic_queue[:3]
            if str(item.get("label") or "").strip()
        }
        appended_first_three = [
            dict(item)
            for item in appended_destinations
            if str(item.get("label") or "").strip().lower() in first_three_labels
        ]
        if appended_first_three:
            delta["appended_destinations"] = appended_first_three
            reasons.append("new_destinations")
    heuristic_corroboration = {
        str(item).strip().lower()
        for item in list(heuristic_probe.get("corroboration_needs") or [])
        if str(item).strip()
    }
    ai_corroboration = [
        str(item).strip()
        for item in list(ai_probe.get("corroboration_needs") or [])
        if str(item).strip() and str(item).strip().lower() not in heuristic_corroboration
    ]
    if ai_corroboration:
        delta["corroboration_needs"] = ai_corroboration
        reasons.append("corroboration_delta")
    for key in ("expected_guide_area", "expected_memory_type", "radial_expectation", "expected_answer_field", "answer_hypothesis", "expected_stop_condition"):
        heuristic_value = str(heuristic_probe.get(key) or "").strip()
        ai_value = str(ai_probe.get(key) or "").strip()
        if ai_value and ai_value != heuristic_value:
            delta[key] = {"heuristic": heuristic_value or None, "ai": ai_value}
            if key in {"expected_guide_area", "expected_memory_type", "radial_expectation"}:
                reasons.append(key)
    if float(components.get("landing_neighborhood_similarity") or 0.0) < 1.0:
        delta["landing_neighborhood_similarity"] = round(float(components.get("landing_neighborhood_similarity") or 0.0), 4)
        reasons.append("landing_shift")
    delta["semantic_destination_queue"] = merged_semantic_queue
    return bool(reasons), delta, reasons


def _merge_runtime_summary(branches: list[dict[str, Any]]) -> dict[str, Any]:
    histogram = {"reuse_branch": 0, "enrich_branch": 0, "fork_new_branch": 0}
    merged_strand_ids: list[str] = []
    enriched_strand_ids: list[str] = []
    forked_strand_ids: list[str] = []
    dual_origin_branch_ids: list[str] = []
    for branch in list(branches or []):
        outcome = str(branch.get("merge_outcome") or "").strip()
        strand_id = str(branch.get("strand_id") or "").strip()
        if str(branch.get("dual_origin") or "").strip().lower() == "true" or bool(branch.get("dual_origin")):
            branch_id = str(branch.get("branch_id") or "").strip()
            if branch_id:
                dual_origin_branch_ids.append(branch_id)
        if outcome in histogram:
            histogram[outcome] += 1
            if strand_id:
                if outcome == "reuse_branch":
                    merged_strand_ids.append(strand_id)
                elif outcome == "enrich_branch":
                    enriched_strand_ids.append(strand_id)
                elif outcome == "fork_new_branch":
                    forked_strand_ids.append(strand_id)
    return {
        "branch_reuse_count": histogram["reuse_branch"],
        "branch_enrich_count": histogram["enrich_branch"],
        "branch_fork_count": histogram["fork_new_branch"],
        "dual_origin_branch_count": len(set(dual_origin_branch_ids)),
        "merge_resolution_histogram": histogram,
        "merged_strand_ids": sorted(set(merged_strand_ids)),
        "enriched_strand_ids": sorted(set(enriched_strand_ids)),
        "forked_strand_ids": sorted(set(forked_strand_ids)),
    }


def _route_richness_score_for_branch(branch: dict[str, Any]) -> float:
    route_trace = [dict(item) for item in list(branch.get("route_trace") or []) if isinstance(item, dict)]
    if not route_trace:
        return 0.0
    travel_count = sum(1 for entry in route_trace if bool(entry.get("travel_performed")))
    study_count = sum(1 for entry in route_trace if str(entry.get("move_type") or "") == "study")
    hydrate_count = sum(1 for entry in route_trace if str(entry.get("move_type") or "") == "hydrate")
    reorder_count = sum(1 for entry in route_trace if str(entry.get("move_type") or "") == "reorder")
    reached_count = sum(1 for entry in route_trace if bool(entry.get("destination_reached")) or str(entry.get("move_type") or "") == "destination_reached")
    yielded_total = sum(int(entry.get("yielded_match_count") or 0) for entry in route_trace)
    highway_steps = sum(1 for entry in route_trace if str(entry.get("edge_type") or "") == "highway" and bool(entry.get("travel_performed")))
    score = (
        min(1.0, travel_count / 4.0) * 0.34
        + min(1.0, (study_count + hydrate_count) / 4.0) * 0.16
        + min(1.0, yielded_total / 8.0) * 0.18
        + min(1.0, highway_steps / 2.0) * 0.12
        + min(1.0, reached_count / 2.0) * 0.12
        + min(1.0, reorder_count / 2.0) * 0.08
    )
    return round(max(0.0, min(1.0, score)), 4)


def _route_runtime_summary(branches: list[dict[str, Any]]) -> dict[str, Any]:
    branch_rows = [dict(branch) for branch in list(branches or []) if isinstance(branch, dict)]
    route_entries = [
        (dict(branch), dict(entry))
        for branch in branch_rows
        for entry in list(branch.get("route_trace") or [])
        if isinstance(entry, dict)
    ]
    total_entries = len(route_entries)
    family_step_counts = {"heuristic": 0, "ai": 0, "dual-origin": 0}
    highway_considered = 0
    highway_traversed = 0
    highway_not_used = 0
    highway_effective = 0
    link_traversed = 0
    link_effective = 0
    local_traversed = 0
    travel_step_count = 0
    studied_node_count = 0
    hydrated_node_count = 0
    reached_branch_ids: set[str] = set()
    execution_reorder_reasons: dict[str, int] = defaultdict(int)
    execution_reorder_count = 0
    for branch, entry in route_entries:
        family_attribution = str(entry.get("family_attribution") or _route_family_attribution(branch) or "heuristic")
        if family_attribution in family_step_counts:
            family_step_counts[family_attribution] += 1
        if bool(entry.get("destination_reached")) or str(entry.get("move_type") or "") == "destination_reached":
            reached_branch_ids.add(str(branch.get("branch_id") or id(branch)))
        if str(entry.get("move_type") or "") == "reorder":
            execution_reorder_count += 1
            reason = str(entry.get("reorder_reason") or "unspecified").strip() or "unspecified"
            execution_reorder_reasons[reason] += 1
        edge_type = str(entry.get("edge_type") or "")
        effective = bool(entry.get("destination_reached")) or int(entry.get("yielded_match_count") or 0) > 0 or bool(list(entry.get("studied_node_ids") or [])) or bool(list(entry.get("hydrated_node_ids") or []))
        if bool(entry.get("considered_highway")):
            highway_considered += 1
            if not (edge_type == "highway" and bool(entry.get("travel_performed"))):
                highway_not_used += 1
        studied_node_count += len(list(entry.get("studied_node_ids") or []))
        hydrated_node_count += len(list(entry.get("hydrated_node_ids") or []))
        if bool(entry.get("travel_performed")):
            travel_step_count += 1
        if edge_type == "highway" and bool(entry.get("travel_performed")):
            highway_traversed += 1
            if effective:
                highway_effective += 1
        if edge_type == "link" and bool(entry.get("travel_performed")):
            link_traversed += 1
            if effective:
                link_effective += 1
        if edge_type == "local" and bool(entry.get("travel_performed")):
            local_traversed += 1
    highway_considered = max(
        highway_considered,
        sum(int(branch.get("considered_highway_count") or 0) for branch in branch_rows),
    )
    highway_traversed = max(
        highway_traversed,
        sum(int(branch.get("highway_traversed_count") or branch.get("highway_hops_taken") or 0) for branch in branch_rows),
    )
    highway_not_used = max(0, highway_considered - highway_traversed, highway_not_used)
    link_traversed = max(
        link_traversed,
        sum(int(branch.get("link_traversed_count") or branch.get("link_hops_taken") or 0) for branch in branch_rows),
    )
    local_traversed = max(
        local_traversed,
        sum(int(branch.get("local_traversed_count") or branch.get("local_hops_taken") or 0) for branch in branch_rows),
    )
    travel_step_count = max(travel_step_count, highway_traversed + link_traversed + local_traversed)
    studied_node_count = max(
        studied_node_count,
        sum(int(branch.get("studied_node_count") or len(list(branch.get("studied_node_ids") or []))) for branch in branch_rows),
    )
    hydrated_node_count = max(
        hydrated_node_count,
        sum(int(branch.get("hydrated_node_count") or len(list(branch.get("hydrated_node_ids") or []))) for branch in branch_rows),
    )
    branch_scores = [_route_richness_score_for_branch(branch) for branch in branch_rows if dict(branch)]
    return {
        "route_step_count": total_entries,
        "travel_step_count": travel_step_count,
        "highway_considered_count": highway_considered,
        "highway_traversed_count": highway_traversed,
        "highway_not_used_count": highway_not_used,
        "link_traversed_count": link_traversed,
        "local_traversed_count": local_traversed,
        "studied_node_count": studied_node_count,
        "hydrated_node_count": hydrated_node_count,
        "route_richness_score": round(sum(branch_scores) / max(1, len(branch_scores)), 6) if branch_scores else 0.0,
        "heuristic_family_route_step_ratio": round(family_step_counts["heuristic"] / max(1, total_entries), 6),
        "ai_family_route_step_ratio": round(family_step_counts["ai"] / max(1, total_entries), 6),
        "dual_origin_family_route_step_ratio": round(family_step_counts["dual-origin"] / max(1, total_entries), 6),
        "highway_effective_use_ratio": round(highway_effective / max(1, highway_traversed), 6),
        "link_effective_use_ratio": round(link_effective / max(1, link_traversed), 6),
        "destination_reached_ratio": round(len(reached_branch_ids) / max(1, len(branch_rows)), 6) if branch_rows else 0.0,
        "execution_reorder_count": execution_reorder_count,
        "execution_reorder_reasons": dict(execution_reorder_reasons),
    }


def _route_truth_summary(
    *,
    branches: list[dict[str, Any]],
    route_runtime: dict[str, Any],
    direct_preflight_fast_path: bool = False,
    direct_preflight_route_fast_path_reason: str | None = None,
    document_lookup_fast_packet_found: bool = False,
    document_lookup_fast_no_match: bool = False,
    document_lookup_route_fast_path_reason: str | None = None,
    document_synthesis_fast_packet_found: bool = False,
    document_synthesis_route_fast_path_reason: str | None = None,
    warm_state_used: bool = False,
    warm_route_budget_override: int | None = None,
    warm_route_fast_path_reason: str | None = None,
    warm_route_validation_required: bool = False,
    llm_scout_state: dict[str, Any] | None = None,
    ai_material_contribution: bool = False,
    ai_contribution_reason: str | None = None,
) -> dict[str, Any]:
    branch_rows = [dict(branch) for branch in list(branches or []) if isinstance(branch, dict)]

    def branch_node_count(field: str) -> int:
        return len(
            {
                str(node_id).strip()
                for branch in branch_rows
                for node_id in list(branch.get(field) or [])
                if str(node_id).strip()
            }
        )

    route_step_count = int(route_runtime.get("route_step_count") or 0)
    travel_step_count = int(route_runtime.get("travel_step_count") or 0)
    direct_reason = str(direct_preflight_route_fast_path_reason or "").strip()
    document_reason = str(
        document_lookup_route_fast_path_reason
        or document_synthesis_route_fast_path_reason
        or ""
    ).strip()
    warm_reason = str(warm_route_fast_path_reason or "").strip()
    warm_pre_route = bool(warm_state_used and warm_route_budget_override == 0)
    document_pre_route = bool(
        document_lookup_fast_packet_found
        or document_lookup_fast_no_match
        or document_synthesis_fast_packet_found
    )
    travel_performed = travel_step_count > 0
    travel_required = not bool(direct_preflight_fast_path or document_pre_route or warm_pre_route)
    if direct_preflight_fast_path:
        execution_mode = "direct_preflight"
        truth_label = "closed from grounded preflight evidence"
        fast_path_reason = direct_reason or "direct_preflight_answer_sufficient"
    elif document_pre_route:
        execution_mode = "document_pre_route"
        truth_label = "closed from document packet truth before route travel"
        fast_path_reason = document_reason or "document_packet_closure"
    elif warm_pre_route:
        execution_mode = "warm_recall"
        truth_label = "closed from warm/hot context recall before route travel"
        fast_path_reason = warm_reason or "warm_context_sufficient"
    elif travel_performed:
        execution_mode = "route_travel"
        truth_label = "route travel executed"
        fast_path_reason = None
    elif route_step_count > 0:
        execution_mode = "route_trace_no_travel"
        truth_label = "backend emitted route trace without travel hops"
        fast_path_reason = None
    elif warm_state_used and warm_route_validation_required:
        execution_mode = "warm_validation_pending"
        truth_label = "warm context was reused but still required source validation"
        fast_path_reason = warm_reason or "warm_context_requires_validation"
    else:
        execution_mode = "planned_no_travel"
        truth_label = "no backend route travel emitted"
        fast_path_reason = None
    llm_state = dict(llm_scout_state or {})
    return {
        "route_step_count": route_step_count,
        "travel_step_count": travel_step_count,
        "highway_considered_count": int(route_runtime.get("highway_considered_count") or 0),
        "highway_traversed_count": int(route_runtime.get("highway_traversed_count") or 0),
        "highway_not_used_count": int(route_runtime.get("highway_not_used_count") or 0),
        "link_traversed_count": int(route_runtime.get("link_traversed_count") or 0),
        "local_traversed_count": int(route_runtime.get("local_traversed_count") or 0),
        "studied_node_count": int(route_runtime.get("studied_node_count") or 0),
        "hydrated_node_count": int(route_runtime.get("hydrated_node_count") or 0),
        "candidate_node_count": branch_node_count("candidate_node_ids"),
        "promoted_node_count": branch_node_count("evidence_node_ids"),
        "reservoir_only_node_count": branch_node_count("reservoir_only_node_ids"),
        "branch_count": len(branch_rows),
        "landed_branch_count": sum(
            1
            for branch in branch_rows
            if list(branch.get("route_trace") or [])
            or list(branch.get("studied_node_ids") or [])
            or list(branch.get("hydrated_node_ids") or [])
            or list(branch.get("evidence_node_ids") or [])
            or bool(branch.get("destination_reached"))
        ),
        "destination_reached_count": sum(
            1
            for branch in branch_rows
            if bool(branch.get("destination_reached"))
            or bool((branch.get("destination_progress") or {}).get("destination_reached"))
            or any(bool(entry.get("destination_reached")) for entry in list(branch.get("route_trace") or []) if isinstance(entry, dict))
        ),
        "destination_reached_ratio": float(route_runtime.get("destination_reached_ratio") or 0.0),
        "route_richness_score": float(route_runtime.get("route_richness_score") or 0.0),
        "execution_mode": execution_mode,
        "truth_label": truth_label,
        "fast_path_reason": fast_path_reason,
        "travel_required": travel_required,
        "travel_performed": travel_performed,
        "direct_preflight_fast_path": bool(direct_preflight_fast_path),
        "document_pre_route": document_pre_route,
        "warm_pre_route": warm_pre_route,
        "warm_route_validation_required": bool(warm_route_validation_required),
        "ai_scout_status": str(llm_state.get("status") or "") or None,
        "ai_completed_ms": llm_state.get("completed_ms"),
        "ai_probe_count": int(llm_state.get("llm_probe_count") or 0),
        "ai_added_probe_count": int(llm_state.get("added_probe_count") or 0),
        "ai_material_contribution": bool(ai_material_contribution),
        "ai_contribution_reason": ai_contribution_reason,
        "ai_spatial_snap_branch_count": sum(1 for branch in branch_rows if dict(branch.get("spatial_snap") or {})),
        "ai_spatial_snap_traveled_branch_count": sum(
            1
            for branch in branch_rows
            if dict(branch.get("spatial_snap") or {})
            and any(
                bool(event.get("travel_performed")) or str(event.get("move_type") or "") == "travel"
                for event in list(branch.get("route_trace") or [])
                if isinstance(event, dict)
            )
        ),
        "heuristic_provisional_branch_count": sum(1 for branch in branch_rows if bool(branch.get("heuristic_provisional"))),
    }


def _ledger_dict(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    if hasattr(value, "model_dump"):
        try:
            return dict(value.model_dump())
        except Exception:
            return {}
    return {}


def _ledger_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return list(value)
    if isinstance(value, tuple):
        return list(value)
    return []


def _ledger_id_list(*values: Any, limit: int = 32) -> list[str]:
    rows: list[str] = []
    for value in values:
        if isinstance(value, dict):
            for key in (
                "node_id",
                "source_node_id",
                "target_node_id",
                "from_node_id",
                "to_node_id",
                "document_anchor_node_id",
                "anchor_node_id",
            ):
                item = str(value.get(key) or "").strip()
                if item and item not in rows:
                    rows.append(item)
            for key in ("yielded_match_ids", "studied_node_ids", "hydrated_node_ids", "node_ids"):
                for item in _ledger_list(value.get(key)):
                    text = str(item or "").strip()
                    if text and text not in rows:
                        rows.append(text)
        elif isinstance(value, (list, tuple, set)):
            for item in list(value):
                if isinstance(item, dict):
                    for nested in _ledger_id_list(item, limit=limit):
                        if nested not in rows:
                            rows.append(nested)
                else:
                    text = str(item or "").strip()
                    if text and text not in rows:
                        rows.append(text)
        else:
            text = str(value or "").strip()
            if text and text not in rows:
                rows.append(text)
        if len(rows) >= limit:
            break
    return rows[:limit]


def _branch_path_mission_id(
    branch: dict[str, Any],
    *,
    mission_by_path_id: dict[str, dict[str, Any]] | None = None,
) -> str:
    direct = str(branch.get("path_mission_id") or branch.get("mission_id") or "").strip()
    if direct:
        return direct
    route_prior = _ledger_dict(branch.get("route_preference_prior"))
    prior = str(route_prior.get("path_mission_id") or route_prior.get("mission_id") or "").strip()
    if prior:
        return prior
    path_id = str(branch.get("ai_spatial_path_id") or branch.get("path_id") or "").strip()
    if path_id and mission_by_path_id and path_id in mission_by_path_id:
        return str(mission_by_path_id[path_id].get("mission_id") or "").strip()
    merge_state = _ledger_dict(branch.get("mission_merge_state"))
    return str(merge_state.get("path_mission_id") or merge_state.get("mission_id") or "").strip()


def _ledger_document_refs(*sources: Any, limit: int = 12) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_ref(payload: dict[str, Any], *, source: str | None = None) -> None:
        document_id = str(
            payload.get("document_id")
            or payload.get("doc_id")
            or payload.get("source_ref")
            or payload.get("source_id")
            or payload.get("id")
            or ""
        ).strip()
        title = _mission_text(
            payload.get("title")
            or payload.get("document_title")
            or payload.get("source_title")
            or payload.get("label")
            or "",
            limit=220,
        )
        anchor = str(payload.get("anchor_node_id") or payload.get("document_anchor_node_id") or payload.get("node_id") or "").strip()
        raw_availability = _ledger_dict(payload.get("raw_availability"))
        raw_available = bool(
            payload.get("raw_available")
            or payload.get("raw_text_available")
            or payload.get("raw_available_in_store")
            or raw_availability.get("raw_text_available")
            or str(raw_availability.get("state") or "") == "raw_available"
        )
        key = document_id or anchor or title
        if not key or key in seen:
            return
        seen.add(key)
        row = {
            "document_id": document_id or None,
            "title": title or None,
            "anchor_node_id": anchor or None,
            "raw_available": raw_available,
            "relationship_to_query": str(payload.get("relationship_to_query") or "").strip() or None,
            "document_evidence_rank": payload.get("document_evidence_rank"),
            "document_evidence_score": payload.get("document_evidence_score"),
            "why_included": list(payload.get("why_included") or [])[:10] if isinstance(payload.get("why_included"), list) else [],
            "expected_contents": _ledger_dict(payload.get("expected_contents")),
            "matched_claim_terms": _ledger_id_list(payload.get("matched_claim_terms"), limit=24),
            "missing_claim_terms": _ledger_id_list(payload.get("missing_claim_terms"), limit=24),
            "matched_entities": _ledger_id_list(payload.get("matched_entities"), limit=12),
            "score_components": _ledger_dict(payload.get("score_components") or payload.get("document_evidence_score_components")),
            "retrieve_document_call": _ledger_dict(payload.get("retrieve_document_call")),
            "source": source or str(payload.get("source") or "runtime_document_ref"),
        }
        rows.append({key: value for key, value in row.items() if value not in (None, [], {})})

    def visit(value: Any, *, source: str | None = None) -> None:
        if len(rows) >= limit:
            return
        if isinstance(value, dict):
            nested_source = source or str(value.get("source") or "").strip() or None
            if any(str(value.get(key) or "").strip() for key in ("document_id", "doc_id", "source_ref", "source_id", "id", "title", "document_title")):
                add_ref(value, source=nested_source)
            for key in ("document_refs", "documents", "supporting_documents", "document_packets", "source_trace"):
                if key in value:
                    visit(value.get(key), source=nested_source or key)
        elif isinstance(value, (list, tuple)):
            for item in list(value):
                visit(item, source=source)
                if len(rows) >= limit:
                    break
        elif str(value or "").strip():
            add_ref({"document_id": str(value).strip()}, source=source or "runtime_document_ref")

    for source in sources:
        visit(source)
        if len(rows) >= limit:
            break
    return rows[:limit]


def _ledger_route_events(route_trace: list[Any], *, limit: int = 16) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for index, raw in enumerate(route_trace[:limit], start=1):
        entry = _ledger_dict(raw)
        if not entry:
            continue
        events.append(
            {
                "index": index,
                "move_type": str(entry.get("move_type") or "").strip() or "study",
                "edge_type": str(entry.get("edge_type") or "").strip() or "none",
                "source_node_id": str(entry.get("source_node_id") or entry.get("from_node_id") or "").strip() or None,
                "target_node_id": str(entry.get("target_node_id") or entry.get("to_node_id") or "").strip() or None,
                "destination_id": str(entry.get("destination_id") or "").strip() or None,
                "destination_label": _mission_text(entry.get("destination_label") or "", limit=180) or None,
                "travel_performed": bool(entry.get("travel_performed")),
                "destination_reached": bool(entry.get("destination_reached")),
                "yielded_match_count": int(entry.get("yielded_match_count") or 0),
                "studied_node_ids": _ledger_id_list(entry.get("studied_node_ids"), limit=8),
                "hydrated_node_ids": _ledger_id_list(entry.get("hydrated_node_ids"), limit=8),
            }
        )
    return [{key: value for key, value in row.items() if value not in (None, [], {})} for row in events]


def _ledger_traversed_edges(branch: dict[str, Any], route_trace: list[Any], *, limit: int = 24) -> list[dict[str, Any]]:
    edges: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_edge(payload: dict[str, Any], *, source: str) -> None:
        from_id = str(payload.get("from_node_id") or payload.get("source_node_id") or payload.get("from") or "").strip()
        to_id = str(payload.get("to_node_id") or payload.get("target_node_id") or payload.get("to") or "").strip()
        edge_type = str(payload.get("edge_type") or payload.get("type") or "none").strip() or "none"
        if not (from_id or to_id):
            return
        key = f"{from_id}->{to_id}:{edge_type}:{source}"
        if key in seen:
            return
        seen.add(key)
        edges.append(
            {
                "from_node_id": from_id or None,
                "to_node_id": to_id or None,
                "edge_type": edge_type,
                "source": source,
                "travel_performed": bool(payload.get("travel_performed", True)),
            }
        )

    for edge in _ledger_list(branch.get("traversed_edges")):
        add_edge(_ledger_dict(edge), source="branch.traversed_edges")
        if len(edges) >= limit:
            return edges[:limit]
    for raw in route_trace:
        entry = _ledger_dict(raw)
        if not bool(entry.get("travel_performed")) and str(entry.get("move_type") or "") != "travel":
            continue
        add_edge(entry, source="route_trace")
        if len(edges) >= limit:
            break
    return edges[:limit]


def _mission_coverage_state(
    *,
    mission: dict[str, Any],
    branch: dict[str, Any] | None,
    hot_node_ids: list[str],
    cold_node_ids: list[str],
    hot_evidence_rows: list[dict[str, Any]] | None = None,
    cold_evidence_rows: list[dict[str, Any]] | None = None,
    duplicate_node_ids: list[str],
    excluded_node_ids: list[str],
    document_refs: list[dict[str, Any]],
    route_events: list[dict[str, Any]],
    visited_node_ids: list[str],
    provider_degraded: bool,
) -> tuple[str, str]:
    expected_shape = _ledger_dict(mission.get("expected_evidence_shape"))
    document_requested = bool(expected_shape.get("document_requested"))
    reached = bool((branch or {}).get("destination_reached")) or bool(_ledger_dict((branch or {}).get("destination_progress")).get("destination_reached"))
    reached = reached or any(bool(event.get("destination_reached")) for event in route_events)
    has_hot_evidence = bool(hot_node_ids or list(hot_evidence_rows or []))
    has_cold_evidence = bool(cold_node_ids or list(cold_evidence_rows or []))
    if has_hot_evidence or (document_requested and document_refs):
        return "resolved", "mission_evidence_shape_satisfied"
    if has_cold_evidence:
        return "partially_resolved", "cold_answer_material_found_not_promoted"
    if duplicate_node_ids and not (has_hot_evidence or has_cold_evidence or document_refs):
        return "duplicate_only", "only_duplicate_or_warm_material_found"
    if excluded_node_ids and not (has_hot_evidence or has_cold_evidence or document_refs):
        return "forbidden", "only_excluded_or_forbidden_material_found"
    if reached or route_events or visited_node_ids:
        return "near_miss", "route_executed_without_sufficient_mission_evidence"
    if provider_degraded:
        return "provider_degraded", "ai_or_semantic_provider_degraded_before_execution"
    return "missed", "mission_not_executed_or_no_route_material"


def _ledger_text_key(value: Any) -> str:
    text = _fold_text(str(value or "")).replace("_", " ")
    return re.sub(r"\s+", " ", text).strip()


def _ledger_mission_match_keys(mission: dict[str, Any], branch: dict[str, Any] | None = None) -> set[str]:
    expected_shape = _ledger_dict(mission.get("expected_evidence_shape"))
    branch = dict(branch or {})
    raw_values = [
        mission.get("mission_id"),
        mission.get("path_id"),
        mission.get("goal"),
        mission.get("answer_hypothesis"),
        expected_shape.get("target_id"),
        expected_shape.get("answer_field"),
        expected_shape.get("support_slot"),
        expected_shape.get("section_key"),
        branch.get("goal"),
        branch.get("answer_hypothesis"),
        branch.get("expected_answer_field"),
        branch.get("support_slot"),
        branch.get("section_key"),
    ]
    keys: set[str] = set()
    for value in raw_values:
        key = _ledger_text_key(value)
        if not key:
            continue
        keys.add(key)
        keys.add(_ledger_text_key(_goal_to_slot(key)))
        keys.add(_ledger_text_key(_canonical_required_slot(key)))
        for token in re.split(r"[^a-z0-9]+", key):
            if len(token) >= 3:
                keys.add(token)
                keys.add(_ledger_text_key(_goal_to_slot(token)))
                keys.add(_ledger_text_key(_canonical_required_slot(token)))
    slot_aliases = {
        "identity": {"identity", "name", "profile", "bio", "person", "subject"},
        "work": {"work", "role", "project", "projects", "company", "companies", "organization", "business"},
        "relationships": {"relationships", "relationship", "family", "father", "mother", "partner", "mentor", "sibling"},
        "history": {"history", "timeline", "date", "milestone", "career", "past"},
        "values": {"values", "principles", "beliefs", "mission"},
        "style": {"style", "tone", "voice", "communication"},
        "documents": {"documents", "document", "source", "sources", "raw", "file"},
    }
    canonical_slots = {
        key
        for key in list(keys)
        if key in slot_aliases
    }
    for slot in canonical_slots:
        keys.update(slot_aliases.get(slot, set()))
    keys.discard("")
    return keys


def _ledger_entry_match_keys(entry: dict[str, Any]) -> set[str]:
    raw_values: list[Any] = [
        entry.get("node_id"),
        entry.get("goal"),
        entry.get("section"),
        entry.get("section_key"),
        entry.get("support_slot"),
        entry.get("target_id"),
        entry.get("answer_field"),
        entry.get("memory_type"),
        entry.get("topic"),
        entry.get("document_role"),
    ]
    raw_values.extend(_ledger_list(entry.get("support_slots")))
    raw_values.extend(_ledger_list(entry.get("branch_goals")))
    raw_values.extend(_ledger_list(entry.get("mission_goals")))
    keys: set[str] = set()
    for value in raw_values:
        key = _ledger_text_key(value)
        if not key:
            continue
        keys.add(key)
        keys.add(_ledger_text_key(_goal_to_slot(key)))
        keys.add(_ledger_text_key(_canonical_required_slot(key)))
        for token in re.split(r"[^a-z0-9]+", key):
            if len(token) >= 3:
                keys.add(token)
                keys.add(_ledger_text_key(_goal_to_slot(token)))
                keys.add(_ledger_text_key(_canonical_required_slot(token)))
    keys.discard("")
    return keys


def _ledger_evidence_text(entry: dict[str, Any], *, limit: int = 700) -> str:
    explicit = (
        entry.get("text")
        or entry.get("evidence_snippet")
        or entry.get("agent_line")
        or entry.get("snippet")
    )
    if explicit:
        return _mission_text(explicit, limit=limit)

    summary = _mission_text(entry.get("summary") or "", limit=limit)
    raw_text = _mission_text(entry.get("raw_text") or "", limit=max(limit, 900))
    if raw_text and summary:
        summary_folded = _ledger_text_key(summary)
        raw_folded = _ledger_text_key(raw_text)
        summary_incomplete = bool("..." in summary or "\u2026" in summary)
        summary_incomplete = summary_incomplete or bool(len(summary) < 320 and len(raw_text) > len(summary) + 80)
        if summary_incomplete:
            if summary_folded and summary_folded not in raw_folded:
                return _mission_text(f"{summary}. {raw_text}", limit=limit)
            return _mission_text(raw_text, limit=limit)

    return _mission_text(summary or raw_text or entry.get("label") or "", limit=limit)


def _ledger_node_evidence_entry(node: dict[str, Any], *, node_id: str, source: str) -> dict[str, Any]:
    provenance = _ledger_dict(node.get("provenance"))
    confidence_values = [
        node.get("evidence_confidence"),
        node.get("memory_confidence"),
        node.get("score"),
    ]
    confidence: float | None = None
    for value in confidence_values:
        try:
            parsed = float(value)
        except (TypeError, ValueError):
            continue
        confidence = max(0.0, min(1.0, parsed))
        break
    entry = {
        **node,
        "node_id": node_id,
        "section": (
            node.get("section")
            or node.get("section_key")
            or node.get("support_slot")
            or provenance.get("guide_conceptual_area")
            or node.get("memory_type")
        ),
        "source": source,
        "source_title": (
            node.get("source_title")
            or node.get("source_label")
            or node.get("source_unit_title")
            or provenance.get("source_label")
            or provenance.get("source_uri")
        ),
        "document_id": (
            node.get("document_id")
            or node.get("document_anchor_id")
            or provenance.get("document_id")
            or provenance.get("source_ref")
        ),
        "confidence": confidence,
    }
    return {key: value for key, value in entry.items() if value not in (None, "", [], {})}


def _ledger_compact_evidence_row(
    entry: dict[str, Any],
    *,
    source: str,
    default_promotion_state: str | None = None,
) -> dict[str, Any]:
    node_id = str(
        entry.get("node_id")
        or entry.get("target_node_id")
        or entry.get("source_node_id")
        or entry.get("anchor_node_id")
        or ""
    ).strip()
    text = _ledger_evidence_text(entry, limit=700)
    if not (node_id or text):
        return {}
    promotion_state = str(entry.get("promotion_state") or default_promotion_state or "").strip().lower()
    row = {
        "node_id": node_id or None,
        "section": str(entry.get("section") or entry.get("section_key") or entry.get("support_slot") or "").strip() or None,
        "text": text or None,
        "source": source,
        "promotion_state": promotion_state or None,
        "support_slot": str(entry.get("support_slot") or "").strip() or None,
        "document_id": str(entry.get("document_id") or entry.get("source_ref") or entry.get("source_id") or "").strip() or None,
        "source_title": _mission_text(entry.get("source_title") or entry.get("title") or "", limit=180) or None,
        "confidence": entry.get("confidence"),
        "reason": _mission_text(entry.get("reason") or "", limit=220) or None,
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def _ledger_evidence_rows_from_node_ids(node_ids: list[str], *, source: str, cold_answer_signal: bool = False) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    cleaned_ids = _ledger_id_list(node_ids, limit=64)
    hydrated_by_id: dict[str, dict[str, Any]] = {}
    if cleaned_ids:
        try:
            hydrated_by_id = {
                str(node.get("id") or node.get("node_id") or "").strip(): dict(node)
                for node in fetch_nodes_by_ids(cleaned_ids, include_raw_text=True)
                if isinstance(node, dict) and str(node.get("id") or node.get("node_id") or "").strip()
            }
        except Exception:
            hydrated_by_id = {}
    for node_id in cleaned_ids:
        node = hydrated_by_id.get(node_id)
        if node:
            row = _ledger_compact_evidence_row(
                _ledger_node_evidence_entry(node, node_id=node_id, source=source),
                source=source,
                default_promotion_state="cold" if cold_answer_signal else "hot",
            )
            if not row:
                row = {"node_id": node_id, "source": source}
            else:
                row["hydrated_from_node_store"] = True
        else:
            row = {"node_id": node_id, "source": source}
        if cold_answer_signal:
            row["cold_answer_signal"] = True
        rows.append(row)
    return rows


def _ledger_collect_evidence_entries(
    *,
    evidence_reservoir: dict[str, Any] | None = None,
    matches: list[dict[str, Any]] | None = None,
    path_corridors: dict[str, Any] | None = None,
    limit: int = 240,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add(raw: Any, *, source: str, path_id: str | None = None) -> None:
        if len(rows) >= limit:
            return
        entry = _ledger_dict(raw)
        if not entry:
            return
        if path_id and not str(entry.get("path_id") or "").strip():
            entry["path_id"] = path_id
        node_id = str(entry.get("node_id") or entry.get("target_node_id") or entry.get("source_node_id") or "").strip()
        text = _ledger_evidence_text(entry, limit=500)
        key = f"{node_id}:{_ledger_text_key(text)[:140]}:{source}:{path_id or ''}"
        if not (node_id or text) or key in seen:
            return
        seen.add(key)
        entry["_ledger_source"] = source
        rows.append(entry)

    reservoir = _ledger_dict(evidence_reservoir)
    for entry in _ledger_list(reservoir.get("entries")):
        add(entry, source="evidence_reservoir.entries")
    for match in list(matches or []):
        add(match, source="retrieval.matches")
    corridors = _ledger_dict(path_corridors)
    for entry in _ledger_list(corridors.get("useful_intermediate_material")):
        add(entry, source="path_corridors.useful_intermediate_material")
    for path in _ledger_list(corridors.get("paths") or corridors.get("corridors")):
        path_row = _ledger_dict(path)
        if not path_row:
            continue
        path_id = str(path_row.get("path_id") or path_row.get("ai_spatial_path_id") or "").strip() or None
        for key in ("useful_intermediate_material", "intermediate_nodes"):
            for entry in _ledger_list(path_row.get(key)):
                add(entry, source=f"path_corridors.paths.{key}", path_id=path_id)
    return rows[:limit]


def _ledger_entry_matches_mission(entry: dict[str, Any], mission: dict[str, Any], branch: dict[str, Any] | None = None) -> bool:
    mission_keys = _ledger_mission_match_keys(mission, branch)
    if not mission_keys:
        return False
    entry_keys = _ledger_entry_match_keys(entry)
    if mission_keys.intersection(entry_keys):
        return True
    text_key = _ledger_text_key(_ledger_evidence_text(entry, limit=900))
    if not text_key:
        return False
    strong_keys = {key for key in mission_keys if len(key) >= 5 and key not in {"source", "document", "documents"}}
    return any(key in text_key for key in strong_keys)


def _ledger_select_support_evidence(
    *,
    mission: dict[str, Any],
    branch: dict[str, Any] | None,
    entries: list[dict[str, Any]],
    desired_states: set[str],
    fallback_answer_eligible: bool = False,
    limit: int = 8,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for entry in entries:
        if len(rows) >= limit:
            break
        payload = dict(entry or {})
        if not _ledger_entry_matches_mission(payload, mission, branch):
            continue
        promotion_state = str(payload.get("promotion_state") or "").strip().lower()
        state_match = promotion_state in desired_states
        if not state_match and fallback_answer_eligible:
            state_match = bool(payload.get("answer_eligible")) and promotion_state not in {"cold", "excluded", "forbidden", "duplicate"}
        if not state_match:
            continue
        source = str(payload.get("_ledger_source") or "runtime_evidence").strip()
        row = _ledger_compact_evidence_row(
            payload,
            source=source,
            default_promotion_state=promotion_state or ("hot" if fallback_answer_eligible else None),
        )
        node_id = str(row.get("node_id") or "").strip()
        text_key = _ledger_text_key(row.get("text"))[:160]
        key = node_id or text_key
        if not key or key in seen:
            continue
        seen.add(key)
        rows.append(row)
    return rows[:limit]


def _ledger_path_corridor_branches(path_corridors: dict[str, Any] | None, *, limit: int = 24) -> list[dict[str, Any]]:
    corridors = _ledger_dict(path_corridors)
    if not corridors:
        return []
    rows: list[dict[str, Any]] = []
    for index, raw_path in enumerate(_ledger_list(corridors.get("paths") or corridors.get("corridors")), start=1):
        if len(rows) >= limit:
            break
        path = _ledger_dict(raw_path)
        if not path:
            continue
        path_id = str(path.get("ai_spatial_path_id") or path.get("path_id") or f"P{index}").strip() or f"P{index}"
        material = [
            _ledger_dict(item)
            for key in ("useful_intermediate_material", "intermediate_nodes")
            for item in _ledger_list(path.get(key))
            if _ledger_dict(item)
        ]
        hot_node_ids = _ledger_id_list(
            [
                item
                for item in material
                if str(item.get("promotion_state") or "").strip().lower() in {"hot", "promoted", "audit"}
            ],
            limit=32,
        )
        cold_node_ids = _ledger_id_list(
            [
                item
                for item in material
                if str(item.get("promotion_state") or "").strip().lower() in {"cold", "reservoir"}
            ],
            limit=32,
        )
        excluded_node_ids = _ledger_id_list(
            [
                item
                for item in material
                if str(item.get("promotion_state") or "").strip().lower() in {"excluded", "forbidden"}
            ],
            limit=24,
        )
        route_events = [
            _ledger_dict(item)
            for item in _ledger_list(path.get("route_events") or path.get("events"))
            if _ledger_dict(item)
        ]
        goal = (
            path.get("goal")
            or path.get("why_traverse")
            or path.get("from_label")
            or path.get("to_label")
            or "path_corridor_goal"
        )
        rows.append(
            {
                "branch_id": str(path.get("branch_id") or f"path_corridor::{path_id}").strip(),
                "path_id": path_id,
                "ai_spatial_path_id": path_id,
                "goal": goal,
                "answer_hypothesis": path.get("answer_hypothesis") or path.get("why_traverse") or goal,
                "expected_answer_field": path.get("section") or path.get("support_slot") or path.get("target_slot"),
                "current_region": {
                    key: value
                    for key, value in {
                        "region_id": path.get("ai_spatial_landing_region_ref") or path.get("landing_region_ref"),
                        "bucket_key": path.get("bucket_key"),
                    }.items()
                    if value
                },
                "route_trace": route_events,
                "visited_node_ids": _ledger_id_list(
                    path.get("traversed_node_ids"),
                    route_events,
                    material,
                    limit=48,
                ),
                "evidence_node_ids": hot_node_ids,
                "reservoir_only_node_ids": cold_node_ids,
                "excluded_node_ids": excluded_node_ids,
                "destination_reached": str(path.get("lifecycle_state") or "") in {"completed", "stopped"} or bool(path.get("changed_context_package")),
                "_ledger_path_corridor_material": material,
                "ledger_source": "path_corridor_runtime",
                "planner_family": path.get("planner_source"),
                "heuristic_provisional": bool(path.get("heuristic_provisional")),
                "provisional_until_ai_spatial": bool(path.get("provisional_until_ai_spatial")),
            }
        )
    return rows


def _ledger_resolve_branch_mission(
    branch: dict[str, Any],
    *,
    branch_index: int,
    mission_by_id: dict[str, dict[str, Any]],
    mission_by_path_id: dict[str, dict[str, Any]],
    missions: list[dict[str, Any]],
) -> tuple[str, dict[str, Any]]:
    mission_id = _branch_path_mission_id(branch, mission_by_path_id=mission_by_path_id)
    mission = dict(mission_by_id.get(mission_id) or {})
    if mission:
        return mission_id, mission
    path_id = str(branch.get("ai_spatial_path_id") or branch.get("path_id") or "").strip()
    if path_id and path_id in mission_by_path_id:
        mission = dict(mission_by_path_id[path_id])
        return str(mission.get("mission_id") or "").strip(), mission
    branch_keys = _ledger_mission_match_keys(
        {
            "goal": branch.get("goal"),
            "answer_hypothesis": branch.get("answer_hypothesis"),
            "expected_evidence_shape": {
                "answer_field": branch.get("expected_answer_field") or branch.get("support_slot") or branch.get("section_key")
            },
        },
        branch,
    )
    scored: list[tuple[int, dict[str, Any]]] = []
    for candidate in missions:
        candidate_keys = _ledger_mission_match_keys(candidate)
        score = len(branch_keys.intersection(candidate_keys))
        if score > 0:
            scored.append((score, dict(candidate)))
    if scored:
        scored.sort(key=lambda item: item[0], reverse=True)
        mission = scored[0][1]
        return str(mission.get("mission_id") or "").strip(), mission
    fallback_id = f"branch_{str(branch.get('branch_id') or branch_index).strip() or branch_index}"
    return fallback_id, {
        "mission_id": fallback_id,
        "path_id": path_id or None,
        "goal": str(branch.get("goal") or "").strip() or "legacy_branch_goal",
        "answer_hypothesis": str(branch.get("answer_hypothesis") or "").strip() or None,
        "expected_evidence_shape": {
            "schema_version": "agvm.path_mission_expected_evidence_shape.v1",
            "answer_field": str(branch.get("expected_answer_field") or branch.get("support_slot") or "").strip() or None,
            "category_labels_are_metadata_only": True,
        },
        "ledger_source": "branch_without_path_mission_contract",
    }


def _branch_judgement_evidence_counts(row: dict[str, Any]) -> dict[str, int]:
    return {
        "hot": len([item for item in _ledger_list(row.get("hot_evidence")) if isinstance(item, dict)]),
        "cold": len([item for item in _ledger_list(row.get("cold_evidence")) if isinstance(item, dict)]),
        "duplicate": len([item for item in _ledger_list(row.get("duplicate_evidence")) if isinstance(item, dict)]),
        "excluded": len([item for item in _ledger_list(row.get("excluded_evidence")) if isinstance(item, dict)]),
        "document_refs": len([item for item in _ledger_list(row.get("document_refs")) if isinstance(item, dict)]),
        "route_events": len([item for item in _ledger_list(row.get("route_events")) if isinstance(item, dict)]),
        "visited_nodes": len(_ledger_id_list(row.get("visited_node_ids"), limit=256)),
    }


def _branch_judgement_has_provenance(row: dict[str, Any]) -> bool:
    refs = [dict(item) for item in _ledger_list(row.get("document_refs")) if isinstance(item, dict)]
    if any(str(ref.get("document_id") or ref.get("anchor_node_id") or ref.get("title") or "").strip() for ref in refs):
        return True
    for key in ("hot_evidence", "cold_evidence"):
        for raw in _ledger_list(row.get(key)):
            evidence = _ledger_dict(raw)
            if not evidence:
                continue
            source = str(evidence.get("source") or "").strip()
            if str(evidence.get("node_id") or evidence.get("document_id") or evidence.get("source_title") or "").strip():
                return True
            if source and (str(evidence.get("text") or "").strip() or str(evidence.get("section") or "").strip()):
                return True
    for event in _ledger_list(row.get("route_events")):
        payload = _ledger_dict(event)
        if str(payload.get("source_node_id") or payload.get("target_node_id") or payload.get("node_id") or "").strip():
            return True
    return False


def _branch_judgement_document_requested(row: dict[str, Any]) -> bool:
    expected_shape = _ledger_dict(row.get("expected_evidence_shape"))
    answer_field = _ledger_text_key(expected_shape.get("answer_field"))
    goal = _ledger_text_key(row.get("goal"))
    return bool(expected_shape.get("document_requested")) or answer_field in {"document", "documents", "source", "sources", "raw"} or any(
        marker in goal for marker in ("document", "source", "raw", "file")
    )


def _branch_judgement_private_or_off_contract(row: dict[str, Any]) -> bool:
    expected_shape = _ledger_dict(row.get("expected_evidence_shape"))
    haystack = " ".join(
        _ledger_text_key(value)
        for value in (
            row.get("goal"),
            row.get("answer_hypothesis"),
            row.get("coverage_reason"),
            row.get("missing_reason"),
            expected_shape.get("answer_field"),
            expected_shape.get("target_id"),
            expected_shape.get("support_slot"),
        )
    )
    markers = (
        "private",
        "privato",
        "non pubblico",
        "non public",
        "secret",
        "segreto",
        "password",
        "passport",
        "passaporto",
        "tax id",
        "fiscal",
        "phone private",
        "telefono privato",
        "off contract",
        "off_contract",
        "forbidden",
    )
    return any(marker in haystack for marker in markers)


def _branch_judgement_ai_required(row: dict[str, Any], *, query_text: str, retrieval_mode: str) -> bool:
    folded_query = _ledger_text_key(query_text)
    folded_goal = _ledger_text_key(row.get("goal"))
    route_events = _ledger_list(row.get("route_events"))
    mode = str(retrieval_mode or "").strip().lower()
    broad_markers = (
        "dossier",
        "complete",
        "completo",
        "broad",
        "ampio",
        "multi",
        "collega",
        "connect",
        "path",
        "percorso",
        "corridor",
        "forensic",
        "audit",
    )
    return (
        mode in {"heavy", "forensic"}
        or len(route_events) > 1
        or bool(row.get("wrong_region_signal"))
        or bool(row.get("heuristic_support_only"))
        or any(marker in folded_query or marker in folded_goal for marker in broad_markers)
    )


def _branch_judgement_cache_key(
    row: dict[str, Any],
    *,
    query_text: str,
    retrieval_mode: str,
    revision_context: dict[str, Any] | None,
    allow_ai_branch_controller: bool = False,
) -> str:
    revisions = dict(revision_context or {})
    try:
        brain_id = current_brain_id()
    except Exception:
        brain_id = None
    payload = {
        "schema_version": BRANCH_JUDGEMENT_SCHEMA_VERSION,
        "brain_id": brain_id,
        "retrieval_mode": retrieval_mode,
        "ai_branch_controller_mode": "enabled" if allow_ai_branch_controller else "disabled",
        "query_hint": _ledger_text_key(query_text)[:220],
        "revisions": {
            key: revisions.get(key)
            for key in (
                "brain_revision",
                "matrix_revision",
                "metamemory_revision",
                "topology_revision",
                "atlas_revision",
                "calibration_revision",
            )
            if revisions.get(key) is not None
        },
        "row": {
            "mission_id": row.get("mission_id"),
            "path_id": row.get("path_id"),
            "goal": row.get("goal"),
            "answer_hypothesis": row.get("answer_hypothesis"),
            "coverage_state": row.get("coverage_state"),
            "coverage_reason": row.get("coverage_reason"),
            "missing_reason": row.get("missing_reason"),
            "expected_evidence_shape": row.get("expected_evidence_shape"),
            "hot_evidence": row.get("hot_evidence"),
            "cold_evidence": row.get("cold_evidence"),
            "duplicate_evidence": row.get("duplicate_evidence"),
            "excluded_evidence": row.get("excluded_evidence"),
            "document_refs": row.get("document_refs"),
            "route_events": row.get("route_events"),
            "visited_node_ids": row.get("visited_node_ids"),
            "heuristic_support_only": row.get("heuristic_support_only"),
            "accepted_by_ai_or_master": row.get("accepted_by_ai_or_master"),
        },
    }
    return hashlib.sha1(json.dumps(payload, sort_keys=True, default=str, ensure_ascii=False).encode("utf-8")).hexdigest()


def _branch_autojudge_next_action(state: str, *, fallback: str | None = None) -> str | None:
    normalized = str(state or "").strip().lower()
    if normalized == "needs_document":
        return "retrieve_document"
    if normalized == "needs_radius_widen":
        return "continue_ai_guided_branch_search"
    if normalized == "wrong_region":
        return "rerun_ai_spatial_or_matrix_calibration_preview"
    if normalized == "useful_partial":
        return fallback or "inspect_path_corridor"
    if normalized == "provider_degraded":
        return "retry_retrieve_after_provider_recovers"
    return None


def _compact_branch_autojudge_row(row: dict[str, Any], *, counts: dict[str, int]) -> dict[str, Any]:
    expected = dict(row.get("expected_evidence_shape") or {})

    def evidence_head(values: Any, *, limit: int = 3) -> list[dict[str, Any]]:
        output: list[dict[str, Any]] = []
        for item in list(values or []):
            if not isinstance(item, dict):
                continue
            output.append(
                {
                    "node_id": str(item.get("node_id") or item.get("id") or "").strip()[:80] or None,
                    "source": str(item.get("source") or item.get("source_type") or "").strip()[:80] or None,
                    "text": str(
                        item.get("text")
                        or item.get("summary")
                        or item.get("claim")
                        or item.get("evidence_snippet")
                        or ""
                    ).strip()[:260],
                }
            )
            if len(output) >= limit:
                break
        return [{k: v for k, v in payload.items() if v not in (None, "")} for payload in output]

    return {
        "mission_id": str(row.get("mission_id") or row.get("branch_id") or "").strip()[:100],
        "path_id": str(row.get("path_id") or "").strip()[:100],
        "goal": str(row.get("goal") or "").strip()[:260],
        "answer_hypothesis": str(row.get("answer_hypothesis") or "").strip()[:360],
        "answer_field": str(expected.get("answer_field") or expected.get("target_id") or "").strip()[:120],
        "claim_shape": str(expected.get("claim_shape") or row.get("expected_claim_shape") or "").strip()[:260],
        "coverage_state": str(row.get("coverage_state") or "").strip()[:100],
        "coverage_reason": str(row.get("coverage_reason") or row.get("missing_reason") or "").strip()[:260],
        "counts": dict(counts),
        "hot_evidence_head": evidence_head(row.get("hot_evidence")),
        "cold_evidence_head": evidence_head(row.get("cold_evidence")),
        "document_refs_head": [
            {
                "document_id": str(dict(item).get("document_id") or dict(item).get("id") or "").strip()[:100],
                "title": str(dict(item).get("title") or dict(item).get("document_title") or "").strip()[:180],
                "raw_available": bool(dict(item).get("raw_available") or dict(item).get("raw_ready")),
            }
            for item in list(row.get("document_refs") or [])[:3]
            if isinstance(item, dict)
        ],
        "route_event_count": counts.get("route_events", 0),
        "visited_node_count": counts.get("visited_nodes", 0),
        "heuristic_support_only": bool(row.get("heuristic_support_only")),
        "accepted_by_ai_or_master": bool(row.get("accepted_by_ai_or_master")),
    }


def _ai_branch_autojudge_timeout_seconds(retrieval_mode: str) -> float:
    mode = str(retrieval_mode or "balanced").strip().lower()
    if mode == "flash":
        return 1.6
    if mode == "balanced":
        return 2.4
    if mode == "heavy":
        return 3.6
    return 4.2


def _normalize_ai_branch_autojudge_payload(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    data = dict(payload or {})
    state = str(data.get("state") or data.get("branch_state") or "").strip().lower()
    if state not in _AI_BRANCH_AUTOJUDGE_STATES:
        return None
    confidence = data.get("confidence")
    try:
        confidence_value = float(confidence)
    except (TypeError, ValueError):
        confidence_value = 0.72
    reason_codes = [
        str(item or "").strip()
        for item in list(data.get("reason_codes") or data.get("reasons") or [])
        if str(item or "").strip()
    ]
    reason = str(data.get("reason") or "").strip()
    if reason and "ai_branch_reason" not in reason_codes:
        reason_codes.insert(0, "ai_branch_reason")
    missing = [
        str(item or "").strip()
        for item in list(data.get("missing_evidence") or data.get("expected_missing_evidence") or [])
        if str(item or "").strip()
    ]
    return {
        "state": state,
        "confidence": round(max(0.0, min(1.0, confidence_value)), 3),
        "reason": reason[:360] or None,
        "reason_codes": _dedupe_limited(reason_codes or [f"ai_branch_{state}"], limit=8),
        "missing_evidence": _dedupe_limited(missing, limit=6),
        "next_recommended_action": str(data.get("next_recommended_action") or "").strip() or None,
    }


def _run_ai_branch_autojudge(
    row: dict[str, Any],
    *,
    query_text: str,
    retrieval_mode: str,
    counts: dict[str, int],
    revision_context: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, str | None, float]:
    if not llm_enabled():
        return None, "llm_disabled", 0.0
    schema = {
        "type": "object",
        "additionalProperties": False,
        "required": ["state", "confidence", "reason"],
        "properties": {
            "state": {"type": "string", "enum": sorted(_AI_BRANCH_AUTOJUDGE_STATES)},
            "confidence": {"type": "number", "minimum": 0.0, "maximum": 1.0},
            "reason": {"type": "string"},
            "reason_codes": {"type": "array", "maxItems": 8, "items": {"type": "string"}},
            "missing_evidence": {"type": "array", "maxItems": 6, "items": {"type": "string"}},
            "next_recommended_action": {
                "type": ["string", "null"],
                "enum": [
                    None,
                    "retrieve_document",
                    "continue_ai_guided_branch_search",
                    "rerun_ai_spatial_or_matrix_calibration_preview",
                    "inspect_path_corridor",
                    "retry_retrieve_after_provider_recovers",
                    "stop",
                ],
            },
        },
    }
    prompt_payload = {
        "schema_version": AI_BRANCH_AUTOJUDGE_SCHEMA_VERSION,
        "query": str(query_text or "")[:500],
        "retrieval_mode": str(retrieval_mode or "balanced"),
        "revision_context": {
            key: value
            for key, value in dict(revision_context or {}).items()
            if key
            in {
                "brain_revision",
                "matrix_revision",
                "metamemory_revision",
                "topology_revision",
                "atlas_revision",
                "calibration_revision",
            }
        },
        "branch": _compact_branch_autojudge_row(row, counts=counts),
        "policy": {
            "judge_only_this_branch": True,
            "no_raw_document_bodies": True,
            "resolved_requires_visible_provenance": True,
            "heuristic_support_cannot_certify_without_ai_or_master_acceptance": True,
        },
    }
    started_at = time.perf_counter()
    payload, error = structured_json(
        model=retrieval_model(),
        system_prompt=(
            "You are AGVM's branch evidence judge. Judge only this compact branch ledger. "
            "Do not answer the user and do not invent missing facts. Decide whether this branch is resolved, useful partial, "
            "needs document hydration, needs radius widening, landed in the wrong region, should stop, or is provider degraded. "
            "Visible provenance is mandatory for a resolved branch."
        ),
        user_prompt=json.dumps(prompt_payload, ensure_ascii=False),
        schema_name="agvm_ai_branch_autojudge_v1",
        schema=schema,
        timeout=_ai_branch_autojudge_timeout_seconds(retrieval_mode),
        role="retrieval",
        max_output_tokens=260,
    )
    elapsed_ms = round((time.perf_counter() - started_at) * 1000.0, 3)
    if error or not isinstance(payload, dict):
        return None, error or "llm_empty", elapsed_ms
    normalized = _normalize_ai_branch_autojudge_payload(payload)
    if not normalized:
        return None, "invalid_ai_branch_autojudge_payload", elapsed_ms
    return normalized, None, elapsed_ms


def _branch_autojudge_row(
    row: dict[str, Any],
    *,
    query_text: str = "",
    retrieval_mode: str = "balanced",
    revision_context: dict[str, Any] | None = None,
    allow_ai_branch_controller: bool = False,
) -> dict[str, Any]:
    key = _branch_judgement_cache_key(
        row,
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        revision_context=revision_context,
        allow_ai_branch_controller=allow_ai_branch_controller,
    )
    with _BRANCH_AUTOJUDGE_CACHE_LOCK:
        cached = _BRANCH_AUTOJUDGE_CACHE.get(key)
    if cached:
        result = dict(cached)
        result["cache_hit"] = True
        return result

    counts = _branch_judgement_evidence_counts(row)
    coverage_state = str(row.get("coverage_state") or "").strip().lower()
    has_useful = bool(counts["hot"] or counts["cold"] or counts["document_refs"])
    has_hot_or_doc = bool(counts["hot"] or counts["document_refs"])
    has_provenance = _branch_judgement_has_provenance(row)
    document_requested = _branch_judgement_document_requested(row)
    private_or_off_contract = _branch_judgement_private_or_off_contract(row)
    ai_required = _branch_judgement_ai_required(row, query_text=query_text, retrieval_mode=retrieval_mode)
    next_action: str | None = None
    reason_codes: list[str] = []
    state = "stop"
    confidence = 0.3
    deterministic_clear = False

    if coverage_state in {"provider_degraded", "timeout", "failed"}:
        state = "provider_degraded"
        confidence = 0.95
        deterministic_clear = True
        next_action = "retry_retrieve_after_provider_recovers"
        reason_codes.append("provider_degraded")
    elif counts["excluded"] and not has_useful:
        state = "excluded_only"
        confidence = 0.95
        deterministic_clear = True
        next_action = None
        reason_codes.append("only_excluded_or_forbidden_material")
    elif coverage_state in {"forbidden", "excluded_only"} or private_or_off_contract and not has_hot_or_doc:
        state = "excluded_only" if counts["excluded"] else "stop"
        confidence = 0.9
        deterministic_clear = True
        next_action = None
        reason_codes.append("private_or_off_contract_not_answerable")
    elif counts["duplicate"] and not has_useful:
        state = "duplicate_only"
        confidence = 0.9
        deterministic_clear = True
        next_action = "reuse_existing_hot_context_or_expand_different_region"
        reason_codes.append("duplicate_only_without_new_evidence")
    elif coverage_state == "resolved":
        if has_hot_or_doc and has_provenance:
            if bool(row.get("heuristic_support_only")) and not bool(row.get("accepted_by_ai_or_master")):
                state = "useful_partial"
                confidence = 0.68
                next_action = "wait_for_ai_or_master_acceptance"
                reason_codes.append("heuristic_support_not_certifying")
            else:
                state = "resolved"
                confidence = 0.92
                deterministic_clear = True
                next_action = None
                reason_codes.append("sufficient_visible_evidence_with_provenance")
        elif document_requested:
            state = "needs_document"
            confidence = 0.72
            next_action = "retrieve_document"
            reason_codes.append("document_requested_but_refs_or_raw_missing")
        else:
            state = "useful_partial"
            confidence = 0.58
            next_action = "inspect_path_corridor"
            reason_codes.append("resolved_state_without_visible_provenance")
    elif coverage_state in {"partially_resolved", "near_miss"} and has_useful:
        if document_requested and not counts["document_refs"]:
            state = "needs_document"
            confidence = 0.74
            next_action = "retrieve_document"
            reason_codes.append("partial_material_needs_document_hydration")
        else:
            state = "useful_partial"
            confidence = 0.66
            next_action = "inspect_path_corridor"
            reason_codes.append("useful_evidence_not_yet_branch_complete")
    elif coverage_state == "wrong_region" or bool(row.get("wrong_region_signal")):
        state = "wrong_region"
        confidence = 0.82
        next_action = "rerun_ai_spatial_or_matrix_calibration_preview"
        reason_codes.append("branch_landed_in_wrong_region")
    elif coverage_state in {"near_miss"} or counts["route_events"] or counts["visited_nodes"]:
        state = "needs_radius_widen"
        confidence = 0.7
        next_action = "widen_radius_or_traverse_bridge"
        reason_codes.append("route_executed_without_enough_evidence")
    elif document_requested and counts["document_refs"]:
        state = "needs_document"
        confidence = 0.72
        next_action = "retrieve_document"
        reason_codes.append("document_refs_available_but_branch_material_missing")
    elif coverage_state in {"missed", ""} and ai_required and not private_or_off_contract:
        state = "needs_radius_widen"
        confidence = 0.62
        next_action = "continue_ai_guided_branch_search"
        reason_codes.append("ai_required_branch_missed_without_no_match_proof")
    elif coverage_state in {"missed", ""}:
        state = "stop"
        confidence = 0.78
        deterministic_clear = True
        next_action = None
        reason_codes.append("no_visible_branch_evidence")
    else:
        state = "stop"
        confidence = 0.55
        next_action = None
        reason_codes.append("unhandled_branch_state_stopped")

    if not has_provenance and state == "resolved":
        state = "useful_partial"
        confidence = min(confidence, 0.58)
        next_action = next_action or "inspect_path_corridor"
        reason_codes.append("downgraded_no_visible_provenance")
    if private_or_off_contract and state in {"resolved", "useful_partial", "needs_document"} and counts["excluded"]:
        state = "excluded_only"
        confidence = 0.93
        next_action = None
        reason_codes.append("off_contract_evidence_excluded")

    controller_source = "deterministic_evidence_gate"
    controller_state = "deterministic_clear" if deterministic_clear else "deterministic_fallback_ai_controller_recommended"
    if ai_required and not deterministic_clear:
        controller_source = "deterministic_fallback_pending_ai_branch_controller"
    elif ai_required and deterministic_clear:
        controller_source = "deterministic_clear_over_ai_authored_mission"

    ai_controller_payload: dict[str, Any] | None = None
    ai_controller_error: str | None = None
    ai_controller_turn_ms = 0.0
    ai_controller_used = False
    if ai_required and not deterministic_clear and allow_ai_branch_controller:
        ai_controller_payload, ai_controller_error, ai_controller_turn_ms = _run_ai_branch_autojudge(
            row,
            query_text=query_text,
            retrieval_mode=retrieval_mode,
            counts=counts,
            revision_context=revision_context,
        )
        if ai_controller_payload:
            requested_state = str(ai_controller_payload.get("state") or "").strip().lower()
            ai_controller_used = True
            controller_source = "llm_branch_autojudge"
            controller_state = "ai_controller_used"
            state = requested_state
            confidence = float(ai_controller_payload.get("confidence") or confidence)
            next_action = (
                str(ai_controller_payload.get("next_recommended_action") or "").strip()
                or _branch_autojudge_next_action(state, fallback=next_action)
            )
            reason_codes.extend(list(ai_controller_payload.get("reason_codes") or []))
            if ai_controller_payload.get("missing_evidence"):
                reason_codes.append("ai_branch_named_missing_evidence")
            if not has_provenance and state == "resolved":
                state = "useful_partial"
                confidence = min(confidence, 0.58)
                next_action = next_action or "inspect_path_corridor"
                reason_codes.append("ai_resolved_downgraded_no_visible_provenance")
            if private_or_off_contract and state in {"resolved", "useful_partial", "needs_document"} and counts["excluded"]:
                state = "excluded_only"
                confidence = 0.93
                next_action = None
                reason_codes.append("ai_branch_off_contract_evidence_excluded")
        else:
            controller_source = "deterministic_fallback_after_ai_branch_controller_error"
            controller_state = "ai_controller_error_fallback"
            reason_codes.append("ai_branch_controller_unavailable")
    elif ai_required and not deterministic_clear:
        reason_codes.append("ai_branch_controller_not_enabled_for_call_site")

    result = {
        "schema_version": BRANCH_JUDGEMENT_SCHEMA_VERSION,
        "judgement_id": f"branch_judge_{str(row.get('mission_id') or row.get('branch_id') or 'row').strip()}_{state}",
        "state": state,
        "confidence": round(float(confidence), 3),
        "reason_codes": _dedupe_limited(reason_codes, limit=12),
        "missing_reason": str(row.get("missing_reason") or row.get("coverage_reason") or "").strip() or None,
        "next_recommended_action": next_action,
        "evidence_counts": counts,
        "has_visible_provenance": has_provenance,
        "document_requested": document_requested,
        "private_or_off_contract_request": private_or_off_contract,
        "ai_branch_controller_required": ai_required,
        "ai_branch_controller_state": controller_state,
        "ai_branch_controller_used": ai_controller_used,
        "ai_branch_controller_error": ai_controller_error,
        "ai_branch_controller_turn_ms": ai_controller_turn_ms if ai_controller_turn_ms else None,
        "ai_branch_missing_evidence": list(ai_controller_payload.get("missing_evidence") or []) if ai_controller_payload else [],
        "branch_controller_source": controller_source,
        "judge_source": controller_source,
        "cache_key": key[:16],
        "cache_hit": False,
        "independent_from_answer_demo": True,
    }
    result = {k: v for k, v in result.items() if v not in (None, [], {})}
    with _BRANCH_AUTOJUDGE_CACHE_LOCK:
        if len(_BRANCH_AUTOJUDGE_CACHE) >= _BRANCH_AUTOJUDGE_CACHE_MAX:
            _BRANCH_AUTOJUDGE_CACHE.clear()
        _BRANCH_AUTOJUDGE_CACHE[key] = dict(result)
    return result


def apply_branch_autojudge_to_mission_ledger(
    mission_evidence_ledger: dict[str, Any] | None,
    *,
    query_text: str = "",
    retrieval_mode: str = "balanced",
    revision_context: dict[str, Any] | None = None,
    allow_ai_branch_controller: bool = False,
    max_workers: int | None = None,
) -> dict[str, Any]:
    ledger = dict(mission_evidence_ledger or {})
    rows = [dict(row) for row in _ledger_list(ledger.get("rows")) if isinstance(row, dict)]
    started_at = time.perf_counter()
    if not rows:
        ledger["branch_judgement_summary"] = {
            "schema_version": BRANCH_AUTOJUDGE_SCHEMA_VERSION,
            "status": "empty",
            "row_count": 0,
            "state_counts": {},
            "judge_timing_ms": 0.0,
        }
        return ledger

    worker_count = max(1, min(int(max_workers or 6), len(rows)))
    judged_by_index: dict[int, dict[str, Any]] = {}
    if worker_count == 1:
        for index, row in enumerate(rows):
            judged_by_index[index] = _branch_autojudge_row(
                row,
                query_text=query_text,
                retrieval_mode=retrieval_mode,
                revision_context=revision_context,
                allow_ai_branch_controller=allow_ai_branch_controller,
            )
    else:
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            future_by_index = {
                executor.submit(
                    _branch_autojudge_row,
                    row,
                    query_text=query_text,
                    retrieval_mode=retrieval_mode,
                    revision_context=revision_context,
                    allow_ai_branch_controller=allow_ai_branch_controller,
                ): index
                for index, row in enumerate(rows)
            }
            for future in as_completed(future_by_index):
                judged_by_index[future_by_index[future]] = future.result()

    state_counts: dict[str, int] = {}
    cache_hits = 0
    ai_required_count = 0
    ai_used_count = 0
    ai_error_count = 0
    deterministic_clear_count = 0
    controller_sources: dict[str, int] = {}
    for index, row in enumerate(rows):
        judgement = dict(judged_by_index.get(index) or {})
        state = str(judgement.get("state") or "unknown")
        state_counts[state] = state_counts.get(state, 0) + 1
        cache_hits += int(bool(judgement.get("cache_hit")))
        ai_required_count += int(bool(judgement.get("ai_branch_controller_required")))
        ai_used_count += int(bool(judgement.get("ai_branch_controller_used")))
        ai_error_count += int(bool(judgement.get("ai_branch_controller_error")))
        deterministic_clear_count += int(str(judgement.get("ai_branch_controller_state") or "") == "deterministic_clear")
        source = str(judgement.get("branch_controller_source") or judgement.get("judge_source") or "").strip()
        if source:
            controller_sources[source] = controller_sources.get(source, 0) + 1
        row["branch_judgement"] = judgement
        rows[index] = row

    accepted_states = {"resolved", "useful_partial", "needs_document"}
    action_states = {"needs_radius_widen", "wrong_region"}
    status = "ready"
    if state_counts.get("provider_degraded"):
        status = "provider_degraded"
    elif any(state in action_states for state in state_counts):
        status = "needs_more_search"
    elif not any(state in accepted_states for state in state_counts):
        status = "no_actionable_branch"
    summary = {
        "schema_version": BRANCH_AUTOJUDGE_SCHEMA_VERSION,
        "status": status,
        "row_count": len(rows),
        "state_counts": state_counts,
        "resolved_count": state_counts.get("resolved", 0),
        "useful_partial_count": state_counts.get("useful_partial", 0),
        "needs_document_count": state_counts.get("needs_document", 0),
        "needs_radius_widen_count": state_counts.get("needs_radius_widen", 0),
        "wrong_region_count": state_counts.get("wrong_region", 0),
        "duplicate_only_count": state_counts.get("duplicate_only", 0),
        "excluded_only_count": state_counts.get("excluded_only", 0),
        "provider_degraded_count": state_counts.get("provider_degraded", 0),
        "stop_count": state_counts.get("stop", 0),
        "ai_branch_controller_required_count": ai_required_count,
        "branch_ai_controller_count": ai_used_count,
        "branch_ai_controller_error_count": ai_error_count,
        "deterministic_clear_count": deterministic_clear_count,
        "branch_controller_sources": controller_sources,
        "cache_hit_count": cache_hits,
        "cache_miss_count": max(0, len(rows) - cache_hits),
        "parallel_worker_count": worker_count,
        "judge_timing_ms": round((time.perf_counter() - started_at) * 1000.0, 3),
        "source": "mission_evidence_ledger",
        "independent_from_answer_demo": True,
    }
    ledger["rows"] = rows
    ledger["branch_judgement_summary"] = summary
    ledger["branch_judge_timing_ms"] = summary["judge_timing_ms"]
    ledger["branch_judge_state_counts"] = state_counts
    ledger["branch_judge_ready"] = status in {"ready", "no_actionable_branch", "provider_degraded"}
    return ledger


def build_mission_evidence_ledger(
    *,
    path_mission_contract: dict[str, Any] | None,
    branches: list[dict[str, Any]],
    route_runtime: dict[str, Any] | None = None,
    document_refs: list[dict[str, Any]] | None = None,
    document_workspace: dict[str, Any] | None = None,
    semantic_contract_runtime: dict[str, Any] | None = None,
    ai_spatial_landing_contract_runtime: dict[str, Any] | None = None,
    path_corridors: dict[str, Any] | None = None,
    evidence_reservoir: dict[str, Any] | None = None,
    matches: list[dict[str, Any]] | None = None,
    query_text: str = "",
    retrieval_mode: str = "balanced",
    revision_context: dict[str, Any] | None = None,
    allow_ai_branch_controller: bool = False,
) -> dict[str, Any]:
    contract = dict(path_mission_contract or {})
    missions = [dict(item) for item in list(contract.get("path_missions") or []) if isinstance(item, dict)]
    mission_by_id = {
        str(mission.get("mission_id") or "").strip(): dict(mission)
        for mission in missions
        if str(mission.get("mission_id") or "").strip()
    }
    mission_by_path_id = {
        str(mission.get("path_id") or "").strip(): dict(mission)
        for mission in missions
        if str(mission.get("path_id") or "").strip()
    }
    global_document_refs = _ledger_document_refs(document_refs or [], document_workspace or {}, limit=24)
    document_evidence_lane = _ledger_dict((document_workspace or {}).get("document_evidence_lane"))
    semantic_runtime = dict(semantic_contract_runtime or {})
    spatial_runtime = dict(ai_spatial_landing_contract_runtime or {})
    provider_degraded = (
        str(semantic_runtime.get("status") or "").strip().lower() in {"provider_degraded", "failed", "timeout"}
        or str(spatial_runtime.get("status") or "").strip().lower() in {"provider_degraded", "failed", "timeout"}
    )
    ledger_completed_at = utc_timestamp()
    rows: list[dict[str, Any]] = []
    seen_missions: set[str] = set()
    runtime_evidence_entries = _ledger_collect_evidence_entries(
        evidence_reservoir=evidence_reservoir,
        matches=matches or [],
        path_corridors=path_corridors,
    )
    branch_inputs = [
        dict(item)
        for item in list(branches or [])
        if isinstance(item, dict)
    ]
    branch_inputs.extend(_ledger_path_corridor_branches(path_corridors))
    for branch_index, raw_branch in enumerate(branch_inputs, start=1):
        if not isinstance(raw_branch, dict):
            continue
        branch = dict(raw_branch)
        mission_id, mission = _ledger_resolve_branch_mission(
            branch,
            branch_index=branch_index,
            mission_by_id=mission_by_id,
            mission_by_path_id=mission_by_path_id,
            missions=missions,
        )
        seen_missions.add(mission_id)
        route_trace = [_ledger_dict(item) for item in _ledger_list(branch.get("route_trace")) if _ledger_dict(item)]
        hot_node_ids = _ledger_id_list(branch.get("evidence_node_ids"), limit=32)
        cold_node_ids = _ledger_id_list(
            branch.get("reservoir_only_node_ids"),
            branch.get("cold_node_ids"),
            branch.get("cold_evidence_node_ids"),
            limit=32,
        )
        duplicate_node_ids = _ledger_id_list(
            branch.get("duplicate_node_ids"),
            branch.get("duplicate_evidence_node_ids"),
            branch.get("reused_node_ids"),
            limit=24,
        )
        excluded_node_ids = _ledger_id_list(
            branch.get("excluded_node_ids"),
            branch.get("forbidden_node_ids"),
            branch.get("disallowed_node_ids"),
            limit=24,
        )
        visited_node_ids = _ledger_id_list(
            branch.get("visited_node_ids"),
            branch.get("candidate_node_ids"),
            branch.get("studied_node_ids"),
            branch.get("hydrated_node_ids"),
            branch.get("traversed_nodes"),
            route_trace,
            hot_node_ids,
            cold_node_ids,
            limit=48,
        )
        row_document_refs = _ledger_document_refs(
            branch.get("document_refs"),
            branch.get("source_trace"),
            branch.get("document_packets"),
            route_trace,
            limit=12,
        )
        expected_shape = _ledger_dict(mission.get("expected_evidence_shape"))
        if not row_document_refs and bool(expected_shape.get("document_requested")):
            row_document_refs = global_document_refs[:8]
        route_events = _ledger_route_events(route_trace, limit=18)
        traversed_edges = _ledger_traversed_edges(branch, route_trace, limit=24)
        hot_evidence_rows = _ledger_evidence_rows_from_node_ids(hot_node_ids, source="branch.evidence_node_ids")
        if not hot_evidence_rows:
            hot_evidence_rows = _ledger_select_support_evidence(
                mission=mission,
                branch=branch,
                entries=runtime_evidence_entries,
                desired_states={"hot", "promoted", "audit"},
                fallback_answer_eligible=True,
                limit=8,
            )
            hot_node_ids = _ledger_id_list([row.get("node_id") for row in hot_evidence_rows], limit=32)
        cold_evidence_rows = _ledger_evidence_rows_from_node_ids(
            cold_node_ids,
            source="branch.reservoir_only_node_ids",
            cold_answer_signal=True,
        )
        if not cold_evidence_rows and not hot_evidence_rows:
            cold_evidence_rows = _ledger_select_support_evidence(
                mission=mission,
                branch=branch,
                entries=runtime_evidence_entries,
                desired_states={"cold", "reservoir", "off_contract"},
                fallback_answer_eligible=False,
                limit=8,
            )
            for row in cold_evidence_rows:
                row["cold_answer_signal"] = True
            cold_node_ids = _ledger_id_list([row.get("node_id") for row in cold_evidence_rows], limit=32)
        duplicate_evidence_rows = _ledger_evidence_rows_from_node_ids(duplicate_node_ids, source="duplicate_or_warm_material")
        if not duplicate_evidence_rows:
            duplicate_evidence_rows = _ledger_select_support_evidence(
                mission=mission,
                branch=branch,
                entries=runtime_evidence_entries,
                desired_states={"duplicate", "warm"},
                fallback_answer_eligible=False,
                limit=6,
            )
            duplicate_node_ids = _ledger_id_list([row.get("node_id") for row in duplicate_evidence_rows], limit=24)
        excluded_evidence_rows = _ledger_evidence_rows_from_node_ids(excluded_node_ids, source="excluded_or_forbidden_material")
        if not excluded_evidence_rows:
            excluded_evidence_rows = _ledger_select_support_evidence(
                mission=mission,
                branch=branch,
                entries=runtime_evidence_entries,
                desired_states={"excluded", "forbidden"},
                fallback_answer_eligible=False,
                limit=6,
            )
            excluded_node_ids = _ledger_id_list([row.get("node_id") for row in excluded_evidence_rows], limit=24)
        coverage_state, coverage_reason = _mission_coverage_state(
            mission=mission,
            branch=branch,
            hot_node_ids=hot_node_ids,
            cold_node_ids=cold_node_ids,
            hot_evidence_rows=hot_evidence_rows,
            cold_evidence_rows=cold_evidence_rows,
            duplicate_node_ids=duplicate_node_ids,
            excluded_node_ids=excluded_node_ids,
            document_refs=row_document_refs,
            route_events=route_events,
            visited_node_ids=visited_node_ids,
            provider_degraded=provider_degraded,
        )
        branch_snap = _ledger_dict(branch.get("spatial_snap"))
        current_region = _ledger_dict(branch.get("current_region"))
        row = {
            "schema_version": MISSION_LEDGER_ROW_SCHEMA_VERSION,
            "mission_id": mission_id,
            "path_id": str(mission.get("path_id") or branch.get("ai_spatial_path_id") or "").strip() or None,
            "branch_id": str(branch.get("branch_id") or "").strip() or None,
            "started_at": str(branch.get("started_at") or branch.get("created_at") or "").strip() or None,
            "completed_at": str(branch.get("completed_at") or ledger_completed_at).strip(),
            "stage_timings": _ledger_dict(branch.get("stage_timings") or branch.get("runtime_stage_timing")),
            "goal": _mission_text(mission.get("goal") or branch.get("goal") or "", limit=240),
            "answer_hypothesis": _mission_text(mission.get("answer_hypothesis") or branch.get("answer_hypothesis") or "", limit=520) or None,
            "expected_evidence_shape": expected_shape,
            "hot_cold_policy": _ledger_dict(mission.get("hot_cold_policy")),
            "landing_region_ref": mission.get("landing_region_ref"),
            "snapped_landing": branch_snap or None,
            "snap_delta": branch_snap.get("snap_delta"),
            "current_region": current_region or None,
            "visited_node_ids": visited_node_ids,
            "traversed_edges": traversed_edges,
            "route_events": route_events,
            "hot_evidence": hot_evidence_rows,
            "cold_evidence": cold_evidence_rows,
            "duplicate_evidence": duplicate_evidence_rows,
            "excluded_evidence": excluded_evidence_rows,
            "document_refs": row_document_refs,
            "document_refs_seen": row_document_refs,
            "coverage_state": coverage_state,
            "coverage_reason": coverage_reason,
            "missing_reason": coverage_reason if coverage_state not in {"resolved"} else None,
            "wrong_region_signal": _ledger_dict(branch.get("wrong_region_signal")),
            "correction_signal": {
                "schema_version": "agvm.mission_correction_signal.v1",
                "state": coverage_state,
                "path_mission_id": mission_id,
                "expected_region_ref": mission.get("landing_region_ref"),
                "observed_bucket_keys": _ledger_id_list(
                    branch.get("visited_bucket_keys"),
                    current_region.get("bucket_key"),
                    branch_snap.get("bucket_key"),
                    limit=12,
                ),
                "learning_use": "feed_heuristic_calibration_sleep_evolve_after_review",
                "needs_review": coverage_state in {"near_miss", "missed", "wrong_region", "provider_degraded"},
            },
            "package_candidate_sections": _dedupe_limited(
                [
                    str(expected_shape.get("target_id") or ""),
                    str(expected_shape.get("answer_field") or ""),
                    str(branch.get("expected_answer_field") or ""),
                    _goal_to_slot(str(mission.get("goal") or branch.get("goal") or "")),
                ],
                limit=8,
            ),
            "planner_family": str(branch.get("planner_family") or branch.get("planner_source") or "").strip() or None,
            "heuristic_support_only": bool(branch.get("heuristic_provisional") or branch.get("provisional_until_ai_spatial")),
            "accepted_by_ai_or_master": not bool(branch.get("heuristic_provisional") or branch.get("provisional_until_ai_spatial")),
        }
        rows.append({key: value for key, value in row.items() if value not in (None, [], {})})
    for mission in missions:
        mission_id = str(mission.get("mission_id") or "").strip()
        if not mission_id or mission_id in seen_missions:
            continue
        expected_shape = _ledger_dict(mission.get("expected_evidence_shape"))
        row = {
            "schema_version": MISSION_LEDGER_ROW_SCHEMA_VERSION,
            "mission_id": mission_id,
            "path_id": str(mission.get("path_id") or "").strip() or None,
            "completed_at": ledger_completed_at,
            "stage_timings": {},
            "goal": _mission_text(mission.get("goal") or "", limit=240),
            "answer_hypothesis": _mission_text(mission.get("answer_hypothesis") or "", limit=520) or None,
            "expected_evidence_shape": expected_shape,
            "hot_cold_policy": _ledger_dict(mission.get("hot_cold_policy")),
            "landing_region_ref": mission.get("landing_region_ref"),
            "visited_node_ids": [],
            "traversed_edges": [],
            "route_events": [],
            "hot_evidence": [],
            "cold_evidence": [],
            "duplicate_evidence": [],
            "excluded_evidence": [],
            "document_refs": global_document_refs[:8] if bool(expected_shape.get("document_requested")) else [],
            "document_refs_seen": global_document_refs[:8] if bool(expected_shape.get("document_requested")) else [],
            "coverage_state": "missed",
            "coverage_reason": "path_mission_not_executed_by_runtime",
            "missing_reason": "path_mission_not_executed_by_runtime",
            "wrong_region_signal": {},
            "correction_signal": {
                "schema_version": "agvm.mission_correction_signal.v1",
                "state": "missed",
                "path_mission_id": mission_id,
                "expected_region_ref": mission.get("landing_region_ref"),
                "learning_use": "feed_heuristic_calibration_sleep_evolve_after_review",
                "needs_review": True,
            },
            "package_candidate_sections": _dedupe_limited(
                [
                    str(expected_shape.get("target_id") or ""),
                    str(expected_shape.get("answer_field") or ""),
                    _goal_to_slot(str(mission.get("goal") or "")),
                ],
                limit=8,
            ),
        }
        rows.append({key: value for key, value in row.items() if value not in (None, [], {})})
    if not rows and global_document_refs:
        target_text = _mission_text(document_evidence_lane.get("target_text") or query_text, limit=520)
        for ref_index, ref in enumerate(global_document_refs[:8], start=1):
            relationship = str(ref.get("relationship_to_query") or "related").strip() or "related"
            resolved_relationship = relationship in {"primary", "supporting"}
            coverage_state = "resolved" if resolved_relationship else "partially_resolved"
            coverage_reason = (
                "document_evidence_primary_or_supporting_ref_ranked_by_lane"
                if resolved_relationship
                else "document_evidence_related_ref_available"
            )
            doc_key = str(ref.get("document_id") or ref.get("anchor_node_id") or ref.get("title") or ref_index).strip()
            row = {
                "schema_version": MISSION_LEDGER_ROW_SCHEMA_VERSION,
                "mission_id": f"document_evidence::{doc_key}",
                "completed_at": ledger_completed_at,
                "goal": target_text or _mission_text(query_text, limit=240),
                "expected_evidence_shape": {
                    "schema_version": "agvm.document_evidence_expected_shape.v1",
                    "document_requested": True,
                    "target_id": target_text or _mission_text(query_text, limit=240),
                    "claim_shape": target_text or _mission_text(query_text, limit=240),
                },
                "visited_node_ids": _ledger_id_list(ref.get("anchor_node_id"), ref.get("document_id"), limit=8),
                "traversed_edges": [],
                "route_events": [],
                "hot_evidence": [],
                "cold_evidence": [],
                "duplicate_evidence": [],
                "excluded_evidence": [],
                "document_refs": [dict(ref)],
                "document_refs_seen": [dict(ref)],
                "document_evidence_row": True,
                "document_evidence_relationship": relationship,
                "coverage_state": coverage_state,
                "coverage_reason": coverage_reason,
                "missing_reason": None if coverage_state == "resolved" else coverage_reason,
                "correction_signal": {
                    "schema_version": "agvm.mission_correction_signal.v1",
                    "state": coverage_state,
                    "path_mission_id": f"document_evidence::{doc_key}",
                    "learning_use": "feed_document_evidence_ranking_review_without_raw_mining",
                    "needs_review": coverage_state != "resolved",
                },
                "package_candidate_sections": ["documents"],
                "accepted_by_ai_or_master": True,
            }
            rows.append({key: value for key, value in row.items() if value not in (None, [], {})})
    state_counts: dict[str, int] = {}
    for row in rows:
        state = str(row.get("coverage_state") or "unknown")
        state_counts[state] = state_counts.get(state, 0) + 1
    hot_count = sum(len(list(row.get("hot_evidence") or [])) for row in rows)
    cold_count = sum(len(list(row.get("cold_evidence") or [])) for row in rows)
    document_ref_count = len(
        {
            str(ref.get("document_id") or ref.get("title") or ref.get("anchor_node_id") or "")
            for row in rows
            for ref in list(row.get("document_refs") or [])
            if isinstance(ref, dict) and str(ref.get("document_id") or ref.get("title") or ref.get("anchor_node_id") or "").strip()
        }
    )
    status = "ready" if rows else ("blocked" if contract and not bool(contract.get("materialized")) else "empty")
    blockers: list[str] = []
    if contract and not bool(contract.get("materialized")):
        blockers.extend(_mission_strings(contract.get("blockers"), limit=12))
    if not rows:
        blockers.append("mission_ledger_rows_missing")
    revision_payload = {
        key: dict(revision_context or {}).get(key)
        for key in (
            "brain_revision",
            "matrix_revision",
            "metamemory_revision",
            "topology_revision",
            "atlas_revision",
            "calibration_revision",
            "source_replay_revision",
        )
        if dict(revision_context or {}).get(key) is not None
    }
    ledger_payload = {
        "schema_version": MISSION_EVIDENCE_LEDGER_SCHEMA_VERSION,
        "row_schema_version": MISSION_LEDGER_ROW_SCHEMA_VERSION,
        "status": status,
        "retrieval_mode": str(retrieval_mode or "balanced"),
        "revision_context": revision_payload,
        "brain_revision": revision_payload.get("brain_revision"),
        "matrix_revision": revision_payload.get("matrix_revision"),
        "metamemory_revision": revision_payload.get("metamemory_revision"),
        "topology_revision": revision_payload.get("topology_revision"),
        "atlas_revision": revision_payload.get("atlas_revision"),
        "calibration_revision": revision_payload.get("calibration_revision"),
        "source_replay_revision": revision_payload.get("source_replay_revision"),
        "mission_contract_schema_version": str(contract.get("schema_version") or "") or None,
        "mission_contract_status": str(contract.get("status") or "") or None,
        "mission_count": len(missions),
        "row_count": len(rows),
        "coverage_state_counts": state_counts,
        "resolved_count": state_counts.get("resolved", 0),
        "partial_count": state_counts.get("partially_resolved", 0),
        "near_miss_count": state_counts.get("near_miss", 0),
        "missed_count": state_counts.get("missed", 0),
        "hot_evidence_count": hot_count,
        "cold_evidence_count": cold_count,
        "document_ref_count": document_ref_count,
        "document_evidence_lane": {
            key: value
            for key, value in document_evidence_lane.items()
            if key != "documents"
        },
        "document_evidence_row_count": len([row for row in rows if bool(row.get("document_evidence_row"))]),
        "route_event_count": sum(len(list(row.get("route_events") or [])) for row in rows),
        "route_runtime": dict(route_runtime or {}),
        "renderer_contract": {
            "package_builder_should_use_ledger_only": True,
            "package_builder_must_not_mine_raw_text": True,
            "package_builder_rescue_required": False,
            "ledger_rows_available_before_package_render": True,
        },
        "master_inputs_ready": bool(rows),
        "blockers": _dedupe_limited(blockers, limit=12),
        "rows": rows[:24],
    }
    return apply_branch_autojudge_to_mission_ledger(
        ledger_payload,
        query_text=query_text,
        retrieval_mode=retrieval_mode,
        revision_context=revision_context,
        allow_ai_branch_controller=allow_ai_branch_controller,
    )


def _mission_learning_int(value: Any) -> int:
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _mission_learning_endpoint_hint(action: str | None) -> str | None:
    return {
        "sleep_preview": "/memory/mcp/sleep-preview",
        "evolve_preview": "/memory/mcp/evolve-preview",
        "matrix_calibration_preview": "/memory/mcp/matrix-calibration-preview",
        "grow_repair": "/memory/mcp/grow-source-preview",
        "inspect_path_corridor": "/memory/mcp/retrieve-path-corridor",
        "inspect_context_package": "/memory/mcp/inspect-context-package",
        "retrieve_document": "/memory/mcp/retrieve-document",
        "retry_retrieve_after_provider_recovers": "/memory/mcp/retrieve-context",
    }.get(str(action or "").strip())


def _mission_learning_action_for_family(family: str) -> str:
    family = str(family or "").strip()
    if family == "hot_cold_policy":
        return "sleep_preview"
    if family in {"geometry_or_matrix", "prompt_or_metamemory"}:
        return "matrix_calibration_preview"
    if family == "node_shape_or_link":
        return "evolve_preview"
    if family in {"grow_or_source", "document_delivery"}:
        return "grow_repair"
    if family == "provider_or_latency":
        return "retry_retrieve_after_provider_recovers"
    if family == "benchmark_policy":
        return "inspect_context_package"
    return "inspect_path_corridor"


def _mission_learning_add_signal(
    *,
    family_counts: dict[str, int],
    reason_counts: dict[str, int],
    samples: list[dict[str, Any]],
    family: str,
    reason: str,
    row: dict[str, Any] | None = None,
) -> None:
    family = str(family or "").strip()
    reason = str(reason or "").strip()
    if not family or not reason:
        return
    family_counts[family] = family_counts.get(family, 0) + 1
    reason_counts[reason] = reason_counts.get(reason, 0) + 1
    if row is not None and len(samples) < 16:
        correction = _ledger_dict(row.get("correction_signal"))
        samples.append(
            {
                "mission_id": row.get("mission_id"),
                "path_id": row.get("path_id"),
                "branch_id": row.get("branch_id"),
                "goal": _mission_text(row.get("goal") or "", limit=180),
                "coverage_state": row.get("coverage_state"),
                "coverage_reason": row.get("coverage_reason"),
                "family": family,
                "reason": reason,
                "expected_region_ref": row.get("landing_region_ref") or correction.get("expected_region_ref"),
                "observed_bucket_keys": _ledger_id_list(correction.get("observed_bucket_keys"), limit=8),
                "hot_evidence_count": len(_ledger_list(row.get("hot_evidence"))),
                "cold_evidence_count": len(_ledger_list(row.get("cold_evidence"))),
                "document_ref_count": len(_ledger_list(row.get("document_refs"))),
            }
        )


def _mission_learning_goal_key(row: dict[str, Any] | None = None, *, goal: Any = None) -> str:
    payload = _ledger_dict(row)
    expected_shape = _ledger_dict(payload.get("expected_evidence_shape"))
    normalized_goal = _fold_text(str(goal if goal is not None else payload.get("goal") or payload.get("mission_id") or ""))
    target = _fold_text(str(expected_shape.get("target_id") or ""))
    answer_field = _fold_text(str(expected_shape.get("answer_field") or ""))
    canonical_shape = _fold_text(
        str(
            expected_shape.get("claim_shape")
            or expected_shape.get("evidence_shape")
            or expected_shape.get("success_question")
            or payload.get("answer_hypothesis")
            or normalized_goal
        )
    )
    semantic_goal = canonical_shape or normalized_goal
    return "|".join(part for part in (target or answer_field, semantic_goal) if part)[:260]


def build_mission_learning_rollup(
    *,
    query_text: str,
    mission_evidence_ledger: dict[str, Any] | None,
    master_judgement: dict[str, Any] | None = None,
    package_render_contract: dict[str, Any] | None = None,
    path_truth_contract: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Convert the mission ledger into reviewable learning/health signals.

    This is intentionally a renderer/diagnostic layer: it does not search raw
    documents, does not create facts and does not mutate geometry.
    """

    ledger = _ledger_dict(mission_evidence_ledger)
    rows = [_ledger_dict(row) for row in _ledger_list(ledger.get("rows")) if _ledger_dict(row)]
    judgement = _ledger_dict(master_judgement)
    render_contract = _ledger_dict(package_render_contract)
    path_truth = _ledger_dict(path_truth_contract)
    family_counts: dict[str, int] = {}
    reason_counts: dict[str, int] = {}
    samples: list[dict[str, Any]] = []
    correction_priors: list[dict[str, Any]] = []
    bridge_candidates: list[dict[str, Any]] = []
    density_bucket_counts: dict[str, int] = {}
    active_edge_counts: dict[str, int] = {}
    provider_state = str(judgement.get("provider_state") or "").strip().lower()
    agent_payload_state = str(judgement.get("agent_payload_state") or "").strip().lower()
    selected_payload_reconciliation = bool(
        judgement.get("selected_payload_reconciliation")
        or str(judgement.get("source") or "").strip() == "selected_context_package_contract"
    )
    superseded_ledger_reason = str(judgement.get("superseded_ledger_reason") or "").strip()
    subsumed_goal_keys = {
        _mission_learning_goal_key(goal=goal)
        for goal in _ledger_list(judgement.get("subsumed_unresolved_goals"))
        if str(goal or "").strip()
    }
    subsumed_goal_texts = {
        _fold_text(str(goal or ""))
        for goal in _ledger_list(judgement.get("subsumed_unresolved_goals"))
        if str(goal or "").strip()
    }

    for row in rows:
        state = str(row.get("coverage_state") or "").strip().lower()
        branch_judgement = _ledger_dict(row.get("branch_judgement"))
        branch_state = str(branch_judgement.get("state") or "").strip().lower()
        expected_shape = _ledger_dict(row.get("expected_evidence_shape"))
        correction = _ledger_dict(row.get("correction_signal"))
        wrong_region = _ledger_dict(row.get("wrong_region_signal"))
        route_events = _ledger_list(row.get("route_events"))
        traversed_edges = _ledger_list(row.get("traversed_edges"))
        visited_node_ids = _ledger_id_list(row.get("visited_node_ids"), limit=64)
        observed_bucket_keys = _ledger_id_list(correction.get("observed_bucket_keys"), limit=16)
        hot_count = len(_ledger_list(row.get("hot_evidence")))
        cold_count = len(_ledger_list(row.get("cold_evidence")))
        duplicate_count = len(_ledger_list(row.get("duplicate_evidence")))
        excluded_count = len(_ledger_list(row.get("excluded_evidence")))
        document_ref_count = len(_ledger_list(row.get("document_refs")))
        document_requested = bool(expected_shape.get("document_requested"))
        selected_payload_superseded_empty_row = bool(
            selected_payload_reconciliation
            and state in {"missed", ""}
            and branch_state in {"", "stop", "needs_radius_widen"}
            and not (
                hot_count
                or cold_count
                or duplicate_count
                or excluded_count
                or document_ref_count
                or route_events
                or visited_node_ids
            )
        )
        duplicate_goal_subsumed_by_master = bool(
            (
                _mission_learning_goal_key(row) in subsumed_goal_keys
                or _fold_text(str(row.get("goal") or row.get("mission_id") or "")) in subsumed_goal_texts
            )
            and state in {"missed", ""}
            and branch_state in {"", "missed", "needs_radius_widen", "wrong_region"}
            and not (
                hot_count
                or cold_count
                or duplicate_count
                or excluded_count
                or document_ref_count
                or route_events
                or visited_node_ids
            )
        )

        for bucket_key in observed_bucket_keys:
            density_bucket_counts[bucket_key] = density_bucket_counts.get(bucket_key, 0) + 1
        for edge in traversed_edges:
            edge_payload = _ledger_dict(edge)
            edge_kind = str(edge_payload.get("kind") or edge_payload.get("edge_type") or edge_payload.get("source") or "route_edge").strip()
            if edge_kind:
                active_edge_counts[edge_kind] = active_edge_counts.get(edge_kind, 0) + 1

        if selected_payload_superseded_empty_row or duplicate_goal_subsumed_by_master:
            continue

        if state == "provider_degraded" or branch_state == "provider_degraded":
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="provider_or_latency",
                reason="provider_or_latency:mission_provider_degraded",
                row=row,
            )
        if state in {"near_miss", "wrong_region"} or branch_state == "wrong_region" or wrong_region:
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="geometry_or_matrix",
                reason="geometry_or_matrix:route_executed_without_expected_evidence",
                row=row,
            )
        elif branch_state == "needs_radius_widen":
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="geometry_or_matrix",
                reason="geometry_or_matrix:branch_autojudge_needs_radius_widen",
                row=row,
            )
        elif bool(correction.get("needs_review")) and (route_events or visited_node_ids) and not (hot_count or cold_count or document_ref_count):
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="geometry_or_matrix",
                reason="geometry_or_matrix:review_needed_after_empty_traversal",
                row=row,
            )
        if state == "missed" and not (route_events or visited_node_ids):
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="prompt_or_metamemory",
                reason="prompt_or_metamemory:mission_not_executed_or_unrouteable",
                row=row,
            )
        if cold_count and not hot_count:
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="hot_cold_policy",
                reason="hot_cold_policy:answer_material_found_cold_not_promoted",
                row=row,
            )
        if state == "duplicate_only" or branch_state == "duplicate_only" or (duplicate_count and not (hot_count or cold_count or document_ref_count)):
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="node_shape_or_link",
                reason="node_shape_or_link:duplicate_only_or_warm_reuse_without_new_evidence",
                row=row,
            )
        if document_requested and not document_ref_count:
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="document_delivery",
                reason="document_delivery:requested_document_without_actionable_ref",
                row=row,
            )
        if state == "forbidden" or excluded_count:
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="benchmark_policy",
                reason="benchmark_policy:forbidden_or_excluded_material_encountered",
                row=row,
            )
        if state == "missed" and document_requested and not document_ref_count:
            _mission_learning_add_signal(
                family_counts=family_counts,
                reason_counts=reason_counts,
                samples=samples,
                family="grow_or_source",
                reason="grow_or_source:source_or_document_gap_for_requested_mission",
                row=row,
            )

        if bool(correction.get("needs_review")) or wrong_region or branch_state in {"needs_radius_widen", "wrong_region"}:
            if len(correction_priors) < 16:
                correction_priors.append(
                    {
                        "mission_id": row.get("mission_id"),
                        "path_id": row.get("path_id"),
                        "goal": _mission_text(row.get("goal") or "", limit=180),
                        "coverage_state": state,
                        "expected_region_ref": row.get("landing_region_ref") or correction.get("expected_region_ref"),
                        "observed_bucket_keys": observed_bucket_keys[:8],
                        "snap_delta": row.get("snap_delta"),
                        "review_required": True,
                        "learning_use": "review_before_heuristic_prior_or_geometry_change",
                    }
                )
        if cold_count and not hot_count and len(bridge_candidates) < 12:
            bridge_candidates.append(
                {
                    "mission_id": row.get("mission_id"),
                    "path_id": row.get("path_id"),
                    "goal": _mission_text(row.get("goal") or "", limit=180),
                    "candidate_kind": "cold_to_hot_bridge_review",
                    "cold_evidence_count": cold_count,
                    "expected_region_ref": row.get("landing_region_ref") or correction.get("expected_region_ref"),
                    "observed_bucket_keys": observed_bucket_keys[:8],
                }
            )

    if selected_payload_reconciliation and superseded_ledger_reason:
        _mission_learning_add_signal(
            family_counts=family_counts,
            reason_counts=reason_counts,
            samples=samples,
            family="geometry_or_matrix",
            reason="geometry_or_matrix:selected_payload_superseded_nonexecuted_route_snapshot",
            row=None,
        )
    if provider_state == "degraded" or agent_payload_state == "provider_degraded":
        _mission_learning_add_signal(
            family_counts=family_counts,
            reason_counts=reason_counts,
            samples=samples,
            family="provider_or_latency",
            reason="provider_or_latency:master_judgement_provider_degraded",
            row=None,
        )
    missing_goals = [str(item) for item in _ledger_list(judgement.get("missing_goals")) if str(item).strip()]
    partial_goals = [str(item) for item in _ledger_list(judgement.get("partial_goals")) if str(item).strip()]
    if missing_goals and agent_payload_state not in {"no_match", "provider_degraded"}:
        _mission_learning_add_signal(
            family_counts=family_counts,
            reason_counts=reason_counts,
            samples=samples,
            family="prompt_or_metamemory",
            reason="prompt_or_metamemory:master_missing_goals_after_missions",
            row=None,
        )
    if partial_goals:
        _mission_learning_add_signal(
            family_counts=family_counts,
            reason_counts=reason_counts,
            samples=samples,
            family="hot_cold_policy",
            reason="hot_cold_policy:master_partial_goals_need_promotion_or_links",
            row=None,
        )
    path_ready = bool(path_truth.get("ready") or path_truth.get("all_planned_paths_accounted_for"))
    pending_paths = _mission_learning_int(path_truth.get("pending_path_count") or path_truth.get("pending"))
    if path_truth and not path_ready and pending_paths > 0:
        _mission_learning_add_signal(
            family_counts=family_counts,
            reason_counts=reason_counts,
            samples=samples,
            family="geometry_or_matrix",
            reason="geometry_or_matrix:path_truth_pending_after_package_render",
            row=None,
        )
    if render_contract and not bool(render_contract.get("source_is_ledger_only")) and not selected_payload_reconciliation:
        _mission_learning_add_signal(
            family_counts=family_counts,
            reason_counts=reason_counts,
            samples=samples,
            family="benchmark_policy",
            reason="benchmark_policy:package_renderer_not_ledger_only",
            row=None,
        )

    recommended_actions: list[dict[str, Any]] = []
    seen_actions: set[tuple[str, str]] = set()
    for family, count in sorted(family_counts.items()):
        action = _mission_learning_action_for_family(family)
        key = (family, action)
        if key in seen_actions:
            continue
        seen_actions.add(key)
        severity = "action_recommended" if count >= 2 or family in {"provider_or_latency", "document_delivery"} else "watch"
        recommended_actions.append(
            {
                "family": family,
                "action": action,
                "endpoint_hint": _mission_learning_endpoint_hint(action),
                "count": count,
                "severity": severity,
                "review_required": True,
                "hidden_mutation_allowed": False,
                "reason_code": f"{action}:mission_learning_{family}_{'repeated' if count >= 2 else 'observed'}",
            }
        )

    signal_count = sum(family_counts.values())
    if not rows:
        status = "empty"
    elif family_counts.get("provider_or_latency"):
        status = "provider_degraded"
    elif any(item.get("severity") == "action_recommended" for item in recommended_actions):
        status = "needs_review"
    elif signal_count:
        status = "watch"
    else:
        status = "healthy"
    rollup_basis = {
        "query": _mission_text(query_text, limit=240),
        "ledger_status": ledger.get("status"),
        "row_states": [row.get("coverage_state") for row in rows],
        "master_state": agent_payload_state,
        "families": family_counts,
    }
    rollup_id = "mission_learning::" + hashlib.sha256(
        json.dumps(rollup_basis, sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")
    ).hexdigest()[:16]
    sorted_density = sorted(density_bucket_counts.items(), key=lambda item: (-item[1], item[0]))[:12]
    return {
        "schema_version": MISSION_LEARNING_ROLLUP_SCHEMA_VERSION,
        "rollup_id": rollup_id,
        "status": status,
        "source": "mission_evidence_ledger",
        "query_text": _mission_text(query_text, limit=240),
        "mission_count": _mission_learning_int(ledger.get("mission_count")),
        "row_count": len(rows),
        "resolved_count": _mission_learning_int(ledger.get("resolved_count")),
        "partial_count": _mission_learning_int(ledger.get("partial_count")),
        "near_miss_count": _mission_learning_int(ledger.get("near_miss_count")),
        "missed_count": _mission_learning_int(ledger.get("missed_count")),
        "signal_count": signal_count,
        "family_counts": family_counts,
        "reason_counts": reason_counts,
        "recommended_actions": recommended_actions,
        "health_explanation": {
            "prompt_or_metamemory": family_counts.get("prompt_or_metamemory", 0),
            "geometry_or_matrix": family_counts.get("geometry_or_matrix", 0),
            "node_shape_or_link": family_counts.get("node_shape_or_link", 0),
            "grow_or_source": family_counts.get("grow_or_source", 0),
            "provider_or_latency": family_counts.get("provider_or_latency", 0),
            "benchmark_policy": family_counts.get("benchmark_policy", 0),
            "hot_cold_policy": family_counts.get("hot_cold_policy", 0),
            "document_delivery": family_counts.get("document_delivery", 0),
        },
        "topology_overlay_summary": {
            "schema_version": "agvm.topology_overlay_summary.v1",
            "source": "mission_learning_rollup",
            "applied": False,
            "review_required": bool(correction_priors or bridge_candidates),
            "density_lobes": [{"bucket_key": key, "signal_count": count} for key, count in sorted_density],
            "active_edge_counts": active_edge_counts,
            "correction_priors": correction_priors,
            "bridge_candidates": bridge_candidates,
            "personal_geometry_note": "review-only overlay; sleep/evolve/matrix calibration may apply later with rollback",
        },
        "samples": samples,
        "maintenance_policy": {
            "hidden_mutation_allowed": False,
            "requires_review_before_sleep_evolve_or_matrix_apply": True,
            "package_builder_may_not_rescue_missing_evidence": True,
            "heuristic_prior_activation": "only_after_repeated_reviewed_success",
        },
    }


def _planner_family_summary(
    *,
    probes: list[dict[str, Any]],
    branches: list[dict[str, Any]],
    family_plan_confidence: dict[str, float] | None = None,
) -> dict[str, dict[str, Any]]:
    summary: dict[str, dict[str, Any]] = {}
    for family in ("heuristic", "ai"):
        family_probes = [dict(probe) for probe in probes if _planner_family_for_probe(probe) == family]
        attributed_probes = [dict(probe) for probe in probes if _record_has_family(probe, family)]
        family_branches = [dict(branch) for branch in branches if str(branch.get("planner_family") or "").strip().lower() == family]
        attributed_branches = [dict(branch) for branch in branches if _record_has_family(branch, family)]
        dual_origin_branches = [dict(branch) for branch in attributed_branches if bool(branch.get("dual_origin"))]
        family_goals = sorted(
            {
                str(item).strip()
                for item in (
                    [probe.get("goal") for probe in attributed_probes]
                    + [branch.get("goal") for branch in attributed_branches]
                )
                if str(item).strip()
            }
        )
        visible_probes = attributed_probes or family_probes
        summary[family] = {
            "planner_family": family,
            "plan_id": _family_plan_id_for_family(family),
            "plan_confidence": round(
                max(
                    0.0,
                    min(
                        1.0,
                        float(
                            (family_plan_confidence or {}).get(family)
                            or max((float(probe.get("family_plan_confidence") or 0.0) for probe in visible_probes), default=0.0)
                        ),
                    ),
                ),
                4,
            ),
            "probe_count": len(visible_probes),
            "physical_probe_count": len(family_probes),
            "attributed_probe_count": len(attributed_probes),
            "branch_count": len(attributed_branches),
            "physical_branch_count": len(family_branches),
            "active_branch_count": sum(1 for branch in attributed_branches if str(branch.get("status") or "") == "active"),
            "dual_origin_branch_count": len(dual_origin_branches),
            "attributed_branch_count": len(attributed_branches),
            "goal_count": len(family_goals),
            "goals": family_goals,
            "route_step_count": sum(len(list(branch.get("route_trace") or [])) for branch in attributed_branches),
            "route_richness_score": round(
                sum(float(branch.get("route_richness_score") or 0.0) for branch in attributed_branches) / max(1, len(attributed_branches)),
                4,
            )
            if attributed_branches
            else 0.0,
            "probe_ids": [str(probe.get("probe_id") or "") for probe in visible_probes if str(probe.get("probe_id") or "").strip()][:12],
            "branch_ids": [str(branch.get("branch_id") or "") for branch in attributed_branches if str(branch.get("branch_id") or "").strip()][:12],
            "landing_labels": [str(probe.get("label") or "") for probe in visible_probes if str(probe.get("label") or "").strip()][:12],
        }
    return summary


def _planner_family_comparison(branches: list[dict[str, Any]]) -> dict[str, Any]:
    family_branches = {
        family: [dict(branch) for branch in branches if _record_has_family(branch, family)]
        for family in ("heuristic", "ai")
    }
    physical_family_branches = {
        family: [dict(branch) for branch in branches if str(branch.get("planner_family") or "").strip().lower() == family]
        for family in ("heuristic", "ai")
    }
    family_nodes = {
        family: {
            str(node_id)
            for branch in family_branch_rows
            for node_id in list(branch.get("evidence_node_ids") or [])
            if str(node_id).strip()
        }
        for family, family_branch_rows in family_branches.items()
    }
    family_goals = {
        family: {
            str(branch.get("goal") or "")
            for branch in family_branch_rows
            if str(branch.get("goal") or "").strip()
        }
        for family, family_branch_rows in family_branches.items()
    }
    overlap_nodes = sorted(family_nodes["heuristic"] & family_nodes["ai"])
    overlap_goals = sorted(family_goals["heuristic"] & family_goals["ai"])
    heuristic_only_goals = sorted(family_goals["heuristic"] - family_goals["ai"])
    ai_only_goals = sorted(family_goals["ai"] - family_goals["heuristic"])
    heuristic_yield = sum(float(branch.get("route_yield") or 0.0) for branch in family_branches["heuristic"])
    ai_yield = sum(float(branch.get("route_yield") or 0.0) for branch in family_branches["ai"])
    conflicts: list[dict[str, Any]] = []
    for left in family_branches["heuristic"]:
        left_destination_key = _destination_lease_key(left.get("active_destination") or {})
        for right in family_branches["ai"]:
            if str(left.get("branch_id") or "") == str(right.get("branch_id") or ""):
                continue
            right_destination_key = _destination_lease_key(right.get("active_destination") or {})
            shared_nodes = sorted(
                set(str(node_id) for node_id in list(left.get("evidence_node_ids") or []) if str(node_id).strip())
                & set(str(node_id) for node_id in list(right.get("evidence_node_ids") or []) if str(node_id).strip())
            )
            if left_destination_key and left_destination_key == right_destination_key:
                conflicts.append(
                    {
                        "type": "shared_destination",
                        "left_branch_id": str(left.get("branch_id") or ""),
                        "right_branch_id": str(right.get("branch_id") or ""),
                        "destination_key": left_destination_key,
                        "shared_node_ids": shared_nodes[:8],
                    }
                )
            elif len(shared_nodes) >= 2:
                conflicts.append(
                    {
                        "type": "shared_evidence",
                        "left_branch_id": str(left.get("branch_id") or ""),
                        "right_branch_id": str(right.get("branch_id") or ""),
                        "shared_node_ids": shared_nodes[:8],
                    }
                )
    overlap_ratio = round(len(overlap_nodes) / max(1, len(family_nodes["heuristic"] | family_nodes["ai"])), 6)
    divergence_ratio = round((len(heuristic_only_goals) + len(ai_only_goals)) / max(1, len(family_goals["heuristic"] | family_goals["ai"])), 6)
    return {
        "family_overlap": {
            "shared_node_ids": overlap_nodes[:16],
            "shared_goal_keys": overlap_goals[:12],
            "overlap_ratio": overlap_ratio,
        },
        "family_divergence": {
            "heuristic_only_goals": heuristic_only_goals[:12],
            "ai_only_goals": ai_only_goals[:12],
            "divergence_ratio": divergence_ratio,
        },
        "family_yield": {
            "heuristic": round(heuristic_yield, 6),
            "ai": round(ai_yield, 6),
        },
        "family_conflicts": conflicts[:12],
        "family_contribution_summary": {
            family: {
                "branch_count": len(physical_family_branches[family]),
                "physical_branch_count": len(physical_family_branches[family]),
                "dual_origin_branch_count": sum(1 for branch in family_branches[family] if bool(branch.get("dual_origin"))),
                "attributed_branch_count": len(family_branches[family]),
                "evidence_node_count": len(family_nodes[family]),
                "goal_count": len(family_goals[family]),
                "route_yield": round(sum(float(branch.get("route_yield") or 0.0) for branch in family_branches[family]), 6),
            }
            for family in ("heuristic", "ai")
        },
    }


def _branch_kind_for_probe(probe: dict[str, Any]) -> str:
    landing_basis = str(probe.get("landing_basis") or "")
    if landing_basis.startswith("llm"):
        return "llm_navigation"
    return "heuristic_navigation"


def _create_branch_from_probe(query: RetrieveRequest, probe: dict[str, Any]) -> dict[str, Any]:
    branch_id = f"branch_{probe['probe_id']}"
    worker_kind = _branch_kind_for_probe(probe)
    planner_family = _planner_family_for_probe(probe)
    family_plan_id = str(probe.get("family_plan_id") or _family_plan_id_for_family(planner_family))
    family_branch_id = str(probe.get("family_branch_id") or f"{planner_family}::{branch_id}")
    start_region = _region_descriptor_from_probe(probe)
    destination_queue = _normalize_destination_queue(
        spec_destinations=list(probe.get("destination_queue") or []),
        goal=str(probe.get("goal") or ""),
        probe_label=str(probe.get("label") or branch_id),
        fallback_guide_area=str(probe.get("expected_guide_area") or ""),
        fallback_memory_type=str(probe.get("expected_memory_type") or ""),
        fallback_radial_expectation=str(probe.get("radial_expectation") or "mid"),
        fallback_color_hex=str(((probe.get("semantic_color") or {}).get("hex")) or ""),
        fallback_bucket_keys=list(probe.get("target_bucket_keys") or []),
    )
    active_destination = dict(destination_queue[0]) if destination_queue else None
    semantic_destination_queue = [dict(item) for item in list(probe.get("semantic_destination_queue") or destination_queue)]
    execution_destination_queue = [dict(item) for item in list(destination_queue or semantic_destination_queue)]
    origin_families = _families_for_record(probe)
    source_probe_ids_by_family = {
        str(key).strip().lower(): str(value).strip()
        for key, value in dict(probe.get("source_probe_ids_by_family") or {}).items()
        if str(key).strip().lower() in {"heuristic", "ai"} and str(value).strip()
    }
    source_probe_ids_by_family.setdefault(planner_family, str(probe.get("probe_id") or "").strip())
    origin_destination_queues = {
        str(key).strip().lower(): [dict(item) for item in list(value or [])]
        for key, value in dict(probe.get("origin_destination_queues") or {}).items()
        if str(key).strip().lower() in {"heuristic", "ai"}
    }
    origin_destination_queues.setdefault(planner_family, [dict(item) for item in list(probe.get("family_destination_queue") or destination_queue)])
    branch = {
        "branch_id": branch_id,
        "strand_id": str(probe.get("strand_id") or "").strip() or None,
        "merge_outcome": probe.get("merge_outcome"),
        "dual_origin": bool(probe.get("dual_origin")),
        "origin_families": origin_families,
        "source_probe_ids_by_family": source_probe_ids_by_family,
        "semantic_destination_queue": semantic_destination_queue,
        "origin_destination_queues": origin_destination_queues,
        "ai_refinement_delta": dict(probe.get("ai_refinement_delta") or {}),
        "path_mission_id": _probe_path_mission_id(probe) or None,
        "mission_merge_state": dict(probe.get("mission_merge_state") or {}),
        "heuristic_provisional": bool(probe.get("heuristic_provisional")),
        "provisional_until_ai_spatial": bool(probe.get("provisional_until_ai_spatial")),
        "spatial_contract_status": str(probe.get("spatial_contract_status") or "").strip() or None,
        "spatial_snap": dict(probe.get("spatial_snap") or {}),
        "ai_spatial_path_id": str(probe.get("ai_spatial_path_id") or "").strip() or None,
        "ai_spatial_landing_region_ref": str(probe.get("ai_spatial_landing_region_ref") or "").strip() or None,
        "ai_spatial_landing_coordinate": dict(probe.get("ai_spatial_landing_coordinate") or {}) or None,
        "ai_spatial_bridge_targets": [str(item) for item in list(probe.get("ai_spatial_bridge_targets") or []) if str(item).strip()][:6],
        "ai_spatial_preferred_edges": [str(item) for item in list(probe.get("ai_spatial_preferred_edges") or []) if str(item).strip()][:8],
        "merge_score": probe.get("merge_score"),
        "merge_reasons": [str(item).strip() for item in list(probe.get("merge_reasons") or []) if str(item).strip()][:10],
        "merge_partner_branch_id": str(probe.get("merge_partner_branch_id") or "").strip() or None,
        "merge_resolution_reason": str(probe.get("merge_resolution_reason") or "").strip() or None,
        "family_branch_id": family_branch_id,
        "planner_family": planner_family,
        "family_plan_id": family_plan_id,
        "family_plan_confidence": round(float(probe.get("family_plan_confidence") or probe.get("branch_priority") or probe.get("weight") or 0.0), 4),
        "worker_id": branch_id,
        "worker_kind": worker_kind,
        "probe_ids": [probe["probe_id"]],
        "goal": probe["goal"],
        "status": "active",
        "success_criteria": {"min_confidence": probe["success_min_confidence"]},
        "budget": {
            "max_steps": min(query.max_steps, query.max_total_steps),
            "max_candidate_reads": query.max_candidates_per_step,
            "max_nearby_bundles": 2,
            "max_fulltexts": query.max_nodes_fulltext,
            "max_text_chars": max(
                200,
                min(query.max_total_text_chars, int(probe.get("max_text_chars") or query.max_total_text_chars)),
            ),
            "max_highway_hops": 1 if query.allow_highway_expansion else 0,
            "max_pattern_hops": 1 if query.allow_pattern_expansion else 0,
        },
        "search_radius": probe["search_radius"],
        "visited_node_ids": [],
        "visited_bucket_keys": [],
        "evidence_node_ids": [],
        "stop_reason": None,
        "answer_hypothesis": str(probe.get("answer_hypothesis") or "").strip() or None,
        "expected_answer_field": str(probe.get("expected_answer_field") or _expected_answer_field_for_goal(str(probe.get("goal") or ""))).strip() or None,
        "corroboration_needs": list(probe.get("corroboration_needs") or []),
        "branch_priority": round(float(probe.get("branch_priority") or probe.get("weight") or 0.5), 4),
        "expected_stop_condition": str(probe.get("expected_stop_condition") or "").strip() or None,
        "start_region": start_region,
        "current_region": dict(start_region),
        "current_node_id": None,
        "destination_queue": destination_queue,
        "execution_destination_queue": execution_destination_queue,
        "destination_execution_index": 0,
        "destination_reorder_reason": None,
        "destination_reorder_history": [],
        "destination_resolution": {},
        "family_destination_queue": [dict(item) for item in semantic_destination_queue],
        "active_destination": active_destination,
        "route_state": "landing",
        "route_yield": 0.0,
        "visited_edge_refs": [],
        "traversed_nodes": [],
        "traversed_edges": [],
        "route_trace": [],
        "move_types": [],
        "destination_progress": {
            "reached_destination_ids": [],
            "remaining_destination_ids": [str(item.get("destination_id") or "") for item in destination_queue if str(item.get("destination_id") or "")],
        },
        "route_preference_prior": dict(probe.get("route_preference_prior") or {}),
        "crowding_penalty_factor": float(probe.get("crowding_penalty_factor") or 1.0),
        "calibration_scope_keys": [str(item) for item in list(probe.get("calibration_scope_keys") or []) if str(item).strip()],
        "calibration_applied": bool(probe.get("calibration_applied")),
        "highway_hops_taken": 0,
        "link_hops_taken": 0,
        "local_hops_taken": 0,
        "highway_traversed_count": 0,
        "link_traversed_count": 0,
        "local_traversed_count": 0,
        "considered_highway_count": 0,
        "studied_node_count": 0,
        "hydrated_node_count": 0,
        "route_richness_score": 0.0,
        "covered_slots": [],
        "local_stop_recommendation": None,
        "controller_kind": "fallback_branch_controller",
        "controller_recommendation": {
            "action": "continue_current_route",
            "reason": f"begin from landing for {str(probe.get('goal') or 'goal')}",
            "confidence": 0.52,
            "target_destination_id": str((active_destination or {}).get("destination_id") or "") or None,
            "requested_actions": ["inspect_bucket"],
            "decision_source": "fallback_disabled",
            "controller_kind": "fallback_branch_controller",
            "turn_ms": 0.0,
            "evidence_basis": [f"goal:{str(probe.get('goal') or '')}".strip(":")],
            "fallback_preview_action": "continue_current_route",
            "override_applied": False,
        },
        "controller_confidence": 0.52,
        "controller_reason": f"begin from landing for {str(probe.get('goal') or 'goal')}",
        "controller_turn_ms": 0.0,
        "controller_evidence_basis": [f"goal:{str(probe.get('goal') or '')}".strip(":")],
        "controller_decision_source": "fallback_disabled",
        "controller_fallback_reason": "disabled",
        "controller_escalation_needed": False,
        "controller_escalation_reason": None,
        "controller_requested_master_action": "continue",
        "controller_blocking_destination_id": str((active_destination or {}).get("destination_id") or "") or None,
        "controller_blocking_state": "landing",
        "last_round_index": 0,
        "lifecycle_stage": "landing",
        "family_contribution_summary": {
            "planner_family": planner_family,
            "evidence_node_count": 0,
            "route_yield": 0.0,
            "covered_slot_count": 0,
        },
    }
    _ensure_branch_destination_resolution(branch, round_index=0)
    if active_destination:
        _set_destination_resolution_state(
            branch,
            active_destination,
            state="active",
            state_reason="initial_landing",
            round_index=0,
            execution_index=0,
        )
    return branch


def _merge_planner_probes(
    *,
    query: RetrieveRequest,
    current_probes: list[dict[str, Any]],
    current_branches: list[dict[str, Any]],
    new_probes: list[dict[str, Any]],
    atlas_payload: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, list[dict[str, Any]]], int, dict[str, Any]]:
    merged = [dict(probe) for probe in current_probes]
    branch_by_probe_id = {
        str((branch.get("probe_ids") or [""])[0] or ""): dict(branch)
        for branch in current_branches
        if str((branch.get("probe_ids") or [""])[0] or "")
    }
    probe_id_to_index = {
        str(probe.get("probe_id") or ""): index
        for index, probe in enumerate(merged)
        if str(probe.get("probe_id") or "")
    }
    added = 0
    heuristic_landing_count = sum(1 for probe in merged if _planner_family_for_probe(probe) == "heuristic")
    ai_mission_ids = {
        _probe_path_mission_id(probe) or str(probe.get("probe_id") or "").strip()
        for probe in list(new_probes or [])
        if isinstance(probe, dict) and _planner_family_for_probe(probe) == "ai"
    }
    ai_mission_ids.discard("")
    merge_summary = {
        "schema_version": MISSION_AWARE_MERGE_SCHEMA_VERSION,
        "branch_reuse_count": 0,
        "branch_enrich_count": 0,
        "branch_fork_count": 0,
        "dual_origin_branch_count": 0,
        "merge_resolution_histogram": {"reuse_branch": 0, "enrich_branch": 0, "fork_new_branch": 0},
        "merged_strand_ids": [],
        "enriched_strand_ids": [],
        "forked_strand_ids": [],
        "heuristic_landing_count": heuristic_landing_count,
        "ai_mission_count": len(ai_mission_ids),
        "ai_probe_count": sum(1 for probe in list(new_probes or []) if isinstance(probe, dict) and _planner_family_for_probe(probe) == "ai"),
        "mission_overlap_count": 0,
        "mission_divergence_count": 0,
        "dropped_ai_mission_count": 0,
        "mission_merge_rows": [],
        "learning_signals": [],
        "certification": {
            "heuristic_only_certification_allowed": False,
            "ai_mission_required": True,
            "state": "ai_missions_present" if ai_mission_ids else "partial_until_ai_mission",
            "blockers": [] if ai_mission_ids else ["ai_mission_missing"],
        },
    }
    for ai_probe in list(new_probes or []):
        ai_family = _planner_family_for_probe(ai_probe)
        if ai_family != "ai":
            if len(merged) >= int(query.max_total_branches):
                continue
            merged.append(dict(ai_probe))
            added += 1
            continue
        candidates: list[tuple[float, list[str], dict[str, float], dict[str, Any], str]] = []
        for heuristic_probe in merged:
            if _planner_family_for_probe(heuristic_probe) != "heuristic":
                continue
            basis = _probe_merge_basis(ai_probe, heuristic_probe)
            if not basis:
                continue
            merge_score, merge_reasons, components = _probe_merge_similarity(ai_probe, heuristic_probe)
            mission_bonus, mission_reasons = _mission_merge_score_bonus(
                ai_probe,
                heuristic_probe,
                basis=basis,
                components=components,
            )
            if mission_bonus:
                components["mission_overlap_bonus"] = mission_bonus
                merge_score = round(min(1.0, float(merge_score) + mission_bonus), 6)
                merge_reasons = list(dict.fromkeys([*merge_reasons, *mission_reasons]))
            candidates.append((merge_score, merge_reasons, components, heuristic_probe, basis))
        best_candidate = max(candidates, key=lambda item: item[0], default=None)
        if best_candidate is None or best_candidate[0] < 0.55:
            if len(merged) >= int(query.max_total_branches):
                merge_summary["dropped_ai_mission_count"] += 1
                merge_summary["learning_signals"].append(
                    _mission_merge_learning_signal(
                        ai_probe=ai_probe,
                        outcome="dropped_ai_mission",
                        reason="branch_capacity_exhausted_after_reserved_slots",
                        best_score=float(best_candidate[0]) if best_candidate else 0.0,
                        heuristic_probe=dict(best_candidate[3]) if best_candidate else None,
                    )
                )
                continue
            forked_probe = dict(ai_probe)
            forked_probe["merge_outcome"] = "fork_new_branch"
            forked_probe["dual_origin"] = False
            forked_probe["origin_families"] = ["ai"]
            forked_probe["semantic_destination_queue"] = [dict(item) for item in list(forked_probe.get("destination_queue") or [])]
            forked_probe["origin_destination_queues"] = {"ai": [dict(item) for item in list(forked_probe.get("destination_queue") or [])]}
            forked_probe["source_probe_ids_by_family"] = {"ai": str(forked_probe.get("probe_id") or "").strip()}
            forked_probe["merge_score"] = round(float(best_candidate[0]) if best_candidate else 0.0, 6) if best_candidate else 0.0
            forked_probe["merge_reasons"] = list(best_candidate[1]) if best_candidate else ["no_compatible_heuristic_branch"]
            merged.append(forked_probe)
            added += 1
            merge_summary["branch_fork_count"] += 1
            merge_summary["merge_resolution_histogram"]["fork_new_branch"] += 1
            strand_id = str(forked_probe.get("strand_id") or "").strip()
            if strand_id:
                merge_summary["forked_strand_ids"].append(strand_id)
            merge_summary["mission_divergence_count"] += 1
            merge_summary["mission_merge_rows"].append(
                {
                    "path_mission_id": _probe_path_mission_id(forked_probe) or None,
                    "ai_probe_id": str(forked_probe.get("probe_id") or "").strip() or None,
                    "heuristic_probe_id": str((best_candidate[3] if best_candidate else {}).get("probe_id") or "").strip() or None,
                    "outcome": "fork_new_branch",
                    "overlap": False,
                    "divergence": True,
                    "merge_score": forked_probe["merge_score"],
                    "reason": "below_merge_threshold" if best_candidate else "no_compatible_heuristic_branch",
                }
            )
            merge_summary["learning_signals"].append(
                _mission_merge_learning_signal(
                    ai_probe=forked_probe,
                    outcome="fork_new_branch",
                    reason="below_merge_threshold" if best_candidate else "no_compatible_heuristic_branch",
                    best_score=float(best_candidate[0]) if best_candidate else 0.0,
                    heuristic_probe=dict(best_candidate[3]) if best_candidate else None,
                )
            )
            continue
        merge_score, merge_reasons, components, heuristic_probe, basis = best_candidate
        material_delta, ai_delta, delta_reasons = _ai_refinement_delta(
            heuristic_probe,
            ai_probe,
            components=components,
        )
        if basis not in {"strand_id", "answer_field"}:
            material_delta = True
            delta_reasons = list(delta_reasons) + ["goal_only_match_requires_fork"]
        if merge_score >= 0.82 and not material_delta and basis in {"strand_id", "answer_field"}:
            outcome = "reuse_branch"
        elif basis in {"strand_id", "answer_field"}:
            outcome = "enrich_branch"
        else:
            outcome = "fork_new_branch"
        if outcome == "fork_new_branch":
            if len(merged) >= int(query.max_total_branches):
                merge_summary["dropped_ai_mission_count"] += 1
                merge_summary["learning_signals"].append(
                    _mission_merge_learning_signal(
                        ai_probe=ai_probe,
                        outcome="dropped_ai_mission",
                        reason="branch_capacity_exhausted_after_ai_fork_required",
                        best_score=float(merge_score),
                        heuristic_probe=heuristic_probe,
                    )
                )
                continue
            forked_probe = dict(ai_probe)
            forked_probe["merge_outcome"] = "fork_new_branch"
            forked_probe["dual_origin"] = False
            forked_probe["origin_families"] = ["ai"]
            forked_probe["semantic_destination_queue"] = [dict(item) for item in list(forked_probe.get("destination_queue") or [])]
            forked_probe["origin_destination_queues"] = {"ai": [dict(item) for item in list(forked_probe.get("destination_queue") or [])]}
            forked_probe["source_probe_ids_by_family"] = {"ai": str(forked_probe.get("probe_id") or "").strip()}
            forked_probe["merge_score"] = merge_score
            forked_probe["merge_reasons"] = list(dict.fromkeys([*merge_reasons, *delta_reasons]))
            merged.append(forked_probe)
            added += 1
            merge_summary["branch_fork_count"] += 1
            merge_summary["merge_resolution_histogram"]["fork_new_branch"] += 1
            strand_id = str(forked_probe.get("strand_id") or "").strip()
            if strand_id:
                merge_summary["forked_strand_ids"].append(strand_id)
            merge_summary["mission_divergence_count"] += 1
            merge_summary["mission_merge_rows"].append(
                {
                    "path_mission_id": _probe_path_mission_id(forked_probe) or None,
                    "ai_probe_id": str(forked_probe.get("probe_id") or "").strip() or None,
                    "heuristic_probe_id": str(heuristic_probe.get("probe_id") or "").strip() or None,
                    "outcome": "fork_new_branch",
                    "overlap": False,
                    "divergence": True,
                    "merge_score": round(float(merge_score), 6),
                    "reason": "mission_requires_distinct_route",
                }
            )
            merge_summary["learning_signals"].append(
                _mission_merge_learning_signal(
                    ai_probe=forked_probe,
                    outcome="fork_new_branch",
                    reason="mission_requires_distinct_route",
                    best_score=float(merge_score),
                    heuristic_probe=heuristic_probe,
                )
            )
            continue
        heuristic_probe_id = str(heuristic_probe.get("probe_id") or "")
        heuristic_index = probe_id_to_index.get(heuristic_probe_id)
        if heuristic_index is None:
            continue
        updated_probe = dict(merged[heuristic_index])
        heuristic_queue = [dict(item) for item in list(updated_probe.get("destination_queue") or [])]
        ai_queue = [dict(item) for item in list(ai_probe.get("destination_queue") or [])]
        semantic_destination_queue, appended_destinations = _merge_semantic_destination_queue(heuristic_queue, ai_queue)
        source_probe_ids_by_family = {
            str(key).strip().lower(): str(value).strip()
            for key, value in dict(updated_probe.get("source_probe_ids_by_family") or {}).items()
            if str(key).strip().lower() in {"heuristic", "ai"} and str(value).strip()
        }
        source_probe_ids_by_family.setdefault("heuristic", heuristic_probe_id)
        source_probe_ids_by_family["ai"] = str(ai_probe.get("probe_id") or "").strip()
        origin_destination_queues = {
            str(key).strip().lower(): [dict(item) for item in list(value or [])]
            for key, value in dict(updated_probe.get("origin_destination_queues") or {}).items()
            if str(key).strip().lower() in {"heuristic", "ai"}
        }
        origin_destination_queues.setdefault("heuristic", [dict(item) for item in heuristic_queue])
        origin_destination_queues["ai"] = [dict(item) for item in ai_queue]
        updated_probe["merge_outcome"] = outcome
        updated_probe["dual_origin"] = True
        updated_probe["origin_families"] = ["heuristic", "ai"]
        updated_probe["source_probe_ids_by_family"] = source_probe_ids_by_family
        updated_probe["semantic_destination_queue"] = semantic_destination_queue
        updated_probe["origin_destination_queues"] = origin_destination_queues
        for ai_spatial_key in (
            "path_mission_id",
            "spatial_snap",
            "ai_spatial_path_id",
            "ai_spatial_strand_id",
            "ai_spatial_landing_region_ref",
            "ai_spatial_landing_coordinate",
            "ai_spatial_waypoints",
            "ai_spatial_bridge_targets",
            "ai_spatial_preferred_edges",
            "ai_spatial_stop_condition",
            "ai_spatial_rationale",
        ):
            ai_value = ai_probe.get(ai_spatial_key)
            if ai_value not in (None, "", [], {}):
                updated_probe[ai_spatial_key] = ai_value
        updated_probe["landing_basis"] = str(updated_probe.get("landing_basis") or "inverse_like_estimation")
        updated_probe["ai_landing_basis"] = str(ai_probe.get("landing_basis") or "llm::ai_spatial_contract")
        updated_probe["merge_score"] = merge_score
        updated_probe["merge_reasons"] = list(dict.fromkeys([f"basis:{basis}", *merge_reasons, *delta_reasons]))
        updated_probe["mission_merge_state"] = {
            "schema_version": "agvm.probe_mission_merge_state.v1",
            "path_mission_id": _probe_path_mission_id(ai_probe) or None,
            "basis": basis,
            "outcome": outcome,
            "merge_score": round(float(merge_score), 6),
            "mission_overlap": True,
            "mission_divergence": False,
            "score_components": dict(components),
        }
        updated_probe["family_destination_queue"] = [dict(item) for item in semantic_destination_queue]
        updated_probe["merge_partner_branch_id"] = None
        updated_probe["merge_resolution_reason"] = outcome
        if outcome == "enrich_branch":
            for key in ("answer_hypothesis", "expected_answer_field", "expected_stop_condition"):
                ai_value = str(ai_probe.get(key) or "").strip()
                if ai_value:
                    updated_probe[key] = ai_value
            updated_probe["corroboration_needs"] = list(
                dict.fromkeys(
                    [
                        *(str(item).strip() for item in list(updated_probe.get("corroboration_needs") or []) if str(item).strip()),
                        *(str(item).strip() for item in list(ai_probe.get("corroboration_needs") or []) if str(item).strip()),
                    ]
                )
            )[:6]
            updated_probe["branch_priority"] = round(float(ai_probe.get("branch_priority") or updated_probe.get("branch_priority") or 0.0), 4)
            updated_probe["destination_queue"] = [dict(item) for item in semantic_destination_queue]
            updated_probe["ai_refinement_delta"] = {
                **dict(ai_delta),
                "appended_destination_count": len(appended_destinations),
            }
            merge_summary["branch_enrich_count"] += 1
            merge_summary["merge_resolution_histogram"]["enrich_branch"] += 1
            strand_id = str(updated_probe.get("strand_id") or "").strip()
            if strand_id:
                merge_summary["enriched_strand_ids"].append(strand_id)
        else:
            updated_probe["ai_refinement_delta"] = {}
            updated_probe["destination_queue"] = [dict(item) for item in heuristic_queue]
            merge_summary["branch_reuse_count"] += 1
            merge_summary["merge_resolution_histogram"]["reuse_branch"] += 1
            strand_id = str(updated_probe.get("strand_id") or "").strip()
            if strand_id:
                merge_summary["merged_strand_ids"].append(strand_id)
        merge_summary["mission_overlap_count"] += 1
        merge_summary["mission_merge_rows"].append(
            {
                "path_mission_id": _probe_path_mission_id(ai_probe) or None,
                "ai_probe_id": str(ai_probe.get("probe_id") or "").strip() or None,
                "heuristic_probe_id": heuristic_probe_id or None,
                "outcome": outcome,
                "overlap": True,
                "divergence": False,
                "merge_score": round(float(merge_score), 6),
                "reason": f"basis:{basis}",
            }
        )
        merged[heuristic_index] = updated_probe
    atlas_shortlists = _apply_probe_shortlists(merged, query, atlas_payload)
    branches = []
    for probe in merged:
        existing_branch = branch_by_probe_id.get(str(probe["probe_id"]))
        if existing_branch:
            existing_branch["search_radius"] = probe["search_radius"]
            existing_branch["worker_kind"] = existing_branch.get("worker_kind") or _branch_kind_for_probe(probe)
            existing_branch["planner_family"] = str(existing_branch.get("planner_family") or _planner_family_for_probe(probe))
            existing_branch["family_plan_id"] = str(existing_branch.get("family_plan_id") or probe.get("family_plan_id") or _family_plan_id_for_family(_planner_family_for_probe(probe)))
            existing_branch["family_plan_confidence"] = round(float(probe.get("family_plan_confidence") or existing_branch.get("family_plan_confidence") or probe.get("branch_priority") or 0.0), 4)
            existing_branch["family_branch_id"] = str(existing_branch.get("family_branch_id") or probe.get("family_branch_id") or f"{_planner_family_for_probe(probe)}::{existing_branch.get('branch_id') or probe['probe_id']}")
            existing_branch["merge_outcome"] = probe.get("merge_outcome")
            existing_branch["dual_origin"] = bool(probe.get("dual_origin"))
            existing_branch["origin_families"] = _families_for_record(probe)
            existing_branch["source_probe_ids_by_family"] = {
                str(key).strip().lower(): str(value).strip()
                for key, value in dict(probe.get("source_probe_ids_by_family") or {}).items()
                if str(key).strip().lower() in {"heuristic", "ai"} and str(value).strip()
            }
            existing_branch["semantic_destination_queue"] = [dict(item) for item in list(probe.get("semantic_destination_queue") or probe.get("destination_queue") or [])]
            existing_branch["origin_destination_queues"] = {
                str(key).strip().lower(): [dict(item) for item in list(value or [])]
                for key, value in dict(probe.get("origin_destination_queues") or {}).items()
                if str(key).strip().lower() in {"heuristic", "ai"}
            }
            existing_branch["ai_refinement_delta"] = dict(probe.get("ai_refinement_delta") or {})
            existing_branch["path_mission_id"] = _probe_path_mission_id(probe) or None
            existing_branch["mission_merge_state"] = dict(probe.get("mission_merge_state") or {})
            existing_branch["heuristic_provisional"] = bool(probe.get("heuristic_provisional"))
            existing_branch["provisional_until_ai_spatial"] = bool(probe.get("provisional_until_ai_spatial"))
            existing_branch["spatial_contract_status"] = str(probe.get("spatial_contract_status") or "").strip() or None
            existing_branch["spatial_snap"] = dict(probe.get("spatial_snap") or {})
            existing_branch["ai_spatial_path_id"] = str(probe.get("ai_spatial_path_id") or "").strip() or None
            existing_branch["ai_spatial_landing_region_ref"] = str(probe.get("ai_spatial_landing_region_ref") or "").strip() or None
            existing_branch["ai_spatial_landing_coordinate"] = dict(probe.get("ai_spatial_landing_coordinate") or {}) or None
            existing_branch["ai_spatial_bridge_targets"] = [str(item) for item in list(probe.get("ai_spatial_bridge_targets") or []) if str(item).strip()][:6]
            existing_branch["ai_spatial_preferred_edges"] = [str(item) for item in list(probe.get("ai_spatial_preferred_edges") or []) if str(item).strip()][:8]
            existing_branch["merge_score"] = probe.get("merge_score")
            existing_branch["merge_reasons"] = [str(item).strip() for item in list(probe.get("merge_reasons") or []) if str(item).strip()][:10]
            existing_branch["merge_resolution_reason"] = str(probe.get("merge_resolution_reason") or existing_branch.get("merge_resolution_reason") or probe.get("merge_outcome") or "").strip() or None
            existing_branch["answer_hypothesis"] = str(probe.get("answer_hypothesis") or existing_branch.get("answer_hypothesis") or "").strip() or None
            existing_branch["expected_answer_field"] = str(probe.get("expected_answer_field") or existing_branch.get("expected_answer_field") or "").strip() or None
            existing_branch["corroboration_needs"] = list(probe.get("corroboration_needs") or existing_branch.get("corroboration_needs") or [])
            existing_branch["branch_priority"] = round(float(probe.get("branch_priority") or existing_branch.get("branch_priority") or probe.get("weight") or 0.5), 4)
            existing_branch["expected_stop_condition"] = str(probe.get("expected_stop_condition") or existing_branch.get("expected_stop_condition") or "").strip() or None
            existing_branch["start_region"] = _region_descriptor_from_probe(probe)
            destination_queue = _normalize_destination_queue(
                spec_destinations=list(probe.get("destination_queue") or existing_branch.get("destination_queue") or []),
                goal=str(probe.get("goal") or existing_branch.get("goal") or ""),
                probe_label=str(probe.get("label") or existing_branch.get("branch_id") or "landing"),
                fallback_guide_area=str(probe.get("expected_guide_area") or ""),
                fallback_memory_type=str(probe.get("expected_memory_type") or ""),
                fallback_radial_expectation=str(probe.get("radial_expectation") or "mid"),
                fallback_color_hex=str(((probe.get("semantic_color") or {}).get("hex")) or ""),
                fallback_bucket_keys=list(probe.get("target_bucket_keys") or []),
            )
            semantic_destination_queue = [dict(item) for item in list(probe.get("semantic_destination_queue") or destination_queue)]
            existing_branch["destination_queue"] = semantic_destination_queue if probe.get("merge_outcome") == "enrich_branch" else destination_queue
            existing_branch["semantic_destination_queue"] = semantic_destination_queue
            existing_branch["family_destination_queue"] = [dict(item) for item in semantic_destination_queue]
            execution_destination_queue = [dict(item) for item in list(existing_branch.get("execution_destination_queue") or []) if isinstance(item, dict)]
            if not execution_destination_queue:
                execution_destination_queue = [dict(item) for item in semantic_destination_queue]
            else:
                execution_destination_queue = [
                    dict(item)
                    for item in execution_destination_queue
                    if _destination_semantic_index(semantic_destination_queue, item) is not None
                ]
                execution_keys = {_destination_identity(item) for item in execution_destination_queue}
                for semantic_item in semantic_destination_queue:
                    if _destination_identity(semantic_item) not in execution_keys:
                        execution_destination_queue.append(dict(semantic_item))
            existing_branch["execution_destination_queue"] = execution_destination_queue
            existing_branch["destination_execution_index"] = min(
                int(existing_branch.get("destination_execution_index") or 0),
                max(0, len(execution_destination_queue) - 1),
            )
            existing_branch["destination_reorder_reason"] = str(existing_branch.get("destination_reorder_reason") or "").strip() or None
            existing_branch["destination_reorder_history"] = [dict(item) for item in list(existing_branch.get("destination_reorder_history") or [])[:12]]
            existing_branch["destination_resolution"] = _clone_destination_resolution(existing_branch.get("destination_resolution"))
            existing_round_index = int(existing_branch.get("last_round_index") or 0)
            _ensure_branch_destination_resolution(existing_branch, round_index=existing_round_index)
            active_destination = dict(existing_branch.get("active_destination") or {})
            if not active_destination and execution_destination_queue:
                active_destination = dict(existing_branch["execution_destination_queue"][existing_branch["destination_execution_index"]] or {})
                existing_branch["active_destination"] = active_destination
            if active_destination:
                _set_destination_resolution_state(
                    existing_branch,
                    active_destination,
                    state="active",
                    state_reason="planner_merge_refresh",
                    round_index=existing_round_index,
                    execution_index=int(existing_branch.get("destination_execution_index") or 0),
                )
            existing_branch["merge_partner_branch_id"] = str(existing_branch.get("merge_partner_branch_id") or "").strip() or None
            existing_branch["current_region"] = dict(existing_branch.get("current_region") or existing_branch.get("start_region") or _region_descriptor_from_probe(probe))
            existing_branch["route_trace"] = [dict(item) for item in list(existing_branch.get("route_trace") or [])[:24]]
            branches.append(existing_branch)
        else:
            branches.append(_create_branch_from_probe(query, probe))
    merge_summary.update(_merge_runtime_summary(branches))
    merge_summary["merged_strand_ids"] = sorted(set(str(item).strip() for item in list(merge_summary.get("merged_strand_ids") or []) if str(item).strip()))
    merge_summary["enriched_strand_ids"] = sorted(set(str(item).strip() for item in list(merge_summary.get("enriched_strand_ids") or []) if str(item).strip()))
    merge_summary["forked_strand_ids"] = sorted(set(str(item).strip() for item in list(merge_summary.get("forked_strand_ids") or []) if str(item).strip()))
    blockers: list[str] = []
    if not ai_mission_ids:
        blockers.append("ai_mission_missing")
    if int(merge_summary.get("dropped_ai_mission_count") or 0) > 0:
        blockers.append("ai_mission_dropped_by_capacity")
    if ai_mission_ids and not list(merge_summary.get("mission_merge_rows") or []):
        blockers.append("ai_mission_not_merged")
    certification_state = (
        "ai_mission_merged"
        if ai_mission_ids and not blockers
        else "partial_until_ai_mission"
    )
    merge_summary["certification"] = {
        **dict(merge_summary.get("certification") or {}),
        "heuristic_only_certification_allowed": False,
        "ai_mission_required": True,
        "state": certification_state,
        "blockers": blockers,
    }
    merge_summary["mission_merge_row_count"] = len(list(merge_summary.get("mission_merge_rows") or []))
    merge_summary["learning_signal_count"] = len(list(merge_summary.get("learning_signals") or []))
    return merged, branches, atlas_shortlists, added, merge_summary


def _mission_aware_merge_runtime_summary(
    *,
    merge_summary: dict[str, Any],
    probes: list[dict[str, Any]],
    branches: list[dict[str, Any]],
    path_mission_contract: dict[str, Any],
    ai_spatial_landing_contract: dict[str, Any],
    capacity_reservation: dict[str, Any],
    semantic_contract_runtime: dict[str, Any] | None = None,
) -> dict[str, Any]:
    summary = dict(merge_summary or {})
    missions = [dict(item) for item in list(dict(path_mission_contract or {}).get("path_missions") or []) if isinstance(item, dict)]
    mission_ids = {
        str(mission.get("mission_id") or "").strip()
        for mission in missions
        if str(mission.get("mission_id") or "").strip()
    }
    probe_mission_ids = {
        _probe_path_mission_id(probe)
        for probe in list(probes or [])
        if isinstance(probe, dict) and _probe_path_mission_id(probe)
    }
    branch_mission_ids = {
        str(branch.get("path_mission_id") or "").strip()
        for branch in list(branches or [])
        if isinstance(branch, dict) and str(branch.get("path_mission_id") or "").strip()
    }
    all_mission_ids = mission_ids | probe_mission_ids | branch_mission_ids
    ai_contract = dict(ai_spatial_landing_contract or {})
    semantic_runtime = dict(semantic_contract_runtime or {})
    capacity = dict(capacity_reservation or {})
    heuristic_count = sum(1 for probe in list(probes or []) if isinstance(probe, dict) and _record_has_family(probe, "heuristic"))
    ai_probe_count = sum(1 for probe in list(probes or []) if isinstance(probe, dict) and _planner_family_for_probe(probe) == "ai")
    dual_count = sum(1 for branch in list(branches or []) if isinstance(branch, dict) and bool(branch.get("dual_origin")))
    blockers = list(dict(summary.get("certification") or {}).get("blockers") or [])
    if not all_mission_ids and not bool(ai_contract.get("materialized")):
        blockers.append("ai_mission_missing")
    if bool(ai_contract.get("materialized")) and not bool(ai_contract.get("certifiable")):
        blockers.append("ai_spatial_not_certifiable")
    if int(capacity.get("dropped_heuristic_probe_count") or 0) > 0:
        summary["dropped_heuristic_probe_count"] = int(capacity.get("dropped_heuristic_probe_count") or 0)
        summary["dropped_heuristic_probe_ids"] = list(capacity.get("dropped_heuristic_probe_ids") or [])[:24]
    blockers = list(dict.fromkeys(str(item).strip() for item in blockers if str(item).strip()))
    certification_state = (
        "ai_mission_merged"
        if all_mission_ids and not blockers
        else "partial_until_ai_mission"
    )
    summary.update(
        {
            "schema_version": MISSION_AWARE_MERGE_SCHEMA_VERSION,
            "heuristic_landing_count": heuristic_count,
            "ai_mission_count": len(all_mission_ids),
            "ai_probe_count": ai_probe_count,
            "dual_origin_branch_count": max(int(summary.get("dual_origin_branch_count") or 0), dual_count),
            "reserved_ai_slots": int(capacity.get("reserved_ai_probe_slots") or 0),
            "reserved_path_mission_ids": list(capacity.get("reserved_path_mission_ids") or [])[:24],
            "cache_prior_source": str(ai_contract.get("source") or semantic_runtime.get("source") or "").strip() or None,
            "first_payload_provenance": {
                "semantic_source": str(semantic_runtime.get("source") or "").strip() or None,
                "semantic_material": bool(semantic_runtime.get("material")),
                "ai_spatial_source": str(ai_contract.get("source") or "").strip() or None,
                "ai_spatial_materialized": bool(ai_contract.get("materialized")),
                "ai_spatial_certifiable": bool(ai_contract.get("certifiable")),
                "heuristic_provisional_probe_count": sum(1 for probe in list(probes or []) if isinstance(probe, dict) and bool(probe.get("heuristic_provisional"))),
            },
            "certification": {
                "heuristic_only_certification_allowed": False,
                "ai_mission_required": True,
                "state": certification_state,
                "blockers": blockers,
            },
        }
    )
    summary["mission_merge_row_count"] = len(list(summary.get("mission_merge_rows") or []))
    summary["learning_signal_count"] = len(list(summary.get("learning_signals") or []))
    return summary


def materialize_ai_spatial_contract_into_plan(
    plan: dict[str, Any],
    query: RetrieveRequest,
    atlas_payload: dict[str, Any],
    identity_nucleus: dict[str, Any],
    *,
    search_id: str | None = None,
) -> dict[str, Any]:
    """Turn a late AI spatial contract into physical probes before route execution."""
    updated = dict(plan or {})
    contract = dict(updated.get("ai_spatial_landing_contract") or {})
    path_mission_contract = build_path_mission_contract(
        query_text=query.query_text,
        retrieval_mode=str(getattr(query, "retrieval_mode", None) or dict(updated.get("planner_runtime") or {}).get("retrieval_mode") or "balanced"),
        semantic_contract=dict(updated.get("semantic_contract") or dict(updated.get("planner_runtime") or {}).get("semantic_contract") or {}),
        semantic_contract_runtime=dict(
            updated.get("semantic_contract_runtime") or dict(updated.get("planner_runtime") or {}).get("semantic_contract_runtime") or {}
        ),
        ai_spatial_landing_contract=contract,
    )
    updated = _attach_path_mission_contract_to_plan(updated, path_mission_contract)
    paths = [dict(item) for item in list(contract.get("inverse_answer_paths") or []) if isinstance(item, dict)]
    contract_materialized = bool(contract.get("materialized") and contract.get("certifiable") and paths)
    if not contract_materialized:
        return updated

    existing_probes = [dict(item) for item in list(updated.get("probes") or []) if isinstance(item, dict)]
    if any(str(probe.get("family_plan_id") or "") == "ai_spatial_contract" for probe in existing_probes):
        return updated
    existing_branches = [dict(item) for item in list(updated.get("branches") or []) if isinstance(item, dict)]
    identity_context = dict(updated.get("identity_context") or build_identity_context(identity_nucleus))
    spatial_brief = dict(
        updated.get("metamemory_spatial_brief")
        or dict(updated.get("planner_runtime") or {}).get("metamemory_spatial_brief")
        or {}
    )

    existing_probes = _mark_heuristic_provisional(
        existing_probes,
        ai_spatial_materialized=True,
        ai_spatial_status=str(contract.get("status") or ""),
    )
    probe_materialization = _build_ai_spatial_probes_from_contract(
        query=query,
        ai_spatial_landing_contract=contract,
        atlas_payload=atlas_payload,
        identity_context=identity_context,
        metamemory_spatial_brief=spatial_brief,
        start_index=len(existing_probes),
    )
    ai_spatial_probes = [
        dict(item)
        for item in list(probe_materialization.get("probes") or [])
        if isinstance(item, dict)
    ]
    if not ai_spatial_probes:
        planner_runtime = dict(updated.get("planner_runtime") or {})
        merge_summary = _mission_aware_merge_runtime_summary(
            merge_summary={"status": "no_ai_spatial_probes", "added_branch_count": 0},
            probes=existing_probes,
            branches=existing_branches,
            path_mission_contract=path_mission_contract,
            ai_spatial_landing_contract=contract,
            capacity_reservation={},
            semantic_contract_runtime=dict(updated.get("semantic_contract_runtime") or planner_runtime.get("semantic_contract_runtime") or {}),
        )
        planner_runtime["ai_spatial_probe_materialization"] = dict(probe_materialization)
        planner_runtime["ai_spatial_probe_count"] = 0
        planner_runtime["spatial_snap_count"] = 0
        planner_runtime["ai_spatial_merge_summary"] = dict(merge_summary)
        planner_runtime["mission_aware_merge_summary"] = dict(merge_summary)
        planner_runtime["mission_merge_certification_state"] = str(dict(merge_summary.get("certification") or {}).get("state") or "")
        planner_runtime["ai_spatial_physical_materialization_applied"] = False
        updated["planner_runtime"] = planner_runtime
        updated["ai_spatial_probe_materialization"] = dict(probe_materialization)
        return updated

    kept_probes, capacity_reservation = _reserve_capacity_for_ai_spatial_probes(
        existing_probes,
        ai_spatial_probes,
        max_total_branches=int(query.max_total_branches),
    )
    kept_probe_ids = {str(probe.get("probe_id") or "") for probe in kept_probes if str(probe.get("probe_id") or "")}
    kept_branches = [
        branch
        for branch in existing_branches
        if not list(branch.get("probe_ids") or [])
        or str((branch.get("probe_ids") or [""])[0] or "") in kept_probe_ids
    ]
    probes, branches, atlas_shortlists, ai_added_count, merge_summary = _merge_planner_probes(
        query=query,
        current_probes=kept_probes,
        current_branches=kept_branches,
        new_probes=ai_spatial_probes,
        atlas_payload=atlas_payload,
    )
    merge_summary["status"] = "merged_late_ai_spatial_probes"
    merge_summary["added_branch_count"] = ai_added_count
    merge_summary = _mission_aware_merge_runtime_summary(
        merge_summary=merge_summary,
        probes=probes,
        branches=branches,
        path_mission_contract=path_mission_contract,
        ai_spatial_landing_contract=contract,
        capacity_reservation=capacity_reservation,
        semantic_contract_runtime=dict(updated.get("semantic_contract_runtime") or dict(updated.get("planner_runtime") or {}).get("semantic_contract_runtime") or {}),
    )
    family_plans = _planner_family_summary(
        probes=probes,
        branches=branches,
        family_plan_confidence={
            "heuristic": max(
                (float(probe.get("family_plan_confidence") or 0.0) for probe in probes if _planner_family_for_probe(probe) == "heuristic"),
                default=0.0,
            ),
            "ai": max(
                (float(probe.get("family_plan_confidence") or 0.0) for probe in probes if _record_has_family(probe, "ai")),
                default=0.0,
            ),
        },
    )
    planner_mode = "hybrid_ai_spatial" if any(_record_has_family(branch, "ai") for branch in branches) else str(updated.get("planner_mode") or "hybrid")
    landing_metadata = build_landing_metadata(probes, branches)
    planner_runtime = {
        **dict(updated.get("planner_runtime") or {}),
        "planner_mode": planner_mode,
        "branch_count": len(branches),
        "landing_metadata_count": len(landing_metadata),
        "ai_spatial_landing_contract": dict(contract),
        "ai_spatial_landing_contract_runtime": dict(updated.get("ai_spatial_landing_contract_runtime") or {}),
        "ai_landing_count": int(dict(contract.get("metrics") or {}).get("ai_landing_count") or 0),
        "ai_path_count": int(dict(contract.get("metrics") or {}).get("ai_path_count") or 0),
        "ai_spatial_landing_count": int(dict(contract.get("metrics") or {}).get("ai_landing_count") or 0),
        "ai_spatial_path_count": int(dict(contract.get("metrics") or {}).get("ai_path_count") or 0),
        "ai_spatial_probe_count": len(ai_spatial_probes),
        "ai_spatial_probe_materialization": dict(probe_materialization),
        "spatial_snap": [dict(item) for item in list(probe_materialization.get("snap_events") or [])],
        "spatial_snap_count": len(list(probe_materialization.get("snap_events") or [])),
        "heuristic_provisional": any(bool(probe.get("heuristic_provisional")) for probe in probes),
        "heuristic_provisional_probe_count": sum(1 for probe in probes if bool(probe.get("heuristic_provisional"))),
        "ai_spatial_capacity_reservation": dict(capacity_reservation),
        "ai_spatial_merge_summary": dict(merge_summary),
        "mission_aware_merge_summary": dict(merge_summary),
        "mission_overlap_count": int(merge_summary.get("mission_overlap_count") or 0),
        "mission_divergence_count": int(merge_summary.get("mission_divergence_count") or 0),
        "dropped_heuristic_probe_count": int(merge_summary.get("dropped_heuristic_probe_count") or 0),
        "heuristic_only_certification_allowed": bool(dict(merge_summary.get("certification") or {}).get("heuristic_only_certification_allowed")),
        "mission_merge_certification_state": str(dict(merge_summary.get("certification") or {}).get("state") or ""),
        "ai_spatial_physical_materialization_applied": True,
        "ai_spatial_physical_materialization_search_id": str(search_id or "") or None,
    }
    if search_id:
        search_map_2d_truth = build_search_map_2d_truth(
            search_id=str(search_id),
            thread_id=query.thread_id,
            probes=probes,
            branches=branches,
            landing_metadata=landing_metadata,
            route_truth_summary=dict(updated.get("route_truth_summary") or {}),
            phase="planning",
        )
        map_stream_state = {
            "schema_version": "agvm.search_map_progressive_stream.v1",
            "phase": "planning",
            "landing_count": int((search_map_2d_truth.get("metrics") or {}).get("landing_count") or 0),
            "route_plan_count": int((search_map_2d_truth.get("metrics") or {}).get("route_plan_count") or 0),
            "route_step_count": int((search_map_2d_truth.get("metrics") or {}).get("route_step_count") or 0),
            "travel_step_count": int((search_map_2d_truth.get("metrics") or {}).get("travel_event_count") or 0),
            "route_segment_count": int((search_map_2d_truth.get("metrics") or {}).get("route_segment_count") or 0),
            "ai_material_contribution": True,
            "terminal_frozen": False,
        }
        updated["search_map_2d_truth"] = search_map_2d_truth
        updated["map_stream_state"] = map_stream_state
        planner_runtime["search_map_2d_truth"] = search_map_2d_truth
        planner_runtime["map_stream_state"] = map_stream_state

    updated["identity_context"] = identity_context
    updated["probes"] = probes
    updated["branches"] = branches
    updated["atlas_shortlists"] = atlas_shortlists
    updated["landing_metadata"] = landing_metadata
    updated["planner_mode"] = planner_mode
    updated["ai_family_plan"] = family_plans.get("ai") or {}
    updated["heuristic_family_plan"] = family_plans.get("heuristic") or {}
    updated["ai_spatial_probe_materialization"] = dict(probe_materialization)
    updated["spatial_snap"] = [dict(item) for item in list(probe_materialization.get("snap_events") or [])]
    updated["planner_runtime"] = planner_runtime
    planner_seed_runtime = dict(updated.get("planner_seed_runtime") or {})
    if planner_seed_runtime:
        planner_seed_runtime["ai_spatial_probe_materialization"] = dict(probe_materialization)
        planner_seed_runtime["spatial_snap"] = [dict(item) for item in list(probe_materialization.get("snap_events") or [])]
        planner_seed_runtime["ai_spatial_physical_materialization_applied"] = True
        updated["planner_seed_runtime"] = planner_seed_runtime
    return updated


def prepare_runtime_plan(
    query: RetrieveRequest,
    atlas_payload: dict[str, Any],
    identity_nucleus: dict[str, Any],
    *,
    defer_planner_seed: bool = False,
) -> dict[str, Any]:
    plan_started_at = time.perf_counter()
    stage_timings_ms: dict[str, float] = {}

    def mark_stage(key: str, started_at: float) -> None:
        stage_timings_ms[key] = round((time.perf_counter() - started_at) * 1000.0, 3)

    phase_started = time.perf_counter()
    identity_context = build_identity_context(identity_nucleus)
    mark_stage("identity_nucleus_ms", phase_started)

    phase_started = time.perf_counter()
    selected_retrieval_mode, retrieval_mode_selected_by = _select_retrieval_mode(query)
    merge_window_seconds = _planner_merge_window_seconds(retrieval_mode=selected_retrieval_mode)
    probe_limit_reason = "broad_summary" if _is_broad_summary_query(query.query_text) else "aspect_count"
    reserved_llm_slots = max(0, min(query.max_total_branches, query.max_probe_count) - _initial_probe_limit(query))
    query_class = _query_class(query.query_text)
    legacy_query_contract = build_query_contract(query.query_text, retrieval_mode=selected_retrieval_mode)
    semantic_brain_revision = _semantic_contract_brain_revision(query, atlas_payload)
    mark_stage("request_setup_ms", phase_started)

    phase_started = time.perf_counter()
    heuristic_calibration_snapshot = _fetch_hot_path_heuristic_calibration_snapshot()
    mark_stage("heuristic_calibration_ms", phase_started)

    retrieval_mode_budget = {
        "mode": selected_retrieval_mode,
        "max_probe_count": int(query.max_probe_count),
        "max_total_branches": int(query.max_total_branches),
        "initial_probe_limit": int(_initial_probe_limit(query)),
        "merge_window_seconds": merge_window_seconds,
    }
    active_brain_id = current_brain_id()
    phase_started = time.perf_counter()
    active_metamemory_snapshot = metamemory_snapshot()
    mark_stage("metamemory_snapshot_ms", phase_started)

    phase_started = time.perf_counter()
    active_metamemory_spatial_brief = metamemory_spatial_brief(
        role="retrieval",
        brain_id=active_brain_id,
        brain_revision=semantic_brain_revision,
        atlas_payload=atlas_payload,
        identity_nucleus=identity_nucleus,
        calibration_snapshot=heuristic_calibration_snapshot,
        mode_budget=retrieval_mode_budget,
    )
    mark_stage("metamemory_brief_ms", phase_started)
    active_metamemory_spatial_summary = {
        "schema_version": active_metamemory_spatial_brief.get("schema_version"),
        "revision": active_metamemory_spatial_brief.get("revision"),
        "source_snapshot_version": active_metamemory_spatial_brief.get("source_snapshot_version"),
        "metamemory_revision": active_metamemory_spatial_brief.get("metamemory_revision")
        or active_metamemory_spatial_brief.get("source_snapshot_version"),
        "source_hash": active_metamemory_spatial_brief.get("source_hash"),
        "brain_id": active_metamemory_spatial_brief.get("brain_id"),
        "brain_revision": active_metamemory_spatial_brief.get("brain_revision"),
        "matrix_revision": active_metamemory_spatial_brief.get("matrix_revision"),
        "topology_revision": active_metamemory_spatial_brief.get("topology_revision"),
        "atlas_revision": active_metamemory_spatial_brief.get("atlas_revision"),
        "calibration_revision": active_metamemory_spatial_brief.get("calibration_revision"),
        "source_replay_revision": active_metamemory_spatial_brief.get("source_replay_revision"),
        "guide_areas": list(active_metamemory_spatial_brief.get("guide_areas") or []),
        "radial_bands": list(active_metamemory_spatial_brief.get("radial_bands") or []),
        "atlas_bucket_count": int(dict(active_metamemory_spatial_brief.get("atlas_summary") or {}).get("bucket_count") or 0),
        "topology_overlay_present": bool(
            dict(active_metamemory_spatial_brief.get("topology_overlay_summary") or {}).get("overlay_present")
        ),
        "topology_density_lobe_count": len(
            list(dict(active_metamemory_spatial_brief.get("topology_overlay_summary") or {}).get("density_lobes") or [])
        ),
        "topology_active_highway_count": len(
            list(dict(active_metamemory_spatial_brief.get("topology_overlay_summary") or {}).get("active_highways") or [])
        ),
        "calibration_event_count": int(dict(active_metamemory_spatial_brief.get("calibration_summary") or {}).get("event_count") or 0),
        "spatial_readiness": dict(active_metamemory_spatial_brief.get("spatial_readiness_contract") or {}),
    }
    phase_started = time.perf_counter()
    semantic_contract, semantic_contract_runtime = compile_semantic_query_contract(
        query_text=query.query_text,
        retrieval_mode=selected_retrieval_mode,
        legacy_contract=legacy_query_contract,
        identity_hints=identity_context,
        tool_name=query.mcp_tool_name,
        allow_ai=bool(llm_enabled()),
        deferred=bool(defer_planner_seed),
        timeout=_semantic_contract_timeout_seconds(selected_retrieval_mode),
        brain_revision=semantic_brain_revision,
        cache_scope="retrieve_semantic_contract",
    )
    mark_stage("semantic_ai_ms", phase_started)
    semantic_identity_hints = sanitize_identity_hints(semantic_contract.get("identity_hints") or {})
    runtime_identity_hints = sanitize_identity_hints(identity_context)
    if not semantic_identity_hints.get("core_name") and runtime_identity_hints.get("core_name"):
        semantic_contract = {**dict(semantic_contract or {}), "identity_hints": runtime_identity_hints}
    elif "identity_hints" not in dict(semantic_contract or {}):
        semantic_contract = {**dict(semantic_contract or {}), "identity_hints": runtime_identity_hints}
    else:
        semantic_contract = {**dict(semantic_contract or {}), "identity_hints": semantic_identity_hints}
    seed_max_probe_count = _planner_seed_max_items(query.query_text, query.max_probe_count, query.max_total_branches)
    planner_seed_enabled = bool(llm_enabled())
    planner_seed_deferred = bool(planner_seed_enabled and defer_planner_seed)
    planner_seed_started_at = time.perf_counter()
    planner_seed_payload = None
    planner_seed_error: str | None = None
    planner_seed_source = "disabled"
    planner_seed_status = "disabled"
    planner_seed_attempt_count = 0
    planner_seed_primary_status = "disabled"
    planner_seed_retry_used = False
    planner_seed_recovered_from_timeout = False
    answer_strands: list[dict[str, Any]] = []
    semantic_contract_seed_strands = _answer_strands_from_semantic_contract(
        semantic_contract,
        query_text=query.query_text,
        max_probe_count=seed_max_probe_count,
    )
    semantic_contract_ai_seed = bool(
        semantic_contract_seed_strands
        and _semantic_contract_is_ai_material(semantic_contract_runtime)
    )
    if semantic_contract_seed_strands and not semantic_contract_ai_seed:
        semantic_contract_seed_strands = [
            {
                **dict(strand),
                "planner_family": "heuristic",
                "family_plan_id": "heuristic_family_plan",
                "family_plan_confidence": min(0.72, float(strand.get("family_plan_confidence") or 0.72)),
            }
            for strand in semantic_contract_seed_strands
        ]
    if planner_seed_deferred:
        planner_seed_source = "background_deferred"
        planner_seed_status = "deferred"
        planner_seed_primary_status = "deferred"
        if semantic_contract_seed_strands:
            answer_strands = [dict(item) for item in semantic_contract_seed_strands]
    elif planner_seed_enabled:
        planner_seed_attempt_count += 1
        planner_seed_payload, planner_seed_error = llm_fast_planner_seed(
            query,
            identity_source=identity_context,
            retrieval_mode=selected_retrieval_mode,
        )
        if planner_seed_payload and not planner_seed_error:
            answer_strands = _normalize_answer_strands(
                list(planner_seed_payload.get("answer_strands") or []),
                query_text=query.query_text,
                max_probe_count=seed_max_probe_count,
                planner_family="ai",
            )
            answer_strands = _select_answer_strands_for_query(
                answer_strands,
                query_text=query.query_text,
                max_probe_count=seed_max_probe_count,
            )
        if answer_strands:
            planner_seed_source = "llm"
            planner_seed_status = "completed"
            planner_seed_primary_status = "completed"
        else:
            planner_seed_source = _planner_seed_source_from_error(planner_seed_error)
            planner_seed_status = planner_seed_source
            planner_seed_primary_status = planner_seed_status
            retry_budget = _planner_seed_retry_timeout_seconds(selected_retrieval_mode, query.query_text)
            if planner_seed_source == "timeout" and retry_budget > 0.0 and selected_retrieval_mode in {"balanced", "heavy", "forensic"}:
                planner_seed_retry_used = True
                planner_seed_attempt_count += 1
                retry_payload, retry_error = _run_fast_planner_seed_request(
                    query,
                    identity_source=identity_nucleus,
                    retrieval_mode=selected_retrieval_mode,
                    minimal=True,
                    timeout_override=retry_budget,
                )
                retry_answer_strands = _normalize_answer_strands(
                    list((retry_payload or {}).get("answer_strands") or []),
                    query_text=query.query_text,
                    max_probe_count=seed_max_probe_count,
                    planner_family="ai",
                )
                retry_answer_strands = _select_answer_strands_for_query(
                    retry_answer_strands,
                    query_text=query.query_text,
                    max_probe_count=seed_max_probe_count,
                )
                if retry_answer_strands:
                    answer_strands = retry_answer_strands
                    planner_seed_payload = retry_payload
                    planner_seed_error = None
                    planner_seed_source = "llm"
                    planner_seed_status = "completed"
                    planner_seed_recovered_from_timeout = True
                else:
                    planner_seed_error = retry_error or planner_seed_error
                    planner_seed_source = _planner_seed_source_from_error(planner_seed_error)
                    planner_seed_status = planner_seed_source
    if not answer_strands and semantic_contract_seed_strands:
        answer_strands = [dict(item) for item in semantic_contract_seed_strands]
    if not answer_strands:
        answer_strands = _normalize_answer_strands(
            heuristic_answer_strands(query.query_text, seed_max_probe_count),
            query_text=query.query_text,
            max_probe_count=seed_max_probe_count,
            planner_family="heuristic",
        )
        answer_strands = _select_answer_strands_for_query(
            answer_strands,
            query_text=query.query_text,
            max_probe_count=seed_max_probe_count,
        )
    else:
        answer_strands = _supplement_answer_strands_for_query(
            answer_strands,
            query_text=query.query_text,
            max_probe_count=seed_max_probe_count,
        )
        answer_strands = _select_answer_strands_for_query(
            answer_strands,
            query_text=query.query_text,
            max_probe_count=seed_max_probe_count,
        )
    planner_seed_ms = round((time.perf_counter() - planner_seed_started_at) * 1000.0, 2)
    seed_goal_coverage, seed_destination_presence = _planner_seed_summaries(answer_strands, query_text=query.query_text)
    planner_seed_query_class = query_class if query_class != "direct_fact" else (
        str((planner_seed_payload or {}).get("seed_query_class") or query_class).strip() or query_class
    )
    planner_seed_runtime = {
        "planner_seed_enabled": planner_seed_enabled,
        "planner_seed_status": planner_seed_status,
        "planner_seed_ms": planner_seed_ms,
        "planner_seed_source": planner_seed_source,
        "planner_seed_attempt_count": planner_seed_attempt_count,
        "planner_seed_primary_status": planner_seed_primary_status,
        "planner_seed_retry_used": planner_seed_retry_used,
        "planner_seed_recovered_from_timeout": planner_seed_recovered_from_timeout,
        "planner_seed_deferred": planner_seed_deferred,
        "planner_seed_blocking": bool(planner_seed_enabled and not planner_seed_deferred),
        "critical_path_planner_seed_deferred": planner_seed_deferred,
        "first_answer_sla_split": planner_seed_deferred,
        "ai_background_enrichment_enabled": planner_seed_deferred,
        "planner_seed_deferred_reason": "first_answer_sla_split" if planner_seed_deferred else None,
        "answer_strands": [dict(item) for item in answer_strands],
        "answer_strand_count": len(answer_strands),
        "metamemory_snapshot": dict(active_metamemory_snapshot),
        "metamemory_spatial_brief": dict(active_metamemory_spatial_brief),
        "metamemory_spatial_brief_summary": dict(active_metamemory_spatial_summary),
        "metamemory_revision": active_metamemory_snapshot.get("snapshot_version"),
        "metamemory_spatial_revision": active_metamemory_spatial_brief.get("revision"),
        "planner_seed_summary": str((planner_seed_payload or {}).get("seed_summary") or "").strip() or None,
        "planner_seed_query_class": planner_seed_query_class,
        "seed_goal_coverage": seed_goal_coverage,
        "seed_destination_presence": seed_destination_presence,
        "seed_used_by_bootstrap": bool(answer_strands),
        "planner_seed_error": planner_seed_error,
        "semantic_contract_seed_used": bool(semantic_contract_seed_strands and answer_strands),
        "semantic_contract_ai_seed_used": bool(semantic_contract_ai_seed and answer_strands),
        "semantic_contract_seed_strand_count": len(semantic_contract_seed_strands),
        "semantic_contract_seed_source": str(semantic_contract_runtime.get("source") or "") or None,
        "semantic_contract_blocking": bool(not defer_planner_seed),
        "semantic_contract_deferred_requested": bool(defer_planner_seed),
        "semantic_contract_brain_revision": semantic_brain_revision,
    }
    ai_spatial_initial_mode_budget = dict(retrieval_mode_budget)
    if defer_planner_seed:
        ai_spatial_initial_mode_budget["source"] = "preflight_initial_plan"
        ai_spatial_initial_mode_budget["cache_only"] = True
        ai_spatial_initial_mode_budget["first_payload_deferred_initial_plan"] = True
    phase_started = time.perf_counter()
    ai_spatial_landing_contract = build_ai_spatial_landing_contract(
        query_text=query.query_text,
        retrieval_mode=selected_retrieval_mode,
        semantic_contract=semantic_contract,
        semantic_contract_runtime=semantic_contract_runtime,
        answer_strands=answer_strands,
        identity_hints=semantic_contract.get("identity_hints") or identity_context,
        metamemory_spatial_brief=active_metamemory_spatial_brief,
        mode_budget=ai_spatial_initial_mode_budget,
        brain_revision=semantic_brain_revision,
        allow_ai=bool(llm_enabled()),
        deferred=bool(
            planner_seed_deferred
            and (
                not _semantic_contract_is_ai_material(semantic_contract_runtime)
                or bool(ai_spatial_initial_mode_budget.get("first_payload_deferred_initial_plan"))
            )
        ),
        cache_scope="retrieve_ai_spatial_contract",
    )
    mark_stage("spatial_ai_ms", phase_started)
    ai_spatial_landing_contract_runtime = {
        "schema_version": "agvm.ai_spatial_landing_contract_runtime.v1",
        "status": str(ai_spatial_landing_contract.get("status") or ""),
        "source": str(ai_spatial_landing_contract.get("source") or ""),
        "materialized": bool(ai_spatial_landing_contract.get("materialized")),
        "certifiable": bool(ai_spatial_landing_contract.get("certifiable")),
        "planner_latency_ms": ai_spatial_landing_contract.get("planner_latency_ms"),
        "missing_reasons": list(ai_spatial_landing_contract.get("missing_reasons") or []),
        "metrics": dict(ai_spatial_landing_contract.get("metrics") or {}),
        "cache": dict(ai_spatial_landing_contract.get("cache") or {}),
        "metamemory_spatial_revision": ai_spatial_landing_contract.get("metamemory_spatial_revision"),
        "brain_revision": ai_spatial_landing_contract.get("brain_revision"),
    }
    phase_started = time.perf_counter()
    path_mission_contract = build_path_mission_contract(
        query_text=query.query_text,
        retrieval_mode=selected_retrieval_mode,
        semantic_contract=semantic_contract,
        semantic_contract_runtime=semantic_contract_runtime,
        ai_spatial_landing_contract=ai_spatial_landing_contract,
    )
    mark_stage("mission_contract_ms", phase_started)
    path_missions = [
        dict(item)
        for item in list(path_mission_contract.get("path_missions") or [])
        if isinstance(item, dict)
    ]
    planner_seed_runtime["ai_spatial_landing_contract"] = dict(ai_spatial_landing_contract)
    planner_seed_runtime["ai_spatial_landing_contract_runtime"] = dict(ai_spatial_landing_contract_runtime)
    planner_seed_runtime["ai_spatial_landing_count"] = int(dict(ai_spatial_landing_contract.get("metrics") or {}).get("ai_landing_count") or 0)
    planner_seed_runtime["ai_spatial_path_count"] = int(dict(ai_spatial_landing_contract.get("metrics") or {}).get("ai_path_count") or 0)
    planner_seed_runtime["path_mission_contract"] = dict(path_mission_contract)
    planner_seed_runtime["path_mission_count"] = len(path_missions)
    phase_started = time.perf_counter()
    probes, stop_threshold, decomposition_mode = fallback_retrieval_plan(
        query,
        atlas_payload=atlas_payload,
        identity_context=identity_context,
        calibration_snapshot=heuristic_calibration_snapshot,
        answer_strands=answer_strands,
        planner_seed_source=planner_seed_source,
    )
    mark_stage("heuristic_planner_ms", phase_started)

    phase_started = time.perf_counter()
    probes = _ensure_probe_goal_coverage(
        probes,
        query_text=query.query_text,
        max_probes=_initial_probe_limit(query),
        atlas_payload=atlas_payload,
        identity_context=identity_context,
    )
    probes = _reindex_probes(probes)
    probes = [
        _annotate_probe_family(
            probe,
            planner_family=_planner_family_for_probe(probe),
            family_plan_id=str(probe.get("family_plan_id") or _family_plan_id_for_family(_planner_family_for_probe(probe))).strip()
            or _family_plan_id_for_family(_planner_family_for_probe(probe)),
            family_plan_confidence=float(
                probe.get("family_plan_confidence")
                or probe.get("branch_priority")
                or probe.get("weight")
                or 0.0
            ),
        )
        for probe in probes
    ]
    ai_spatial_materialized = bool(
        ai_spatial_landing_contract.get("materialized")
        and ai_spatial_landing_contract.get("certifiable")
        and list(ai_spatial_landing_contract.get("inverse_answer_paths") or [])
    )
    probes = _mark_heuristic_provisional(
        probes,
        ai_spatial_materialized=ai_spatial_materialized,
        ai_spatial_status=str(ai_spatial_landing_contract.get("status") or ""),
    )
    mark_stage("heuristic_merge_prep_ms", phase_started)

    phase_started = time.perf_counter()
    ai_spatial_probe_materialization = _build_ai_spatial_probes_from_contract(
        query=query,
        ai_spatial_landing_contract=ai_spatial_landing_contract,
        atlas_payload=atlas_payload,
        identity_context=identity_context,
        metamemory_spatial_brief=active_metamemory_spatial_brief,
        start_index=len(probes),
    )
    mark_stage("mission_materialization_ms", phase_started)
    ai_spatial_probes = [dict(item) for item in list(ai_spatial_probe_materialization.get("probes") or []) if isinstance(item, dict)]
    phase_started = time.perf_counter()
    probes, ai_spatial_capacity_reservation = _reserve_capacity_for_ai_spatial_probes(
        probes,
        ai_spatial_probes,
        max_total_branches=int(query.max_total_branches),
    )
    atlas_shortlists = _apply_probe_shortlists(probes, query, atlas_payload)
    branches = [_create_branch_from_probe(query, probe) for probe in probes]
    mark_stage("atlas_shortlist_ms", phase_started)
    ai_spatial_merge_summary: dict[str, Any] = {
        "status": "no_ai_spatial_probes",
        "added_branch_count": 0,
        "branch_reuse_count": 0,
        "branch_enrich_count": 0,
        "branch_fork_count": 0,
        "dual_origin_branch_count": 0,
        "merge_resolution_histogram": {"reuse_branch": 0, "enrich_branch": 0, "fork_new_branch": 0},
    }
    if ai_spatial_probes:
        phase_started = time.perf_counter()
        probes, branches, atlas_shortlists, ai_spatial_added_count, ai_spatial_merge_summary = _merge_planner_probes(
            query=query,
            current_probes=probes,
            current_branches=branches,
            new_probes=ai_spatial_probes,
            atlas_payload=atlas_payload,
        )
        ai_spatial_merge_summary["status"] = "merged_ai_spatial_probes"
        ai_spatial_merge_summary["added_branch_count"] = ai_spatial_added_count
        mark_stage("ai_heuristic_merge_ms", phase_started)
    else:
        stage_timings_ms.setdefault("ai_heuristic_merge_ms", 0.0)
    ai_spatial_merge_summary = _mission_aware_merge_runtime_summary(
        merge_summary=ai_spatial_merge_summary,
        probes=probes,
        branches=branches,
        path_mission_contract=path_mission_contract,
        ai_spatial_landing_contract=ai_spatial_landing_contract,
        capacity_reservation=ai_spatial_capacity_reservation,
        semantic_contract_runtime=semantic_contract_runtime,
    )
    planner_mode = (
        "hybrid_ai_spatial"
        if any("ai" in _families_for_record(branch) for branch in branches)
        else ("hybrid" if llm_enabled() else "heuristic")
    )
    family_plans = _planner_family_summary(
        probes=probes,
        branches=branches,
        family_plan_confidence={
            "heuristic": max((float(probe.get("family_plan_confidence") or 0.0) for probe in probes if _planner_family_for_probe(probe) == "heuristic"), default=0.0),
            "ai": max((float(probe.get("family_plan_confidence") or 0.0) for probe in probes if _planner_family_for_probe(probe) == "ai"), default=0.0),
        },
    )
    calibration_scope_keys = sorted(
        {
            str(scope_key)
            for probe in probes
            for scope_key in list(probe.get("calibration_scope_keys") or [])
            if str(scope_key).strip()
        }
    )
    calibration_applied_probe_count = sum(1 for probe in probes if bool(probe.get("calibration_applied")))
    compiled_prior_applied_probe_count = sum(1 for probe in probes if bool(probe.get("compiled_prior_applied")))
    heuristic_calibration_summary = dict((heuristic_calibration_snapshot or {}).get("summary") or {})
    compiled_prior_scope_keys = [
        scope_key for scope_key in calibration_scope_keys if str(scope_key).startswith("compiled_prior::")
    ]
    heuristic_calibration_runtime = {
        "available": bool((heuristic_calibration_snapshot or {}).get("event_count") or (heuristic_calibration_snapshot or {}).get("updated_at")),
        "applied": calibration_applied_probe_count > 0,
        "scope_keys_used": calibration_scope_keys,
        "branch_count_adjustment": len(probes) - _preferred_probe_limit(query.query_text, min(query.max_probe_count, query.max_total_branches)),
        "applied_probe_count": calibration_applied_probe_count,
        "compiled_prior_available": bool(compiled_prior_scope_keys) or any(bool(probe.get("compiled_prior_template")) for probe in probes),
        "compiled_prior_applied": compiled_prior_applied_probe_count > 0 or bool(compiled_prior_scope_keys),
        "compiled_prior_applied_probe_count": compiled_prior_applied_probe_count,
        "compiled_prior_scope_keys": compiled_prior_scope_keys,
        "failure_signature_count": len(dict((heuristic_calibration_snapshot or {}).get("failure_signatures") or {})),
        "review_candidate_count": sum(
            1
            for payload in dict((heuristic_calibration_snapshot or {}).get("failure_signatures") or {}).values()
            if bool(dict(dict(payload).get("review") or {}).get("required", True))
        ),
        "compiled_prior_count": len(dict((heuristic_calibration_snapshot or {}).get("compiled_priors") or {})),
        "compiled_summary": heuristic_calibration_summary,
        "query_class": query_class,
        "event_count": int((heuristic_calibration_snapshot or {}).get("event_count") or 0),
        "hot_path_recent_events_loaded": bool((heuristic_calibration_snapshot or {}).get("recent_events")),
        "hot_path_recent_landing_corrections_loaded": bool((heuristic_calibration_snapshot or {}).get("recent_landing_correction_events")),
        "snapshot_mode": "hot_path_lightweight",
        "updated_at": (heuristic_calibration_snapshot or {}).get("updated_at"),
    }
    stage_timings_ms["planner_total_ms"] = round((time.perf_counter() - plan_started_at) * 1000.0, 3)
    active_metamemory_spatial_readiness = dict(
        active_metamemory_spatial_brief.get("spatial_readiness_contract") or {}
    )
    runtime_stage_timing = _runtime_stage_timing_payload(
        **stage_timings_ms,
        semantic_ai_source=str(semantic_contract_runtime.get("source") or "") or None,
        semantic_ai_material=bool(semantic_contract_runtime.get("material")),
        spatial_ai_source=str(ai_spatial_landing_contract.get("source") or "") or None,
        spatial_ai_materialized=bool(ai_spatial_landing_contract.get("materialized")),
        spatial_ai_certifiable=bool(ai_spatial_landing_contract.get("certifiable")),
        calibration_snapshot_mode="hot_path_lightweight",
    )
    phase_timings = _runtime_stage_phase_timings(runtime_stage_timing)
    return {
        "identity_context": identity_context,
        "answer_strands": answer_strands,
        "planner_seed_runtime": planner_seed_runtime,
        "seed_goal_coverage": seed_goal_coverage,
        "seed_destination_presence": seed_destination_presence,
        "semantic_contract": semantic_contract,
        "semantic_contract_runtime": semantic_contract_runtime,
        "metamemory_snapshot": dict(active_metamemory_snapshot),
        "metamemory_spatial_brief": dict(active_metamemory_spatial_brief),
        "metamemory_spatial_brief_summary": dict(active_metamemory_spatial_summary),
        "metamemory_spatial_readiness": dict(active_metamemory_spatial_readiness),
        "ai_spatial_landing_contract": dict(ai_spatial_landing_contract),
        "ai_spatial_landing_contract_runtime": dict(ai_spatial_landing_contract_runtime),
        "path_mission_contract": dict(path_mission_contract),
        "path_missions": [dict(item) for item in path_missions],
        "ai_spatial_probe_materialization": dict(ai_spatial_probe_materialization),
        "spatial_snap": [dict(item) for item in list(ai_spatial_probe_materialization.get("snap_events") or [])],
        "probes": probes,
        "branches": branches,
        "atlas_shortlists": atlas_shortlists,
        "heuristic_family_plan": family_plans.get("heuristic") or {},
        "ai_family_plan": family_plans.get("ai") or {},
        "planner_mode": planner_mode,
        "decomposition_mode": decomposition_mode,
        "stop_threshold": stop_threshold,
        "planner_runtime": {
            "planner_mode": planner_mode,
            "decomposition_mode": decomposition_mode,
            "branch_count": len(branches),
            "planner_path": "hybrid_initial" if planner_mode in {"hybrid", "hybrid_ai_spatial"} else "fallback",
            "probe_limit_reason": probe_limit_reason,
            "broad_summary_query": _is_broad_summary_query(query.query_text),
            "query_class": _query_class(query.query_text),
            "query_contract": legacy_query_contract,
            "semantic_contract": semantic_contract,
            "semantic_contract_runtime": semantic_contract_runtime,
            "metamemory_snapshot": dict(active_metamemory_snapshot),
            "metamemory_spatial_brief": dict(active_metamemory_spatial_brief),
            "metamemory_spatial_brief_summary": dict(active_metamemory_spatial_summary),
            "metamemory_spatial_readiness": dict(active_metamemory_spatial_readiness),
            "ai_spatial_landing_contract": dict(ai_spatial_landing_contract),
            "ai_spatial_landing_contract_runtime": dict(ai_spatial_landing_contract_runtime),
            "path_mission_contract": dict(path_mission_contract),
            "path_missions": [dict(item) for item in path_missions],
            "path_mission_count": len(path_missions),
            "mission_contract_status": str(path_mission_contract.get("status") or "") or None,
            "mission_contract_materialized": bool(path_mission_contract.get("materialized")),
            "metamemory_revision": active_metamemory_snapshot.get("snapshot_version"),
            "metamemory_spatial_revision": active_metamemory_spatial_brief.get("revision"),
            "ai_landing_count": int(dict(ai_spatial_landing_contract.get("metrics") or {}).get("ai_landing_count") or 0),
            "ai_path_count": int(dict(ai_spatial_landing_contract.get("metrics") or {}).get("ai_path_count") or 0),
            "ai_spatial_landing_count": int(dict(ai_spatial_landing_contract.get("metrics") or {}).get("ai_landing_count") or 0),
            "ai_spatial_path_count": int(dict(ai_spatial_landing_contract.get("metrics") or {}).get("ai_path_count") or 0),
            "ai_spatial_probe_count": len(ai_spatial_probes),
            "ai_spatial_probe_materialization": dict(ai_spatial_probe_materialization),
            "spatial_snap": [dict(item) for item in list(ai_spatial_probe_materialization.get("snap_events") or [])],
            "spatial_snap_count": len(list(ai_spatial_probe_materialization.get("snap_events") or [])),
            "heuristic_provisional": any(bool(probe.get("heuristic_provisional")) for probe in probes),
            "heuristic_provisional_probe_count": sum(1 for probe in probes if bool(probe.get("heuristic_provisional"))),
            "ai_spatial_capacity_reservation": dict(ai_spatial_capacity_reservation),
            "ai_spatial_merge_summary": dict(ai_spatial_merge_summary),
            "mission_aware_merge_summary": dict(ai_spatial_merge_summary),
            "mission_overlap_count": int(ai_spatial_merge_summary.get("mission_overlap_count") or 0),
            "mission_divergence_count": int(ai_spatial_merge_summary.get("mission_divergence_count") or 0),
            "dropped_heuristic_probe_count": int(ai_spatial_merge_summary.get("dropped_heuristic_probe_count") or 0),
            "heuristic_only_certification_allowed": bool(dict(ai_spatial_merge_summary.get("certification") or {}).get("heuristic_only_certification_allowed")),
            "mission_merge_certification_state": str(dict(ai_spatial_merge_summary.get("certification") or {}).get("state") or ""),
            "semantic_contract_status": str(semantic_contract_runtime.get("status") or ""),
            "semantic_contract_source": str(semantic_contract_runtime.get("source") or ""),
            "semantic_contract_ai_required": bool(semantic_contract_runtime.get("ai_required")),
            "semantic_contract_material": bool(semantic_contract_runtime.get("material")),
            "semantic_contract_cache_status": str(semantic_contract_runtime.get("cache_status") or "") or None,
            "semantic_contract_cache_hit": bool(semantic_contract_runtime.get("cache_hit")),
            "semantic_contract_brain_revision": semantic_brain_revision,
            "semantic_contract_blocking": bool(not defer_planner_seed),
            "semantic_contract_deferred_requested": bool(defer_planner_seed),
            "planner_error": None,
            "fast_path_used": True,
            "fast_model_profile": _fast_model_profile(
                retrieval_mode=selected_retrieval_mode,
                query_text=query.query_text,
                response_mode=query.response_mode,
                semantic_contract_runtime=semantic_contract_runtime,
                planner_seed_runtime=planner_seed_runtime,
                first_answer_sla_split=planner_seed_runtime["first_answer_sla_split"],
            ),
            "llm_scout_enabled": bool(llm_enabled()),
            "llm_scout_status": "pending" if llm_enabled() else "disabled",
            "planner_seed_enabled": planner_seed_runtime["planner_seed_enabled"],
            "planner_seed_status": planner_seed_runtime["planner_seed_status"],
            "planner_seed_ms": planner_seed_runtime["planner_seed_ms"],
            "planner_seed_source": planner_seed_runtime["planner_seed_source"],
            "planner_seed_deferred": planner_seed_runtime["planner_seed_deferred"],
            "planner_seed_blocking": planner_seed_runtime["planner_seed_blocking"],
            "critical_path_planner_seed_deferred": planner_seed_runtime["critical_path_planner_seed_deferred"],
            "first_answer_sla_split": planner_seed_runtime["first_answer_sla_split"],
            "ai_background_enrichment_enabled": planner_seed_runtime["ai_background_enrichment_enabled"],
            "planner_seed_deferred_reason": planner_seed_runtime["planner_seed_deferred_reason"],
            "answer_strands": [dict(item) for item in answer_strands],
            "answer_strand_count": len(answer_strands),
            "seed_goal_coverage": seed_goal_coverage,
            "seed_destination_presence": seed_destination_presence,
            "seed_used_by_bootstrap": planner_seed_runtime["seed_used_by_bootstrap"],
            "planner_seed_summary": planner_seed_runtime["planner_seed_summary"],
            "planner_seed_query_class": planner_seed_runtime["planner_seed_query_class"],
            "semantic_contract_seed_used": planner_seed_runtime["semantic_contract_seed_used"],
            "semantic_contract_ai_seed_used": planner_seed_runtime["semantic_contract_ai_seed_used"],
            "semantic_contract_seed_strand_count": planner_seed_runtime["semantic_contract_seed_strand_count"],
            "semantic_contract_seed_source": planner_seed_runtime["semantic_contract_seed_source"],
            "runtime_stage_timing": runtime_stage_timing,
            "phase_timings": phase_timings,
            "planner_merge_window_seconds": merge_window_seconds,
            "reserved_llm_slots": reserved_llm_slots,
            "retrieval_mode": selected_retrieval_mode,
            "retrieval_mode_selected_by": retrieval_mode_selected_by,
            "family_plans": family_plans,
            "heuristic_calibration": heuristic_calibration_runtime,
            "branch_reuse_count": int(ai_spatial_merge_summary.get("branch_reuse_count") or 0),
            "branch_enrich_count": int(ai_spatial_merge_summary.get("branch_enrich_count") or 0),
            "branch_fork_count": int(ai_spatial_merge_summary.get("branch_fork_count") or 0),
            "dual_origin_branch_count": int(ai_spatial_merge_summary.get("dual_origin_branch_count") or 0),
            "merge_resolution_histogram": dict(ai_spatial_merge_summary.get("merge_resolution_histogram") or {"reuse_branch": 0, "enrich_branch": 0, "fork_new_branch": 0}),
            "merged_strand_ids": list(ai_spatial_merge_summary.get("merged_strand_ids") or []),
            "enriched_strand_ids": list(ai_spatial_merge_summary.get("enriched_strand_ids") or []),
            "forked_strand_ids": list(ai_spatial_merge_summary.get("forked_strand_ids") or []),
            "mission_merge_rows": list(ai_spatial_merge_summary.get("mission_merge_rows") or []),
            "mission_merge_learning_signals": list(ai_spatial_merge_summary.get("learning_signals") or []),
        },
    }


def _process_branch_round(
    *,
    query: RetrieveRequest,
    probe: dict[str, Any],
    branch: dict[str, Any],
    round_index: int,
    atlas_shortlist: list[dict[str, Any]],
    identity_context: dict[str, Any],
    success_threshold: float,
    mode_config: dict[str, Any],
    navigation_actions: list[dict[str, Any]] | None = None,
    blackboard: dict[str, Any] | None = None,
) -> dict[str, Any]:
    round_started_at = time.perf_counter()
    blackboard = dict(blackboard or {})
    retrieval_mode = str(mode_config.get("retrieval_mode") or getattr(query, "retrieval_mode", None) or "balanced")
    branch = dict(branch)
    branch["last_round_index"] = int(round_index)
    current_node_before = str(branch.get("current_node_id") or "").strip() or None
    current_position = dict(probe.get("landing_position") or probe["base_position"])
    current_node_payload = None
    if current_node_before:
        current_node_payload = next(iter(fetch_nodes_by_ids([current_node_before], include_raw_text=False)), None)
        if current_node_payload and isinstance(current_node_payload.get("final_position"), dict):
            current_position = dict(current_node_payload.get("final_position") or current_position)
    radius = float(branch["search_radius"])
    bucket_keys = [bucket["bucket_key"] for bucket in atlas_shortlist[:2]]
    applied_actions = _normalize_navigation_actions(navigation_actions)
    action_hydrate_ids: list[str] = []
    action_highway_targets: list[str] = []
    action_link_targets: list[str] = []
    terminate_reason: str | None = None
    for action in applied_actions:
        payload = dict(action.get("payload") or {})
        action_type = str(action.get("action") or "")
        if action_type == "inspect_bucket":
            target_bucket = str(payload.get("bucket_key") or "").strip()
            if target_bucket and target_bucket not in bucket_keys:
                bucket_keys.append(target_bucket)
        elif action_type == "inspect_adjacent_buckets":
            for target_bucket in list(payload.get("bucket_keys") or []):
                target_bucket = str(target_bucket or "").strip()
                if target_bucket and target_bucket not in bucket_keys:
                    bucket_keys.append(target_bucket)
        elif action_type == "expand_radius":
            radius = min(0.42, max(radius, radius + float(payload.get("delta") or 0.0)))
        elif action_type == "follow_highway":
            target = str(payload.get("node_id") or "").strip()
            if target:
                action_highway_targets.append(target)
        elif action_type == "follow_local_link":
            target = str(payload.get("node_id") or "").strip()
            if target:
                action_link_targets.append(target)
        elif action_type == "hydrate_node":
            target = str(payload.get("node_id") or "").strip()
            if target:
                action_hydrate_ids.append(target)
        elif action_type == "hydrate_nodes":
            action_hydrate_ids.extend(str(target or "").strip() for target in list(payload.get("node_ids") or []))
        elif action_type in {"read_document_anchor", "read_document_chunk"}:
            target = str(payload.get("node_id") or "").strip()
            if target:
                action_hydrate_ids.append(target)
        elif action_type == "terminate_branch":
            terminate_reason = str(payload.get("reason") or action.get("rationale") or "terminate_branch").strip() or "terminate_branch"
            break
    query_class = _query_class(f"{query.query_text} {probe['query_text']}")
    goal = _canonical_goal_from_context(
        str(branch.get("goal") or probe.get("goal") or ""),
        root_query_text=query.query_text,
        probe_query_text=str(probe.get("query_text") or query.query_text),
        expected_guide_area=str(probe.get("expected_guide_area") or ""),
    ) or str(branch.get("goal") or probe.get("goal") or _goal_for_query_text(f"{query.query_text} {probe['query_text']}", probe.get("expected_guide_area")))
    semantic_destination_queue = [
        dict(item)
        for item in list(branch.get("semantic_destination_queue") or branch.get("destination_queue") or [])
        if isinstance(item, dict)
    ]
    execution_destination_queue, destination_execution_index = _destination_queue_for_execution(branch)
    if not execution_destination_queue and semantic_destination_queue:
        execution_destination_queue = [dict(item) for item in semantic_destination_queue]
        destination_execution_index = 0
    active_destination = (
        dict(execution_destination_queue[destination_execution_index])
        if execution_destination_queue and destination_execution_index < len(execution_destination_queue)
        else {}
    )
    _ensure_branch_destination_resolution(branch, round_index=round_index)
    if active_destination:
        _set_destination_resolution_state(
            branch,
            active_destination,
            state="active",
            state_reason="round_started",
            round_index=round_index,
            execution_index=destination_execution_index,
        )

    def _terminal_branch(reason: str) -> dict[str, Any]:
        updated_branch = dict(branch)
        updated_branch["status"] = "stopped"
        updated_branch["stop_reason"] = reason
        updated_branch["recommended_next_actions"] = []
        updated_branch["planned_actions"] = applied_actions
        updated_branch["route_state"] = "stopped"
        updated_branch["lifecycle_stage"] = "stopped"
        updated_branch["local_stop_recommendation"] = "stop_branch"
        updated_branch["controller_kind"] = "fallback_branch_controller"
        updated_branch["controller_recommendation"] = {
            "action": "stop_branch",
            "reason": reason,
            "confidence": 0.82,
            "target_destination_id": str((updated_branch.get("active_destination") or active_destination).get("destination_id") or "") or None,
            "requested_actions": [],
            "decision_source": "fallback_disabled",
            "fallback_reason": "disabled",
            "controller_kind": "fallback_branch_controller",
            "turn_ms": 0.0,
            "evidence_basis": _controller_evidence_basis(updated_branch),
            "fallback_preview_action": "stop_branch",
            "override_applied": False,
            **_controller_escalation_defaults(active_destination=updated_branch.get("active_destination") or active_destination),
        }
        updated_branch["controller_confidence"] = 0.82
        updated_branch["controller_reason"] = reason
        updated_branch["controller_turn_ms"] = 0.0
        updated_branch["controller_evidence_basis"] = _controller_evidence_basis(updated_branch)
        updated_branch["controller_decision_source"] = "fallback_disabled"
        updated_branch["controller_fallback_reason"] = "disabled"
        updated_branch["controller_escalation_needed"] = False
        updated_branch["controller_escalation_reason"] = None
        updated_branch["controller_requested_master_action"] = "continue"
        updated_branch["controller_blocking_destination_id"] = str((updated_branch.get("active_destination") or active_destination).get("destination_id") or "") or None
        updated_branch["controller_blocking_state"] = str(updated_branch.get("route_state") or "stopped")
        updated_branch["semantic_destination_queue"] = [dict(item) for item in semantic_destination_queue]
        updated_branch["execution_destination_queue"] = [dict(item) for item in execution_destination_queue]
        updated_branch["destination_execution_index"] = destination_execution_index
        updated_branch["active_destination"] = dict(active_destination or {})
        updated_branch["last_round_index"] = int(round_index)
        if active_destination:
            _set_destination_resolution_state(
                updated_branch,
                active_destination,
                state="suppressed_by_master" if str(reason).startswith("master_") else "route_exhausted",
                state_reason=reason,
                round_index=round_index,
                execution_index=destination_execution_index,
            )
        _bulk_mark_open_destinations(
            updated_branch,
            state="suppressed_by_master" if str(reason).startswith("master_") else "route_exhausted",
            state_reason=reason,
            round_index=round_index,
        )
        updated_branch["route_richness_score"] = _route_richness_score_for_branch(updated_branch)
        updated_branch["family_contribution_summary"] = {
            "planner_family": str(updated_branch.get("planner_family") or "heuristic"),
            "evidence_node_count": len(list(updated_branch.get("evidence_node_ids") or [])),
            "route_yield": round(float(updated_branch.get("route_yield") or 0.0), 4),
            "covered_slot_count": len(list(updated_branch.get("covered_slots") or [])),
        }
        return {
            "branch": updated_branch,
            "step": {
                "probe_id": probe["probe_id"],
                "label": probe["label"],
                "step_number": round_index,
                "bucket_key": position_to_bucket(current_position)["key"],
                "target_bucket_keys": bucket_keys[:6],
                "candidate_ids": [],
                "followed_highway_targets": [],
                "matches": [],
                "satisfaction_score": 0.0,
                "stop_reason": reason,
                "route_decision": {},
                "route_trace": [dict(item) for item in list(updated_branch.get("route_trace") or [])[-6:]],
                "active_destination": _canonical_active_destination(updated_branch.get("active_destination")),
                "route_state": str(updated_branch.get("route_state") or ""),
                "elapsed_ms": round((time.perf_counter() - round_started_at) * 1000.0, 2),
            },
            "shared_topic": None,
            "visited_bucket_key": position_to_bucket(current_position)["key"],
            "node_cache_updates": {},
            "top_matches": [],
            "round_progress": False,
            "query_class": query_class,
            "applied_actions": applied_actions,
        }

    if terminate_reason:
        return _terminal_branch(terminate_reason)
    if not active_destination:
        updated_branch = dict(branch)
        route_trace = [dict(item) for item in list(updated_branch.get("route_trace") or [])]
        route_trace.append(
            {
                "source_node_id": current_node_before,
                "target_node_id": None,
                "destination_id": None,
                "destination_key": None,
                "destination_label": None,
                "edge_type": "none",
                "move_type": "route_exhausted",
                "navigation_action": None,
                "candidate_source": None,
                "travel_performed": False,
                "route_score": 0.0,
                "route_reason": "no_execution_destinations",
                "route_yield": round(float(updated_branch.get("route_yield") or 0.0), 4),
                "destination_reached": False,
                "lease_conflict": False,
                "region_pressure": 0.0,
                "yielded_match_count": 0,
                "family_attribution": _route_family_attribution(updated_branch),
                "considered_highway": False,
                "destination_relevance": 0.0,
                "destination_progress_gain": 0.0,
                "corroboration_yield": 0.0,
                "topology_efficiency": 0.0,
                "highway_usefulness_memory": 0.5,
                "from_node_id": current_node_before,
                "to_node_id": None,
                "from_bucket_key": position_to_bucket(current_position)["key"],
                "to_bucket_key": position_to_bucket(current_position)["key"],
                "destination_before": {},
                "destination_after": {},
                "semantic_order_index": None,
                "execution_order_index": None,
                "reorder_reason": None,
                "yielded_match_ids": [],
                "studied_node_ids": [],
                "hydrated_node_ids": [],
            }
        )
        updated_branch["route_trace"] = route_trace[:24]
        updated_branch["move_types"] = list(dict.fromkeys(list(updated_branch.get("move_types") or []) + ["route_exhausted"]))[:24]
        updated_branch["route_state"] = "route_exhausted"
        updated_branch["lifecycle_stage"] = "stopped"
        updated_branch["status"] = "stopped"
        updated_branch["stop_reason"] = "route_exhausted"
        updated_branch["last_round_index"] = int(round_index)
        _bulk_mark_open_destinations(
            updated_branch,
            state="route_exhausted",
            state_reason="no_execution_destinations",
            round_index=round_index,
        )
        updated_branch["route_richness_score"] = _route_richness_score_for_branch(updated_branch)
        updated_branch["local_stop_recommendation"] = "stop_branch"
        updated_branch["family_contribution_summary"] = {
            "planner_family": str(updated_branch.get("planner_family") or "heuristic"),
            "evidence_node_count": len(list(updated_branch.get("evidence_node_ids") or [])),
            "route_yield": round(float(updated_branch.get("route_yield") or 0.0), 4),
            "covered_slot_count": len(list(updated_branch.get("covered_slots") or [])),
        }
        return {
            "branch": updated_branch,
            "step": {
                "probe_id": probe["probe_id"],
                "label": probe["label"],
                "step_number": round_index,
                "bucket_key": position_to_bucket(current_position)["key"],
                "target_bucket_keys": bucket_keys[:6],
                "candidate_ids": [],
                "followed_highway_targets": [],
                "matches": [],
                "satisfaction_score": 0.0,
                "stop_reason": "route_exhausted",
                "route_decision": {},
                "route_trace": [dict(item) for item in list(updated_branch.get("route_trace") or [])[-6:]],
                "active_destination": None,
                "route_state": "route_exhausted",
                "elapsed_ms": round((time.perf_counter() - round_started_at) * 1000.0, 2),
            },
            "shared_topic": None,
            "visited_bucket_key": position_to_bucket(current_position)["key"],
            "node_cache_updates": {},
            "top_matches": [],
            "round_progress": False,
            "query_class": query_class,
            "applied_actions": applied_actions,
        }

    candidate_sources: dict[str, list[str]] = defaultdict(list)
    candidate_map: dict[str, dict[str, Any]] = {}

    def _register_candidates(items: list[dict[str, Any]], source_label: str) -> None:
        for candidate in list(items or []):
            node_id = str(candidate.get("id") or "").strip()
            if not node_id or not is_answer_eligible(candidate):
                continue
            candidate_map.setdefault(node_id, candidate)
            candidate_sources[node_id].append(source_label)

    _register_candidates(
        query_nearby_navigation(
            current_position,
            radius=radius,
            limit=int(branch["budget"]["max_candidate_reads"]),
        ),
        "nearby_radius",
    )

    allow_adjacent = query.allow_adjacent_bucket_expansion and bucket_keys and (
        query_class in {"broad_summary", "document_lookup"} or len(candidate_map) < max(8, query.max_matches)
    )
    if allow_adjacent:
        _register_candidates(
            fetch_nav_by_coarse_bucket_keys(bucket_keys, limit=int(branch["budget"]["max_candidate_reads"])),
            "adjacent_bucket",
        )

    if current_node_payload:
        if int(branch["budget"]["max_highway_hops"] or 0) > int(branch.get("highway_hops_taken") or 0):
            explicit_highway_targets = [
                str(link.get("target_node_id") or "").strip()
                for link in list(current_node_payload.get("highways") or [])[:6]
                if str(link.get("target_node_id") or "").strip()
            ]
            _register_candidates(fetch_nodes_by_ids(explicit_highway_targets[:12], include_raw_text=False), "route_highway")
        explicit_link_targets = [
            str(link.get("target_node_id") or "").strip()
            for link in list(current_node_payload.get("links") or [])[:8]
            if str(link.get("target_node_id") or "").strip()
        ]
        _register_candidates(fetch_nodes_by_ids(explicit_link_targets[:12], include_raw_text=False), "route_link")

    allow_document_anchors = query.allow_document_anchor_expansion and bucket_keys and (
        query_class in {"relation_fact", "style_values", "broad_summary", "document_lookup"} or goal in {"history", "family", "father", "partner", "mentor", "sibling", "company_founding", "documents"}
    )
    if allow_document_anchors:
        _register_candidates(fetch_nav_by_coarse_bucket_keys(bucket_keys, limit=6, document_anchor_only=True), "document_anchor")

    hinted_target_ids = list(dict.fromkeys(action_highway_targets + action_link_targets + action_hydrate_ids))[:12]
    if hinted_target_ids:
        for candidate in fetch_nodes_by_ids(hinted_target_ids, include_raw_text=False):
            if not is_answer_eligible(candidate):
                continue
            candidate_map.setdefault(candidate["id"], candidate)
            if candidate["id"] in action_highway_targets:
                candidate_sources[candidate["id"]].append("action_highway")
            if candidate["id"] in action_link_targets:
                candidate_sources[candidate["id"]].append("action_link")
            if candidate["id"] in action_hydrate_ids:
                candidate_sources[candidate["id"]].append("action_hydrate")

    if goal in {"name", "birthplace", "residence", "family", "father", "partner", "mentor", "sibling", "role", "projects", "style", "values", "history"}:
        core_limit = 8
        if query_class == "relation_fact":
            core_limit = 3
        elif query_class == "style_values":
            core_limit = 4
        _register_candidates(
            fetch_nodes_by_ids(_identity_core_candidate_ids(identity_context, limit=core_limit), include_raw_text=False),
            "identity_core",
        )
        _register_candidates(
            fetch_nodes_by_ids(_goal_support_candidate_ids(identity_context, str(probe.get("goal") or ""), limit=10), include_raw_text=False),
            "goal_support",
        )

    temporal_terms = _explicit_temporal_terms(query.query_text)
    if goal == "history" and temporal_terms:
        _register_candidates(
            fetch_nodes_by_text_terms(temporal_terms, limit=max(query.max_matches, 16), include_raw_text=False),
            "exact_temporal",
        )
    goal_text_terms = _goal_text_terms_for_goal(goal)
    if goal_text_terms:
        _register_candidates(
            fetch_nodes_by_text_terms(
                list(goal_text_terms),
                limit=max(min(query.max_matches * 2, 24), 12),
                include_raw_text=False,
            ),
            "goal_text",
        )
        if goal in {"style", "values", "company_founding"}:
            _register_candidates(
                _subject_anchored_goal_text_nodes(
                    goal,
                    tuple(goal_text_terms),
                    identity_context,
                    limit=max(min(query.max_matches * 2, 24), 12),
                ),
                "goal_subject_text",
            )

    if query.allow_highway_expansion:
        highway_targets: list[str] = []
        for candidate in list(candidate_map.values()):
            for highway in list(candidate.get("highways") or [])[:4]:
                target = str(highway.get("target_node_id") or "")
                if target:
                    highway_targets.append(target)
        _register_candidates(fetch_nodes_by_ids(list(dict.fromkeys(highway_targets))[:12], include_raw_text=False), "highway_neighbor")

    branch_for_route = dict(branch)
    branch_for_route["active_destination"] = dict(active_destination)
    branch_for_route["semantic_destination_queue"] = [dict(item) for item in semantic_destination_queue]
    branch_for_route["execution_destination_queue"] = [dict(item) for item in execution_destination_queue]
    branch_for_route["destination_execution_index"] = destination_execution_index
    execution_destination_queue, destination_execution_index, reorder_event = _maybe_reorder_execution_destinations(
        probe=probe,
        branch=branch_for_route,
        semantic_destination_queue=semantic_destination_queue,
        execution_destination_queue=execution_destination_queue,
        execution_index=destination_execution_index,
        candidate_map=candidate_map,
        candidate_sources=candidate_sources,
        blackboard=blackboard,
        current_position=current_position,
    )
    active_destination = (
        dict(execution_destination_queue[destination_execution_index])
        if execution_destination_queue and destination_execution_index < len(execution_destination_queue)
        else {}
    )
    branch_for_route["active_destination"] = dict(active_destination)
    branch_for_route["execution_destination_queue"] = [dict(item) for item in execution_destination_queue]
    branch_for_route["destination_execution_index"] = destination_execution_index

    route_decision, route_target_candidate = _choose_backend_route_move(
        probe=probe,
        branch=branch_for_route,
        candidate_map=candidate_map,
        candidate_sources=candidate_sources,
        blackboard=blackboard,
        current_position=current_position,
    )
    if str(route_decision.get("navigation_action") or "") == "expand_radius":
        radius = min(0.42, max(radius, radius + 0.03))

    route_anchor_position = dict(current_position)
    route_anchor_node_id = current_node_before
    route_anchor_candidate = dict(route_target_candidate or {})
    if route_anchor_candidate:
        anchor_position = dict(route_anchor_candidate.get("final_position") or {})
        if anchor_position:
            route_anchor_position = anchor_position
        route_anchor_node_id = str(route_anchor_candidate.get("id") or route_anchor_node_id or "") or None
        anchor_bucket_key = str((route_anchor_candidate.get("bucket") or {}).get("key") or "")
        if anchor_bucket_key and anchor_bucket_key not in bucket_keys:
            bucket_keys.append(anchor_bucket_key)
        _register_candidates(
            query_nearby_navigation(
                route_anchor_position,
                radius=radius,
                limit=int(branch["budget"]["max_candidate_reads"]),
            ),
            "route_anchor_radius",
        )

    ranking_probe = {
        **dict(probe),
        "landing_position": dict(route_anchor_position),
        "base_position": dict(route_anchor_position),
        "search_radius": radius,
    }
    ranked: list[dict[str, Any]] = []
    node_cache_updates: dict[str, dict[str, Any]] = {}
    for candidate in candidate_map.values():
        node_cache_updates[candidate["id"]] = candidate
        sources = list(dict.fromkeys(candidate_sources.get(candidate["id"], [])))
        ranked.append(rank_candidate(ranking_probe, candidate, sources, identity_context=identity_context))
    ranked.sort(key=lambda item: (-item["raw_score"], item["node_id"]))
    hydrate_limit = min(
        int(branch["budget"]["max_candidate_reads"]),
        max(query.max_matches * 2, int(branch["budget"]["max_fulltexts"]) * 2, 12),
    )
    rerank_pool = _prepare_rerank_pool(ranked, hydrate_limit=hydrate_limit)
    top_matches = rerank_hydrated_matches(
        ranking_probe,
        rerank_pool,
        hydrate_limit=hydrate_limit,
        max_nodes_fulltext=int(branch["budget"]["max_fulltexts"]),
        identity_context=identity_context,
    )[: query.max_matches]
    satisfaction = compute_satisfaction(top_matches)
    center_bucket_key = position_to_bucket(route_anchor_position)["key"]

    updated_branch = dict(branch)
    updated_branch["search_radius"] = round(radius, 4)
    updated_branch["last_round_index"] = int(round_index)
    updated_branch["semantic_destination_queue"] = [dict(item) for item in semantic_destination_queue]
    updated_branch["execution_destination_queue"] = [dict(item) for item in execution_destination_queue]
    updated_branch["destination_execution_index"] = destination_execution_index
    updated_branch["destination_reorder_reason"] = str((reorder_event or {}).get("reorder_reason") or updated_branch.get("destination_reorder_reason") or "").strip() or None
    reorder_history = [dict(item) for item in list(updated_branch.get("destination_reorder_history") or []) if isinstance(item, dict)]
    if reorder_event:
        reorder_history.append(
            {
                "round_index": round_index,
                "reorder_reason": str(reorder_event.get("reorder_reason") or ""),
                "reorder_from_label": str(reorder_event.get("reorder_from_label") or ""),
                "reorder_to_label": str(reorder_event.get("reorder_to_label") or ""),
                "execution_order_index": destination_execution_index,
            }
        )
    updated_branch["destination_reorder_history"] = reorder_history[-12:]
    updated_branch["visited_bucket_keys"] = list(
        dict.fromkeys(list(branch["visited_bucket_keys"]) + [bucket_key for bucket_key in [center_bucket_key, *bucket_keys] if str(bucket_key).strip()])
    )
    updated_branch["visited_node_ids"] = list(
        dict.fromkeys(list(branch["visited_node_ids"]) + ([str(route_anchor_node_id)] if route_anchor_node_id else []) + [match["node_id"] for match in top_matches])
    )
    updated_branch["candidate_node_ids"] = list(dict.fromkeys(str(node_id) for node_id in candidate_map.keys() if str(node_id).strip()))[:24]
    studied_round_ids = list(
        dict.fromkeys(
            ([str(route_anchor_node_id)] if route_anchor_node_id else [])
            + [str(match.get("node_id") or "") for match in top_matches if str(match.get("node_id") or "").strip()]
        )
    )
    hydrated_round_ids = list(
        dict.fromkeys(
            [str(match.get("node_id") or "") for match in rerank_pool if str(match.get("node_id") or "").strip()]
            + [str(item).strip() for item in action_hydrate_ids if str(item).strip()]
        )
    )
    updated_branch["studied_node_ids"] = list(dict.fromkeys(list(branch.get("studied_node_ids") or []) + studied_round_ids))[:24]
    updated_branch["hydrated_node_ids"] = list(dict.fromkeys(list(branch.get("hydrated_node_ids") or []) + hydrated_round_ids))[:24]
    updated_branch["studied_node_count"] = len(list(updated_branch.get("studied_node_ids") or []))
    updated_branch["hydrated_node_count"] = len(list(updated_branch.get("hydrated_node_ids") or []))
    updated_branch["evidence_node_ids"] = list(dict.fromkeys(list(branch["evidence_node_ids"]) + [match["node_id"] for match in top_matches]))
    updated_branch["planned_actions"] = applied_actions
    updated_branch["recommended_next_actions"] = []
    current_region = _region_descriptor_from_candidate(
        route_anchor_candidate or current_node_payload,
        fallback_probe=probe,
        destination=active_destination or None,
    )
    updated_branch["current_region"] = current_region
    updated_branch["current_node_id"] = str(route_anchor_node_id or (top_matches[0] if top_matches else {}).get("node_id") or updated_branch.get("current_node_id") or "") or None
    traversed_nodes = list(updated_branch.get("traversed_nodes") or [])
    if updated_branch.get("current_node_id"):
        traversed_nodes.append(str(updated_branch["current_node_id"]))
    updated_branch["traversed_nodes"] = list(dict.fromkeys(traversed_nodes))[:24]
    traversed_edges = list(updated_branch.get("traversed_edges") or [])
    visited_edge_refs = list(updated_branch.get("visited_edge_refs") or [])
    move_types = list(updated_branch.get("move_types") or [])
    move_type = str(route_decision.get("move_type") or "")
    if reorder_event:
        move_types.append("reorder")
    if move_type:
        move_types.append(move_type)
    edge_type = str(route_decision.get("edge_type") or "")
    traveled = bool(route_decision.get("travel_performed"))
    if traveled and edge_type in {"highway", "link", "local"} and route_decision.get("target_node_id"):
        traversed_edge = {
            "source_node_id": route_decision.get("source_node_id"),
            "target_node_id": route_decision.get("target_node_id"),
            "edge_type": edge_type,
            "move_type": route_decision.get("move_type"),
            "route_score": route_decision.get("route_score"),
            "destination_id": route_decision.get("destination_id"),
            "destination_key": route_decision.get("destination_key"),
        }
        traversed_edges.append(traversed_edge)
        visited_edge_refs.append(dict(traversed_edge))
    updated_branch["traversed_edges"] = traversed_edges[:24]
    updated_branch["visited_edge_refs"] = visited_edge_refs[:24]
    updated_branch["move_types"] = move_types[:24]
    updated_branch["highway_hops_taken"] = int(updated_branch.get("highway_hops_taken") or 0) + (1 if traveled and edge_type == "highway" else 0)
    updated_branch["link_hops_taken"] = int(updated_branch.get("link_hops_taken") or 0) + (1 if traveled and edge_type == "link" else 0)
    updated_branch["local_hops_taken"] = int(updated_branch.get("local_hops_taken") or 0) + (1 if traveled and edge_type == "local" else 0)
    updated_branch["highway_traversed_count"] = int(updated_branch.get("highway_traversed_count") or 0) + (1 if traveled and edge_type == "highway" else 0)
    updated_branch["link_traversed_count"] = int(updated_branch.get("link_traversed_count") or 0) + (1 if traveled and edge_type == "link" else 0)
    updated_branch["local_traversed_count"] = int(updated_branch.get("local_traversed_count") or 0) + (1 if traveled and edge_type == "local" else 0)
    updated_branch["considered_highway_count"] = int(updated_branch.get("considered_highway_count") or 0) + (1 if bool(route_decision.get("considered_highway")) else 0)
    covered_slots = list(updated_branch.get("covered_slots") or [])
    if top_matches:
        covered_slots.append(_goal_to_slot(str(updated_branch.get("goal") or goal)))
    updated_branch["covered_slots"] = list(dict.fromkeys(slot for slot in covered_slots if str(slot).strip()))[:8]
    route_yield = max(
        float(updated_branch.get("route_yield") or 0.0),
        min(1.0, max(float(top_matches[0]["raw_score"]) if top_matches else 0.0, float(satisfaction or 0.0))),
    )
    updated_branch["route_yield"] = round(route_yield, 4)

    shared_topic = None
    if top_matches:
        shared_topic = {
            "topic": branch["goal"],
            "node_ids": [match["node_id"] for match in top_matches[:3]],
            "confidence": float(top_matches[0]["raw_score"]),
            "status": "fulfilled" if float(top_matches[0]["raw_score"]) >= success_threshold else "covered",
        }

    destination_before = dict(active_destination)
    destination_reached = _route_destination_match_for_node(route_anchor_candidate or current_node_payload, destination_before)
    if not destination_reached and destination_before and top_matches:
        destination_reached = any(_route_destination_match_for_node(match.get("node") or {}, destination_before) for match in top_matches[:4])

    route_decision["yielded_match_count"] = len(top_matches)
    route_decision["yielded_match_ids"] = [str(match.get("node_id") or "") for match in top_matches if str(match.get("node_id") or "").strip()][:8]
    route_decision["studied_node_ids"] = studied_round_ids[:8]
    route_decision["hydrated_node_ids"] = hydrated_round_ids[:8]
    route_decision["route_yield"] = round(route_yield, 4)
    route_decision["destination_reached"] = destination_reached
    route_decision["from_node_id"] = current_node_before
    route_decision["to_node_id"] = route_anchor_node_id if route_anchor_node_id and route_anchor_node_id != current_node_before else route_decision.get("target_node_id")
    route_decision["from_bucket_key"] = position_to_bucket(current_position)["key"]
    route_decision["to_bucket_key"] = center_bucket_key
    route_decision["destination_before"] = dict(destination_before)
    route_decision["semantic_order_index"] = _destination_semantic_index(semantic_destination_queue, destination_before)
    route_decision["execution_order_index"] = destination_execution_index
    route_decision["reorder_reason"] = str((reorder_event or {}).get("reorder_reason") or "").strip() or None

    stop_for_step = None
    execution_destination_after = [dict(item) for item in execution_destination_queue]
    destination_after = dict(destination_before)
    terminal_route_exhausted = False
    destination_progress = dict(updated_branch.get("destination_progress") or {})
    reached_destination_ids = [str(item) for item in list(destination_progress.get("reached_destination_ids") or []) if str(item).strip()]
    active_destination_id = str(destination_before.get("destination_id") or "").strip()
    if destination_reached and active_destination_id and active_destination_id not in reached_destination_ids:
        reached_destination_ids.append(active_destination_id)
    remaining_destination_ids = [
        str(item.get("destination_id") or "").strip()
        for index, item in enumerate(execution_destination_after)
        if index >= destination_execution_index and str(item.get("destination_id") or "").strip() and str(item.get("destination_id") or "").strip() not in reached_destination_ids
    ]
    if destination_reached:
        if destination_execution_index + 1 < len(execution_destination_after):
            destination_execution_index += 1
            destination_after = dict(execution_destination_after[destination_execution_index] or {})
        else:
            destination_after = {}
    elif not top_matches and not traveled:
        if destination_execution_index + 1 < len(execution_destination_after):
            destination_execution_index += 1
            destination_after = dict(execution_destination_after[destination_execution_index] or {})
        else:
            destination_after = {}
            terminal_route_exhausted = True
    updated_branch["destination_execution_index"] = destination_execution_index
    updated_branch["execution_destination_queue"] = execution_destination_after
    updated_branch["active_destination"] = dict(destination_after)
    _ensure_branch_destination_resolution(updated_branch, round_index=round_index)
    route_decision["destination_after"] = dict(destination_after)

    route_trace = [dict(item) for item in list(updated_branch.get("route_trace") or [])]
    if reorder_event:
        route_trace.append(dict(reorder_event))
    route_trace.append(dict(route_decision))
    if destination_reached:
        _set_destination_resolution_state(
            updated_branch,
            destination_before,
            state="reached",
            state_reason="destination_reached",
            round_index=round_index,
            execution_index=max(0, destination_execution_index - (1 if destination_after else 0)),
        )
        if destination_after:
            _set_destination_resolution_state(
                updated_branch,
                destination_after,
                state="active",
                state_reason="advanced_after_reached",
                round_index=round_index,
                execution_index=destination_execution_index,
            )
        route_trace.append(
            {
                "source_node_id": route_decision.get("to_node_id") or route_decision.get("target_node_id"),
                "target_node_id": None,
                "destination_id": str(destination_before.get("destination_id") or "") or None,
                "destination_key": _destination_lease_key(destination_before),
                "destination_label": str(destination_before.get("label") or "") or None,
                "edge_type": "none",
                "move_type": "destination_reached",
                "navigation_action": None,
                "candidate_source": None,
                "travel_performed": False,
                "route_score": round(float(route_decision.get("route_score") or 0.0), 4),
                "route_reason": "destination_reached",
                "route_yield": round(route_yield, 4),
                "destination_reached": True,
                "lease_conflict": False,
                "region_pressure": 0.0,
                "yielded_match_count": len(top_matches),
                "yielded_match_ids": route_decision.get("yielded_match_ids") or [],
                "studied_node_ids": studied_round_ids[:8],
                "hydrated_node_ids": hydrated_round_ids[:8],
                "family_attribution": _route_family_attribution(updated_branch),
                "considered_highway": False,
                "destination_relevance": round(float(route_decision.get("destination_relevance") or 0.0), 4),
                "destination_progress_gain": 1.0,
                "corroboration_yield": round(float(route_decision.get("corroboration_yield") or 0.0), 4),
                "topology_efficiency": round(float(route_decision.get("topology_efficiency") or 0.0), 4),
                "highway_usefulness_memory": round(float(route_decision.get("highway_usefulness_memory") or 0.5), 4),
                "from_node_id": route_decision.get("to_node_id") or route_decision.get("target_node_id"),
                "to_node_id": None,
                "from_bucket_key": center_bucket_key,
                "to_bucket_key": center_bucket_key,
                "destination_before": dict(destination_before),
                "destination_after": dict(destination_after),
                "semantic_order_index": _destination_semantic_index(semantic_destination_queue, destination_before),
                "execution_order_index": max(0, destination_execution_index - (1 if destination_after else 0)),
                "reorder_reason": None,
            }
        )
        updated_branch["move_types"] = list(dict.fromkeys(list(updated_branch.get("move_types") or []) + ["destination_reached"]))[:24]
    elif terminal_route_exhausted:
        _set_destination_resolution_state(
            updated_branch,
            destination_before,
            state="route_exhausted",
            state_reason="route_exhausted",
            round_index=round_index,
            execution_index=destination_execution_index,
        )
        route_trace.append(
            {
                "source_node_id": route_decision.get("to_node_id") or route_decision.get("target_node_id") or current_node_before,
                "target_node_id": None,
                "destination_id": str(destination_before.get("destination_id") or "") or None,
                "destination_key": _destination_lease_key(destination_before),
                "destination_label": str(destination_before.get("label") or "") or None,
                "edge_type": "none",
                "move_type": "route_exhausted",
                "navigation_action": None,
                "candidate_source": None,
                "travel_performed": False,
                "route_score": round(float(route_decision.get("route_score") or 0.0), 4),
                "route_reason": "route_exhausted",
                "route_yield": round(route_yield, 4),
                "destination_reached": False,
                "lease_conflict": False,
                "region_pressure": 0.0,
                "yielded_match_count": len(top_matches),
                "yielded_match_ids": route_decision.get("yielded_match_ids") or [],
                "studied_node_ids": studied_round_ids[:8],
                "hydrated_node_ids": hydrated_round_ids[:8],
                "family_attribution": _route_family_attribution(updated_branch),
                "considered_highway": False,
                "destination_relevance": round(float(route_decision.get("destination_relevance") or 0.0), 4),
                "destination_progress_gain": round(float(route_decision.get("destination_progress_gain") or 0.0), 4),
                "corroboration_yield": round(float(route_decision.get("corroboration_yield") or 0.0), 4),
                "topology_efficiency": round(float(route_decision.get("topology_efficiency") or 0.0), 4),
                "highway_usefulness_memory": round(float(route_decision.get("highway_usefulness_memory") or 0.5), 4),
                "from_node_id": route_decision.get("to_node_id") or route_decision.get("target_node_id") or current_node_before,
                "to_node_id": None,
                "from_bucket_key": center_bucket_key,
                "to_bucket_key": center_bucket_key,
                "destination_before": dict(destination_before),
                "destination_after": {},
                "semantic_order_index": _destination_semantic_index(semantic_destination_queue, destination_before),
                "execution_order_index": destination_execution_index,
                "reorder_reason": None,
            }
        )
        updated_branch["move_types"] = list(dict.fromkeys(list(updated_branch.get("move_types") or []) + ["route_exhausted"]))[:24]
    updated_branch["route_trace"] = route_trace[:24]

    if terminal_route_exhausted:
        updated_branch["status"] = "stopped"
        stop_for_step = "route_exhausted"
        updated_branch["stop_reason"] = stop_for_step
    elif top_matches and float(top_matches[0]["raw_score"]) >= success_threshold:
        updated_branch["status"] = "satisfied"
        stop_for_step = "goal_satisfied"
        updated_branch["stop_reason"] = stop_for_step
    elif top_matches and satisfaction >= success_threshold:
        updated_branch["status"] = "satisfied"
        stop_for_step = "shared_context_sufficient"
        updated_branch["stop_reason"] = stop_for_step
    elif top_matches and query_class in {"direct_fact", "relation_fact"} and float(top_matches[0]["raw_score"]) >= max(float(mode_config.get("direct_fact_floor") or 0.64), success_threshold - 0.08):
        updated_branch["status"] = "satisfied"
        stop_for_step = "high_confidence_direct_fact"
        updated_branch["stop_reason"] = stop_for_step
    else:
        updated_branch["status"] = "active"
        updated_branch["stop_reason"] = None

    remaining_destination_ids = [
        str(item.get("destination_id") or "").strip()
        for index, item in enumerate(execution_destination_after)
        if index >= destination_execution_index and str(item.get("destination_id") or "").strip() and str(item.get("destination_id") or "").strip() not in reached_destination_ids
    ]
    no_active_destination = _canonical_active_destination(updated_branch.get("active_destination")) is None
    if updated_branch["status"] == "active" and no_active_destination and not remaining_destination_ids:
        stop_for_step = "destination_reached_no_remaining_destinations" if destination_reached else "route_exhausted"
        updated_branch["status"] = "stopped"
        updated_branch["stop_reason"] = stop_for_step
        latest_trace = [dict(item) for item in list(updated_branch.get("route_trace") or [])]
        latest_move_type = str((latest_trace[-1] if latest_trace else {}).get("move_type") or "")
        if latest_move_type not in {"destination_reached", "route_exhausted"}:
            latest_trace.append(
                {
                    "source_node_id": route_decision.get("to_node_id") or route_decision.get("target_node_id") or current_node_before,
                    "target_node_id": None,
                    "destination_id": str(destination_before.get("destination_id") or "") or None,
                    "destination_key": _destination_lease_key(destination_before),
                    "destination_label": str(destination_before.get("label") or "") or None,
                    "edge_type": "none",
                    "move_type": "route_exhausted",
                    "navigation_action": None,
                    "candidate_source": None,
                    "travel_performed": False,
                    "route_score": round(float(route_decision.get("route_score") or 0.0), 4),
                    "route_reason": stop_for_step,
                    "route_yield": round(route_yield, 4),
                    "destination_reached": bool(destination_reached),
                    "lease_conflict": False,
                    "region_pressure": 0.0,
                    "yielded_match_count": len(top_matches),
                    "yielded_match_ids": route_decision.get("yielded_match_ids") or [],
                    "studied_node_ids": studied_round_ids[:8],
                    "hydrated_node_ids": hydrated_round_ids[:8],
                    "family_attribution": _route_family_attribution(updated_branch),
                    "considered_highway": False,
                    "destination_relevance": round(float(route_decision.get("destination_relevance") or 0.0), 4),
                    "destination_progress_gain": round(float(route_decision.get("destination_progress_gain") or 0.0), 4),
                    "corroboration_yield": round(float(route_decision.get("corroboration_yield") or 0.0), 4),
                    "topology_efficiency": round(float(route_decision.get("topology_efficiency") or 0.0), 4),
                    "highway_usefulness_memory": round(float(route_decision.get("highway_usefulness_memory") or 0.5), 4),
                    "from_node_id": route_decision.get("to_node_id") or route_decision.get("target_node_id") or current_node_before,
                    "to_node_id": None,
                    "from_bucket_key": center_bucket_key,
                    "to_bucket_key": center_bucket_key,
                    "destination_before": dict(destination_before),
                    "destination_after": {},
                    "semantic_order_index": _destination_semantic_index(semantic_destination_queue, destination_before),
                    "execution_order_index": destination_execution_index,
                    "reorder_reason": None,
                }
            )
            updated_branch["route_trace"] = latest_trace[:24]
    destination_progress["reached_destination_ids"] = reached_destination_ids[:8]
    destination_progress["remaining_destination_ids"] = remaining_destination_ids[:8]
    destination_progress["active_destination_id"] = str((updated_branch.get("active_destination") or {}).get("destination_id") or "").strip() or None
    destination_progress["last_round_satisfaction"] = round(float(satisfaction or 0.0), 4)
    destination_progress["destination_reached"] = destination_reached
    updated_branch["destination_progress"] = destination_progress

    if updated_branch["status"] == "satisfied":
        if destination_before:
            _set_destination_resolution_state(
                updated_branch,
                destination_before,
                state="reached",
                state_reason=stop_for_step or "goal_satisfied",
                round_index=round_index,
                execution_index=max(0, destination_execution_index - (1 if destination_reached and destination_after else 0)),
            )
        if stop_for_step in {"goal_satisfied", "shared_context_sufficient", "high_confidence_direct_fact"}:
            _bulk_mark_open_destinations(
                updated_branch,
                state="superseded_by_stronger_branch",
                state_reason=stop_for_step,
                round_index=round_index,
            )
        updated_branch["route_state"] = "goal_satisfied"
        updated_branch["lifecycle_stage"] = "satisfied"
    elif updated_branch["status"] == "stopped":
        _bulk_mark_open_destinations(
            updated_branch,
            state="route_exhausted",
            state_reason=stop_for_step or "route_exhausted",
            round_index=round_index,
        )
        updated_branch["route_state"] = "route_exhausted"
        updated_branch["lifecycle_stage"] = "stopped"
    elif destination_reached and updated_branch.get("active_destination"):
        updated_branch["route_state"] = "routing"
        updated_branch["lifecycle_stage"] = "routing"
    elif destination_reached:
        updated_branch["route_state"] = "evidence_holding"
        updated_branch["lifecycle_stage"] = "evidence_holding"
    else:
        if updated_branch.get("active_destination"):
            _set_destination_resolution_state(
                updated_branch,
                updated_branch.get("active_destination"),
                state="active",
                state_reason="round_continues",
                round_index=round_index,
                execution_index=int(updated_branch.get("destination_execution_index") or 0),
            )
        updated_branch["route_state"] = "routing"
        updated_branch["lifecycle_stage"] = "routing"
    updated_branch["route_richness_score"] = _route_richness_score_for_branch(updated_branch)
    updated_branch["local_stop_recommendation"] = stop_for_step or _branch_local_stop_recommendation(updated_branch, query_class=query_class)
    controller_recommendation = _branch_controller_recommendation(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
        branch=updated_branch,
        blackboard=blackboard,
    )
    updated_branch = _apply_controller_recommendation(updated_branch, controller_recommendation)
    updated_branch = _finalize_terminal_branch_destinations(updated_branch, round_index=round_index)
    updated_branch["recommended_next_actions"] = list(dict.fromkeys(list(controller_recommendation.get("requested_actions") or [])))[:3]
    updated_branch["family_contribution_summary"] = {
        "planner_family": str(updated_branch.get("planner_family") or "heuristic"),
        "evidence_node_count": len(list(updated_branch.get("evidence_node_ids") or [])),
        "route_yield": round(float(updated_branch.get("route_yield") or 0.0), 4),
        "covered_slot_count": len(list(updated_branch.get("covered_slots") or [])),
    }

    return {
        "branch": updated_branch,
        "step": {
            "probe_id": probe["probe_id"],
            "label": probe["label"],
            "step_number": round_index,
            "bucket_key": center_bucket_key,
            "target_bucket_keys": bucket_keys[:6],
            "candidate_ids": list(candidate_map.keys())[: int(branch["budget"]["max_candidate_reads"])],
            "followed_highway_targets": [str(route_decision.get("target_node_id") or "")] if edge_type == "highway" and traveled and str(route_decision.get("target_node_id") or "").strip() else [],
            "matches": top_matches[:6],
            "satisfaction_score": satisfaction,
            "stop_reason": stop_for_step,
            "route_decision": dict(route_decision),
            "route_trace": [dict(item) for item in updated_branch.get("route_trace", [])[-6:]],
            "active_destination": _canonical_active_destination(updated_branch.get("active_destination")),
            "route_state": str(updated_branch.get("route_state") or ""),
            "elapsed_ms": round((time.perf_counter() - round_started_at) * 1000.0, 2),
        },
        "shared_topic": shared_topic,
        "visited_bucket_key": center_bucket_key,
        "node_cache_updates": node_cache_updates,
        "top_matches": top_matches,
        "round_progress": bool(top_matches or traveled or destination_reached),
        "query_class": query_class,
        "applied_actions": applied_actions,
    }


def _build_follow_up_candidates(query_text: str, context: dict[str, Any] | None, shared_evidence: dict[str, Any] | None) -> list[dict[str, Any]]:
    aspects = set(detect_query_aspects(query_text))
    subject = _memory_subject_label(query_text)
    sections = {
        str(section.get("key") or ""): section
        for section in list((context or {}).get("structured_sections") or [])
        if section
    }
    suggestions: list[dict[str, Any]] = []

    def add_suggestion(query: str, reason: str, priority: float) -> None:
        if any(item["query"] == query for item in suggestions):
            return
        suggestions.append({"query": query, "reason": reason, "priority": round(priority, 3)})

    if "work" in sections and "projects" not in aspects:
        add_suggestion(f"Su cosa lavora esattamente {subject}?", "project_detail_gap", 0.88)
    if "relationships" in sections and "partner" not in aspects:
        add_suggestion(f"Chi sono le relazioni piu importanti di {subject}?", "relationship_expansion", 0.84)
    if "style" in sections and "style" not in aspects:
        add_suggestion(f"Come comunica {subject} nei dettagli?", "style_expansion", 0.8)
    if "history" in sections and "history" not in aspects:
        add_suggestion(f"Quali sono gli snodi principali della storia di {subject}?", "history_expansion", 0.78)
    if "identity" in sections and "residence" not in aspects:
        add_suggestion(f"Dove vive adesso {subject}?", "identity_follow_up", 0.72)
    if not suggestions and list((shared_evidence or {}).get("covered_goals") or []):
        add_suggestion("Qual e il prossimo aspetto piu utile da approfondire?", "generic_follow_up", 0.6)
    suggestions.sort(key=lambda item: (-float(item["priority"]), item["query"]))
    return suggestions[:4]


def _build_blackboard(
    *,
    query_text: str,
    retrieval_mode: str,
    shared_topics: dict[str, dict[str, Any]],
    branches: list[dict[str, Any]],
    context: dict[str, Any] | None,
    visited_node_ids: set[str],
    visited_bucket_keys: set[str],
    master_state: dict[str, Any] | None = None,
    worker_registry: dict[str, Any] | None = None,
    branch_overlaps: list[dict[str, Any]] | None = None,
    follow_up_candidates: list[dict[str, Any]] | None = None,
    contradiction_flags: list[str] | None = None,
    extra_worker_reports: list[dict[str, Any]] | None = None,
    answer_strands: list[dict[str, Any]] | None = None,
    planner_seed_runtime: dict[str, Any] | None = None,
    seed_goal_coverage: dict[str, Any] | None = None,
    seed_destination_presence: dict[str, Any] | None = None,
) -> dict[str, Any]:
    structured_sections = list((context or {}).get("structured_sections") or [])
    facts_by_slot: dict[str, list[str]] = {}
    coverage_by_slot: dict[str, float] = {}
    for section in structured_sections:
        key = str(section.get("key") or "")
        items = [str(item).strip() for item in list(section.get("items") or []) if str(item).strip()]
        if not key or not items:
            continue
        facts_by_slot[key] = items
        coverage_by_slot[key] = round(float(section.get("confidence") or 0.0), 4)
    for topic, payload in shared_topics.items():
        slot = _goal_to_slot(topic)
        coverage_by_slot[slot] = max(round(float(payload.get("confidence") or 0.0), 4), float(coverage_by_slot.get(slot) or 0.0))
    required_slots = _required_slots_for_query(query_text)
    unresolved_slots = [slot for slot in required_slots if float(coverage_by_slot.get(slot) or 0.0) < 0.55]
    branch_summaries = [_branch_blackboard_snapshot(branch) for branch in branches]
    family_comparison = _planner_family_comparison(branches)
    merge_runtime = _merge_runtime_summary(branches)
    route_runtime = _route_runtime_summary(branches)
    closure_summary = _final_closure_summary(branches)
    master_state_payload = dict(master_state or {})
    answer_surface_state = str(master_state_payload.get("answer_surface_state") or closure_summary.get("answer_surface_state") or "not_ready")
    closure_state = str(master_state_payload.get("closure_state") or ("exploration_complete" if bool(closure_summary.get("final_closure_ready")) else "open"))
    goal_leases = {
        str(branch.get("goal") or ""): str(branch.get("branch_id") or "")
        for branch in branches
        if str(branch.get("status") or "") == "active" and str(branch.get("goal") or "").strip()
    }
    destination_leases = {}
    region_pressure: dict[str, int] = defaultdict(int)
    merge_triggers: list[dict[str, Any]] = []
    for branch in branches:
        if str(branch.get("status") or "") != "active":
            continue
        destination_key = _destination_lease_key(branch.get("active_destination") or {})
        if destination_key:
            destination_leases[destination_key] = str(branch.get("branch_id") or "")
        region_id = str((branch.get("current_region") or {}).get("region_id") or "")
        if region_id:
            region_pressure[region_id] += 1
    for left in branches:
        for right in branches:
            if str(left.get("branch_id") or "") >= str(right.get("branch_id") or ""):
                continue
            left_destination_key = _destination_lease_key(left.get("active_destination") or {})
            right_destination_key = _destination_lease_key(right.get("active_destination") or {})
            shared_traversed = sorted(
                set(str(item) for item in list(left.get("traversed_nodes") or []))
                & set(str(item) for item in list(right.get("traversed_nodes") or []))
            )
            if left_destination_key and left_destination_key == right_destination_key:
                merge_triggers.append(
                    {
                        "left_branch_id": str(left.get("branch_id") or ""),
                        "right_branch_id": str(right.get("branch_id") or ""),
                        "reason": "shared_destination_lease",
                        "destination_key": left_destination_key,
                        "shared_traversed_nodes": shared_traversed[:8],
                    }
                )
            elif len(shared_traversed) >= 3:
                merge_triggers.append(
                    {
                        "left_branch_id": str(left.get("branch_id") or ""),
                        "right_branch_id": str(right.get("branch_id") or ""),
                        "reason": "route_overlap",
                        "shared_traversed_nodes": shared_traversed[:8],
                    }
                )
    return {
        "retrieval_mode": retrieval_mode,
        "answer_surface_state": answer_surface_state,
        "closure_state": closure_state,
        "final_closure_ready": bool(master_state_payload.get("final_closure_ready", closure_summary.get("final_closure_ready"))),
        "final_closure_blockers": [dict(item) for item in list(master_state_payload.get("final_closure_blockers") or closure_summary.get("final_closure_blockers") or [])[:16]],
        "unresolved_destination_count": int(master_state_payload.get("unresolved_destination_count", closure_summary.get("unresolved_destination_count") or 0)),
        "closure_blocker_reason_histogram": dict(closure_summary.get("closure_blocker_reason_histogram") or {}),
        "required_slots": required_slots,
        "facts_by_slot": facts_by_slot,
        "coverage_by_slot": coverage_by_slot,
        "unresolved_slots": unresolved_slots,
        "worker_reports": [_build_worker_report(branch) for branch in branches] + list(extra_worker_reports or []),
        "master_state": dict(master_state or {}),
        "worker_registry": dict(worker_registry or {}),
        "branch_summaries": branch_summaries,
        "destination_resolution": {
            str(branch.get("branch_id") or ""): _clone_destination_resolution(branch.get("destination_resolution"))
            for branch in branches
            if str(branch.get("branch_id") or "").strip()
        },
        "shared_node_ids": sorted(visited_node_ids),
        "shared_bucket_keys": sorted(visited_bucket_keys),
        "branch_overlaps": list(branch_overlaps or []),
        "contradiction_flags": list(contradiction_flags or []),
        "follow_up_candidates": list(follow_up_candidates or []),
        "goal_leases": goal_leases,
        "destination_leases": destination_leases,
        "region_pressure": dict(region_pressure),
        "merge_triggers": merge_triggers,
        "family_overlap": dict(family_comparison.get("family_overlap") or {}),
        "family_divergence": dict(family_comparison.get("family_divergence") or {}),
        "family_yield": dict(family_comparison.get("family_yield") or {}),
        "family_conflicts": list(family_comparison.get("family_conflicts") or []),
        "family_contribution_summary": dict(family_comparison.get("family_contribution_summary") or {}),
        "branch_reuse_count": int(merge_runtime.get("branch_reuse_count") or 0),
        "branch_enrich_count": int(merge_runtime.get("branch_enrich_count") or 0),
        "branch_fork_count": int(merge_runtime.get("branch_fork_count") or 0),
        "dual_origin_branch_count": int(merge_runtime.get("dual_origin_branch_count") or 0),
        "merge_resolution_histogram": dict(merge_runtime.get("merge_resolution_histogram") or {}),
        "merged_strand_ids": list(merge_runtime.get("merged_strand_ids") or []),
        "enriched_strand_ids": list(merge_runtime.get("enriched_strand_ids") or []),
        "forked_strand_ids": list(merge_runtime.get("forked_strand_ids") or []),
        "route_step_count": int(route_runtime.get("route_step_count") or 0),
        "travel_step_count": int(route_runtime.get("travel_step_count") or 0),
        "highway_considered_count": int(route_runtime.get("highway_considered_count") or 0),
        "highway_traversed_count": int(route_runtime.get("highway_traversed_count") or 0),
        "link_traversed_count": int(route_runtime.get("link_traversed_count") or 0),
        "local_traversed_count": int(route_runtime.get("local_traversed_count") or 0),
        "studied_node_count": int(route_runtime.get("studied_node_count") or 0),
        "hydrated_node_count": int(route_runtime.get("hydrated_node_count") or 0),
        "route_richness_score": float(route_runtime.get("route_richness_score") or 0.0),
        "heuristic_family_route_step_ratio": float(route_runtime.get("heuristic_family_route_step_ratio") or 0.0),
        "ai_family_route_step_ratio": float(route_runtime.get("ai_family_route_step_ratio") or 0.0),
        "dual_origin_family_route_step_ratio": float(route_runtime.get("dual_origin_family_route_step_ratio") or 0.0),
        "highway_effective_use_ratio": float(route_runtime.get("highway_effective_use_ratio") or 0.0),
        "link_effective_use_ratio": float(route_runtime.get("link_effective_use_ratio") or 0.0),
        "destination_reached_ratio": float(route_runtime.get("destination_reached_ratio") or 0.0),
        "execution_reorder_count": int(route_runtime.get("execution_reorder_count") or 0),
        "execution_reorder_reasons": dict(route_runtime.get("execution_reorder_reasons") or {}),
        "answer_strands": [dict(item) for item in list(answer_strands or []) if isinstance(item, dict)],
        "planner_seed_runtime": dict(planner_seed_runtime or {}),
        "seed_goal_coverage": dict(seed_goal_coverage or {}),
        "seed_destination_presence": dict(seed_destination_presence or {}),
    }


def _section_snapshots(context: dict[str, Any] | None) -> list[dict[str, Any]]:
    snapshots: list[dict[str, Any]] = []
    for section in list((context or {}).get("structured_sections") or []):
        key = str(section.get("key") or "")
        title = str(section.get("title") or key or "section")
        items = [str(item).strip() for item in list(section.get("items") or []) if str(item).strip()]
        if not key and not items:
            continue
        snapshots.append(
            {
                "key": key,
                "title": title,
                "items": items,
                "confidence": round(float(section.get("confidence") or 0.0), 4),
                "evidence_node_ids": [str(item) for item in list(section.get("evidence_node_ids") or []) if str(item)],
            }
        )
    return snapshots


def _section_deltas(previous_snapshots: list[dict[str, Any]], current_snapshots: list[dict[str, Any]]) -> list[dict[str, Any]]:
    previous_items = {
        str(snapshot.get("key") or ""): {str(item).strip() for item in list(snapshot.get("items") or []) if str(item).strip()}
        for snapshot in previous_snapshots
    }
    deltas: list[dict[str, Any]] = []
    for snapshot in current_snapshots:
        key = str(snapshot.get("key") or "")
        items = [str(item).strip() for item in list(snapshot.get("items") or []) if str(item).strip()]
        added_items = [item for item in items if item not in previous_items.get(key, set())]
        if added_items:
            deltas.append(
                {
                    "key": key,
                    "title": str(snapshot.get("title") or key or "section"),
                    "added_items": added_items,
                    "total_items": len(items),
                }
            )
    return deltas


def _section_node_ids(section_snapshots: list[dict[str, Any]]) -> set[str]:
    return {
        str(node_id).strip()
        for section in list(section_snapshots or [])
        if isinstance(section, dict)
        for node_id in list(section.get("evidence_node_ids") or [])
        if str(node_id).strip()
    }


def _reservoir_node_ids(
    *,
    evidence_reservoir: dict[str, Any] | None,
    evidence_snippets: list[dict[str, Any]] | None,
    partial_matches: list[dict[str, Any]] | None,
) -> set[str]:
    node_ids = {
        str(entry.get("node_id") or "").strip()
        for entry in list((evidence_reservoir or {}).get("entries") or [])
        if isinstance(entry, dict) and str(entry.get("node_id") or "").strip()
    }
    node_ids.update(
        str(snippet.get("node_id") or "").strip()
        for snippet in list(evidence_snippets or [])
        if isinstance(snippet, dict) and str(snippet.get("node_id") or "").strip()
    )
    node_ids.update(
        str(match.get("node_id") or "").strip()
        for match in list(partial_matches or [])
        if isinstance(match, dict) and str(match.get("node_id") or "").strip()
    )
    return {node_id for node_id in node_ids if node_id}


def _context_token_estimate(
    *,
    section_snapshots: list[dict[str, Any]],
    context_dossier_partial: str | None,
    evidence_snippets: list[dict[str, Any]],
) -> int:
    text_parts = [str(context_dossier_partial or "")]
    for section in list(section_snapshots or []):
        text_parts.append(str(section.get("title") or section.get("key") or ""))
        text_parts.extend(str(item or "") for item in list(section.get("items") or []))
    for snippet in list(evidence_snippets or []):
        if not isinstance(snippet, dict):
            continue
        text_parts.append(str(snippet.get("text") or snippet.get("summary") or ""))
    char_count = len("\n".join(part for part in text_parts if part.strip()))
    return max(0, int((char_count + 3) // 4))


def _context_wave_source_branches(
    *,
    branches: list[dict[str, Any]],
    added_node_ids: set[str],
) -> list[dict[str, Any]]:
    source_branches: list[dict[str, Any]] = []
    fallback_branches: list[dict[str, Any]] = []
    for branch in list(branches or []):
        if not isinstance(branch, dict):
            continue
        evidence_node_ids = {
            str(node_id).strip()
            for node_id in list(branch.get("evidence_node_ids") or branch.get("studied_node_ids") or branch.get("visited_node_ids") or [])
            if str(node_id).strip()
        }
        branch_record = {
            "branch_id": str(branch.get("branch_id") or ""),
            "goal": str(branch.get("goal") or ""),
            "planner_family": str(branch.get("planner_family") or ""),
            "origin_families": [str(item) for item in list(branch.get("origin_families") or []) if str(item).strip()],
            "matched_added_node_count": len(evidence_node_ids & added_node_ids),
            "evidence_node_count": len(evidence_node_ids),
            "route_state": branch.get("route_state") or branch.get("lifecycle_stage"),
            "stop_reason": branch.get("stop_reason"),
        }
        if branch_record["matched_added_node_count"]:
            source_branches.append(branch_record)
        elif branch_record["evidence_node_count"]:
            fallback_branches.append(branch_record)
    return (source_branches or fallback_branches)[:6]


def _build_context_wave(
    *,
    wave_index: int,
    query_text: str,
    runtime_phase: str,
    section_snapshots: list[dict[str, Any]],
    section_deltas: list[dict[str, Any]],
    context_dossier_partial: str | None,
    evidence_snippets: list[dict[str, Any]],
    evidence_reservoir: dict[str, Any] | None,
    partial_matches: list[dict[str, Any]],
    branches: list[dict[str, Any]],
    previous_hot_node_ids: set[str],
    previous_reservoir_node_ids: set[str],
    previous_token_estimate: int,
    warm_state_used: bool,
    warm_state_summary: dict[str, Any] | None,
    continuity_state: str,
    document_mode: str,
    after_first_answer: bool,
    source: str,
) -> dict[str, Any]:
    current_hot_node_ids = _section_node_ids(section_snapshots)
    current_reservoir_node_ids = _reservoir_node_ids(
        evidence_reservoir=evidence_reservoir,
        evidence_snippets=evidence_snippets,
        partial_matches=partial_matches,
    )
    added_hot_nodes = sorted(current_hot_node_ids - previous_hot_node_ids)
    demoted_nodes = sorted(previous_hot_node_ids - current_hot_node_ids)
    cold_reservoir_additions = sorted((current_reservoir_node_ids - current_hot_node_ids) - previous_reservoir_node_ids)
    token_estimate = _context_token_estimate(
        section_snapshots=section_snapshots,
        context_dossier_partial=context_dossier_partial,
        evidence_snippets=evidence_snippets,
    )
    added_node_ids = set(added_hot_nodes) | set(cold_reservoir_additions)
    source_branches = _context_wave_source_branches(branches=branches, added_node_ids=added_node_ids)
    source_families = sorted(
        {
            str(branch.get("planner_family") or "").strip()
            for branch in source_branches
            if str(branch.get("planner_family") or "").strip()
        }
    )
    return {
        "wave_id": f"context_wave_{wave_index:04d}",
        "wave_index": wave_index,
        "created_at": utc_timestamp(),
        "query_text": str(query_text or ""),
        "source": str(source or "context_update"),
        "runtime_phase": str(runtime_phase or ""),
        "after_first_answer": bool(after_first_answer),
        "source_branches": source_branches,
        "source_families": source_families,
        "added_hot_nodes": added_hot_nodes,
        "added_hot_node_count": len(added_hot_nodes),
        "demoted_nodes": demoted_nodes,
        "demoted_node_count": len(demoted_nodes),
        "cold_reservoir_additions": cold_reservoir_additions,
        "cold_reservoir_addition_count": len(cold_reservoir_additions),
        "hot_node_count": len(current_hot_node_ids),
        "reservoir_node_count": len(current_reservoir_node_ids),
        "section_deltas": [dict(item) for item in list(section_deltas or []) if isinstance(item, dict)][:12],
        "section_delta_count": len(list(section_deltas or [])),
        "section_count": len(list(section_snapshots or [])),
        "token_estimate": token_estimate,
        "token_delta": token_estimate - int(previous_token_estimate or 0),
        "warm_reuse_source": "warm_packet" if warm_state_used else "cold_start",
        "warm_state_used": bool(warm_state_used),
        "warm_state_summary": dict(warm_state_summary or {}),
        "continuity_state": str(continuity_state or ""),
        "document_mode": str(document_mode or "none"),
        "dossier_chars": len(str(context_dossier_partial or "")),
    }


def _build_stream_evidence_snippets(matches: list[dict[str, Any]], limit: int = 6) -> list[dict[str, Any]]:
    snippets: list[dict[str, Any]] = []
    for match in [dict(item) for item in list(matches or []) if is_answer_eligible(item)][:limit]:
        node = dict(match.get("node") or {})
        snippet_text = (
            str(match.get("evidence_snippet") or "").strip()
            or str(node.get("raw_text") or "").strip()
            or str(match.get("summary") or "").strip()
        )
        if not snippet_text:
            continue
        snippets.append(
            {
                "node_id": str(match.get("node_id") or ""),
                "text": _truncate_prompt_text(snippet_text, limit=280),
                "kind": str(node.get("memory_type") or "memory"),
                "source_label": str((node.get("provenance") or {}).get("source_label") or ""),
                "source_trust": str(node.get("source_trust") or "user_asserted"),
                "claim_status": str(node.get("claim_status") or "fact"),
            }
        )
    return snippets


def _build_partial_context_dossier(section_snapshots: list[dict[str, Any]]) -> str | None:
    blocks: list[str] = []
    for snapshot in section_snapshots:
        title = str(snapshot.get("title") or snapshot.get("key") or "Section")
        items = [str(item).strip() for item in list(snapshot.get("items") or []) if str(item).strip()]
        if not items:
            continue
        blocks.append(f"{title}: {'; '.join(items[:3])}")
    return "\n\n".join(blocks[:6]) or None


def _build_partial_answer_payload(
    *,
    query_text: str,
    retrieval_mode: str,
    partial_matches: list[dict[str, Any]],
    partial_context: dict[str, Any] | None,
    shared_evidence_snapshot: dict[str, Any],
    section_snapshots: list[dict[str, Any]],
    document_mode: str = "none",
    document_packets: list[dict[str, Any]] | None = None,
) -> dict[str, Any] | None:
    direct_answer = build_direct_fact_answer(query_text, partial_matches[:8])
    context_dossier_partial = _build_partial_context_dossier(section_snapshots)
    evidence_snippets = _build_stream_evidence_snippets(partial_matches)
    query_class = _query_class(query_text)
    support_metadata = build_answer_support_metadata(
        matches=partial_matches,
        shared_evidence=shared_evidence_snapshot,
        evidence_node_ids=list((direct_answer or {}).get("evidence_node_ids") or []),
    )
    lookup_terms = _document_lookup_terms(query_text) if document_mode == "lookup" else []
    if lookup_terms and list(document_packets or []) and _document_lookup_max_packet_fit(document_packets) < 0.2:
        requested = _document_lookup_requested_label(query_text)
        answer_text = f"Non ho ancora trovato un {requested} che corrisponda alla richiesta nella memoria recuperata."
        fallback_support_metadata = build_answer_support_metadata(
            matches=partial_matches,
            shared_evidence=shared_evidence_snapshot,
        )
        return {
            "answer": {
                "answer_text": answer_text,
                "mode": "document_lookup_guard",
                "confidence": 0.5,
                "answerability_state": "partial",
                "document_lookup_state": "no_matching_document_packet_yet",
                "insufficient": False,
                "evidence_node_ids": [str(match.get("node_id") or "") for match in partial_matches[:4] if str(match.get("node_id") or "")],
                "evidence_snippets": evidence_snippets,
                "support_node_count": int(fallback_support_metadata.get("support_node_count") or 0),
                "support_slot_count": int(fallback_support_metadata.get("support_slot_count") or 0),
                "family_attribution_summary": dict(fallback_support_metadata.get("family_attribution_summary") or {}),
                "contradiction_present": bool(fallback_support_metadata.get("contradiction_present")),
                "distinct_evidence_packet_count": int(fallback_support_metadata.get("distinct_evidence_packet_count") or 0),
                "ordered_document_sequence_supported": bool(fallback_support_metadata.get("ordered_document_sequence_supported")),
            },
            "answer_short": answer_text,
            "answer_full_partial": answer_text,
            "context": partial_context or {},
            "context_dossier_partial": context_dossier_partial,
            "shared_evidence": shared_evidence_snapshot,
            "evidence_snippets": evidence_snippets,
        }
    direct_fast_path = query_class in {"direct_fact", "relation_fact", "style_values"} and retrieval_mode == "flash"
    if direct_answer:
        direct_answer_text = clean_answer_surface_text(direct_answer.get("answer_text"))
        answerability_state = str(direct_answer.get("answerability_state") or "partial")
        if not direct_fast_path and not (
            int(support_metadata.get("support_node_count") or 0) >= 2
            or int(support_metadata.get("support_slot_count") or 0) >= 2
            or int(support_metadata.get("distinct_evidence_packet_count") or 0) >= 2
            or bool(support_metadata.get("ordered_document_sequence_supported"))
        ):
            answerability_state = "partial"
        return {
            "answer": {
                "answer_text": direct_answer_text,
                "mode": direct_answer["mode"],
                "confidence": min(float(direct_answer["confidence"]), 0.66) if answerability_state != str(direct_answer.get("answerability_state") or "") else direct_answer["confidence"],
                "answerability_state": answerability_state,
                "evidence_node_ids": direct_answer["evidence_node_ids"],
                "evidence_snippets": direct_answer.get("evidence_snippets") or evidence_snippets,
                "support_node_count": int(support_metadata.get("support_node_count") or direct_answer.get("support_node_count") or 0),
                "support_slot_count": int(support_metadata.get("support_slot_count") or direct_answer.get("support_slot_count") or 0),
                "family_attribution_summary": dict(support_metadata.get("family_attribution_summary") or direct_answer.get("family_attribution_summary") or {}),
                "contradiction_present": bool(support_metadata.get("contradiction_present") or direct_answer.get("contradiction_present")),
                "answer_adequacy": dict(direct_answer.get("answer_adequacy") or {}),
                "distinct_evidence_packet_count": int(support_metadata.get("distinct_evidence_packet_count") or 0),
                "ordered_document_sequence_supported": bool(support_metadata.get("ordered_document_sequence_supported")),
            },
            "answer_short": direct_answer_text,
            "answer_full_partial": direct_answer_text,
            "context": partial_context or {},
            "context_dossier_partial": context_dossier_partial,
            "shared_evidence": shared_evidence_snapshot,
            "evidence_snippets": direct_answer.get("evidence_snippets") or evidence_snippets,
        }

    context_fragments = list((partial_context or {}).get("context_fragments") or [])
    answer_text = ""
    if context_fragments:
        answer_text = str(context_fragments[0].get("text") or "").strip()
    if not answer_text and partial_matches:
        answer_text = str(partial_matches[0].get("summary") or "").strip()
    if not answer_text and context_dossier_partial and direct_fast_path:
        answer_text = str(context_dossier_partial.splitlines()[0] or "").strip()
    if not answer_text:
        return None
    answer_text = clean_answer_surface_text(answer_text)
    if not answer_text:
        return None
    fallback_support_metadata = build_answer_support_metadata(
        matches=partial_matches,
        shared_evidence=shared_evidence_snapshot,
    )
    return {
        "answer": {
            "answer_text": _truncate_prompt_text(answer_text, limit=260),
            "mode": "heuristic",
            "confidence": max(0.4, min(0.92, float(shared_evidence_snapshot.get("confidence") or 0.0))),
            "answerability_state": "partial",
            "evidence_node_ids": [str(match.get("node_id") or "") for match in partial_matches[:4] if str(match.get("node_id") or "")],
            "evidence_snippets": evidence_snippets,
            "support_node_count": int(fallback_support_metadata.get("support_node_count") or 0),
            "support_slot_count": int(fallback_support_metadata.get("support_slot_count") or 0),
            "family_attribution_summary": dict(fallback_support_metadata.get("family_attribution_summary") or {}),
            "contradiction_present": bool(fallback_support_metadata.get("contradiction_present")),
            "distinct_evidence_packet_count": int(fallback_support_metadata.get("distinct_evidence_packet_count") or 0),
            "ordered_document_sequence_supported": bool(fallback_support_metadata.get("ordered_document_sequence_supported")),
        },
        "answer_short": _truncate_prompt_text(answer_text, limit=260),
        "answer_full_partial": _truncate_prompt_text(answer_text, limit=520),
        "context": partial_context or {},
        "context_dossier_partial": context_dossier_partial,
        "shared_evidence": shared_evidence_snapshot,
        "evidence_snippets": evidence_snippets,
    }


def _first_answer_preflight_matches(
    *,
    query: RetrieveRequest,
    retrieval_mode: str,
    probes: list[dict[str, Any]],
    identity_context: dict[str, Any],
    limit: int,
) -> list[dict[str, Any]]:
    query_class = _query_class(query.query_text)
    temporal_query = _is_temporal_reference_query(query.query_text)
    if query_class == "document_lookup" and not temporal_query:
        return []
    probe_cap = 3 if retrieval_mode == "flash" else 4 if retrieval_mode == "balanced" else 6
    matches_by_id: dict[str, dict[str, Any]] = {}
    core_ids = _identity_core_candidate_ids(identity_context, limit=4)
    for probe in list(probes or [])[:probe_cap]:
        goal = str(probe.get("goal") or "").strip()
        if not goal:
            continue
        goal_ids = _goal_support_candidate_ids(identity_context, goal, limit=8)
        candidate_ids = list(dict.fromkeys([*goal_ids, *core_ids]))
        text_candidate_nodes: list[dict[str, Any]] = []
        goal_text_terms = _goal_text_terms_for_goal(goal)
        if goal_text_terms:
            try:
                if goal in {"style", "values"}:
                    text_candidate_nodes = _subject_anchored_goal_text_nodes(
                        goal,
                        tuple(goal_text_terms),
                        identity_context,
                        limit=max(8, min(int(limit), 16)),
                    )
                else:
                    text_candidate_nodes = fetch_nodes_by_text_terms(
                        list(goal_text_terms),
                        limit=max(8, min(int(limit) * 2, 24)),
                        include_raw_text=True,
                    )
            except Exception:
                text_candidate_nodes = []
        if not candidate_ids and not text_candidate_nodes:
            continue
        try:
            candidate_nodes = fetch_nodes_by_ids(candidate_ids[:12], include_raw_text=True)
        except Exception:
            candidate_nodes = []
        candidate_node_by_id = {
            str(node.get("id") or "").strip(): dict(node)
            for node in list(candidate_nodes or [])
            if str(node.get("id") or "").strip()
        }
        text_candidate_source_by_id: dict[str, str] = {}
        for node in list(text_candidate_nodes or []):
            node_payload = dict(node or {})
            node_id = str(node_payload.get("id") or "").strip()
            if not node_id:
                continue
            candidate_node_by_id.setdefault(node_id, node_payload)
            text_candidate_source_by_id[node_id] = (
                "goal_subject_text"
                if _node_text_is_subject_anchored(node_payload, identity_context)
                else "goal_text"
            )
        candidate_nodes = list(candidate_node_by_id.values())
        ranked: list[dict[str, Any]] = []
        for node in candidate_nodes:
            node_id = str(node.get("id") or "").strip()
            if not node_id:
                continue
            sources = ["first_answer_preflight"]
            if node_id in goal_ids:
                sources.append("goal_support")
            if node_id in core_ids:
                sources.append("identity_core")
            text_source = text_candidate_source_by_id.get(node_id)
            if text_source:
                sources.append(text_source)
            try:
                match = rank_candidate(probe, dict(node), list(dict.fromkeys(sources)), identity_context=identity_context)
            except Exception:
                continue
            slot = _goal_to_slot(goal)
            match["support_slots"] = [slot]
            match["branch_goals"] = [goal]
            match["first_answer_preflight"] = True
            ranked.append(match)
        if ranked:
            try:
                ranked = rerank_hydrated_matches(
                    probe,
                    ranked,
                    hydrate_limit=min(len(ranked), 12),
                    max_nodes_fulltext=min(query.max_nodes_fulltext, 12),
                    identity_context=identity_context,
                )
            except Exception:
                pass
        for match in ranked:
            node_id = str(match.get("node_id") or "").strip()
            if not node_id:
                continue
            current = matches_by_id.get(node_id)
            if current is None or float(match.get("raw_score") or match.get("score") or 0.0) > float(current.get("raw_score") or current.get("score") or 0.0):
                matches_by_id[node_id] = dict(match)
            else:
                merged_sources = list(dict.fromkeys([*list(current.get("sources") or []), *list(match.get("sources") or [])]))
                merged_slots = list(dict.fromkeys([*list(current.get("support_slots") or []), *list(match.get("support_slots") or [])]))
                merged_goals = list(dict.fromkeys([*list(current.get("branch_goals") or []), *list(match.get("branch_goals") or [])]))
                current["sources"] = merged_sources
                current["support_slots"] = merged_slots
                current["branch_goals"] = merged_goals
                matches_by_id[node_id] = current
    named_targets = _query_named_targets(query.query_text)
    if named_targets and query_class != "document_lookup":
        for target in named_targets[:4]:
            try:
                target_nodes = fetch_nodes_by_text_terms([target], limit=max(8, min(int(limit) * 2, 24)), include_raw_text=True)
            except Exception:
                target_nodes = []
            for node in target_nodes[: max(4, min(int(limit), 12))]:
                target_match = _named_target_match_for_node(
                    query.query_text,
                    dict(node),
                    target,
                    identity_context,
                    source="named_target_preflight",
                )
                if not target_match:
                    continue
                node_id = str(target_match.get("node_id") or "").strip()
                if not node_id:
                    continue
                current = matches_by_id.get(node_id)
                if current is None or float(target_match.get("raw_score") or target_match.get("score") or 0.0) > float(current.get("raw_score") or current.get("score") or 0.0):
                    matches_by_id[node_id] = dict(target_match)
                else:
                    current["sources"] = list(dict.fromkeys([*list(current.get("sources") or []), *list(target_match.get("sources") or [])]))
                    current["support_slots"] = list(dict.fromkeys([*list(current.get("support_slots") or []), *list(target_match.get("support_slots") or [])]))
                    current["branch_goals"] = list(dict.fromkeys([*list(current.get("branch_goals") or []), *list(target_match.get("branch_goals") or [])]))
                    current["first_answer_preflight"] = True
                    current["named_target_preflight"] = True
                    matches_by_id[node_id] = current
    matches = list(matches_by_id.values())
    if temporal_query:
        matches = _augment_matches_with_temporal_sweep(query.query_text, matches, limit=max(limit, 12))
        for match in matches:
            sources = list(match.get("sources") or [])
            if "temporal_sweep" not in sources:
                continue
            match["first_answer_preflight"] = True
            match["support_slots"] = list(dict.fromkeys([*list(match.get("support_slots") or []), "history"]))
            match["branch_goals"] = list(dict.fromkeys([*list(match.get("branch_goals") or []), "history"]))
    matches.sort(key=lambda item: (-float(item.get("raw_score") or item.get("score") or 0.0), -float(item.get("score") or 0.0), str(item.get("node_id") or "")))
    return matches[: max(1, int(limit))]


def _document_node_query_term_fit(query_text: str, node: dict[str, Any]) -> float:
    terms = _document_lookup_terms(query_text)
    if not terms:
        return 0.0
    provenance = dict(node.get("provenance") or {})
    text_parts = [
        str(node.get("summary") or ""),
        str(node.get("raw_text") or ""),
        str(provenance.get("source_label") or ""),
        str(provenance.get("source_type") or ""),
    ]
    folded_text = _fold_text(" ".join(text_parts))
    if not folded_text:
        return 0.0
    matched_terms = [term for term in terms if term in folded_text]
    overlap = len(matched_terms) / max(1, len(terms))
    phrase = " ".join(terms[: min(8, len(terms))])
    phrase_bonus = 0.18 if phrase and phrase in folded_text else 0.0
    lead_pair_bonus = 0.1 if len(terms) >= 2 and all(term in folded_text for term in terms[:2]) else 0.0
    return round(min(1.0, overlap + phrase_bonus + lead_pair_bonus), 6)


def _document_lookup_pre_route_matches(
    *,
    query_text: str,
    probes: list[dict[str, Any]],
    identity_context: dict[str, Any],
    limit: int,
) -> list[dict[str, Any]]:
    if _query_class(query_text) != "document_lookup":
        return []
    lookup_terms = _document_lookup_terms(query_text)
    if not lookup_terms:
        return []
    ranking_probe = next((probe for probe in list(probes or []) if str(probe.get("goal") or "") == "documents"), None)
    if ranking_probe is None:
        ranking_probe = next(iter(list(probes or [])), None)
    if not ranking_probe:
        return []

    node_by_id: dict[str, dict[str, Any]] = {}
    node_sources: dict[str, list[str]] = defaultdict(list)

    def collect_nodes(terms: list[str] | tuple[str, ...], source: str, node_limit: int) -> None:
        try:
            candidate_nodes = fetch_nodes_by_text_terms(list(terms), limit=node_limit, include_raw_text=True)
        except Exception:
            candidate_nodes = []
        for node in list(candidate_nodes or []):
            node_payload = dict(node or {})
            node_id = str(node_payload.get("id") or "").strip()
            if not node_id or not _is_document_catalog_node(node_payload):
                continue
            if node_id not in node_by_id:
                node_by_id[node_id] = node_payload
            node_sources[node_id] = list(dict.fromkeys([*node_sources.get(node_id, []), source]))

    bounded_limit = max(int(limit) * 2, 24)
    collect_nodes(lookup_terms, "document_lookup_target_terms", bounded_limit)
    collect_nodes(_DOCUMENT_CATALOG_PROBE_TERMS, "document_lookup_catalog_terms", bounded_limit)

    ranked: list[dict[str, Any]] = []
    for node_id, node in node_by_id.items():
        sources = list(dict.fromkeys(["document_lookup_pre_route", *node_sources.get(node_id, [])]))
        try:
            match = rank_candidate(ranking_probe, dict(node), sources, identity_context=identity_context)
        except Exception:
            continue
        term_fit = _document_node_query_term_fit(query_text, node)
        catalog_floor = 0.62 if term_fit <= 0.0 else min(0.96, 0.58 + 0.34 * term_fit)
        raw_score = max(float(match.get("raw_score") or match.get("score") or 0.0), catalog_floor)
        match["raw_score"] = round(min(1.0, raw_score), 6)
        match["score"] = round(match["raw_score"] * float(ranking_probe.get("weight") or 1.0), 6)
        match["support_slots"] = ["documents"]
        match["branch_goals"] = ["documents"]
        match["first_answer_preflight"] = True
        match["document_lookup_pre_route"] = True
        match["document_lookup_term_fit"] = term_fit
        ranked.append(match)

    ranked.sort(
        key=lambda item: (
            -float(item.get("document_lookup_term_fit") or 0.0),
            -float(item.get("raw_score") or item.get("score") or 0.0),
            str(item.get("node_id") or ""),
        )
    )
    return ranked[: max(1, int(limit))]


def _shared_evidence_from_preflight_matches(
    *,
    query_text: str,
    matches: list[dict[str, Any]],
    branches: list[dict[str, Any]],
    visited_node_ids: set[str],
    visited_bucket_keys: set[str],
    context: dict[str, Any] | None,
) -> dict[str, Any]:
    covered_goals = sorted(
        {
            str(goal).strip()
            for match in list(matches or [])
            for goal in list(match.get("branch_goals") or [])
            if str(goal).strip()
        }
    )
    coverage_by_slot: dict[str, float] = {}
    for section in list((context or {}).get("structured_sections") or []):
        key = str(section.get("key") or "").strip()
        if not key:
            continue
        coverage_by_slot[key] = max(float(coverage_by_slot.get(key) or 0.0), float(section.get("confidence") or 0.0))
    for match in list(matches or []):
        raw_score = float(match.get("raw_score") or match.get("score") or 0.0)
        for slot in list(match.get("support_slots") or []):
            normalized_slot = str(slot).strip()
            if normalized_slot:
                coverage_by_slot[normalized_slot] = max(float(coverage_by_slot.get(normalized_slot) or 0.0), raw_score)
    required_slots = _required_slots_for_query(query_text)
    unresolved_slots = [slot for slot in required_slots if float(coverage_by_slot.get(slot) or 0.0) < 0.55]
    confidence = max([float(value or 0.0) for value in coverage_by_slot.values()] or [0.0])
    return {
        "covered_goals": covered_goals,
        "fulfilled_goals": [],
        "branch_status": {str(branch.get("branch_id") or ""): str(branch.get("status") or "") for branch in branches},
        "evidence_topics": [
            {
                "topic": goal,
                "node_ids": [
                    str(match.get("node_id") or "")
                    for match in matches
                    if goal in list(match.get("branch_goals") or []) and str(match.get("node_id") or "").strip()
                ][:4],
                "confidence": round(max((float(match.get("raw_score") or match.get("score") or 0.0) for match in matches if goal in list(match.get("branch_goals") or [])), default=0.0), 4),
                "status": "covered",
            }
            for goal in covered_goals
        ],
        "shared_node_ids": sorted({*visited_node_ids, *{str(match.get("node_id") or "") for match in matches if str(match.get("node_id") or "").strip()}}),
        "shared_bucket_keys": sorted(visited_bucket_keys),
        "confidence_by_goal": {
            goal: round(max((float(match.get("raw_score") or match.get("score") or 0.0) for match in matches if goal in list(match.get("branch_goals") or [])), default=0.0), 4)
            for goal in covered_goals
        },
        "branch_overlaps": [],
        "contradiction_flags": [],
        "coverage_by_slot": coverage_by_slot,
        "unresolved_slots": unresolved_slots,
        "confidence": round(confidence, 4),
        "first_answer_preflight": True,
    }


def retrieve_runtime(
    query: RetrieveRequest,
    atlas_payload: dict[str, Any],
    identity_nucleus: dict[str, Any],
    *,
    prepared_plan: dict[str, Any] | None = None,
    search_id: str | None = None,
    event_callback: Any | None = None,
) -> dict[str, Any]:
    started_at = time.perf_counter()
    runtime_plan = prepared_plan or prepare_runtime_plan(query, atlas_payload, identity_nucleus, defer_planner_seed=True)
    identity_context = dict(runtime_plan["identity_context"])
    legacy_query_contract = build_query_contract(
        query.query_text,
        retrieval_mode=str((runtime_plan.get("planner_runtime") or {}).get("retrieval_mode") or getattr(query, "retrieval_mode", None) or "balanced"),
    )
    semantic_contract_lock = threading.Lock()
    semantic_contract_state: dict[str, Any] = {
        "contract": dict(runtime_plan.get("semantic_contract") or {}),
        "runtime": dict(runtime_plan.get("semantic_contract_runtime") or {}),
    }
    semantic_brain_revision = str(
        (runtime_plan.get("planner_runtime") or {}).get("semantic_contract_brain_revision")
        or (runtime_plan.get("planner_seed_runtime") or {}).get("semantic_contract_brain_revision")
        or _semantic_contract_brain_revision(query, atlas_payload)
    )

    def semantic_contract_snapshot() -> dict[str, Any]:
        with semantic_contract_lock:
            return {
                "contract": dict(semantic_contract_state.get("contract") or {}),
                "runtime": dict(semantic_contract_state.get("runtime") or {}),
            }

    def semantic_contract_fields() -> dict[str, Any]:
        snapshot = semantic_contract_snapshot()
        return {
            "semantic_contract": snapshot["contract"],
            "semantic_contract_runtime": snapshot["runtime"],
        }

    probes = list(runtime_plan["probes"])
    branches = [dict(branch) for branch in list(runtime_plan["branches"])]
    atlas_shortlists = dict(runtime_plan["atlas_shortlists"])
    planner_family_plans = {
        "heuristic": dict(runtime_plan.get("heuristic_family_plan") or {}),
        "ai": dict(runtime_plan.get("ai_family_plan") or {}),
    }
    planner_mode = str(runtime_plan["planner_mode"])
    decomposition_mode = str(runtime_plan["decomposition_mode"])
    query_class = _query_class(query.query_text)
    retrieval_mode, retrieval_mode_selected_by = _select_retrieval_mode(query)
    mode_config = _retrieval_mode_config(retrieval_mode, query_class)
    stop_threshold = max(0.5, min(0.99, float(runtime_plan["stop_threshold"]) + float(mode_config["threshold_adjust"])))
    normalized_thread_id = str(query.thread_id or "").strip() or None
    warm_state = fetch_warm_thread_state(normalized_thread_id) if normalized_thread_id else None
    previous_warm_packet = dict((warm_state or {}).get("warm_packet") or {})
    continuity_gate = _evaluate_continuity_details(query.query_text, warm_state, allow_semantic_gate=False)
    continuity_state = str(continuity_gate.get("continuity_state") or "low_continuity")
    warm_packet_seed = _apply_warm_state_gate(warm_state, continuity_state, query.query_text)
    warm_seed_matches = _warm_packet_seed_matches(warm_packet_seed or {})
    warm_state_used = bool(warm_packet_seed and warm_seed_matches)
    warm_state_summary = _summarize_warm_state(warm_packet_seed or (warm_state or {}).get("warm_packet"))
    runtime_phase = "planning"
    stop_reason = "budget_exhausted"

    visited_node_ids: set[str] = set()
    visited_bucket_keys: set[str] = set()
    all_steps: list[dict[str, Any]] = []
    aggregated: dict[str, dict[str, Any]] = {}
    shared_topics: dict[str, dict[str, Any]] = {}
    node_cache: dict[str, dict[str, Any]] = {}
    first_context_ms: float | None = None
    first_landing_ms: float | None = None
    answer_first_ms: float | None = None
    answer_final_ms: float | None = None
    all_candidate_ids: set[str] = set()
    partial_answer_revision = 0
    partial_answer_signature: str | None = None
    post_partial_context_update_count = 0
    answer_now_before_exploration_complete = False
    context_level_1_before_final = False
    master_decision_history: list[dict[str, Any]] = []
    navigator_worker_reports: dict[str, dict[str, Any]] = {}
    navigator_worker_registry: dict[str, dict[str, Any]] = {}
    session_worker_reports: dict[str, dict[str, Any]] = {}
    session_worker_registry: dict[str, dict[str, Any]] = {}
    last_section_snapshot_state: list[dict[str, Any]] = []
    context_waves: list[dict[str, Any]] = []
    context_wave_hot_node_ids: set[str] = set()
    context_wave_reservoir_node_ids: set[str] = set()
    context_wave_token_estimate = 0
    latest_hot_context_summary: dict[str, Any] = {}
    latest_evidence_reservoir: dict[str, Any] = {}
    latest_context_quality_metrics: dict[str, Any] = {}
    latest_warm_packet: dict[str, Any] | None = dict(warm_packet_seed or {}) if warm_packet_seed else None
    final_surface_accumulator: dict[str, Any] = {
        "hot_context_summary": {},
        "context_dossier_partial": None,
        "evidence_snippets": [],
        "master_state": {},
        "planner_runtime": dict(runtime_plan.get("planner_runtime") or {}),
    }
    route_truth_required = bool(
        getattr(query, "complete_paths", False)
        or str(getattr(query, "context_package_mode", None) or "") == "forensic_trace"
    )
    route_truth_round_budget = max(1, min(int(query.max_steps or 1), int(query.max_total_steps or 1), 4))
    early_final_surface_emitted = False
    early_final_surface_sealed = False
    early_final_surface_payload: dict[str, Any] | None = None
    early_final_seal_reason: str | None = None
    early_final_seal_source: str | None = None
    early_final_answer_full: str | None = None
    early_final_context_update_count = 0
    early_final_context_wave_count = 0
    early_final_answer_candidate_count = 0
    early_final_emitted_at_ms: float | None = None
    detached_result_snapshot_payload: dict[str, Any] | None = None
    detached_result_snapshot_emitted = False
    background_enrichment_budget = _background_enrichment_budget(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
    )
    if route_truth_required:
        background_enrichment_budget = dict(background_enrichment_budget)
        background_enrichment_budget["route_truth_required"] = True
        background_enrichment_budget["max_rounds_after_early_final"] = max(
            int(background_enrichment_budget.get("max_rounds_after_early_final") or 0),
            int(route_truth_round_budget),
        )
        background_enrichment_budget["max_seconds_after_early_final"] = max(
            float(background_enrichment_budget.get("max_seconds_after_early_final") or 0.0),
            8.0 if retrieval_mode in {"heavy", "forensic"} else 5.0,
        )
        background_enrichment_budget["max_context_updates_after_early_final"] = max(
            int(background_enrichment_budget.get("max_context_updates_after_early_final") or 0),
            2,
        )
        background_enrichment_budget["max_answer_candidates_after_early_final"] = max(
            int(background_enrichment_budget.get("max_answer_candidates_after_early_final") or 0),
            2,
        )
        background_enrichment_budget["policy"] = "route_truth_completion_before_final_seal"
    background_enrichment_state = "not_started"
    background_enrichment_started_round: int | None = None
    background_enrichment_stop_reason: str | None = None
    background_enrichment_budget_exhausted = False
    background_enrichment_rounds_consumed = 0
    background_enrichment_yield_policy = dict(background_enrichment_budget.get("yield_policy") or _background_enrichment_yield_policy(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
    ))
    background_enrichment_yield_reports: list[dict[str, Any]] = []
    background_enrichment_yield_recorded_rounds: set[int] = set()
    background_enrichment_yield_summary: dict[str, Any] = _background_enrichment_yield_summary([], background_enrichment_yield_policy)
    background_enrichment_low_yield_rounds = 0
    client_visible_partial_budget_seconds = _client_visible_partial_terminal_budget_seconds(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
        route_truth_required=route_truth_required,
    )
    client_visible_partial_terminalized = False
    client_visible_partial_terminal_reason: str | None = None
    post_final_worker_throttle_policy = _post_final_worker_throttle_policy(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
        route_truth_required=route_truth_required,
        route_truth_branch_cap=query.max_total_branches,
        route_truth_round_budget=route_truth_round_budget,
    )
    post_final_worker_throttle_enabled = bool(post_final_worker_throttle_policy.get("enabled", True))
    post_final_branch_value_reports: list[dict[str, Any]] = []
    post_final_worker_cap_history: list[dict[str, Any]] = []
    post_final_branch_pruned_count = 0
    post_final_ai_worker_suppressed_count = 0
    current_document_mode = "none"
    current_document_packets: list[dict[str, Any]] = []
    document_lookup_kind = "none"
    document_lookup_contract: dict[str, Any] = {}
    document_workspace: dict[str, Any] = {}
    warm_final_answer_seed: dict[str, Any] | None = None
    warm_flash_short_circuit = False
    warm_source_pressure = _query_has_source_pressure(query.query_text)
    warm_route_validation_required = bool(
        warm_source_pressure
        or query_class == "document_lookup"
        or retrieval_mode == "forensic"
    )
    warm_route_budget_override: int | None = None
    warm_final_scout_wait_override: float | None = None
    warm_route_fast_path_reason: str | None = None
    planner_merge_window_seconds = float((runtime_plan.get("planner_runtime") or {}).get("planner_merge_window_seconds") or _planner_merge_window_seconds(retrieval_mode=retrieval_mode))
    first_answer_sla_split = _first_answer_sla_split_enabled(runtime_plan)
    initial_scout_wait_seconds = _initial_llm_scout_wait_seconds(
        planner_merge_window_seconds=planner_merge_window_seconds,
        runtime_plan=runtime_plan,
    )
    final_scout_wait_seconds = _final_llm_scout_wait_seconds(
        retrieval_mode=retrieval_mode,
        first_answer_sla_split=first_answer_sla_split,
    )
    final_scout_wait_seconds = _material_scout_wait_seconds(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        first_answer_sla_split=first_answer_sla_split,
        base_wait_seconds=final_scout_wait_seconds,
    )
    first_answer_sla_ms = _first_answer_sla_ms(retrieval_mode=retrieval_mode)
    final_surface_sla_seconds = _final_surface_sla_seconds(
        query_text=query.query_text,
        retrieval_mode=retrieval_mode,
        query_class=query_class,
        first_answer_sla_split=first_answer_sla_split,
    )
    final_scout_wait_budget_seconds = final_scout_wait_seconds
    final_scout_join_wait_seconds = final_scout_wait_seconds
    final_scout_wait_capped_by_sla = False
    scout_non_blocking_finalization = False
    first_answer_ready_before_final_join = False
    scout_status_at_final_join_exit: str | None = None
    scout_running_at_final_join_exit = False
    scout_running_after_final_join = False
    document_lookup_fast_no_match = False
    document_lookup_fast_packet_found = False
    document_lookup_route_budget_override: int | None = None
    document_lookup_route_fast_path_reason: str | None = None
    document_lookup_pre_route_match_count = 0
    document_lookup_pre_route_max_packet_fit: float | None = None
    document_synthesis_fast_packet_found = False
    document_synthesis_route_budget_override: int | None = None
    document_synthesis_route_fast_path_reason: str | None = None
    direct_preflight_fast_path = False
    direct_preflight_answer_usable = False
    direct_preflight_route_budget_override: int | None = None
    direct_preflight_route_fast_path_reason: str | None = None
    direct_preflight_match_count = 0
    direct_preflight_target_count = 0
    llm_scout_suppressed_reason: str | None = None
    llm_scout_state: dict[str, Any] = {
        "enabled": bool(llm_enabled()) and not bool(llm_scout_suppressed_reason),
        "completed": False,
        "ingested": False,
        "payload": None,
        "error": None,
        "llm_probe_count": 0,
        "added_probe_count": 0,
        "completed_ms": None,
        "status": "suppressed" if llm_scout_suppressed_reason else ("pending" if llm_enabled() else "disabled"),
        "suppressed_reason": llm_scout_suppressed_reason,
        "fast_only": False,
        "fast_only_reason": None,
        "first_answer_sla_ms": first_answer_sla_ms,
        "final_surface_sla_seconds": final_surface_sla_seconds,
        "final_wait_budget_seconds": final_scout_wait_budget_seconds,
        "final_join_wait_seconds": final_scout_join_wait_seconds,
        "final_wait_capped_by_sla": final_scout_wait_capped_by_sla,
        "non_blocking_finalization": scout_non_blocking_finalization,
        "first_answer_ready_before_final_join": first_answer_ready_before_final_join,
        "status_at_final_join_exit": scout_status_at_final_join_exit,
        "running_at_final_join_exit": scout_running_at_final_join_exit,
        "running_after_final_join": scout_running_after_final_join,
        "planner_family_plan": {},
        "branch_reuse_count": 0,
        "branch_enrich_count": 0,
        "branch_fork_count": 0,
        "dual_origin_branch_count": 0,
        "merge_resolution_histogram": {"reuse_branch": 0, "enrich_branch": 0, "fork_new_branch": 0},
        "merged_strand_ids": [],
        "enriched_strand_ids": [],
        "forked_strand_ids": [],
    }

    def _run_llm_scout() -> None:
        semantic_snapshot = semantic_contract_snapshot()
        scout_fast_only = _llm_scout_fast_only_mode(
            first_answer_sla_split=first_answer_sla_split,
            semantic_contract=semantic_snapshot["contract"],
            semantic_contract_runtime=semantic_snapshot["runtime"],
        )
        llm_scout_state["fast_only"] = scout_fast_only
        llm_scout_state["fast_only_reason"] = (
            "first_answer_sla_without_ai_required"
            if scout_fast_only
            else "ai_required_full_planner" if first_answer_sla_split else "standard_full_planner"
        )
        llm_scout_state["status"] = "running"
        planner_payload, planner_error = llm_retrieval_plan(
            query,
            identity_context,
            atlas_payload,
            answer_strands=list(runtime_plan.get("answer_strands") or []),
            fast_only=scout_fast_only,
        )
        llm_scout_state["payload"] = planner_payload
        llm_scout_state["error"] = planner_error
        llm_scout_state["completed"] = True
        llm_scout_state["completed_ms"] = round((time.perf_counter() - started_at) * 1000.0, 2)
        llm_scout_state["status"] = "failed" if planner_error else "completed"

    llm_scout_thread: threading.Thread | None = None

    def emit(event_type: str, payload: dict[str, Any]) -> None:
        nonlocal first_context_ms, first_landing_ms, answer_first_ms, answer_final_ms
        nonlocal early_final_context_update_count, early_final_context_wave_count, early_final_answer_candidate_count
        elapsed_ms = round((time.perf_counter() - started_at) * 1000.0, 2)
        enriched_payload = {
            **dict(payload or {}),
            **semantic_contract_fields(),
            "search_id": str(search_id or dict(payload or {}).get("search_id") or "") or None,
            "elapsed_ms": elapsed_ms,
        }
        if event_type == "landing_ready" and first_landing_ms is None:
            first_landing_ms = elapsed_ms
        if event_type in {"context_update", "context_wave"} and first_context_ms is None:
            first_context_ms = elapsed_ms
        if event_type == "answer_partial" and answer_first_ms is None:
            answer_first_ms = elapsed_ms
        if event_type == "answer_final" and answer_final_ms is None:
            answer_final_ms = elapsed_ms
        if early_final_surface_emitted:
            enriched_payload.setdefault("early_final_sealed", bool(early_final_surface_sealed))
            enriched_payload.setdefault("early_final_seal_reason", early_final_seal_reason)
            enriched_payload.setdefault("early_final_seal_source", early_final_seal_source)
            enriched_payload.setdefault("background_enrichment_state", background_enrichment_state)
            enriched_payload.setdefault("background_enrichment_budget", background_enrichment_budget)
            if background_enrichment_stop_reason:
                enriched_payload.setdefault("background_enrichment_stop_reason", background_enrichment_stop_reason)
            if event_type in {"context_update", "context_wave", "metrics_update", "step_complete", "worker_stopped"}:
                enriched_payload["background_enrichment_active"] = True
                enriched_payload["answer_surface_state"] = "final_sealed" if early_final_surface_sealed else "answer_now_and_continue"
                enriched_payload["closure_state"] = "final_sealed" if early_final_surface_sealed else "open"
                enriched_payload["final_closure_ready"] = bool(early_final_surface_sealed)
            if event_type == "context_update":
                early_final_context_update_count += 1
                enriched_payload["early_final_context_update_count"] = early_final_context_update_count
            elif event_type == "context_wave":
                early_final_context_wave_count += 1
                enriched_payload["early_final_context_wave_count"] = early_final_context_wave_count
            elif event_type == "answer_candidate":
                early_final_answer_candidate_count += 1
                enriched_payload["early_final_answer_candidate_count"] = early_final_answer_candidate_count
        if not event_callback:
            return
        if event_type in {"answer_partial", "answer_final", "answer_candidate", "scout_status", "search_stopped"}:
            enriched_payload.setdefault("first_answer_ready", bool(answer_first_ms is not None or partial_answer_revision > 0))
            enriched_payload.setdefault("first_answer_sla_ms", first_answer_sla_ms)
            enriched_payload.setdefault("final_surface_sla_seconds", final_surface_sla_seconds)
            enriched_payload.setdefault("llm_scout_status", llm_scout_state.get("status"))
        event_callback(event_type, enriched_payload)

    semantic_contract_thread: threading.Thread | None = None
    semantic_contract_started_at: float | None = None

    def _run_semantic_contract_compiler() -> None:
        contract, runtime = compile_semantic_query_contract(
            query_text=query.query_text,
            retrieval_mode=retrieval_mode,
            legacy_contract=legacy_query_contract,
            identity_hints=identity_nucleus,
            tool_name=query.mcp_tool_name,
            allow_ai=True,
            deferred=False,
            timeout=_semantic_contract_timeout_seconds(retrieval_mode),
            brain_revision=semantic_brain_revision,
            cache_scope="retrieve_semantic_contract",
        )
        with semantic_contract_lock:
            semantic_contract_state["contract"] = dict(contract or {})
            semantic_contract_state["runtime"] = dict(runtime or {})
        emit(
            "semantic_contract_ready",
            {
                "runtime_phase": runtime_phase,
                "semantic_contract": dict(contract or {}),
                "semantic_contract_runtime": dict(runtime or {}),
            },
        )

    initial_semantic_runtime = dict(semantic_contract_state.get("runtime") or {})
    if (
        str(initial_semantic_runtime.get("status") or "") in {"deferred", "fallback"}
        and bool(initial_semantic_runtime.get("ai_required"))
        and bool(llm_enabled())
        and not _semantic_contract_is_ai_material(initial_semantic_runtime)
    ):
        semantic_contract_context = copy_context()
        semantic_contract_started_at = time.perf_counter()
        semantic_contract_thread = threading.Thread(
            target=lambda: semantic_contract_context.run(_run_semantic_contract_compiler),
            daemon=True,
        )
        semantic_contract_thread.start()

    if bool(llm_scout_state["enabled"]):
        llm_scout_context = copy_context()
        llm_scout_thread = threading.Thread(target=lambda: llm_scout_context.run(_run_llm_scout), daemon=True)
        llm_scout_thread.start()
        llm_scout_thread.join(timeout=initial_scout_wait_seconds)

    runtime_ai_spatial_attempted = bool(
        dict(runtime_plan.get("ai_spatial_landing_contract") or {}).get("materialized")
    )

    def runtime_ai_spatial_pre_route_wait_seconds() -> float:
        if not bool(llm_enabled()):
            return 0.0
        raw_override = str(os.getenv("AGVM_RUNTIME_AI_SPATIAL_PRE_ROUTE_WAIT_SECONDS") or "").strip()
        if raw_override:
            try:
                return max(0.0, min(90.0, float(raw_override)))
            except ValueError:
                pass
        mode = str(retrieval_mode or "balanced").strip().lower()
        # The route worker may wait briefly for AI-spatial material that is
        # already underway, but it must not inherit the provider queue ceiling.
        # A long queue ceiling is an ops guard, not a product latency budget.
        if mode == "flash":
            return 5.5
        if mode == "heavy":
            return 10.5
        if mode == "forensic":
            return 14.0
        return 8.0

    def runtime_ai_spatial_contract_timeout_seconds() -> float:
        mode = str(retrieval_mode or "balanced").strip().lower()
        if mode == "flash":
            return 5.2
        if mode == "heavy":
            return 9.0
        if mode == "forensic":
            return 12.0
        return 6.5

    def materialize_runtime_ai_spatial_contract_if_ready(
        *,
        source: str,
        semantic_wait_seconds: float = 0.0,
    ) -> bool:
        nonlocal runtime_plan, probes, branches, atlas_shortlists, planner_family_plans, planner_mode
        nonlocal runtime_ai_spatial_attempted
        if all_steps or any(list(branch.get("route_trace") or []) for branch in branches):
            return False
        existing_contract = dict(runtime_plan.get("ai_spatial_landing_contract") or {})
        existing_paths = [dict(item) for item in list(existing_contract.get("inverse_answer_paths") or []) if isinstance(item, dict)]
        existing_materialized = bool(
            existing_contract.get("materialized")
            and existing_contract.get("certifiable")
            and existing_paths
        )
        existing_physical = bool(
            dict(runtime_plan.get("planner_runtime") or {}).get("ai_spatial_physical_materialization_applied")
            or any(str(probe.get("family_plan_id") or "") == "ai_spatial_contract" for probe in probes)
        )
        if existing_materialized and existing_physical:
            return True
        snapshot = semantic_contract_snapshot()
        semantic_contract_payload = dict(snapshot.get("contract") or {})
        semantic_runtime_payload = dict(snapshot.get("runtime") or {})
        semantic_has_material = _semantic_contract_is_ai_material(semantic_runtime_payload)

        def adopt_trace_semantic_contract(*, source_label: str) -> bool:
            nonlocal semantic_contract_payload, semantic_runtime_payload, semantic_has_material, runtime_plan
            trace_contract, trace_runtime = _latest_materialized_semantic_surface_from_events(search_id)
            if not _semantic_contract_is_ai_material(trace_runtime):
                return False
            if _semantic_contract_runtime_rank(trace_runtime) <= _semantic_contract_runtime_rank(semantic_runtime_payload):
                return False
            with semantic_contract_lock:
                semantic_contract_state["contract"] = dict(trace_contract or semantic_contract_state.get("contract") or {})
                semantic_contract_state["runtime"] = dict(trace_runtime)
            semantic_contract_payload = dict(trace_contract or semantic_contract_payload)
            semantic_runtime_payload = dict(trace_runtime)
            semantic_has_material = True
            runtime_plan["semantic_contract"] = dict(semantic_contract_payload)
            runtime_plan["semantic_contract_runtime"] = dict(semantic_runtime_payload)
            planner_runtime_payload = dict(runtime_plan.get("planner_runtime") or {})
            planner_runtime_payload["semantic_contract"] = dict(semantic_contract_payload)
            planner_runtime_payload["semantic_contract_runtime"] = dict(semantic_runtime_payload)
            planner_runtime_payload["semantic_contract_status"] = str(semantic_runtime_payload.get("status") or "")
            planner_runtime_payload["semantic_contract_source"] = str(semantic_runtime_payload.get("source") or "")
            planner_runtime_payload["semantic_contract_material"] = bool(semantic_runtime_payload.get("material"))
            planner_runtime_payload["semantic_contract_reused_from_trace"] = source_label
            runtime_plan["planner_runtime"] = planner_runtime_payload
            emit(
                "semantic_contract_reused_from_trace",
                {
                    "runtime_phase": runtime_phase,
                    "source": source_label,
                    "semantic_contract": dict(semantic_contract_payload),
                    "semantic_contract_runtime": dict(semantic_runtime_payload),
                    "policy": "route_worker_reuses_first_package_ai_contract_instead_of_waiting_or_recompiling",
                },
            )
            return True

        if not semantic_has_material:
            adopt_trace_semantic_contract(source_label=f"{source}_before_semantic_wait")
        if (
            not semantic_has_material
            and semantic_contract_thread
            and semantic_contract_thread.is_alive()
            and semantic_wait_seconds > 0.0
        ):
            wait_started = time.perf_counter()
            emit(
                "ai_spatial_semantic_wait_started",
                {
                    "runtime_phase": runtime_phase,
                    "source": source,
                    "wait_seconds": float(semantic_wait_seconds),
                    "reason": "ai_spatial_requires_fresh_or_cached_semantic_contract_before_route",
                    "semantic_contract_runtime": semantic_runtime_payload,
                },
            )
            semantic_deadline = time.perf_counter() + max(0.0, float(semantic_wait_seconds))
            while time.perf_counter() < semantic_deadline:
                if adopt_trace_semantic_contract(source_label=f"{source}_semantic_wait_trace"):
                    break
                semantic_contract_thread.join(timeout=min(0.2, max(0.0, semantic_deadline - time.perf_counter())))
                snapshot = semantic_contract_snapshot()
                semantic_contract_payload = dict(snapshot.get("contract") or {})
                semantic_runtime_payload = dict(snapshot.get("runtime") or {})
                semantic_has_material = _semantic_contract_is_ai_material(semantic_runtime_payload)
                if semantic_has_material:
                    break
            snapshot = semantic_contract_snapshot()
            semantic_contract_payload = dict(snapshot.get("contract") or {})
            semantic_runtime_payload = dict(snapshot.get("runtime") or {})
            semantic_has_material = _semantic_contract_is_ai_material(semantic_runtime_payload)
            if not semantic_has_material:
                adopt_trace_semantic_contract(source_label=f"{source}_after_semantic_wait")
            emit(
                "ai_spatial_semantic_wait_completed",
                {
                    "runtime_phase": runtime_phase,
                    "source": source,
                    "elapsed_ms": round((time.perf_counter() - wait_started) * 1000.0, 2),
                    "compiler_still_running": bool(semantic_contract_thread.is_alive()),
                    "semantic_contract_runtime": semantic_runtime_payload,
                    "semantic_contract": semantic_contract_payload,
                },
            )
        if not semantic_has_material:
            return False

        spatial_brief = dict(
            runtime_plan.get("metamemory_spatial_brief")
            or dict(runtime_plan.get("planner_runtime") or {}).get("metamemory_spatial_brief")
            or {}
        )
        if not spatial_brief:
            return False

        seed_max_probe_count = _planner_seed_max_items(
            query.query_text,
            query.max_probe_count,
            query.max_total_branches,
        )
        semantic_answer_strands = _answer_strands_from_semantic_contract(
            semantic_contract_payload,
            query_text=query.query_text,
            max_probe_count=seed_max_probe_count,
        )
        answer_strands = semantic_answer_strands or [
            dict(item)
            for item in list(runtime_plan.get("answer_strands") or [])
            if isinstance(item, dict)
        ]
        if semantic_answer_strands:
            answer_strands = _supplement_answer_strands_for_query(
                semantic_answer_strands,
                query_text=query.query_text,
                max_probe_count=seed_max_probe_count,
            )
            answer_strands = _select_answer_strands_for_query(
                answer_strands,
                query_text=query.query_text,
                max_probe_count=seed_max_probe_count,
            )
        if not answer_strands:
            return False

        runtime_plan["semantic_contract"] = semantic_contract_payload
        runtime_plan["semantic_contract_runtime"] = semantic_runtime_payload
        runtime_plan["answer_strands"] = [dict(item) for item in answer_strands]
        planner_seed_runtime = dict(runtime_plan.get("planner_seed_runtime") or {})
        planner_seed_runtime["answer_strands"] = [dict(item) for item in answer_strands]
        planner_seed_runtime["answer_strand_count"] = len(answer_strands)
        planner_seed_runtime["semantic_contract_seed_used"] = bool(semantic_answer_strands)
        planner_seed_runtime["semantic_contract_ai_seed_used"] = bool(semantic_answer_strands)
        planner_seed_runtime["semantic_contract_seed_strand_count"] = len(semantic_answer_strands)
        planner_seed_runtime["semantic_contract_seed_source"] = str(semantic_runtime_payload.get("source") or "") or None
        runtime_plan["planner_seed_runtime"] = planner_seed_runtime
        planner_runtime_payload = {
            **dict(runtime_plan.get("planner_runtime") or {}),
            "semantic_contract": semantic_contract_payload,
            "semantic_contract_runtime": semantic_runtime_payload,
            "semantic_contract_status": str(semantic_runtime_payload.get("status") or ""),
            "semantic_contract_source": str(semantic_runtime_payload.get("source") or ""),
            "semantic_contract_material": bool(semantic_runtime_payload.get("material")),
            "answer_strands": [dict(item) for item in answer_strands],
            "answer_strand_count": len(answer_strands),
            "semantic_contract_ai_seed_used": bool(semantic_answer_strands),
            "semantic_contract_seed_strand_count": len(semantic_answer_strands),
        }
        runtime_plan["planner_runtime"] = planner_runtime_payload

        spatial_contract = dict(runtime_plan.get("ai_spatial_landing_contract") or {})
        spatial_paths = [dict(item) for item in list(spatial_contract.get("inverse_answer_paths") or []) if isinstance(item, dict)]
        spatial_materialized = bool(
            spatial_contract.get("materialized")
            and spatial_contract.get("certifiable")
            and spatial_paths
        )
        if not spatial_materialized:
            trace_spatial_contract, trace_spatial_runtime = _latest_materialized_ai_spatial_surface_from_events(search_id)
            if _ai_spatial_contract_is_materialized(trace_spatial_contract):
                spatial_contract = dict(trace_spatial_contract)
                spatial_runtime = dict(trace_spatial_runtime or _ai_spatial_contract_runtime(spatial_contract))
                runtime_plan["ai_spatial_landing_contract"] = spatial_contract
                runtime_plan["ai_spatial_landing_contract_runtime"] = spatial_runtime
                planner_seed_runtime = dict(runtime_plan.get("planner_seed_runtime") or {})
                planner_seed_runtime["ai_spatial_landing_contract"] = dict(spatial_contract)
                planner_seed_runtime["ai_spatial_landing_contract_runtime"] = dict(spatial_runtime)
                planner_seed_runtime["ai_spatial_landing_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_landing_count") or 0)
                planner_seed_runtime["ai_spatial_path_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_path_count") or 0)
                runtime_plan["planner_seed_runtime"] = planner_seed_runtime
                planner_runtime_payload = dict(runtime_plan.get("planner_runtime") or {})
                planner_runtime_payload["ai_spatial_landing_contract"] = dict(spatial_contract)
                planner_runtime_payload["ai_spatial_landing_contract_runtime"] = dict(spatial_runtime)
                planner_runtime_payload["ai_landing_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_landing_count") or 0)
                planner_runtime_payload["ai_path_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_path_count") or 0)
                planner_runtime_payload["ai_spatial_reused_from_trace"] = source
                runtime_plan["planner_runtime"] = planner_runtime_payload
                spatial_paths = [dict(item) for item in list(spatial_contract.get("inverse_answer_paths") or []) if isinstance(item, dict)]
                spatial_materialized = True
                runtime_ai_spatial_attempted = True
                emit(
                    "ai_spatial_contract_reused_from_trace",
                    {
                        "runtime_phase": runtime_phase,
                        "source": source,
                        "ai_spatial_landing_contract": dict(spatial_contract),
                        "ai_spatial_landing_contract_runtime": dict(spatial_runtime),
                        "materialized": True,
                        "policy": "route_worker_reuses_first_package_spatial_ai_before_backend_traversal",
                    },
                )
        if not spatial_materialized:
            if runtime_ai_spatial_attempted:
                return False
            runtime_ai_spatial_attempted = True
            mode_budget = {
                "mode": retrieval_mode,
                "max_probe_count": int(query.max_probe_count),
                "max_total_branches": int(query.max_total_branches),
                "pre_route_wait_seconds": float(semantic_wait_seconds or 0.0),
                "bounded_route_single_shot": True,
                "source": source,
            }
            spatial_started = time.perf_counter()
            emit(
                "ai_spatial_materialization_started",
                {
                    "runtime_phase": runtime_phase,
                    "source": source,
                    "retrieval_mode": retrieval_mode,
                    "answer_strand_count": len(answer_strands),
                    "timeout_seconds": runtime_ai_spatial_contract_timeout_seconds(),
                    "policy": "ai_places_inverse_answer_paths_before_backend_traversal",
                },
            )
            spatial_contract = build_ai_spatial_landing_contract(
                query_text=query.query_text,
                retrieval_mode=retrieval_mode,
                semantic_contract=semantic_contract_payload,
                semantic_contract_runtime=semantic_runtime_payload,
                answer_strands=[dict(item) for item in answer_strands],
                identity_hints=semantic_contract_payload.get("identity_hints") or identity_context,
                metamemory_spatial_brief=spatial_brief,
                mode_budget=mode_budget,
                brain_revision=str(
                    semantic_runtime_payload.get("brain_revision")
                    or dict(semantic_runtime_payload.get("cache") or {}).get("brain_revision")
                    or semantic_brain_revision
                )
                or None,
                allow_ai=True,
                deferred=False,
                timeout=runtime_ai_spatial_contract_timeout_seconds(),
                cache_scope="retrieve_ai_spatial_contract",
            )
            spatial_runtime = {
                "schema_version": "agvm.ai_spatial_landing_contract_runtime.v1",
                "status": str(spatial_contract.get("status") or ""),
                "source": str(spatial_contract.get("source") or ""),
                "materialized": bool(spatial_contract.get("materialized")),
                "certifiable": bool(spatial_contract.get("certifiable")),
                "planner_latency_ms": spatial_contract.get("planner_latency_ms"),
                "missing_reasons": list(spatial_contract.get("missing_reasons") or []),
                "metrics": dict(spatial_contract.get("metrics") or {}),
                "cache": dict(spatial_contract.get("cache") or {}),
                "metamemory_spatial_revision": spatial_contract.get("metamemory_spatial_revision"),
                "brain_revision": spatial_contract.get("brain_revision"),
                "runtime_pre_route_elapsed_ms": round((time.perf_counter() - spatial_started) * 1000.0, 2),
            }
            runtime_plan["ai_spatial_landing_contract"] = spatial_contract
            runtime_plan["ai_spatial_landing_contract_runtime"] = spatial_runtime
            planner_seed_runtime = dict(runtime_plan.get("planner_seed_runtime") or {})
            planner_seed_runtime["ai_spatial_landing_contract"] = dict(spatial_contract)
            planner_seed_runtime["ai_spatial_landing_contract_runtime"] = dict(spatial_runtime)
            planner_seed_runtime["ai_spatial_landing_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_landing_count") or 0)
            planner_seed_runtime["ai_spatial_path_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_path_count") or 0)
            runtime_plan["planner_seed_runtime"] = planner_seed_runtime
            planner_runtime_payload = dict(runtime_plan.get("planner_runtime") or {})
            planner_runtime_payload["ai_spatial_landing_contract"] = dict(spatial_contract)
            planner_runtime_payload["ai_spatial_landing_contract_runtime"] = dict(spatial_runtime)
            planner_runtime_payload["ai_landing_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_landing_count") or 0)
            planner_runtime_payload["ai_path_count"] = int(dict(spatial_contract.get("metrics") or {}).get("ai_path_count") or 0)
            runtime_plan["planner_runtime"] = planner_runtime_payload
            emit(
                "ai_spatial_materialization_completed",
                {
                    "runtime_phase": runtime_phase,
                    "source": source,
                    "ai_spatial_landing_contract": dict(spatial_contract),
                    "ai_spatial_landing_contract_runtime": dict(spatial_runtime),
                    "materialized": bool(spatial_contract.get("materialized")),
                    "certifiable": bool(spatial_contract.get("certifiable")),
                },
            )

        runtime_plan = materialize_ai_spatial_contract_into_plan(
            runtime_plan,
            query,
            atlas_payload,
            identity_nucleus,
            search_id=search_id,
        )
        probes = [dict(item) for item in list(runtime_plan.get("probes") or []) if isinstance(item, dict)]
        branches = [dict(item) for item in list(runtime_plan.get("branches") or []) if isinstance(item, dict)]
        atlas_shortlists = dict(runtime_plan.get("atlas_shortlists") or {})
        planner_mode = str(runtime_plan.get("planner_mode") or planner_mode)
        planner_family_plans = {
            "heuristic": dict(runtime_plan.get("heuristic_family_plan") or planner_family_plans.get("heuristic") or {}),
            "ai": dict(runtime_plan.get("ai_family_plan") or planner_family_plans.get("ai") or {}),
        }
        final_surface_accumulator["planner_runtime"] = dict(runtime_plan.get("planner_runtime") or {})
        applied = bool(dict(runtime_plan.get("planner_runtime") or {}).get("ai_spatial_physical_materialization_applied"))
        emit(
            "ai_spatial_route_plan_ready",
            {
                "runtime_phase": runtime_phase,
                "source": source,
                "applied": applied,
                "planner_mode": planner_mode,
                "probe_count": len(probes),
                "branch_count": len(branches),
                "ai_spatial_probe_count": int(dict(runtime_plan.get("planner_runtime") or {}).get("ai_spatial_probe_count") or 0),
                "spatial_snap_count": int(dict(runtime_plan.get("planner_runtime") or {}).get("spatial_snap_count") or 0),
                **progressive_search_map_payload(branches, f"{source}_ai_spatial_route_plan_ready"),
            },
        )
        return applied

    def record_context_wave(
        *,
        source: str,
        runtime_phase_value: str,
        partial_matches: list[dict[str, Any]],
        branches_snapshot: list[dict[str, Any]],
        section_snapshots: list[dict[str, Any]],
        section_deltas: list[dict[str, Any]],
        context_dossier_partial: str | None,
        evidence_snippets: list[dict[str, Any]],
        evidence_reservoir_snapshot: dict[str, Any] | None,
        document_mode_value: str,
        after_first_answer: bool | None = None,
    ) -> dict[str, Any]:
        nonlocal context_wave_hot_node_ids, context_wave_reservoir_node_ids, context_wave_token_estimate
        wave = _build_context_wave(
            wave_index=len(context_waves) + 1,
            query_text=query.query_text,
            runtime_phase=runtime_phase_value,
            section_snapshots=section_snapshots,
            section_deltas=section_deltas,
            context_dossier_partial=context_dossier_partial,
            evidence_snippets=evidence_snippets,
            evidence_reservoir=evidence_reservoir_snapshot,
            partial_matches=partial_matches,
            branches=branches_snapshot,
            previous_hot_node_ids=context_wave_hot_node_ids,
            previous_reservoir_node_ids=context_wave_reservoir_node_ids,
            previous_token_estimate=context_wave_token_estimate,
            warm_state_used=warm_state_used,
            warm_state_summary=warm_state_summary,
            continuity_state=continuity_state,
            document_mode=document_mode_value,
            after_first_answer=bool(after_first_answer if after_first_answer is not None else (answer_first_ms is not None or partial_answer_revision > 0)),
            source=source,
        )
        context_wave_hot_node_ids = _section_node_ids(section_snapshots)
        context_wave_reservoir_node_ids = _reservoir_node_ids(
            evidence_reservoir=evidence_reservoir_snapshot,
            evidence_snippets=evidence_snippets,
            partial_matches=partial_matches,
        )
        context_wave_token_estimate = int(wave.get("token_estimate") or 0)
        context_waves.append(wave)
        emit("context_wave", wave)
        return wave

    def stop_for_supersede_request(
        round_index_value: int,
        *,
        source: str,
        branch_rows: list[dict[str, Any]] | None = None,
    ) -> bool:
        nonlocal background_enrichment_state, background_enrichment_stop_reason, stop_reason, runtime_phase
        supersede_request = _peek_search_supersede(search_id)
        if not supersede_request:
            return False
        supersede_reason = str(supersede_request.get("reason") or "superseded_by_followup").strip() or "superseded_by_followup"
        target_rows = branch_rows if branch_rows is not None else branches
        for branch in target_rows:
            if str(branch.get("status") or "") == "active":
                branch["status"] = "stopped"
                branch["stop_reason"] = supersede_reason
                branch["route_state"] = "stopped"
                branch["lifecycle_stage"] = "stopped"
                branch["local_stop_recommendation"] = "stop_branch"
            _bulk_mark_open_destinations(
                branch,
                state="suppressed_by_master",
                state_reason=supersede_reason,
                round_index=round_index_value,
            )
        stop_reason = supersede_reason
        if early_final_surface_emitted:
            background_enrichment_state = "completed"
            background_enrichment_stop_reason = supersede_reason
            runtime_phase = "background_enrichment_completed"
        else:
            runtime_phase = "finalizing"
        emit(
            "background_enrichment_stopped" if early_final_surface_emitted else "search_supersede_requested",
            {
                "runtime_phase": runtime_phase,
                "search_id": str(search_id or "") or None,
                "source": source,
                "supersede": dict(supersede_request),
                "stop_reason": supersede_reason,
                "background_enrichment_state": background_enrichment_state,
                "background_enrichment_stop_reason": background_enrichment_stop_reason,
                "early_final_sealed": bool(early_final_surface_sealed),
                "early_final_seal_reason": early_final_seal_reason,
                "early_final_seal_source": early_final_seal_source,
                "detached_result_snapshot": bool(detached_result_snapshot_emitted),
                "answer_surface_state": "final_sealed" if early_final_surface_sealed else ("answer_now_and_continue" if early_final_surface_emitted else "not_ready"),
                "closure_state": "final_sealed" if early_final_surface_sealed else ("open" if early_final_surface_emitted else "pending"),
                "final_closure_ready": bool(early_final_surface_sealed),
            },
        )
        return True

    def stop_for_client_visible_partial_budget(
        round_index_value: int,
        *,
        source: str,
        final_ready: bool = False,
        branch_rows: list[dict[str, Any]] | None = None,
    ) -> bool:
        nonlocal background_enrichment_state, background_enrichment_stop_reason, stop_reason, runtime_phase
        nonlocal client_visible_partial_terminalized, client_visible_partial_terminal_reason
        if client_visible_partial_terminalized:
            return True
        if final_ready or early_final_surface_sealed:
            return False
        if route_truth_required or client_visible_partial_budget_seconds <= 0.0:
            return False
        if first_context_ms is None and partial_answer_revision <= 0:
            return False
        first_visible_ms = float(first_context_ms if first_context_ms is not None else answer_first_ms or 0.0)
        if first_visible_ms <= 0.0:
            return False
        elapsed_after_first_visible = max(
            0.0,
            ((time.perf_counter() - started_at) * 1000.0 - first_visible_ms) / 1000.0,
        )
        if elapsed_after_first_visible < float(client_visible_partial_budget_seconds):
            return False
        client_visible_partial_terminalized = True
        client_visible_partial_terminal_reason = "partial_context_client_visible_low_yield_terminal"
        stop_reason = client_visible_partial_terminal_reason
        background_enrichment_state = "completed" if early_final_surface_emitted else "completed_partial"
        background_enrichment_stop_reason = client_visible_partial_terminal_reason
        runtime_phase = "partial_context_terminal"
        target_rows = branch_rows if branch_rows is not None else branches
        for branch in target_rows:
            if str(branch.get("status") or "") == "active":
                branch["status"] = "stopped"
                branch["stop_reason"] = client_visible_partial_terminal_reason
                branch["route_state"] = "stopped"
                branch["lifecycle_stage"] = "stopped"
                branch["local_stop_recommendation"] = "stop_branch"
            _bulk_mark_open_destinations(
                branch,
                state="suppressed_by_master",
                state_reason=client_visible_partial_terminal_reason,
                round_index=round_index_value,
            )
        emit(
            "partial_context_terminalized",
            {
                "runtime_phase": runtime_phase,
                "search_id": str(search_id or "") or None,
                "source": source,
                "stop_reason": client_visible_partial_terminal_reason,
                "client_visible_partial_budget_seconds": float(client_visible_partial_budget_seconds),
                "elapsed_after_first_visible_seconds": round(elapsed_after_first_visible, 3),
                "first_context_ms": first_context_ms,
                "first_answer_ms": answer_first_ms,
                "background_enrichment_state": background_enrichment_state,
                "background_enrichment_stop_reason": background_enrichment_stop_reason,
                "completion_state": "partial_complete_low_yield",
                "final_materialization_pending": False,
                "result_ready_terminal": True,
                "final_closure_ready": False,
            },
        )
        return True

    def build_detached_result_snapshot(
        *,
        source: str,
        partial_payload: dict[str, Any],
        partial_context: dict[str, Any] | None,
        partial_matches: list[dict[str, Any]],
        shared_evidence_snapshot: dict[str, Any],
        section_snapshots: list[dict[str, Any]],
        evidence_reservoir_snapshot: dict[str, Any] | None,
        document_mode_value: str,
        document_packets_value: list[dict[str, Any]],
        hot_context_summary_snapshot: dict[str, Any] | None,
        context_wave_payload: dict[str, Any] | None,
    ) -> dict[str, Any]:
        answer_payload = dict(partial_payload.get("answer") or {})
        answer_short_text = polish_final_answer_surface(query.query_text, partial_payload.get("answer_short")) or clean_answer_surface_text(partial_payload.get("answer_short"))
        answer_full_text = polish_final_answer_surface(query.query_text, partial_payload.get("answer_full") or partial_payload.get("answer_full_partial") or answer_short_text) or clean_answer_surface_text(partial_payload.get("answer_full") or partial_payload.get("answer_full_partial") or answer_short_text)
        answer_payload["answer_text"] = answer_short_text or answer_full_text or str(answer_payload.get("answer_text") or "")
        snapshot_surface_state = "final_sealed" if early_final_surface_sealed else "answer_now_and_continue"
        snapshot_closure_state = "final_sealed" if early_final_surface_sealed else "open"
        snapshot_master_state = {
            "status": "answer_surface_snapshot_ready",
            "stop_reason": early_final_seal_reason or "contract_passing_early_final_surface",
            "answer_surface_state": snapshot_surface_state,
            "closure_state": snapshot_closure_state,
            "final_closure_ready": bool(early_final_surface_sealed),
            "background_enrichment_active": True,
            "background_enrichment_state": "running",
            "background_enrichment_budget": dict(background_enrichment_budget),
            "early_final_seal_source": early_final_seal_source or source,
        }
        snapshot_timing = {
            "plan_ms": (runtime_plan.get("planner_runtime") or {}).get("plan_ms"),
            "run_start_ms": 0.0,
            "first_landing_ms": first_landing_ms,
            "first_context_ms": first_context_ms,
            "answer_first_ms": answer_first_ms,
            "answer_final_ms": answer_final_ms,
            "snapshot_ready_ms": round((time.perf_counter() - started_at) * 1000.0, 2),
            "total_ms": round((time.perf_counter() - started_at) * 1000.0, 2),
            "result_surface_ready_ms": round((time.perf_counter() - started_at) * 1000.0, 2),
            "branch_count": len(branches),
            "visited_bucket_count": len(visited_bucket_keys),
            "candidate_count_before_hydration": len(all_candidate_ids),
            "hydrated_count": len(partial_matches[: query.max_matches]),
            "final_match_count": len(partial_matches[: query.max_matches]),
        }
        snapshot_runtime = {
            **dict(runtime_plan.get("planner_runtime") or {}),
            "planner_mode": "hybrid" if llm_scout_state["enabled"] else planner_mode,
            "decomposition_mode": "hybrid" if llm_scout_state["added_probe_count"] else decomposition_mode,
            "query_class": query_class,
            "retrieval_mode": retrieval_mode,
            "result_snapshot_kind": "early_final_surface",
            "result_materialization_state": "snapshot_ready",
            "final_materialization_pending": True,
            "result_ready_terminal": False,
            "result_surface_ready_ms": snapshot_timing["result_surface_ready_ms"],
            "final_materialization_started_ms": None,
            "final_materialization_completed_ms": None,
            "final_materialization_stage_timings": [],
            "detached_result_snapshot": True,
            "detached_result_snapshot_ready": True,
            "detached_result_snapshot_source": source,
            "early_final_surface_enabled": bool(first_answer_sla_split),
            "early_final_sealed": bool(early_final_surface_sealed),
            "early_final_seal_reason": early_final_seal_reason,
            "early_final_seal_source": early_final_seal_source or source,
            "background_enrichment_after_early_final": True,
            "background_enrichment_state": "running",
            "background_enrichment_budget": dict(background_enrichment_budget),
            "background_enrichment_budget_exhausted": False,
            "background_enrichment_stop_reason": None,
            "post_final_worker_throttle_enabled": bool(post_final_worker_throttle_enabled),
            "post_final_worker_throttle_policy": dict(post_final_worker_throttle_policy),
            "post_final_branch_pruned_count": int(post_final_branch_pruned_count),
            "post_final_ai_worker_suppressed_count": int(post_final_ai_worker_suppressed_count),
            "first_answer_ready": bool(answer_first_ms is not None or partial_answer_revision > 0),
            "final_answer_ready": bool(early_final_surface_sealed),
            "final_answer_sealed": bool(early_final_surface_sealed),
            "final_surface_sla_seconds": final_surface_sla_seconds,
            "llm_scout_status": llm_scout_state.get("status"),
            "branch_count": len(branches),
            "landing_metadata_count": len(build_landing_metadata(probes, branches)),
            "context_wave_count": len(context_waves),
        }
        snapshot = {
            "search_id": str(search_id or "") or None,
            "query_text": query.query_text,
            "thread_id": normalized_thread_id,
            "response_mode": query.response_mode,
            "retrieval_mode": retrieval_mode,
            "decomposition_mode": "hybrid" if llm_scout_state["added_probe_count"] else decomposition_mode,
            "planner_mode": "hybrid" if llm_scout_state["enabled"] else planner_mode,
            "document_mode": document_mode_value,
            "document_lookup_kind": document_lookup_kind,
            **semantic_contract_fields(),
            "document_lookup": document_lookup_contract,
            "supporting_documents": list(document_lookup_contract.get("supporting_documents") or []),
            "source_trace": list(document_lookup_contract.get("source_trace") or []),
            "document_packets": document_packets_value,
            "evidence_reservoir": evidence_reservoir_snapshot,
            "answer_strands": [dict(item) for item in list(runtime_plan.get("answer_strands") or []) if isinstance(item, dict)],
            "planner_seed_runtime": dict(runtime_plan.get("planner_seed_runtime") or {}),
            "seed_goal_coverage": dict(runtime_plan.get("seed_goal_coverage") or {}),
            "seed_destination_presence": dict(runtime_plan.get("seed_destination_presence") or {}),
            "probes": probes,
            "branches": branches,
            "landing_metadata": build_landing_metadata(probes, branches),
            "shared_evidence": {
                **dict(shared_evidence_snapshot or {}),
                "master_state": snapshot_master_state,
                "answer_surface_state": snapshot_surface_state,
                "closure_state": snapshot_closure_state,
                "final_closure_ready": bool(early_final_surface_sealed),
            },
            "steps": all_steps,
            "matches": partial_matches[: query.max_matches],
            "visited_node_ids": sorted(visited_node_ids),
            "visited_bucket_keys": sorted(visited_bucket_keys),
            "stop_reason": early_final_seal_reason or "contract_passing_early_final_surface",
            "answer": answer_payload if query.response_mode in {"answer", "both"} else None,
            "context": partial_context if query.response_mode in {"context", "both"} else None,
            "answer_short": answer_short_text or answer_full_text,
            "answer_full": answer_full_text or answer_short_text,
            "answer_surface_update": partial_payload.get("answer_surface_update") or {},
            "final_answer_update_policy": str(partial_payload.get("final_answer_update_policy") or "kept_first_answer"),
            "early_final_surface": early_final_surface_payload,
            "early_final_sealed": bool(early_final_surface_sealed),
            "early_final_seal_reason": early_final_seal_reason,
            "early_final_seal_source": early_final_seal_source or source,
            "background_enrichment_after_early_final": True,
            "background_enrichment_state": "running",
            "background_enrichment_budget": dict(background_enrichment_budget),
            "background_enrichment_stop_reason": None,
            "background_enrichment_budget_exhausted": False,
            "detached_result_snapshot": True,
            "result_snapshot_kind": "early_final_surface",
            "result_materialization_state": "snapshot_ready",
            "final_materialization_pending": True,
            "result_ready_terminal": False,
            "result_surface_ready_ms": snapshot_timing["result_surface_ready_ms"],
            "final_materialization_stage_timings": [],
            "context_structured": {"sections": section_snapshots},
            "context_dossier": None,
            "hot_context_summary": dict(hot_context_summary_snapshot or {}),
            "context_dossier_partial": partial_payload.get("context_dossier_partial"),
            "evidence_snippets": list(partial_payload.get("evidence_snippets") or []),
            "context_waves": context_waves[-12:],
            "master_state": snapshot_master_state,
            "answer_surface_state": snapshot_surface_state,
            "closure_state": snapshot_closure_state,
            "final_closure_ready": bool(early_final_surface_sealed),
            "final_closure_blockers": []
            if early_final_surface_sealed
            else [
                {
                    "branch_id": "ai_validation",
                    "reason": "ai_validation_required_before_final_seal",
                    "destination_key": "ai_validation",
                }
            ],
            "unresolved_destination_count": 0,
            "answer_now_before_exploration_complete": True,
            "final_closure_after_destination_resolution": False,
            "context_level_1_before_final": bool(context_level_1_before_final),
            "planner_runtime": snapshot_runtime,
            "timing": snapshot_timing,
            "follow_up_candidates": [],
            "answerability_state": "grounded" if str(answer_payload.get("answerability_state") or "") != "insufficient" else "insufficient",
            "warm_state_saved": bool(normalized_thread_id and latest_warm_packet),
            "continuity_summary": {
                "thread_id": normalized_thread_id,
                "continuity_state": continuity_state,
                "warm_state_used": warm_state_used,
                "warm_state_summary": warm_state_summary,
            },
            "warm_followup_economy": {},
            "context_quality_metrics": dict((evidence_reservoir_snapshot or {}).get("quality_metrics") or {}),
            "ai_material_contribution": False,
            "ai_contribution_reason": None,
            "ai_materiality": {},
            "route_truth_summary": {},
            "context_wave": dict(context_wave_payload or {}),
        }
        return normalize_retrieve_response_payload(snapshot)

    def maybe_emit_early_final_surface(
        *,
        source: str,
        partial_payload: dict[str, Any],
        partial_context: dict[str, Any] | None,
        partial_matches: list[dict[str, Any]],
        shared_evidence_snapshot: dict[str, Any],
        section_snapshots: list[dict[str, Any]],
        evidence_reservoir_snapshot: dict[str, Any] | None,
        document_mode_value: str,
        document_packets_value: list[dict[str, Any]],
        hot_context_summary_snapshot: dict[str, Any] | None,
        context_wave_payload: dict[str, Any] | None,
        usable: bool,
    ) -> bool:
        nonlocal early_final_surface_emitted, early_final_surface_sealed, early_final_surface_payload, early_final_seal_reason
        nonlocal early_final_seal_source, early_final_answer_full, answer_now_before_exploration_complete
        nonlocal early_final_emitted_at_ms, detached_result_snapshot_payload, detached_result_snapshot_emitted
        nonlocal background_enrichment_state, background_enrichment_stop_reason, background_enrichment_budget_exhausted
        if early_final_surface_emitted or query.response_mode not in {"answer", "both"}:
            return False
        candidate_answer_full = _early_final_candidate_answer_full(
            query_text=query.query_text,
            retrieval_mode=retrieval_mode,
            partial_payload=partial_payload,
            section_snapshots=section_snapshots,
        )
        decision = _early_final_surface_decision(
            query_text=query.query_text,
            retrieval_mode=retrieval_mode,
            partial_payload=partial_payload,
            shared_evidence_snapshot=shared_evidence_snapshot,
            section_snapshots=section_snapshots,
            evidence_reservoir=evidence_reservoir_snapshot,
            document_mode=document_mode_value,
            document_packets=document_packets_value,
            usable=usable,
            candidate_answer_full=candidate_answer_full,
        )
        if not bool(decision.get("ready")):
            return False
        answer_payload = dict(partial_payload.get("answer") or {})
        answer_short_text = polish_final_answer_surface(query.query_text, partial_payload.get("answer_short")) or clean_answer_surface_text(partial_payload.get("answer_short"))
        final_answer_text = str(candidate_answer_full or answer_short_text or answer_payload.get("answer_text") or "").strip()
        final_answer_text = polish_final_answer_surface(query.query_text, final_answer_text) or clean_answer_surface_text(final_answer_text)
        if not final_answer_text:
            return False
        answer_payload["answer_text"] = answer_short_text or final_answer_text
        answer_payload["answerability_state"] = "grounded" if str(answer_payload.get("answerability_state") or "") != "insufficient" else "insufficient"
        answer_payload["insufficient"] = False
        answer_payload.setdefault("mode", "early_final_surface")
        answer_payload["early_final_surface"] = True
        answer_payload["early_final_seal_source"] = str(source)
        answer_payload["early_final_decision"] = dict(decision)
        surface_update = _answer_surface_update_summary(
            query_text=query.query_text,
            answer_short=answer_short_text,
            candidate_answer_full=final_answer_text,
            final_answer_full=final_answer_text,
            preserved_short_final=bool(answer_short_text and final_answer_text == answer_short_text),
        )
        semantic_snapshot_for_early_surface = semantic_contract_snapshot()
        early_final_surface_sealed = not bool(llm_enabled()) and not bool(
            (semantic_snapshot_for_early_surface.get("runtime") or {}).get("ai_required")
            or (semantic_snapshot_for_early_surface.get("contract") or {}).get("ai_required")
        )
        surface_state = "final_sealed" if early_final_surface_sealed else "answer_now_and_continue"
        closure_state = "final_sealed" if early_final_surface_sealed else "open"
        final_closure_ready_value = bool(early_final_surface_sealed)
        early_final_surface_emitted = True
        early_final_seal_reason = str(decision.get("reason") or "contract_passing_early_final_surface")
        early_final_seal_source = str(source)
        early_final_answer_full = final_answer_text
        early_final_emitted_at_ms = round((time.perf_counter() - started_at) * 1000.0, 2)
        background_enrichment_state = "running"
        background_enrichment_stop_reason = None
        background_enrichment_budget_exhausted = False
        answer_now_before_exploration_complete = True
        early_master_state = {
            "status": "answer_surface_sealed" if early_final_surface_sealed else "answer_surface_provisional",
            "stop_reason": early_final_seal_reason,
            "answer_surface_state": surface_state,
            "closure_state": closure_state,
            "final_closure_ready": final_closure_ready_value,
            "background_enrichment_active": True,
            "background_enrichment_state": background_enrichment_state,
            "background_enrichment_budget": dict(background_enrichment_budget),
            "early_final_seal_source": early_final_seal_source,
        }
        early_final_surface_payload = {
            "answer": answer_payload,
            "context": partial_context,
            "answer_short": answer_short_text or final_answer_text,
            "answer_full": final_answer_text,
            "answer_surface_update": surface_update,
            "final_answer_update_policy": str(surface_update.get("policy") or ""),
            "context_dossier": None,
            "context_dossier_partial": partial_payload.get("context_dossier_partial"),
            "hot_context_summary": dict(hot_context_summary_snapshot or {}),
            "evidence_snippets": list(partial_payload.get("evidence_snippets") or []),
            "context_wave": dict(context_wave_payload or {}),
            "context_waves": context_waves[-12:],
            "master_state": early_master_state,
            "section_snapshots": section_snapshots,
            "coverage_by_slot": dict(shared_evidence_snapshot.get("coverage_by_slot") or {}),
            "unresolved_slots": list(shared_evidence_snapshot.get("unresolved_slots") or []),
            "shared_evidence": {
                **dict(shared_evidence_snapshot or {}),
                "master_state": early_master_state,
                "answer_surface_state": surface_state,
                "closure_state": closure_state,
                "final_closure_ready": final_closure_ready_value,
            },
            "stop_reason": early_final_seal_reason,
            "thread_id": normalized_thread_id,
            "runtime_phase": "background_enrichment",
            "warm_state_saved": bool(normalized_thread_id and latest_warm_packet),
            "continuity_summary": {
                "thread_id": normalized_thread_id,
                "continuity_state": continuity_state,
                "warm_state_used": warm_state_used,
                "warm_state_summary": warm_state_summary,
            },
            "document_mode": document_mode_value,
            "document_packets": document_packets_value,
            "evidence_reservoir": evidence_reservoir_snapshot,
            "evidence_reservoir_summary": dict((evidence_reservoir_snapshot or {}).get("reservoir_summary") or {}),
            "context_quality_metrics": dict((evidence_reservoir_snapshot or {}).get("quality_metrics") or {}),
            "first_answer_ready": bool(answer_first_ms is not None or partial_answer_revision > 0),
            "final_answer_ready": bool(early_final_surface_sealed),
            "final_answer_sealed": bool(early_final_surface_sealed),
            "early_final_sealed": bool(early_final_surface_sealed),
            "early_final_seal_reason": early_final_seal_reason,
            "early_final_seal_source": early_final_seal_source,
            "background_enrichment_active": True,
            "background_enrichment_state": background_enrichment_state,
            "background_enrichment_budget": dict(background_enrichment_budget),
            "answer_surface_state": surface_state,
            "closure_state": closure_state,
            "final_closure_ready": final_closure_ready_value,
            "final_closure_blockers": [],
            "unresolved_destination_count": int(decision.get("unresolved_destination_count") or 0),
        }
        emit("answer_final" if early_final_surface_sealed else "answer_partial", early_final_surface_payload)
        detached_result_snapshot_payload = build_detached_result_snapshot(
            source=source,
            partial_payload=early_final_surface_payload,
            partial_context=partial_context,
            partial_matches=partial_matches,
            shared_evidence_snapshot=shared_evidence_snapshot,
            section_snapshots=section_snapshots,
            evidence_reservoir_snapshot=evidence_reservoir_snapshot,
            document_mode_value=document_mode_value,
            document_packets_value=document_packets_value,
            hot_context_summary_snapshot=hot_context_summary_snapshot,
            context_wave_payload=context_wave_payload,
        )
        detached_result_snapshot_emitted = True
        emit(
            "result_snapshot_ready",
            {
                "result": detached_result_snapshot_payload,
                "result_snapshot": detached_result_snapshot_payload,
                "detached_result_snapshot": True,
                "result_snapshot_kind": "early_final_surface",
                "runtime_phase": "background_enrichment",
                "background_enrichment_state": background_enrichment_state,
                "background_enrichment_budget": dict(background_enrichment_budget),
                "early_final_sealed": bool(early_final_surface_sealed),
                "early_final_seal_reason": early_final_seal_reason,
                "early_final_seal_source": early_final_seal_source,
            },
        )
        emit(
            "result_ready",
            {
                "result": detached_result_snapshot_payload,
                "result_materialization_state": "snapshot_ready",
                "final_materialization_pending": True,
                "result_ready_terminal": False,
                "detached_result_snapshot": True,
                "result_snapshot_kind": "early_final_surface",
                "runtime_phase": "background_enrichment",
                "background_enrichment_state": background_enrichment_state,
                "background_enrichment_budget": dict(background_enrichment_budget),
                "early_final_sealed": bool(early_final_surface_sealed),
                "early_final_seal_reason": early_final_seal_reason,
                "early_final_seal_source": early_final_seal_source,
            },
        )
        emit(
            "background_enrichment_started",
            {
                "runtime_phase": "background_enrichment",
                "background_enrichment_state": background_enrichment_state,
                "background_enrichment_budget": dict(background_enrichment_budget),
                "background_enrichment_yield_policy": dict(background_enrichment_yield_policy),
                "detached_result_snapshot": True,
                "early_final_sealed": bool(early_final_surface_sealed),
                "early_final_seal_reason": early_final_seal_reason,
                "early_final_seal_source": early_final_seal_source,
            },
        )
        emit(
            "metrics_update",
            {
                "runtime_phase": "background_enrichment",
                "early_final_sealed": bool(early_final_surface_sealed),
                "early_final_seal_reason": early_final_seal_reason,
                "early_final_seal_source": early_final_seal_source,
                "background_enrichment_active": True,
                "background_enrichment_state": background_enrichment_state,
                "background_enrichment_budget": dict(background_enrichment_budget),
                "detached_result_snapshot": True,
                "answer_surface_state": surface_state,
                "closure_state": closure_state,
                "final_closure_ready": final_closure_ready_value,
            },
        )
        return True

    def activate_document_lookup_no_match_fast_path(
        *,
        document_mode_value: str,
        document_packets_value: list[dict[str, Any]],
        shared_evidence_snapshot: dict[str, Any] | None,
        source: str,
        round_index_value: int = 0,
        branches_to_stop: list[dict[str, Any]] | None = None,
    ) -> bool:
        nonlocal document_lookup_fast_no_match, document_lookup_route_budget_override, document_lookup_route_fast_path_reason, final_scout_wait_seconds, stop_reason
        if not _document_lookup_no_match_closure_ready(
            query_text=query.query_text,
            document_mode=document_mode_value,
            document_packets=document_packets_value,
            shared_evidence=shared_evidence_snapshot,
        ):
            return False
        document_lookup_fast_no_match = True
        document_lookup_route_budget_override = 0
        document_lookup_route_fast_path_reason = f"document_lookup_no_matching_packet::{source}"
        final_scout_wait_seconds = min(final_scout_wait_seconds, 0.35)
        stop_reason = "document_lookup_no_matching_packet"
        target_branches = branches_to_stop if branches_to_stop is not None else branches
        for branch in target_branches:
            if str(branch.get("status") or "") != "active":
                continue
            branch["status"] = "stopped"
            branch["stop_reason"] = "document_lookup_no_matching_packet"
            branch["route_state"] = "route_exhausted"
            branch["lifecycle_stage"] = "stopped"
            branch["local_stop_recommendation"] = "stop_branch"
            _bulk_mark_open_destinations(
                branch,
                state="route_exhausted",
                state_reason="document_lookup_no_matching_packet",
                round_index=round_index_value,
            )
        return True

